  syntax: '<number>';
  inherits: true;
  initial-value: 0;
}

@property --ds-progress-head-1 {
  syntax: '<percentage>';
  inherits: true;
  initial-value: 0%;
}

@property --ds-progress-head-2 {
  syntax: '<percentage>';
  inherits: true;
  initial-value: 0%;
}

@property --ds-progress-tail-1 {
  syntax: '<percentage>';
  inherits: true;
  initial-value: 0%;
}

@property --ds-progress-tail-2 {
  syntax: '<percentage>';
  inherits: true;
  initial-value: 0%;
}

@property --ds-spinner-arc {
  syntax: '<angle>';
  inherits: false;
  initial-value: 10deg;
}

@property --ds-spinner-start {
  syntax: '<angle>';
  inherits: false;
  initial-value: 0deg;
}

@property --ds-skeleton-x {
  syntax: '<length>';
  inherits: true;
  initial-value: 0px;
}

/*
 * The share of a chart mark (a meter, a column; 0 ... 1), set by the page
