    --ds-distance-md: 8px;
    --ds-distance-lg: 12px;
    --ds-distance-xl: 24px;
    --ds-distance-sheet: 100%;
    --ds-scale-enter: .98;
    --ds-scale-popup: .95;
    --ds-scale-tooltip: .9;
    --ds-scale-small: .6;
