@layer ds.motion {
  /* ── Keyframes: enter ──────────────────────────── */

  @keyframes ds-fade-in {
    from { opacity: 0; }
  }

  /*
   * Movement only. Opacity must take the standard curve while the movement
   * floats on the spring (an overshooting fade flashes), and one keyframe
   * runs on one curve, so entrances pair ds-fade-in with one of these:
   *
   *   animation: ds-fade-in var(--ds-dur-medium) var(--ds-ease-in-out) backwards,
   *              ds-lift-in var(--ds-dur-medium) var(--ds-ease-spatial) backwards;
   *
   * ds-lift-in rises (snackbars, a swapped view), ds-grow-in rises from just
   * below full size (dialogs; --ds-motion-scale sets the start scale),
   * ds-shift-in comes from the side (side sheets), ds-pop-in grows small
   * markers (badges). The .ds-enter utilities below always use these pairs.
   */
  @keyframes ds-lift-in {
    from { translate: 0 var(--ds-motion-distance, var(--ds-distance-md)); }
  }

  @keyframes ds-grow-in {
    from {
      translate: 0 var(--ds-motion-distance, var(--ds-distance-md));
      scale: var(--ds-motion-scale, var(--ds-scale-enter));
    }
  }

  @keyframes ds-shift-in {
    from { translate: var(--ds-motion-distance, var(--ds-distance-xl)) 0; }
  }

  /* A rolling line (a status text that changes): the new line comes up from
     below into its slot (--ds-motion-distance: 100%, one line height). */
  @keyframes ds-roll-in {
    from { translate: 0 var(--ds-motion-distance, 100%); }
  }

  /* Small markers that appear (badges, counters): the smallest start scale
     (--ds-scale-small). */
  @keyframes ds-pop-in {
    from { scale: var(--ds-motion-scale, var(--ds-scale-small)); }
  }

  /* A stroke that draws itself (a check after success). The glyph carries
     pathLength="1" and the element sets stroke-dasharray: 1, so the stroke
     starts fully offset (--ds-draw-length, default 1) and draws in. */
  @keyframes ds-draw {
    from { stroke-dashoffset: var(--ds-draw-length, 1); }
  }

  /* A chart mark that fills from zero to its share on its first render
     (.ds-meter, .ds-columns__col): the registered --ds-share runs from 0
     to the mark's own value, so its fill, clipped at the share, keeps its
     round end the whole way. A value that changes later transitions, it
     never replays this. */
  @keyframes ds-fill-share {
    from { --ds-share: 0; }
  }

  /* Deprecated in 2.0 (removed in 3.0 at the earliest): a scaled bar
     squashes its round end; use --ds-share with ds-fill-share. A bar that
     fills from its start: the element sets its own transform (the scaleX
     or scaleY of its share) and transform-origin; the scale property
     multiplies it, so the bar grows from zero to its share. A value that
     changes later jumps or transitions, it never replays this. */
  @keyframes ds-fill-x {
    from { scale: 0 1; }
  }

  @keyframes ds-fill-y {
    from { scale: 1 0; }
  }

  /* ── Keyframes: leave ──────────────────────────── */
  /* Movement only, each paired with ds-fade-out (the fade accelerates on
     its own curve):

       animation: ds-fade-out var(--ds-dur-fast) var(--ds-ease-in) forwards,
                  ds-drop-out var(--ds-dur-fast) var(--ds-ease-in) forwards;
  */

  @keyframes ds-fade-out {
    to { opacity: 0; }
  }

  /* Down (the reverse of ds-lift-in). */
  @keyframes ds-drop-out {
    to { translate: 0 var(--ds-motion-distance, var(--ds-distance-md)); }
  }

  /* Smaller and a little down (the reverse of ds-grow-in). */
  @keyframes ds-shrink-out {
    to {
      translate: 0 var(--ds-motion-distance, var(--ds-distance-sm));
      scale: var(--ds-motion-scale, var(--ds-scale-enter));
    }
  }

  /* Sideways (a side sheet, a drawer). */
  @keyframes ds-shift-out {
    to { translate: var(--ds-motion-distance, var(--ds-distance-lg)) 0; }
  }

  /* A small marker disappears (the reverse of ds-pop-in). */
  @keyframes ds-pop-out {
    to { scale: var(--ds-motion-scale, var(--ds-scale-small)); }
  }

  /* The rolling line leaves upwards (--ds-motion-distance: -100%). */
  @keyframes ds-roll-out {
    to { translate: 0 var(--ds-motion-distance, -100%); }
  }

  /* ── Keyframes: popup reveal ───────────────────── */
  /* A popup (menu, combobox list) uncovers itself from the edge of its
     trigger: --ds-clip-from is the hidden state (DS.motion.originFrom()
     writes it, default: closed towards the top edge). clip-path does not
     interpolate to `none`, so both keyframes name both ends; the open end
     reaches --ds-space-6 beyond the box, the resting clip of .ds-menu and
     .ds-combo__popup, so the popup's shadow stays visible while the
     animation runs and nothing snaps when it ends. */
  @keyframes ds-clip-in {
    from { clip-path: var(--ds-clip-from, inset(0 0 100% 0)); }
    to { clip-path: inset(calc(-1 * var(--ds-space-6))); }
  }

  @keyframes ds-clip-out {
    from { clip-path: inset(calc(-1 * var(--ds-space-6))); }
    to { clip-path: var(--ds-clip-from, inset(0 0 100% 0)); }
  }

  /* ── Keyframes: feedback ───────────────────────── */

  /* The pointer ripple of an action (DS.ripple): a circle grows from the
     pointer. Its fade is a separate track (ds-fade-out). */
  @keyframes ds-press-ripple {
    from { scale: 0; }
