@layer ds.utilities {
  /* `hidden` wins inside the theme also without .ds-base (an embedded
     widget): the UA [hidden] rule loses to every component's display, so
     DS.motion.leave(el, v, { then: 'hide' }) on an alert, a button or a chip
     would snap back visible. Zero specificity, first in the last layer: it
     beats every component and loses to project CSS and to the utilities
     below that set display (.ds-swap, .ds-icon-swap). .ds-presence keeps
     its allow-discrete exit, and hidden="until-found" stays searchable. */
  :where(.ds-theme) :where([hidden]:not(.ds-presence, [hidden="until-found"])) {
    display: none;
  }

  /* ── Utilities ─────────────────────────────────── */

  /* Order matters inside this layer, not specificity: the layer beats every
     component's own animation, and within it the later rule wins. The
     first-render utilities come first, .ds-enter after them and .ds-leave
     last, so an exit always wins over an entrance. */

  /* First render of a page only: its children (cards, tiles) fade in and
     rise the smallest distance one after the other, at most six steps
     (stagger() numbers them). Refreshes never animate: drop the class once
     the entrance played. */
  .ds-stagger > * {
    --ds-motion-distance: var(--ds-distance-sm);
    animation:
      ds-fade-in var(--ds-dur-medium) var(--ds-ease-in-out) backwards,
      ds-lift-in var(--ds-dur-medium) var(--ds-ease-spatial) backwards;
    animation-delay: calc(var(--ds-i, 0) * var(--ds-stagger));
  }

  /* Where sibling-index() exists, CSS-only pages stagger too: each child
     numbers itself, capped at the sixth step. An inline --ds-i from
     stagger() still wins. */
  @supports (z-index: sibling-index()) {
    .ds-stagger > * {
      --ds-i: min(sibling-index() - 1, 5);
    }
  }

  /* Freshly loaded content replaces its placeholder: fade-through with the
     smallest rise (opacity on the standard curve, the rise on the spring). */
  .ds-reveal {
    --ds-motion-distance: var(--ds-distance-sm);
    animation:
      ds-fade-in var(--ds-dur-medium) var(--ds-ease-in-out) backwards,
      ds-lift-in var(--ds-dur-medium) var(--ds-ease-spatial) backwards;
  }

  /* Loaders keep their own animation: a skeleton, .ds-loading, .ds-boot
     or a shape loader waits its loader delay (fast loads never flash it)
     and a spinner keeps turning, also as a direct child of .ds-stagger
     (skeleton placeholders in a staggered grid) or with .ds-reveal.
     revert-layer hands them back to ds.components. The selectors weigh one
     class, so they beat the two rules above by order and .ds-enter and
     .ds-leave below still win. */
  .ds-stagger > :where(.ds-skeleton, .ds-loading, .ds-boot, .ds-spinner, .ds-loader),
  .ds-reveal:where(.ds-skeleton, .ds-loading, .ds-boot, .ds-spinner, .ds-loader) {
    animation: revert-layer;
  }

  /*
   * Reveal on scroll (opt-in, long read-only pages: reports, overviews):
   * a block fades in and rises --ds-distance-md while it enters the
   * scrollport, tied to the scroll position (view()), so it never plays on
   * its own and scrolling back reverses it. It is opaque once
   * 4 x --ds-space-6 (96px) of it are in view; a block already passed
   * shows its end state. Never on tables, rows, forms or anything typed
   * into or searched, and not together with .ds-enter or .ds-reveal on the
   * same element. Without view() timelines it does nothing: static, never
   * hidden. The shorthand comes first (it resets animation-timeline).
   */
  @supports (animation-timeline: view()) {
    .ds-reveal--scroll {
      --ds-motion-distance: var(--ds-distance-md);
      animation:
        ds-fade-in linear both,
        ds-lift-in var(--ds-ease-out) both;
      animation-timeline: view();
      animation-range: entry 0% entry calc(4 * var(--ds-space-6));
    }

    /* DS.motion.enter() or leave() on such a block plays in time: the
       one-shot utilities set longhands only, which keep the view()
       timeline, so it goes back to the document's here. */
    .ds-reveal--scroll:is(.ds-enter, .ds-leave) {
      animation-timeline: auto;
      animation-range: normal;
    }
  }

  /* Paper has no scroll position: every block prints at its end state. */
  @media print {
    .ds-reveal--scroll {
      animation: none;
    }
  }

  /*
   * One-shot entrance. Variants pick the keyframes; `--ds-i` (set by
   * stagger() in js/motion.js) delays each item of a list by one
   * --ds-stagger step. Every variant fades on the standard curve: movement
   * runs as a second animation (the lists pair up; duration, delay and fill
   * repeat) and floats on the spring, so the fade never overshoots.
   *
   * It plays once and ends, also on an element with its own loop (the
   * entrance replaces that loop while it runs). Never put .ds-enter on a
   * looping element in static markup: wrap it (spinner.css).
   *
   *   <li class="ds-enter ds-enter--scale">   via JS: DS.motion.enter(el, 'scale')
   */
  .ds-enter {
    animation-name: var(--ds-enter-keyframes, ds-fade-in, ds-lift-in);
    animation-duration: var(--ds-enter-duration, var(--ds-dur-medium));
    animation-timing-function: var(--ds-enter-easing, var(--ds-ease-in-out), var(--ds-ease-spatial));
    animation-delay: calc(var(--ds-i, 0) * var(--ds-stagger) + var(--ds-enter-delay, 0ms));
    animation-iteration-count: 1;
    animation-direction: normal;
    animation-play-state: running;
    /* backwards: hold the start state during the delay, then hand back to the
       element's own styles. */
    animation-fill-mode: backwards;
  }

  .ds-enter--fade { --ds-enter-keyframes: ds-fade-in; --ds-enter-easing: var(--ds-ease-in-out); }
  .ds-enter--scale { --ds-enter-keyframes: ds-fade-in, ds-grow-in; }
  .ds-enter--slide { --ds-enter-keyframes: ds-fade-in, ds-shift-in; --ds-enter-duration: var(--ds-dur-slow); --ds-enter-easing: var(--ds-ease-in-out), var(--ds-ease-spatial); }

  /* Content that replaces a placeholder or another view: fade-through, the
     default pair with the smallest rise. The distance applies to this
     element only (the hooks do not inherit): children that enter inside it
     keep their own distance. */
  .ds-enter--swap { --ds-motion-distance: var(--ds-distance-sm); }

  /* Waits before it shows: fast loads never flash a loading indicator. */
  .ds-enter--delayed { --ds-enter-keyframes: ds-fade-in; --ds-enter-easing: var(--ds-ease-in-out); --ds-enter-delay: var(--ds-delay-loader); }

  /* A small marker appears (a badge, a counter that gets its first value):
     it springs in from --ds-scale-small (the scale settles just past full
     size, about 1%). */
  .ds-enter--pop { --ds-enter-keyframes: ds-fade-in, ds-pop-in; }

  /* A chart mark grows to its share once (first render of a chart): a
     value travelling, so it glides on the value curve like progress (data
     never overshoots). The mark sets --ds-share; the animation runs it
     from 0. */
  .ds-enter--fill { --ds-enter-keyframes: ds-fade-in, ds-fill-share; --ds-enter-duration: var(--ds-dur-glide); --ds-enter-easing: var(--ds-ease-in-out), var(--ds-ease-value); }

  /* Deprecated in 2.0 (removed in 3.0 at the earliest; use .ds-enter--fill
     with --ds-share): a bar or column that scales to its share. */
  .ds-enter--fill-x { --ds-enter-keyframes: ds-fade-in, ds-fill-x; --ds-enter-duration: var(--ds-dur-glide); --ds-enter-easing: var(--ds-ease-in-out), var(--ds-ease-value); }
  .ds-enter--fill-y { --ds-enter-keyframes: ds-fade-in, ds-fill-y; --ds-enter-duration: var(--ds-dur-glide); --ds-enter-easing: var(--ds-ease-in-out), var(--ds-ease-value); }

  /* One-shot exit; leave() in js/motion.js removes or hides the element
     afterwards. It starts at once and plays once, whatever delay (a loader
     that waited to fade in) or loop the element's own animation had. Small
     exits accelerate (--ds-ease-in, the fade included) in --ds-dur-fast,
     0.6 of the default entrance. The variants pair ds-fade-out with a
     movement-only exit. */
  .ds-leave {
    animation-name: var(--ds-leave-keyframes, ds-fade-out);
    animation-duration: var(--ds-leave-duration, var(--ds-dur-fast));
    animation-timing-function: var(--ds-leave-easing, var(--ds-ease-in));
    animation-delay: 0ms;
    animation-iteration-count: 1;
    animation-fill-mode: forwards;
    pointer-events: none;
  }

  .ds-leave--sink { --ds-leave-keyframes: ds-fade-out, ds-drop-out; }
  .ds-leave--scale { --ds-leave-keyframes: ds-fade-out, ds-shrink-out; --ds-leave-duration: var(--ds-dur-base); }
  .ds-leave--slide { --ds-leave-keyframes: ds-fade-out, ds-shift-out; --ds-leave-duration: var(--ds-dur-base); }
  .ds-leave--pop { --ds-leave-keyframes: ds-fade-out, ds-pop-out; }

  /* Loaders whose loop draws them keep it while they leave (a loading bar
     after its data arrived, a skeleton replaced by content): the loop
     names stay in the list, so they run on where they are, and the exit
     takes the positions after them. A leave variant may name one or two
     keyframes, so its timing is listed twice (a list repeats to the
     number of names; surplus entries are ignored). */
  .ds-leave:where(.ds-loadbar) {
    animation-name: ds-progress-head, ds-progress-tail, var(--ds-leave-keyframes, ds-fade-out);
    animation-duration: var(--ds-loop-indeterminate), var(--ds-loop-indeterminate), var(--ds-leave-duration, var(--ds-dur-fast)), var(--ds-leave-duration, var(--ds-dur-fast));
    animation-timing-function: linear, linear, var(--ds-leave-easing, var(--ds-ease-in)), var(--ds-leave-easing, var(--ds-ease-in));
    animation-iteration-count: infinite, infinite, 1, 1;
    animation-fill-mode: none, none, forwards, forwards;
  }

  .ds-leave:where(.ds-skeleton) {
    animation-name: ds-skeleton-wave, var(--ds-leave-keyframes, ds-fade-out);
    animation-duration: var(--ds-loop-skeleton), var(--ds-leave-duration, var(--ds-dur-fast)), var(--ds-leave-duration, var(--ds-dur-fast));
    animation-timing-function: linear, var(--ds-leave-easing, var(--ds-ease-in)), var(--ds-leave-easing, var(--ds-ease-in));
    animation-delay: calc(var(--ds-delay-loader) + var(--ds-dur-medium)), 0ms, 0ms;
    animation-iteration-count: infinite, 1, 1;
    animation-fill-mode: backwards, forwards, forwards;
  }

  /*
   * A slot where outgoing and incoming content cross (roll() and
   * crossfade() in js/motion.js): every child takes the same grid cell, so
   * while both are there the slot keeps the width of the wider one instead
   * of jumping, and a line that rolls in or out is clipped at the slot.
   *
   *   <span class="ds-swap"><span>Saving ...</span></span>   via JS: DS.motion.roll(el, 'Saved')
   */
  .ds-swap {
    display: inline-grid;
    overflow: clip;
  }

  .ds-swap > * {
    grid-area: 1 / 1;
  }

  /*
   * A soft slot edge (2.0): lines appear from and leave behind a soft edge
   * instead of a hard cut. The slot takes --ds-swap-fade (default
   * --ds-space-2) of room above and below, given back by a negative margin
   * so nothing moves, and a static vertical mask fades that room. Nothing
   * in the mask animates.
   *
   *   <span class="ds-swap ds-swap--fade"><span>Syncing 3 of 40</span></span>
   */
  .ds-swap--fade {
    padding-block: var(--ds-swap-fade, var(--ds-space-2));
    margin-block: calc(-1 * var(--ds-swap-fade, var(--ds-space-2)));
    -webkit-mask-image: linear-gradient(to bottom, transparent, #000 var(--ds-swap-fade, var(--ds-space-2)), #000 calc(100% - var(--ds-swap-fade, var(--ds-space-2))), transparent);
    mask-image: linear-gradient(to bottom, transparent, #000 var(--ds-swap-fade, var(--ds-space-2)), #000 calc(100% - var(--ds-swap-fade, var(--ds-space-2))), transparent);
  }

  /*
   * Icon swap (copy to check, play to pause): two icons in one grid cell.
   * data-swap="b" on the wrapper, or (without data-swap) an ancestor with
   * aria-pressed="true", shows b; otherwise a shows. The incoming icon
   * fades in (--ds-dur-fast) and springs up from --ds-scale-small
   * (--ds-dur-medium); the outgoing one only fades (--ds-dur-instant,
   * accelerating) and takes its small scale once it is gone. A
   * pathLength="1" glyph in b (the check) draws itself as it comes. A
   * crossfade with a scale, not a path morph. Transitions, not keyframes:
   * nothing plays on the first render, and a rapid toggle turns back from
   * where the icons are. DS.motion.crossfade(el, icon, { kind: 'icon' })
   * builds the markup and flips data-swap.
   *
   *   <span class="ds-icon-swap" data-swap="a">
   *     <span class="ds-icon-swap__a">(copy)</span><span class="ds-icon-swap__b">(check)</span>
   *   </span>
   */
  .ds-icon-swap {
    display: inline-grid;
    place-items: center;
    vertical-align: middle;
  }

  .ds-icon-swap > :is(.ds-icon-swap__a, .ds-icon-swap__b) {
    grid-area: 1 / 1;
    display: inline-flex;
    transition:
      opacity var(--ds-dur-fast) var(--ds-ease-in-out),
      scale var(--ds-dur-medium) var(--ds-ease-spatial);
  }

  /* Hidden: b at rest, a while b shows. b's drawn glyph waits undrawn:
     the face carries stroke-dashoffset and the glyph inherits it (one
     state on the face, so engines that restyle only the face's own
     subtree still draw the glyph). */
  .ds-icon-swap > .ds-icon-swap__b,
  .ds-icon-swap:where([data-swap="b"], [aria-pressed="true"] :not([data-swap])) > .ds-icon-swap__a {
    opacity: 0;
    scale: var(--ds-scale-small);
    stroke-dashoffset: 1;
    transition:
      opacity var(--ds-dur-instant) var(--ds-ease-in),
      scale 0s var(--ds-dur-instant),
      stroke-dashoffset 0s var(--ds-dur-instant);
  }

  .ds-icon-swap:where([data-swap="b"], [aria-pressed="true"] :not([data-swap])) > .ds-icon-swap__b {
    opacity: 1;
    scale: 1;
    stroke-dashoffset: 0;
    transition:
      opacity var(--ds-dur-fast) var(--ds-ease-in-out),
      scale var(--ds-dur-medium) var(--ds-ease-spatial),
      stroke-dashoffset var(--ds-dur-medium) var(--ds-ease-out);
  }

  .ds-icon-swap__b [pathLength] {
    stroke-dasharray: 1;
  }

  /*
   * Disclosure: <details class="ds-collapsible"> opens and closes with a
   * height transition where the browser can animate to `auto` (progressive
   * enhancement; elsewhere it simply toggles). A transition takes the
   * timing of the state it moves to, so the closed rule is the close and
   * the [open] rule the open: it opens over --ds-dur-medium on
   * --ds-ease-out (the height pushes the content below, so it never
   * overshoots, D29) and closes faster, accelerating; the content fades
   * with it. content-visibility steps at the end of the close
   * (allow-discrete), so the content stays painted while it goes.
   *
   * The content box clips during the height change, but its clip reaches
   * out by --ds-space-3 (12px): a 2px ring at its snap start (offset +
   * width out, then its own width) plus about --ds-space-1 of room, so the
   * ring of a control flush with the content edge is never cut. One token,
   * not a calc() of the focus tokens: Chromium computes a calc() in
   * overflow-clip-margin to 0. Larger shadows (--ds-elev-2/3) may still be
   * cut a little. Where overflow-clip-margin is missing, give the content
   * that much padding (the ring room) instead.
   */
  @supports (interpolate-size: allow-keywords) {
    .ds-collapsible {
      interpolate-size: allow-keywords;
    }

    .ds-collapsible::details-content {
      height: 0;
      opacity: 0;
      overflow: clip;
      overflow-clip-margin: var(--ds-space-3);
      transition:
        height var(--ds-dur-base) var(--ds-ease-in),
        opacity var(--ds-dur-fast) var(--ds-ease-in),
        content-visibility var(--ds-dur-base) allow-discrete;
    }

    .ds-collapsible[open]::details-content {
      height: auto;
      opacity: 1;
      transition:
        height var(--ds-dur-medium) var(--ds-ease-out),
        opacity var(--ds-dur-medium) var(--ds-ease-in-out),
        content-visibility var(--ds-dur-medium) allow-discrete;
    }
  }

  /*
   * Disclosure chevron (D25): turns 180deg with the expansion on the spring,
   * in a summary of an open <details> or under aria-expanded="true" (a
   * table row's toggle, a menu trigger).
   *
   *   <summary>Advanced <svg class="ds-chevron" ...>(chevronDown)</svg></summary>
   *   <button aria-expanded="false" ...><svg class="ds-chevron" ...>(chevronDown)</svg></button>
   */
  .ds-chevron {
    transition: rotate var(--ds-dur-medium) var(--ds-ease-spatial);
  }

  /* A collapsible's summary with a chevron drops the native marker. */
  .ds-collapsible > summary:has(> .ds-chevron) {
    list-style: none;
  }

  .ds-collapsible > summary:has(> .ds-chevron)::-webkit-details-marker {
    display: none;
  }

  .ds-chevron:where([open] > summary *, [aria-expanded="true"] *) {
    rotate: 180deg;
  }

  /*
   * Presence: a project element that is toggled with the hidden attribute,
   * as a [popover] or as a <dialog> without DS.overlay fades in and grows
   * from --ds-motion-scale (default --ds-scale-popup) on the spring, its
   * clip opening from --ds-clip-from (DS.motion.originFrom() writes it;
   * by default the clip stays open), and leaves faster, accelerating.
   * display and overlay step with allow-discrete, so it stays rendered (and
   * in the top layer) until its exit ends. Plain transitions retarget by
   * themselves: open, close, open continues from where it is. The exit
   * state is three separate rules, so an engine that does not know
   * :popover-open drops only its own rule. Elsewhere: an instant toggle.
   * The lists also carry the element's own state transitions (background,
   * colour, border, shadow on --ds-dur-fast, the focus snap of
   * outline-offset), so a pill inside keeps its hover and focus motion; put
   * .ds-presence on a wrapper, never on a .ds-btn, .ds-chip or .ds-card
   * (their own transition lists would be replaced).
   */
  @supports (transition-behavior: allow-discrete) {
    .ds-presence {
      clip-path: inset(calc(-1 * var(--ds-space-6)));
      transition:
        opacity var(--ds-dur-fast) var(--ds-ease-in-out),
        scale var(--ds-dur-medium) var(--ds-ease-spatial),
        clip-path var(--ds-dur-medium) var(--ds-ease-spatial),
        background-color var(--ds-dur-fast) var(--ds-ease-in-out),
        color var(--ds-dur-fast) var(--ds-ease-in-out),
        border-color var(--ds-dur-fast) var(--ds-ease-in-out),
        box-shadow var(--ds-dur-fast) var(--ds-ease-in-out),
        outline-offset var(--ds-dur-fast) var(--ds-ease-out),
        display var(--ds-dur-medium) allow-discrete,
        overlay var(--ds-dur-medium) allow-discrete;
    }

    @starting-style {
      .ds-presence:not(.ds-presence--keep) {
        opacity: 0;
        scale: var(--ds-motion-scale, var(--ds-scale-popup));
        clip-path: var(--ds-clip-from, inset(calc(-1 * var(--ds-space-6))));
      }
    }

    .ds-presence[hidden] {
      opacity: 0;
      scale: var(--ds-motion-scale, var(--ds-scale-popup));
      clip-path: var(--ds-clip-from, inset(calc(-1 * var(--ds-space-6))));
      transition:
        opacity var(--ds-dur-fast) var(--ds-ease-in-out),
        scale var(--ds-dur-fast) var(--ds-ease-in),
        clip-path var(--ds-dur-fast) var(--ds-ease-in),
        background-color var(--ds-dur-fast) var(--ds-ease-in-out),
        color var(--ds-dur-fast) var(--ds-ease-in-out),
        border-color var(--ds-dur-fast) var(--ds-ease-in-out),
        box-shadow var(--ds-dur-fast) var(--ds-ease-in-out),
        outline-offset var(--ds-dur-fast) var(--ds-ease-out),
        display var(--ds-dur-fast) allow-discrete,
        overlay var(--ds-dur-fast) allow-discrete;
    }

    dialog.ds-presence:not([open]) {
      opacity: 0;
      scale: var(--ds-motion-scale, var(--ds-scale-popup));
      clip-path: var(--ds-clip-from, inset(calc(-1 * var(--ds-space-6))));
      transition:
        opacity var(--ds-dur-fast) var(--ds-ease-in-out),
        scale var(--ds-dur-fast) var(--ds-ease-in),
        clip-path var(--ds-dur-fast) var(--ds-ease-in),
        background-color var(--ds-dur-fast) var(--ds-ease-in-out),
        color var(--ds-dur-fast) var(--ds-ease-in-out),
        border-color var(--ds-dur-fast) var(--ds-ease-in-out),
        box-shadow var(--ds-dur-fast) var(--ds-ease-in-out),
        outline-offset var(--ds-dur-fast) var(--ds-ease-out),
        display var(--ds-dur-fast) allow-discrete,
        overlay var(--ds-dur-fast) allow-discrete;
    }

    .ds-presence[popover]:not(:popover-open) {
      opacity: 0;
      scale: var(--ds-motion-scale, var(--ds-scale-popup));
      clip-path: var(--ds-clip-from, inset(calc(-1 * var(--ds-space-6))));
      transition:
        opacity var(--ds-dur-fast) var(--ds-ease-in-out),
        scale var(--ds-dur-fast) var(--ds-ease-in),
        clip-path var(--ds-dur-fast) var(--ds-ease-in),
        background-color var(--ds-dur-fast) var(--ds-ease-in-out),
        color var(--ds-dur-fast) var(--ds-ease-in-out),
        border-color var(--ds-dur-fast) var(--ds-ease-in-out),
        box-shadow var(--ds-dur-fast) var(--ds-ease-in-out),
        outline-offset var(--ds-dur-fast) var(--ds-ease-out),
        display var(--ds-dur-fast) allow-discrete,
        overlay var(--ds-dur-fast) allow-discrete;
    }
  }

  /*
   * Presence that keeps its box (2.0): a pill that shows on hover, a "Saved"
   * note, a jump button whose room stays reserved. The page toggles
   * data-ds-shown; hidden is opacity 0 and visibility hidden (out of the
   * tab order and the accessibility tree), so nothing around it moves. It
   * fades in over --ds-dur-fast and out in --ds-dur-instant (exit 0.67);
   * visibility steps at the end of the exit. Baseline: no @starting-style
   * or allow-discrete needed.
   *
   *   <span class="ds-presence ds-presence--keep" [data-ds-shown]>...</span>
   */
  .ds-presence--keep {
    opacity: 0;
    visibility: hidden;
    transition:
      opacity var(--ds-dur-instant) var(--ds-ease-in-out),
      visibility 0s linear var(--ds-dur-instant);
  }

  .ds-presence--keep[data-ds-shown] {
    opacity: 1;
    visibility: visible;
    transition:
      opacity var(--ds-dur-fast) var(--ds-ease-in-out),
      visibility 0s;
  }

  /* A node that DS.dom.morphHtml moves with insertBefore (engines without
     moveBefore) is new to the style engine, so its @starting-style
     entrances (a status icon, an error message's room) would play again on
     every sort. It carries data-ds-moving for one style flush: no
     transitions, so data changes glide and never replay an entrance.
     DS.indicator.create() sets it on the track for the flush that
     gives its items their look under the new pill. Their ::before and
     ::after too: a hairline or a state layer is part of the look. */
  :where(.ds-theme) [data-ds-moving],
  :where(.ds-theme) [data-ds-moving]::before,
  :where(.ds-theme) [data-ds-moving]::after,
  :where(.ds-theme) [data-ds-moving] *,
  :where(.ds-theme) [data-ds-moving] *::before,
  :where(.ds-theme) [data-ds-moving] *::after {
    transition: none;
  }

  /* ── View transitions ──────────────────────────── */
  /*
   * DS.motion.transition() (js/motion.js) writes data-ds-vt="<type>" on
   * <html> while a View Transition runs; shell.css, sheet.css and
   * toast.css name the view, the panel, the docked drawer, an open sheet's
   * body and a snackbar region with messages only then (and it adds
   * data-ds-vt-morph while the panel changes width), and an
   * indicator created with a `name` carries its own name for good. Every
   * selector starts at .ds-theme, so it only matches when the theme sits on
   * <html> (the pseudo-elements hang off the document element and inherit
   * its tokens) and never restyles a host page. Durations and curves are
   * tokens, so --ds-time-scale slows them too.
   *
   * Old and new are two images of one moment, not a component's entrance
   * and exit: the exit-to-entrance ratio does not apply, and fade-through
   * lets the old view go in --ds-dur-instant by design. No keyframes of
   * their own: the ds-fade-*, ds-grow-in and ds-shift-in/-out pairs.
   */

  /* A view outside the app frame (2.0): a wizard, a sign-in page or a page
     without .ds-app names its .ds-vt-view ds-view while a transition runs,
     so it plays like .ds-view. One per page, never inside .ds-app (the
     frame's view has the name then). Without View Transitions
     DS.motion.transition() enters its first child with .ds-enter--swap.

       <main class="ds-vt-view"><section>(step 1)</section></main> */
  .ds-theme[data-ds-vt] .ds-vt-view {
    view-transition-name: ds-view;
  }

  /* The root (the top bar, the backdrop, everything unnamed): the browser's
     crossfade, short; pixels that did not change stay still under its
     plus-lighter blend. */
  .ds-theme::view-transition-old(root),
  .ds-theme::view-transition-new(root) {
    animation-duration: var(--ds-dur-fast);
    animation-timing-function: var(--ds-ease-in-out);
  }

  /* Every group moves and resizes on the spring, over the indicator's cap
     (--ds-dur-slow): a named indicator glides to its new item this way on
     a page load (css/optional/view-transitions.css). */
  .ds-theme::view-transition-group(*) {
    animation-duration: var(--ds-dur-slow);
    animation-timing-function: var(--ds-ease-spatial);
  }

  /* The docked drawer stays the drawer: its new image is live and covers
     the old one at once (no crossfade), so the pill glides to the new
     destination under its labels and the labels change colour, as on a
     click (DS.motion.transition() lifts an indicator's name meanwhile).
     When the drawer leaves or comes back with the view, the :only-child
     image plays its own motion. */
  .ds-theme::view-transition-new(ds-drawer) {
    animation: none;
  }

  /* Fade-through, the default (without a condition on data-ds-vt, so the
     opt-in stylesheet for page loads reuses it): the old view goes quickly
     and accelerating, then the new one fades in and grows from
     --ds-scale-enter in place. */
  .ds-theme::view-transition-old(ds-view),
  .ds-theme::view-transition-old(ds-sheet-body) {
    animation: ds-fade-out var(--ds-dur-instant) var(--ds-ease-in) both;
  }

  .ds-theme::view-transition-new(ds-view),
  .ds-theme::view-transition-new(ds-sheet-body) {
    --ds-motion-distance: 0px;
    animation:
      ds-fade-in var(--ds-dur-medium) var(--ds-ease-in-out) var(--ds-dur-instant) both,
      ds-grow-in var(--ds-dur-medium) var(--ds-ease-spatial) var(--ds-dur-instant) both;
  }

  /* Shared axis X: forward, the old view leaves to the start while the new
     one comes from the end; back mirrors both. The two images travel on
     one axis on the spring and land together at --ds-dur-slow; the fades
     are those of fade-through. The new image travels with its fade (after
     --ds-dur-instant, over --ds-dur-medium): the spring covers most of
     its way early, so a view that moved while still invisible would only
     settle on screen. */
  .ds-theme[data-ds-vt="forward"]::view-transition-old(ds-view),
  .ds-theme[data-ds-vt="forward"]::view-transition-old(ds-sheet-body) {
    --ds-motion-distance: calc(-1 * var(--ds-distance-xl));
    animation:
      ds-fade-out var(--ds-dur-instant) var(--ds-ease-in) both,
      ds-shift-out var(--ds-dur-slow) var(--ds-ease-spatial) both;
  }

  .ds-theme[data-ds-vt="forward"]::view-transition-new(ds-view),
  .ds-theme[data-ds-vt="forward"]::view-transition-new(ds-sheet-body) {
    --ds-motion-distance: var(--ds-distance-xl);
    animation:
      ds-fade-in var(--ds-dur-medium) var(--ds-ease-in-out) var(--ds-dur-instant) both,
      ds-shift-in var(--ds-dur-medium) var(--ds-ease-spatial) var(--ds-dur-instant) both;
  }

  .ds-theme[data-ds-vt="back"]::view-transition-old(ds-view),
  .ds-theme[data-ds-vt="back"]::view-transition-old(ds-sheet-body) {
    --ds-motion-distance: var(--ds-distance-xl);
    animation:
      ds-fade-out var(--ds-dur-instant) var(--ds-ease-in) both,
      ds-shift-out var(--ds-dur-slow) var(--ds-ease-spatial) both;
  }

  .ds-theme[data-ds-vt="back"]::view-transition-new(ds-view),
  .ds-theme[data-ds-vt="back"]::view-transition-new(ds-sheet-body) {
    --ds-motion-distance: calc(-1 * var(--ds-distance-xl));
    animation:
      ds-fade-in var(--ds-dur-medium) var(--ds-ease-in-out) var(--ds-dur-instant) both,
      ds-shift-in var(--ds-dur-medium) var(--ds-ease-spatial) var(--ds-dur-instant) both;
  }

  /* Container transform: the card or row (ds-container before the update)
     grows into its detail (ds-container after it) on the spring over
     --ds-dur-long, a large surface. One surface grows: the new image is
     live and opaque from the first frame, and the old one lies on top of
     it and fades out within --ds-dur-fast (two images fading at once
     would leave the group see-through halfway, the page showing through
     a card that vanishes and a panel that fades in). */
  .ds-theme[data-ds-vt="container"]::view-transition-group(ds-container) {
    animation-duration: var(--ds-dur-long);
    animation-timing-function: var(--ds-ease-spatial);
  }

  /* Both images keep the browser's sizing (as wide as the group, their own
     aspect, from the top) and the pair clips them to the group: a card is
     never stretched into the shape of its detail, nor magnified to cover a
     much taller panel (cover would scale a card's text several times). */
  .ds-theme[data-ds-vt="container"]::view-transition-image-pair(ds-container) {
    overflow: clip;
  }

  .ds-theme[data-ds-vt="container"]::view-transition-old(ds-container) {
    z-index: var(--ds-z-raised);
    animation: ds-fade-out var(--ds-dur-fast) var(--ds-ease-in-out) both;
  }

  .ds-theme[data-ds-vt="container"]::view-transition-new(ds-container) {
    animation: none;
  }

  /* A view with or without the drawer (data-drawer-hidden toggled inside
     DS.motion.transition()): the panel morphs to its new width instead of
     the grid jumping, a large surface on the spring over --ds-dur-long.
     Its images are only the white surface (the content is the separately
     named view), so the new one fills the group at once and the old one
     is not drawn. The view's group travels with it; its images keep their
     natural size from the top left, so text is never scaled while the
     width changes (the group's edge cuts it). Only then (DS.motion.
     transition() sets data-ds-vt-morph when the panel's width changed):
     a plain swap keeps the --ds-dur-slow groups, so the frozen page holds
     input no longer than the view's own motion. Page loads cannot tell,
     so they keep --ds-dur-slow too. */
  .ds-theme[data-ds-vt-morph]::view-transition-group(ds-panel),
  .ds-theme[data-ds-vt-morph]::view-transition-group(ds-view) {
    animation-duration: var(--ds-dur-long);
  }

  /* Stacking inside the transition (two steps of the z scale): a drawer
     that comes back exists in the new state only, so its group comes last
     and would paint over the panel that makes room for it; the surfaces of
     the page lie above the drawer instead, in their own order. The drawer
     lies above an indicator's group (page loads), so a gliding pill passes
     under its labels (the opt-in stylesheet makes the docked drawer
     transparent; it lies on the same backdrop). */
  .ds-theme::view-transition-group(ds-drawer) {
    z-index: var(--ds-z-raised);
  }

  .ds-theme::view-transition-group(ds-panel),
  .ds-theme::view-transition-group(ds-view),
  .ds-theme::view-transition-group(ds-sheet-body),
  .ds-theme::view-transition-group(ds-container) {
    z-index: var(--ds-z-sticky);
  }

  /* Snackbars stay where they are: a region with messages (toast.css
     names it ds-toasts while a transition runs) lies above every group
     of the page and shows only its live image, so a message never blinks
     out under the panel's opaque image; its group follows the region if
     the update moves it (the drawer shown or hidden). A message that goes
     with the update fades out. */
  .ds-theme::view-transition-group(ds-toasts) {
    z-index: var(--ds-z-toast);
  }

  .ds-theme::view-transition-old(ds-toasts) {
    opacity: 0;
    animation: none;
  }

  .ds-theme::view-transition-new(ds-toasts) {
    animation: none;
  }

  .ds-theme::view-transition-old(ds-toasts):only-child {
    opacity: 1;
    animation: ds-fade-out var(--ds-dur-fast) var(--ds-ease-in) both;
  }

  /* A drawer in both states shows only its live image (see above); a
     transparent one would otherwise show both label sets at once. */
  .ds-theme::view-transition-old(ds-drawer) {
    opacity: 0;
    animation: none;
  }

  .ds-theme::view-transition-old(ds-panel) {
    opacity: 0;
    animation: none;
  }

  .ds-theme::view-transition-new(ds-panel) {
    width: 100%;
    height: 100%;
    animation: none;
  }

  /* A panel on one side only: a page load from a page whose frame lay
     under the modal drawer or an overlay (css/optional/view-transitions.css
     names it only where nothing covers it) crossfades like the root
     around it, so the drawer and its scrim do not vanish at once. */
  .ds-theme::view-transition-new(ds-panel):only-child {
    animation: ds-fade-in var(--ds-dur-fast) var(--ds-ease-in-out) both;
  }

  .ds-theme::view-transition-old(ds-panel):only-child {
    opacity: 1;
    animation: ds-fade-out var(--ds-dur-fast) var(--ds-ease-in-out) both;
  }

  .ds-theme::view-transition-old(ds-view),
  .ds-theme::view-transition-new(ds-view) {
    height: 100%;
    overflow: clip;
    object-fit: none;
    object-position: left top;
  }

  /* The docked drawer leaves to the start, accelerating, faded within
     --ds-dur-fast (the panel grows over it); it comes back from there on
     the spring while the panel makes room. Only one image exists then:
     the drawer is shown on one side of the transition only. */
  .ds-theme::view-transition-old(ds-drawer):only-child {
    --ds-motion-distance: calc(-1 * var(--ds-distance-xl));
    opacity: 1;
    animation:
      ds-fade-out var(--ds-dur-fast) var(--ds-ease-in) both,
      ds-shift-out var(--ds-dur-base) var(--ds-ease-exit) both;
  }

  .ds-theme::view-transition-new(ds-drawer):only-child {
    --ds-motion-distance: calc(-1 * var(--ds-distance-xl));
    animation:
      ds-fade-in var(--ds-dur-medium) var(--ds-ease-in-out) both,
      ds-shift-in var(--ds-dur-long) var(--ds-ease-spatial) both;
  }
}

/* ── core/base.css ── */
/*
 * Page base for full apps (opt-in): the backdrop, body type, selection,
 * headings on the type roles (h1 headline, h2 subtitle, h3 to h6 the
 * label role, no margins), links (an icon at either end of a plain link
 * keeps its distance), inline code (just text inside a pre or a link), a
 * rule (hr, a hairline like .ds-divider), marked text (mark, on the tint)
 * and the focus ring. Rendered rich text keeps a hierarchy of its own in
 * .ds-prose. Under .ds-base `hidden` always hides; never add a [hidden]
 * rule of your own. (Border-box sizing applies to all of .ds-theme, see
 * global.css.)
 *
 *   <html class="ds-theme ds-base">
 *
 * Every rule is scoped to .ds-base through :where(), which adds no
 * specificity: the rules weigh exactly what bare element selectors would,
 * so any class of the page still wins over them. An embedded widget puts
 * .ds-base on its root element: the html/body rules never match there, so
 * the host page stays untouched.
 */

@layer ds.base {
  /* Under .ds-base `hidden` beats everything, page CSS included. Without
     it (a widget that leaves it off), motion.css still hides ds components that
     carry `hidden` inside .ds-theme, in ds.utilities. */
  :where(.ds-base) [hidden] {
    display: none !important;
  }

  html:where(.ds-base),
  :where(.ds-base) body {
    margin: 0;
    height: 100%;
  }

  /* The tinted backdrop of the whole app: white panels sit on it. */
  html:where(.ds-base) {
    -webkit-text-size-adjust: 100%;
    text-size-adjust: 100%;
    background: var(--ds-backdrop);
  }

  :where(.ds-base) body {
    font: var(--ds-font-body);
    color: var(--ds-text);
    background: var(--ds-backdrop);
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
  }

  :where(.ds-base) ::selection {
    background: var(--ds-accent);
    color: var(--ds-on-accent);
  }

  /* Set while a modal layer is open (the page behind must not scroll). */
  :where(.ds-base) body.ds-no-scroll {
    overflow: hidden;
  }

  /* Links are told apart from text by the underline, not by colour. */
  :where(.ds-base) a {
    color: var(--ds-link);
    text-decoration-line: underline;
    text-decoration-thickness: var(--ds-link-underline-thickness);
    text-underline-offset: var(--ds-link-underline-offset);
    text-decoration-color: var(--ds-link-underline);
    outline-offset: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    transition:
      text-decoration-color var(--ds-dur-fast) var(--ds-ease-in-out),
      outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  @media (hover: hover) {
    :where(.ds-base) a:hover {
      text-decoration-color: var(--ds-link-underline-hover);
    }
  }

  /* An icon at the end of a plain link (an external link, "Open") or at its
     start keeps a gap to the text and sits on its centre line. */
  :where(.ds-base) :where(a:not([class])) > svg:last-child {
    margin-inline-start: var(--ds-space-1);
    vertical-align: -0.125em;
  }

  :where(.ds-base) :where(a:not([class])) > svg:first-child {
    margin-inline-end: var(--ds-space-1);
    vertical-align: -0.125em;
  }

  /* Bare headings take the type roles, without the browser's margins:
     element weight only, in ds.base, so every component class and every
     unlayered project rule wins. Two weights, as everywhere. */
  :where(.ds-base) :is(h1, h2, h3, h4, h5, h6) {
    margin: 0;
    color: var(--ds-text);
    letter-spacing: 0;
  }

  :where(.ds-base) h1 {
    font: var(--ds-font-headline);
  }

  :where(.ds-base) h2 {
    font: var(--ds-font-subtitle);
  }

  :where(.ds-base) :is(h3, h4, h5, h6) {
    font: var(--ds-font-label);
  }

  /* A rule: a hairline, as .ds-divider. */
  :where(.ds-base) hr {
    margin: 0;
    border: 0;
    border-top: 1px solid var(--ds-line);
  }

  /* Marked text (a search hit): on the tint. Forced colours map it to Mark
     by themselves. */
  :where(.ds-base) mark {
    border-radius: var(--ds-radius-xs);
    background: var(--ds-accent);
    color: var(--ds-on-accent);
  }

  /* Inline code takes the size and colour of the text around it, only the
     typeface changes (a layered reset's code colour does not reach it).
     Its own box is just its glyphs: the monospace font sits higher on the
     baseline and would open up the line by a pixel. */
  :where(.ds-base) code {
    font-family: var(--ds-font-mono);
    font-size: inherit;
    color: inherit;
    line-height: 1;
    background: var(--ds-code-bg);
    border: 1px solid var(--ds-line);
    border-radius: var(--ds-radius-xs);
    padding: 0 var(--ds-space-1);
  }

  /* Code in a block or a link is part of it: no chip per line. */
  :where(.ds-base) :where(pre, a) code {
    padding: 0;
    border: 0;
    background: none;
    line-height: inherit;
  }

  :where(.ds-base) button,
  :where(.ds-base) input,
  :where(.ds-base) select,
  :where(.ds-base) textarea {
    font-family: inherit;
  }

  /* Two weights, 400 and the label weight: emphasis in UI copy is a label,
     not the browser's bold. */
  :where(.ds-base) strong,
  :where(.ds-base) b {
    font-weight: var(--ds-weight-label);
  }

  /* The ring is solid from the first frame and snaps in: links (above),
     disclosure summaries and focusable elements rest one ring width further
     out. Other elements, and programmatic focus targets (tabindex -1, such
     as the drawer, whose forced-colours edge is an outline), show it at
     once. The outline follows the element's radius. */
  :where(.ds-base) :where(summary, [tabindex]:not([tabindex^="-"])) {
    outline-offset: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    transition: outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  :where(.ds-base) :focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: var(--ds-focus-offset);
  }
}

/* ── core/global.css ── */
/*
 * Global: the rules for every element inside .ds-theme, whatever
 * components a page uses, so every bundle and every set of single files
 * carries them (tools/bundle.mjs writes the core first).
 *
 * - Border-box sizing: every component is measured as border-box (a 100%
 *   wide field with its padding, a dialog of min(400px, 100%)). Zero
 *   specificity, so a host page that embeds .ds-theme keeps any sizing it
 *   sets itself. Elements only: a rule whose subject is every ::before and
 *   ::after makes the engine compute two pseudo-element styles for every
 *   element of the page, content or not (in Chromium more than half the
 *   style cost of a plain element). A pseudo-element with a size and a
 *   border or padding sets box-sizing in its own rule.
 * - Zero-weight defaults that a component of an earlier sublayer must still
 *   beat: the browser margins of paragraphs in a card.
 * - Forced colours: icons coloured on the <svg> itself would keep their
 *   authored colour (dark grey on black), so every icon follows the forced
 *   text colour of its control.
 *
 * The rules sit in ds.components, first in it (ds.css inlines this file
 * right before the first component): they held that place in 2.x, at the
 * top of utilities.css (border-box) and in shell.css (the !important icon
 * colour, which no other rule sets with !important, so its place within
 * the layer decides nothing).
 */

@layer ds.components.global {
  :where(.ds-theme),
  :where(.ds-theme) * {
    box-sizing: border-box;
  }

  /* A card's rhythm decides its spacing: no browser margins of paragraphs
     in it (a last one would add 1em to the bottom padding). Here and not in
     card.css: a zero-weight default holds only in the first sublayer, and
     the paragraphs of components that come before the card (a tile's
     value, a progress label) keep their own margins. */
  :where(.ds-card) p {
    margin-block: 0;
  }

  @media (forced-colors: active) {
    .ds-theme svg {
      color: inherit !important;
    }
  }
}


/* ── components/layout/layout.css ── */
/*
 * Layout: the primitives a page arranges its parts with, on the gap
 * tokens. Each works by its intrinsic size (no media query and no
 * container needed), so it fits a phone, a side sheet and a wide page
 * alike. The one-column stack is .ds-stack of the page component.
 *
 *   <div class="ds-cluster">button, chip, badge ...</div>     a row that wraps
 *   <div class="ds-cluster ds-cluster--between">title, actions</div>
 *   <button class="ds-btn ds-push">...</button>    pushes itself and what follows to the row's end
 *
 *   <div class="ds-split">                            side and main, stacked once main would be narrower than --ds-split-min
 *     <aside class="ds-split__side">filters</aside>
 *     <div class="ds-split__main">results</div>
 *   </div>
 *   (the side may come second: at the end on one line, below main once stacked)
 *
 *   <div class="ds-switcher">a, b, c</div>           a row of equal parts that turns into a column at once
 *   <div class="ds-measure">text, form</div>          a centred column at the reading measure
 *   <div class="ds-cover">                            fills the height; __main sits in the middle
 *     <header>...</header><div class="ds-cover__main">...</div><footer>...</footer>
 *   </div>
 *   <div class="ds-frame ds-frame--4-3"><img src="..." alt="..."></div>   media cropped to a ratio
 *   <div class="ds-grid">card, card, card ...</div>  auto-fit columns at least --ds-grid-min wide
 *
 * Modifiers:
 *   .ds-cluster--end, --center, --between   where the row's items go
 *   .ds-cluster--top, --baseline            how they line up across (default: centred)
 *   .ds-cluster--nowrap                     one line; a .ds-truncate title (or its wrapper) gives way, the rest keep their width
 *   .ds-split--stretch                      side and main as tall as the taller one (default: top)
 *   .ds-switcher--top                       parts keep their own height (default: as tall as the tallest)
 *   .ds-measure--wide                       --ds-content-max instead of the reading measure
 *   .ds-measure--intrinsic                  centres its children at their own width
 *   .ds-cover--screen                       at least the dynamic viewport high
 *   .ds-frame--square, --4-3, --3-4, --16-9 (default), --21-9
 *   .ds-grid--fill                          keeps empty tracks: a lone card stays a card wide
 *   .ds-grid--max-2, --max-3, --max-4, --max-6   at most so many columns
 *
 * Options: density tightens the default gaps by 2px a step (the padding
 * of blocks, conventions section 3), never below 0; a .ds-gap-* class
 * (spacing) sets an exact gap; a gap hook sets the base that density
 * steps from. Shape multiplies the frame's
 * radius. Size, tone and touch are the children's own: a primitive has no
 * height or meaning.
 *
 * Hooks: --ds-cluster-gap (--ds-space-2), --ds-split-gap,
 * --ds-switcher-gap, --ds-grid-gap (--ds-space-4), --ds-split-side
 * (18rem, the side's width while beside main), --ds-split-min (50%, the
 * narrowest main before they stack), --ds-switcher-at (30rem, the width
 * under which the parts stack), --ds-measure-max (--ds-measure),
 * --ds-measure-pad (0), --ds-cover-min (100%), --ds-cover-pad
 * (--ds-space-4), --ds-frame-ratio (16 / 9), --ds-frame-radius
 * (--ds-radius-md), --ds-grid-min (16rem).
 *
 * No motion: a primitive never animates its layout.
 */

@layer ds.components.layout {
  /* ── Cluster: a row that wraps ────────────────── */

  .ds-cluster {
    --_gap: max(0px, calc(var(--ds-cluster-gap, var(--ds-space-2)) + var(--ds-density, 0) * 2px));
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--_gap);
    min-width: 0;
  }

  .ds-cluster--end {
    justify-content: flex-end;
  }

  .ds-cluster--center {
    justify-content: center;
  }

  .ds-cluster--between {
    justify-content: space-between;
  }

  .ds-cluster--top {
    align-items: flex-start;
  }

  .ds-cluster--baseline {
    align-items: baseline;
  }

  /* One line instead of wrapping. With a .ds-truncate title in it, only
     the title (or the item that holds it) gives way: every other item
     keeps its width, even one wider than its content (an icon button, an
     avatar). Without one, the items shrink as flex items do, to their
     longest word. A cluster that holds a title says so to its items
     (--_cluster-shrink: 0, inherited); a selector that styles the items of
     a cluster that :has() a title, or an item after one that does, makes
     Chromium restyle the whole page on each change of an attribute
     anywhere. An item that is another nowrap cluster passes the 0 on to
     its own items: they keep their width as it keeps its own. */
  .ds-cluster--nowrap {
    flex-wrap: nowrap;
  }

  .ds-cluster--nowrap:has(.ds-truncate) {
    --_cluster-shrink: 0;
  }

  .ds-cluster--nowrap > :not(.ds-truncate, :has(.ds-truncate)) {
    flex-shrink: var(--_cluster-shrink, 1);
  }

  .ds-cluster--nowrap > :has(.ds-truncate) {
    min-width: 0;
  }

  /* An auto margin takes the free space of its line: this item and what
     follows go to the end. */
  .ds-push {
    margin-inline-start: auto;
  }

  /* ── Split: a side and the main column ─────────── */

  /* Both grow; main grows far more, so the side keeps --ds-split-side
     while they share a line. Once main would fall under --ds-split-min of
     the line, it wraps below and both take the full width. */
  .ds-split {
    --_gap: max(0px, calc(var(--ds-split-gap, var(--ds-space-4)) + var(--ds-density, 0) * 2px));
    display: flex;
    flex-wrap: wrap;
    align-items: flex-start;
    gap: var(--_gap);
    min-width: 0;
  }

  .ds-split--stretch {
    align-items: stretch;
  }

  .ds-split__side {
    flex-grow: 1;
    flex-basis: var(--ds-split-side, 18rem);
    min-width: 0;
  }

  /* The basis is the narrowest main: side, gap and main fit on one line
     only while main gets --ds-split-min; the growth goes almost all to
     main. No min-width carries it, so a component that sets one on the
     same element (a .ds-stack main) changes nothing. */
  .ds-split__main {
    flex: 999 1 min(100%, var(--ds-split-min, 50%));
    min-width: 0;
  }

  /* ── Switcher: equal parts in a row or a column ── */

  /* Above --ds-switcher-at the basis is negative (every part on one line,
     equal); below it, huge (each part on a line of its own): the row
     turns into a column at once, never with two above one. */
  .ds-switcher {
    --_gap: max(0px, calc(var(--ds-switcher-gap, var(--ds-space-4)) + var(--ds-density, 0) * 2px));
    display: flex;
    flex-wrap: wrap;
    gap: var(--_gap);
    min-width: 0;
  }

  .ds-switcher--top {
    align-items: flex-start;
  }

  .ds-switcher > * {
    flex-grow: 1;
    flex-basis: calc((var(--ds-switcher-at, 30rem) - 100%) * 999);
    min-width: 0;
  }

  /* More than four parts never share a row: they would be too narrow to
     read, so five or more always stack. */
  .ds-switcher > :nth-last-child(n+5),
  .ds-switcher > :nth-last-child(n+5) ~ * {
    flex-basis: 100%;
  }

  /* ── Measure: a centred column ─────────────────── */

  .ds-measure {
    box-sizing: content-box;
    max-inline-size: var(--ds-measure-max, var(--ds-measure));
    margin-inline: auto;
    padding-inline: var(--ds-measure-pad, 0px);
  }

  .ds-measure--wide {
    max-inline-size: var(--ds-measure-max, var(--ds-content-max));
  }

  .ds-measure--intrinsic {
    display: flex;
    flex-direction: column;
    align-items: center;
  }

  /* ── Cover: fills the height, its main part centred ── */

  .ds-cover {
    display: flex;
    flex-direction: column;
    gap: var(--ds-space-4);
    min-block-size: var(--ds-cover-min, 100%);
    padding: var(--ds-cover-pad, var(--ds-space-4));
  }

  .ds-cover--screen {
    min-block-size: 100dvh;
  }

  /* Auto margins share the free height around it: centred, while a head
     and a foot keep to the edges. */
  .ds-cover__main {
    margin-block: auto;
  }

  /* ── Frame: media cropped to a ratio ───────────── */

  .ds-frame {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    aspect-ratio: var(--ds-frame-ratio, 16 / 9);
    overflow: hidden;
    border-radius: calc(var(--ds-frame-radius, var(--ds-radius-md)) * var(--ds-shape, 1));
    background: var(--ds-surface-low);
  }

  .ds-frame--square {
    aspect-ratio: 1;
  }

  .ds-frame--4-3 {
    aspect-ratio: 4 / 3;
  }

  .ds-frame--3-4 {
    aspect-ratio: 3 / 4;
  }

  .ds-frame--16-9 {
    aspect-ratio: 16 / 9;
  }

  .ds-frame--21-9 {
    aspect-ratio: 21 / 9;
  }

  /* Media fill the frame and crop to it; anything else is centred. */
  .ds-frame > :is(img, video, iframe, canvas, picture) {
    inline-size: 100%;
    block-size: 100%;
    border: 0;
    object-fit: cover;
  }

  .ds-frame > picture > img {
    inline-size: 100%;
    block-size: 100%;
    object-fit: cover;
  }

  /* ── Grid: auto-fit columns ────────────────────── */

  /* As many columns as fit at --ds-grid-min (never wider than the grid,
     so a phone gets one). --max-n raises the track's floor just above a
     share of n + 1, so n + 1 columns never fit, whatever the gap. */
  .ds-grid {
    --_gap: max(0px, calc(var(--ds-grid-gap, var(--ds-space-4)) + var(--ds-density, 0) * 2px));
    --_track: var(--ds-grid-min, 16rem);
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(min(100%, var(--_track)), 1fr));
    gap: var(--_gap);
    min-width: 0;
  }

  .ds-grid--fill {
    grid-template-columns: repeat(auto-fill, minmax(min(100%, var(--_track)), 1fr));
  }

  .ds-grid--max-2 {
    --_track: max(var(--ds-grid-min, 16rem), 100% / 3 + 1px);
  }

  .ds-grid--max-3 {
    --_track: max(var(--ds-grid-min, 16rem), 100% / 4 + 1px);
  }

  .ds-grid--max-4 {
    --_track: max(var(--ds-grid-min, 16rem), 100% / 5 + 1px);
  }

  .ds-grid--max-6 {
    --_track: max(var(--ds-grid-min, 16rem), 100% / 7 + 1px);
  }

  /* Forced colours: a frame keeps an edge where its fill turns Canvas. */
  @media (forced-colors: active) {
    .ds-frame {
      outline: 1px solid transparent;
    }
  }
}

/* ── components/utilities/utilities.css ── */
/*
 * Utilities: screen-reader text and small text helpers, the press model
 * for a project element, actions that show on demand, keys, dividers,
 * icons that fill and touch targets. (Border-box sizing inside .ds-theme
 * is core: src/core/global.css.)
 *
 *   .ds-sr       visually hidden, still read by screen readers
 *   .ds-muted    quieter body text (tabular figures, no margin)
 *   .ds-meta     a meta line: hints, "last saved ..." (tabular figures);
 *                a leading 16px icon (> svg:first-child) sits on its line
 *   .ds-stale    content on its way out, dimmed until it is replaced (set
 *                aria-busy="true" on the container while it is stale)
 *   .ds-num      right-aligned tabular figures (table cells)
 *   .ds-center   centred text
 *   .ds-nowrap   keeps a value and its unit together
 *
 * .ds-stale dims only after --ds-delay-loader, so an update that answers
 * within 200ms never dims; taking it off is instant, so fresh values show
 * at once (docs/motion.md, "Data motion").
 *
 * Every component scroller is positioned (a containing block), so
 * .ds-sr text and absolute parts inside it never escape to the page.
 *
 * A pressable element of your own (a row, a card of a project component):
 *
 *   <div class="x-row ds-pressable" tabindex="0" role="button">...</div>
 *   .ds-pressable--lg     the larger hover layer (--ds-state-hover-lg) of big surfaces
 *   .ds-pressable--inset  the ring inside the edge (rests at 0, snaps to -width)
 *
 * The state layer (::before) in var(--ds-pressable-layer, currentColor):
 * hover --ds-state-hover inside @media (hover: hover), the press
 * --ds-state-pressed in --ds-dur-micro (also while js/ripple.js holds
 * .ds-pressed), the focus layer --ds-state-focus at once with the ring,
 * which rests at offset + width and snaps to the offset (--ds-dur-fast).
 * It is a ripple host (DS.ripple.attach()); under .ds-ripples the press is
 * the ripple's. No morph: pills are .ds-btn. Disabled, aria-disabled and
 * aria-busy show no hover or press layer, no ripple and the not-allowed
 * cursor (aria-disabled keeps the focus layer). Forced colours: no layer,
 * the ring stays. Options: .ds-touch makes it at least --ds-touch-target
 * high, .ds-shape-* multiplies its radius; size, density and tone are the
 * project element's own.
 *
 * Actions that show on demand (a row's edit button):
 *
 *   <td><span class="ds-hover-actions"><button class="ds-btn ds-btn--quiet ds-btn--icon ds-sm" type="button" aria-label="Edit">...</button></span></td>
 *
 * .ds-hover-actions fades in (opacity, --ds-dur-fast) while its nearest
 * host (a tr, li, .ds-card, .ds-drawer__row or .ds-hover-host: a table in
 * a card answers to its rows, not to the card) is hovered (devices that
 * hover), holds the focus, is current or selected (a drawer row: its item
 * is current) or carries data-ds-shown, or while the actions hold an open
 * menu ([aria-expanded="true"]) or data-ds-shown; it fades out
 * faster (--ds-dur-instant, 0.67). Always shown on touch screens
 * (hover: none) and under .ds-touch. Opacity only: the buttons stay in the
 * tab order and the accessibility tree, and hover moves nothing.
 *
 *   <kbd class="ds-kbd">Ctrl</kbd>    a key (the code font in a hairline box;
 *                                     .ds-shape-* multiplies its radius)
 *   <hr class="ds-divider">           a hairline (--inset: from --ds-space-4)
 *   <span class="ds-divider ds-divider--vertical" role="separator" aria-orientation="vertical"></span>
 *                                     upright (--inset: short of the row's edges)
 *   <div class="ds-divider ds-divider--label" role="separator"><span>Today</span></div>
 *                                     around a caption (--start, --end: near that end)
 *   <div class="ds-divider ds-divider--vertical ds-divider--label" role="separator" aria-orientation="vertical"><span>or</span></div>
 *                                     upright around a caption
 *   The colour: --ds-divider-color (--ds-line).
 *
 * Icons that fill when on (js/icons.js, the fillable glyphs):
 * .ds-icon--fillable on the <svg> fills its last element in currentColor
 * while an ancestor is [aria-pressed="true"] or [aria-checked="true"]
 * (fill on --ds-dur-fast); .ds-icon--filled fills it always.
 *
 * Touch screens: .ds-touch (on .ds-theme or any container) sets fields to the
 * input type role; every component takes --ds-touch-target (48px) from
 * --ds-target-min, which core/options.css sets on .ds-touch. Opt in
 * (docs/theming.md, "Touch screens"); never automatic.
 *
 * Hooks: --ds-pressable-radius (--ds-radius-sm), --ds-pressable-layer
 * (currentColor), --ds-kbd-border (--ds-line-2), --ds-kbd-bg (--ds-surface),
 * --ds-divider-color (--ds-line).
 *
 * Progressive:
 * - text-wrap (a paragraph of .ds-muted avoids a lone last word): without
 *   it the text wraps as usual.
 */

@layer ds.components.utilities {
  /* Placed at the top left of its positioned ancestor: left where it stands
     (the end of a row that scrolls sideways) it would widen the nearest
     positioned scroller, up to a sideways scroll of the page. */
  .ds-sr {
    position: absolute !important;
    top: 0 !important;
    inset-inline-start: 0 !important;
    width: 1px !important;
    height: 1px !important;
    padding: 0 !important;
    margin: -1px !important;
    overflow: hidden !important;
    clip: rect(0, 0, 0, 0) !important;
    white-space: nowrap !important;
    border: 0 !important;
  }

  .ds-muted {
    margin: 0;
    color: var(--ds-text-2);
    font: var(--ds-font-body);
    /* Counts and times beside a title line up. */
    font-variant-numeric: tabular-nums;
  }

  /* A paragraph of notes keeps the reading measure and ends without a lone
     last word. */
  p.ds-muted {
    max-width: var(--ds-measure);
    text-wrap: pretty;
  }

  .ds-meta {
    margin: 0;
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
    font-variant-numeric: tabular-nums;
  }

  /* A 16px glyph leading the line fills the meta role's 16px line from
     its top, so it centres on the text without growing the line (on the
     baseline it stood 4px high and the line grew), and keeps the gap of
     .ds-kv-list__icon to the text. */
  .ds-meta > svg:first-child {
    display: inline-block;
    margin-inline-end: var(--ds-space-1);
    vertical-align: top;
  }

  /* Content on its way out (a filter applied, a test running again): it
     stays in place, dimmed, until the new one replaces it in one step, so
     nothing collapses and jumps back meanwhile. It dims after the loader
     delay (a fast answer never dims); the rest state has no transition, so
     removing the class shows the fresh values at once. */
  .ds-stale {
    opacity: var(--ds-state-stale);
    transition: opacity var(--ds-dur-base) var(--ds-ease-in-out) var(--ds-delay-loader);
  }

  .ds-num {
    text-align: end !important;
    font-variant-numeric: tabular-nums;
  }

  .ds-center {
    text-align: center !important;
  }

  .ds-nowrap {
    white-space: nowrap;
  }

  /*
   * A pressable element of the project's own: the state layer of the
   * system, the focus snap and the ripple; never a morph.
   */
  .ds-pressable {
    position: relative;
    /* The layer (z-index -1) stays above the fill, below the content. */
    isolation: isolate;
    min-height: var(--ds-target-min, 0px);
    border-radius: calc(var(--ds-pressable-radius, var(--ds-radius-sm)) * var(--ds-shape, 1));
    cursor: pointer;
    -webkit-tap-highlight-color: transparent;
    /* The ring rests (invisible) one width further out and snaps in. */
    outline-offset: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    transition: outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-pressable::before {
    content: '';
    position: absolute;
    inset: 0;
    z-index: -1;
    border-radius: inherit;
    background: var(--ds-pressable-layer, currentColor);
    opacity: 0;
    pointer-events: none;
    transition: opacity var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  @media (hover: hover) {
    .ds-pressable:hover::before {
      opacity: var(--ds-state-hover);
    }

    .ds-pressable--lg:hover::before {
      opacity: var(--ds-state-hover-lg);
    }
  }

  /* Keyboard focus: the layer appears with the ring and fades out on blur. */
  .ds-pressable:focus-visible::before {
    opacity: var(--ds-state-focus);
    transition-duration: 0s;
  }

  .ds-pressable:active::before,
  .ds-pressable.ds-pressed::before {
    opacity: var(--ds-state-pressed);
    transition-duration: var(--ds-dur-micro);
  }

  .ds-pressable:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: var(--ds-focus-offset);
  }

  /* An inset ring (a row in a list that clips): it rests on the edge and snaps inward. */
  .ds-pressable--inset {
    outline-offset: 0;
  }

  .ds-pressable--inset:focus-visible {
    outline-offset: calc(-1 * var(--ds-focus-width));
  }

  /* Blocked: no hover or press layer and no ripple (js/ripple.js); an
     aria-disabled element stays focusable and keeps its focus layer. */
  .ds-pressable:is(:disabled, [aria-disabled="true"], [aria-busy="true"]) {
    cursor: not-allowed;
  }

  @media (hover: hover) {
    .ds-pressable:is(:disabled, [aria-disabled="true"], [aria-busy="true"]):hover::before {
      opacity: 0;
    }
  }

  .ds-pressable:is(:disabled, [aria-disabled="true"], [aria-busy="true"]):is(:active, .ds-pressed)::before {
    opacity: 0;
  }

  /*
   * Actions that show on demand: hidden by opacity only (still in the tab
   * order and the tree), shown with their nearest host's hover, focus,
   * current or selected state, or their own open menu; they leave faster
   * than they come.
   */
  .ds-hover-actions {
    opacity: 0;
    transition: opacity var(--ds-dur-instant) var(--ds-ease-in-out);
  }

  /* Only the nearest host reveals its actions: a table in a card or a list
     in a list item shows the pointed row's actions, not every row's. A
     hovered host's ancestors are hovered too, so "no host around the
     actions is left unhovered" means the nearest one is hovered. The hosts
     of other components (a card, a drawer row, a selected table row) reveal
     them with the same rules in their own stylesheets, which come later
     (card.css, shell.css, table.css); every rule keeps the whole list of
     hosts in its exclusion. */
  @media (hover: hover) {
    :is(tr, li, .ds-hover-host):hover .ds-hover-actions:not(:is(tr, li, .ds-card, .ds-drawer__row, .ds-hover-host):not(:hover) .ds-hover-actions) {
      opacity: 1;
      transition: opacity var(--ds-dur-fast) var(--ds-ease-in-out);
    }
  }

  /* The same for the states: a host in one of them shows its actions
     unless a host nearer the actions is in none of them. An open menu
     counts where it is, in the actions (no :has() on every row and card). */
  :is(tr, li, .ds-hover-host):is(:focus-within, [aria-current]:not([aria-current="false"]), [aria-selected="true"], [data-ds-shown]) .ds-hover-actions:not(:is(tr, li, .ds-card, .ds-drawer__row, .ds-hover-host):is(:focus-within, [aria-current]:not([aria-current="false"]), [aria-selected="true"], .ds-table__row--selected, [data-ds-shown]) :is(tr, li, .ds-card, .ds-drawer__row, .ds-hover-host):not(:focus-within, [aria-current]:not([aria-current="false"]), [aria-selected="true"], .ds-table__row--selected, [data-ds-shown]) .ds-hover-actions),
  .ds-hover-actions:is(:focus-within, [data-ds-shown], [aria-expanded="true"], :has([aria-expanded="true"])) {
    opacity: 1;
    transition: opacity var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  /* No hover to reveal them: always there. */
  @media (hover: none) {
    .ds-hover-actions {
      opacity: 1;
    }
  }

  .ds-touch .ds-hover-actions {
    opacity: 1;
  }

  /* A key on the keyboard: the code font in a hairline box. */
  .ds-kbd {
    display: inline-grid;
    place-items: center;
    min-width: var(--ds-space-5);
    padding: 0 var(--ds-space-1);
    border: 1px solid var(--ds-kbd-border, var(--ds-line-2));
    border-radius: calc(var(--ds-radius-xs) * var(--ds-shape, 1));
    background: var(--ds-kbd-bg, var(--ds-surface));
    color: var(--ds-text-2);
    font: var(--ds-font-code);
  }

  /* Dividers: a hairline across, inset, upright or around a caption. Borders,
     so they survive forced colours. */
  .ds-divider {
    display: block;
    height: 0;
    margin: 0;
    border: 0;
    border-top: 1px solid var(--ds-divider-color, var(--ds-line));
  }

  .ds-divider--inset {
    margin-inline-start: var(--ds-space-4);
  }

  .ds-divider--vertical {
    display: inline-block;
    align-self: stretch;
    width: 0;
    height: auto;
    min-height: 1em;
    border-top: 0;
    border-inline-start: 1px solid var(--ds-divider-color, var(--ds-line));
  }

  /* Upright and inset: it stops short of the row's top and bottom edges. */
  .ds-divider--vertical.ds-divider--inset {
    margin-inline-start: 0;
    margin-block: var(--ds-space-2);
  }

  .ds-divider--label {
    display: flex;
    align-items: center;
    gap: var(--ds-space-3);
    height: auto;
    border-top: 0;
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
  }

  .ds-divider--label::before,
  .ds-divider--label::after {
    content: '';
    flex: 1 1 0;
    border-top: 1px solid var(--ds-divider-color, var(--ds-line));
  }

  /* The caption near one end: a short lead hairline on its side. */
  .ds-divider--label.ds-divider--start::before,
  .ds-divider--label.ds-divider--end::after {
    flex: 0 0 var(--ds-space-4);
  }

  /* Upright around a caption ("or" between two columns): the hairlines
     above and below it. */
  .ds-divider--vertical.ds-divider--label {
    flex-direction: column;
    width: auto;
    border-inline-start: 0;
  }

  .ds-divider--vertical.ds-divider--label::before,
  .ds-divider--vertical.ds-divider--label::after {
    min-height: var(--ds-space-2);
    border-top: 0;
    border-inline-start: 1px solid var(--ds-divider-color, var(--ds-line));
    box-sizing: border-box;
  }

  /* Icons that fill when on: the last element of a fillable glyph is a closed outline. */
  .ds-icon--fillable > :last-child {
    fill: transparent;
    transition: fill var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  :is([aria-pressed="true"], [aria-checked="true"]) .ds-icon--fillable > :last-child,
  .ds-icon--filled > :last-child {
    fill: currentColor;
  }

  /*
   * Touch screens (opt-in, docs/theming.md): every target at least
   * --ds-touch-target, fields at the input role (no zoom on focus in iOS).
   * A component takes it from --ds-target-min (core/options.css), as a
   * minimum over its computed height: setting its base hook here would add
   * the size step on top.
   */
  .ds-touch {
    --ds-input-font: var(--ds-font-input);
  }

  @media (forced-colors: active) {
    .ds-pressable::before {
      display: none;
    }
  }
}

/* ── components/scroller/scroller.css ── */
/*
 * Scroll areas: a strip wider than its panel (months, a row of cards, a
 * wide chart) that scrolls sideways on its own, a column taller than its
 * room that scrolls down, each with a fade at each end that still has
 * content to show, and the place of a "Latest" pill in a log that sticks
 * to its end.
 *
 *   <div class="ds-scroll-x" tabindex="0" role="region" aria-label="Months">
 *     <div>... content wider than the panel ...</div>
 *   </div>
 *   DS.dom.scrollEdges(scroller)   the attribute fallback (below)
 *
 *   <div class="ds-scroll-x ds-scroll-x--reel" tabindex="0" role="region" aria-label="Devices">
 *     <div class="ds-card"> ... </div> <div class="ds-card"> ... </div>
 *   </div>
 *                       a horizontal reel: the children stand in a row,
 *                       --ds-scroll-reel-item wide (the next one peeks in),
 *                       --ds-scroll-reel-gap apart, and the scroll comes to
 *                       rest on the start of one (proximity: never fights a
 *                       scroll that stops between two)
 *
 *   <div class="ds-scroll-y" tabindex="0" role="region" aria-label="Log">
 *     ... content taller than --ds-scroll-max-height ...
 *   </div>
 *   DS.dom.scrollEdges(scroller, { axis: 'block' })   the attribute fallback
 *                       the same on the block axis; its scrollbar keeps its
 *                       room whether it shows or not (scrollbar-gutter), so
 *                       content that grows never reflows sideways
 *
 *   tabindex="0" role="region" aria-label  only when nothing inside can
 *                       take focus: the scroller is then the tab stop that
 *                       arrow keys scroll (WebKit gives a scroller none by
 *                       itself); its ring is inset (it rests at 0 and snaps
 *                       to minus its width) and never masked
 *
 *   <div class="ds-jump"><div class="ds-presence" hidden>
 *     <button class="ds-btn ds-btn--tonal ds-btn--icon" type="button" aria-label="Latest">(arrowDown)</button>
 *   </div></div>
 *                       the last child of a scrolling log: a pill that
 *                       floats --ds-space-4 above the log's bottom edge
 *                       while the log is not at its end (DS.dom.followEnd()
 *                       toggles hidden on the .ds-presence and scrolls to
 *                       the end on a click); the place takes no room
 *
 * The fade: the mask is a gradient whose two ends are the registered
 * (tokens.css) numbers --ds-scroll-edge-start and --ds-scroll-edge-end
 * (0 or 1, also in between) times the fade length, so 0 is no fade. Where scroll
 * timelines exist, ds-scroll-edge-start and ds-scroll-edge-end (motion.css)
 * drive them on the scroller's own scroll(self inline) timeline: the start
 * fade grows while the first --ds-space-8 scroll away, the end fade goes
 * over the last --ds-space-8; a strip that fits has an inactive timeline
 * and fades nowhere. Elsewhere DS.dom.scrollEdges() writes
 * data-ds-overflow-start and data-ds-overflow-end (more to scroll at that
 * end), which set the numbers to 1 over --ds-dur-fast (the first
 * measurement at once: the transition waits for data-ds-edges, which it
 * writes after the first edges, so nothing moves on load); without it the
 * strip shows no fade. The mask leaves the scrollbar strip opaque: its height is
 * --ds-scrollbar-height (written by DS.dom.scrollEdges(); 0px without it).
 * The gradient runs left to right (left-to-right pages only).
 * Focus inside lands outside the fades (scroll-padding).
 *
 * Options: density takes 2px per step off the reel's gap. A scroll area has
 * no height, radius or meaning of its own, so size, shape, tone and touch
 * do not apply; they reach what it holds.
 *
 * The table wrappers of table.css fade on the same two numbers, and the
 * menus (menu.css: shades of their surface) and combobox lists
 * (combobox.css: the same mask) reuse them on the block axis.
 *
 * Hooks: --ds-scroll-fade (the fade length, default --ds-space-8; 0px turns
 * the fades of every scroller off: .ds-scroll-x, .ds-scroll-y, the card
 * table wrappers and the menu edges), --ds-scroll-reel-item
 * (min(80%, 280px)), --ds-scroll-reel-gap (--ds-space-4),
 * --ds-scroll-max-height (none).
 *
 * Runtime property (written by DS.dom.scrollEdges(), read with a 0px
 * fallback): --ds-scrollbar-height, and its block-axis twin
 * --ds-scrollbar-width (read by .ds-scroll-y and the combobox list's mask).
 *
 * Print: the strip shows all of its content, unmasked; the jump pill is
 * hidden.
 *
 * Progressive:
 * - scroll-driven animations (animation-timeline: scroll(), animation-range;
 *   the fades follow the scroll position): without them the
 *   data-ds-overflow-* attributes of DS.dom.scrollEdges() set the fades,
 *   or none show.
 * - scrollbar-color and scrollbar-width (a thin, quiet scrollbar): without
 *   them the platform scrollbar shows.
 * - scrollbar-gutter (.ds-scroll-y keeps the scrollbar's room): without it
 *   content narrows when the scrollbar comes.
 */

@layer ds.components.scroller {
  /* Positioned: absolutely placed content (a .ds-sr label) is clipped by
     the strip instead of widening the page. The block padding is the room
     of the focus rings inside; the mask covers the content box and leaves
     the scrollbar strip opaque. */
  .ds-scroll-x {
    position: relative;
    overflow-x: auto;
    overscroll-behavior-x: contain;
    scrollbar-width: thin;
    scrollbar-color: var(--ds-line-2) transparent;
    padding-block: var(--ds-space-1);
    scroll-padding-inline: var(--ds-scroll-fade, var(--ds-space-8));
    mask-image:
      linear-gradient(to right, transparent, #000 calc(var(--ds-scroll-edge-start) * var(--ds-scroll-fade, var(--ds-space-8))), #000 calc(100% - var(--ds-scroll-edge-end) * var(--ds-scroll-fade, var(--ds-space-8))), transparent),
      linear-gradient(#000, #000);
    mask-size: 100% calc(100% - var(--ds-scrollbar-height, 0px)), 100% var(--ds-scrollbar-height, 0px);
    mask-position: 0 0, 0 100%;
    mask-repeat: no-repeat;
  }

  /* A horizontal reel: the children in a row, each a share of the panel so
     the next one peeks in. The inline padding is the room of their focus
     rings, as the block padding above. */
  .ds-scroll-x--reel {
    display: flex;
    gap: calc(var(--ds-scroll-reel-gap, var(--ds-space-4)) + var(--ds-density, 0) * 2px);
    padding-inline: var(--ds-space-1);
    scroll-snap-type: x proximity;
  }

  .ds-scroll-x--reel > * {
    flex: 0 0 var(--ds-scroll-reel-item, min(80%, 280px));
    min-width: 0;
    scroll-snap-align: start;
  }

  /* The block axis: the same mask turned, its scrollbar strip opaque at the
     inline end. The block padding of .ds-scroll-x is not needed: the rings
     of what scrolls here have the room at its sides, which it pads. */
  .ds-scroll-y {
    position: relative;
    max-height: var(--ds-scroll-max-height, none);
    overflow-y: auto;
    overscroll-behavior-y: contain;
    scrollbar-width: thin;
    scrollbar-color: var(--ds-line-2) transparent;
    scrollbar-gutter: stable;
    padding-inline: var(--ds-space-1);
    scroll-padding-block: var(--ds-scroll-fade, var(--ds-space-8));
    mask-image:
      linear-gradient(to bottom, transparent, #000 calc(var(--ds-scroll-edge-start) * var(--ds-scroll-fade, var(--ds-space-8))), #000 calc(100% - var(--ds-scroll-edge-end) * var(--ds-scroll-fade, var(--ds-space-8))), transparent),
      linear-gradient(#000, #000);
    mask-size: calc(100% - var(--ds-scrollbar-width, 0px)) 100%, var(--ds-scrollbar-width, 0px) 100%;
    mask-position: 0 0, 100% 0;
    mask-repeat: no-repeat;
  }

  /* The fallback: DS.dom.scrollEdges() says which end has more. Where a
     scroll timeline drives the numbers, the animation wins over these.
     The fades glide only once it has measured (data-ds-edges comes after
     the first edges), so a strip shows its first fades still on load. */
  .ds-scroll-x[data-ds-edges],
  .ds-scroll-y[data-ds-edges] {
    transition:
      --ds-scroll-edge-start var(--ds-dur-fast) var(--ds-ease-in-out),
      --ds-scroll-edge-end var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  .ds-scroll-x[data-ds-overflow-start],
  .ds-scroll-y[data-ds-overflow-start] {
    --ds-scroll-edge-start: 1;
  }

  .ds-scroll-x[data-ds-overflow-end],
  .ds-scroll-y[data-ds-overflow-end] {
    --ds-scroll-edge-end: 1;
  }

  /* Scroll-linked: the shorthand first (it resets animation-timeline);
     one timeline for both animations. */
  @supports (animation-timeline: scroll()) {
    .ds-scroll-x {
      animation: ds-scroll-edge-start linear both, ds-scroll-edge-end linear both;
      animation-timeline: scroll(self inline);
      animation-range: 0 var(--ds-space-8), calc(100% - var(--ds-space-8)) 100%;
    }

    .ds-scroll-y {
      animation: ds-scroll-edge-start linear both, ds-scroll-edge-end linear both;
      animation-timeline: scroll(self block);
      animation-range: 0 var(--ds-space-8), calc(100% - var(--ds-space-8)) 100%;
    }
  }

  /* A scroller that is a tab stop: an inset ring, solid from the first
     frame, that snaps from the edge inward; the mask would cut it, so the
     focused strip shows unmasked. */
  .ds-scroll-x[tabindex],
  .ds-scroll-y[tabindex] {
    outline-offset: 0;
    transition: outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-scroll-x[tabindex][data-ds-edges],
  .ds-scroll-y[tabindex][data-ds-edges] {
    transition:
      --ds-scroll-edge-start var(--ds-dur-fast) var(--ds-ease-in-out),
      --ds-scroll-edge-end var(--ds-dur-fast) var(--ds-ease-in-out),
      outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-scroll-x[tabindex]:focus-visible,
  .ds-scroll-y[tabindex]:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: calc(-1 * var(--ds-focus-width));
    mask-image: none;
  }

  /*
   * The place of a "Latest" pill: sticky at the bottom of its log, no room
   * of its own (height 0), so the log's content never moves when the pill
   * comes; only the pill takes the pointer, the place lets clicks through
   * to the log under it. The pill keeps its own height (not stretched to
   * the place's 0) and is lifted by its whole height.
   */
  .ds-jump {
    position: sticky;
    inset-block-end: var(--ds-space-4);
    z-index: var(--ds-z-sticky);
    display: flex;
    align-items: flex-start;
    justify-content: center;
    height: 0;
    overflow: visible;
    pointer-events: none;
  }

  .ds-jump > * {
    pointer-events: auto;
    translate: 0 -100%;
  }

  @media print {
    .ds-scroll-x,
    .ds-scroll-y {
      max-height: none;
      overflow: visible;
      mask-image: none;
    }

    /* On paper a reel is a wrapped row: nothing to scroll to. */
    .ds-scroll-x--reel {
      flex-wrap: wrap;
    }

    .ds-jump {
      display: none;
    }
  }
}

/* ── components/spinner/spinner.css ── */
/*
 * Spinner: the Material 3 arc, the inline loading indicator (busy buttons,
 * chips, status chips, table cells). The arc grows from 10deg to 270deg and
 * shrinks back while its start advances, so the tail chases the head
 * (ds-spinner-arc, --ds-loop-arc), and the whole ring turns once per
 * --ds-loop-spin (ds-spin). One element, painted by a conic gradient on
 * the two registered angles (--ds-spinner-start, --ds-spinner-arc) through
 * a ring mask; no track by default (M3, 2024). Show it only after
 * --ds-delay-loader, so fast loads never flash it. A block of the page
 * that waits (a section, a sheet, the app start) shows the shape loader
 * instead (loader.css).
 *
 * Never put .ds-enter on the spinner itself in static markup: the entrance
 * replaces the arc and the turn while it runs, and the classes stay. Delay
 * a spinner through .ds-loading (it has its own delay), or wrap it:
 *   <span class="ds-enter ds-enter--delayed"><span class="ds-spinner"></span></span>
 * DS.motion.enter(spinner, 'delayed') is fine: the entrance plays once and
 * enter() removes its classes, so the spinner turns again.
 *
 *   .ds-spinner                on surfaces (16px at md)
 *   .ds-spinner--ink           inside buttons and chips: the arc in the
 *                              text colour, on a faint ring of it
 *   .ds-spinner--determinate   circular progress (40px at md, 4px): the share
 *                              (--ds-progress, 0 ... 1) as an arc, a gap,
 *                              then the remaining track in --ds-accent; the
 *                              arc is wavy (--ds-progress-ring-wave) on a
 *                              plain track, and flat while it is short
 *                              (cross-fading between 6% and 11%). It
 *                              never spins, and its value glides on
 *                              --ds-ease-value over --ds-dur-glide, like
 *                              linear progress and DS.motion.countUp():
 *     <span class="ds-spinner ds-spinner--determinate" role="progressbar" aria-label="Upload"
 *           aria-valuemin="0" aria-valuemax="100" aria-valuenow="40" style="--ds-progress: .4"></span>
 *   .ds-spinner--flat          with --determinate: a plain arc, no wave
 *
 * Options (docs/options.md), computed here into --_s:
 *   size      .ds-xs ... .ds-xl on the spinner or any ancestor: 4px per step
 *             (never under 10px), the ring 8px per step (24 ... 56px); the
 *             ring's width follows its size unless the hook sets one
 *   tone      .ds-tone-* on the spinner itself: the arc in --ds-tone, a
 *             determinate track in --ds-tone-container; an inherited tone
 *             never recolours it. A share in a tone needs its word next to it.
 *   density, shape, target-min: not read. A spinner is round and no target;
 *             its size follows the size step alone.
 *
 * Inside .ds-progress a determinate spinner reads the share of its
 * .ds-progress (the property inherits) and lands with its bar on the same
 * frame; progress.css takes its transition away there.
 *
 * Hooks: --ds-spinner-size (16px), --ds-spinner-determinate-size (40px),
 * the md bases; --ds-spinner-color (the arc), --ds-spinner-track (none, or
 * --ds-accent on the determinate ring), --ds-spinner-width (2px; the
 * determinate ring reads --ds-spinner-determinate-width, a tenth of its
 * size). A project that set border-width on a spinner sets
 * --ds-spinner-width instead.
 *
 * The small spinner's faint ring mixes the text colour (color-mix()).
 *
 * Print: the arc and the ring keep their colours (print-color-adjust), so
 * a status chip keeps its glyph and a determinate ring its share.
 */

@layer ds.components.spinner {
  .ds-spinner {
    --_s: max(10px, calc(var(--ds-spinner-size, 16px) + var(--ds-size-step, 0) * 4px));
    display: inline-block;
    width: var(--_s);
    height: var(--_s);
    flex-shrink: 0;
    border: 0;
    border-radius: 50%;
    background: conic-gradient(from var(--ds-spinner-start), var(--ds-spinner-color, var(--ds-primary)) 0 var(--ds-spinner-arc), var(--ds-spinner-track, transparent) 0);
    /* The ring: the inner disc is cut away, half a pixel soft for an even edge. */
    mask-image: radial-gradient(farthest-side, transparent calc(100% - var(--ds-spinner-width, 2px)), #000 calc(100% - var(--ds-spinner-width, 2px) + .5px));
    animation:
      ds-spinner-arc var(--ds-loop-arc) linear infinite,
      ds-spin var(--ds-loop-spin) linear infinite;
  }

  /* The arc and a faint ring in the text colour. */
  .ds-spinner--ink {
    --ds-spinner-color: currentColor;
    --ds-spinner-track: color-mix(in srgb, currentColor 22%, transparent);
  }

  /* A tone from the class on the spinner itself (zero weight, so the
     forced-colours rule below still wins by order). */
  .ds-spinner:where(.ds-tone-neutral, .ds-tone-primary, .ds-tone-info, .ds-tone-success, .ds-tone-warning, .ds-tone-error) {
    --ds-spinner-color: var(--ds-tone);
  }

  /*
   * Circular progress: the element holds the value; ::before paints the
   * track, ::after the arc, each a ring of its own, so the arc can be wavy
   * on a plain track (M3 Expressive). The arc ends at the share; a gap of
   * about 4px of arc (14deg at the ring's radius) separates it from the
   * track on both ends and opens with the first percent, so an empty ring
   * is a whole track and a full one a whole arc (the colour stops clamp
   * past 360deg).
   */
  .ds-spinner--determinate {
    --_s: calc(var(--ds-spinner-determinate-size, 40px) + var(--ds-size-step, 0) * 8px);
    --ds-spinner-width: var(--ds-spinner-determinate-width, calc(var(--_s) / 10));
    position: relative;
    background: none;
    mask-image: none;
    animation: none;
    transition: --ds-progress var(--ds-dur-glide) var(--ds-ease-value);
  }

  .ds-spinner--determinate::before,
  .ds-spinner--determinate::after {
    content: '';
    position: absolute;
    inset: 0;
    border-radius: 50%;
    mask-image: radial-gradient(farthest-side, transparent calc(100% - var(--ds-spinner-width, 2px)), #000 calc(100% - var(--ds-spinner-width, 2px) + .5px));
  }

  .ds-spinner--determinate:where(.ds-tone-neutral, .ds-tone-primary, .ds-tone-info, .ds-tone-success, .ds-tone-warning, .ds-tone-error) {
    --ds-spinner-track: var(--ds-tone-container);
  }

  .ds-spinner--determinate::before {
    background: conic-gradient(
      transparent 0 calc(var(--ds-progress) * 360deg + 14deg * min(1, var(--ds-progress) * 100)),
      var(--ds-spinner-track, var(--ds-accent)) 0 calc(360deg - 14deg * min(1, var(--ds-progress) * 100)),
      transparent 0
    );
  }

  .ds-spinner--determinate::after {
    background: conic-gradient(var(--ds-spinner-color, var(--ds-primary)) 0 calc(var(--ds-progress) * 360deg), transparent 0);
  }

  /* The wavy arc (--ds-progress-ring-wave: 7 waves around a 16.4px radius,
     stretched with the ring) on a plain track at the wave's middle; --flat
     keeps both plain rings at the edge. A short arc would be a loose tick or hook of the wave, so
     up to 6% the arc is flat (a layer of the track's ring, at the wave's
     middle) and the wavy one cross-fades in by 11%, on the gliding share
     (--ds-progress-wave-start, --ds-progress-wave-ramp). */
  .ds-spinner--determinate:not(.ds-spinner--flat)::before {
    inset: calc(var(--_s) * .04);
    background:
      conic-gradient(color-mix(in srgb, var(--ds-spinner-color, var(--ds-primary)) clamp(0%, calc(1 - var(--ds-progress) / var(--ds-progress-wave-ramp) + var(--ds-progress-wave-start) / var(--ds-progress-wave-ramp)) * 100%, 100%), transparent) 0 calc(var(--ds-progress) * 360deg), transparent 0),
      conic-gradient(
        transparent 0 calc(var(--ds-progress) * 360deg + 14deg * min(1, var(--ds-progress) * 100)),
        var(--ds-spinner-track, var(--ds-accent)) 0 calc(360deg - 14deg * min(1, var(--ds-progress) * 100)),
        transparent 0
      );
  }

  .ds-spinner--determinate:not(.ds-spinner--flat)::after {
    opacity: calc(var(--ds-progress) / var(--ds-progress-wave-ramp) - var(--ds-progress-wave-start) / var(--ds-progress-wave-ramp));
    mask-image: var(--ds-progress-ring-wave);
    mask-size: 100% 100%;
    mask-repeat: no-repeat;
  }

  /* Forced colors drop background images: the arc and its track paint in
     system colours, the ring mask stays. */
  @media (forced-colors: active) {
    .ds-spinner {
      forced-color-adjust: none;
      --ds-spinner-color: Highlight;
      --ds-spinner-track: GrayText;
    }
  }

  /* Print: the arc and the ring are backgrounds, which printing drops by
     default; a running status keeps its glyph, a ring its share. */
  @media print {
    .ds-spinner {
      -webkit-print-color-adjust: exact;
      print-color-adjust: exact;
    }
  }
}

/* ── components/loader/loader.css ── */
/*
 * Shape loader: the Material 3 Expressive loading indicator and the block
 * loader of the system (.ds-boot, .ds-loading). A shape morphs through the
 * seven M3 shapes (soft burst, cookie-9, pentagon, pill, sunny, cookie-4,
 * oval; ds-loader-morph), every step landing on the spatial spring, while
 * it turns once per round (ds-loader-turn, linear); one round takes
 * --ds-loop-loader. Like every loader it fades in only after
 * --ds-delay-loader, so fast loads never show it.
 *
 *   <span class="ds-loader" aria-hidden="true"></span>
 *   <div class="ds-boot" role="status"><span class="ds-loader" aria-hidden="true"></span>Starting ...</div>
 *   <div class="ds-loading" role="status"><span class="ds-loader ds-sm" aria-hidden="true"></span>Loading ...</div>
 *
 *   .ds-loader              48px container at md, the shape 38/48 of it
 *   .ds-loader--contained   the shape on a --ds-accent disc
 *
 * Options (docs/options.md), computed here into --_s:
 *   size      .ds-xs ... .ds-xl on the loader or any ancestor: 24px per step
 *             (16, 24, 48, 72, 96px), so .ds-sm is the loading line's 24px
 *   density, shape, target-min, tone: not read. It morphs through its own
 *             shapes, it is no target and it says nothing but "wait".
 *
 * Hooks: --ds-loader-size (48px, the md base), --ds-loader-color
 * (--ds-primary).
 *
 * The loader is decoration: aria-hidden, and the surrounding role="status"
 * carries the text. Inside .ds-boot, .ds-loading and .ds-skeleton the
 * container waits its own delay, so loading.css drops the loader's fade
 * there (the delays never stack). The loops run on ::before, so .ds-enter on the
 * loader itself replaces only its fade.
 *
 * At most a few per view: the polygon morph repaints every frame. Inline
 * spots (buttons, chips, status chips, table cells) keep the arc spinner
 * (spinner.css).
 *
 * Print: the shape is not printed (its label is).
 */

@layer ds.components.loader {
  .ds-loader {
    --_s: max(16px, calc(var(--ds-loader-size, 48px) + var(--ds-size-step, 0) * 24px));
    display: inline-grid;
    place-items: center;
    flex-shrink: 0;
    width: var(--_s);
    height: var(--_s);
    border-radius: 50%;
    animation: ds-fade-in var(--ds-dur-medium) var(--ds-ease-in-out) var(--ds-delay-loader) backwards;
  }

  /* The shape: 64-vertex polygons, so every morph is a straight blend. */
  .ds-loader::before {
    content: '';
    width: calc(100% * 38 / 48);
    height: calc(100% * 38 / 48);
    background: var(--ds-loader-color, var(--ds-primary));
    animation:
      ds-loader-morph var(--ds-loop-loader) var(--ds-ease-spatial) infinite,
      ds-loader-turn var(--ds-loop-loader) linear infinite;
  }

  .ds-loader--contained {
    background: var(--ds-accent);
  }

  /* Forced colors drop the fills: the shape in the system highlight, the
     disc of the contained loader as an edge. */
  @media (forced-colors: active) {
    .ds-loader {
      forced-color-adjust: none;
    }

    .ds-loader::before {
      background: Highlight;
    }

    .ds-loader--contained {
      background: Canvas;
      outline: 1px solid CanvasText;
    }
  }

  /* Print: a frozen shape says nothing on paper; the label stays. */
  @media print {
    .ds-loader {
      display: none;
    }
  }
}

/* ── components/indicator/indicator.css ── */
/*
 * Sliding indicator (js/indicator.js). The component that uses it gives it
 * a look (background, and its corners through --ds-indicator-radius); this
 * file only moves it.
 *
 * The pill is drawn by clip-path on a box, never by animating width/height:
 * the box (--ds-indicator-x/-y/-w/-h, moved by translate) jumps, the four
 * edges of the clip (--ds-indicator-t/-r/-b/-l, registered lengths) glide.
 * At rest the box is the active item and the clip insets are 0px: a plain
 * rounded pill. A glide makes the box the union of the pill it leaves and
 * the item it goes to, widened on the travel axis by an overshoot margin
 * (data-glide), and moves the edges from the one to the other on the
 * spatial spring. The leading edge leads and the trailing edge follows
 * --ds-indicator-lag later (data-dir), so the pill stretches toward its
 * target; the leading edge passes it by at most 5 % of the travel and
 * settles. The trailing edge runs on --ds-ease-in-out, which never
 * overshoots: the pill never gets shorter than its item and never slides
 * past it (--ds-indicator-ease-t/-r/-b/-l, the curve of each edge, are
 * set by the data-dir rules; component internal). The travel
 * time grows with the distance (from --ds-dur-medium, capped at
 * --ds-dur-slow): js writes it as --ds-indicator-dur on the track, where
 * the labels of the items read it too. The radius springs like a pill's
 * after a press morph, also while the pill rests (the drawer squares the
 * pill under a pressed active item).
 *
 *   <nav class="ds-has-indicator">
 *     <span class="ds-indicator ..." aria-hidden="true" data-ds-keep></span> ...items...
 *   </nav>
 *   (DS.indicator.create(), or data-ds-indicator and DS.init(), inserts the
 *   span and the class.)
 *
 * State on the span, written by js:
 *   data-glide               a glide runs: the box is the union, no own radius
 *   data-dir                 left, right, up or down: the travel; the edge
 *                            on the other side trails
 *   data-empty               no active item: faded out, contracted to the
 *                            centre (it grows from there when one appears)
 *   .ds-indicator--instant   placed without a glide (public)
 *
 * Property of the indicator's class:
 *   --ds-indicator-radius    the pill's corners (a component class sets it;
 *                            js copies a plain border-radius of a project
 *                            class into it at rest). It does not inherit, so
 *                            it is set on that class, never on .ds-theme
 *
 * Motion hook (themes never set it):
 *   --ds-indicator-lag       how long the trailing edge waits (default
 *                            --ds-dur-micro)
 *
 * Options (src/core/options.css): the pill has no size of its own. Size,
 * density and .ds-touch change the items, and js places the pill on what
 * it measures (a resize at once, without a glide). The shape comes with its
 * radius: a component's class computes --ds-indicator-radius with
 * --ds-shape in its own rule, and js copies a project class's plain
 * border-radius with --ds-shape as a live factor; this file never
 * multiplies. No tone: a pill shows a choice, no status.
 *
 * Forced colours: no pill, for any class; the items show the selection by
 * the system colours of their own component.
 */

/* The edges and the radius transition as lengths. */
@property --ds-indicator-t {
  syntax: '<length>';
  inherits: false;
  initial-value: 0px;
}

@property --ds-indicator-r {
  syntax: '<length>';
  inherits: false;
  initial-value: 0px;
}

@property --ds-indicator-b {
  syntax: '<length>';
  inherits: false;
  initial-value: 0px;
}

@property --ds-indicator-l {
  syntax: '<length>';
  inherits: false;
  initial-value: 0px;
}

@property --ds-indicator-radius {
  syntax: '<length>';
  inherits: false;
  initial-value: 0px;
}

@layer ds.components.indicator {
  .ds-has-indicator {
    position: relative;
    isolation: isolate;
  }

  /* Box and clip; the order of the transition lists (edges, radius,
     opacity) is the one every rule below keeps. */
  /* Physical on purpose (D9): DS.indicator writes viewport-measured x and
     y, from the top left corner. */
  .ds-indicator {
    position: absolute;
    top: 0;
    left: 0;
    z-index: -1;
    width: var(--ds-indicator-w, 0);
    height: var(--ds-indicator-h, 0);
    translate: var(--ds-indicator-x, 0) var(--ds-indicator-y, 0);
    /* max(): a radius going to 0 passes it on the spring, and a negative one
       makes the whole clip-path invalid, so the union would paint. */
    clip-path: inset(var(--ds-indicator-t) var(--ds-indicator-r) var(--ds-indicator-b) var(--ds-indicator-l) round max(0px, var(--ds-indicator-radius)));
    pointer-events: none;
    transition-property: --ds-indicator-t, --ds-indicator-r, --ds-indicator-b, --ds-indicator-l, --ds-indicator-radius, opacity;
    transition-duration:
      var(--ds-indicator-dur, var(--ds-dur-medium)),
      var(--ds-indicator-dur, var(--ds-dur-medium)),
      var(--ds-indicator-dur, var(--ds-dur-medium)),
      var(--ds-indicator-dur, var(--ds-dur-medium)),
      var(--ds-dur-medium),
      var(--ds-dur-fast);
    transition-timing-function:
      var(--ds-indicator-ease-t, var(--ds-ease-spatial)),
      var(--ds-indicator-ease-r, var(--ds-ease-spatial)),
      var(--ds-indicator-ease-b, var(--ds-ease-spatial)),
      var(--ds-indicator-ease-l, var(--ds-ease-spatial)),
      var(--ds-ease-spatial),
      var(--ds-ease-in-out);
    transition-delay: 0s;
  }

  /* The trailing edge follows: the edge opposite the travel waits, then
     closes in without overshoot (on the spring it would also pass its
     target, and near the end of a long jump the pill would be shorter than
     the item and slide off it). The curve goes through a variable, so a
     rule that restates the curve list (the drawer's pressed pill) keeps it. */
  .ds-indicator[data-dir="right"] {
    --ds-indicator-ease-l: var(--ds-ease-in-out);
    transition-delay: 0s, 0s, 0s, var(--ds-indicator-lag, var(--ds-dur-micro)), 0s, 0s;
  }

  .ds-indicator[data-dir="left"] {
    --ds-indicator-ease-r: var(--ds-ease-in-out);
    transition-delay: 0s, var(--ds-indicator-lag, var(--ds-dur-micro)), 0s, 0s, 0s, 0s;
  }

  .ds-indicator[data-dir="down"] {
    --ds-indicator-ease-t: var(--ds-ease-in-out);
    transition-delay: var(--ds-indicator-lag, var(--ds-dur-micro)), 0s, 0s, 0s, 0s, 0s;
  }

  .ds-indicator[data-dir="up"] {
    --ds-indicator-ease-b: var(--ds-ease-in-out);
    transition-delay: 0s, 0s, var(--ds-indicator-lag, var(--ds-dur-micro)), 0s, 0s, 0s;
  }

  /* While the box is the union of two items, a radius of its own would cut
     into the painted pill (js also sets it inline: unlayered project CSS
     beats this rule). */
  .ds-has-indicator > .ds-indicator[data-glide] {
    border-radius: 0;
  }

  /* Placed without a glide: the edges jump. A radius change (a press morph)
     still springs, and a fade in progress continues. */
  .ds-indicator--instant {
    transition-property: --ds-indicator-radius, opacity;
    transition-duration: var(--ds-dur-medium), var(--ds-dur-fast);
    transition-timing-function: var(--ds-ease-spatial), var(--ds-ease-in-out);
    transition-delay: 0s;
  }

  .ds-indicator[data-empty] {
    opacity: 0;
  }

  /* The active item went away: the pill contracts to its centre, quickly
     and accelerating, while it fades. */
  .ds-indicator[data-glide][data-empty]:not(.ds-indicator--instant) {
    transition-duration: var(--ds-dur-fast), var(--ds-dur-fast), var(--ds-dur-fast), var(--ds-dur-fast), var(--ds-dur-medium), var(--ds-dur-fast);
    transition-timing-function: var(--ds-ease-in), var(--ds-ease-in), var(--ds-ease-in), var(--ds-ease-in), var(--ds-ease-spatial), var(--ds-ease-in);
  }

  @media (forced-colors: active) {
    .ds-indicator {
      display: none;
    }
  }
}

/* ── components/button/button.css ── */
/*
 * Button: one component for every button. Every action is a pill at the
 * default shape (D11): its rest radius is min(radius, half its height)
 * times --ds-shape, so a square theme or region (.ds-shape-square) has
 * square buttons and the default stays the pill.
 *
 * Variants (the look):
 *   .ds-btn                  outlined (secondary action)
 *   .ds-btn--outlined        the same, named explicitly
 *   .ds-btn--filled          the main action of a form or dialog; one per
 *                            area
 *   .ds-btn--tonal           the tint: a softer main action
 *   .ds-btn--elevated        a raised surface with the action ink (level 1,
 *                            level 2 on hover): an action on an image or
 *                            a busy backdrop
 *   .ds-btn--text            no frame (dialog secondary actions, inline actions)
 *   .ds-btn--quiet           muted until hovered (toolbars, headers)
 *   .ds-btn--ghost           no frame, the ink of its surroundings (on a
 *                            tinted, inverse or status surface, where the
 *                            action ink would not read)
 *   .ds-btn--icon            round, icon only (needs aria-label)
 *   .ds-btn--disc            hover: a solid disc fades in behind the icon
 *   icon buttons             .ds-btn--icon with a look: standard
 *                            (--quiet: no frame, the quieter ink),
 *                            --filled, --tonal or --outlined; an
 *                            aria-label and a data-tip with the same
 *                            words; each also a toggle (aria-pressed, a
 *                            .ds-icon--fillable glyph fills while on)
 *   .ds-btn--block           full width (a form's one action on a phone,
 *                            a sign-in card)
 *   [aria-pressed="true"]    a toggle that is on: the tint, plus the
 *                            attribute, so it is not told by colour alone;
 *                            in a track with a sliding indicator
 *                            (.ds-has-indicator) the pill paints it: the
 *                            button stays clear and its label changes
 *                            colour on the pill's timing; with
 *                            aria-disabled="true" a choice made once and
 *                            locked: it keeps its on look, no layer; on
 *                            --filled or --tonal the neutral container
 *                            while off (aria-pressed="false") and the
 *                            variant's own fill while on (Material 3
 *                            toggles: off and on differ by the fill)
 *   .ds-btn--disclosure      a button that opens a panel; while
 *                            aria-expanded="true" it takes the tint like a
 *                            pressed toggle (so does a button with
 *                            aria-haspopup="dialog"; menu triggers do not)
 *   .ds-btn--adaptive        a labelled button whose label folds away in a
 *                            narrow content panel (600px); anywhere else,
 *                            sheets and dialogs included, in a window of
 *                            600px or less; it leaves a round quiet icon
 *                            button that keeps its name:
 *     <button class="ds-btn ds-btn--adaptive" type="button" data-tip="Export">(download 16)<span class="ds-btn__label">Export</span></button>
 *
 * Options (src/core/options.css, docs/options.md), on the button or any
 * ancestor; each is computed here, in the button's own rule:
 *   size      .ds-xs ... .ds-xl: 8px of height per step (24, 32, 40, 48,
 *             56px), 4px of side padding per step, the type role of the
 *             size (--ds-size-font); an icon button 8px per step too
 *   density   .ds-density-*: 4px of height per step (40, 36, 32, 28px);
 *             not the side padding, and not icon buttons (a target with no
 *             label to make room for: make it smaller with a size)
 *   shape     .ds-shape-*: multiplies the rest and the pressed radius
 *   touch     .ds-touch: at least --ds-touch-target (48px) high, an icon
 *             button as wide; touch wins over size and density
 *   tone      .ds-tone-error on .ds-btn--filled only: the filled error
 *             button of a destructive confirmation (the confirm dialog
 *             and the type-to-confirm pattern, D10); pages keep no red
 *             buttons, and no other tone colours a button
 *
 * Link button: .ds-link-btn, a button that reads like a link (an action
 * inside text or a table cell, the subject that opens a detail): the link
 * colour and underline, no padding, border or fill. An inline link: no
 * ripple, no morph; a press darkens its underline (the press feedback on
 * touch screens); keyboard focus a ring solid from the first frame that
 * snaps from offset + width to the offset (outline-offset, --ds-dur-fast).
 *
 *   <button class="ds-link-btn" type="button">LAPTOP-0042</button>
 *
 * Quiet links: .ds-link--quiet (a link) and .ds-link-btn--quiet (with
 * .ds-link-btn): the quieter ink and a hairline underline in --ds-line-2,
 * the link colour and its hover underline on hover; still underlined.
 *
 * Faces: a button whose label changes while it works (DS.motion.busy())
 * stacks every label it can show in one grid cell, so it is as wide as the
 * widest and never changes width; the label stays while it loads:
 *
 *   <button class="ds-btn ds-btn--filled" type="button">
 *     <span class="ds-btn__faces">
 *       <span class="ds-btn__face">Save</span>
 *       <span class="ds-btn__face ds-btn__face--busy" aria-hidden="true"><span class="ds-spinner ds-spinner--ink ds-sm"></span>Saving</span>
 *       <span class="ds-btn__face ds-btn__face--done" aria-hidden="true">(check 16)Saved</span>
 *       <span class="ds-btn__face ds-btn__face--failed" aria-hidden="true">(alertCircle 16)Not saved</span>
 *     </span>
 *   </button>
 *
 *   [aria-busy="true"]       blocked at once for pointer, keyboard and form
 *                            submission (DS.motion.guard(), which busy()
 *                            and DS.ripple.attach() install); the busy
 *                            face shows only after --ds-delay-loader (a
 *                            fast save shows nothing)
 *   .ds-btn--done            the success face, for --ds-hold-success; its
 *                            check (pathLength="1") draws itself (ds-draw);
 *                            blocked like a busy button
 *   .ds-btn--failed          the error face (an icon and a word), for
 *                            --ds-hold-status after the work failed; not
 *                            blocked: a press tries again
 *
 * The faces roll: a face that leaves rises and fades (--ds-dur-instant,
 * accelerating), the next one rises in from below (--ds-dur-fast); back to
 * rest they roll the other way. Announcing the result (aria-live) stays the
 * page's job.
 *
 * Hover and press lay the content colour over the button at the state-layer
 * opacities (::before), so one rule works on every fill and every palette.
 * Hover never moves anything, and nothing scales on press: the press is the
 * layer (in --ds-dur-micro), the ripple (js/ripple.js) and the shape, which
 * turns squarer (--ds-radius-action-pressed times --ds-shape, in
 * --ds-dur-micro) and springs back on release (--ds-ease-spatial,
 * --ds-dur-medium). The rest radius is never 9999px but at most half the
 * height, so the morph interpolates over its whole run; a pressed radius is
 * never rounder than the rest radius. Disabled, aria-disabled, busy and
 * done buttons neither morph nor show a press layer.
 *
 * Focus: the ring is solid from the first frame and snaps from
 * offset + width to the offset (outline-offset, --ds-dur-fast), with the
 * focus layer (--ds-state-focus) under it; a press stays on top of it.
 *
 * The look comes from --ds-btn-* hooks. A theme may set them on .ds-theme
 * to tune every button; variants set them on the element. Nothing here
 * hard-codes a colour. --ds-btn-height and the padding are the base values
 * (size md, comfortable density) the options apply to;
 * --ds-btn-height-exact fixes the height, ignoring size and density (never
 * the touch minimum). Hooks: -height, -height-exact, -padding-x,
 * -padding-start, -radius, -radius-pressed, -font, -bg, -color, -border,
 * -shadow, -state (layer colour), -state-opacity, -state-focus-opacity,
 * -state-pressed-opacity, -hover-color, -hover-border, -hover-shadow,
 * -hover-decoration, -icon-size, -quiet-color, -disabled-bg, -disabled-border. The computed values
 * (--_h, --_box, --_half, --_radius, --_pad) are private: never set them.
 *
 * Forced colours: a pressed toggle and an open disclosure button take the
 * system highlight (Highlight / HighlightText, a focused one a CanvasText
 * ring), an aria-disabled button GrayText (a locked choice keeps
 * Highlight).
 *
 * Hooks set on the element by a variant (--ds-btn-padding-start before a
 * leading icon, --ds-btn-quiet-color in the top bar) win over a theme
 * value; change them per element.
 */

@layer ds.components.button {
  .ds-btn {
    /* The options, computed here (docs/options.md). The height: the hook
       (size md, comfortable) plus 8px per size step and 4px per density
       step, unless an exact height is set. */
    --_h: var(--ds-btn-height-exact, calc(var(--ds-btn-height, 40px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px));
    /* What it measures: never below the touch minimum (.ds-touch). */
    --_box: max(var(--ds-target-min, 0px), var(--_h));
    /* Half the box: the largest radius a pill can show. A radius of 9999px
       would interpolate almost all of its way off screen and snap in the
       last frame of the morph. */
    --_half: calc(var(--_box) / 2);
    /* The rest radius: the pill (at most half the box) times the shape, so
       a square shape has square corners and the default keeps the pill. */
    --_radius: min(calc(min(var(--ds-btn-radius, var(--ds-radius-action)), var(--_half)) * var(--ds-shape, 1)), var(--_half));
    /* Side padding: 4px per size step; density leaves it alone. */
    --_pad: calc(var(--ds-btn-padding-x, var(--ds-space-4)) + var(--ds-size-step, 0) * 4px);
    position: relative;
    /* The state layer (z-index -1) stays above the fill, below the label. */
    isolation: isolate;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: var(--ds-space-2);
    min-height: var(--_box);
    padding-block: 0;
    padding-inline: var(--ds-btn-padding-start, var(--_pad)) var(--_pad);
    border: 1px solid var(--ds-btn-border, var(--ds-line-2));
    border-radius: var(--_radius);
    background: var(--ds-btn-bg, transparent);
    color: var(--ds-btn-color, var(--ds-action-ink));
    box-shadow: var(--ds-btn-shadow, none);
    font: var(--ds-btn-font, var(--ds-size-font, var(--ds-font-label)));
    letter-spacing: 0;
    text-transform: none;
    white-space: nowrap;
    text-decoration: none;
    cursor: pointer;
    -webkit-tap-highlight-color: transparent;
    /* The ring rests (invisible) one width further out and snaps in. */
    outline-offset: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    transition:
      border-color var(--ds-dur-fast) var(--ds-ease-in-out),
      background-color var(--ds-dur-fast) var(--ds-ease-in-out),
      color var(--ds-dur-fast) var(--ds-ease-in-out),
      box-shadow var(--ds-dur-fast) var(--ds-ease-in-out),
      opacity var(--ds-dur-fast) var(--ds-ease-in-out),
      border-radius var(--ds-dur-medium) var(--ds-ease-spatial),
      outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  /* State layer */
  .ds-btn::before {
    content: '';
    position: absolute;
    inset: 0;
    z-index: -1;
    border-radius: inherit;
    background: var(--ds-btn-state, currentColor);
    opacity: 0;
    pointer-events: none;
    transition: opacity var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  /* Touch devices show no hover; a press shows on any device (below). */
  @media (hover: hover) {
    .ds-btn:hover {
      border-color: var(--ds-btn-hover-border, var(--ds-btn-border, var(--ds-line-2)));
      color: var(--ds-btn-hover-color, var(--ds-btn-color, var(--ds-action-ink)));
      box-shadow: var(--ds-btn-hover-shadow, var(--ds-btn-shadow, none));
      text-decoration: var(--ds-btn-hover-decoration, none);
      /* After the shorthand, which resets them: the link underline geometry. */
      text-decoration-thickness: var(--ds-link-underline-thickness);
      text-underline-offset: var(--ds-link-underline-offset);
    }

    .ds-btn:hover::before {
      opacity: var(--ds-btn-state-opacity, var(--ds-state-hover));
    }
  }

  /* Keyboard focus: the layer appears with the ring and fades out on blur
     (the rest transition). After hover, before press: a press stays on top. */
  .ds-btn:focus-visible::before {
    opacity: var(--ds-btn-state-focus-opacity, var(--ds-state-focus));
    transition-duration: 0s;
  }

  /* Press-in in --ds-dur-micro. .ds-pressed (js/ripple.js) holds the press
     for at least --ds-dur-instant, so a quick click shows it whole. */
  .ds-btn:active::before,
  .ds-btn.ds-pressed::before {
    opacity: var(--ds-btn-state-pressed-opacity, var(--ds-state-pressed));
    transition-duration: var(--ds-dur-micro);
  }

  /* Shape morph: squarer while pressed (the pressed role times the shape,
     never rounder than at rest, so a square shape stays square), in
     --ds-dur-micro; the rest transition springs it back on release. The
     state layer follows (inherit). */
  .ds-btn:active:not(:disabled, [aria-disabled="true"], [aria-busy="true"], .ds-btn--done),
  .ds-btn.ds-pressed:not(:disabled, [aria-disabled="true"], [aria-busy="true"], .ds-btn--done) {
    border-radius: min(calc(var(--ds-btn-radius-pressed, var(--ds-radius-action-pressed)) * var(--ds-shape, 1)), var(--_radius));
    transition:
      border-color var(--ds-dur-fast) var(--ds-ease-in-out),
      background-color var(--ds-dur-fast) var(--ds-ease-in-out),
      color var(--ds-dur-fast) var(--ds-ease-in-out),
      box-shadow var(--ds-dur-fast) var(--ds-ease-in-out),
      opacity var(--ds-dur-fast) var(--ds-ease-in-out),
      border-radius var(--ds-dur-micro) var(--ds-ease-out),
      outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  /* A leading icon sits closer to the edge (Material 3: 12px instead of 16px
     at md, 4px more per larger size, never more than the end padding),
     also the icon of the first face of a button with faces. */
  .ds-btn:is(:has(> svg:first-child), :has(> .ds-btn__faces:first-child > .ds-btn__face:first-child > svg:first-child)) {
    --ds-btn-padding-start: min(var(--_pad), calc(var(--ds-space-3) + max(var(--ds-size-step, 0), 0) * 4px));
  }

  .ds-btn:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: var(--ds-focus-offset);
  }

  .ds-btn:disabled,
  .ds-btn[aria-busy="true"],
  .ds-btn--done {
    cursor: default;
    pointer-events: none;
  }

  /* aria-disabled without aria-busy: blocked but still focusable and
     hoverable, so a tooltip can say why (the page's script ignores its
     clicks). No state layer and no hover elevation. */
  .ds-btn[aria-disabled="true"]:not([aria-busy="true"]) {
    cursor: not-allowed;
    box-shadow: none;
    text-decoration: none;
  }

  @media (hover: hover) {
    .ds-btn[aria-disabled="true"]:hover::before {
      opacity: 0;
    }
  }

  /* Blocked buttons show no press (a key still makes them :active). They
     keep the focus layer: an aria-disabled button stays focusable for its
     tooltip. */
  .ds-btn:is([aria-disabled="true"], [aria-busy="true"], .ds-btn--done):is(:active, .ds-pressed)::before {
    opacity: 0;
  }

  .ds-btn:is([aria-disabled="true"], [aria-busy="true"], .ds-btn--done):focus-visible::before {
    opacity: var(--ds-btn-state-focus-opacity, var(--ds-state-focus));
  }

  /*
   * Disabled: the neutral Material look by default (--ds-disabled-fill for
   * container and outline, --ds-disabled-ink for the label, full opacity). A
   * theme may dim the whole button instead (--ds-disabled-opacity, see
   * tokens.css). A busy button (aria-busy) is blocked but keeps its colour.
   * Colours and opacity fade on --ds-dur-fast, like every control.
   */
  .ds-btn:disabled,
  .ds-btn[aria-disabled="true"]:not([aria-busy="true"]) {
    box-shadow: none;
    opacity: var(--ds-disabled-opacity, var(--ds-state-disabled));
    color: var(--ds-disabled-ink, var(--ds-btn-color, var(--ds-action-ink)));
    background: var(--ds-btn-disabled-bg, var(--ds-btn-bg, transparent));
    border-color: var(--ds-btn-disabled-border, var(--ds-disabled-fill, var(--ds-btn-border, var(--ds-line-2))));
  }

  /* Busy: blocked, but in full colour. Nothing changes on a fast response;
     after the loader delay a spinner and the label say it is working (the
     dimmed disabled look would only flash). */
  .ds-btn[aria-busy="true"] {
    opacity: 1;
  }

  /* Faces: every label of the button in one grid cell, so the widest sets
     the width and nothing jumps when they change. */
  .ds-btn__faces {
    display: inline-grid;
    gap: inherit;
  }

  /* The face that is shown; it enters with a fade on the standard curve and
     rises in, decelerating. */
  .ds-btn__face {
    grid-area: 1 / 1;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: inherit;
    transition:
      opacity var(--ds-dur-fast) var(--ds-ease-in-out),
      translate var(--ds-dur-fast) var(--ds-ease-out);
  }

  /* Faces not shown wait below (the ones still to come) or above (the ones
     before the current face), so the leaving face rises out and the next
     one rises in; back to rest they roll down. Leaving accelerates in
     --ds-dur-instant. */
  .ds-btn__face--busy,
  .ds-btn__face--done,
  .ds-btn__face--failed {
    opacity: 0;
    translate: 0 var(--ds-distance-sm);
    transition:
      opacity var(--ds-dur-instant) var(--ds-ease-in),
      translate var(--ds-dur-instant) var(--ds-ease-in);
  }

  /* Busy: the label leaves and the spinner face comes only after the loader
     delay, so a fast save changes nothing. */
  .ds-btn[aria-busy="true"] .ds-btn__face:not(.ds-btn__face--busy, .ds-btn__face--done, .ds-btn__face--failed) {
    opacity: 0;
    translate: 0 calc(-1 * var(--ds-distance-sm));
    transition:
      opacity var(--ds-dur-instant) var(--ds-ease-in) var(--ds-delay-loader),
      translate var(--ds-dur-instant) var(--ds-ease-in) var(--ds-delay-loader);
  }

  .ds-btn[aria-busy="true"] .ds-btn__face--busy {
    opacity: 1;
    translate: none;
    transition:
      opacity var(--ds-dur-fast) var(--ds-ease-in-out) var(--ds-delay-loader),
      translate var(--ds-dur-fast) var(--ds-ease-out) var(--ds-delay-loader);
  }

  /* The hidden busy face keeps its spinner still: no endless loop per
     button at rest. Paused, not removed, so the arc stays where it is while
     the face fades out. */
  .ds-btn:not([aria-busy="true"]) .ds-btn__face--busy .ds-spinner {
    animation-play-state: paused;
  }

  /* Done: the success face, its check drawing itself. */
  .ds-btn--done:not([aria-busy="true"]) .ds-btn__face:not(.ds-btn__face--done) {
    opacity: 0;
    translate: 0 calc(-1 * var(--ds-distance-sm));
    transition:
      opacity var(--ds-dur-instant) var(--ds-ease-in),
      translate var(--ds-dur-instant) var(--ds-ease-in);
  }

  .ds-btn--done:not([aria-busy="true"]) .ds-btn__face--done {
    opacity: 1;
    translate: none;
    transition:
      opacity var(--ds-dur-fast) var(--ds-ease-in-out),
      translate var(--ds-dur-fast) var(--ds-ease-out);
  }

  /* Failed: the error face, an icon and a word (never the colour alone);
     the button keeps its colours and takes a press again at once. */
  .ds-btn--failed:not([aria-busy="true"]) .ds-btn__face:not(.ds-btn__face--failed) {
    opacity: 0;
    translate: 0 calc(-1 * var(--ds-distance-sm));
    transition:
      opacity var(--ds-dur-instant) var(--ds-ease-in),
      translate var(--ds-dur-instant) var(--ds-ease-in);
  }

  .ds-btn--failed:not([aria-busy="true"]) .ds-btn__face--failed {
    opacity: 1;
    translate: none;
    transition:
      opacity var(--ds-dur-fast) var(--ds-ease-in-out),
      translate var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-btn__face--done [pathLength] {
    stroke-dasharray: 1;
  }

  /* The check draws on its <svg>; the pathLength="1" path inherits the
     stroke (Chromium can miss a class change above a [pathLength] rule). */
  .ds-btn--done:not([aria-busy="true"]) .ds-btn__face--done > svg {
    animation: ds-draw var(--ds-dur-medium) var(--ds-ease-out) var(--ds-dur-micro) backwards;
  }

  .ds-btn svg {
    flex-shrink: 0;
  }

  /* Filled. Level 1 on hover where the theme has elevation. */
  .ds-btn--filled {
    --ds-btn-border: var(--ds-primary);
    --ds-btn-bg: var(--ds-primary);
    --ds-btn-color: var(--ds-on-primary);
    --ds-btn-hover-shadow: var(--ds-elev-hover);
    --ds-btn-disabled-bg: var(--ds-disabled-fill, var(--ds-btn-bg));
    --ds-btn-disabled-border: var(--ds-disabled-fill, var(--ds-btn-border));
  }

  /* The one red button (D10): a filled button in the error tone confirms a
     destructive action in the confirm dialog or the type-to-confirm
     pattern, its label naming the consequence ("Delete 3 devices"). It
     reads the tone the class sets on the button itself, never an
     inherited one: a filled button inside an error alert stays filled. */
  .ds-btn--filled.ds-tone-error {
    --ds-btn-border: var(--ds-tone, var(--ds-error));
    --ds-btn-bg: var(--ds-tone, var(--ds-error));
    --ds-btn-color: var(--ds-on-tone, var(--ds-on-error));
  }

  .ds-btn--tonal {
    --ds-btn-border: var(--ds-accent);
    --ds-btn-bg: var(--ds-accent);
    --ds-btn-color: var(--ds-on-accent);
    --ds-btn-disabled-bg: var(--ds-disabled-fill, var(--ds-btn-bg));
    --ds-btn-disabled-border: var(--ds-disabled-fill, var(--ds-btn-border));
  }

  .ds-btn--outlined {
    --ds-btn-border: var(--ds-line-2);
    --ds-btn-bg: transparent;
    --ds-btn-color: var(--ds-action-ink);
  }

  /* Elevated: a raised surface instead of an outline; level 2 on hover. */
  .ds-btn--elevated {
    --ds-btn-border: transparent;
    --ds-btn-bg: var(--ds-surface-low);
    --ds-btn-color: var(--ds-action-ink);
    --ds-btn-shadow: var(--ds-elev-1);
    --ds-btn-hover-shadow: var(--ds-elev-2);
    --ds-btn-disabled-bg: var(--ds-disabled-fill, var(--ds-btn-bg));
    --ds-btn-disabled-border: transparent;
  }

  .ds-btn--text {
    --ds-btn-border: transparent;
    --ds-btn-bg: transparent;
    --ds-btn-color: var(--ds-action-ink);
    --ds-btn-padding-x: var(--ds-space-3);
    --ds-btn-disabled-border: transparent;
  }

  .ds-btn--quiet {
    --ds-btn-border: transparent;
    --ds-btn-bg: transparent;
    --ds-btn-color: var(--ds-btn-quiet-color, var(--ds-text-2));
    --ds-btn-hover-color: var(--ds-text);
    --ds-btn-disabled-border: transparent;
  }

  /* Ghost: no frame, the ink of its surroundings (currentColor is the
     inherited colour), so it reads on any surface its parent colours. */
  .ds-btn--ghost {
    --ds-btn-border: transparent;
    --ds-btn-bg: transparent;
    --ds-btn-color: currentColor;
    --ds-btn-hover-color: currentColor;
    --ds-btn-padding-x: var(--ds-space-3);
    --ds-btn-disabled-border: transparent;
  }

  /* Icon only: a square box of the icon size, 8px per size step, never
     below the touch minimum; density leaves it alone. */
  .ds-btn--icon {
    --_box: max(var(--ds-target-min, 0px), calc(var(--ds-btn-icon-size, 40px) + var(--ds-size-step, 0) * 8px));
    width: var(--_box);
    height: var(--_box);
    min-height: 0;
    padding: 0;
  }

  /* Full width: the button fills its line, its content centred. */
  .ds-btn--block {
    display: flex;
    width: 100%;
  }

  /*
   * Disc: a solid --ds-fill-round disc fades in behind the icon instead of
   * a faint layer (round buttons on the backdrop), also under keyboard
   * focus. It only fades, it never grows: in on --ds-dur-base, out on
   * --ds-dur-fast (the state layer's own transition); pressing shows the
   * full disc at once. It morphs and ripples like every pill.
   */
  .ds-btn--disc {
    --ds-btn-state: var(--ds-fill-round);
    --ds-btn-state-opacity: 1;
    --ds-btn-state-focus-opacity: 1;
    --ds-btn-state-pressed-opacity: 1;
  }

  @media (hover: hover) {
    .ds-btn--disc:hover::before {
      transition-duration: var(--ds-dur-base);
    }
  }

  /* A toggle that is on (a filter shown, "only active"): the tint. So is a
     button whose panel is open (a disclosure, a dialog or side sheet
     opener); a menu trigger stays as it is. */
  .ds-btn[aria-pressed="true"],
  :is(.ds-btn--disclosure, .ds-btn[aria-haspopup="dialog"])[aria-expanded="true"] {
    --ds-btn-border: var(--ds-accent);
    --ds-btn-bg: var(--ds-accent);
    --ds-btn-color: var(--ds-on-accent);
    --ds-btn-hover-color: var(--ds-on-accent);
  }

  /* Filled and tonal toggles (Material 3): off, the neutral container (the
     action ink on a filled one, the quieter ink on a tonal one); on, the
     variant's own fill. So off and on differ by the fill, not by a hue, and
     a filled toggle that is on stays filled. */
  :is(.ds-btn--filled, .ds-btn--tonal)[aria-pressed="false"] {
    --ds-btn-border: var(--ds-surface-highest);
    --ds-btn-bg: var(--ds-surface-highest);
    --ds-btn-color: var(--ds-action-ink);
    --ds-btn-hover-color: var(--ds-action-ink);
  }

  .ds-btn--tonal[aria-pressed="false"] {
    --ds-btn-color: var(--ds-text-2);
    --ds-btn-hover-color: var(--ds-text);
  }

  .ds-btn--filled[aria-pressed="true"] {
    --ds-btn-border: var(--ds-primary);
    --ds-btn-bg: var(--ds-primary);
    --ds-btn-color: var(--ds-on-primary);
    --ds-btn-hover-color: var(--ds-on-primary);
  }

  /* A choice made once and then locked (aria-disabled while pressed): it
     keeps its on look at full strength and shows no layer; its unpressed
     siblings dim as disabled buttons do. */
  .ds-btn[aria-pressed="true"][aria-disabled="true"]:not([aria-busy="true"]) {
    opacity: 1;
    color: var(--ds-btn-color, var(--ds-action-ink));
    background: var(--ds-btn-bg, transparent);
    border-color: var(--ds-btn-border, var(--ds-line-2));
    cursor: default;
  }

  /*
   * Adaptive label: in a narrow content panel (600px) the label goes
   * visually hidden and the button turns into a round quiet icon button.
   * Everything outside a content panel (the top bar, a page outside the
   * frame) and sheets and dialogs (which may sit inside one but are not
   * its width) follow the window instead; no container on new elements
   * (layout containment would re-anchor popups). The window rule names the
   * overlays only in its exclusion ("in a content panel and not in a sheet
   * or dialog", at the weight of one class): they are a condition here,
   * not a component this file styles, so button.css keeps its early
   * sublayer.
   * Its accessible name stays the label; a data-tip names it to the eye
   * while it is folded. The 1px floor: Firefox can style the button
   * before its container's first layout and read that container as 0px
   * wide; without the floor the button would come folded and unfold on
   * load (its colours and radius transitioning).
   */
  @container ds-content (min-width: 1px) and (max-width: 600px) {
    .ds-btn--adaptive {
      --_box: max(var(--ds-target-min, 0px), calc(var(--ds-btn-icon-size, 40px) + var(--ds-size-step, 0) * 8px));
      --ds-btn-border: transparent;
      --ds-btn-bg: transparent;
      --ds-btn-color: var(--ds-btn-quiet-color, var(--ds-text-2));
      --ds-btn-hover-color: var(--ds-text);
      width: var(--_box);
      height: var(--_box);
      min-height: 0;
      padding: 0;
    }

    .ds-btn--adaptive > svg {
      width: 20px;
      height: 20px;
    }

    .ds-btn--adaptive .ds-btn__label {
      position: absolute;
      top: 0;
      inset-inline-start: 0;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
    }
  }

  @media (max-width: 600px) {
    .ds-btn--adaptive:not(:where(.ds-content *):not(:is(.ds-sheet, .ds-dialog) *)) {
      --_box: max(var(--ds-target-min, 0px), calc(var(--ds-btn-icon-size, 40px) + var(--ds-size-step, 0) * 8px));
      --ds-btn-border: transparent;
      --ds-btn-bg: transparent;
      --ds-btn-color: var(--ds-btn-quiet-color, var(--ds-text-2));
      --ds-btn-hover-color: var(--ds-text);
      width: var(--_box);
      height: var(--_box);
      min-height: 0;
      padding: 0;
    }

    .ds-btn--adaptive:not(:where(.ds-content *):not(:is(.ds-sheet, .ds-dialog) *)) > svg {
      width: 20px;
      height: 20px;
    }

    .ds-btn--adaptive:not(:where(.ds-content *):not(:is(.ds-sheet, .ds-dialog) *)) .ds-btn__label {
      position: absolute;
      top: 0;
      inset-inline-start: 0;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
    }
  }

  /* A button that reads like a link: an action inside text or a table cell
     (the subject that opens the detail). */
  .ds-link-btn {
    padding: 0;
    border: 0;
    border-radius: var(--ds-radius-xs);
    background: none;
    color: var(--ds-link);
    font: inherit;
    font-weight: var(--ds-weight-label);
    text-align: start;
    text-decoration: underline;
    text-decoration-thickness: var(--ds-link-underline-thickness);
    text-decoration-color: var(--ds-link-underline);
    text-underline-offset: var(--ds-link-underline-offset);
    cursor: pointer;
    /* The ring rests (invisible) one width further out and snaps in. */
    outline-offset: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    transition:
      text-decoration-color var(--ds-dur-fast) var(--ds-ease-in-out),
      outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  @media (hover: hover) {
    .ds-link-btn:hover {
      text-decoration-color: var(--ds-link-underline-hover);
    }
  }

  /* The press on touch screens, which show no hover: the underline darkens
     like on hover. An inline link has no ripple and no morph. */
  .ds-link-btn:active {
    text-decoration-color: var(--ds-link-underline-hover);
  }

  /* Its own ring, also without .ds-base; it follows the small radius. */
  .ds-link-btn:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: var(--ds-focus-offset);
  }

  /* Quiet links: the quieter ink with a hairline underline, the link colour
     on hover; still underlined, so they read as links. */
  .ds-link--quiet,
  .ds-link-btn.ds-link-btn--quiet {
    color: var(--ds-text-2);
    text-decoration-line: underline;
    text-decoration-thickness: var(--ds-link-underline-thickness);
    text-decoration-color: var(--ds-line-2);
    text-underline-offset: var(--ds-link-underline-offset);
    /* The ring rests (invisible) one width further out and snaps in. */
    outline-offset: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    transition:
      color var(--ds-dur-fast) var(--ds-ease-in-out),
      text-decoration-color var(--ds-dur-fast) var(--ds-ease-in-out),
      outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  @media (hover: hover) {
    .ds-link--quiet:hover,
    .ds-link-btn.ds-link-btn--quiet:hover {
      color: var(--ds-link);
      text-decoration-color: var(--ds-link-underline-hover);
    }
  }

  .ds-link--quiet:active,
  .ds-link-btn.ds-link-btn--quiet:active {
    color: var(--ds-link);
    text-decoration-color: var(--ds-link-underline-hover);
  }

  .ds-link--quiet:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: var(--ds-focus-offset);
  }

  /* Toggles in a track with a sliding indicator (js/indicator.js): the pill
     paints the selection. A tint of its own would appear in place while the
     pill still travels (two pills at once), so the button stays clear and
     only its label changes colour, on the pill's timing (--ds-indicator-dur
     on the track). The pressed twin keeps the colour entry: a clicked toggle
     is still pressed (.ds-pressed outlives the click) while its pill
     arrives. Forced colors keep the selection colours below. */
  .ds-has-indicator > .ds-btn[aria-pressed="true"] {
    --ds-btn-border: transparent;
    --ds-btn-bg: transparent;
  }

  .ds-has-indicator > .ds-btn {
    transition:
      border-color var(--ds-dur-fast) var(--ds-ease-in-out),
      background-color var(--ds-dur-fast) var(--ds-ease-in-out),
      color var(--ds-indicator-dur, var(--ds-dur-medium)) var(--ds-ease-in-out),
      box-shadow var(--ds-dur-fast) var(--ds-ease-in-out),
      opacity var(--ds-dur-fast) var(--ds-ease-in-out),
      border-radius var(--ds-dur-medium) var(--ds-ease-spatial),
      outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-has-indicator > .ds-btn:active:not(:disabled, [aria-disabled="true"], [aria-busy="true"], .ds-btn--done),
  .ds-has-indicator > .ds-btn.ds-pressed:not(:disabled, [aria-disabled="true"], [aria-busy="true"], .ds-btn--done) {
    transition:
      border-color var(--ds-dur-fast) var(--ds-ease-in-out),
      background-color var(--ds-dur-fast) var(--ds-ease-in-out),
      color var(--ds-indicator-dur, var(--ds-dur-medium)) var(--ds-ease-in-out),
      box-shadow var(--ds-dur-fast) var(--ds-ease-in-out),
      opacity var(--ds-dur-fast) var(--ds-ease-in-out),
      border-radius var(--ds-dur-micro) var(--ds-ease-out),
      outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  /* Forced colors turn the tint into Canvas, so on would look like off: the
     system's selection colours instead, and a ring that names its colour. */
  @media (forced-colors: active) {
    /* Blocked (aria-disabled): GrayText, like a disabled button. */
    .ds-btn[aria-disabled="true"]:not([aria-busy="true"]) {
      forced-color-adjust: none;
      border-color: GrayText;
      background: Canvas;
      color: GrayText;
    }

    .ds-btn[aria-pressed="true"],
    .ds-btn[aria-pressed="true"][aria-disabled="true"]:not([aria-busy="true"]),
    :is(.ds-btn--disclosure, .ds-btn[aria-haspopup="dialog"])[aria-expanded="true"] {
      forced-color-adjust: none;
      border-color: Highlight;
      background: Highlight;
      color: HighlightText;
    }

    /* Blocked controls stay focusable (their tooltip says why); unforced,
       their ring would keep the brand colour. */
    .ds-btn[aria-pressed="true"]:focus-visible,
    .ds-btn[aria-disabled="true"]:focus-visible,
    :is(.ds-btn--disclosure, .ds-btn[aria-haspopup="dialog"])[aria-expanded="true"]:focus-visible {
      outline-color: CanvasText;
    }
  }
}

/* ── components/loading/loading.css ── */
/*
 * Loading states. Nothing shows for fast loads: every indicator fades in
 * only after --ds-delay-loader (the same delay as LOADER_DELAY_MS in
 * js/motion.js, whose settleLoader() keeps a visible one up long enough).
 * Their loops always run at their token speed (--ds-loop-* in tokens.css).
 * A block that waits shows the shape loader (loader.css); inline spots
 * keep the arc spinner (spinner.css).
 *
 *   <div class="ds-boot" role="status"><span class="ds-loader" aria-hidden="true"></span>Starting ...</div>
 *                                                     app start, after --ds-delay-boot
 *   <div class="ds-loading" role="status"><span class="ds-loader ds-sm" aria-hidden="true"></span>Loading ...
 *     <p class="ds-loading__detail">812 of 2,030 rows</p></div>   detail lines under the text (2.0)
 *   <div class="ds-skeleton" role="status"> <span class="ds-sr">Loading ...</span>
 *     <span class="ds-loadbar" aria-hidden="true"><span class="ds-loadbar__bar"></span></span>
 *     <span class="ds-skeleton__line ds-skeleton__line--heading"></span> ...
 *     <span class="ds-skeleton__line ds-skeleton__line--lead"></span>
 *     <p class="ds-skeleton__note">Loading 3 of 12 reports</p>      a progress line (2.0); hidden while empty
 *     <div class="ds-skeleton__card"> <span class="ds-skeleton__line ds-skeleton__line--title"></span> ...
 *
 *   .ds-skeleton__line  a body line; --heading (a page title), --lead (its
 *                       lead), --title (a card title), --mid (a middle-length
 *                       line), --short (a last line), --label (a field's label)
 *
 * The presets are bones in documented markup (docs/components.md), each a
 * .ds-skeleton or inside one:
 *   text, heading  .ds-skeleton__line and its modifiers
 *   avatar         .ds-skeleton__avatar   a round bone, 40px at md
 *   media          .ds-skeleton__media    a block bone, --ds-skeleton-media-ratio
 *   list row       .ds-skeleton__row      avatar, .ds-skeleton__lines, a meta bone
 *   table          .ds-skeleton__table    .ds-skeleton__cells rows (--head first)
 *   card           .ds-skeleton__card     lines in a card outline
 *   form           .ds-skeleton__form     --label lines and .ds-skeleton__field bones
 *   .ds-skeleton--pulse   the bones breathe in place instead of the wave
 *
 * Options (docs/options.md), read here:
 *   size      .ds-xs ... .ds-xl on a bone or any ancestor: 2px per step on a
 *             line, 8px on an avatar, a field and a row; the loader in a
 *             .ds-loading follows its own steps
 *   density   any container: the padding and the gaps of the blocks (2px per
 *             step: under the compact theme, density -2, the line's padding is
 *             12px and a card's 20px, on purpose), a field and a table row 4px
 *             per step: their owners' formula on their owners' hooks
 *             (--ds-input-height, --ds-table-row-height, --ds-table-head-height),
 *             so a bone never jumps when the real control replaces it
 *   shape     a bone's radius and a card's corners times --ds-shape; an
 *             avatar stays round
 *   tone, target-min: not read. Nothing here is a target or says more than
 *             "wait".
 *
 * The older markup with a .ds-spinner in .ds-boot or .ds-loading keeps
 * working; the spinner is the inline variant (a row in a list, a cell).
 *
 * Hooks: --ds-skeleton-radius (the bones' corners; default
 * --ds-radius-action, the heading line --ds-radius-sm, a media bone
 * --ds-radius-card), --ds-skeleton-media-ratio (16 / 9).
 *
 * Skeleton: one synchronised, calm diagonal wave across the whole surface.
 * The surface runs ds-skeleton-wave once its own entrance is over (its
 * delay is --ds-delay-loader plus --ds-dur-medium) and animates one
 * registered value, --ds-skeleton-x; every bone clips itself to its shape
 * (clip-path with its radius) and carries the band as a fixed ::after,
 * placed in the viewport and moved by `translate` to that position (2.0),
 * so the bones show a single continuous band. The band has a compositor
 * layer of its own (will-change: translate): the wave moves it without
 * repainting the bones or the view (before 2.0 a fixed background was
 * repainted with the whole view on every step). A bone outside a
 * .ds-skeleton runs the wave itself. Fallback: under a transformed
 * ancestor (a sheet mid-slide, an element running .ds-enter) the band is
 * placed in that ancestor instead of the viewport; the bones stay in sync
 * in time and share the band within it.
 *
 * Loading bar: the two-segment indeterminate choreography of M3
 * (ds-progress-head, ds-progress-tail on --ds-loop-indeterminate), flat
 * (at the panel edge a wave would be clipped). In a skeleton it shares the
 * skeleton's delay; on its own it fades in after --ds-delay-loader. It
 * reaches the panel edges through the read-only padding properties of
 * .ds-content (--ds-content-pad-top, --ds-content-pad-x; page.css) and,
 * inside a .ds-page, the page's centring (100cqw of .ds-content), and the
 * view's scroll hairline hides while it is there (shell.css). Place it (or
 * its skeleton) directly in .ds-content or .ds-page, with no other size
 * container in between.
 *
 * Refresh pattern: put .ds-stale on the content and insert a loading bar
 * above it; when the data arrives,
 *   await DS.motion.settleLoader(startedAt, { element: loadbar });
 *   await DS.motion.leave(loadbar);       (fades it out and removes it)
 * then render the fresh content and remove .ds-stale. The bar's segments
 * (and a skeleton's wave) keep moving while it fades out: .ds-leave keeps
 * their loops (motion.css).
 *
 * Pulse (.ds-skeleton--pulse): for a surface that should not sweep (a small
 * card among finished ones, a long table). Each bone shows the highlight
 * through its own ::after, whose opacity breathes on the ds-fade-in keyframe
 * running infinite and alternate, on --ds-loop-skeleton and --ds-ease-in-out,
 * after the same delay. Opacity only: no repaint.
 *
 * Print: the band and the loading bar are left out.
 *
 * Runtime property --ds-skeleton-x (registered, tokens.css): the band's
 * position; it rests at -150vw (off screen) whenever the wave does not
 * run, so an exit that replaces the wave never shows a band.
 */

@layer ds.components.loading {
  /* App start: appears only when the start takes a moment. */
  .ds-boot {
    min-height: 100svh;
    display: grid;
    place-content: center;
    justify-items: center;
    gap: var(--ds-space-5);
    animation: ds-fade-in var(--ds-dur-slow) var(--ds-ease-in-out) var(--ds-delay-boot) backwards;
  }

  /* Small loading line (side sheets, "load more"): the loader, then the
     text, in one row as in 1.x (inline markup in the text or a trailing
     button stays on it). */
  .ds-loading {
    display: flex;
    align-items: center;
    gap: var(--ds-space-3);
    padding: calc(var(--ds-space-4) + var(--ds-density, 0) * 2px) 0;
    color: var(--ds-text-2);
    font: var(--ds-font-body);
    animation: ds-fade-in var(--ds-dur-medium) var(--ds-ease-in-out) var(--ds-delay-loader) backwards;
  }

  /* Page placeholder: the outline of the page, one wave passing over it
     after its entrance. The wave holds its start (off screen) during the
     delay. */
  .ds-skeleton {
    /* At rest (an exit or entrance that replaces the wave) the band stays
       off screen, as at the start of the sweep. */
    --ds-skeleton-x: -150vw;
    display: grid;
    gap: calc(var(--ds-space-4) + var(--ds-density, 0) * 2px);
    animation:
      ds-fade-in var(--ds-dur-medium) var(--ds-ease-in-out) var(--ds-delay-loader) backwards,
      ds-skeleton-wave var(--ds-loop-skeleton) linear calc(var(--ds-delay-loader) + var(--ds-dur-medium)) infinite backwards;
  }

  /* The container already waits: no second delay on a loader in it. */
  .ds-boot .ds-loader,
  .ds-loading .ds-loader,
  .ds-skeleton .ds-loader {
    animation: none;
  }

  /* With detail lines (2.0) it becomes two columns: the lines sit under the
     text in its column, aligned with it whatever the loader's size. Keep
     the text one run there (or one element): each piece is a cell. */
  .ds-loading:has(> .ds-loading__detail) {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr);
    row-gap: var(--ds-space-1);
  }

  .ds-loading__detail {
    grid-column: 2;
    margin: 0;
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
  }

  /* A progress line under the lead bone (2.0), inside the role="status"
     skeleton, so it is announced. */
  .ds-skeleton__note {
    margin: calc(-1 * var(--ds-space-2)) 0 0;
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
    font-variant-numeric: tabular-nums;
  }

  .ds-skeleton__note:empty {
    display: none;
  }

  .ds-skeleton__card {
    display: grid;
    gap: calc(var(--ds-space-3) + var(--ds-density, 0) * 2px);
    padding: calc(var(--ds-space-6) + var(--ds-density, 0) * 2px);
    border: 1px solid var(--ds-line);
    border-radius: calc(var(--ds-radius-card) * var(--ds-shape, 1));
  }

  /* A bone: the band is two viewports wide and fixed to the viewport, so
     every bone shows its own slice of the same band. The bone clips the
     band to its rounded shape; the band moves on its own layer, so the
     wave repaints nothing. */
  .ds-skeleton__line,
  .ds-skeleton__field {
    --_r: var(--ds-skeleton-radius, var(--ds-radius-action));
    --_bone: min(calc(min(var(--_r), calc(var(--_h) / 2)) * var(--ds-shape, 1)), calc(var(--_h) / 2));
  }

  .ds-skeleton__line {
    --_line: 12px;
    --_h: calc(var(--_line) + var(--ds-size-step, 0) * 2px);
    display: block;
    width: 100%;
    height: var(--_h);
  }

  /* A field: the height of the control it stands for. */
  .ds-skeleton__field {
    --_h: max(var(--ds-target-min, 0px), calc(var(--ds-input-height, 40px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px));
    --_r: var(--ds-skeleton-radius, var(--ds-radius-sm));
    display: block;
    width: 100%;
    height: var(--_h);
  }

  .ds-skeleton__avatar {
    --_h: calc(40px + var(--ds-size-step, 0) * 8px);
    --_bone: 50%;
    display: block;
    flex-shrink: 0;
    width: var(--_h);
    height: var(--_h);
  }

  .ds-skeleton__media {
    --_bone: calc(var(--ds-skeleton-radius, var(--ds-radius-card)) * var(--ds-shape, 1));
    display: block;
    width: 100%;
    aspect-ratio: var(--ds-skeleton-media-ratio, 16 / 9);
  }

  .ds-skeleton__line,
  .ds-skeleton__field,
  .ds-skeleton__avatar,
  .ds-skeleton__media {
    border-radius: var(--_bone);
    background-color: var(--ds-surface-highest);
    clip-path: inset(0 round var(--_bone));
  }

  .ds-skeleton__line::after,
  .ds-skeleton__field::after,
  .ds-skeleton__avatar::after,
  .ds-skeleton__media::after {
    content: '';
    position: fixed;
    inset-block: 0;
    inset-inline-start: 0;
    width: 200vw;
    background-image: linear-gradient(105deg, transparent 40%, var(--ds-skeleton-highlight) 50%, transparent 60%);
    translate: var(--ds-skeleton-x) 0;
    will-change: translate;
    pointer-events: none;
  }

  .ds-skeleton__line:not(.ds-skeleton *),
  .ds-skeleton__field:not(.ds-skeleton *),
  .ds-skeleton__avatar:not(.ds-skeleton *),
  .ds-skeleton__media:not(.ds-skeleton *) {
    --ds-skeleton-x: -150vw;
    animation: ds-skeleton-wave var(--ds-loop-skeleton) linear infinite;
  }

  .ds-skeleton__line--heading { --_line: 28px; --_r: var(--ds-skeleton-radius, var(--ds-radius-sm)); width: 28%; }
  .ds-skeleton__line--lead { width: 56%; margin-bottom: var(--ds-space-2); }
  .ds-skeleton__line--title { --_line: 16px; width: 24%; }
  .ds-skeleton__line--short { width: 44%; }
  .ds-skeleton__line--mid { width: 70%; }
  .ds-skeleton__line--label { width: 24%; }

  /* A list row: avatar, two lines, a meta bone at the end. */
  .ds-skeleton__row {
    display: flex;
    align-items: center;
    gap: var(--ds-space-3);
    min-height: calc(64px + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px);
  }

  .ds-skeleton__lines {
    display: grid;
    flex: 1;
    gap: var(--ds-space-2);
    min-width: 0;
  }

  .ds-skeleton__row > .ds-skeleton__line {
    flex: 0 0 auto;
    width: 64px;
  }

  /* A table: rows of equal cells, a hairline under each; --head first. */
  .ds-skeleton__table {
    display: grid;
  }

  .ds-skeleton__cells {
    display: grid;
    grid-auto-flow: column;
    grid-auto-columns: minmax(0, 1fr);
    align-items: center;
    gap: var(--ds-space-4);
    min-height: max(var(--ds-target-min, 0px), calc(var(--ds-table-row-height, 52px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px));
    border-bottom: 1px solid var(--ds-line);
  }

  .ds-skeleton__cells--head {
    min-height: max(var(--ds-target-min, 0px), calc(var(--ds-table-head-height, 48px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px));
  }

  .ds-skeleton__form {
    display: grid;
    gap: calc(var(--ds-space-2) + var(--ds-density, 0) * 2px);
  }

  .ds-skeleton__form > .ds-skeleton__field:not(:last-child) {
    margin-bottom: var(--ds-space-3);
  }

  /* Pulse: the surface keeps its entrance and has no wave; each bone shows
     the highlight, its opacity breathing (a compositor animation, no
     repaint). The bone's clip keeps it in shape. */
  .ds-skeleton--pulse {
    animation: ds-fade-in var(--ds-dur-medium) var(--ds-ease-in-out) var(--ds-delay-loader) backwards;
  }

  .ds-skeleton--pulse :is(.ds-skeleton__line, .ds-skeleton__field, .ds-skeleton__avatar, .ds-skeleton__media)::after {
    position: absolute;
    inset: 0;
    width: auto;
    background-image: none;
    background-color: var(--ds-skeleton-highlight);
    translate: none;
    will-change: opacity;
    animation: ds-fade-in var(--ds-loop-skeleton) var(--ds-ease-in-out) var(--ds-delay-loader) infinite alternate backwards;
  }

  .ds-skeleton--pulse :is(.ds-skeleton__line, .ds-skeleton__field, .ds-skeleton__avatar, .ds-skeleton__media) {
    position: relative;
  }

  /*
   * Page loading bar: 4px at the top edge of the content panel, sticky
   * while the panel scrolls. The track animates the edges of both segments
   * (registered, inheriting); segment 1 is the bar, segment 2 the ::after,
   * each the full width clipped between its tail and its head.
   */
  .ds-loadbar {
    position: sticky;
    top: 0;
    z-index: var(--ds-z-raised);
    display: block;
    height: 4px;
    overflow: hidden;
    margin: calc(-1 * var(--ds-content-pad-top, var(--ds-space-6))) calc(-1 * var(--ds-content-pad-x, var(--ds-space-8))) var(--ds-space-5);
    background: var(--ds-accent);
    animation:
      ds-progress-head var(--ds-loop-indeterminate) linear infinite,
      ds-progress-tail var(--ds-loop-indeterminate) linear infinite;
  }

  /* On its own (a refresh), the bar waits the loader delay; in a skeleton
     the skeleton waits, and only the loops run here. */
  .ds-loadbar:not(.ds-skeleton > .ds-loadbar) {
    animation:
      ds-fade-in var(--ds-dur-medium) var(--ds-ease-in-out) var(--ds-delay-loader) backwards,
      ds-progress-head var(--ds-loop-indeterminate) linear infinite,
      ds-progress-tail var(--ds-loop-indeterminate) linear infinite;
  }

  @media (max-width: 720px) {
    .ds-loadbar {
      margin-bottom: var(--ds-space-4);
    }
  }

  .ds-loadbar__bar,
  .ds-loadbar::after {
    position: absolute;
    inset: 0;
    display: block;
    background: var(--ds-primary);
  }

  .ds-loadbar__bar {
    clip-path: inset(0 calc(100% - var(--ds-progress-head-1)) 0 var(--ds-progress-tail-1) round calc(var(--ds-radius-action) * var(--ds-shape, 1)));
  }

  .ds-loadbar::after {
    content: '';
    clip-path: inset(0 calc(100% - var(--ds-progress-head-2)) 0 var(--ds-progress-tail-2) round calc(var(--ds-radius-action) * var(--ds-shape, 1)));
  }

  /* Forced colors turn every fill into Canvas, which would hide the bones
     and the bar: edges for the bones and the track, the system highlight
     for both segments. */
  @media (forced-colors: active) {
    .ds-skeleton__line,
    .ds-skeleton__field,
    .ds-skeleton__avatar,
    .ds-skeleton__media {
      outline: 1px solid CanvasText;
      clip-path: none;
    }

    .ds-skeleton__line::after,
    .ds-skeleton__field::after,
    .ds-skeleton__avatar::after,
    .ds-skeleton__media::after {
      content: none;
    }

    .ds-loadbar {
      outline: 1px solid CanvasText;
    }

    .ds-loadbar__bar,
    .ds-loadbar::after {
      forced-color-adjust: none;
      background: Highlight;
    }
  }

  /* Print: a fixed box repeats on every printed page, so the band goes;
     the moving loading bar says nothing on paper. */
  @media print {
    .ds-skeleton__line::after,
    .ds-skeleton__field::after,
    .ds-skeleton__avatar::after,
    .ds-skeleton__media::after {
      content: none;
    }

    .ds-loadbar {
      display: none;
    }
  }
}

/* ── components/disclosure/disclosure.css ── */
/*
 * Disclosure: a styled <details> that opens and closes like any
 * .ds-collapsible (motion.css: the height and the fade, the .ds-chevron
 * turning on the spring), and accordion rows.
 *
 *   <details class="ds-collapsible ds-disclosure">
 *     <summary>Advanced [icon chevronDown 20 .ds-chevron]</summary>
 *     <div class="ds-disclosure__body"> ... </div>
 *   </details>
 *
 *   <div class="ds-disclosure-list">
 *     <details class="ds-collapsible ds-disclosure ds-disclosure--row" name="faq">
 *       <summary><span class="ds-disclosure__title">Sync</span><span class="ds-disclosure__meta">Nightly</span>[icon chevronDown 20 .ds-chevron]</summary>
 *       <div class="ds-disclosure__body"> ... </div>
 *     </details>
 *   </div>
 *
 * The plain summary is a pill (at least 40px high) whose state layer hangs
 * --ds-space-2 into the space at its sides, so its text stays in line with
 * the content around it: hover --ds-state-hover, press --ds-state-pressed
 * in --ds-dur-micro, the focus layer and a ring that snaps in from offset +
 * width, the press morph (squarer in --ds-dur-micro, springing back over
 * --ds-dur-medium) and the ripple (js/ripple.js). The body starts
 * --ds-space-3 below the summary.
 *
 * .ds-disclosure--row: a full-width summary (at least 48px high) with a
 * title, a quiet meta and the chevron at the end; rows in a
 * .ds-disclosure-list are divided by hairlines. A row takes a rectangular
 * layer (hover --ds-state-hover-lg), an inset ring, the ripple and no morph.
 * In a card the list runs to its edges (card.css, through
 * --ds-disclosure-row-padding-exact).
 *
 * Exclusive accordion: rows that share a name (details[name], at the floor)
 * open one at a time, with no script; opening one closes the other through
 * the same .ds-collapsible motion. Keyboard: Tab between the summaries,
 * Enter or Space toggles (native).
 * The errors list of alert.css (.ds-errors) keeps its own summary.
 *
 * Options (src/core/options.css, docs/options.md), on the disclosure or any
 * ancestor; each is computed here, in the summary's own rule:
 *   size      .ds-xs ... .ds-xl: 8px of height per step, the type role of
 *             the size (--ds-size-font)
 *   density   .ds-density-*: 4px of height per step; a row's side padding
 *             and the space above and below a body 2px per step
 *   shape     .ds-shape-*: multiplies the plain summary's rest and pressed
 *             radius (a row stays rectangular)
 *   touch     .ds-touch: at least --ds-touch-target high; touch wins over
 *             size and density
 *   tone      not read: a disclosure shows no meaning of its own
 *
 * Hooks: --ds-disclosure-height (40px), --ds-disclosure-row-height (48px),
 * the base heights the options apply to; --ds-disclosure-radius,
 * --ds-disclosure-radius-pressed, --ds-disclosure-font,
 * --ds-disclosure-row-padding (--ds-space-4, the base),
 * --ds-disclosure-row-padding-exact (unset; a fixed side padding that
 * ignores density: what a card sets). The computed values (--_h, --_box,
 * --_half, --_radius, --_pad) are private.
 *
 * Forced colours: no state layer; the ring, the hairlines and the turned
 * chevron stay.
 */

@layer ds.components.disclosure {
  .ds-disclosure > summary {
    --_h: calc(var(--ds-disclosure-height, 40px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px);
    --_box: max(var(--ds-target-min, 0px), var(--_h));
    --_half: calc(var(--_box) / 2);
    --_radius: min(calc(min(var(--ds-disclosure-radius, var(--ds-radius-action)), var(--_half)) * var(--ds-shape, 1)), var(--_half));
    position: relative;
    isolation: isolate;
    display: flex;
    align-items: center;
    gap: var(--ds-space-2);
    box-sizing: border-box;
    width: fit-content;
    max-width: calc(100% + 2 * var(--ds-space-2));
    min-height: var(--_box);
    margin-inline: calc(-1 * var(--ds-space-2));
    padding-inline: var(--ds-space-2);
    border-radius: var(--_radius);
    color: var(--ds-text);
    font: var(--ds-disclosure-font, var(--ds-size-font, var(--ds-font-label)));
    list-style: none;
    cursor: pointer;
    -webkit-tap-highlight-color: transparent;
    /* The ring rests (invisible) one width further out and snaps in. */
    outline-offset: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    transition:
      border-radius var(--ds-dur-medium) var(--ds-ease-spatial),
      outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-disclosure > summary::-webkit-details-marker {
    display: none;
  }

  .ds-disclosure > summary::before {
    content: '';
    position: absolute;
    inset: 0;
    z-index: -1;
    border-radius: inherit;
    background: currentColor;
    opacity: 0;
    pointer-events: none;
    transition: opacity var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  @media (hover: hover) {
    .ds-disclosure > summary:hover::before {
      opacity: var(--ds-state-hover);
    }

    /* A row's larger hover layer; before the focus and press layers, which
       win at the same specificity. */
    .ds-disclosure--row > summary:hover::before {
      opacity: var(--ds-state-hover-lg);
    }
  }

  /* Keyboard focus: the layer appears with the ring and fades out on blur. */
  .ds-disclosure > summary:focus-visible::before {
    opacity: var(--ds-state-focus);
    transition-duration: 0s;
  }

  /* Press-in in --ds-dur-micro (.ds-pressed: js/ripple.js holds it). */
  .ds-disclosure > summary:active::before,
  .ds-disclosure > summary.ds-pressed::before {
    opacity: var(--ds-state-pressed);
    transition-duration: var(--ds-dur-micro);
  }

  /* The press morph: squarer while pressed (never rounder than at rest),
     springing back on release. */
  .ds-disclosure:not(.ds-disclosure--row) > summary:active,
  .ds-disclosure:not(.ds-disclosure--row) > summary.ds-pressed {
    border-radius: min(calc(var(--ds-disclosure-radius-pressed, var(--ds-radius-action-pressed)) * var(--ds-shape, 1)), var(--_radius));
    transition:
      border-radius var(--ds-dur-micro) var(--ds-ease-out),
      outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-disclosure > summary:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: var(--ds-focus-offset);
  }

  .ds-disclosure > summary > svg {
    flex: none;
  }

  .ds-disclosure__body {
    padding-top: calc(var(--ds-space-3) + var(--ds-density, 0) * 2px);
  }

  /*
   * Accordion rows: a full-width summary, rectangular. The side padding is
   * shared with the body; a card sets the exact hook to run the rows to its
   * edges.
   */
  .ds-disclosure--row {
    --_pad: var(--ds-disclosure-row-padding-exact, calc(var(--ds-disclosure-row-padding, var(--ds-space-4)) + var(--ds-density, 0) * 2px));
  }

  .ds-disclosure-list > .ds-disclosure + .ds-disclosure {
    border-top: 1px solid var(--ds-line);
  }

  .ds-disclosure--row > summary {
    --_h: calc(var(--ds-disclosure-row-height, 48px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px);
    width: auto;
    max-width: none;
    margin-inline: 0;
    padding: var(--ds-space-2) var(--_pad);
    border-radius: 0;
    gap: var(--ds-space-3);
    /* An inset ring: it rests on the edge and snaps inward. */
    outline-offset: 0;
    transition: outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-disclosure--row > summary:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: calc(-1 * var(--ds-focus-width));
  }

  .ds-disclosure__title {
    flex: 1 1 auto;
    min-width: 0;
    overflow-wrap: anywhere;
  }

  .ds-disclosure__meta {
    flex: none;
    color: var(--ds-text-2);
    font: var(--ds-font-body);
  }

  .ds-disclosure--row > .ds-disclosure__body {
    padding: 0 var(--_pad) calc(var(--ds-space-4) + var(--ds-density, 0) * 2px);
  }

  /* The ring stays; a layer of the page's ink would only hide the text. */
  @media (forced-colors: active) {
    .ds-disclosure > summary::before {
      display: none;
    }
  }
}

/* ── components/timeline/timeline.css ── */
/*
 * Timeline: the history of a record, newest first or oldest first as the
 * page orders it. A rail runs down the start edge with a dot (or an icon
 * marker) on the head line of every entry; day headings group entries.
 *
 *   <ol class="ds-timeline" role="list" aria-label="History of LAPTOP-0042">
 *     <li class="ds-timeline__group" role="presentation"><h3 class="ds-timeline__day">12 Oct 2026</h3></li>
 *     <li class="ds-timeline__item" data-ds-key="e3">
 *       <div class="ds-timeline__head"><p class="ds-timeline__title">Issued</p><span class="ds-status ds-tone-success">...</span></div>
 *       <p class="ds-timeline__meta"><time datetime="2026-10-12T14:05">14:05</time> · Ada Lovelace</p>
 *       <p class="ds-timeline__text">Issued to Ada Lovelace.</p>
 *       <div class="ds-timeline__actions ds-sm"><button class="ds-btn ds-btn--text" type="button" aria-label="Edit the entry of 12 Oct 2026, 14:05">Edit</button></div>
 *     </li>
 *     <li class="ds-timeline__item ds-timeline__item--muted"> ... </li>
 *     <li class="ds-timeline__item ds-timeline__item--icon"><span class="ds-timeline__marker" aria-hidden="true">[icon user 16]</span> ... </li>
 *   </ol>
 *
 * An entry is indented by --ds-timeline-indent and divided from the one
 * before by a hairline from its text edge. Its dot (::after) is drawn
 * with borders, so it stays in forced colours, and centred on the head
 * line (--ds-timeline-head-line, the height of a status chip). The rail
 * (::before) runs in segments from dot to dot, with a gap of --ds-space-1
 * around each dot; it passes through day headings (.ds-timeline__group,
 * no dot). --muted: a ring instead of a dot, for an entry that did not
 * take effect (say why in words). --icon with .ds-timeline__marker: a
 * disc with a 16px icon instead of the dot. A 16px icon leading __meta
 * (> svg:first-child) sits on its text line. __text keeps its line breaks
 * and the reading measure; __body holds a form in place; __actions hangs
 * the padding of its text buttons.
 *
 * No motion of its own: entries come and go through DS.motion.flip (a
 * removed entry moves focus to its neighbour, live entries with
 * live: true), and while they glide they stand on an opaque backing
 * (data-ds-glide and --ds-flip-backdrop on the list). Editing in place
 * swaps the text and the form through DS.motion.crossfade.
 *
 * Variants (3.0):
 *   .ds-timeline--activity   a feed: an entry is one sentence, who did what
 *     (.ds-timeline__title in the body font, <strong> for who), in a
 *     __marker with an avatar's initials or an image; no hairlines, the
 *     entries closer together, .ds-timeline__time at the end of the line.
 *     A --muted entry there (the system's own, a sync that changed nothing)
 *     also takes the quieter ink
 *   .ds-timeline__item--comment   the entry's .ds-timeline__text in a box of
 *     its own (--ds-timeline-comment-bg): what someone wrote, apart from
 *     what happened
 *   .ds-timeline__item--muted with --icon: the marker is a ring as well
 *
 * Options (src/core/options.css, docs/options.md), on the list or any
 * ancestor; each is computed here, in the rule that uses it:
 *   size      .ds-xs ... .ds-xl: the marker 4px per step, the indent with
 *             it, the dot 2px per step, the title the type role of the size
 *             (--ds-size-font); the head line 4px per step above md and no
 *             less below it, as it still holds a status chip or a line of
 *             body text; the text and the meta stay
 *   density   .ds-density-*: an entry's block padding 2px per step (the
 *             rail follows); never the type, the marker or the dot
 *   shape     .ds-shape-*: multiplies the radius of the dot, the marker
 *             (half their size: round at the default, rounded corners at
 *             soft, square at square) and the comment box
 *   touch     nothing here: the entry is no target, its buttons are
 *
 * Hooks: --ds-timeline-indent (--ds-space-8), --ds-timeline-padding
 * (--ds-space-3, --activity --ds-space-2), --ds-timeline-dot-size
 * (10px), --ds-timeline-dot-color (--ds-primary), --ds-timeline-muted-color
 * (--ds-outline), --ds-timeline-line-width (2px), --ds-timeline-line-color
 * (--ds-line), --ds-timeline-divider-color (--ds-line),
 * --ds-timeline-marker-size (24px), --ds-timeline-head-line (24px),
 * --ds-timeline-comment-bg (--ds-surface-low), --ds-timeline-comment-radius
 * (--ds-radius-card).
 */

@layer ds.components.timeline {
  /* No top margin of its own: inside a card the card's rhythm spaces it
     (zero weight). */
  :where(.ds-timeline) {
    margin-top: 0;
  }

  .ds-timeline {
    margin-inline: 0;
    margin-bottom: 0;
    padding: 0;
    list-style: none;
    color: var(--ds-text);
  }

  .ds-timeline:empty {
    display: none;
  }

  /* The geometry of the rail, once for every part that uses it. */
  .ds-timeline__item,
  .ds-timeline__group {
    --_pad: max(0px, calc(var(--ds-timeline-padding, var(--ds-space-3)) + var(--ds-density, 0) * 2px));
    /* Upward only: the line holds a chip or a line of body text at any size,
       and the marks stay centred on what it holds. */
    --_head: calc(var(--ds-timeline-head-line, 24px) + max(0, var(--ds-size-step, 0)) * 4px);
    --_dot: calc(var(--ds-timeline-dot-size, 10px) + var(--ds-size-step, 0) * 2px);
    --_marker: calc(var(--ds-timeline-marker-size, 24px) + var(--ds-size-step, 0) * 4px);
    --_indent: calc(var(--ds-timeline-indent, var(--ds-space-8)) + var(--ds-size-step, 0) * 4px);
    position: relative;
    margin-inline-start: var(--_indent);
  }

  .ds-timeline--activity > :is(.ds-timeline__item, .ds-timeline__group) {
    --_pad: max(0px, calc(var(--ds-timeline-padding, var(--ds-space-2)) + var(--ds-density, 0) * 2px));
  }

  .ds-timeline__item {
    display: grid;
    gap: var(--ds-space-1);
    padding-block: var(--_pad);
  }

  .ds-timeline__item + .ds-timeline__item {
    border-top: 1px solid var(--ds-timeline-divider-color, var(--ds-line));
  }

  .ds-timeline--activity > .ds-timeline__item + .ds-timeline__item {
    border-top: 0;
  }

  /* The dot, centred on the rail and on the head line. */
  .ds-timeline__item::after {
    content: '';
    position: absolute;
    top: calc(var(--_pad) + var(--_head) / 2 - var(--_dot) / 2);
    inset-inline-start: calc(var(--_marker) / 2 - var(--_indent) - var(--_dot) / 2);
    box-sizing: border-box;
    width: var(--_dot);
    height: var(--_dot);
    border: calc(var(--_dot) / 2) solid var(--ds-timeline-dot-color, var(--ds-primary));
    border-radius: min(calc(min(var(--ds-radius-action), calc(var(--_dot) / 2)) * var(--ds-shape, 1)), calc(var(--_dot) / 2));
  }

  /* An entry that did not take effect: a ring. */
  .ds-timeline__item--muted::after {
    border-width: var(--ds-timeline-line-width, 2px);
    border-color: var(--ds-timeline-muted-color, var(--ds-outline));
  }

  .ds-timeline__item--icon::after {
    display: none;
  }

  /*
   * The rail: from below this entry's dot (or marker) to above the next
   * one's, in the next entry's top padding. A day heading carries it
   * through its own height; the last entry has none.
   */
  .ds-timeline__item::before,
  .ds-timeline__group::before {
    content: '';
    position: absolute;
    top: calc(var(--_pad) + var(--_head) / 2 + var(--_dot) / 2 + var(--ds-space-1));
    bottom: calc(var(--ds-space-1) + var(--_dot) / 2 - var(--_pad) - var(--_head) / 2);
    inset-inline-start: calc(var(--_marker) / 2 - var(--_indent) - var(--ds-timeline-line-width, 2px) / 2);
    border-inline-start: var(--ds-timeline-line-width, 2px) solid var(--ds-timeline-line-color, var(--ds-line));
    pointer-events: none;
  }

  .ds-timeline__item--icon::before {
    top: calc(var(--_pad) + var(--_head) / 2 + var(--_marker) / 2 + var(--ds-space-1));
  }

  /* Above a marker it stops at the marker's edge, not at a dot's: a muted
     ring would show the end of the rail inside it. */
  :is(.ds-timeline__item, .ds-timeline__group):has(+ .ds-timeline__item--icon)::before {
    bottom: calc(var(--ds-space-1) + var(--_marker) / 2 - var(--_pad) - var(--_head) / 2);
  }

  .ds-timeline__group::before {
    top: 0;
  }

  .ds-timeline > :last-child::before,
  .ds-timeline > .ds-timeline__group:first-child::before {
    display: none;
  }

  .ds-timeline__marker {
    position: absolute;
    top: calc(var(--_pad) + var(--_head) / 2 - var(--_marker) / 2);
    inset-inline-start: calc(-1 * var(--_indent));
    display: grid;
    place-items: center;
    box-sizing: border-box;
    width: var(--_marker);
    height: var(--_marker);
    overflow: hidden;
    border: 1px solid transparent;
    border-radius: min(calc(min(var(--ds-radius-action), calc(var(--_marker) / 2)) * var(--ds-shape, 1)), calc(var(--_marker) / 2));
    background: var(--ds-surface-high);
    color: var(--ds-text-2);
    font: var(--ds-font-caption);
    /* Initials in proportion to the disc, so two letters are never cut. */
    font-size: calc(var(--_marker) / 2);
  }

  /* 16px on the 24px disc, in proportion at the other sizes. */
  .ds-timeline__marker > svg {
    width: calc(var(--_marker) * 2 / 3);
    height: calc(var(--_marker) * 2 / 3);
  }

  /* An avatar: the picture fills the disc. */
  .ds-timeline__marker > img {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: cover;
  }

  .ds-timeline__item--muted > .ds-timeline__marker {
    border-color: var(--ds-timeline-muted-color, var(--ds-outline));
    background: none;
  }

  .ds-timeline__group {
    padding-block: var(--ds-space-4) var(--ds-space-1);
  }

  .ds-timeline__group:first-child {
    padding-top: 0;
  }

  .ds-timeline__day {
    margin: 0;
    color: var(--ds-text-2);
    font: var(--ds-font-caption);
  }

  .ds-timeline__head {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--ds-space-1) var(--ds-space-2);
    min-height: var(--_head);
  }

  .ds-timeline__title {
    margin: 0;
    color: var(--ds-text);
    font: var(--ds-size-font, var(--ds-font-label));
    overflow-wrap: anywhere;
  }

  /* A feed reads as a sentence: who in the label weight, the rest regular. */
  .ds-timeline--activity .ds-timeline__title {
    flex: 1 1 0;
    min-width: min(12rem, 100%);
    font: var(--ds-font-body);
  }

  .ds-timeline--activity .ds-timeline__title strong {
    font-weight: var(--ds-weight-label);
  }

  .ds-timeline--activity .ds-timeline__item--muted .ds-timeline__title {
    color: var(--ds-text-2);
  }

  /* When, at the end of the head line. */
  .ds-timeline__time {
    margin-inline-start: auto;
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
  }

  .ds-timeline__meta {
    margin: 0;
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
    font-variant-numeric: tabular-nums;
  }

  /* As in .ds-meta: a leading 16px glyph fills the 16px line from its top,
     centred on the text, the line kept. */
  .ds-timeline__meta > svg:first-child {
    display: inline-block;
    margin-inline-end: var(--ds-space-1);
    vertical-align: top;
  }

  .ds-timeline__text {
    max-width: var(--ds-measure);
    margin: 0;
    color: var(--ds-text);
    font: var(--ds-font-body);
    white-space: pre-line;
    overflow-wrap: anywhere;
  }

  /* What someone wrote, in a box of its own; its border is its edge in
     forced colours too. */
  .ds-timeline__item--comment > .ds-timeline__text {
    box-sizing: border-box;
    width: fit-content;
    padding: calc(var(--ds-space-2) + var(--ds-density, 0) * 1px) var(--ds-space-3);
    border: 1px solid var(--ds-line);
    border-radius: calc(var(--ds-timeline-comment-radius, var(--ds-radius-card)) * var(--ds-shape, 1));
    background: var(--ds-timeline-comment-bg, var(--ds-surface-low));
  }

  .ds-timeline__body {
    padding-top: var(--ds-space-2);
  }

  /* Text buttons hang their padding, so their label lines up with the text:
     what .ds-btn--text sets on itself (no theme's hook reaches it), stepping
     4px per size, so give the size to this element, not to each button. */
  .ds-timeline__actions {
    display: flex;
    flex-wrap: wrap;
    gap: var(--ds-space-1);
    margin-inline-start: calc(-1 * (var(--ds-space-3) + var(--ds-size-step, 0) * 4px));
  }

  /* While entries glide (DS.motion.flip marks the list data-ds-glide with
     --ds-flip-backdrop), each stands on an opaque backing. */
  .ds-timeline[data-ds-glide] > :is(.ds-timeline__item, .ds-timeline__group) {
    background-image: linear-gradient(var(--ds-flip-backdrop, var(--ds-surface)), var(--ds-flip-backdrop, var(--ds-surface)));
  }
}

/* ── components/tasks/tasks.css ── */
/*
 * Tasks: a checklist of the steps of a job (an import, a setup, a
 * migration), each pending, running, done or failed.
 *
 *   <div class="ds-tasks__head"><h3 class="ds-card__title">Set up LAPTOP-0042</h3><p class="ds-meta">3 of 7</p></div>
 *   <ol class="ds-tasks" aria-label="Steps">
 *     <li class="ds-tasks__item" data-status="done"><span class="ds-tasks__mark">[icon checkCircle 20]</span><span class="ds-tasks__text">Copy the image<span class="ds-sr">: done</span></span></li>
 *     <li class="ds-tasks__item" data-status="running"><span class="ds-tasks__mark"><span class="ds-spinner ds-spinner--ink ds-sm"></span></span><span class="ds-tasks__text">Install updates<span class="ds-sr">: running</span></span></li>
 *     <li class="ds-tasks__item" data-status="failed"><span class="ds-tasks__mark">[icon alertCircle 20]</span><span class="ds-tasks__text">Join the domain: failed, the server did not answer</span></li>
 *     <li class="ds-tasks__item" data-status="pending"><span class="ds-tasks__mark"></span><span class="ds-tasks__text">Restart<span class="ds-sr">: waiting</span></span></li>
 *   </ol>
 *
 * The status shows in the mark's shape and the text's weight, never in
 * colour alone: pending a ring in --ds-outline, running the small spinner
 * and the label weight, done the check in a circle (--ds-success) and
 * the text in --ds-text-2, failed the alert circle in --ds-error with the
 * word in the text. Put the status into the text for screen readers too
 * (a .ds-sr word), and keep the count in the head ("3 of 7") in step. In
 * forced colours the marks take CanvasText.
 *
 * Motion: when a step turns done in place (DS.dom.morphHtml patches the
 * keyed item, so its mark stays), the tick of the new check draws itself:
 * the mark's stroke-dashoffset, which the pathLength="1" tick inherits,
 * runs from 1 to 0 over --ds-dur-medium after --ds-dur-micro. A list
 * rendered with done steps stays still on load (a transition, not a
 * keyframe).
 *
 * Options (src/core/options.css, docs/options.md), on the list or any
 * ancestor: size and density space the steps (--ds-tasks-gap, --ds-space-2,
 * 2px per size step and per density step, at least none). They leave the
 * body font and the 20px mark alone: the mark is a glyph on the text's first
 * line. Shape multiplies the radius of the pending ring (half its size: round
 * at the default, rounded corners at soft, square at square); the spinner and
 * the check in a circle are round glyphs, no radius. A step is no target and shows its
 * status by its own colours, so touch and tone do not apply.
 */

@layer ds.components.tasks {
  .ds-tasks__head {
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    justify-content: space-between;
    gap: var(--ds-space-1) var(--ds-space-3);
  }

  /* No top margin of its own: inside a card the card's rhythm spaces it
     (zero weight). */
  :where(.ds-tasks) {
    margin-top: 0;
  }

  .ds-tasks {
    display: grid;
    gap: max(0px, calc(var(--ds-tasks-gap, var(--ds-space-2)) + var(--ds-size-step, 0) * 2px + var(--ds-density, 0) * 2px));
    margin-inline: 0;
    margin-bottom: 0;
    padding: 0;
    list-style: none;
  }

  .ds-tasks:empty {
    display: none;
  }

  .ds-tasks__item {
    display: flex;
    align-items: flex-start;
    gap: var(--ds-space-3);
    color: var(--ds-text);
    font: var(--ds-font-body);
  }

  /* The mark sits on the first line of the text (20px). */
  .ds-tasks__mark {
    display: grid;
    flex: none;
    place-items: center;
    width: var(--ds-space-5);
    height: var(--ds-space-5);
    color: var(--ds-text-2);
    /* Inherited by the tick of a done step: undrawn until the step is done. */
    stroke-dashoffset: 1;
    transition: stroke-dashoffset var(--ds-dur-medium) var(--ds-ease-out) var(--ds-dur-micro);
  }

  .ds-tasks__text {
    min-width: 0;
    overflow-wrap: anywhere;
  }

  .ds-tasks__item[data-status="pending"] .ds-tasks__mark::before {
    content: '';
    box-sizing: border-box;
    width: var(--ds-space-4);
    height: var(--ds-space-4);
    border: 2px solid var(--ds-outline);
    border-radius: min(calc(min(var(--ds-radius-action), calc(var(--ds-space-4) / 2)) * var(--ds-shape, 1)), calc(var(--ds-space-4) / 2));
  }

  .ds-tasks__item[data-status="running"] .ds-tasks__mark {
    color: var(--ds-primary);
  }

  .ds-tasks__item[data-status="running"] .ds-tasks__text {
    font-weight: var(--ds-weight-label);
  }

  .ds-tasks__item[data-status="done"] .ds-tasks__mark {
    color: var(--ds-success);
    stroke-dashoffset: 0;
  }

  .ds-tasks__item[data-status="done"] .ds-tasks__text {
    color: var(--ds-text-2);
  }

  .ds-tasks__item[data-status="done"] .ds-tasks__mark [pathLength] {
    stroke-dasharray: 1;
  }

  .ds-tasks__item[data-status="failed"] .ds-tasks__mark {
    color: var(--ds-error);
  }

  @media (forced-colors: active) {
    .ds-tasks__mark,
    .ds-tasks__item[data-status] .ds-tasks__mark {
      color: CanvasText;
    }

    .ds-tasks__item[data-status="pending"] .ds-tasks__mark::before {
      border-color: CanvasText;
    }
  }
}

/* ── components/status/status.css ── */
/*
 * Status chip: icon and text on the tonal container of its status, never
 * colour alone. A running state turns the small spinner instead of an
 * icon; keep that node when the label changes, so it never restarts.
 *
 *   <span class="ds-status ds-tone-success"><svg ...>(check, 16)</svg><span>Synced</span></span>
 *   <span class="ds-status ds-status--running"><span class="ds-spinner ds-status__spinner" aria-hidden="true"></span><span>Running</span></span>
 *
 *   .ds-tone-success  -warning  -error  -info  -primary  -neutral
 *   --running   a neutral chip with the primary spinner
 *   (none)      neutral, e.g. idle or off, told apart by the icon
 *
 * Options (docs/options.md), computed here into --_h:
 *   size      .ds-xs ... .ds-xl on the chip or any ancestor: 4px per step
 *             (16 ... 32px, 2px of side padding per step). The caption type
 *             and the icon's markup size stay.
 *   shape     the radius times --ds-shape (a one-line chip stays round up to
 *             half its height)
 *   tone      from the class on the chip itself: an inherited tone never
 *             recolours a chip, and a chip always has its icon and word
 *   density, target-min: not read. A chip is no target and has no room to
 *             lose: it sits in a line, like a badge, so the compact theme
 *             keeps 2.x's 24px. A smaller chip is .ds-sm.
 *
 * Fully round at one line (radius = half the height); a long label that
 * wraps keeps soft corners instead of turning into a stadium.
 * Hooks: --ds-status-height (24px, the md base), --ds-status-radius,
 * --ds-status-spinner-width (2px, the ring of the running spinner).
 *
 * Status changes glide, for a user action and a poll alike: colour and
 * icon change smoothly for every status change, the text at once. The
 * container and its icon change colour over --ds-dur-medium; render with
 * DS.dom.morphHtml, which patches the kept span in place, so the class
 * change transitions instead of replacing the chip. An icon or spinner
 * that comes in new (running to ok) fades in and springs up from
 * --ds-scale-small, like the incoming face of .ds-icon-swap; a page that
 * swaps the icon itself can use DS.motion.crossfade(chip, icon, { kind:
 * 'icon' }). What glides and what changes at once: docs/motion.md, "Data
 * motion".
 *
 * Tag: a label of words ("Preview", "Beta", "External"), not a state and
 * not a count; not interactive.
 *
 *   <span class="ds-tag">Preview</span>
 *   <span class="ds-tag ds-tone-neutral">(tag 16)External</span>
 *
 * The caption type on the tint (--ds-tag-bg / --ds-tag-color, from
 * --ds-accent / --ds-on-accent; a tone: its container pair, neutral
 * --ds-surface-high / --ds-text), an optional leading 16px icon in
 * --ds-on-accent-icon, the pill radius min(--ds-radius-action, half its
 * height) times --ds-shape. Size as on the chip, no density. Forced
 * colours: a CanvasText outline. Tag = words, badge (.ds-badge) = counts,
 * status chip = a state with an icon. Hooks: --ds-tag-bg, --ds-tag-color,
 * --ds-tag-height (24px, the md base).
 *
 * @starting-style (at the floor) brings the incoming icon's fade and scale;
 * it also plays on the first render of a chip, never on a keyed move: where
 * moveBefore is missing, morphHtml marks a moved row data-ds-moving for one
 * style flush (motion.css).
 */

@layer ds.components.status {
  .ds-status {
    --_h: calc(var(--ds-status-height, 24px) + var(--ds-size-step, 0) * 4px);
    /* Round at one line whatever the size; a label that wraps keeps these
       corners instead of a stadium, since the half is of one line's height. */
    --_round: max(var(--ds-radius-md), calc(var(--_h) / 2));
    display: inline-flex;
    align-items: center;
    gap: var(--ds-space-1);
    min-height: var(--_h);
    max-width: 100%;
    padding-block: max(0px, calc((var(--_h) - 1lh) / 2));
    padding-inline: calc(6px + var(--ds-size-step, 0) * 2px) calc(var(--ds-space-2) + var(--ds-size-step, 0) * 2px);
    border-radius: calc(var(--ds-status-radius, var(--_round)) * var(--ds-shape, 1));
    background: var(--ds-surface-high);
    color: var(--ds-text-2);
    font: var(--ds-font-caption);
    vertical-align: middle;
    transition:
      background-color var(--ds-dur-medium) var(--ds-ease-in-out),
      color var(--ds-dur-medium) var(--ds-ease-in-out);
  }

  .ds-status > svg {
    flex-shrink: 0;
  }

  /* The icon's colour follows the modifier on the container's timing; an
     icon or spinner that comes in new fades in and springs up. */
  .ds-status > :is(svg, .ds-spinner) {
    transition:
      color var(--ds-dur-medium) var(--ds-ease-in-out),
      opacity var(--ds-dur-fast) var(--ds-ease-in-out),
      scale var(--ds-dur-fast) var(--ds-ease-spatial);
  }

  @starting-style {
    .ds-status > :is(svg, .ds-spinner) {
      opacity: 0;
      scale: var(--ds-scale-small);
    }
  }

  /* A tone from the class on the chip itself (.ds-tone-* sets the pair). */
  .ds-status:is(.ds-tone-neutral, .ds-tone-primary, .ds-tone-info, .ds-tone-success, .ds-tone-warning, .ds-tone-error) {
    background: var(--ds-tone-container);
    color: var(--ds-on-tone-container);
  }

  /* The neutral chip keeps its quieter ink. */
  .ds-status.ds-tone-neutral {
    color: var(--ds-text-2);
  }

  .ds-status.ds-tone-success > svg {
    color: var(--ds-success);
  }

  /* Running: a neutral chip with the primary spinner. */
  .ds-status--running {
    color: var(--ds-text);
  }

  /* The arc at its own pace, the turn a little faster than on a surface. */
  .ds-status__spinner {
    --ds-spinner-width: var(--ds-status-spinner-width, 2px);
    width: 14px;
    height: 14px;
    margin: 1px;
    animation-duration: var(--ds-loop-arc), var(--ds-loop-spin-fast);
  }

  /* Tag: words on the tint, a pill at one line. */
  .ds-tag {
    --_h: calc(var(--ds-tag-height, 24px) + var(--ds-size-step, 0) * 4px);
    /* min-height: the line can outgrow the height (a large type scale). */
    --_half: calc(max(var(--_h), 1lh) / 2);
    display: inline-flex;
    align-items: center;
    gap: var(--ds-space-1);
    min-height: var(--_h);
    max-width: 100%;
    padding: 0 calc(var(--ds-space-2) + var(--ds-size-step, 0) * 2px);
    border-radius: min(calc(min(var(--ds-radius-action), var(--_half)) * var(--ds-shape, 1)), var(--_half));
    background: var(--ds-tag-bg, var(--ds-accent));
    color: var(--ds-tag-color, var(--ds-on-accent));
    font: var(--ds-font-caption);
    white-space: nowrap;
    vertical-align: middle;
  }

  .ds-tag > svg {
    flex-shrink: 0;
    width: 16px;
    height: 16px;
    color: var(--ds-on-accent-icon);
  }

  .ds-tag:has(> svg:first-child) {
    padding-inline-start: calc(6px + var(--ds-size-step, 0) * 2px);
  }

  /* A tone from the class on the tag itself; words, so never colour alone. */
  .ds-tag:is(.ds-tone-neutral, .ds-tone-primary, .ds-tone-info, .ds-tone-success, .ds-tone-warning, .ds-tone-error) {
    --ds-tag-bg: var(--ds-tone-container);
    --ds-tag-color: var(--ds-on-tone-container);
  }

  .ds-tag:is(.ds-tone-neutral, .ds-tone-primary, .ds-tone-info, .ds-tone-success, .ds-tone-warning, .ds-tone-error) > svg {
    color: inherit;
  }

  .ds-tag.ds-tone-neutral {
    --ds-tag-bg: var(--ds-surface-high);
    --ds-tag-color: var(--ds-text);
  }

  .ds-tag.ds-tone-neutral > svg {
    color: var(--ds-text-2);
  }

  @media (forced-colors: active) {
    .ds-tag {
      outline: 1px solid CanvasText;
      outline-offset: -1px;
    }
  }
}

/* ── components/alert/alert.css ── */
/*
 * Alerts: notices on tonal containers with an icon, never colour alone.
 * The neutral alert has no colour of its own: the quiet surface and the
 * icon in the primary colour.
 *
 *   <div class="ds-alert ds-tone-warning" role="status">
 *     <svg ...>(alert, 20)</svg>
 *     <span class="ds-alert__text">The certificate expires in 5 days.</span>
 *     <button class="ds-btn ds-btn--text ds-sm" type="button">Renew</button>
 *   </div>
 *
 *   (none: neutral info)  .ds-tone-success  -warning  -error  -info  -primary  -neutral
 *   .ds-alert--plain      a finding in a card: no fill, no edge, no inline
 *                         padding, no radius; hairlines between consecutive
 *                         plain alerts (a preset of the hooks below)
 *   .ds-alert--inline     an inline message, under a field or in a row: icon
 *                         and meta text on the surface, no box
 *   .ds-alert--section    a section message: a block with a title, room around
 *                         it and its actions always under the text
 *
 * Options (docs/options.md), read here:
 *   size      .ds-xs ... .ds-xl on the alert or any ancestor: 2px of padding
 *             per step (its buttons take the same step). Type and icon stay.
 *   density   any container: 2px of padding per step; type and icon stay.
 *             So the compact theme (density -2) pads it 8/12px, 2.x's 12/16
 *             with less room, on purpose.
 *   shape     the radius times --ds-shape (--plain and --inline have none)
 *   tone      from the class on the alert itself (an inherited tone never
 *             recolours it); the icon and the word stay, never colour alone
 *   target-min: its buttons and the .ds-errors summary read it, the alert
 *             itself is no target. A button taller than the line and its
 *             padding makes the alert grow: the box always holds it.
 *
 * A title, more paragraphs and actions:
 *
 *   <div class="ds-alert ds-tone-warning">
 *     <svg ...>(alert, 20)</svg>
 *     <div class="ds-alert__text"><p class="ds-alert__title">Certificate expires soon</p><p>Renew it before 1 May.</p></div>
 *     <div class="ds-alert__actions"><button class="ds-btn ds-btn--text ds-sm" type="button">Renew</button></div>
 *   </div>
 *
 * With .ds-alert__actions the alert wraps: the text takes at least
 * --ds-alert-text-basis (256px) and the actions drop under it when the row
 * is narrow. Static findings carry no live role.
 *
 * Hooks: --ds-alert-bg (--ds-surface-low), --ds-alert-color (--ds-text),
 * --ds-alert-icon (--ds-primary; also the edge colour), --ds-alert-edge
 * (the width of a leading edge, 0), --ds-alert-radius (--ds-radius-card),
 * --ds-alert-padding-block (12px) and --ds-alert-padding-inline (16px),
 * the md bases, and per tone (success, warning, error)
 * --ds-alert-<kind>-bg, --ds-alert-<kind>-color, --ds-alert-<kind>-icon
 * with today's values as fallbacks; error buttons take
 * --ds-alert-error-color; --ds-alert-text-basis. Forced colours: a
 * transparent outline becomes the edge of a box.
 *
 * The summary of .ds-errors is a pressable part: a state layer in its
 * colour (hover, press in --ds-dur-micro, focus with --ds-state-focus) in
 * a 4px padding that hangs into the space around it, the ripple
 * (js/ripple.js), and its own ring for keyboard focus (also without
 * .ds-base): solid from the first frame, it snaps from offset + width to
 * the offset (outline-offset, --ds-dur-fast). It is not a pill and does
 * not morph. Its chevron (.ds-errors__chevron) turns 180deg with the list
 * on the spring, like .ds-chevron; <details class="ds-errors
 * ds-collapsible"> opens the list with the collapsible timing.
 *
 * Inserting and dismissing (docs/motion.md, "Data motion"): through
 * DS.motion.flip on the stack, for a user action and live data alike.
 * Dismiss: flip(stack, () => alert.remove()): the alert fades out in place,
 * out of flow, and the alerts below glide up on the spring (in any flex or
 * grid gap, no height animated). Insert: flip(stack, () =>
 * stack.prepend(alert)): it fades in while the others glide down.
 */

@layer ds.components.alert {
  /* No entrance of their own: an alert re-rendered with fresh data is
     patched in place and never fades in again. An alert that comes or goes
     (a user action or live data) does it through DS.motion.flip on its
     stack (the header above); one that replaces a placeholder takes
     .ds-reveal, never per update. */

  /* The block padding is at least the hang of its button (--_btn, set below
     when it has one), so the button stays inside and centred on the line. */
  .ds-alert {
    --_pad-block: max(calc(var(--ds-alert-padding-block, var(--ds-space-3)) + var(--ds-size-step, 0) * 2px + var(--ds-density, 0) * 2px), calc((var(--_btn, 0px) - var(--ds-space-5)) / 2));
    display: flex;
    align-items: flex-start;
    gap: var(--ds-space-3);
    padding: var(--_pad-block) calc(var(--ds-alert-padding-inline, var(--ds-space-4)) + var(--ds-size-step, 0) * 2px + var(--ds-density, 0) * 2px);
    border-inline-start: var(--ds-alert-edge, 0px) solid var(--ds-alert-icon, var(--ds-primary));
    border-radius: calc(var(--ds-alert-radius, var(--ds-radius-card)) * var(--ds-shape, 1));
    background: var(--ds-alert-bg, var(--ds-surface-low));
    color: var(--ds-alert-color, var(--ds-text));
    font: var(--ds-font-body);
  }

  .ds-alert > svg {
    flex-shrink: 0;
    color: var(--ds-alert-icon, var(--ds-primary));
  }

  /* The 20px icon and a 20px line share one baseline. */
  .ds-alert__text {
    flex: 1;
    min-width: 0;
    overflow-wrap: anywhere;
  }

  /* The height of its button, which the alert cannot read: it computes the
     button's, one size step down when the button carries .ds-sm itself. */
  .ds-alert:has(> .ds-btn, > .ds-alert__actions) {
    --_btn: max(var(--ds-target-min, 0px), calc(var(--ds-btn-height, 40px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px));
  }

  .ds-alert:has(> .ds-btn.ds-sm, > .ds-alert__actions > .ds-btn.ds-sm) {
    --_btn: max(var(--ds-target-min, 0px), calc(var(--ds-btn-height, 40px) - 8px + var(--ds-density, 0) * 4px));
  }

  /* The button hangs out of the 20px text line by the same amount above and
     below, so its label sits on the text's centre line and the banner keeps
     its even padding. Never further than the padding: a button of another
     size stays inside the box too. */
  .ds-alert .ds-btn {
    flex-shrink: 0;
    margin-block: max(calc(-1 * var(--_pad-block)), calc((var(--ds-space-5) - max(var(--ds-target-min, 0px), calc(var(--ds-btn-height, 40px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px))) / 2));
    margin-inline: auto calc(-1 * var(--ds-space-2));
  }

  /* A title and more paragraphs in the text. */
  .ds-alert__title {
    display: block;
    color: inherit;
    font: var(--ds-font-label);
  }

  .ds-alert__text > p {
    margin: 0;
  }

  .ds-alert__text > p + p {
    margin-top: var(--ds-space-2);
  }

  /* Actions in a row after the text: the row hangs out of the text line as
     a single button would, its buttons sit side by side. */
  .ds-alert__actions {
    display: flex;
    flex-wrap: wrap;
    flex-shrink: 0;
    gap: var(--ds-space-1);
    margin-block: max(calc(-1 * var(--_pad-block)), calc((var(--ds-space-5) - var(--_btn)) / 2));
    margin-inline: auto calc(-1 * var(--ds-space-2));
  }

  .ds-alert__actions > .ds-btn {
    margin: 0;
  }

  .ds-alert:has(> .ds-alert__actions) {
    flex-wrap: wrap;
  }

  .ds-alert:has(> .ds-alert__actions) > .ds-alert__text {
    flex: 1 1 var(--ds-alert-text-basis, 256px);
  }

  .ds-alert a {
    color: inherit;
  }

  /* The tones set the alert's hooks from their own, with today's colours as
     fallbacks, from the class on the alert itself. Zero weight on the tone,
     so --plain, --inline and --section below still decide by order. */
  .ds-alert:where(.ds-tone-success) {
    --ds-alert-bg: var(--ds-alert-success-bg, var(--ds-success-container));
    --ds-alert-color: var(--ds-alert-success-color, var(--ds-on-success-container));
    --ds-alert-icon: var(--ds-alert-success-icon, var(--ds-success));
  }

  .ds-alert:where(.ds-tone-warning) {
    --ds-alert-bg: var(--ds-alert-warning-bg, var(--ds-warning-surface));
    --ds-alert-color: var(--ds-alert-warning-color, var(--ds-text));
    --ds-alert-icon: var(--ds-alert-warning-icon, var(--ds-warning));
  }

  .ds-alert:where(.ds-tone-error) {
    --ds-alert-bg: var(--ds-alert-error-bg, var(--ds-error-container));
    --ds-alert-color: var(--ds-alert-error-color, var(--ds-on-error-container));
    --ds-alert-icon: var(--ds-alert-error-icon, var(--ds-error));
  }

  /* A filled or tonal button keeps the ink of its own fill. */
  .ds-alert:where(.ds-tone-error):not(.ds-alert--plain, .ds-alert--inline) .ds-btn:not(.ds-btn--filled, .ds-btn--tonal) {
    --ds-btn-color: var(--ds-alert-error-color, var(--ds-on-error-container));
  }

  .ds-alert:where(.ds-tone-neutral, .ds-tone-primary, .ds-tone-info) {
    --ds-alert-bg: var(--ds-tone-container);
    --ds-alert-color: var(--ds-on-tone-container);
    --ds-alert-icon: var(--ds-tone);
  }

  /* Plain: a finding in a card, on the card's own surface. A preset of the
     hooks (after the kinds: their icon stays), hairlines between
     consecutive ones. */
  .ds-alert--plain {
    --ds-alert-bg: transparent;
    --ds-alert-color: var(--ds-text);
    --ds-alert-edge: 0;
    padding-inline: 0;
    border-radius: 0;
  }

  .ds-alert--plain + .ds-alert--plain {
    border-top: 1px solid var(--ds-line);
  }

  /* An inline message, under a field or in a row: the icon in the tone and
     the word on the surface, in the meta type; no box to pad or round, so
     size, density and shape have nothing to change. */
  .ds-alert--inline {
    --_pad-block: 0px;
    --ds-alert-bg: transparent;
    --ds-alert-color: var(--ds-text);
    --ds-alert-edge: 0;
    display: inline-flex;
    gap: var(--ds-space-1);
    margin: 0;
    padding: 0;
    border-radius: 0;
    font: var(--ds-font-meta);
  }

  /* With no padding to hang into, its button makes the row and the words
     centre on it. */
  .ds-alert--inline:has(> .ds-btn, > .ds-alert__actions) {
    align-items: center;
  }

  /* A section message: a block with a title, its actions always under the
     text in the text's column, so nothing hangs. */
  .ds-alert--section {
    --_pad-block: calc(var(--ds-alert-padding-block, var(--ds-space-4)) + var(--ds-size-step, 0) * 2px + var(--ds-density, 0) * 2px);
    display: grid;
    grid-template-columns: auto minmax(0, 1fr);
    padding: var(--_pad-block) calc(var(--ds-alert-padding-inline, var(--ds-space-5)) + var(--ds-size-step, 0) * 2px + var(--ds-density, 0) * 2px);
  }

  .ds-alert--section .ds-alert__title {
    margin-bottom: var(--ds-space-1);
    font: var(--ds-font-subtitle);
  }

  .ds-alert--section > :is(.ds-alert__actions, .ds-btn) {
    grid-column: 2;
    justify-self: start;
    margin: var(--ds-space-2) 0 0;
  }

  /* Forced colours drop the fill: a transparent outline becomes the edge. */
  @media (forced-colors: active) {
    .ds-alert:not(.ds-alert--plain, .ds-alert--inline) {
      outline: 1px solid transparent;
      outline-offset: -1px;
    }
  }

  /* Code in a tonal alert is told apart by the typeface alone. */
  .ds-alert code {
    padding: 0;
    border: 0;
    background: none;
    color: inherit;
  }

  /* Collapsible list of messages: icon and text in the summary.

     <details class="ds-errors ds-collapsible"><summary><svg ...>(alertCircle)</svg>2 errors<svg class="ds-errors__chevron" ...>(chevronDown)</svg></summary><ul><li>...</li></ul></details> */
  .ds-errors {
    font: var(--ds-font-body);
  }

  /* Its 4px padding (the room of its state layer) hangs into the space
     around it, like the table's sort button, so the text keeps its place. */
  .ds-errors summary {
    position: relative;
    isolation: isolate;
    display: inline-flex;
    align-items: center;
    gap: var(--ds-space-2);
    min-height: var(--ds-target-min, 0px);
    margin: calc(-1 * var(--ds-space-1));
    padding: var(--ds-space-1);
    border-radius: calc(var(--ds-radius-xs) * var(--ds-shape, 1));
    color: var(--ds-on-error-container);
    font: var(--ds-font-label);
    cursor: pointer;
    -webkit-tap-highlight-color: transparent;
    /* The ring rests (invisible) one width further out and snaps in. */
    outline-offset: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    transition: outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  /* State layer in the content colour. */
  .ds-errors summary::before {
    content: '';
    position: absolute;
    inset: 0;
    z-index: -1;
    border-radius: inherit;
    background: currentColor;
    opacity: 0;
    pointer-events: none;
    transition: opacity var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  @media (hover: hover) {
    .ds-errors summary:hover::before {
      opacity: var(--ds-state-hover);
    }
  }

  /* Keyboard focus: the layer appears with the ring and fades out on blur. */
  .ds-errors summary:focus-visible::before {
    opacity: var(--ds-state-focus);
    transition-duration: 0s;
  }

  /* Press-in in --ds-dur-micro (.ds-pressed: js/ripple.js holds it). */
  .ds-errors summary:active::before,
  .ds-errors summary.ds-pressed::before {
    opacity: var(--ds-state-pressed);
    transition-duration: var(--ds-dur-micro);
  }

  .ds-errors summary:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: var(--ds-focus-offset);
  }

  .ds-errors summary svg {
    flex-shrink: 0;
    color: var(--ds-error);
  }

  /* Its own bullets: a layered reset (list-style: none on ul) would leave
     the indent without its markers. */
  .ds-errors ul {
    list-style-type: disc;
    margin: var(--ds-space-2) 0 0;
    padding-inline-start: var(--ds-space-5);
    color: var(--ds-text-2);
    overflow-wrap: anywhere;
  }

  .ds-errors li + li {
    margin-top: var(--ds-space-1);
  }

  .ds-errors summary::-webkit-details-marker {
    display: none;
  }

  /* The disclosure chevron turns 180deg with the expansion (D25), on the
     timing of .ds-chevron. */
  .ds-errors .ds-errors__chevron {
    color: inherit;
    transition: rotate var(--ds-dur-medium) var(--ds-ease-spatial);
  }

  .ds-errors[open] .ds-errors__chevron {
    rotate: 180deg;
  }
}

/* ── components/switch/switch.css ── */
/*
 * Switch (Material 3, 52 x 32) with its name and a state word next to it,
 * so the state never shows through the handle position and colour alone.
 * The word is hidden from screen readers, which announce the switch state
 * itself. With both words in the markup the CSS shows the right one and
 * crossfades them (the leaving word fades, the other rises in); a single
 * word still works, and then the page keeps it in step.
 *
 *   <label class="ds-switch">
 *     <input type="checkbox" role="switch" name="sync" checked>
 *     <span class="ds-switch__track" aria-hidden="true"></span>
 *     <span class="ds-switch__label">Nightly sync</span>
 *     <span class="ds-switch__state" aria-hidden="true"><span class="ds-switch__on">On</span><span class="ds-switch__off">Off</span></span>
 *   </label>
 *
 *   single word:  <span class="ds-switch__state" aria-hidden="true">On</span>
 *
 * Options (src/core/options.css, docs/options.md), on the switch or any
 * ancestor; each is computed here, in the switch's own rule:
 *   size      .ds-xs ... .ds-xl: 4px of track per step (24, 28, 32, 36, 40px;
 *             the width, the handle, its travel and the icon follow), 8px of
 *             row and halo per step, the name in the size's type role
 *   density   .ds-density-*: 4px of row per step (a list row 4px and 2px of
 *             padding); never the track, which is a target with no label
 *   shape     .ds-shape-*: multiplies the track's and the handle's radius (at
 *             most half their height: a pill at the default, square at 0)
 *   touch     .ds-touch: a row and a halo of at least --ds-touch-target
 *
 * The handle travels and grows on the spatial spring (translate and scale,
 * --ds-dur-medium), also when the page sets `checked`; it never renders
 * above its 28px pressed size (at md). Pressed it grows to 28px (--ds-dur-instant),
 * and a halo around it (the switch's press feedback, no ripple) shows
 * hover, press and keyboard focus. Keyboard focus also rings the track:
 * solid from the first frame, it snaps from offset + width to the offset
 * (outline-offset, --ds-dur-fast). Disabled: the neutral Material look
 * (--ds-disabled-fill track, --ds-disabled-ink handle), no hover, halo or
 * grow; it fades in on --ds-dur-fast (opacity, the name and the word) with
 * the colours of the track.
 *
 * The input covers the track (a native hit target, also for a tooltip:
 * data-tip goes on the input); the track takes no pointer.
 *
 * Blocked with a reason: aria-disabled="true" on the input looks and acts
 * like disabled (no hover, halo, grow; the click is blocked by the action
 * guard) but stays focusable, so its tooltip can say why; the ring and the
 * focus halo stay.
 *
 * Locked (a value another system sets): .ds-switch--locked, always with
 * aria-disabled="true" and the reason in words. Its on and off looks keep
 * full strength; the lock glyph rides the handle (the track's last child):
 *
 *   <label class="ds-switch ds-switch--locked">
 *     <input type="checkbox" role="switch" checked aria-disabled="true" aria-describedby="sync-why">
 *     <span class="ds-switch__track" aria-hidden="true"><svg class="ds-switch__icon" ...>(lock, 16)</svg></span>
 *     <span class="ds-switch__label">Nightly sync</span>
 *     <small class="ds-switch__hint" id="sync-why">Set by the device policy</small>
 *   </label>
 *
 * The off handle grows to 24px (6/7) so the lock fits; the lock travels
 * with it (translate, --ds-dur-medium on the spring), in
 * --ds-surface-highest on the off handle and --ds-primary on the on handle,
 * and fades in on --ds-dur-fast, out on --ds-dur-instant.
 *
 * With icons: .ds-switch--icons shows one glyph per state on the handle,
 * crossfading while it travels (both handles at 24px, as with the lock):
 *
 *   <label class="ds-switch ds-switch--icons">
 *     <input type="checkbox" role="switch" checked>
 *     <span class="ds-switch__track" aria-hidden="true"><svg class="ds-switch__icon ds-switch__icon--off" ...>(close, 16)</svg><svg class="ds-switch__icon ds-switch__icon--on" ...>(check, 16)</svg></span>
 *     <span class="ds-switch__label">Nightly sync</span>
 *   </label>
 *
 * Busy: while the page waits for the answer, aria-busy="true" together with
 * aria-disabled="true" on the input (the action guard blocks the click, Space
 * and a label click; the switch stays focusable). On and off keep full
 * strength, no hover, halo or grow; the handle holds a spinner, which shows
 * only after --ds-delay-loader, so a fast answer shows nothing:
 *
 *   <span class="ds-switch__track" aria-hidden="true"><span class="ds-spinner ds-switch__spinner"></span></span>
 *
 * Hint and extras: small.ds-switch__hint (a line under the name, the meta
 * type), span.ds-switch__meta (non-interactive extras before the state
 * word: a count, a tag); the label wraps long words. A switch with a hint
 * lays its parts on a small grid, the hint under the name; the name and
 * its hint stand together and the text centres on the track.
 *
 * Many settings, each a switch: .ds-switch-list holds .ds-switch rows on a
 * grid (track, name over hint, meta, state), at least
 * --ds-switch-list-row-height (56px), hairlines between; the text centres
 * on the track with or without a hint; at 560px and below the meta wraps
 * under the name. Name each input with
 * aria-labelledby (its .ds-switch__label) and describe it with
 * aria-describedby (its hint), so the extras stay out of its name.
 *
 * Forced colours: system colours for on and off (Highlight, CanvasText),
 * GrayText when blocked; a locked or busy switch keeps on and off; a focused
 * checked switch rings in CanvasText.
 *
 * Hooks: --ds-switch-height (40px), --ds-switch-track-height (32px),
 * --ds-switch-halo (40px), --ds-switch-font, --ds-switch-disabled-track,
 * --ds-switch-disabled-handle, --ds-switch-list-row-height (56px). The
 * computed values (--_t, --_w, --_handle, --_travel and the like) are
 * private: never set them.
 *
 * Print: track and handle keep their colours (print-color-adjust), so on
 * and off show on paper next to the state word.
 */

@layer ds.components.switch {
  .ds-switch {
    /* The options, computed here (docs/options.md). The track: 4px per size
       step, its width in the 52 : 32 of the base. */
    --_t: calc(var(--ds-switch-track-height, 32px) + var(--ds-size-step, 0) * 4px);
    --_w: calc(var(--_t) * 13 / 8);
    /* The handle's box inside the 2px border (28px at md), its travel and the
       icon on it. */
    --_handle: calc(var(--_t) - 4px);
    --_travel: calc(var(--_w) - var(--_t));
    --_icon: calc(var(--_handle) * 4 / 7);
    /* Corners: at most half the height, times the shape. */
    --_track-radius: min(calc(min(var(--ds-radius-action), calc(var(--_t) / 2)) * var(--ds-shape, 1)), calc(var(--_t) / 2));
    --_handle-radius: min(calc(min(var(--ds-radius-action), calc(var(--_handle) / 2)) * var(--ds-shape, 1)), calc(var(--_handle) / 2));
    /* The halo, a target with no label: size only, the touch minimum wins. */
    --_halo: max(var(--ds-target-min, 0px), calc(var(--ds-switch-halo, 40px) + var(--ds-size-step, 0) * 8px));
    /* The row: 8px per size step, 4px per density step, the touch minimum. */
    --_box: max(var(--ds-target-min, 0px), calc(var(--ds-switch-height, 40px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px));
    position: relative;
    display: inline-flex;
    align-items: center;
    gap: var(--ds-space-3);
    min-height: var(--_box);
    color: var(--ds-text);
    font: var(--ds-switch-font, var(--ds-size-font, var(--ds-font-label)));
    cursor: pointer;
  }

  /* The input covers the track: the native hit target (and a tooltip's
     trigger); the track below takes no pointer. */
  .ds-switch input {
    position: absolute;
    inset-block: 0;
    inset-inline-start: 0;
    width: var(--_w);
    height: var(--_t);
    margin: auto 0;
    appearance: none;
    opacity: 0;
    cursor: inherit;
  }

  .ds-switch__track {
    position: relative;
    /* The lock (z-index) stays inside the track. */
    isolation: isolate;
    flex-shrink: 0;
    width: var(--_w);
    height: var(--_t);
    border: 2px solid var(--ds-outline);
    border-radius: var(--_track-radius);
    background: var(--ds-surface-highest);
    /* The ring rests (invisible) one width further out and snaps in. */
    outline-offset: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    pointer-events: none;
    transition:
      background-color var(--ds-dur-base) var(--ds-ease-in-out),
      border-color var(--ds-dur-base) var(--ds-ease-in-out),
      opacity var(--ds-dur-fast) var(--ds-ease-in-out),
      outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  /* The handle is the pressed box at the start of the padding box (at md 28px
     in 48 x 28, centre 14, 14), scaled down: 16px off, 24px on, 28px while
     pressed, so it never renders above 1. It travels and grows on the
     spatial spring (translate and scale; the spring from 6/7 peaks below
     1), the press grows it fast and decelerating, the colour changes on
     the standard curve. */
  /* Physical on purpose (D9): the handle and its halo start at the left
     and travel on translate (mirrored motion is not part of 2.0). */
  .ds-switch__track::after {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    width: var(--_handle);
    height: var(--_handle);
    border-radius: var(--_handle-radius);
    background: var(--ds-outline);
    scale: calc(4 / 7);
    transition:
      translate var(--ds-dur-medium) var(--ds-ease-spatial),
      scale var(--ds-dur-medium) var(--ds-ease-spatial),
      background-color var(--ds-dur-base) var(--ds-ease-in-out);
  }

  /* The halo: a circle centred on the handle box that moves with it on
     the same spring; the switch's state layer (hover, press, focus) and
     its press feedback (no ripple). */
  .ds-switch__track::before {
    content: '';
    position: absolute;
    top: calc((var(--_handle) - var(--_halo)) / 2);
    left: calc((var(--_handle) - var(--_halo)) / 2);
    width: var(--_halo);
    height: var(--_halo);
    border-radius: 50%;
    background: currentColor;
    color: var(--ds-text);
    opacity: 0;
    pointer-events: none;
    transition:
      translate var(--ds-dur-medium) var(--ds-ease-spatial),
      opacity var(--ds-dur-fast) var(--ds-ease-in-out),
      color var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  /* Hover darkens the resting handle (Material 3: on-surface-variant) and
     lights the halo; only on a switch that can change. */
  @media (hover: hover) {
    .ds-switch:hover input:not(:checked):not(:disabled, [aria-disabled="true"]) + .ds-switch__track::after {
      background: var(--ds-text-2);
    }

    .ds-switch:hover input:not(:disabled, [aria-disabled="true"]) + .ds-switch__track::before {
      opacity: var(--ds-state-hover);
    }
  }

  .ds-switch input:checked + .ds-switch__track {
    border-color: var(--ds-primary);
    background: var(--ds-primary);
  }

  .ds-switch input:checked + .ds-switch__track::after {
    background: var(--ds-on-primary);
    translate: var(--_travel) 0;
    scale: calc(6 / 7);
  }

  .ds-switch input:checked + .ds-switch__track::before {
    color: var(--ds-primary);
    translate: var(--_travel) 0;
  }

  .ds-switch input:focus-visible + .ds-switch__track {
    outline: var(--ds-focus-outline);
    outline-offset: var(--ds-focus-offset);
  }

  /* Keyboard focus: the halo appears with the ring (it fades out on blur);
     a toggle meanwhile still glides. */
  .ds-switch input:focus-visible + .ds-switch__track::before {
    opacity: var(--ds-state-focus);
    transition:
      translate var(--ds-dur-medium) var(--ds-ease-spatial),
      opacity 0s,
      color var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  /* Pressed (also a static .ds-pressed): the handle grows to its full 28px
     (Material 3) and the off handle darkens; the halo takes the press. The
     release springs back with the travel. */
  .ds-switch:active input:not(:disabled, [aria-disabled="true"]) + .ds-switch__track::after,
  .ds-switch.ds-pressed input:not(:disabled, [aria-disabled="true"]) + .ds-switch__track::after {
    scale: 1;
    transition:
      translate var(--ds-dur-medium) var(--ds-ease-spatial),
      scale var(--ds-dur-instant) var(--ds-ease-out),
      background-color var(--ds-dur-base) var(--ds-ease-in-out);
  }

  .ds-switch:active input:not(:checked):not(:disabled, [aria-disabled="true"]) + .ds-switch__track::after,
  .ds-switch.ds-pressed input:not(:checked):not(:disabled, [aria-disabled="true"]) + .ds-switch__track::after {
    background: var(--ds-text);
  }

  .ds-switch:active input:not(:disabled, [aria-disabled="true"]) + .ds-switch__track::before,
  .ds-switch.ds-pressed input:not(:disabled, [aria-disabled="true"]) + .ds-switch__track::before {
    opacity: var(--ds-state-pressed);
    transition:
      translate var(--ds-dur-medium) var(--ds-ease-spatial),
      opacity var(--ds-dur-micro) var(--ds-ease-in-out),
      color var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  /* Disabled: the button model. The track takes the neutral fill (a theme
     that dims instead keeps the switch's own colours), the off handle the
     disabled ink, the on handle the surface; no hover, halo or grow. */
  .ds-switch:has(input:is(:disabled, [aria-disabled="true"])) {
    cursor: not-allowed;
  }

  /* The name and the word fade to the quieter ink with the track. */
  .ds-switch__label,
  .ds-switch__state {
    transition: color var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  .ds-switch input:is(:disabled, [aria-disabled="true"]) ~ .ds-switch__label,
  .ds-switch input:is(:disabled, [aria-disabled="true"]) ~ .ds-switch__state {
    color: var(--ds-text-2);
  }

  .ds-switch input:is(:disabled, [aria-disabled="true"]) + .ds-switch__track {
    border-color: var(--ds-switch-disabled-track, var(--ds-disabled-fill, var(--ds-outline)));
    background: var(--ds-switch-disabled-track, var(--ds-disabled-fill, var(--ds-surface-highest)));
    opacity: var(--ds-disabled-opacity, var(--ds-state-disabled));
  }

  .ds-switch input:checked:is(:disabled, [aria-disabled="true"]) + .ds-switch__track {
    border-color: var(--ds-switch-disabled-track, var(--ds-disabled-fill, var(--ds-primary)));
    background: var(--ds-switch-disabled-track, var(--ds-disabled-fill, var(--ds-primary)));
  }

  .ds-switch input:is(:disabled, [aria-disabled="true"]) + .ds-switch__track::after {
    background: var(--ds-switch-disabled-handle, var(--ds-disabled-ink, var(--ds-outline)));
  }

  .ds-switch input:checked:is(:disabled, [aria-disabled="true"]) + .ds-switch__track::after {
    background: var(--ds-surface);
  }

  /*
   * Locked: a value another system sets. Its on and off looks keep full
   * strength (after the disabled rules, with their weight); the off handle
   * grows to 24px to hold the lock.
   */
  .ds-switch input[aria-busy="true"] + .ds-switch__track,
  .ds-switch--locked input:is(:disabled, [aria-disabled="true"]) + .ds-switch__track {
    border-color: var(--ds-outline);
    background: var(--ds-surface-highest);
    opacity: 1;
  }

  .ds-switch input[aria-busy="true"]:checked + .ds-switch__track,
  .ds-switch--locked input:checked:is(:disabled, [aria-disabled="true"]) + .ds-switch__track {
    border-color: var(--ds-primary);
    background: var(--ds-primary);
  }

  .ds-switch input[aria-busy="true"] + .ds-switch__track::after,
  .ds-switch--locked input:is(:disabled, [aria-disabled="true"]) + .ds-switch__track::after {
    background: var(--ds-outline);
    scale: calc(6 / 7);
  }

  .ds-switch input[aria-busy="true"]:checked + .ds-switch__track::after,
  .ds-switch--locked input:checked:is(:disabled, [aria-disabled="true"]) + .ds-switch__track::after {
    background: var(--ds-on-primary);
  }

  .ds-switch input[aria-busy="true"] ~ :is(.ds-switch__label, .ds-switch__state),
  .ds-switch--locked input:is(:disabled, [aria-disabled="true"]) ~ :is(.ds-switch__label, .ds-switch__state) {
    color: var(--ds-text);
  }

  .ds-switch:has(input[aria-busy="true"]) {
    cursor: progress;
  }

  /* The lock rides the handle: its centre is the handle's (14px, 14px of
     the padding box), above it; it fades out faster than it comes. */
  .ds-switch__icon {
    position: absolute;
    inset-block-start: calc((var(--_handle) - var(--_icon)) / 2);
    inset-inline-start: calc((var(--_handle) - var(--_icon)) / 2);
    z-index: var(--ds-z-raised);
    width: var(--_icon);
    height: var(--_icon);
    color: var(--ds-surface-highest);
    opacity: 0;
    transition:
      opacity var(--ds-dur-instant) var(--ds-ease-in-out),
      translate var(--ds-dur-medium) var(--ds-ease-spatial),
      color var(--ds-dur-base) var(--ds-ease-in-out);
  }

  .ds-switch--locked .ds-switch__icon,
  .ds-switch--icons input:not(:checked) + .ds-switch__track .ds-switch__icon--off,
  .ds-switch--icons input:checked + .ds-switch__track .ds-switch__icon--on {
    opacity: 1;
    transition:
      opacity var(--ds-dur-fast) var(--ds-ease-in-out),
      translate var(--ds-dur-medium) var(--ds-ease-spatial),
      color var(--ds-dur-base) var(--ds-ease-in-out);
  }

  .ds-switch input:checked + .ds-switch__track .ds-switch__icon {
    color: var(--ds-primary);
    translate: var(--_travel) 0;
  }

  /* With icons both handles hold a glyph: the off handle grows to 24px, as
     under a lock; a press still grows it to its full size. */
  .ds-switch--icons input + .ds-switch__track::after {
    scale: calc(6 / 7);
  }

  /* On the disabled on handle (--ds-surface) the glyph takes the neutral ink. */
  .ds-switch--icons input:checked:is(:disabled, [aria-disabled="true"]) + .ds-switch__track .ds-switch__icon {
    color: var(--ds-disabled-ink, var(--ds-primary));
  }

  /* The spinner of a busy switch rides the handle like the lock. It waits for
     --ds-delay-loader, so a fast answer shows nothing, and comes back hidden
     (visibility: a loop that is not seen does not paint). */
  .ds-switch__track > .ds-switch__spinner {
    --ds-spinner-color: var(--ds-surface-highest);
    position: absolute;
    inset-block-start: calc((var(--_handle) - var(--_icon)) / 2);
    inset-inline-start: calc((var(--_handle) - var(--_icon)) / 2);
    z-index: var(--ds-z-raised);
    width: var(--_icon);
    height: var(--_icon);
    opacity: 0;
    visibility: hidden;
    transition:
      opacity var(--ds-dur-instant) var(--ds-ease-in-out),
      translate var(--ds-dur-medium) var(--ds-ease-spatial),
      visibility 0s linear var(--ds-dur-instant);
  }

  .ds-switch input:checked + .ds-switch__track > .ds-switch__spinner {
    --ds-spinner-color: var(--ds-primary);
    translate: var(--_travel) 0;
  }

  .ds-switch input[aria-busy="true"] + .ds-switch__track > .ds-switch__spinner {
    opacity: 1;
    visibility: visible;
    transition:
      opacity var(--ds-dur-fast) var(--ds-ease-in-out) var(--ds-delay-loader),
      translate var(--ds-dur-medium) var(--ds-ease-spatial),
      visibility 0s linear var(--ds-delay-loader);
  }

  /* A glyph of .ds-switch--icons makes room for the spinner. */
  .ds-switch input[aria-busy="true"] + .ds-switch__track > .ds-switch__icon {
    opacity: 0;
  }

  /* Hint and extras: a line under the name, and quiet parts before the word. */
  .ds-switch__label {
    min-width: 0;
    overflow-wrap: anywhere;
  }

  small.ds-switch__hint {
    display: block;
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
  }

  span.ds-switch__meta {
    display: inline-flex;
    align-items: center;
    gap: var(--ds-space-2);
    color: var(--ds-text-2);
    font: var(--ds-font-body);
    font-variant-numeric: tabular-nums;
  }

  /* The state in words next to the name ("On" / "Off"). It keeps the width
     of the longer word, so the switch does not move when it flips. */
  .ds-switch__state {
    display: inline-grid;
    min-width: 3.5em;
    margin-inline-start: calc(-1 * var(--ds-space-1));
    color: var(--ds-text-2);
    font: var(--ds-font-body);
  }

  /* Both words in one cell. The hidden one waits below; the leaving word
     only fades (then drops back to wait), the arriving word rises in once
     the other has begun to go. */
  .ds-switch__on,
  .ds-switch__off {
    grid-area: 1 / 1;
    opacity: 0;
    translate: 0 var(--ds-distance-sm);
    transition:
      opacity var(--ds-dur-instant) var(--ds-ease-in),
      translate 0s linear var(--ds-dur-instant);
  }

  .ds-switch input:checked ~ .ds-switch__state .ds-switch__on,
  .ds-switch input:not(:checked) ~ .ds-switch__state .ds-switch__off {
    opacity: 1;
    translate: none;
    transition:
      opacity var(--ds-dur-fast) var(--ds-ease-in-out) var(--ds-dur-micro),
      translate var(--ds-dur-fast) var(--ds-ease-out) var(--ds-dur-micro);
  }

  /* Forced colors: the handle and the on state are fills only; in system
     colours, so on and off still differ. The halo is a tint: hidden. */
  @media (forced-colors: active) {
    .ds-switch__track::after,
    .ds-switch:hover input:not(:checked):not(:disabled, [aria-disabled="true"]) + .ds-switch__track::after,
    .ds-switch:active input:not(:checked):not(:disabled, [aria-disabled="true"]) + .ds-switch__track::after,
    .ds-switch.ds-pressed input:not(:checked):not(:disabled, [aria-disabled="true"]) + .ds-switch__track::after {
      forced-color-adjust: none;
      background: CanvasText;
    }

    .ds-switch input:checked + .ds-switch__track {
      forced-color-adjust: none;
      border-color: Highlight;
      background: Highlight;
    }

    .ds-switch input:checked + .ds-switch__track::after {
      background: Canvas;
    }

    .ds-switch__track::before {
      display: none;
    }

    .ds-switch input:is(:disabled, [aria-disabled="true"]) + .ds-switch__track {
      forced-color-adjust: none;
      border-color: GrayText;
      background: Canvas;
    }

    .ds-switch input:checked:is(:disabled, [aria-disabled="true"]) + .ds-switch__track {
      background: GrayText;
    }

    .ds-switch input:is(:disabled, [aria-disabled="true"]) + .ds-switch__track::after {
      background: GrayText;
    }

    .ds-switch input:checked:is(:disabled, [aria-disabled="true"]) + .ds-switch__track::after {
      background: Canvas;
    }

    .ds-switch input:is(:disabled, [aria-disabled="true"]) ~ .ds-switch__label,
    .ds-switch input:is(:disabled, [aria-disabled="true"]) ~ .ds-switch__state {
      color: GrayText;
    }

    /* A checked switch keeps its ring in CanvasText (the track is Highlight),
       and so does a blocked one (its track is not forced). */
    .ds-switch input:checked:focus-visible + .ds-switch__track,
    .ds-switch input[aria-disabled="true"]:focus-visible + .ds-switch__track {
      outline-color: CanvasText;
    }

    /* Locked: the normal on and off system colours, the lock in Canvas on
       the off handle and in Highlight on the on handle. */
    .ds-switch input[aria-busy="true"] + .ds-switch__track,
    .ds-switch--locked input:is(:disabled, [aria-disabled="true"]) + .ds-switch__track {
      border-color: CanvasText;
      background: Canvas;
    }

    .ds-switch input[aria-busy="true"]:checked + .ds-switch__track,
    .ds-switch--locked input:checked:is(:disabled, [aria-disabled="true"]) + .ds-switch__track {
      border-color: Highlight;
      background: Highlight;
    }

    .ds-switch input[aria-busy="true"] + .ds-switch__track::after,
    .ds-switch--locked input:is(:disabled, [aria-disabled="true"]) + .ds-switch__track::after {
      background: CanvasText;
    }

    .ds-switch input[aria-busy="true"]:checked + .ds-switch__track::after,
    .ds-switch--locked input:checked:is(:disabled, [aria-disabled="true"]) + .ds-switch__track::after {
      background: Canvas;
    }

    .ds-switch input[aria-busy="true"] ~ :is(.ds-switch__label, .ds-switch__state),
    .ds-switch--locked input:is(:disabled, [aria-disabled="true"]) ~ :is(.ds-switch__label, .ds-switch__state) {
      color: CanvasText;
    }

    /* The page's forced svg rule (shell.css) makes every icon inherit its
       colour, so the track carries it: the lock takes the track's colour. */
    .ds-switch--locked input:is(:disabled, [aria-disabled="true"]) + .ds-switch__track,
    .ds-switch--icons input:not(:checked) + .ds-switch__track {
      color: Canvas;
    }

    .ds-switch--locked input:checked:is(:disabled, [aria-disabled="true"]) + .ds-switch__track,
    .ds-switch--icons input:checked + .ds-switch__track {
      color: Highlight;
    }

    .ds-switch__icon {
      forced-color-adjust: none;
      color: inherit;
    }

    /* A blocked switch with icons: the glyph on its GrayText or Canvas handle. */
    .ds-switch--icons input:is(:disabled, [aria-disabled="true"]):not([aria-busy="true"]) + .ds-switch__track {
      color: Canvas;
    }

    .ds-switch--icons input:checked:is(:disabled, [aria-disabled="true"]):not([aria-busy="true"]) + .ds-switch__track {
      color: GrayText;
    }

    /* The spinner on the handle, in the track's colour: it needs its own, the
       arc would take the handle's. */
    .ds-switch__track > .ds-switch__spinner {
      forced-color-adjust: none;
      --ds-spinner-color: Canvas;
    }

    .ds-switch input:checked + .ds-switch__track > .ds-switch__spinner {
      --ds-spinner-color: Highlight;
    }
  }

  /*
   * Many settings, each a switch: rows on one grid (track, name over hint,
   * meta, state word), hairlines between. At 560px and below the meta
   * wraps under the name.
   */
  .ds-switch-list {
    display: grid;
    container: ds-switch-list / inline-size;
    margin: 0;
    padding: 0;
  }

  /* A switch with a hint stacks the hint under its name (the same areas).
     The name and the hint stand together, no gap between the text rows;
     the two flexible rows around them take the free height, so the text
     centres on the track whichever rows are empty (no hint, no meta, a
     wrapped name). */
  .ds-switch:has(> .ds-switch__hint) {
    display: inline-grid;
    grid-template-columns: auto minmax(0, 1fr) auto auto;
    grid-template-rows: 1fr auto auto 1fr;
    grid-template-areas:
      "track . meta state"
      "track label meta state"
      "track hint meta state"
      "track . meta state";
    align-items: center;
    column-gap: var(--ds-space-3);
    row-gap: 0;
  }

  .ds-switch-list > .ds-switch {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr) auto auto;
    grid-template-rows: 1fr auto auto 1fr;
    grid-template-areas:
      "track . meta state"
      "track label meta state"
      "track hint meta state"
      "track . meta state";
    align-items: center;
    column-gap: var(--ds-space-3);
    row-gap: 0;
    min-height: max(var(--ds-target-min, 0px), calc(var(--ds-switch-list-row-height, 56px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px));
    padding-block: calc(var(--ds-space-2) + var(--ds-density, 0) * 2px);
    border-bottom: 1px solid var(--ds-line);
  }

  .ds-switch-list > .ds-switch:last-child {
    border-bottom: 0;
  }

  .ds-switch > .ds-switch__track {
    grid-area: track;
  }

  .ds-switch > .ds-switch__label {
    grid-area: label;
  }

  .ds-switch > .ds-switch__hint {
    grid-area: hint;
  }

  .ds-switch > .ds-switch__meta {
    grid-area: meta;
  }

  .ds-switch > .ds-switch__state {
    grid-area: state;
  }

  @container ds-switch-list (max-width: 560px) {
    .ds-switch-list > .ds-switch {
      grid-template-columns: auto minmax(0, 1fr) auto;
      grid-template-rows: 1fr auto auto auto 1fr;
      grid-template-areas:
        "track . state"
        "track label state"
        "track hint state"
        "track meta state"
        "track . state";
    }

    /* Under the hint (or the name) the meta keeps a little air; a tag
       directly on the text line reads as part of it. */
    .ds-switch > .ds-switch__meta {
      justify-self: start;
      margin-top: var(--ds-space-1);
    }
  }

  /* Print: track and handle are backgrounds, which printing drops by
     default; on and off stay visible. */
  @media print {
    .ds-switch {
      -webkit-print-color-adjust: exact;
      print-color-adjust: exact;
    }
  }
}

/* ── components/slider/slider.css ── */
/*
 * Slider (Material 3): a value on a scale (a threshold, days of history),
 * drawn on the native range input, so keyboard, forms and labels stay
 * native. A 4px track in the tonal accent, its active part in the primary
 * colour, and a 20px round handle with a halo (--ds-slider-halo, 40px)
 * for hover, press and keyboard focus, like the switch's: the halo is the
 * press (no ripple), and the handle never scales. Keyboard focus also
 * rings the handle: solid from the first frame, it snaps from offset +
 * width to the offset (outline-offset, --ds-dur-fast). The value never
 * glides while it is dragged (direct manipulation): nothing transitions
 * it.
 *
 *   <label class="ds-field__label" for="keep">Keep history for</label>
 *   <div class="ds-field__row">
 *     <input class="ds-slider" id="keep" type="range" min="7" max="365" value="90" aria-describedby="keep-out">
 *     <output class="ds-slider__value" id="keep-out" for="keep">90 days</output>
 *   </div>
 *
 * Firefox draws the active part itself (::-moz-range-progress). Elsewhere
 * the page sets --ds-share (0 to 1, the value's share of the range) on the
 * input when it renders and on every input event; without it the track
 * shows no active part and the slider still works.
 *
 * Options (src/core/options.css, docs/options.md), on the slider or any
 * ancestor; each is computed here, in the slider's own rule:
 *   size      .ds-xs ... .ds-xl: 8px of height and halo per step, 1px of track
 *             and 4px of handle per step, the value in the size's type role
 *   density   .ds-density-*: 4px of height and halo per step, never the
 *             handle or the track
 *   shape     .ds-shape-*: multiplies the radius of the track and of the
 *             handle (round at the default, square at 0); the halo is the
 *             handle's shadow, so it follows the handle's shape
 *   touch     .ds-touch: at least --ds-touch-target (48px) high
 *
 * Disabled (and aria-disabled="true"): the neutral ink for the handle and
 * the active part, no halo; the handle lays the ink over --ds-surface, so
 * it stays solid; it fades on --ds-dur-fast. aria-disabled stays in the tab
 * order, and the action guard (DS.motion.guard) holds its value: a press, a
 * drag or a key moves nothing and no input event reaches the page. Forced
 * colours: the
 * track in ButtonText, the handle in Highlight (GrayText when disabled).
 *
 * Hooks: --ds-slider-halo (40px), --ds-slider-thumb-size (20px),
 * --ds-slider-track-height (4px). The computed values (--_box, --_thumb,
 * --_track, --_spread and the like) are private: never set them.
 *
 * Print: track and handle keep their colours (print-color-adjust).
 */

@layer ds.components.slider {
  .ds-slider {
    /* The options, computed here (docs/options.md); the engine's parts inherit
       them. The input is as high as the halo, never below the touch minimum. */
    --_box: max(var(--ds-target-min, 0px), calc(var(--ds-slider-halo, 40px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px));
    --_thumb: calc(var(--ds-slider-thumb-size, 20px) + var(--ds-size-step, 0) * 4px);
    --_track: calc(var(--ds-slider-track-height, 4px) + var(--ds-size-step, 0) * 1px);
    --_spread: calc((var(--_box) - var(--_thumb)) / 2);
    --_track-radius: min(calc(var(--ds-radius-xs) * var(--ds-shape, 1)), calc(var(--_track) / 2));
    --_thumb-radius: min(calc(var(--_thumb) / 2 * var(--ds-shape, 1)), calc(var(--_thumb) / 2));
    appearance: none;
    display: block;
    width: 100%;
    min-width: 0;
    height: var(--_box);
    margin: 0;
    padding: 0;
    background: transparent;
    color: var(--ds-primary);
    cursor: pointer;
    transition: opacity var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  /* The ring sits on the handle, not around the whole input. */
  .ds-slider:focus-visible {
    outline: none;
  }

  /* The gradient runs left to right: the active part first (D9, LTR). */
  .ds-slider::-webkit-slider-runnable-track {
    height: var(--_track);
    border-radius: var(--_track-radius);
    background: linear-gradient(to right, currentColor calc(var(--ds-share, 0) * 100%), var(--ds-accent) 0);
  }

  .ds-slider::-moz-range-track {
    height: var(--_track);
    border-radius: var(--_track-radius);
    background: var(--ds-accent);
  }

  .ds-slider::-moz-range-progress {
    height: var(--_track);
    border-radius: var(--_track-radius);
    background: currentColor;
  }

  /* The handle and its halo (the halo rests transparent at its full size,
     so only its colour fades). The ring rests one width further out. */
  .ds-slider::-webkit-slider-thumb {
    appearance: none;
    box-sizing: border-box;
    width: var(--_thumb);
    height: var(--_thumb);
    margin-top: calc((var(--_track) - var(--_thumb)) / 2);
    border: 0;
    border-radius: var(--_thumb-radius);
    background: currentColor;
    box-shadow: 0 0 0 var(--_spread) transparent;
    outline-offset: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    transition:
      background-color var(--ds-dur-fast) var(--ds-ease-in-out),
      box-shadow var(--ds-dur-fast) var(--ds-ease-in-out),
      outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-slider::-moz-range-thumb {
    box-sizing: border-box;
    width: var(--_thumb);
    height: var(--_thumb);
    border: 0;
    border-radius: var(--_thumb-radius);
    background: currentColor;
    box-shadow: 0 0 0 var(--_spread) transparent;
    outline-offset: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    transition:
      background-color var(--ds-dur-fast) var(--ds-ease-in-out),
      box-shadow var(--ds-dur-fast) var(--ds-ease-in-out),
      outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  @media (hover: hover) {
    .ds-slider:not(:disabled, [aria-disabled="true"]):hover::-webkit-slider-thumb {
      box-shadow: 0 0 0 var(--_spread) color-mix(in srgb, currentColor calc(var(--ds-state-hover) * 100%), transparent);
    }

    .ds-slider:not(:disabled, [aria-disabled="true"]):hover::-moz-range-thumb {
      box-shadow: 0 0 0 var(--_spread) color-mix(in srgb, currentColor calc(var(--ds-state-hover) * 100%), transparent);
    }
  }

  /* Keyboard focus: the ring snaps in and the halo appears with it (at
     once), also on an aria-disabled slider, which stays in the tab order. */
  .ds-slider:focus-visible::-webkit-slider-thumb {
    outline: var(--ds-focus-outline);
    outline-offset: var(--ds-focus-offset);
    box-shadow: 0 0 0 var(--_spread) color-mix(in srgb, currentColor calc(var(--ds-state-focus) * 100%), transparent);
    transition:
      background-color var(--ds-dur-fast) var(--ds-ease-in-out),
      box-shadow 0s,
      outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-slider:focus-visible::-moz-range-thumb {
    outline: var(--ds-focus-outline);
    outline-offset: var(--ds-focus-offset);
    box-shadow: 0 0 0 var(--_spread) color-mix(in srgb, currentColor calc(var(--ds-state-focus) * 100%), transparent);
    transition:
      background-color var(--ds-dur-fast) var(--ds-ease-in-out),
      box-shadow 0s,
      outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-slider:not(:disabled, [aria-disabled="true"]):active::-webkit-slider-thumb {
    box-shadow: 0 0 0 var(--_spread) color-mix(in srgb, currentColor calc(var(--ds-state-pressed) * 100%), transparent);
    transition:
      background-color var(--ds-dur-fast) var(--ds-ease-in-out),
      box-shadow var(--ds-dur-micro) var(--ds-ease-in-out),
      outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-slider:not(:disabled, [aria-disabled="true"]):active::-moz-range-thumb {
    box-shadow: 0 0 0 var(--_spread) color-mix(in srgb, currentColor calc(var(--ds-state-pressed) * 100%), transparent);
    transition:
      background-color var(--ds-dur-fast) var(--ds-ease-in-out),
      box-shadow var(--ds-dur-micro) var(--ds-ease-in-out),
      outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  /* Disabled: the neutral ink for the handle and the active part (a theme
     that dims instead keeps the slider's colours). */
  .ds-slider:is(:disabled, [aria-disabled="true"]) {
    color: var(--ds-disabled-ink, var(--ds-primary));
    opacity: var(--ds-disabled-opacity, var(--ds-state-disabled));
    cursor: not-allowed;
  }

  /* The ink is translucent: laid over the surface, the handle stays solid
     and the track does not show through it. One engine's pseudo-element
     per rule. */
  .ds-slider:is(:disabled, [aria-disabled="true"])::-webkit-slider-thumb {
    background: linear-gradient(currentColor, currentColor) var(--ds-surface);
  }

  .ds-slider:is(:disabled, [aria-disabled="true"])::-moz-range-thumb {
    background: linear-gradient(currentColor, currentColor) var(--ds-surface);
  }

  /* The value beside the slider: tabular, so the row keeps its width. */
  .ds-slider__value {
    flex: none;
    min-width: var(--ds-space-10);
    color: var(--ds-text);
    font: var(--ds-size-font, var(--ds-font-label));
    font-variant-numeric: tabular-nums;
    text-align: end;
  }

  @media (forced-colors: active) {
    .ds-slider {
      forced-color-adjust: none;
      color: Highlight;
    }

    .ds-slider::-webkit-slider-runnable-track {
      background: ButtonText;
    }

    .ds-slider::-moz-range-track,
    .ds-slider::-moz-range-progress {
      background: ButtonText;
    }

    .ds-slider::-webkit-slider-thumb,
    .ds-slider:not(:disabled, [aria-disabled="true"]):hover::-webkit-slider-thumb,
    .ds-slider:focus-visible::-webkit-slider-thumb,
    .ds-slider:not(:disabled, [aria-disabled="true"]):active::-webkit-slider-thumb {
      box-shadow: none;
    }

    .ds-slider::-moz-range-thumb,
    .ds-slider:not(:disabled, [aria-disabled="true"]):hover::-moz-range-thumb,
    .ds-slider:focus-visible::-moz-range-thumb,
    .ds-slider:not(:disabled, [aria-disabled="true"]):active::-moz-range-thumb {
      box-shadow: none;
    }

    /* One engine's pseudo-element per rule: a selector list with a pseudo-element
       an engine does not know is dropped as a whole. */
    .ds-slider:focus-visible::-webkit-slider-thumb {
      outline-color: CanvasText;
    }

    .ds-slider:focus-visible::-moz-range-thumb {
      outline-color: CanvasText;
    }

    .ds-slider:is(:disabled, [aria-disabled="true"]) {
      color: GrayText;
    }
  }

  /* Print: track and handle are backgrounds, which printing drops by
     default; the value stays visible. */
  @media print {
    .ds-slider {
      -webkit-print-color-adjust: exact;
      print-color-adjust: exact;
    }
  }
}

/* ── components/progress/progress.css ── */
/*
 * Linear progress (Material 3, 2024 look): a primary bar that ends at the
 * share, a gap, then the remaining track in --ds-accent with a stop dot at
 * its end. The bar is wavy and its wave travels (M3 Expressive); it turns
 * flat once the job is complete. An unknown share runs the two-segment
 * choreography of M3 across the track.
 *
 *   <div class="ds-progress [ds-progress--indeterminate | --waiting | --flat]" style="--ds-progress: .4">
 *     <div class="ds-progress__track" role="progressbar" aria-valuenow="40" aria-valuemin="0" aria-valuemax="100" aria-label="Import">
 *       <div class="ds-progress__bar"></div>
 *     </div>
 *     <p class="ds-progress__label">40%</p>
 *     <p class="ds-progress__detail">812 of 2,030 rows</p>
 *
 *   .ds-progress--indeterminate  two segments run across (ds-progress-head,
 *                                ds-progress-tail over --ds-loop-indeterminate)
 *   .ds-progress--waiting        hides the track (only the label shows);
 *                                the track keeps its 4px, so the label
 *                                stays put, and fades in when the
 *                                modifier drops
 *   .ds-progress--flat           the classic look: no gap, no stop dot, no
 *                                wave. Use it in dense table cells: the wave
 *                                reaches 3px above and below the 4px track,
 *                                and an ancestor with overflow: hidden closer
 *                                than that clips it.
 *
 * Where the label sits (default: under the track, as in the markup above):
 *   .ds-progress--label-above    label over the track, detail under it
 *   .ds-progress--label-end      label at the track's end, one row; the
 *                                detail under the track. The track shrinks,
 *                                the label keeps its width.
 *
 * Options (docs/options.md), computed here into --_t, --_wave and the radii:
 *   size      .ds-xs ... .ds-xl on it or any ancestor: the track's thickness,
 *             2px per step (1, 2, 4, 6, 8px); the wave's height follows, its
 *             wavelength stays. Type stays.
 *   density   any container: the label's distance from the track, 2px per step
 *             (so 4px under the compact theme, density -2, on purpose)
 *   shape     the bar's and the track's ends times --ds-shape; the stop dot
 *             stays a dot
 *   tone      from the class on .ds-progress itself: the bar and the stop dot
 *             in --ds-tone, the remaining track in --ds-tone-container; an
 *             inherited tone never recolours it, and its label says the rest
 *   target-min: not read, progress is no target.
 *
 * The share: set --ds-progress (0 ... 1; registered as a number) on the
 * .ds-progress element, with el.style.setProperty (a strict CSP allows it).
 * It glides there on --ds-ease-value over --ds-dur-glide, and the bar, the
 * gap, the remaining track and a nested .ds-spinner--determinate read the
 * inherited value, so they land together, and on the same frame as a
 * DS.motion.countUp() figure set in the same task. The bar is cut by
 * clip-path at the share (never scaled), so its round cap keeps its radius
 * at any share; the clip repaints every frame of a glide, which is fine for
 * a 4px bar.
 *
 * Layers: the track paints the remaining track and the stop dot (background
 * layers that start after the share and the gap); .ds-progress__bar is the
 * box of the bar, 3px taller than the track on both sides, cut at the share
 * (the clip's round end is the cap); its ::before is the wave (the primary
 * colour through the --ds-progress-wave mask, which travels one
 * --ds-progress-wave-length per --ds-loop-wave and stops at completion) and
 * its ::after the flat 4px fill, which cross-fades in over --ds-dur-medium
 * when aria-valuenow reaches 100 (the documented aria-valuemax="100") and
 * in --flat. The track's ::before and ::after are the two indeterminate
 * segments, on the same wave.
 *
 * Short bars are flat (M3 Expressive flattens the wave at small shares): a
 * bar shorter than a wavelength would show a loose piece of the sine that
 * bobs above and below the track as the wave travels. The wave and the
 * flat fill cross-fade on the (gliding) share itself: flat up to 6%, wavy
 * from 11% (--ds-progress-wave-start, --ds-progress-wave-ramp), so the
 * crossover follows the glide on its own.
 *
 * Handoff: when --indeterminate drops, the segments stop where they are and
 * fade out (--ds-dur-fast, --ds-ease-in), the bar fades in (--ds-dur-fast,
 * --ds-ease-in-out) and --ds-progress glides from its previous value (0
 * when it was never set): the bar grows to its share and never sweeps
 * across or shrinks from 100%. Set the first share in the same task that
 * drops the modifier; a share set earlier, while indeterminate, simply
 * appears at that share.
 *
 * Accessibility: while --indeterminate or --waiting is on, remove
 * aria-valuenow and set aria-valuetext ("Preparing", "Waiting"); with the
 * first share, set aria-valuenow again and remove aria-valuetext.
 *
 * Hooks: --ds-progress-height (4px, the md base), --ds-progress-gap (4px
 * between the bar and the remaining track), --ds-progress-bar (the bar,
 * --ds-primary), --ds-progress-stop (the stop dot, --ds-primary),
 * --ds-progress-track (the remaining track, --ds-accent).
 *
 * Print: the bar keeps its colours (print-color-adjust), so the share
 * shows on paper.
 */

@layer ds.components.progress {
  .ds-progress {
    --_t: max(1px, calc(var(--ds-progress-height, 4px) + var(--ds-size-step, 0) * 2px));
    /* How far the wave reaches out of the track: 3px at the 4px track. */
    --_wave: calc(var(--_t) * .75);
    --_cap: min(calc(var(--ds-radius-action) * var(--ds-shape, 1)), calc(var(--_t) / 2));
    --_box-cap: min(calc(var(--ds-radius-action) * var(--ds-shape, 1)), calc(var(--_t) / 2 + var(--_wave)));
    /* The round start of the remaining track goes with the shape. */
    --_nose: calc(var(--_t) / 2 * min(1, var(--ds-shape, 1)));
    --_bar: var(--ds-progress-bar, var(--ds-primary));
    --_track: var(--ds-progress-track, var(--ds-accent));
    --_stop: var(--ds-progress-stop, var(--ds-primary));
    transition: --ds-progress var(--ds-dur-glide) var(--ds-ease-value);
  }

  /* A tone from the class on .ds-progress itself; a hook still wins. */
  .ds-progress:is(.ds-tone-neutral, .ds-tone-primary, .ds-tone-info, .ds-tone-success, .ds-tone-warning, .ds-tone-error) {
    --_bar: var(--ds-progress-bar, var(--ds-tone));
    --_track: var(--ds-progress-track, var(--ds-tone-container));
    --_stop: var(--ds-progress-stop, var(--ds-tone));
  }

  /* Nested, the share inherits from .ds-progress, which glides it: a second
     transition on the ring would trail behind the bar. */
  .ds-progress .ds-spinner--determinate {
    transition: none;
  }

  /*
   * The remaining track starts the gap after the share. The gap opens with
   * the first percent (an empty bar shows the whole track); a disc of the
   * track's height rounds its start. The stop dot is the top layer, under
   * the bar, which paints over it once it arrives. The loops of the
   * segments are declared here, paused, so dropping --indeterminate stops
   * them where they are while they fade out.
   */
  /* The gradients run left to right, like the bar's clip (LTR only, D9). */
  .ds-progress__track {
    position: relative;
    height: var(--_t);
    overflow: visible;
    isolation: isolate;
    border-radius: var(--_cap);
    background:
      radial-gradient(circle calc(var(--_t) / 2) at calc(100% - var(--_t) / 2) 50%, var(--_stop) calc(100% - .5px), transparent),
      radial-gradient(circle var(--_nose) at calc(var(--ds-progress) * 100% + var(--ds-progress-gap, 4px) * min(1, var(--ds-progress) * 100) + var(--_t) / 2) 50%, var(--_track) calc(100% - .5px), transparent),
      linear-gradient(to right, transparent calc(var(--ds-progress) * 100% + var(--ds-progress-gap, 4px) * min(1, var(--ds-progress) * 100) + var(--_t) / 2), var(--_track) 0);
    animation:
      ds-progress-head var(--ds-loop-indeterminate) linear infinite paused,
      ds-progress-tail var(--ds-loop-indeterminate) linear infinite paused;
    transition: opacity var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  /* The bar's box: the track's width, taller on both sides for the wave
     (3px at the 4px track), cut at the share with a round end. */
  .ds-progress__bar {
    position: absolute;
    inset: calc(-1 * var(--_wave)) 0;
    clip-path: inset(0 calc((1 - var(--ds-progress)) * 100%) 0 0 round var(--_box-cap));
    transition: opacity var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  .ds-progress__bar::before,
  .ds-progress__bar::after {
    content: '';
    position: absolute;
    inset-inline: 0;
    background: var(--_bar);
    transition: opacity var(--ds-dur-medium) var(--ds-ease-in-out);
  }

  /* The wave, travelling; it fades in between 6% and 11% (short bars are
     flat). Opacity clamps the ramp to 0 ... 1 by itself. */
  .ds-progress__bar::before {
    top: 0;
    bottom: 0;
    opacity: calc(var(--ds-progress) / var(--ds-progress-wave-ramp) - var(--ds-progress-wave-start) / var(--ds-progress-wave-ramp));
    mask-image: var(--ds-progress-wave);
    mask-size: var(--ds-progress-wave-length) 100%;
    mask-repeat: repeat-x;
    animation: ds-progress-wave var(--ds-loop-wave) linear infinite;
  }

  /* The flat fill, with its own clip: the box's clip rounds the taller box,
     the fill needs its own cap. */
  .ds-progress__bar::after {
    top: var(--_wave);
    height: var(--_t);
    border-radius: var(--_cap);
    clip-path: inset(0 calc((1 - var(--ds-progress)) * 100%) 0 0 round var(--_cap));
    opacity: calc(1 - var(--ds-progress) / var(--ds-progress-wave-ramp) + var(--ds-progress-wave-start) / var(--ds-progress-wave-ramp));
  }

  /* Complete: the wave stops where it is and fades, the flat fill takes
     over. */
  .ds-progress:has(> .ds-progress__track[aria-valuenow="100"]) .ds-progress__bar::before {
    opacity: 0;
    animation-play-state: paused;
  }

  .ds-progress:has(> .ds-progress__track[aria-valuenow="100"]) .ds-progress__bar::after {
    opacity: 1;
  }

  /* The classic look: the whole track behind a flat bar. */
  .ds-progress--flat .ds-progress__track {
    background: var(--_track);
  }

  .ds-progress--flat .ds-progress__bar::before {
    display: none;
  }

  .ds-progress--flat .ds-progress__bar::after {
    opacity: 1;
    transition: none;
  }

  /*
   * The two indeterminate segments: each the full width of the track,
   * taller for the wave, cut between its tail and its head (the track's
   * loops animate the four edges; they inherit). Out of that state they
   * fade out on the way (the handoff) and stay at opacity 0, their wave
   * paused.
   */
  .ds-progress__track::before,
  .ds-progress__track::after {
    content: '';
    position: absolute;
    inset: calc(-1 * var(--_wave)) 0;
    z-index: -1;
    background: var(--_bar);
    mask-image: var(--ds-progress-wave);
    mask-size: var(--ds-progress-wave-length) 100%;
    mask-repeat: repeat-x;
    opacity: 0;
    animation: ds-progress-wave var(--ds-loop-wave) linear infinite paused;
    transition: opacity var(--ds-dur-fast) var(--ds-ease-in);
  }

  .ds-progress__track::before {
    clip-path: inset(0 calc(100% - var(--ds-progress-head-1)) 0 var(--ds-progress-tail-1) round var(--_box-cap));
  }

  .ds-progress__track::after {
    clip-path: inset(0 calc(100% - var(--ds-progress-head-2)) 0 var(--ds-progress-tail-2) round var(--_box-cap));
  }

  /* Indeterminate: the whole track, no stop dot, the segments running;
     the bar waits unseen and still. */
  .ds-progress--indeterminate .ds-progress__track {
    background: var(--_track);
    animation-play-state: running;
  }

  .ds-progress--indeterminate .ds-progress__track::before,
  .ds-progress--indeterminate .ds-progress__track::after {
    opacity: 1;
    animation-play-state: running;
    transition: none;
  }

  .ds-progress--indeterminate .ds-progress__bar {
    opacity: 0;
    transition: none;
  }

  .ds-progress--indeterminate .ds-progress__bar::before {
    animation-play-state: paused;
  }

  .ds-progress--flat.ds-progress--indeterminate .ds-progress__track::before,
  .ds-progress--flat.ds-progress--indeterminate .ds-progress__track::after {
    mask-image: none;
    inset: 0;
    animation: none;
  }

  /* Waiting: the track keeps its height (so the label never jumps when the
     wait ends) but is hidden, its loops held; it fades in when the
     modifier drops. */
  .ds-progress--waiting .ds-progress__track {
    visibility: hidden;
    opacity: 0;
    animation-play-state: paused;
  }

  .ds-progress--waiting .ds-progress__track::before,
  .ds-progress--waiting .ds-progress__track::after,
  .ds-progress--waiting .ds-progress__bar::before {
    animation-play-state: paused;
  }

  .ds-progress__label {
    margin: calc(var(--ds-space-2) + var(--ds-density, 0) * 2px) 0 0;
    color: var(--ds-text);
    font: var(--ds-font-body);
    font-variant-numeric: tabular-nums;
  }

  .ds-progress__detail {
    margin: 0;
    overflow: hidden;
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
    font-variant-numeric: tabular-nums;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  /* Label over the track: the track moves to the second row, whatever the
     markup's order. */
  .ds-progress--label-above {
    display: grid;
  }

  .ds-progress--label-above > .ds-progress__label {
    grid-row: 1;
    margin: 0 0 calc(var(--ds-space-2) + var(--ds-density, 0) * 2px);
  }

  .ds-progress--label-above > .ds-progress__track {
    grid-row: 2;
  }

  .ds-progress--label-above > .ds-progress__detail {
    margin-top: calc(var(--ds-space-2) + var(--ds-density, 0) * 2px);
  }

  /* Label at the track's end, one row; the detail stays under the track. */
  .ds-progress--label-end {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    column-gap: var(--ds-space-3);
    align-items: center;
  }

  .ds-progress--label-end > .ds-progress__label {
    margin: 0;
  }

  .ds-progress--label-end > .ds-progress__detail {
    grid-column: 1 / -1;
    margin-top: calc(var(--ds-space-1) + var(--ds-density, 0) * 1px);
  }

  /* Forced colors drop the fills and the background images: the parts
     paint in system colours (the bar, its segments and the dot Highlight,
     the remaining track GrayText), and the track keeps an edge. */
  @media (forced-colors: active) {
    .ds-progress {
      --ds-progress-bar: Highlight;
      --ds-progress-stop: Highlight;
      --ds-progress-track: GrayText;
    }

    .ds-progress__track {
      forced-color-adjust: none;
      outline: 1px solid CanvasText;
    }

  }

  /* Print: the bar and the track are backgrounds, which printing drops by
     default; the share stays visible. */
  @media print {
    .ds-progress {
      -webkit-print-color-adjust: exact;
      print-color-adjust: exact;
    }
  }
}

/* ── components/chart/chart.css ── */
/*
 * Charts: DS.chart (chart.js: line, area, stacked area, column, bar,
 * combo, sparkline, donut, pie, ring, gauge and bar gauge, SVG drawn by
 * the module into a .ds-chart figure), and the CSS-only marks of 2.x: a
 * meter (a share as a thin bar), columns (counts per category) and a
 * legend. Everything is drawn from the chart roles (--ds-chart-1 ...
 * --ds-chart-4, --ds-chart-neutral, --ds-chart-track, --ds-chart-warning,
 * --ds-chart-error).
 *
 *   <figure class="ds-chart" data-ds-chart="line">            the data is the page's <table>
 *     <figcaption>Requests per hour</figcaption>
 *     <table class="ds-table"> <thead> x, series ... </thead> <tbody> one row per point </tbody> </table>
 *   </figure>
 *   <figure class="ds-chart" data-ds-chart='{"type":"donut","labels":[...],"series":[...]}'>
 *
 * The module writes its parts after the caption, each data-ds-keep:
 *   .ds-chart__tools   the table view toggle (a quiet icon .ds-btn,
 *                      aria-pressed); .ds-chart__view
 *   .ds-chart__legend  li > button.ds-chart__key (aria-pressed: the series
 *                      shows) with an svg .ds-chart__swatch (a line with
 *                      its marker, or a fill) and .ds-chart__key-name
 *                      (.ds-chart__key-value: a slice's share, a ring's value)
 *   .ds-chart__frame   the plot, one tab stop (role application described
 *                      as a chart; img when it takes no keys, meter for a
 *                      gauge): svg.ds-chart__svg with its layers
 *                      .ds-chart__grid (__gridline, __baseline),
 *                      __bands (__zone), __hover (__band), __bars (__bar),
 *                      __areas (__area, __track), __lines (__line, __lone,
 *                      __slice, __zone-arc, __value-arc), __rules (__rule,
 *                      __rule-label), __axes (__tick, __tick--category,
 *                      __axis-title), __cursor, __markers (__marker),
 *                      __dots (__dot); the patterns (__pattern,
 *                      __pattern-ground, __pattern-ink); .ds-chart__centre
 *                      (__figure, __caption) of a donut, ring or gauge;
 *                      the tooltip .ds-chart__tip (__tip-title, __tip-row,
 *                      __tip-key, __tip-key-bar, __tip-gap, __tip-value,
 *                      __tip-name); .ds-chart__rows of a bar gauge
 *                      (__row, __row-head, __row-label, __row-status,
 *                      __row-value, __row-bar); the hint .ds-chart__hint
 *                      and the probe .ds-chart__probe (the lengths below,
 *                      read back by the module)
 *   .ds-chart__table   the table the module writes for a JSON chart
 *                      (__table-caption); visually hidden while the chart
 *                      shows, as is the page's own table
 * State: data-state="chart" or "table" on the figure (written).
 * Modifiers (written from the spec): .ds-chart--line, --area, --column,
 * --bar, --combo, --sparkline, --donut, --pie, --ring, --gauge,
 * --bargauge; .ds-chart--stacked; .ds-chart--patterns (series 2 to 4 of
 * fills hatched, as in forced colours). A series part carries
 * .ds-chart__series and .ds-chart__series--s2, --s3, --s4 or --other (the
 * neutral, after four), or a tone (.ds-tone-*, its own class, always
 * with its name); .ds-chart__series--dim while the keyboard picks another.
 * Lines of series 2 to 4 are dashed (--ds-chart-dash-2 ... -4) and every
 * series has its marker shape (circle, square, triangle, diamond), so
 * series stay apart without colour. Bars are value bars: a rect clipped
 * from --ds-chart-from to --ds-share (registered numbers the module sets),
 * so the round data end keeps its shape and a new value glides on
 * --ds-ease-value over --ds-dur-glide; stacked segments keep a seam and
 * only the outer end rounds (.ds-chart__bar--inner, --on, --down).
 * Lines and areas morph their path in the module (D14), on the same
 * curve and time.
 *
 * Options, computed in .ds-chart and its frame: size steps the plot
 * height (40px per step; radial 24px; a sparkline stays 32px), the widest
 * bar (4px), the marker (2px) and the legend key; density steps the plot
 * height (16px per step; radial 8px) and the legend's gaps; shape
 * multiplies the radius of a bar's data end, a legend key, the tooltip;
 * .ds-touch makes every legend key at least --ds-touch-target high. The
 * frame is container-driven: under 480px of chart width the plot is 3/4
 * of its height and a donut's legend goes under it (beside it from 480px,
 * shrinking to 10rem before it would wrap).
 *
 *   <span class="ds-meter" role="meter" aria-label="Disk" aria-valuemin="0" aria-valuemax="100"
 *         aria-valuenow="78" aria-valuetext="78% used"></span>     (the page sets --ds-share: .78)
 *
 *   <figure class="ds-columns">
 *     <figcaption class="ds-sr">Devices that checked in, per day</figcaption>
 *     <ol class="ds-columns__plot">
 *       <li class="ds-columns__col">                               (the page sets --ds-share on each column)
 *         <span class="ds-columns__value">42</span>
 *         <span class="ds-columns__fill" aria-hidden="true"></span>
 *         <span class="ds-columns__label">Mon</span>
 *       </li>
 *     </ol>
 *   </figure>
 *
 *   <ul class="ds-legend"><li><span class="ds-legend__key"></span>Opened</li><li><span class="ds-legend__key ds-legend__key--s2"></span>Closed</li></ul>
 *
 * Share: --ds-share (0 ... 1, registered in tokens.css), set by the page
 * on the mark (the meter, each column) with style.setProperty. A fill is
 * clipped at the share, never scaled, so its round data end keeps its
 * shape; a later value glides there on --ds-ease-value over
 * --ds-dur-glide, and a column's value rides on the top of its fill. The
 * first render fills from zero with .ds-enter--fill
 * (DS.motion.enterAll(marks, 'fill', { stagger: false })).
 *
 *   .ds-tone-*  on a .ds-meter, a .ds-columns__col or a .ds-legend__key, on
 *               the mark itself (an inherited tone would recolour a whole
 *               chart in a tinted region), always with words next to it:
 *               neutral, warning and error take their chart roles, the
 *               others the tone
 *   .ds-columns__col--s2, --s3, --s4           a column of series 2 to 4
 *   .ds-columns--mini                          a 32px sparkline of columns:
 *     no labels, the columns aria-hidden, the figure role="img" with a
 *     summary in its aria-label; .ds-columns__col--highlight takes
 *     --ds-chart-1, the rest --ds-chart-neutral; spans instead of the
 *     figure and the list inside a button or a link
 *   .ds-columns--grouped                       groups of columns side by
 *     side: .ds-columns__groups > .ds-columns__group (a .ds-columns__plot
 *     and a .ds-columns__label), columns 2px apart, the current group
 *     (.ds-columns__group--current, with a .ds-sr word) on a band of
 *     --ds-surface-low with its label in the label weight; put it in a
 *     .ds-scroll-x when it may be wider than its card
 *   :is(button, a).ds-columns__col             a column that opens its
 *     category: the state layer, an inset ring, the ripple, no morph
 *   .ds-legend__key--s2, --s3, --s4            a key of series 2 to 4
 *
 * Options (src/core/options.css, docs/options.md), on the mark or any
 * ancestor; each is computed here, in the rule that uses it:
 *   size      .ds-xs ... .ds-xl: a meter's height 1px per step, the plot of
 *             the columns 24px per step, a legend key 2px per step; the
 *             type stays the meta font; not a sparkline (32px, it lines up
 *             with a figure)
 *   density   .ds-density-*: the plot of the columns 12px per step; not a
 *             meter, which is thin already, and not the type
 *   shape     .ds-shape-*: multiplies the radius of a meter, of a column's
 *             data end and of a legend key
 *   touch     .ds-touch: a column that opens is at least --ds-touch-target
 *             high (its width comes from the chart's)
 *
 * Every chart has a text equivalent: its caption plus a table or a
 * key-value list, or the values as text. In forced colours the fills
 * take CanvasText, series 2 to 4 a hatching of their own (45, 135 and 90
 * degrees), as do the legend keys; a meter's track becomes Canvas with a
 * CanvasText outline. Printed, the fills keep their colours.
 *
 * DS.chart in forced colours: lines, markers and fills in CanvasText,
 * series 2 to 4 dashed and hatched (45, 135 and 90 degrees), gridlines
 * GrayText, the tooltip and the active slice with a CanvasText edge, the
 * legend keys Highlight while they show (an on/off toggle).
 * -webkit-print-color-adjust stays: Chromium took the plain name late.
 *
 * Hooks: --ds-meter-height (4px), --ds-meter-track (--ds-chart-track),
 * --ds-meter-color (--ds-chart-1), --ds-columns-height (120px),
 * --ds-columns-radius (--ds-radius-xs), --ds-columns-group-min (56px),
 * --ds-chart-color (the series of a column or a legend key, set by the
 * modifiers), --ds-legend-key-size (12px), --ds-chart-forced-ink (CanvasText);
 * DS.chart: --ds-chart-height (240px), --ds-chart-radial-height (200px),
 * --ds-chart-gauge-height (160px), --ds-chart-spark-height (32px),
 * --ds-chart-bar (24px), --ds-chart-radius (--ds-radius-xs),
 * --ds-chart-stroke (2px), --ds-chart-marker (8px), --ds-chart-grid
 * (--ds-line), --ds-chart-area-opacity (--ds-state-dragged),
 * --ds-chart-stack-opacity (--ds-state-stale), --ds-chart-dash-2 ... -4.
 *
 * Progressive:
 * - content-visibility: auto (the table a screen reader reads while the
 *   chart shows is not laid out, so a long series stays fast; it stays in
 *   the accessibility tree): without it the hidden table is laid out.
 */

/* The start of a value bar of DS.chart (0 ... 1, the share it rests on in
   a stack), written by the module; registered so it glides with
   --ds-share. */
@property --ds-chart-from {
  syntax: '<number>';
  inherits: false;
  initial-value: 0;
}

@layer ds.components.chart {
  /* ── Meter ── */

  .ds-meter {
    --_h: calc(var(--ds-meter-height, 4px) + var(--ds-size-step, 0) * 1px);
    --_radius: min(calc(min(var(--ds-radius-action), calc(var(--_h) / 2)) * var(--ds-shape, 1)), calc(var(--_h) / 2));
    --_fill: var(--ds-meter-color, var(--ds-chart-1));
    display: block;
    position: relative;
    height: var(--_h);
    border-radius: var(--_radius);
    background: var(--ds-meter-track, var(--ds-chart-track));
    transition: --ds-share var(--ds-dur-glide) var(--ds-ease-value);
  }

  .ds-meter::before {
    content: '';
    position: absolute;
    inset: 0;
    border-radius: inherit;
    background: var(--_fill);
    clip-path: inset(0 calc((1 - var(--ds-share)) * 100%) 0 0 round var(--_radius));
  }

  /* The tone of the meter itself; it beats a --ds-meter-color of the theme,
     as the meaning goes first. */
  .ds-meter:is(.ds-tone-primary, .ds-tone-info, .ds-tone-success) {
    --_fill: var(--ds-tone);
  }

  .ds-meter.ds-tone-neutral {
    --_fill: var(--ds-chart-neutral);
  }

  .ds-meter.ds-tone-warning {
    --_fill: var(--ds-chart-warning);
  }

  .ds-meter.ds-tone-error {
    --_fill: var(--ds-chart-error);
  }

  /* ── Columns ── */

  /* No top margin of their own: inside a card the card's rhythm spaces
     them (zero weight). */
  :where(.ds-columns, .ds-legend) {
    margin-top: 0;
  }

  /* Block also as a <span>: a sparkline inside a tile that is a button. */
  .ds-columns {
    display: block;
    min-width: 0;
    margin-inline: 0;
    margin-bottom: 0;
  }

  .ds-columns__plot,
  .ds-columns__groups {
    display: grid;
    grid-auto-columns: minmax(0, 1fr);
    grid-auto-flow: column;
    gap: var(--ds-space-3);
    margin: 0;
    /* Room above a full column for its value. */
    padding: var(--ds-space-6) 0 0;
    list-style: none;
  }

  /* An interactive column sits in a plain <li>, which holds its place. */
  .ds-columns__plot > li:not(.ds-columns__col) {
    display: grid;
    min-width: 0;
  }

  .ds-columns__col {
    --_plot: calc(var(--ds-columns-height, 120px) + var(--ds-size-step, 0) * 24px + var(--ds-density, 0) * 12px);
    position: relative;
    display: grid;
    grid-template-rows: var(--_plot) auto;
    justify-items: center;
    row-gap: var(--ds-space-2);
    min-width: 0;
    transition: --ds-share var(--ds-dur-glide) var(--ds-ease-value);
  }

  .ds-columns__fill,
  .ds-columns__value {
    grid-row: 1;
    grid-column: 1;
  }

  .ds-columns__fill {
    width: 100%;
    max-width: var(--ds-space-10);
    height: 100%;
    background: var(--ds-chart-color, var(--ds-chart-1));
    --_radius: calc(var(--ds-columns-radius, var(--ds-radius-xs)) * var(--ds-shape, 1));
    clip-path: inset(calc((1 - var(--ds-share)) * 100%) 0 0 0 round var(--_radius) var(--_radius) 0 0);
  }

  /* The value rides on the top of the fill: only the registered share
     transitions, the position follows it. */
  .ds-columns__value {
    align-self: end;
    translate: 0 calc(-1 * var(--ds-share) * var(--_plot) - var(--ds-space-1));
    color: var(--ds-text);
    font: var(--ds-font-meta);
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
  }

  .ds-columns__label {
    max-width: 100%;
    overflow: hidden;
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .ds-columns__col--s2 {
    --ds-chart-color: var(--ds-chart-2);
  }

  .ds-columns__col--s3 {
    --ds-chart-color: var(--ds-chart-3);
  }

  .ds-columns__col--s4 {
    --ds-chart-color: var(--ds-chart-4);
  }

  /* A sparkline of columns: no labels or values, one highlighted column. */
  .ds-columns--mini .ds-columns__plot {
    gap: 2px;
    padding: 0;
  }

  .ds-columns--mini .ds-columns__col {
    --ds-chart-color: var(--ds-chart-neutral);
    --_plot: var(--ds-space-8);
    grid-template-rows: var(--_plot);
    row-gap: 0;
  }

  .ds-columns--mini .ds-columns__col--highlight {
    --ds-chart-color: var(--ds-chart-1);
  }

  .ds-columns--mini :is(.ds-columns__value, .ds-columns__label) {
    display: none;
  }

  .ds-columns--mini .ds-columns__fill {
    max-width: none;
  }

  /* After the sparkline's neutral: a tone holds in a sparkline too. */
  .ds-columns__col:is(.ds-tone-primary, .ds-tone-info, .ds-tone-success) {
    --ds-chart-color: var(--ds-tone);
  }

  .ds-columns__col.ds-tone-neutral {
    --ds-chart-color: var(--ds-chart-neutral);
  }

  .ds-columns__col.ds-tone-warning {
    --ds-chart-color: var(--ds-chart-warning);
  }

  .ds-columns__col.ds-tone-error {
    --ds-chart-color: var(--ds-chart-error);
  }

  /* Groups of columns side by side, the label under each group. */
  .ds-columns__group {
    position: relative;
    display: grid;
    grid-template-rows: auto auto;
    justify-items: center;
    row-gap: var(--ds-space-2);
    min-width: var(--ds-columns-group-min, 56px);
    padding-inline: var(--ds-space-1);
  }

  .ds-columns--grouped .ds-columns__groups {
    grid-auto-columns: minmax(var(--ds-columns-group-min, 56px), 1fr);
    gap: var(--ds-space-2);
  }

  .ds-columns__group > .ds-columns__plot {
    gap: 2px;
    justify-self: stretch;
    padding: 0;
  }

  .ds-columns__group .ds-columns__col {
    grid-template-rows: var(--_plot);
    row-gap: 0;
  }

  .ds-columns__group .ds-columns__value {
    display: none;
  }

  .ds-columns__group--current {
    border-radius: calc(var(--ds-radius-xs) * var(--ds-shape, 1));
    background: var(--ds-surface-low);
  }

  .ds-columns__group--current > .ds-columns__label {
    color: var(--ds-text);
    font-weight: var(--ds-weight-label);
  }

  /* A column that opens its category: a state layer over the column,
     an inset ring, the ripple, no morph. */
  :is(button, a).ds-columns__col {
    isolation: isolate;
    width: 100%;
    min-height: var(--ds-target-min, 0px);
    padding: 0 0 var(--ds-space-1);
    border: 0;
    border-radius: calc(var(--ds-radius-xs) * var(--ds-shape, 1));
    background: none;
    color: inherit;
    font: inherit;
    text-decoration: none;
    cursor: pointer;
    -webkit-tap-highlight-color: transparent;
    outline-offset: 0;
    transition:
      --ds-share var(--ds-dur-glide) var(--ds-ease-value),
      outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  :is(button, a).ds-columns__col::before {
    content: '';
    position: absolute;
    inset: 0;
    z-index: -1;
    border-radius: inherit;
    background: currentColor;
    opacity: 0;
    pointer-events: none;
    transition: opacity var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  @media (hover: hover) {
    :is(button, a).ds-columns__col:hover::before {
      opacity: var(--ds-state-hover);
    }
  }

  :is(button, a).ds-columns__col:focus-visible::before {
    opacity: var(--ds-state-focus);
    transition-duration: 0s;
  }

  /* Press-in in --ds-dur-micro (.ds-pressed: js/ripple.js holds it). */
  :is(button, a).ds-columns__col:active::before,
  :is(button, a).ds-columns__col.ds-pressed::before {
    opacity: var(--ds-state-pressed);
    transition-duration: var(--ds-dur-micro);
  }

  :is(button, a).ds-columns__col:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: calc(-1 * var(--ds-focus-width));
  }

  /* ── Legend ── */

  .ds-legend {
    display: flex;
    flex-wrap: wrap;
    gap: var(--ds-space-1) var(--ds-space-4);
    margin-inline: 0;
    margin-bottom: 0;
    padding: 0;
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
    list-style: none;
  }

  .ds-legend > li {
    display: inline-flex;
    align-items: center;
    gap: var(--ds-space-2);
  }

  .ds-legend__key {
    --_size: calc(var(--ds-legend-key-size, 12px) + var(--ds-size-step, 0) * 2px);
    flex: none;
    width: var(--_size);
    height: var(--_size);
    border-radius: calc(var(--ds-radius-xs) * var(--ds-shape, 1));
    background: var(--ds-chart-color, var(--ds-chart-1));
  }

  .ds-legend__key--s2 {
    --ds-chart-color: var(--ds-chart-2);
  }

  .ds-legend__key--s3 {
    --ds-chart-color: var(--ds-chart-3);
  }

  .ds-legend__key--s4 {
    --ds-chart-color: var(--ds-chart-4);
  }

  /* The tone of the key itself. */
  .ds-legend__key:is(.ds-tone-primary, .ds-tone-info, .ds-tone-success) {
    --ds-chart-color: var(--ds-tone);
  }

  .ds-legend__key.ds-tone-neutral {
    --ds-chart-color: var(--ds-chart-neutral);
  }

  .ds-legend__key.ds-tone-warning {
    --ds-chart-color: var(--ds-chart-warning);
  }

  .ds-legend__key.ds-tone-error {
    --ds-chart-color: var(--ds-chart-error);
  }

  /* ── DS.chart ── */

  /* The figure: the caption and the tools on one line, then the legend,
     the frame and the table, each a line of its own. The lengths the
     module lays out with are computed here from the options (and read
     back through the probe). */
  .ds-chart {
    position: relative;
    --_bar: calc(var(--ds-chart-bar, 24px) + var(--ds-size-step, 0) * 4px);
    --_marker: calc(var(--ds-chart-marker, 8px) + var(--ds-size-step, 0) * 2px);
    --_stroke: var(--ds-chart-stroke, 2px);
    --_seam: 2px;
    --_gap: var(--ds-space-2);
    --_radius: calc(var(--ds-chart-radius, var(--ds-radius-xs)) * var(--ds-shape, 1));
    container: ds-chart / inline-size;
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: calc(var(--ds-space-3) + var(--ds-density, 0) * 2px) var(--ds-space-2);
    min-width: 0;
    margin: 0;
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
  }

  .ds-chart > * {
    flex: 1 1 100%;
    min-width: 0;
  }

  /* The tools stand at the end of the first line, over the caption's (or
     the legend's) room for them. */
  .ds-chart > figcaption {
    display: flex;
    align-items: center;
    min-height: var(--ds-space-8);
    color: var(--ds-text);
    font: var(--ds-font-label);
  }

  .ds-chart:has(> .ds-chart__tools:not([hidden])) > figcaption,
  .ds-chart:not(:has(> figcaption)):has(> .ds-chart__tools:not([hidden])) > .ds-chart__legend {
    padding-inline-end: var(--ds-space-10);
  }

  .ds-chart__tools {
    position: absolute;
    top: 0;
    inset-inline-end: 0;
    display: flex;
    gap: var(--ds-space-1);
  }

  :is(.ds-chart__tools, .ds-chart__legend, .ds-chart__centre)[hidden] {
    display: none;
  }

  /* The table view: the plot and its legend give way to the table. While
     the chart shows, the tables (the module's, or the page's own) stay for
     screen readers only. */
  .ds-chart[data-state="table"] > :is(.ds-chart__frame, .ds-chart__legend) {
    display: none;
  }

  /* flex and clip-path as well: a wrapper of the page's (a .ds-table-wrap,
     in a later layer) may keep its own position and overflow. Not laid out
     (content-visibility), yet read: a table of 10,000 rows would take
     seconds of layout on every new value. */
  .ds-chart[data-state="chart"] > :not(figcaption, .ds-chart__tools, .ds-chart__legend, .ds-chart__frame) {
    content-visibility: auto;
    flex: none;
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }

  .ds-chart__table {
    position: relative;
    overflow-x: auto;
  }

  .ds-chart__table-caption {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }

  /* ── Legend: one toggle per series ── */

  .ds-chart__legend {
    display: flex;
    flex-wrap: wrap;
    gap: 0 calc(var(--ds-space-1) + var(--ds-density, 0) * 1px);
    margin: 0;
    margin-inline-start: calc(-1 * var(--ds-space-2));
    padding: 0;
    list-style: none;
  }

  .ds-chart__key {
    --_h: calc(28px + var(--ds-size-step, 0) * 4px + var(--ds-density, 0) * 2px);
    --_box: max(var(--ds-target-min, 0px), var(--_h));
    --_half: calc(var(--_box) / 2);
    --_key-radius: min(calc(min(var(--ds-radius-action), var(--_half)) * var(--ds-shape, 1)), var(--_half));
    position: relative;
    isolation: isolate;
    display: inline-flex;
    align-items: center;
    gap: var(--ds-space-2);
    min-height: var(--_box);
    padding: 0 var(--ds-space-2);
    border: 0;
    border-radius: var(--_key-radius);
    background: transparent;
    color: var(--ds-text);
    font: var(--ds-font-meta);
    cursor: pointer;
    -webkit-tap-highlight-color: transparent;
    outline-offset: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    transition:
      color var(--ds-dur-fast) var(--ds-ease-in-out),
      border-radius var(--ds-dur-medium) var(--ds-ease-spatial),
      outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-chart__key::before {
    content: '';
    position: absolute;
    inset: 0;
    z-index: -1;
    border-radius: inherit;
    background: currentColor;
    opacity: 0;
    pointer-events: none;
    transition: opacity var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  @media (hover: hover) {
    .ds-chart__key:hover::before {
      opacity: var(--ds-state-hover);
    }
  }

  /* Press-in in --ds-dur-micro (.ds-pressed: js/ripple.js holds it). */
  .ds-chart__key:active::before,
  .ds-chart__key.ds-pressed::before {
    opacity: var(--ds-state-pressed);
    transition-duration: var(--ds-dur-micro);
  }

  .ds-chart__key:active,
  .ds-chart__key.ds-pressed {
    border-radius: min(calc(var(--ds-radius-action-pressed) * var(--ds-shape, 1)), var(--_key-radius));
    transition: border-radius var(--ds-dur-micro) var(--ds-ease-out);
  }

  /* With DS.ripple.attach() the ripple brings the press; the flat layer
     stays at its hover value. */
  :where(.ds-ripples) .ds-chart__key:where(:not([data-ds-ripple="off"], [data-ds-ripple="off"] *)):is(:active, .ds-pressed)::before {
    opacity: 0;
  }

  @media (hover: hover) {
    :where(.ds-ripples) .ds-chart__key:where(:not([data-ds-ripple="off"], [data-ds-ripple="off"] *)):is(:active, .ds-pressed)::before {
      opacity: var(--ds-state-hover);
    }
  }

  .ds-chart__key:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: var(--ds-focus-offset);
  }

  .ds-chart__key:focus-visible::before {
    opacity: var(--ds-state-focus);
    transition-duration: 0s;
  }

  /* A hidden series: the name struck through, the key hollow (never by
     colour alone; aria-pressed says it to screen readers). */
  .ds-chart__key[aria-pressed="false"] {
    color: var(--ds-text-2);
  }

  .ds-chart__key[aria-pressed="false"] .ds-chart__key-name {
    text-decoration: line-through;
  }

  .ds-chart__key-value {
    color: var(--ds-text-2);
    font-variant-numeric: tabular-nums;
  }

  .ds-chart__swatch {
    flex: none;
    width: calc(20px + var(--ds-size-step, 0) * 2px);
    height: calc(12px + var(--ds-size-step, 0) * 2px);
    overflow: visible;
  }

  .ds-chart__swatch-fill {
    fill: var(--_ink);
    stroke: var(--_ink);
    stroke-width: 1.5px;
    rx: calc(var(--ds-radius-xs) / 2 * var(--ds-shape, 1));
    transition: fill var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  .ds-chart__key[aria-pressed="false"] .ds-chart__swatch-fill {
    fill: transparent;
  }

  .ds-chart__key[aria-pressed="false"] .ds-chart__swatch-line {
    stroke: var(--ds-text-2);
  }

  .ds-chart__key[aria-pressed="false"] .ds-chart__swatch-marker {
    fill: transparent;
    stroke: var(--ds-text-2);
    stroke-width: 1.5px;
  }

  .ds-chart__swatch-marker {
    fill: var(--_ink);
  }

  /* ── Series colours, in their fixed order ── */

  .ds-chart__series {
    --_ink: var(--ds-chart-1);
    --_dash: none;
  }

  .ds-chart__series--s2 {
    --_ink: var(--ds-chart-2);
    --_dash: var(--ds-chart-dash-2, 8px 4px);
    --_pattern: var(--ds-chart-pattern-2, var(--_ink));
  }

  .ds-chart__series--s3 {
    --_ink: var(--ds-chart-3);
    --_dash: var(--ds-chart-dash-3, 2px 4px);
    --_pattern: var(--ds-chart-pattern-3, var(--_ink));
  }

  .ds-chart__series--s4 {
    --_ink: var(--ds-chart-4);
    --_dash: var(--ds-chart-dash-4, 12px 4px 2px 4px);
    --_pattern: var(--ds-chart-pattern-4, var(--_ink));
  }

  .ds-chart__series--other {
    --_ink: var(--ds-chart-neutral);
  }

  /* A tone of the series (or zone, or rule) itself; always with its name. */
  :is(.ds-chart__series, .ds-chart__zone, .ds-chart__rule, .ds-chart__zone-arc, .ds-chart__value-arc, .ds-chart__row):is(.ds-tone-primary, .ds-tone-info, .ds-tone-success) {
    --_ink: var(--ds-tone);
  }

  :is(.ds-chart__series, .ds-chart__zone, .ds-chart__rule, .ds-chart__zone-arc, .ds-chart__value-arc, .ds-chart__row).ds-tone-neutral {
    --_ink: var(--ds-chart-neutral);
  }

  :is(.ds-chart__series, .ds-chart__zone, .ds-chart__rule, .ds-chart__zone-arc, .ds-chart__value-arc, .ds-chart__row).ds-tone-warning {
    --_ink: var(--ds-chart-warning);
  }

  :is(.ds-chart__series, .ds-chart__zone, .ds-chart__rule, .ds-chart__zone-arc, .ds-chart__value-arc, .ds-chart__row).ds-tone-error {
    --_ink: var(--ds-chart-error);
  }

  /* ── The frame and the plot ── */

  .ds-chart__frame {
    --_h: calc(var(--ds-chart-height, 240px) + var(--ds-size-step, 0) * 40px + var(--ds-density, 0) * 16px);
    position: relative;
    height: var(--_h);
    border-radius: var(--_radius);
    outline-offset: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    transition: outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-chart__frame:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: var(--ds-focus-offset);
  }

  :is(.ds-chart--donut, .ds-chart--pie, .ds-chart--ring) > .ds-chart__frame {
    --_h: calc(var(--ds-chart-radial-height, 200px) + var(--ds-size-step, 0) * 24px + var(--ds-density, 0) * 8px);
  }

  .ds-chart--gauge > .ds-chart__frame {
    --_h: calc(var(--ds-chart-gauge-height, 160px) + var(--ds-size-step, 0) * 24px + var(--ds-density, 0) * 8px);
  }

  .ds-chart--bargauge > .ds-chart__frame {
    height: auto;
  }

  /* A sparkline lines up with a figure: 32px, no tools, no legend. */
  .ds-chart--sparkline {
    display: block;
  }

  .ds-chart--sparkline > .ds-chart__frame {
    --_h: var(--ds-chart-spark-height, 32px);
  }

  /* The plot is drawn in SVG coordinates, left to right in every
     direction (the tooltip and the centre figure follow them). */
  .ds-chart__svg {
    display: block;
    direction: ltr;
    overflow: visible;
    font: var(--ds-font-meta);
    -webkit-user-select: none;
    user-select: none;
  }

  /* Read back by the module: the gap, the widest bar, the seam, the marker. */
  .ds-chart__probe {
    position: absolute;
    top: 0;
    inset-inline-start: 0;
    inline-size: var(--_bar);
    block-size: var(--_marker);
    padding-block-start: var(--_gap);
    padding-inline-start: var(--_seam);
    visibility: hidden;
    pointer-events: none;
  }

  .ds-chart__hint {
    display: none;
  }

  /* A chart without a value says so in its frame, without empty axes. */
  .ds-chart__empty {
    position: absolute;
    inset: 0;
    display: none;
    place-items: center;
    color: var(--ds-text-2);
    font: var(--ds-font-body);
  }

  .ds-chart--empty .ds-chart__empty {
    display: grid;
  }

  .ds-chart--empty .ds-chart__svg {
    visibility: hidden;
  }

  /* Narrow charts (container-driven): a lower plot. */
  @container ds-chart (width < 480px) {
    .ds-chart:not(.ds-chart--sparkline, .ds-chart--donut, .ds-chart--pie, .ds-chart--ring, .ds-chart--gauge) > .ds-chart__frame {
      height: calc(var(--_h) * 0.75);
    }

    .ds-chart__tick--category {
      font: var(--ds-font-caption);
    }
  }

  /* Wide donuts, pies and rings: the legend beside the plot, a column of keys with their shares. */
  @container ds-chart (width >= 480px) {
    :is(.ds-chart--donut, .ds-chart--pie, .ds-chart--ring) > .ds-chart__frame {
      flex: 0 0 var(--_h);
      order: 1;
    }

    /* From no basis up to one and a half plots wide (the frame's height,
       computed as the frame does), so a share stays next to its name in a
       wide card. With a basis of zero the line breaks only below the
       legend's minimum: it shrinks beside the plot first (a half-width
       card of 530px keeps it there). */
    :is(.ds-chart--donut, .ds-chart--pie, .ds-chart--ring) > .ds-chart__legend {
      flex: 1 1 0;
      min-inline-size: 10rem;
      max-inline-size: calc((var(--ds-chart-height, 240px) + var(--ds-size-step, 0) * 40px + var(--ds-density, 0) * 16px) * 1.5);
      flex-direction: column;
      order: 2;
      margin-inline-start: var(--ds-space-6);
      padding-inline-end: 0;
    }

    :is(.ds-chart--donut, .ds-chart--pie, .ds-chart--ring) .ds-chart__key {
      width: 100%;
    }

    :is(.ds-chart--donut, .ds-chart--pie, .ds-chart--ring) .ds-chart__key-value {
      margin-inline-start: auto;
    }
  }

  .ds-chart__gridline {
    stroke: var(--ds-chart-grid, var(--ds-line));
    stroke-width: 1px;
    shape-rendering: crispEdges;
  }

  .ds-chart__baseline {
    stroke: var(--ds-line-2);
    stroke-width: 1px;
    shape-rendering: crispEdges;
  }

  .ds-chart__tick {
    fill: var(--ds-text-2);
    font-variant-numeric: tabular-nums;
  }

  .ds-chart__axis-title {
    fill: var(--ds-text-2);
  }

  /* The hover band of columns, and the crosshair of lines. */
  .ds-chart__band {
    fill: currentColor;
    opacity: 0;
    transition: opacity var(--ds-dur-instant) var(--ds-ease-in-out);
  }

  .ds-chart__band--on {
    opacity: var(--ds-state-hover);
    transition-duration: var(--ds-dur-fast);
  }

  .ds-chart__cursor {
    stroke: var(--ds-outline);
    stroke-width: 1px;
    shape-rendering: crispEdges;
    opacity: 0;
    pointer-events: none;
    transition: opacity var(--ds-dur-instant) var(--ds-ease-in-out);
  }

  .ds-chart__cursor--on {
    opacity: 1;
    transition-duration: var(--ds-dur-fast);
  }

  /* ── Marks ── */

  /* A value bar: clipped from --ds-chart-from to --ds-share, never scaled,
     so its round data end keeps its shape while the share glides. A
     segment that rests on another leaves the seam; only the outer end of
     a stack rounds. */
  .ds-chart__bar {
    --_r: var(--_radius);
    --_base: 0px;
    fill: var(--_pattern-fill, var(--_ink));
    clip-path: inset(calc((1 - var(--ds-share)) * 100%) 0 calc(var(--ds-chart-from) * 100% + var(--_base)) 0 round var(--_r) var(--_r) 0 0);
    transition:
      --ds-share var(--ds-dur-glide) var(--ds-ease-value),
      --ds-chart-from var(--ds-dur-glide) var(--ds-ease-value),
      opacity var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  .ds-chart__bar--down {
    clip-path: inset(calc((1 - var(--ds-share)) * 100% + var(--_base)) 0 calc(var(--ds-chart-from) * 100%) 0 round 0 0 var(--_r) var(--_r));
  }

  .ds-chart--bar .ds-chart__bar {
    clip-path: inset(0 calc((1 - var(--ds-share)) * 100%) 0 calc(var(--ds-chart-from) * 100% + var(--_base)) round 0 var(--_r) var(--_r) 0);
  }

  .ds-chart--bar .ds-chart__bar--down {
    clip-path: inset(0 calc((1 - var(--ds-share)) * 100% + var(--_base)) 0 calc(var(--ds-chart-from) * 100%) round var(--_r) 0 0 var(--_r));
  }

  .ds-chart__bar--inner {
    --_r: 0px;
  }

  .ds-chart__bar--on {
    --_base: var(--_seam);
  }

  .ds-chart--patterns .ds-chart__bar,
  .ds-chart--patterns .ds-chart__slice {
    --_pattern-fill: var(--_pattern);
  }

  .ds-chart__pattern-ground {
    fill: var(--_ink);
  }

  .ds-chart__pattern-ink {
    fill: var(--ds-surface);
    opacity: var(--ds-state-stale);
  }

  .ds-chart__line {
    fill: none;
    stroke: var(--_ink);
    stroke-width: var(--_stroke);
    stroke-dasharray: var(--_dash);
    stroke-linecap: round;
    stroke-linejoin: round;
    transition: opacity var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  .ds-chart__area {
    fill: var(--_ink);
    fill-opacity: var(--ds-chart-area-opacity, var(--ds-state-dragged));
    stroke: none;
    transition: opacity var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  .ds-chart--stacked .ds-chart__area {
    fill-opacity: var(--ds-chart-stack-opacity, var(--ds-state-stale));
  }

  .ds-chart--patterns .ds-chart__area.ds-chart__series:is(.ds-chart__series--s2, .ds-chart__series--s3, .ds-chart__series--s4) {
    fill: var(--_pattern);
  }

  /* Markers and the cursor's dots: the series shape with a ring of the
     surface, so they read where they cross a line. */
  .ds-chart__marker,
  .ds-chart__dot {
    fill: var(--_ink);
    stroke: var(--ds-surface);
    stroke-width: 2px;
    paint-order: stroke;
  }

  .ds-chart__series--dim {
    opacity: var(--ds-state-stale);
  }

  .ds-chart__track {
    fill: var(--ds-chart-track);
  }

  .ds-chart__slice {
    fill: var(--_pattern-fill, var(--_ink));
    transition: opacity var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  .ds-chart__lines:has(.ds-chart__slice--active) > .ds-chart__slice:not(.ds-chart__slice--active) {
    opacity: var(--ds-state-stale);
  }

  .ds-chart__value-arc {
    --_ink: var(--ds-chart-1);
  }

  .ds-chart__zone-arc {
    --_ink: var(--ds-chart-neutral);
    fill: var(--_ink);
  }

  /* Thresholds and annotations: a line or a wash, with its word. */
  .ds-chart__rule {
    --_ink: var(--ds-outline);
    stroke: var(--_ink);
    stroke-width: 1px;
    stroke-dasharray: 4px 4px;
    shape-rendering: crispEdges;
  }

  .ds-chart__zone {
    --_ink: var(--ds-chart-neutral);
    fill: var(--_ink);
    fill-opacity: var(--ds-state-hover);
  }

  .ds-chart__rule-label {
    fill: var(--ds-text-2);
    paint-order: stroke;
    stroke: var(--ds-surface);
    stroke-width: 3px;
    stroke-linejoin: round;
  }

  /* ── The centre figure of a donut, ring or gauge ── */

  .ds-chart__centre {
    position: absolute;
    top: var(--ds-chart-cy, 50%);
    left: var(--ds-chart-cx, 50%);
    display: grid;
    justify-items: center;
    max-width: max(var(--ds-space-12), calc(var(--ds-chart-hole, 0px) * 0.8));
    translate: -50% -50%;
    text-align: center;
    pointer-events: none;
  }

  .ds-chart__figure {
    color: var(--ds-text);
    font: var(--ds-font-headline);
    white-space: nowrap;
  }

  .ds-chart__caption {
    overflow: hidden;
    max-width: 100%;
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .ds-chart--pie .ds-chart__centre {
    display: none;
  }

  .ds-chart--gauge .ds-chart__centre {
    translate: -50% -40%;
  }

  /* ── The tooltip: follows the cursor inside the frame ── */

  .ds-chart__tip {
    position: absolute;
    top: 0;
    left: 0;
    z-index: var(--ds-z-raised);
    display: grid;
    gap: var(--ds-space-1);
    min-width: calc(var(--ds-space-12) * 2);
    padding: var(--ds-space-2) var(--ds-space-3);
    border: 1px solid transparent;
    border-radius: calc(var(--ds-radius-sm) * var(--ds-shape, 1));
    background: var(--ds-surface-popover);
    box-shadow: var(--ds-elev-popover);
    color: var(--ds-text);
    font: var(--ds-font-meta);
    opacity: 0;
    visibility: hidden;
    pointer-events: none;
    transition:
      opacity var(--ds-dur-instant) var(--ds-ease-in-out),
      visibility 0s linear var(--ds-dur-instant);
    transition-behavior: allow-discrete;
  }

  .ds-chart__tip[data-state="open"] {
    opacity: 1;
    visibility: visible;
    transition:
      opacity var(--ds-dur-fast) var(--ds-ease-in-out),
      visibility 0s;
  }

  .ds-chart__tip-title {
    color: var(--ds-text-2);
  }

  .ds-chart__tip-row {
    display: grid;
    grid-template-columns: auto auto 1fr;
    align-items: center;
    gap: var(--ds-space-2);
    white-space: nowrap;
  }

  .ds-chart__tip-key,
  .ds-chart__tip-gap {
    width: 16px;
    height: 4px;
    overflow: visible;
  }

  .ds-chart__tip-key .ds-chart__swatch-line {
    fill: none;
    stroke: var(--_ink);
    stroke-width: 2px;
    stroke-dasharray: var(--_dash);
    stroke-linecap: round;
  }

  .ds-chart__tip-key-bar {
    fill: none;
    stroke: var(--_ink);
    stroke-width: 4px;
  }

  .ds-chart__tip-value {
    font-weight: var(--ds-weight-label);
    font-variant-numeric: tabular-nums;
    text-align: end;
  }

  .ds-chart__tip-name {
    overflow: hidden;
    max-width: 16em;
    color: var(--ds-text-2);
    text-overflow: ellipsis;
  }

  /* The swatch line of the legend: the series dash, a short sample. */
  .ds-chart__swatch-line {
    fill: none;
    stroke: var(--_ink);
    stroke-width: 2px;
    stroke-dasharray: var(--_dash);
  }

  /* ── Bar gauge: one labelled meter per row ── */

  .ds-chart__rows {
    display: grid;
    gap: calc(var(--ds-space-3) + var(--ds-density, 0) * 2px);
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .ds-chart__row {
    --_ink: var(--ds-chart-1);
    display: grid;
    gap: var(--ds-space-1);
  }

  .ds-chart__row-head {
    display: flex;
    align-items: baseline;
    gap: var(--ds-space-2);
    min-width: 0;
  }

  .ds-chart__row-label {
    overflow: hidden;
    color: var(--ds-text);
    font: var(--ds-font-body);
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .ds-chart__row-status {
    color: var(--ds-text-2);
  }

  .ds-chart__row-value {
    margin-inline-start: auto;
    color: var(--ds-text);
    font: var(--ds-font-label);
    font-variant-numeric: tabular-nums;
  }

  .ds-chart__row-bar {
    --_h: calc(8px + var(--ds-size-step, 0) * 2px);
    --_row-radius: min(calc(min(var(--ds-radius-action), calc(var(--_h) / 2)) * var(--ds-shape, 1)), calc(var(--_h) / 2));
    position: relative;
    display: block;
    height: var(--_h);
    border-radius: var(--_row-radius);
    background: var(--ds-chart-track);
    transition: --ds-share var(--ds-dur-glide) var(--ds-ease-value);
  }

  .ds-chart__row-bar::before {
    content: '';
    position: absolute;
    inset: 0;
    border-radius: inherit;
    background: var(--_ink);
    clip-path: inset(0 calc((1 - var(--ds-share)) * 100%) 0 0 round var(--_row-radius));
  }

  /* Forced colours: the marks in CanvasText, series 2 to 4 dashed and
     hatched, the grid in GrayText, the shown legend keys Highlight. */
  @media (forced-colors: active) {
    .ds-chart__svg,
    .ds-chart__swatch,
    .ds-chart__tip-key,
    .ds-chart__row-bar {
      forced-color-adjust: none;
    }

    .ds-chart__series,
    .ds-chart__row,
    .ds-chart__value-arc,
    .ds-chart__zone-arc,
    .ds-chart__zone,
    .ds-chart__rule {
      --_ink: CanvasText;
    }

    .ds-chart__bar,
    .ds-chart__slice {
      --_pattern-fill: var(--_pattern);
    }

    .ds-chart__series--other {
      --_ink: GrayText;
    }

    .ds-chart__pattern-ground {
      fill: Canvas;
    }

    .ds-chart__pattern-ink {
      fill: CanvasText;
      opacity: 1;
    }

    .ds-chart__area,
    .ds-chart--stacked .ds-chart__area {
      fill-opacity: var(--ds-state-hover);
    }

    .ds-chart__gridline,
    .ds-chart__cursor {
      stroke: GrayText;
    }

    .ds-chart__baseline {
      stroke: CanvasText;
    }

    .ds-chart__tick,
    .ds-chart__axis-title,
    .ds-chart__rule-label {
      fill: CanvasText;
    }

    .ds-chart__rule-label {
      stroke: Canvas;
    }

    .ds-chart__marker,
    .ds-chart__dot {
      stroke: Canvas;
    }

    .ds-chart__band {
      fill: Highlight;
    }

    .ds-chart__track,
    .ds-chart__row-bar {
      fill: Canvas;
      background: Canvas;
      stroke: CanvasText;
      outline: 1px solid CanvasText;
    }

    .ds-chart__slice--active {
      stroke: Highlight;
      stroke-width: 3px;
    }

    .ds-chart__tip {
      border-color: CanvasText;
    }

    .ds-chart__key[aria-pressed="true"] {
      forced-color-adjust: none;
      background: Highlight;
      color: HighlightText;
    }

    .ds-chart__key[aria-pressed="true"] .ds-chart__swatch {
      --_ink: HighlightText;
      --_pattern-fill: HighlightText;
    }

    .ds-chart__key[aria-pressed="true"] .ds-chart__swatch-marker {
      stroke: Highlight;
    }

    .ds-chart__key[aria-pressed="false"] {
      color: CanvasText;
    }

    .ds-chart__row-bar::before {
      background: CanvasText;
    }
  }

  /* Forced colours drop the series colours: fills in the text colour,
     series 2 to 4 hatched, so they stay apart without colour. */
  @media (forced-colors: active) {
    .ds-meter {
      forced-color-adjust: none;
      background: Canvas;
      outline: 1px solid CanvasText;
    }

    .ds-meter::before {
      background: CanvasText;
    }

    /* --ds-chart-forced-ink: a component that lays the marks on a system
       fill of its own says which ink they take there. */
    .ds-columns__fill,
    .ds-legend__key {
      forced-color-adjust: none;
      background: var(--ds-chart-forced-ink, CanvasText);
    }

    .ds-legend__key--s2,
    .ds-columns__col--s2 > .ds-columns__fill {
      background: repeating-linear-gradient(45deg, CanvasText 0 2px, Canvas 2px 4px);
    }

    .ds-legend__key--s3,
    .ds-columns__col--s3 > .ds-columns__fill {
      background: repeating-linear-gradient(135deg, CanvasText 0 2px, Canvas 2px 4px);
    }

    .ds-legend__key--s4,
    .ds-columns__col--s4 > .ds-columns__fill {
      background: repeating-linear-gradient(90deg, CanvasText 0 2px, Canvas 2px 4px);
    }

    .ds-legend__key {
      outline: 1px solid CanvasText;
    }
  }

  /* Printed, the fills keep their colours (browsers drop backgrounds by
     default, which would print empty charts). */
  @media print {
    .ds-meter,
    .ds-meter::before,
    .ds-columns__fill,
    .ds-legend__key,
    .ds-chart,
    .ds-chart__row-bar,
    .ds-chart__row-bar::before {
      -webkit-print-color-adjust: exact;
      print-color-adjust: exact;
    }
  }
}

/* ── components/tile/tile.css ── */
/*
 * Key figures: tonal tiles that fill their row, up to four (.ds-tiles--3:
 * three), at least --ds-tile-min-width (176px) each, in any container (a
 * page, a dialog, a sheet, beside the drawer).
 *
 *   <div class="ds-tiles">
 *     <div class="ds-tile">
 *       <p class="ds-tile__label">[icon] <span>Open items</span></p>
 *       <p class="ds-tile__value"><span class="ds-tile__figure">128</span><span class="ds-tile__unit">GB</span></p>
 *       <p class="ds-tile__delta ds-tone-success">[icon arrowUp 16]<span>12% more</span></p>
 *       <p class="ds-tile__note">Target 140</p>
 *       <div class="ds-tile__trend">[a sparkline: .ds-columns--mini, or the project's own]</div>
 *
 * The value never wraps and never takes a colour: on narrow tiles it gets
 * smaller instead (a broken number reads as another number). Status goes
 * into the label as an icon. A tile that opens something is a <button
 * class="ds-tile"> or <a class="ds-tile">: a 6% state layer, the press
 * in --ds-dur-micro (also while js/ripple.js holds .ds-pressed) with the
 * ripple, and keyboard focus with the focus layer and a ring that is solid
 * from the first frame and snaps from offset + width to the offset
 * (outline-offset, --ds-dur-fast); no lift, no scale. While pressed it
 * turns squarer (16px to --ds-tile-radius-pressed, 12px) in
 * --ds-dur-micro and springs back over --ds-dur-medium, like a card. A
 * disabled or aria-disabled tile shows no hover or press layer and does
 * not morph; an aria-disabled one keeps its focus layer.
 *
 * Values (docs/motion.md, "Data motion"): every new value goes through
 * DS.motion.countUp(el, next) (el the value, or its .ds-tile__figure when
 * it has a unit), which counts from the figure on screen
 * (the first call from 0) on --ds-ease-value over --ds-dur-glide,
 * retargets mid-count and gives assistive technology the final value. A
 * meter or progress bar set in the same task lands on the same frame. The
 * note changes at once.
 *
 * A tile that filters by its figure is a toggle: aria-pressed (or
 * aria-checked, aria-selected) on the <button class="ds-tile">. Selected it
 * takes --ds-tile-selected-bg (--ds-accent) with --ds-on-accent ink and a
 * static inset ring (a border of --ds-focus-width in --ds-selected-ring,
 * --ds-primary, on its ::after), so the focus ring stays free and both
 * read at once. The colours change on --ds-dur-fast, the ring shows at
 * once. Add a check or the label weight: never the tint alone. Forced
 * colours: Highlight / HighlightText.
 *
 * A value that does not fit ends in an ellipsis (the last resort: shorten
 * figures, the full value in data-tip). .ds-tile__value--empty: a value
 * that is missing ("No data"), in --ds-text-2 with the display font.
 *
 * The unit (.ds-tile__unit, inside the value): a short unit after the
 * figure ("GB", "ms", "%"), in the subtitle type and --ds-text-2, so the
 * figure stays the thing to read. With a unit the figure has an element
 * of its own, .ds-tile__figure, and countUp() runs on that: it writes
 * textContent, which on the value would take the unit with it.
 *
 * The target (.ds-tile__target): a .ds-meter (with a .ds-meter__threshold
 * at the target's share, meter.css) and one line of words under it,
 * .ds-tile__target-text ("92% of the target of 140"). The meter has its own
 * name and value text; the words say whether the target is met, never the
 * mark or the colour alone.
 *
 * The delta (.ds-tile__delta): how the figure moved, always an arrow and a
 * word. Without a tone it stays quiet; a .ds-tone-* on the delta itself
 * (the page decides whether up is good) lays it on the tone's tint. The
 * value itself never takes the colour. The trend (.ds-tile__trend): a slot
 * at the foot of the tile for a sparkline in --ds-tile-trend-color, so the
 * sparklines of a row line up whatever stands above them.
 *
 * Options (src/core/options.css, docs/options.md), on the tile, the row or
 * any ancestor; each is computed here, in the rule that uses it:
 *   size      .ds-xs ... .ds-xl: the value's size, an eighth of the display
 *             size per step; never the label, the note or the padding
 *   density   .ds-density-*: the padding 2px per step, the row's gap 2px
 *             per step; never the type
 *   shape     .ds-shape-*: multiplies the rest and the pressed radius
 *   touch     .ds-touch: a clickable tile at least --ds-touch-target high
 *   tone      .ds-tone-* on .ds-tile__delta only
 *
 * Hooks: --ds-tile-radius, --ds-tile-radius-pressed, --ds-tile-padding
 * (--ds-space-5, on a phone --ds-space-4; the head 4px less), --ds-tile-min-width
 * (176px), --ds-tiles-columns (4), --ds-tile-value-line (44px at the default
 * type scale), --ds-tile-trend-color (--ds-chart-1),
 * --ds-tile-selected-bg, --ds-selected-ring. It sets --ds-chart-forced-ink
 * in forced colours, for the marks of a sparkline (chart's hook, read there).
 *
 * On narrow tiles the value shrinks with the tile (container units).
 */

@layer ds.components.tile {
  /* Intrinsic columns: as many tiles per row as fit at their smallest width,
     never more than --ds-tiles-columns, each row filled. */
  .ds-tiles {
    --_gap: calc(var(--ds-space-3) + var(--ds-density, 0) * 2px);
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(min(100%, max(var(--ds-tile-min-width, 176px), (100% - (var(--ds-tiles-columns, 4) - 1) * var(--_gap)) / var(--ds-tiles-columns, 4))), 1fr));
    gap: var(--_gap);
  }

  .ds-tiles--3 {
    grid-template-columns: repeat(auto-fit, minmax(min(100%, max(var(--ds-tile-min-width, 176px), (100% - 2 * var(--_gap)) / 3)), 1fr));
  }

  .ds-tile {
    /* Its value scales with the tile (cqi, below). */
    container-type: inline-size;
    display: flex;
    flex-direction: column;
    --_pad: calc(var(--ds-tile-padding, var(--ds-space-5)) + var(--ds-density, 0) * 2px);
    --_radius: calc(var(--ds-tile-radius, var(--ds-radius-lg)) * var(--ds-shape, 1));
    min-width: 0;
    padding: calc(var(--_pad) - var(--ds-space-1)) var(--_pad) var(--_pad);
    border-radius: var(--_radius);
    background: var(--ds-surface-low);
  }

  @media (max-width: 600px) {
    .ds-tiles {
      --_gap: calc(var(--ds-space-2) + var(--ds-density, 0) * 2px);
    }

    .ds-tile {
      --_pad: calc(var(--ds-tile-padding, var(--ds-space-4)) + var(--ds-density, 0) * 2px);
    }
  }

  .ds-tile__label {
    display: flex;
    align-items: center;
    gap: var(--ds-space-2);
    margin: 0;
    color: var(--ds-text-2);
    font: var(--ds-font-body);
  }

  .ds-tile__label svg {
    flex-shrink: 0;
  }

  .ds-tile__value {
    --_size: calc(var(--ds-size-display) * (1 + var(--ds-size-step, 0) / 8));
    --_line: calc(var(--ds-tile-value-line, calc(var(--ds-size-display) * 11 / 9)) * (1 + var(--ds-size-step, 0) / 8));
    margin: var(--ds-space-2) 0 0;
    color: var(--ds-text);
    font: var(--ds-font-display);
    /* Tiles of a row are equally wide, so their values keep one size. */
    font-size: min(var(--_size), 26cqi);
    /* The display role's 44/36, or the theme's own through the hook, also on
       the size steps: the line height inside --ds-font-display cannot be read
       here to step it. */
    line-height: var(--_line);
    letter-spacing: 0;
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
    /* The last resort of a value too wide for its tile. */
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  /* A value that is missing: quieter, still in the display font (.ds-muted would replace the font). */
  .ds-tile__value--empty {
    color: var(--ds-text-2);
  }

  /* Clickable tile: the element's own button or link look is reset. */
  :is(button, a).ds-tile {
    position: relative;
    isolation: isolate;
    width: 100%;
    min-height: var(--ds-target-min, 0px);
    margin: 0;
    border: 0;
    color: inherit;
    font: inherit;
    text-align: start;
    text-decoration: none;
    cursor: pointer;
    -webkit-tap-highlight-color: transparent;
    /* The ring rests (invisible) one width further out and snaps in. */
    outline-offset: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    transition:
      background-color var(--ds-dur-fast) var(--ds-ease-in-out),
      color var(--ds-dur-fast) var(--ds-ease-in-out),
      border-radius var(--ds-dur-medium) var(--ds-ease-spatial),
      outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  /* The press morph: squarer while pressed (never rounder than at rest);
     the layer follows through border-radius: inherit. */
  :is(button, a).ds-tile:active:not(:disabled, [aria-disabled="true"]),
  :is(button, a).ds-tile.ds-pressed:not(:disabled, [aria-disabled="true"]) {
    border-radius: min(calc(var(--ds-tile-radius-pressed, var(--ds-radius-md)) * var(--ds-shape, 1)), var(--_radius));
    transition:
      background-color var(--ds-dur-fast) var(--ds-ease-in-out),
      color var(--ds-dur-fast) var(--ds-ease-in-out),
      border-radius var(--ds-dur-micro) var(--ds-ease-out),
      outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  :is(button, a).ds-tile::before {
    content: '';
    position: absolute;
    inset: 0;
    z-index: -1;
    border-radius: inherit;
    background: currentColor;
    opacity: 0;
    pointer-events: none;
    transition: opacity var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  @media (hover: hover) {
    :is(button, a).ds-tile:hover::before {
      opacity: var(--ds-state-hover-lg);
    }
  }

  :is(button, a).ds-tile:focus-visible::before {
    opacity: var(--ds-state-focus);
    transition-duration: 0s;
  }

  :is(button, a).ds-tile:active::before,
  :is(button, a).ds-tile.ds-pressed::before {
    opacity: var(--ds-state-pressed);
    transition-duration: var(--ds-dur-micro);
  }

  /* A blocked tile (disabled, aria-disabled) shows neither hover nor press,
     like its morph above; an aria-disabled tile keeps its focus layer. */
  @media (hover: hover) {
    :is(button, a).ds-tile:is(:disabled, [aria-disabled="true"]):hover::before {
      opacity: 0;
    }
  }

  :is(button, a).ds-tile:is(:disabled, [aria-disabled="true"]):is(:active, .ds-pressed)::before {
    opacity: 0;
  }

  :is(button, a).ds-tile[aria-disabled="true"]:focus-visible::before {
    opacity: var(--ds-state-focus);
  }

  :is(button, a).ds-tile:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: var(--ds-focus-offset);
  }

  /* On the tonal tile the quieter text colour is text-2, never text-3. */
  .ds-tile__note {
    margin: var(--ds-space-1) 0 0;
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
    font-variant-numeric: tabular-nums;
  }

  /* How the figure moved: an arrow and a word. Quiet without a tone. */
  .ds-tile__delta {
    display: inline-flex;
    align-items: center;
    align-self: flex-start;
    gap: var(--ds-space-1);
    max-width: 100%;
    margin: var(--ds-space-1) 0 0;
    color: var(--_delta-ink, var(--ds-text-2));
    font: var(--ds-font-caption);
    font-variant-numeric: tabular-nums;
  }

  .ds-tile__delta svg {
    flex: none;
  }

  /* On the delta itself: an inherited tone would colour every delta in a
     tinted region. The tint and its ink are a tested pair of each palette. */
  .ds-tile__delta:is(.ds-tone-neutral, .ds-tone-primary, .ds-tone-info, .ds-tone-success, .ds-tone-warning, .ds-tone-error) {
    padding: 2px var(--ds-space-2);
    border-radius: calc(var(--ds-radius-chip) * var(--ds-shape, 1));
    background: var(--ds-tone-container);
    color: var(--ds-on-tone-container);
  }

  /* A unit after the figure: quieter, and as large as it can be beside a
     figure that shrinks with its tile. */
  /* The figure beside a unit: what countUp() writes. Tabular, as the value. */
  .ds-tile__figure {
    font-variant-numeric: tabular-nums;
  }

  .ds-tile__unit {
    margin-inline-start: var(--ds-space-1);
    color: var(--ds-text-2);
    font: var(--ds-font-subtitle);
    letter-spacing: 0;
  }

  /* The target: a meter and its words, under the figure. */
  .ds-tile__target {
    display: grid;
    gap: var(--ds-space-1);
    margin-top: var(--ds-space-2);
  }

  .ds-tile__target-text {
    margin: 0;
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
    font-variant-numeric: tabular-nums;
  }

  /* A meter under the figure: how far it is to its target. */
  .ds-tile > .ds-meter {
    margin-top: var(--ds-space-2);
  }

  /* The foot of the tile: the sparklines of a row line up. */
  .ds-tile__trend {
    min-width: 0;
    margin-top: auto;
    padding-top: var(--ds-space-2);
    color: var(--ds-tile-trend-color, var(--ds-chart-1));
  }

  .ds-tile__trend svg {
    display: block;
    width: 100%;
  }

  /* Selected (a filter by this figure): the tint and a static inset ring on
     the free ::after (the state layer is ::before), so the focus ring stays
     free; the ring shows at once, the colours glide. */
  :is(button, a).ds-tile:is([aria-pressed="true"], [aria-checked="true"], [aria-selected="true"]) {
    --_delta-ink: var(--ds-on-accent);
    background: var(--ds-tile-selected-bg, var(--ds-accent));
    color: var(--ds-on-accent);
  }

  :is(button, a).ds-tile:is([aria-pressed="true"], [aria-checked="true"], [aria-selected="true"]) :is(.ds-tile__label, .ds-tile__value, .ds-tile__note) {
    color: var(--ds-on-accent);
  }

  :is(button, a).ds-tile:is([aria-pressed="true"], [aria-checked="true"], [aria-selected="true"])::after {
    content: '';
    position: absolute;
    inset: 0;
    border: var(--ds-focus-width) solid var(--ds-selected-ring, var(--ds-primary));
    border-radius: inherit;
    pointer-events: none;
  }

  @media (forced-colors: active) {
    :is(button, a).ds-tile:is([aria-pressed="true"], [aria-checked="true"], [aria-selected="true"]) {
      --_delta-ink: HighlightText;
      forced-color-adjust: none;
      background: Highlight;
      color: HighlightText;
    }

    /* forced-color-adjust inherits: a toned delta and a sparkline drop their
       own colours for the selection's. */
    :is(button, a).ds-tile:is([aria-pressed="true"], [aria-checked="true"], [aria-selected="true"]) .ds-tile__delta {
      background: transparent;
      color: HighlightText;
    }

    :is(button, a).ds-tile:is([aria-pressed="true"], [aria-checked="true"], [aria-selected="true"]) .ds-tile__trend {
      --ds-chart-forced-ink: HighlightText;
      color: HighlightText;
    }

    :is(button, a).ds-tile:is([aria-pressed="true"], [aria-checked="true"], [aria-selected="true"]) :is(.ds-tile__label, .ds-tile__value, .ds-tile__note) {
      color: HighlightText;
    }

    :is(button, a).ds-tile:is([aria-pressed="true"], [aria-checked="true"], [aria-selected="true"])::after {
      border-color: Highlight;
    }

    :is(button, a).ds-tile:is([aria-pressed="true"], [aria-checked="true"], [aria-selected="true"]):focus-visible {
      outline-color: CanvasText;
    }

    :is(button, a).ds-tile[aria-disabled="true"] {
      forced-color-adjust: none;
      background: Canvas;
      color: GrayText;
    }

    :is(button, a).ds-tile[aria-disabled="true"] :is(.ds-tile__label, .ds-tile__value, .ds-tile__note, .ds-tile__delta, .ds-tile__trend) {
      background: transparent;
      color: GrayText;
    }

    :is(button, a).ds-tile[aria-disabled="true"] .ds-tile__trend {
      --ds-chart-forced-ink: GrayText;
    }

    /* It stays focusable; unforced, its ring would keep the brand colour. */
    :is(button, a).ds-tile[aria-disabled="true"]:focus-visible {
      outline-color: CanvasText;
    }
  }

  /* Print: a short tile is never split across pages. */
  @media print {
    .ds-tile {
      break-inside: avoid;
    }
  }
}

/* ── components/list/list.css ── */
/*
 * Lists: an outlined list of rows that open a record, key-value rows
 * inside cards, a plain list, a definition grid of facts and a line of
 * parts separated by «·».
 *
 *   <ul class="ds-list ds-list--interactive" aria-label="Devices">
 *     <li class="ds-list__item" data-ds-key="d42"> [icon .ds-list__icon]
 *       <span class="ds-list__text"><span class="ds-list__title"><a class="ds-list__action" href="/devices/42">LAPTOP-0042</a></span>
 *         <span class="ds-list__meta">Notebook 14 · Building A</span></span>
 *       <span class="ds-status ...">...</span>
 *       <span class="ds-list__actions"><button class="ds-btn ds-btn--quiet ds-btn--icon ds-sm" type="button" aria-label="More for LAPTOP-0042">...</button></span>
 *       [icon chevronRight .ds-list__chevron]</li></ul>
 *   <ul class="ds-kv-list"><li><span>Name</span><strong>Value</strong></li></ul>
 *   <ul class="ds-kv-list ds-kv-list--interactive"><li><a class="ds-kv-list__row" href="/owners/7"><span>Owner</span><strong>Ada Lovelace</strong></a></li></ul>
 *   <ul class="ds-kv-list ds-kv-list--bars"><li><span>Disk</span><strong>78%</strong><span class="ds-meter" aria-hidden="true"></span></li></ul>
 *   <ul class="ds-plain-list"><li>...</li></ul>
 *   <dl class="ds-facts"><div><dt>Label</dt><dd>Value</dd></div></dl>
 *   <dl class="ds-facts ds-facts--rows"><div><dt>Label</dt><dd>Value <span class="ds-lock" role="img" aria-label="Set by the directory sync">[icon lock 16]</span></dd></div></dl>
 *   <span class="ds-parts"><span class="ds-parts__list"><span>3 new</span><span>1 updated</span></span></span>
 *
 * Row list (.ds-list): an outlined surface (never overflow: a row's menu
 * is not cut) with hairlines between rows; a row wraps its trailing parts
 * (status, actions, chevron) to a second line by itself when the text
 * would get narrower than --ds-list-text-min. .ds-list--interactive: one
 * .ds-list__action per row, whose ::after stretches over the row; the
 * row's other links and controls stay above it. The row takes a state
 * layer in currentColor (hover --ds-state-hover-lg, press
 * --ds-state-pressed in --ds-dur-micro, not while another control in the
 * row is pressed), the focus layer and an inset ring at once (through
 * :has(.ds-list__action:focus-visible), the ring snapping from the edge
 * inward), the ripple (js/ripple.js), and no morph. A row whose action is
 * disabled or aria-disabled shows no hover or press layer and takes the
 * not-allowed cursor; it keeps its focus layer. The current row
 * (aria-current on the row or on its action, not "false") takes
 * --ds-list-current-bg over --ds-dur-fast; in forced colours
 * SelectedItem, its other controls, chips and media on Canvas. Rows that enter through DS.motion.flip fade in over
 * --ds-dur-fast; while rows glide they stand on an opaque backing
 * (data-ds-glide and --ds-flip-backdrop on the list).
 *
 * Key-value rows: .ds-kv-list--interactive rows are links or buttons
 * (.ds-kv-list__row) with the state layer, an outer focus ring that snaps
 * in, the ripple and the disabled model (GrayText in forced colours); a
 * div.ds-kv-list__row is a static row among them. .ds-kv-list__icon
 * (with a tone) marks a value, always with a .ds-sr word.
 * strong.ds-muted is a quiet value (regular weight). .ds-kv-list--bars
 * puts a .ds-meter under each row (aria-hidden: the figure is in the
 * text); the label stays on one line and ends in an ellipsis.
 *
 * Facts take as many 220px columns as fit; exactly four facts get a
 * layout of their own, by the width of the content area. .ds-facts--rows
 * puts each fact on a row of its own, the label in a column of
 * --ds-facts-label-width; under 520px of content (or a 600px window)
 * the label goes above its value. .ds-lock marks a value another system
 * sets (with the lock glyph, a reason in its label and its tooltip): it
 * is not an action.
 *
 * Links in parts take an inset ring for keyboard focus (also without
 * .ds-base): solid from the first frame, it snaps from the edge inward
 * (outline-offset, --ds-dur-fast).
 *
 * A row (3.0) holds, all optional but the text: .ds-list__media (a
 * thumbnail or an avatar, round with --round) or .ds-list__icon; in
 * .ds-list__text the .ds-list__title, .ds-list__description (body font) and
 * .ds-list__meta; then .ds-list__aside (a short fact at the row's end: a
 * time, a count, in the meta font), a status chip, .ds-list__actions and
 * the chevron. .ds-list--stacked: the trailing parts always go under the
 * text, whatever the width. A .ds-list__group row holds a
 * .ds-list__heading (a letter, a day) that stays at the top of the nearest
 * scroller while its rows pass under it (--ds-list-group-top under a sticky
 * page head); the controls of those rows scroll to a stop below it when
 * focus moves up.
 *
 * DS.list (list.js, 3.0): .ds-list__check, a checkbox or a radio at a
 * row's start (data-ds-list-select); a checked row takes
 * --ds-list-selected-bg and keeps its box; a row of a selectable list
 * without an action takes the hover layer (a press toggles its box).
 * .ds-list__grip, the drag handle the module writes (data-ds-list-reorder,
 * DS.dnd; a dragged row, data-ds-dragging, keeps an opaque fill).
 * .ds-list--scroll: the list scrolls itself, up to --ds-list-max-height (a
 * virtual list); a row that holds the focus itself shows an inset ring.
 *
 * Facts (3.0): .ds-facts--stacked (one column), .ds-facts--grid (facts
 * span with .ds-facts__wide and .ds-facts__full; the grid is its own
 * container, so a wide fact takes the one column where only one fits),
 * .ds-facts--bordered (cells with hairlines and a frame,
 * --ds-facts-radius), .ds-facts__copy (the copy button DS.list writes after
 * a value with data-ds-facts-copy; data-state="copied" shows its check).
 *
 * Options (src/core/options.css, docs/options.md), on the list or any
 * ancestor; each is computed here, in the rule that uses it:
 *   size      .ds-xs ... .ds-xl: a row 8px per step (40, 48, 56, 64, 72px;
 *             the block padding 4px of it), its title the type role of the
 *             size (--ds-size-font), the media 4px per step; key-value
 *             rows and facts in rows 8px per step, in the body font
 *   density   .ds-density-*: a row 4px per step (56, 52, 48, 44px; the
 *             padding 2px per side, also sideways); key-value rows and
 *             facts in rows 4px per step; not the type, not the media
 *   shape     .ds-shape-*: multiplies the radius of the list, of its outer
 *             rows, of the media and of a key-value row
 *   touch     .ds-touch: a row and a key-value row that opens at least
 *             --ds-touch-target high; touch wins over size and density
 *   tone      .ds-tone-* on a .ds-kv-list__icon, on the icon itself (an
 *             inherited tone would colour every value); always with a
 *             .ds-sr word
 *
 * Hooks: --ds-list-item-height (56px), --ds-list-padding (--ds-space-4),
 * --ds-list-padding-y (--ds-space-3), --ds-list-radius (--ds-radius-card),
 * --ds-list-title-font (--ds-size-font, else --ds-font-label),
 * --ds-list-media-size (40px), --ds-list-media-radius (--ds-radius-sm),
 * --ds-list-text-min (12rem), --ds-list-current-bg (--ds-accent),
 * --ds-list-group-bg (--ds-surface), --ds-list-group-top (0px),
 * --ds-kv-list-padding (--ds-space-3), --ds-facts-label-width (36%),
 * --ds-list-selected-bg (--ds-accent), --ds-list-max-height (24rem),
 * --ds-facts-radius (--ds-radius-card).
 */

@layer ds.components.list {
  .ds-kv-list,
  .ds-plain-list {
    list-style: none;
    /* No top margin of their own: inside a card the card's rhythm spaces them. */
    margin-inline: 0;
    margin-bottom: 0;
    padding: 0;
  }

  /* A key-value row: 8px per size step, 4px per density step (its padding,
     no less than none); the type stays the body font. */
  .ds-kv-list li,
  .ds-kv-list__row {
    --_pad: max(0px, calc(var(--ds-kv-list-padding, var(--ds-space-3)) + var(--ds-size-step, 0) * 4px + var(--ds-density, 0) * 2px));
  }

  .ds-kv-list li {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: var(--ds-space-3);
    padding: var(--_pad) 0;
    border-top: 1px solid var(--ds-line);
    font: var(--ds-font-body);
  }

  .ds-kv-list li:first-child {
    border-top: none;
    padding-top: 0;
  }

  .ds-kv-list li:last-child {
    padding-bottom: 0;
  }

  .ds-kv-list :is(li, .ds-kv-list__row) > span {
    color: var(--ds-text-2);
  }

  /* Long labels and values wrap inside their own part. */
  .ds-kv-list :is(li, .ds-kv-list__row) > :is(span, strong) {
    min-width: 0;
    overflow-wrap: anywhere;
  }

  .ds-kv-list strong {
    font-weight: var(--ds-weight-label);
    text-align: end;
    font-variant-numeric: tabular-nums;
  }

  /* A quiet value ("Not set", "None"): regular weight. */
  .ds-kv-list strong.ds-muted {
    font-weight: var(--ds-weight-regular);
  }

  /* No top margin of the browser's either; zero weight, so the rhythm of
     a card (.ds-card > * + *) still spaces them. */
  :where(.ds-kv-list, .ds-plain-list, .ds-list) {
    margin-top: 0;
  }

  .ds-plain-list li + li {
    margin-top: calc(var(--ds-space-2) + var(--ds-density, 0) * 2px);
  }

  /* ── Facts: label above value, as many columns as fit ── */

  .ds-facts {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: calc(var(--ds-space-4) + var(--ds-density, 0) * 2px) var(--ds-space-8);
    margin: 0;
  }

  .ds-facts:empty {
    display: none;
  }

  /* Exactly four facts on a page never split three and one: four in a row,
     two and two on a narrower content area, one column on phones. Only
     inside the content area: a side sheet lives outside it and keeps the
     auto-fit columns above. */
  @container ds-content (min-width: 1041px) {
    .ds-facts:has(> :nth-child(4):last-child) {
      grid-template-columns: repeat(4, minmax(0, 1fr));
    }
  }

  @container ds-content (max-width: 1040px) {
    .ds-facts:has(> :nth-child(4):last-child) {
      grid-template-columns: repeat(2, minmax(0, 1fr));
    }
  }

  @container ds-content (max-width: 520px) {
    .ds-facts:has(> :nth-child(4):last-child) {
      grid-template-columns: minmax(0, 1fr);
    }
  }

  .ds-facts dt {
    color: var(--ds-text-2);
    font: var(--ds-font-caption);
  }

  .ds-facts dd {
    margin: var(--ds-space-1) 0 0;
    color: var(--ds-text);
    font: var(--ds-font-body);
    font-variant-numeric: tabular-nums;
    overflow-wrap: anywhere;
  }

  /* A trailing icon in a link (an external target) keeps a little air. Its
     own display: a layered preflight (svg { display: block }) would drop it
     below the text. */
  .ds-facts a svg {
    display: inline-block;
    margin-inline-start: var(--ds-space-1);
    vertical-align: -2px;
  }

  /*
   * Parts: a line of parts that wraps between the parts. A part moves to the
   * next line whole; only a part longer than a whole line wraps inside. Each
   * part brings its «·» in front, in a padding of its own; the list is
   * shifted left by one separator and clipped at the sides only, so the
   * separator of a part that starts a line is never seen (nothing dangles at
   * a line end, nothing leads the next line), while descenders and focus
   * rings above and below stay whole. A link in a part rings inside its own
   * box (an inset ring that snaps inward), so the side clip never cuts it.
   */
  .ds-parts {
    display: block;
    overflow-x: clip;
    overflow-y: visible;
  }

  /* The underline fade of the page base stays in the list. */
  .ds-parts a {
    outline-offset: 0;
    transition:
      text-decoration-color var(--ds-dur-fast) var(--ds-ease-in-out),
      outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-parts a:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: calc(-1 * var(--ds-focus-width));
  }

  .ds-parts__list {
    display: flex;
    flex-wrap: wrap;
    margin-inline-start: calc(-1 * var(--ds-space-3));
  }

  .ds-parts__list > span {
    position: relative;
    min-width: 0;
    padding-inline-start: var(--ds-space-3);
    overflow-wrap: anywhere;
  }

  .ds-parts__list > span::before {
    content: '·';
    position: absolute;
    top: 0;
    inset-inline-start: 0;
    /* As wide as « · » in running text. */
    width: var(--ds-space-3);
    text-align: center;
  }

  /*
   * Row list: records in rows that open them, on an outlined surface. It
   * never clips (overflow stays visible), so a row's menu is not cut; the
   * outer rows round their own corners for the layer and the ripple.
   */
  .ds-list {
    list-style: none;
    margin-inline: 0;
    margin-bottom: 0;
    padding: 0;
    border: 1px solid var(--ds-line);
    border-radius: calc(var(--ds-list-radius, var(--ds-radius-card)) * var(--ds-shape, 1));
    background: var(--ds-surface);
    color: var(--ds-text);
  }

  .ds-list:empty {
    display: none;
  }

  /* What the outer rows round (the list's radius inside its border), and
     the row's padding: never below none under the smallest size and the
     tightest density, so the height below is the one that counts. */
  .ds-list__item,
  .ds-list__group {
    --_inner: max(0px, calc(var(--ds-list-radius, var(--ds-radius-card)) * var(--ds-shape, 1) - 1px));
    --_pad-x: calc(var(--ds-list-padding, var(--ds-space-4)) + var(--ds-density, 0) * 2px);
    --_pad-y: max(0px, calc(var(--ds-list-padding-y, var(--ds-space-3)) + var(--ds-size-step, 0) * 4px + var(--ds-density, 0) * 2px));
  }

  .ds-list__item {
    /* A row that DS.motion.flip() brings in fades in quickly (the hook
       applies to the row itself, never to what is inside). */
    --ds-enter-duration: var(--ds-dur-fast);
    --_h: calc(var(--ds-list-item-height, 56px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px);
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--ds-space-2) var(--ds-space-3);
    box-sizing: border-box;
    min-height: max(var(--ds-target-min, 0px), var(--_h));
    padding: var(--_pad-y) var(--_pad-x);
    border-top: 1px solid var(--ds-line);
    font: var(--ds-font-body);
    /* A row that takes the focus itself (a virtual list's): an inset ring
       that rests on the row's edge and snaps inward. */
    outline-offset: 0;
    transition:
      background-color var(--ds-dur-fast) var(--ds-ease-in-out),
      outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-list > :is(.ds-list__item, .ds-list__group):first-child {
    border-top: 0;
    border-start-start-radius: var(--_inner);
    border-start-end-radius: var(--_inner);
  }

  .ds-list > :is(.ds-list__item, .ds-list__group):last-child {
    border-end-start-radius: var(--_inner);
    border-end-end-radius: var(--_inner);
  }

  /* A letter or a day: it stays at the top of the nearest scroller on an
     opaque fill, above the rows that pass under it (the list never clips). */
  .ds-list__group {
    position: sticky;
    inset-block-start: var(--ds-list-group-top, 0px);
    z-index: var(--ds-z-raised);
    padding: var(--ds-space-1) var(--_pad-x);
    border-top: 1px solid var(--ds-line);
    background: var(--ds-list-group-bg, var(--ds-surface));
  }

  /* Focus moving up stops below the heading, never under it (WCAG 2.4.11):
     the heading's height and the row's padding, so the row's ring shows too.
     A sibling selector, as only rows after a heading pass under one; no
     :has() here, its cost is in the note on facts above. */
  .ds-list__group ~ .ds-list__item :is(a[href], button, input, select, textarea, summary, [tabindex]) {
    scroll-margin-block-start: calc(var(--ds-list-group-top, 0px) + var(--ds-space-6) + var(--ds-space-1) + var(--_pad-y));
  }

  .ds-list__heading {
    margin: 0;
    color: var(--ds-text-2);
    font: var(--ds-font-caption);
  }

  /* The text takes the room; below its minimum the trailing parts drop to
     a second line by themselves (no container query). */
  .ds-list__text {
    display: grid;
    flex: 1 1 var(--ds-list-text-min, 12rem);
    gap: 2px;
    min-width: 0;
  }

  .ds-list__title {
    color: var(--ds-text);
    font: var(--ds-list-title-font, var(--ds-size-font, var(--ds-font-label)));
    overflow-wrap: anywhere;
  }

  .ds-list__description {
    color: var(--ds-text-2);
    font: var(--ds-font-body);
    overflow-wrap: anywhere;
  }

  .ds-list__meta {
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
    font-variant-numeric: tabular-nums;
    overflow-wrap: anywhere;
  }

  .ds-list__icon,
  .ds-list__chevron {
    flex: none;
    color: var(--ds-text-2);
  }

  /* A thumbnail or an avatar. Its transparent border is its edge in forced
     colours. */
  .ds-list__media {
    --_size: calc(var(--ds-list-media-size, 40px) + var(--ds-size-step, 0) * 4px);
    --_radius: var(--ds-list-media-radius, var(--ds-radius-sm));
    display: grid;
    flex: none;
    place-items: center;
    box-sizing: border-box;
    width: var(--_size);
    height: var(--_size);
    overflow: hidden;
    border: 1px solid transparent;
    border-radius: min(calc(min(var(--_radius), calc(var(--_size) / 2)) * var(--ds-shape, 1)), calc(var(--_size) / 2));
    background: var(--ds-surface-high);
    color: var(--ds-text-2);
    font: var(--ds-font-label);
  }

  .ds-list__media--round {
    --_radius: var(--ds-radius-action);
  }

  .ds-list__media > img {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: cover;
  }

  /* A short fact at the row's end: a time, a count. */
  .ds-list__aside {
    flex: none;
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
    font-variant-numeric: tabular-nums;
    text-align: end;
  }

  /* The chevron stays at the end, also on a second line. */
  .ds-list__chevron {
    margin-inline-start: auto;
  }

  .ds-list__actions {
    display: flex;
    flex: none;
    align-items: center;
    gap: var(--ds-space-1);
  }

  /* Stacked: the trailing parts always go under the text; the media or the
     icon holds its column beside all of them. */
  .ds-list--stacked > .ds-list__item {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    justify-items: start;
    row-gap: 0;
  }

  .ds-list--stacked > .ds-list__item:has(> :is(.ds-list__media, .ds-list__icon)) {
    grid-template-columns: auto minmax(0, 1fr);
  }

  /* Not the ripple: a grid column would become its containing block and
     move it off the pointer. */
  .ds-list--stacked > .ds-list__item > :not(.ds-list__media, .ds-list__icon, .ds-press-ripple) {
    grid-column: -2 / -1;
  }

  /* The space goes on the parts: the empty rows the media spans take none. */
  .ds-list--stacked > .ds-list__item > :is(.ds-list__media, .ds-list__icon) {
    grid-row: 1 / span 6;
    align-self: start;
  }

  .ds-list--stacked > .ds-list__item > :not(.ds-list__media, .ds-list__icon, .ds-list__text, .ds-press-ripple) {
    margin-top: var(--ds-space-2);
  }

  .ds-list--stacked > .ds-list__item > .ds-list__chevron {
    justify-self: end;
  }

  /* The current row (aria-current on the row or on its action): the tint,
     with a word or the label weight in the row (never the colour alone). */
  .ds-list__item:is([aria-current]:not([aria-current="false"]), :has(.ds-list__action[aria-current]:not([aria-current="false"]))) {
    background-color: var(--ds-list-current-bg, var(--ds-accent));
  }

  /* While rows glide (DS.motion.flip marks the list data-ds-glide with
     --ds-flip-backdrop), every row stands on an opaque backing, so a row
     that crosses another never shows its text through. */
  .ds-list[data-ds-glide] > .ds-list__item {
    background-image: linear-gradient(var(--ds-flip-backdrop, var(--ds-surface)), var(--ds-flip-backdrop, var(--ds-surface)));
  }

  .ds-list[data-ds-glide] > .ds-list__item:is([aria-current]:not([aria-current="false"]), :has(.ds-list__action[aria-current]:not([aria-current="false"]))) {
    background-image:
      linear-gradient(var(--ds-list-current-bg, var(--ds-accent)), var(--ds-list-current-bg, var(--ds-accent))),
      linear-gradient(var(--ds-flip-backdrop, var(--ds-surface)), var(--ds-flip-backdrop, var(--ds-surface)));
  }

  /*
   * Interactive rows: the row's action stretches over the row (::after
   * against the positioned row); its other links and controls stay above
   * it (zero specificity: a control's own position wins). The state layer
   * sits between the row's colour and its content (the row is isolated).
   */
  .ds-list--interactive > .ds-list__item {
    position: relative;
    isolation: isolate;
    cursor: pointer;
    -webkit-tap-highlight-color: transparent;
    /* An inset ring: it rests on the row's edge and snaps inward. */
    outline-offset: 0;
    transition:
      background-color var(--ds-dur-fast) var(--ds-ease-in-out),
      outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-list--interactive > .ds-list__item::before {
    content: '';
    position: absolute;
    inset: 0;
    z-index: -1;
    border-radius: inherit;
    background: currentColor;
    opacity: 0;
    pointer-events: none;
    transition: opacity var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  @media (hover: hover) {
    .ds-list--interactive > .ds-list__item:hover::before {
      opacity: var(--ds-state-hover-lg);
    }
  }

  /* Keyboard focus on the action: the layer and the ring at once. */
  .ds-list--interactive > .ds-list__item:has(.ds-list__action:focus-visible)::before {
    opacity: var(--ds-state-focus);
    transition-duration: 0s;
  }

  /* Press-in in --ds-dur-micro (.ds-pressed: js/ripple.js holds it); not
     while another control in the row is pressed (it has its own). */
  .ds-list--interactive > .ds-list__item:active:not(:where(:has(:is(a[href], button, input, select, textarea, label, summary):not(.ds-list__action):active)))::before,
  .ds-list--interactive > .ds-list__item.ds-pressed::before {
    opacity: var(--ds-state-pressed);
    transition-duration: var(--ds-dur-micro);
  }

  .ds-list--interactive > .ds-list__item:has(.ds-list__action:focus-visible) {
    outline: var(--ds-focus-outline);
    outline-offset: calc(-1 * var(--ds-focus-width));
  }

  /* A blocked row (its action disabled or aria-disabled) shows neither
     hover nor press; an aria-disabled action keeps its focus layer. */
  .ds-list--interactive > .ds-list__item:has(.ds-list__action:is(:disabled, [aria-disabled="true"])) {
    cursor: not-allowed;
  }

  @media (hover: hover) {
    .ds-list--interactive > .ds-list__item:has(.ds-list__action:is(:disabled, [aria-disabled="true"])):hover::before {
      opacity: 0;
    }
  }

  .ds-list--interactive > .ds-list__item:has(.ds-list__action:is(:disabled, [aria-disabled="true"])):is(:active, .ds-pressed)::before {
    opacity: 0;
  }

  .ds-list--interactive > .ds-list__item:has(.ds-list__action[aria-disabled="true"]:focus-visible)::before {
    opacity: var(--ds-state-focus);
  }

  /* The action reads as the row's title: the whole row is the affordance.
     A <button> action loses its own look. */
  .ds-list--interactive .ds-list__action {
    padding: 0;
    border: 0;
    background: none;
    color: inherit;
    font: inherit;
    text-align: start;
    text-decoration: none;
    cursor: inherit;
  }

  .ds-list--interactive .ds-list__action::after {
    content: '';
    position: absolute;
    inset: 0;
  }

  .ds-list--interactive .ds-list__action:focus-visible {
    outline: none;
  }

  :where(.ds-list--interactive > .ds-list__item) :where(a[href], button, input, select, textarea, label, summary, [tabindex]):where(:not(.ds-list__action)) {
    position: relative;
    z-index: var(--ds-z-raised);
  }

  /*
   * Key-value rows that open something: the row is a link or a button
   * that hangs --ds-space-2 into the space at its sides, so its text stays
   * in line with the static rows; the first and last rows hang their outer
   * padding too. A div.ds-kv-list__row is a static row among them.
   */
  .ds-kv-list--interactive li {
    padding: 0;
  }

  .ds-kv-list__row {
    display: flex;
    flex: 1 1 auto;
    align-items: baseline;
    justify-content: space-between;
    gap: var(--ds-space-3);
    min-width: 0;
    margin-inline: calc(-1 * var(--ds-space-2));
    padding: var(--_pad) var(--ds-space-2);
    border-radius: calc(var(--ds-radius-sm) * var(--ds-shape, 1));
  }

  .ds-kv-list--interactive li:first-child > .ds-kv-list__row {
    margin-top: calc(-1 * var(--_pad));
  }

  .ds-kv-list--interactive li:last-child > .ds-kv-list__row {
    margin-bottom: calc(-1 * var(--_pad));
  }

  :is(a, button).ds-kv-list__row {
    /* A row that opens reaches the touch target through its padding, so its
       text stays centred on one line (1lh: the row's own line). */
    --_pad: max(0px, calc(var(--ds-kv-list-padding, var(--ds-space-3)) + var(--ds-size-step, 0) * 4px + var(--ds-density, 0) * 2px), calc((var(--ds-target-min, 0px) - 1lh) / 2));
    position: relative;
    isolation: isolate;
    border: 0;
    background: none;
    color: inherit;
    font: inherit;
    text-align: start;
    text-decoration: none;
    cursor: pointer;
    -webkit-tap-highlight-color: transparent;
    /* The ring rests (invisible) one width further out and snaps in. */
    outline-offset: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    transition:
      color var(--ds-dur-fast) var(--ds-ease-in-out),
      opacity var(--ds-dur-fast) var(--ds-ease-in-out),
      outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  :is(a, button).ds-kv-list__row::before {
    content: '';
    position: absolute;
    inset: 0;
    z-index: -1;
    border-radius: inherit;
    background: currentColor;
    opacity: 0;
    pointer-events: none;
    transition: opacity var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  @media (hover: hover) {
    :is(a, button).ds-kv-list__row:hover::before {
      opacity: var(--ds-state-hover-lg);
    }
  }

  :is(a, button).ds-kv-list__row:focus-visible::before {
    opacity: var(--ds-state-focus);
    transition-duration: 0s;
  }

  /* Press-in in --ds-dur-micro (.ds-pressed: js/ripple.js holds it). */
  :is(a, button).ds-kv-list__row:active::before,
  :is(a, button).ds-kv-list__row.ds-pressed::before {
    opacity: var(--ds-state-pressed);
    transition-duration: var(--ds-dur-micro);
  }

  :is(a, button).ds-kv-list__row:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: var(--ds-focus-offset);
  }

  /* The disabled model: the neutral ink, no hover or press layer; an
     aria-disabled row keeps its focus layer. */
  :is(a, button).ds-kv-list__row:is(:disabled, [aria-disabled="true"]) {
    color: var(--ds-disabled-ink);
    opacity: var(--ds-disabled-opacity);
    cursor: not-allowed;
  }

  :is(a, button).ds-kv-list__row:is(:disabled, [aria-disabled="true"]) > span {
    color: inherit;
  }

  @media (hover: hover) {
    :is(a, button).ds-kv-list__row:is(:disabled, [aria-disabled="true"]):hover::before {
      opacity: 0;
    }
  }

  :is(a, button).ds-kv-list__row:is(:disabled, [aria-disabled="true"]):is(:active, .ds-pressed)::before {
    opacity: 0;
  }

  :is(a, button).ds-kv-list__row[aria-disabled="true"]:focus-visible::before {
    opacity: var(--ds-state-focus);
  }

  /* An icon before a value, always with a .ds-sr word (never the colour
     alone). */
  .ds-kv-list__icon {
    display: inline-block;
    flex: none;
    margin-inline-end: var(--ds-space-1);
    vertical-align: -3px;
    color: var(--ds-text-2);
  }

  /* On the icon itself: an inherited tone would colour every value. */
  .ds-kv-list__icon:is(.ds-tone-neutral, .ds-tone-primary, .ds-tone-info, .ds-tone-success, .ds-tone-warning, .ds-tone-error) {
    color: var(--ds-tone);
  }

  /* Rows with a meter on a line of their own: the label stays on one line
     (the full text shows as a tooltip when it is cut), the figure at the
     end. */
  .ds-kv-list--bars:not(.ds-kv-list--interactive) li,
  .ds-kv-list--bars .ds-kv-list__row {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: baseline;
    gap: var(--ds-space-2) var(--ds-space-3);
  }

  .ds-kv-list--bars :is(li, .ds-kv-list__row) > span:first-child {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .ds-kv-list--bars .ds-meter {
    grid-column: 1 / -1;
    align-self: center;
  }

  /* ── Facts in rows: the label beside its value ── */

  .ds-facts--rows {
    display: block;
  }

  .ds-facts--rows > div {
    display: grid;
    grid-template-columns: var(--ds-facts-label-width, 36%) minmax(0, 1fr);
    gap: var(--ds-space-4);
    padding-block: max(0px, calc(var(--ds-kv-list-padding, var(--ds-space-3)) + var(--ds-size-step, 0) * 4px + var(--ds-density, 0) * 2px));
    border-top: 1px solid var(--ds-line);
  }

  .ds-facts--rows > div:first-child {
    padding-top: 0;
    border-top: 0;
  }

  .ds-facts--rows > div:last-child {
    padding-bottom: 0;
  }

  .ds-facts--rows dt {
    font: var(--ds-font-body);
  }

  .ds-facts--rows dd {
    margin: 0;
  }

  /* Narrow content: the label goes above its value. */
  @container ds-content (max-width: 520px) {
    .ds-facts--rows > div {
      grid-template-columns: minmax(0, 1fr);
      gap: var(--ds-space-1);
    }
  }

  @media (max-width: 600px) {
    .ds-facts--rows > div {
      grid-template-columns: minmax(0, 1fr);
      gap: var(--ds-space-1);
    }
  }

  /* A value another system sets: the lock and its reason (aria-label and
     data-tip), never a disabled field. Not an action. */
  .ds-lock {
    display: inline-flex;
    margin-inline-start: var(--ds-space-1);
    vertical-align: -3px;
    color: var(--ds-text-2);
  }

  /* ── Selectable, reorderable and scrolling rows (DS.list, 3.0) ── */

  /* A checkbox (or a radio) at the row's start; the row tints while it is
     checked, and the box says so (never the colour alone). */
  .ds-list__check {
    flex: none;
    margin: 0;
  }

  .ds-list__item:has(> .ds-list__check:checked) {
    background-color: var(--ds-list-selected-bg, var(--ds-accent));
  }

  .ds-list[data-ds-glide] > .ds-list__item:has(> .ds-list__check:checked) {
    background-image:
      linear-gradient(var(--ds-list-selected-bg, var(--ds-accent)), var(--ds-list-selected-bg, var(--ds-accent))),
      linear-gradient(var(--ds-flip-backdrop, var(--ds-surface)), var(--ds-flip-backdrop, var(--ds-surface)));
  }

  /* A row of a selectable list without an action of its own: a press
     anywhere on it toggles its box, so it takes the state layer, the
     press and the ripple (a row whose box is disabled shows none). */
  .ds-list[data-ds-list-select] > .ds-list__item:not(:has(.ds-list__action)) {
    position: relative;
    isolation: isolate;
    -webkit-tap-highlight-color: transparent;
  }

  .ds-list[data-ds-list-select] > .ds-list__item:not(:has(.ds-list__action)):not(:has(> .ds-list__check:disabled)) {
    cursor: pointer;
  }

  .ds-list[data-ds-list-select] > .ds-list__item:not(:has(.ds-list__action))::before {
    content: '';
    position: absolute;
    inset: 0;
    z-index: -1;
    border-radius: inherit;
    background: currentColor;
    opacity: 0;
    pointer-events: none;
    transition: opacity var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  @media (hover: hover) {
    .ds-list[data-ds-list-select] > .ds-list__item:not(:has(.ds-list__action)):not(:has(> .ds-list__check:disabled)):hover::before {
      opacity: var(--ds-state-hover-lg);
    }
  }

  /* Press-in in --ds-dur-micro (.ds-pressed: js/ripple.js holds it); not
     while the box itself is pressed (it has its own halo). */
  .ds-list[data-ds-list-select] > .ds-list__item:not(:has(.ds-list__action)):not(:has(> .ds-list__check:disabled)):active:not(:has(> .ds-list__check:active))::before,
  .ds-list[data-ds-list-select] > .ds-list__item:not(:has(.ds-list__action)):not(:has(> .ds-list__check:disabled)).ds-pressed::before {
    opacity: var(--ds-state-pressed);
    transition-duration: var(--ds-dur-micro);
  }

  /* With DS.ripple.attach() the ripple brings the press; the flat layer
     stays at its hover value. */
  :where(.ds-ripples) .ds-list[data-ds-list-select] > .ds-list__item:not(:has(.ds-list__action)):not(:has(> .ds-list__check:disabled)):where(:not([data-ds-ripple="off"], [data-ds-ripple="off"] *)):is(:active, .ds-pressed)::before {
    opacity: 0;
  }

  @media (hover: hover) {
    :where(.ds-ripples) .ds-list[data-ds-list-select] > .ds-list__item:not(:has(.ds-list__action)):not(:has(> .ds-list__check:disabled)):where(:not([data-ds-ripple="off"], [data-ds-ripple="off"] *)):is(:active, .ds-pressed)::before {
      opacity: var(--ds-state-hover-lg);
    }
  }

  .ds-list[data-ds-list-select] > .ds-list__item:not(:has(.ds-list__action)):has(> .ds-list__check:disabled) {
    cursor: not-allowed;
  }

  /* The drag handle DS.list writes at the start of each row. */
  .ds-list__grip {
    flex: none;
    margin-inline-start: calc(-1 * var(--ds-space-2));
    touch-action: none;
    color: var(--ds-text-2);
  }

  /* While it is dragged a row keeps an opaque fill and its corners. */
  .ds-list__item[data-ds-dragging] {
    border-radius: var(--_inner);
    background-color: var(--ds-surface);
  }

  /* A list that scrolls by itself (a long list, a virtual one): its rows
     scroll inside its border, the sticky headings stop at its top. */
  .ds-list--scroll {
    position: relative;
    max-block-size: var(--ds-list-max-height, 24rem);
    overflow: auto;
    overscroll-behavior: contain;
  }

  /* A row that holds the focus itself (DS.list with a virtual window). */
  .ds-list__item:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: calc(-1 * var(--ds-focus-width));
  }

  /* ── Facts, 3.0: stacked, a grid with spans, bordered, copy per value ── */

  /* Stacked: one fact under the other, the label above its value. */
  .ds-facts--stacked {
    grid-template-columns: minmax(0, 1fr);
  }

  /* A grid whose facts may span: the columns of .ds-facts, and the grid
     itself the container its facts measure, so a wide fact takes one
     column when only one fits. */
  .ds-facts--grid {
    container: ds-facts / inline-size;
  }

  .ds-facts--grid > .ds-facts__wide {
    grid-column: span 2;
  }

  .ds-facts--grid > .ds-facts__full {
    grid-column: 1 / -1;
  }

  /* Under two columns of 220px and the gap, a wide fact takes the one. */
  @container ds-facts (max-width: 471px) {
    .ds-facts--grid > .ds-facts__wide {
      grid-column: auto;
    }
  }

  /* Bordered: each fact in a cell, hairlines between them and a frame
     around (the cells hang 1px under the frame, so no edge doubles and an
     empty end of the last line stays blank). */
  .ds-facts--bordered {
    gap: 0;
    overflow: clip;
    border: 1px solid var(--ds-line);
    border-radius: calc(var(--ds-facts-radius, var(--ds-radius-card)) * var(--ds-shape, 1));
    background: var(--ds-surface);
  }

  .ds-facts--bordered > div {
    --_pad: max(0px, calc(var(--ds-kv-list-padding, var(--ds-space-3)) + var(--ds-size-step, 0) * 4px + var(--ds-density, 0) * 2px));
    margin-block: 0 -1px;
    margin-inline: 0 -1px;
    padding: var(--_pad) var(--ds-space-4);
    border-inline-end: 1px solid var(--ds-line);
    border-block-end: 1px solid var(--ds-line);
  }

  .ds-facts--bordered.ds-facts--rows > div,
  .ds-facts--bordered.ds-facts--rows > div:first-child,
  .ds-facts--bordered.ds-facts--rows > div:last-child {
    padding: var(--_pad) var(--ds-space-4);
    border-block-start: 0;
  }

  /* Copy per value: the button DS.list writes after each value. It shows
     on the fact under the pointer or in use, and always without hover. */
  .ds-facts__copy {
    margin-block: calc(-1 * var(--ds-space-1));
    margin-inline-start: var(--ds-space-1);
    vertical-align: middle;
  }

  .ds-facts__copy > svg + svg,
  .ds-facts__copy[data-state="copied"] > svg:first-child {
    display: none;
  }

  .ds-facts__copy[data-state="copied"] > svg + svg {
    display: block;
  }

  @media (hover: hover) {
    .ds-facts dd > .ds-facts__copy {
      opacity: 0;
      transition: opacity var(--ds-dur-fast) var(--ds-ease-in-out);
    }

    .ds-facts > div:is(:hover, :focus-within) > dd > .ds-facts__copy,
    .ds-facts dd > .ds-facts__copy[data-state="copied"] {
      opacity: 1;
    }
  }

  @media (forced-colors: active) {
    .ds-list__item:is([aria-current]:not([aria-current="false"]), :has(.ds-list__action[aria-current]:not([aria-current="false"]))) {
      forced-color-adjust: none;
      background: SelectedItem;
      color: SelectedItemText;
    }

    .ds-list__item:is([aria-current]:not([aria-current="false"]), :has(.ds-list__action[aria-current]:not([aria-current="false"]))) :is(.ds-list__title, .ds-list__description, .ds-list__meta, .ds-list__aside, .ds-list__icon, .ds-list__chevron) {
      color: inherit;
    }

    /* forced-color-adjust inherits: the row's other controls, chips and media
       take the system colours again, on Canvas, so they stay legible on
       the selection fill (a status chip or a menu button at the row's end, an
       avatar's initials, whose border is their edge again; a chip: chip.css,
       which comes later). */
    .ds-list__item:is([aria-current]:not([aria-current="false"]), :has(.ds-list__action[aria-current]:not([aria-current="false"]))) :is(a[href], button, input, select, textarea, label, .ds-status, .ds-tag, .ds-list__media):not(.ds-list__action) {
      forced-color-adjust: auto;
    }

    .ds-list__item:is([aria-current]:not([aria-current="false"]), :has(.ds-list__action[aria-current]:not([aria-current="false"]))) :is(a[href], button, select, textarea, input:not([type="checkbox"], [type="radio"]), .ds-list__media):not(.ds-list__action) {
      background-color: Canvas;
    }

    /* A focused current row: a ring of the text colour inside the fill. */
    .ds-list--interactive > .ds-list__item:has(.ds-list__action[aria-current]:not([aria-current="false"]):focus-visible) {
      outline-color: CanvasText;
    }

    /* Blocked key-value rows: one system colour (D8). */
    :is(a, button).ds-kv-list__row:is(:disabled, [aria-disabled="true"]) {
      color: GrayText;
    }
  }
}

/* ── components/card/card.css ── */
/*
 * Card: a block on a surface, outlined with the passive hairline at
 * --ds-card-radius (--ds-radius-card) times --ds-shape. Hierarchy comes
 * from type, hairlines and tonal tiles, never shadows.
 *
 *   <section class="ds-card">
 *     <div class="ds-card__row"> <h2 class="ds-card__title"> [button | switch | status chip | badge | tag | chip]
 *     <p class="ds-muted"> ...
 *     <h3 class="ds-card__subtitle"> ...
 *     <div class="ds-card__section"> ...
 *     <nav class="ds-card__links"> <a class="ds-btn ds-btn--text ds-card__link"> ...
 *
 * Variants (the look):
 *   .ds-card               outlined: the hairline on --ds-surface
 *   .ds-card--outlined     the same, named explicitly
 *   .ds-card--filled       a quieter block inside a card or form
 *   .ds-card--elevated     a card that floats a little: --ds-card-shadow
 *                          (--ds-elev-1) instead of the hairline
 *   .ds-card--horizontal   media beside the body, wrapping under each other
 *                          when the card is too narrow for both:
 *     <section class="ds-card ds-card--horizontal"> <img class="ds-card__media" src="..." alt="..."> <div class="ds-card__body"> ... </div> </section>
 *     .ds-card__media takes --ds-card-media-size (160px) in the row and
 *     the whole line once wrapped; .ds-card__body keeps the card's rhythm
 *     (the same rules as the card's own children; a <span> body, in a
 *     <button> card, stacks its spans) and asks for at least
 *     --ds-card-body-min (240px).
 *
 * Options (src/core/options.css, docs/options.md), on the card or any
 * ancestor; each is computed here, in the card's own rule:
 *   density   .ds-density-*: 2px off the padding and the rhythm per step
 *             (--ds-card-pad follows, so what bleeds to the card's edges
 *             follows too); read on the card, so a density class on a child
 *             (a dense table) leaves the gap above it alone; type stays
 *   shape     .ds-shape-*: multiplies the rest and the pressed radius, the
 *             media and the mark
 *   touch     .ds-touch: an interactive card is at least --ds-touch-target
 *             high
 *   size      not read by the card: it has no height of its own; a size
 *             class on a card reaches the controls inside it
 *   tone      not read: a card shows no meaning of its own (put a status
 *             chip or an alert in it)
 *
 * Clickable: .ds-card--interactive, the whole card opens something (the
 * name .ds-list--interactive and .ds-table--interactive share):
 *     <a class="ds-card ds-card--interactive" href="/devices/42"> ... </a>
 *     <button class="ds-card ds-card--interactive" type="button"> (spans) </button>
 *     <div class="ds-card ds-card--interactive"> ... <a class="ds-card__action" href="/devices/42">Title</a> ... </div>
 *     The <a> and <button> forms lay their content out as a column from
 *     the top (a button would centre it in a taller grid cell).
 *     The <div> form keeps other controls usable: .ds-card__action's
 *     ::after stretches over the card, the card's other links and controls
 *     stay above it.
 *
 * An interactive card has a state layer in currentColor (hover
 * --ds-state-hover-lg, press --ds-state-pressed in --ds-dur-micro, keyboard
 * focus --ds-state-focus with a ring that is solid from the first frame
 * and snaps from offset + width to the offset; on the <div> form the ring
 * sits on the card through :has(.ds-card__action:focus-visible), so a
 * ripple's clip never cuts it), the press morph (the radius goes to
 * --ds-card-radius-pressed, --ds-radius-card-pressed, times the shape, in
 * --ds-dur-micro and springs back over --ds-dur-medium) and the ripple
 * (js/ripple.js). A disabled or aria-disabled card shows it: the one
 * disabled model (--ds-disabled-ink on its text, --ds-disabled-opacity,
 * cursor not-allowed), no hover or press layer, no hover shadow and no morph
 * (an aria-disabled one keeps its focus layer).
 * Nothing moves on hover: no lift, no scale; a theme may give it a shadow
 * through --ds-card-hover-shadow (default none; an --elevated card keeps its
 * own; for example var(--ds-elev-hover)), in over --ds-dur-medium, out over
 * --ds-dur-base. In forced colours every interactive card keeps a visible
 * edge, a blocked one GrayText, selected or not.
 *
 * Selectable: a choice among a few cards is a toggle: aria-pressed,
 * aria-checked or aria-selected on the card (a <button>), or on the
 * .ds-card__action of the <div> form (a <button class="ds-card__action">
 * loses its own look). Selected it takes --ds-card-selected-bg (--ds-accent)
 * with --ds-on-accent ink and a static inset ring (a border of
 * --ds-focus-width in --ds-selected-ring, --ds-primary, on the card's own
 * ::after), so the focus ring stays free and both read at once. Colours on
 * --ds-dur-fast, the ring at once. Never the tint alone: add a check or the
 * label weight, or .ds-card--selectable, which brings the check:
 *     <button class="ds-card ds-card--interactive ds-card--selectable" type="button" aria-pressed="true">
 *       ... <span class="ds-card__check" aria-hidden="true">(check 16)</span>
 *     </button>
 *     .ds-card__check, the card's last child, is an empty round mark in the
 *     corner at rest and a filled check when selected
 *     (--ds-card-check-size, --ds-space-5); the card keeps its content clear
 *     of it. Forced colours: Highlight / HighlightText.
 *
 * Hooks (on .ds-theme or an element): --ds-card-padding (--ds-space-6),
 * --ds-card-padding-sm (600px and below, --ds-space-4),
 * --ds-card-padding-filled (--ds-space-5), --ds-card-radius,
 * --ds-card-radius-pressed, --ds-card-bg (--ds-surface), --ds-card-border
 * (--ds-line), --ds-card-filled-bg (--ds-surface-low),
 * --ds-card-title-line (the title's line height, 24px, which a button,
 * switch or chip in the header row overhangs; a status chip, badge or tag
 * sits on it), --ds-card-hover-shadow (an interactive card's shadow on
 * hover, default none), --ds-card-shadow (--elevated, --ds-elev-1),
 * --ds-card-selected-bg, --ds-selected-ring, --ds-card-check-size,
 * --ds-card-media-size, --ds-card-body-min. --ds-card-pad is the resulting
 * padding of each card, which tables read to bleed to its edges: read it,
 * never set it. --_radius and --_card-gap are private.
 */

@layer ds.components.card {
  .ds-card {
    --ds-card-pad: calc(var(--ds-card-padding, var(--ds-space-6)) + var(--ds-density, 0) * 2px);
    --_radius: calc(var(--ds-card-radius, var(--ds-radius-card)) * var(--ds-shape, 1));
    /* The rhythm, computed here and read by the children, so a density class
       on a child (a dense table in a comfortable card) changes the child and
       not the gap above it. The name is the card's own: a child may have a
       --_gap. A card inside a card computes its own and reads that above
       itself too: it is the same value unless it has a density class. */
    --_card-gap: calc(var(--ds-space-4) + var(--ds-density, 0) * 2px);
    min-width: 0;
    padding: var(--ds-card-pad);
    border: 1px solid var(--ds-card-border, var(--ds-line));
    border-radius: var(--_radius);
    background: var(--ds-card-bg, var(--ds-surface));
    /* Its own ink on its own surface: without .ds-base (a widget in a host
       page) text would inherit the host's colour. */
    color: var(--ds-text);
  }

  /* The rhythm below decides all spacing; the browser margins of paragraphs
     go in src/core/global.css (zero weight, in the first sublayer, so every
     component's own margin still wins). */

  .ds-card > * + *,
  .ds-card__body > * + * {
    margin-top: var(--_card-gap);
  }

  /* An empty live region (filled later) takes no room. */
  .ds-card > p:empty,
  .ds-card__body > p:empty {
    display: none;
  }

  @media (max-width: 600px) {
    .ds-card {
      --ds-card-pad: calc(var(--ds-card-padding-sm, var(--ds-space-4)) + var(--ds-density, 0) * 2px);
    }
  }

  /* The default look, named explicitly: what a variant list offers. */
  .ds-card--outlined {
    border-color: var(--ds-card-border, var(--ds-line));
    background: var(--ds-card-bg, var(--ds-surface));
  }

  .ds-card--filled {
    --ds-card-pad: calc(var(--ds-card-padding-filled, var(--ds-space-5)) + var(--ds-density, 0) * 2px);
    border-color: transparent;
    background: var(--ds-card-filled-bg, var(--ds-surface-low));
  }

  .ds-card--elevated {
    border-color: transparent;
    box-shadow: var(--ds-card-shadow, var(--ds-elev-1));
  }

  /*
   * Interactive card (D26): a whole card that opens something. The
   * element's own link or button look is reset; the state layer sits
   * between the card's fill and its content (the card is isolated).
   */
  .ds-card--interactive {
    position: relative;
    isolation: isolate;
    min-height: var(--ds-target-min, 0px);
    cursor: pointer;
    -webkit-tap-highlight-color: transparent;
    /* The ring rests (invisible) one width further out and snaps in. */
    outline-offset: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    transition:
      background-color var(--ds-dur-fast) var(--ds-ease-in-out),
      border-color var(--ds-dur-fast) var(--ds-ease-in-out),
      color var(--ds-dur-fast) var(--ds-ease-in-out),
      opacity var(--ds-dur-fast) var(--ds-ease-in-out),
      border-radius var(--ds-dur-medium) var(--ds-ease-spatial),
      box-shadow var(--ds-dur-base) var(--ds-ease-in-out),
      outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  /* A column from the top: a button centres its content in a taller box
     (next to a taller card in a grid row), and its spans stack with the
     card's rhythm like the blocks of the other forms. */
  :is(a, button).ds-card--interactive {
    display: flex;
    flex-direction: column;
    justify-content: flex-start;
    align-items: stretch;
    width: 100%;
    color: var(--ds-text);
    font: inherit;
    text-align: start;
    text-decoration: none;
  }

  .ds-card--interactive::before {
    content: '';
    position: absolute;
    inset: 0;
    z-index: -1;
    border-radius: inherit;
    background: currentColor;
    opacity: 0;
    pointer-events: none;
    transition: opacity var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  @media (hover: hover) {
    .ds-card--interactive:not(:disabled, [aria-disabled="true"]):hover {
      box-shadow: var(--ds-card-hover-shadow, none);
      transition:
        background-color var(--ds-dur-fast) var(--ds-ease-in-out),
        border-color var(--ds-dur-fast) var(--ds-ease-in-out),
        color var(--ds-dur-fast) var(--ds-ease-in-out),
        opacity var(--ds-dur-fast) var(--ds-ease-in-out),
        border-radius var(--ds-dur-medium) var(--ds-ease-spatial),
        box-shadow var(--ds-dur-medium) var(--ds-ease-in-out),
        outline-offset var(--ds-dur-fast) var(--ds-ease-out);
    }

    /* Without a hook an elevated card keeps its own shadow under the pointer. */
    .ds-card--elevated.ds-card--interactive:not(:disabled, [aria-disabled="true"]):hover {
      box-shadow: var(--ds-card-hover-shadow, var(--ds-card-shadow, var(--ds-elev-1)));
    }

    .ds-card--interactive:hover::before {
      opacity: var(--ds-state-hover-lg);
    }
  }

  /* Keyboard focus: the layer appears with the ring and fades out on blur. */
  .ds-card--interactive:focus-visible::before,
  .ds-card--interactive:has(.ds-card__action:focus-visible)::before {
    opacity: var(--ds-state-focus);
    transition-duration: 0s;
  }

  /* Press-in in --ds-dur-micro (.ds-pressed: js/ripple.js holds it); not
     while another control in a <div> card is pressed (it has its own). */
  .ds-card--interactive:active:not(:where(:has(:is(a[href], button, input, select, textarea, label, summary):not(.ds-card__action):active)))::before,
  .ds-card--interactive.ds-pressed::before {
    opacity: var(--ds-state-pressed);
    transition-duration: var(--ds-dur-micro);
  }

  /* A blocked card (disabled, aria-disabled) shows neither hover nor press,
     like its morph below; an aria-disabled card keeps its focus layer. */
  @media (hover: hover) {
    .ds-card--interactive:is(:disabled, [aria-disabled="true"]):hover::before {
      opacity: 0;
    }
  }

  .ds-card--interactive:is(:disabled, [aria-disabled="true"]):is(:active, .ds-pressed)::before {
    opacity: 0;
  }

  .ds-card--interactive[aria-disabled="true"]:is(:focus-visible, :has(.ds-card__action:focus-visible))::before {
    opacity: var(--ds-state-focus);
  }

  /* The press morph: squarer while pressed (never rounder than at rest),
     springing back on release. */
  .ds-card--interactive:active:not(:disabled, [aria-disabled="true"]):not(:where(:has(:is(a[href], button, input, select, textarea, label, summary):not(.ds-card__action):active))),
  .ds-card--interactive.ds-pressed:not(:disabled, [aria-disabled="true"]) {
    border-radius: min(calc(var(--ds-card-radius-pressed, var(--ds-radius-card-pressed)) * var(--ds-shape, 1)), var(--_radius));
    transition:
      background-color var(--ds-dur-fast) var(--ds-ease-in-out),
      border-color var(--ds-dur-fast) var(--ds-ease-in-out),
      color var(--ds-dur-fast) var(--ds-ease-in-out),
      opacity var(--ds-dur-fast) var(--ds-ease-in-out),
      border-radius var(--ds-dur-micro) var(--ds-ease-out),
      box-shadow var(--ds-dur-base) var(--ds-ease-in-out),
      outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  /* The <div> form takes its ring on the card itself, not on the action's
     stretched ::after: a ripple clips the card (overflow: clip) and would
     cut a descendant's ring outside the padding box for the whole press. */
  .ds-card--interactive:focus-visible,
  .ds-card--interactive:has(.ds-card__action:focus-visible) {
    outline: var(--ds-focus-outline);
    outline-offset: var(--ds-focus-offset);
  }

  /* The <div> form: the action's ::after covers the card; the card's other
     links and controls stay above it (zero specificity: a control's own
     position wins). The action reads as the card's text: the whole card is
     the affordance. */
  .ds-card__action {
    color: inherit;
    text-decoration: none;
  }

  /* The button form of the action (a choice card): no look of its own. */
  button.ds-card__action {
    margin: 0;
    padding: 0;
    border: 0;
    background: none;
    font: inherit;
    text-align: start;
    cursor: inherit;
  }

  .ds-card__action::after {
    content: '';
    position: absolute;
    inset: 0;
    border-radius: var(--_radius);
  }

  .ds-card--interactive .ds-card__action:focus-visible {
    outline: none;
  }

  :where(.ds-card--interactive) :where(a[href], button, input, select, textarea, label, summary, [tabindex]):where(:not(.ds-card__action)) {
    position: relative;
    z-index: var(--ds-z-raised);
  }

  /* Selected (a choice among a few cards): the tint and a static inset
     ring on the card's own ::after (the state layer is ::before, the
     stretched link of the <div> form is the action's ::after), drawn over
     the hairline, so the focus ring stays free; the ring shows at once. */
  /* The text roles turn to the ink on the card itself, so its title,
     .ds-muted and .ds-meta follow by inheritance: a rule that reached them
     through :has() (card:has(selected action) .ds-muted) put every text
     change on the page through that check (perf.spec, style recalc). */
  .ds-card--interactive:is([aria-pressed="true"], [aria-checked="true"], [aria-selected="true"]),
  .ds-card--interactive:has(.ds-card__action:is([aria-pressed="true"], [aria-checked="true"], [aria-selected="true"])) {
    --ds-text: var(--ds-on-accent);
    --ds-text-2: var(--ds-on-accent);
    border-color: transparent;
    background: var(--ds-card-selected-bg, var(--ds-accent));
    color: var(--ds-on-accent);
  }

  .ds-card--interactive:is([aria-pressed="true"], [aria-checked="true"], [aria-selected="true"]) :is(.ds-card__title, .ds-card__subtitle, .ds-muted, .ds-meta) {
    color: var(--ds-on-accent);
  }

  .ds-card--interactive:is([aria-pressed="true"], [aria-checked="true"], [aria-selected="true"])::after,
  .ds-card--interactive:has(.ds-card__action:is([aria-pressed="true"], [aria-checked="true"], [aria-selected="true"]))::after {
    content: '';
    position: absolute;
    inset: -1px;
    border: var(--ds-focus-width) solid var(--ds-selected-ring, var(--ds-primary));
    border-radius: inherit;
    pointer-events: none;
  }

  /*
   * Selectable: the check says what the tint says, so a selected card is
   * never told by colour alone. The mark sits in the corner on the title's
   * line; the card keeps its content clear of it; the pointer goes through
   * to the card or its stretched action.
   */
  .ds-card--selectable {
    padding-inline-end: calc(var(--ds-card-pad) + var(--ds-card-check-size, var(--ds-space-5)) + var(--ds-space-2));
  }

  .ds-card__check {
    --_size: var(--ds-card-check-size, var(--ds-space-5));
    position: absolute;
    inset-block-start: calc(var(--ds-card-pad) + (var(--ds-card-title-line, 24px) - var(--_size)) / 2);
    inset-inline-end: var(--ds-card-pad);
    display: grid;
    place-items: center;
    width: var(--_size);
    height: var(--_size);
    border: var(--ds-focus-width) solid var(--ds-outline);
    border-radius: min(calc(min(var(--ds-radius-action), calc(var(--_size) / 2)) * var(--ds-shape, 1)), calc(var(--_size) / 2));
    background: transparent;
    color: transparent;
    pointer-events: none;
    transition:
      background-color var(--ds-dur-fast) var(--ds-ease-in-out),
      border-color var(--ds-dur-fast) var(--ds-ease-in-out),
      color var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  /* Out of flow: no rhythm margin (it would push the mark off its line). */
  .ds-card > .ds-card__check {
    margin: 0;
  }

  .ds-card--interactive:is([aria-pressed="true"], [aria-checked="true"], [aria-selected="true"]) > .ds-card__check,
  .ds-card--interactive:has(.ds-card__action:is([aria-pressed="true"], [aria-checked="true"], [aria-selected="true"])) > .ds-card__check {
    border-color: var(--ds-selected-ring, var(--ds-primary));
    background: var(--ds-selected-ring, var(--ds-primary));
    color: var(--ds-on-primary);
  }

  /*
   * Blocked (disabled, aria-disabled): the one disabled model, on top of
   * the look it has, selected or not. --ds-disabled-opacity dims the whole
   * card where a theme asks for that (1 by default). Its text reads the ink
   * directly: --ds-text cannot be set from a fallback that reads itself.
   */
  .ds-card--interactive:is(:disabled, [aria-disabled="true"]) {
    cursor: not-allowed;
    opacity: var(--ds-disabled-opacity, var(--ds-state-disabled));
    color: var(--ds-disabled-ink, var(--ds-text));
  }

  .ds-card--interactive:is(:disabled, [aria-disabled="true"]) :is(.ds-card__title, .ds-card__subtitle, .ds-muted, .ds-meta, .ds-card__action, .ds-card__media) {
    color: var(--ds-disabled-ink, var(--ds-text));
  }

  /* A link's own cursor would show over the card through its ::after. */
  .ds-card--interactive:is(:disabled, [aria-disabled="true"]) .ds-card__action {
    cursor: inherit;
  }

  .ds-card--interactive:is(:disabled, [aria-disabled="true"]) > .ds-card__check {
    border-color: var(--ds-disabled-ink, var(--ds-outline));
  }

  .ds-card--interactive:is(:disabled, [aria-disabled="true"]):is([aria-pressed="true"], [aria-checked="true"], [aria-selected="true"], :has(.ds-card__action:is([aria-pressed="true"], [aria-checked="true"], [aria-selected="true"]))) {
    color: var(--ds-disabled-ink, var(--ds-text));
  }

  /* The selected mark goes with it, a filled mark on the disabled fill: the
     state still reads. */
  .ds-card--interactive:is(:disabled, [aria-disabled="true"]):is([aria-pressed="true"], [aria-checked="true"], [aria-selected="true"], :has(.ds-card__action:is([aria-pressed="true"], [aria-checked="true"], [aria-selected="true"]))) > .ds-card__check {
    border-color: var(--ds-disabled-fill, var(--ds-outline));
    background: var(--ds-disabled-fill, var(--ds-outline));
    color: var(--ds-disabled-ink, var(--ds-on-primary));
  }

  /*
   * Horizontal: media beside the body. Both flex, so the body takes the
   * free room in a row and each takes a whole line once wrapped, with no
   * query: the card itself decides, wherever it stands. After the column of
   * the <a> and <button> forms, which it replaces.
   */
  .ds-card--horizontal,
  :is(a, button).ds-card--horizontal {
    display: flex;
    flex-flow: row wrap;
    align-items: stretch;
    gap: var(--_card-gap);
  }

  .ds-card--horizontal > * + * {
    margin-top: 0;
  }

  .ds-card__media {
    display: grid;
    place-items: center;
    min-width: 0;
    max-width: 100%;
    border-radius: calc(var(--ds-radius-sm) * var(--ds-shape, 1));
    background: var(--ds-surface-high);
    color: var(--ds-text-2);
    object-fit: cover;
    overflow: hidden;
  }

  .ds-card--horizontal > .ds-card__media {
    flex: 1 1 var(--ds-card-media-size, 160px);
  }

  /* A plain block under the card's own rhythm rules (the rhythm above, the
     subtitle's below): a gap would add to the subtitle's margins. */
  .ds-card__body {
    min-width: 0;
  }

  /* A <button> card holds phrasing content only: its spans stack in a column,
     as they do directly in the <a> and <button> forms. */
  span.ds-card__body {
    display: flex;
    flex-direction: column;
  }

  .ds-card--horizontal > .ds-card__body {
    flex: 999 1 var(--ds-card-body-min, 240px);
  }

  @media (forced-colors: active) {
    .ds-card--interactive.ds-card--filled,
    .ds-card--elevated {
      border-color: CanvasText;
    }

    .ds-card--interactive:is([aria-pressed="true"], [aria-checked="true"], [aria-selected="true"]),
    .ds-card--interactive:has(.ds-card__action:is([aria-pressed="true"], [aria-checked="true"], [aria-selected="true"])) {
      forced-color-adjust: none;
      border-color: Highlight;
      background: Highlight;
      color: HighlightText;
    }

    .ds-card--interactive:is([aria-pressed="true"], [aria-checked="true"], [aria-selected="true"]) :is(.ds-card__title, .ds-card__subtitle, .ds-muted, .ds-meta, .ds-card__action),
    .ds-card--interactive:has(.ds-card__action:is([aria-pressed="true"], [aria-checked="true"], [aria-selected="true"])) :is(.ds-card__title, .ds-card__subtitle, .ds-muted, .ds-meta, .ds-card__action) {
      color: HighlightText;
    }

    /* The media inherits forced-color-adjust: none from the card, so it takes
       the card's colours here and never keeps its author colours. */
    .ds-card--interactive:is([aria-pressed="true"], [aria-checked="true"], [aria-selected="true"]) .ds-card__media,
    .ds-card--interactive:has(.ds-card__action:is([aria-pressed="true"], [aria-checked="true"], [aria-selected="true"])) .ds-card__media {
      background: Highlight;
      color: HighlightText;
    }

    /* Other controls inside a <div> card keep the forced system colours. */
    .ds-card--interactive:has(.ds-card__action:is([aria-pressed="true"], [aria-checked="true"], [aria-selected="true"])) :is(a[href], button, input, select, textarea, label):not(.ds-card__action),
    .ds-card--interactive[aria-disabled="true"] :is(a[href], button, input, select, textarea, label):not(.ds-card__action) {
      forced-color-adjust: auto;
    }

    .ds-card--interactive:is([aria-pressed="true"], [aria-checked="true"], [aria-selected="true"])::after,
    .ds-card--interactive:has(.ds-card__action:is([aria-pressed="true"], [aria-checked="true"], [aria-selected="true"]))::after {
      border-color: Highlight;
    }

    .ds-card--interactive:is([aria-pressed="true"], [aria-checked="true"], [aria-selected="true"]):is(:focus-visible, :has(.ds-card__action:focus-visible)),
    .ds-card--interactive:has(.ds-card__action:is([aria-pressed="true"], [aria-checked="true"], [aria-selected="true"])):has(.ds-card__action:focus-visible) {
      outline-color: CanvasText;
    }

    /* Blocked is GrayText, selected or not: after the selected rules, and
       with the selected form's weight, so the :has() form loses too. */
    .ds-card--interactive:disabled,
    .ds-card--interactive[aria-disabled="true"],
    .ds-card--interactive:is(:disabled, [aria-disabled="true"]):is([aria-pressed="true"], [aria-checked="true"], [aria-selected="true"], :has(.ds-card__action:is([aria-pressed="true"], [aria-checked="true"], [aria-selected="true"]))) {
      forced-color-adjust: none;
      border-color: GrayText;
      background: Canvas;
      color: GrayText;
    }

    .ds-card--interactive:is(:disabled, [aria-disabled="true"]) :is(.ds-card__title, .ds-card__subtitle, .ds-muted, .ds-meta, .ds-card__action),
    .ds-card--interactive:is(:disabled, [aria-disabled="true"]):is([aria-pressed="true"], [aria-checked="true"], [aria-selected="true"], :has(.ds-card__action:is([aria-pressed="true"], [aria-checked="true"], [aria-selected="true"]))) :is(.ds-card__title, .ds-card__subtitle, .ds-muted, .ds-meta, .ds-card__action) {
      color: GrayText;
    }

    .ds-card--interactive:is(:disabled, [aria-disabled="true"]) .ds-card__media,
    .ds-card--interactive:is(:disabled, [aria-disabled="true"]):is([aria-pressed="true"], [aria-checked="true"], [aria-selected="true"], :has(.ds-card__action:is([aria-pressed="true"], [aria-checked="true"], [aria-selected="true"]))) .ds-card__media {
      background: Canvas;
      color: GrayText;
    }

    .ds-card--interactive:is(:disabled, [aria-disabled="true"]):is([aria-pressed="true"], [aria-checked="true"], [aria-selected="true"], :has(.ds-card__action:is([aria-pressed="true"], [aria-checked="true"], [aria-selected="true"])))::after {
      border-color: GrayText;
    }

    /* It stays focusable; unforced, its ring would keep the brand colour. */
    .ds-card--interactive[aria-disabled="true"]:is(:focus-visible, :has(.ds-card__action:focus-visible)) {
      outline-color: CanvasText;
    }

    /* The mark: an empty ring at rest (no forced ink on the hidden check),
       on the selected card the check in the fill's opposite. */
    .ds-card__check {
      forced-color-adjust: none;
      border-color: CanvasText;
      background: Canvas;
      color: Canvas;
    }

    .ds-card--interactive:is([aria-pressed="true"], [aria-checked="true"], [aria-selected="true"]) > .ds-card__check,
    .ds-card--interactive:has(.ds-card__action:is([aria-pressed="true"], [aria-checked="true"], [aria-selected="true"])) > .ds-card__check {
      border-color: HighlightText;
      background: HighlightText;
      color: Highlight;
    }

    .ds-card--interactive:is(:disabled, [aria-disabled="true"]) > .ds-card__check {
      border-color: GrayText;
    }

    /* Blocked and selected: the check says so in the blocked colours. */
    .ds-card--interactive:is(:disabled, [aria-disabled="true"]):is([aria-pressed="true"], [aria-checked="true"], [aria-selected="true"], :has(.ds-card__action:is([aria-pressed="true"], [aria-checked="true"], [aria-selected="true"]))) > .ds-card__check {
      border-color: GrayText;
      background: GrayText;
      color: Canvas;
    }
  }

  .ds-card__title {
    min-width: 0;
    margin: 0;
    padding: 0;
    color: var(--ds-text);
    font: var(--ds-font-subtitle);
    letter-spacing: 0;
    overflow-wrap: anywhere;
  }

  /* A title with a leading icon: icon and words on one centre line. */
  .ds-card__title:has(> svg:first-child) {
    display: flex;
    align-items: center;
    gap: var(--ds-space-2);
  }

  .ds-card__row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--ds-space-3);
    flex-wrap: wrap;
  }

  /* A button (40px) or a switch (40px) next to the title hangs out of the
     title's line (--ds-card-title-line) on both sides instead of making the row taller: every
     card title starts at the same height, whatever its head holds. When the
     row wraps (phones), the row gap makes up for the overhang. A status
     chip, badge or tag fits the title line and sits on it (an overhang
     would hang into the block below a wrapped row); a chip hangs by its
     own height. A badge and a chip come after the card (their own margins
     beat its rhythm), so their rules are in badge.css and chip.css. */
  .ds-card__row {
    row-gap: calc(var(--ds-space-3) + (max(var(--ds-target-min, 0px), calc(var(--ds-btn-height, 40px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px)) - var(--ds-card-title-line, 24px)) / 2);
  }

  .ds-card__row > :not(.ds-card__title, :has(> .ds-card__title)) {
    margin-block: calc((var(--ds-card-title-line, 24px) - max(var(--ds-target-min, 0px), calc(var(--ds-btn-height, 40px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px))) / 2);
  }

  .ds-card__row > .ds-switch,
  .ds-card__row > :has(> .ds-switch) {
    margin-block: calc((var(--ds-card-title-line, 24px) - max(var(--ds-target-min, 0px), calc(var(--ds-switch-height, 40px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px), calc(var(--ds-switch-track-height, 32px) + var(--ds-size-step, 0) * 4px))) / 2);
  }

  .ds-card__row > :is(.ds-status, .ds-tag) {
    margin-block: 0;
  }

  .ds-card__subtitle {
    margin: var(--ds-space-6) 0 0;
    color: var(--ds-text);
    font: var(--ds-font-label);
  }

  .ds-card > .ds-card__subtitle + *,
  .ds-card__body > .ds-card__subtitle + * {
    margin-top: var(--ds-space-2);
  }

  /* Links to related pages: text buttons in a row under a hairline. Each one
     hangs its padding into the gutter, so the first of every line lines up
     with the card text (the gap makes up for it between them). */
  .ds-card__links {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--ds-space-1) calc(var(--ds-space-2) + var(--ds-space-3));
    padding-top: var(--ds-space-3);
    border-top: 1px solid var(--ds-line);
  }

  /* Only text buttons hang their padding out; an outlined button or a link keeps its place. */
  .ds-card__links > :is(.ds-btn--text, .ds-card__link) {
    margin-inline-start: calc(-1 * var(--ds-space-3));
  }

  .ds-card__link {
    --ds-btn-padding-x: var(--ds-space-3);
  }

  /* At the end of a card's header row the padding hangs out at the end. */
  .ds-card__row > .ds-card__link:last-child {
    margin-inline-end: calc(-1 * var(--ds-space-3));
  }

  /* A part of a card with its own small title: a hairline and room above,
     the content close under its title. */
  .ds-card__section {
    display: grid;
    gap: calc(var(--ds-space-3) + var(--ds-density, 0) * 2px);
    margin-top: var(--ds-space-2);
    padding-top: calc(var(--ds-space-5) + var(--ds-density, 0) * 2px);
    border-top: 1px solid var(--ds-card-border, var(--ds-line));
  }

  .ds-card__section > .ds-card__subtitle,
  .ds-card__section > p {
    margin: 0;
  }

  /* A centred "load more" row. */
  .ds-card__more {
    display: flex;
    justify-content: center;
  }

  /* Rows of a disclosure list run to the card's edges, their text in line
     with the card's: the list pulls out, and tells its rows the padding
     through their hook, so nothing here depends on the order of the two
     stylesheets. */
  .ds-card .ds-disclosure-list {
    --ds-disclosure-row-padding-exact: var(--ds-card-pad);
    margin-inline: calc(-1 * var(--ds-card-pad));
  }

  /* Key facts (list.css) under a card's title: the page's rhythm above
     them. A card gives the context, so the rules of what sits in it are
     here, in the card's later sublayer. */
  .ds-card > .ds-facts {
    margin-top: var(--ds-space-5);
  }

  /* Facts above key figures follow the tiles' grid: two equal columns with
     the tiles' gap, so the second fact starts where the third tile does
     (four tiles per row) or the second one does (two per row); phones
     stack them. No per-fact rule: a structural or tag subject under a
     :has() ancestor made Chromium restyle a large part of the page on
     every DOM change inside a card (about 10ms per change on the
     styleguide, every frame of a countUp). */
  .ds-card:has(.ds-tiles) > .ds-facts {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    column-gap: calc(var(--ds-space-3) + var(--ds-density, 0) * 2px);
  }

  @media (max-width: 600px) {
    .ds-card:has(.ds-tiles) > .ds-facts {
      grid-template-columns: minmax(0, 1fr);
    }
  }

  /* Actions on demand (.ds-hover-actions, utilities.css) with a card as
     their nearest host: the card's hover and states reveal them. */
  @media (hover: hover) {
    .ds-card:hover .ds-hover-actions:not(:is(tr, li, .ds-card, .ds-drawer__row, .ds-hover-host):not(:hover) .ds-hover-actions) {
      opacity: 1;
      transition: opacity var(--ds-dur-fast) var(--ds-ease-in-out);
    }
  }

  .ds-card:is(:focus-within, [aria-current]:not([aria-current="false"]), [aria-selected="true"], [data-ds-shown]) .ds-hover-actions:not(:is(tr, li, .ds-card, .ds-drawer__row, .ds-hover-host):is(:focus-within, [aria-current]:not([aria-current="false"]), [aria-selected="true"], .ds-table__row--selected, [data-ds-shown]) :is(tr, li, .ds-card, .ds-drawer__row, .ds-hover-host):not(:focus-within, [aria-current]:not([aria-current="false"]), [aria-selected="true"], .ds-table__row--selected, [data-ds-shown]) .ds-hover-actions) {
    opacity: 1;
    transition: opacity var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  /* Print: a short card is never split across pages (one that holds a table may). */
  @media print {
    .ds-card:not(:has(.ds-table-wrap, .ds-table)) {
      break-inside: avoid;
    }
  }
}

/* ── components/prose/prose.css ── */
/*
 * Rendered rich text: .ds-prose for text the page does not mark up itself
 * (Markdown through DS.markdown, a help article, a release note). A pre in
 * it is a code block: code.css styles it as .ds-code-block (prose requires
 * code); this file keeps only its place in the rhythm.
 *
 *   <div class="ds-prose"> <h2>...</h2> <p>...</p> <ul><li>...</li></ul> <pre><code>...</code></pre> <table>...</table> </div>
 *   <div class="ds-prose ds-prose--dense"> ... </div>        (the body role: in a card, a side sheet)
 *   <div class="ds-prose ds-prose--compact"> ... </div>      (a chat bubble: the body role, one heading size, tight blocks)
 *
 * .ds-prose styles only bare elements inside it (every rule is under
 * :where(.ds-prose) and skips an element with a class that starts with ds-,
 * so a class of the page always wins and a component inside prose keeps its
 * look, wherever its stylesheet stands in the cascade): a rhythm of
 * --ds-prose-gap between blocks (their margins reset first), headings on the
 * type roles (h1 headline, h2 subtitle, h3 and h4 the label weight at the
 * reading size),
 * lists indented --ds-space-5, strong in --ds-prose-strong-weight, links
 * underlined like every link, a pre as a code block (code.css), a table
 * with hairline rows, a --ds-text-2 head and tabular figures that scrolls
 * sideways when it is wider (a cell's data-align="start|center|end", as
 * DS.markdown writes a GFM table's alignment, aligns it), a quote on
 * --ds-surface-high, images at most as wide as the text, inline code a
 * chip, a kbd a key (as .ds-kbd), a mark on the tint. Font:
 * --ds-prose-font (--ds-font-reading); --dense takes --ds-font-body. Long
 * words hyphenate where the browser can, or break.
 *
 * Task lists: a list item that starts with a checkbox (<li><input
 * type="checkbox" disabled checked> text</li>, in a <label> or a <p> too,
 * the way Markdown renderers write them) loses its bullet and takes the
 * checkbox in the bullet's place; wrapped lines stay in line with the text.
 * The box is drawn on the input like a .ds-checkbox, without its motion:
 * rendered text is read-only unless the page wires it (disabled does not dim
 * it here: it is how Markdown says read-only, and the state must read).
 *
 * Callouts: a note in the text, with its word and icon:
 *   <div class="ds-prose__callout ds-tone-warning" role="note">
 *     <p class="ds-prose__callout-title">(alert 16)Warning</p>
 *     <p>...</p>
 *   </div>
 * A tone class on the callout itself (.ds-tone-*) colours the block; without
 * one it has the quote's surface, also inside an element with a tone (a
 * note would read as that tone). The word says what it is, so meaning never
 * rests on the colour.
 *
 * Footnotes: <section class="ds-prose__footnotes"> <ol>...</ol> </section>,
 * the meta role under a hairline. A reference is
 * <sup class="ds-prose__fnref"><a href="#fn-1" id="fnref-1">1</a></sup>
 * (a small figure that leaves the line height alone); each note ends with
 * <a class="ds-prose__fnback" href="#fnref-1" aria-label="Back to reference 1">(cornerUpLeft 16)</a>.
 * The note a reference jumps to (:target) takes the tint, so the eye finds
 * it; the number and the jump say the same.
 *
 * Heading anchors: <h2 id="setup"><a class="ds-prose__anchor"
 * href="#setup">Setup(link 16)</a></h2>: the heading's text links to
 * itself, so its name stays its text; it keeps the heading's look, and the
 * icon (aria-hidden) shows while the heading is hovered or the link has the
 * focus (opacity only).
 *
 * .ds-prose--compact, for a chat bubble or a narrow panel: the body role,
 * every heading at the body size in the label weight, blocks --ds-space-1
 * apart, quotes, callouts, code (code.css) and table cells with less
 * padding.
 *
 * Options (src/core/options.css, docs/options.md), on the prose or any
 * ancestor; each is computed here:
 *   density   .ds-density-*: 1px off the gap between blocks per step, 2px
 *             off the padding of quotes, callouts, code (code.css) and table
 *             cells;
 *             --compact, whose padding is tight already, 1px, and its table
 *             cells keep their side padding; the gap is read on the prose,
 *             so a density class on a child leaves the gap above it alone;
 *             the text stays
 *   shape     .ds-shape-*: multiplies the radius of quotes, callouts, inline
 *             code, kbd and mark (code blocks: code.css)
 *   tone      .ds-tone-*: on a callout only
 *   size      not read: text keeps its role (--dense and --compact choose it)
 *   touch     not read: the only targets are links in text, which the
 *             target-size rule exempts, and read-only task checkboxes
 *
 * Hooks: --ds-prose-gap (--ds-space-2), --ds-prose-font
 * (--ds-font-reading), --ds-prose-strong-weight (--ds-weight-label),
 * --ds-prose-radius (--ds-radius-card).
 *
 * Motion: the anchor icon fades in on --ds-dur-fast and out on
 * --ds-dur-instant; focus rings snap as everywhere.
 *
 * Forced colours: quotes and callouts keep their edges (a transparent
 * outline that the forced colours paint); a mark takes Mark and MarkText;
 * a kbd keeps its border.
 *
 * Print: prose tables wrap and unclip; anchor icons go.
 *
 * Progressive:
 * - hyphenate-limit-chars (hyphens: auto breaks only words of 18
 *   characters or more, keeping 8 on each side; a string with no
 *   hyphenation point, such as a URL, still breaks): without it long
 *   words break anywhere (overflow-wrap) instead of hyphenating.
 * - text-wrap: pretty (paragraphs avoid a lone last word): without it
 *   lines wrap as usual.
 * - scrollbar-color and scrollbar-width (a thin, quiet scrollbar under a
 *   wide table): without them the platform scrollbar shows.
 */

@layer ds.components.prose {
  .ds-prose {
    min-width: 0;
    color: var(--ds-text);
    font: var(--ds-prose-font, var(--ds-font-reading));
    overflow-wrap: anywhere;
    /* Computed here and read by the blocks: a density class on one of them
       changes that block and not the gap above it. */
    --_prose-gap: calc(var(--ds-prose-gap, var(--ds-space-2)) + var(--ds-density, 0) * 1px);
  }

  .ds-prose--dense {
    --ds-prose-font: var(--ds-font-body);
  }

  @supports (hyphenate-limit-chars: 1) {
    /* Hyphenation points come first; break-word splits only a string with
       no other break (a URL, a hash, a path). */
    .ds-prose {
      overflow-wrap: break-word;
      hyphens: auto;
      hyphenate-limit-chars: 18 8 8;
    }
  }

  /* The rhythm: margins reset, then one gap between blocks. */
  :where(.ds-prose) > * {
    margin-block: 0;
  }

  :where(.ds-prose) > * + * {
    margin-block-start: var(--_prose-gap);
  }

  :where(.ds-prose) :is(h1, h2, h3, h4, h5, h6):where(:not([class^="ds-"], [class*=" ds-"])) {
    margin-block: 0;
    color: var(--ds-text);
    letter-spacing: 0;
    text-wrap: balance;
  }

  /* A heading opens a section: more room above it than between paragraphs. */
  :where(.ds-prose) > * + :is(h1, h2, h3, h4, h5, h6):where(:not([class^="ds-"], [class*=" ds-"])) {
    margin-block-start: var(--ds-space-5);
  }

  :where(.ds-prose) h1:where(:not([class^="ds-"], [class*=" ds-"])) {
    font: var(--ds-font-headline);
  }

  :where(.ds-prose) h2:where(:not([class^="ds-"], [class*=" ds-"])) {
    font: var(--ds-font-subtitle);
  }

  :where(.ds-prose) :is(h3, h4, h5, h6):where(:not([class^="ds-"], [class*=" ds-"])) {
    font: inherit;
    font-weight: var(--ds-weight-label);
  }

  :where(.ds-prose) p:where(:not([class^="ds-"], [class*=" ds-"])) {
    text-wrap: pretty;
  }

  :where(.ds-prose) :is(ul, ol):where(:not([class^="ds-"], [class*=" ds-"])) {
    padding-inline-start: var(--ds-space-5);
  }

  :where(.ds-prose) li > :is(ul, ol):where(:not([class^="ds-"], [class*=" ds-"])) {
    margin-block-start: var(--ds-space-1);
  }

  :where(.ds-prose) li:where(:not([class^="ds-"], [class*=" ds-"])) + li:where(:not([class^="ds-"], [class*=" ds-"])) {
    margin-block-start: var(--ds-space-1);
  }

  :where(.ds-prose) :is(strong, b):where(:not([class^="ds-"], [class*=" ds-"])) {
    font-weight: var(--ds-prose-strong-weight, var(--ds-weight-label));
  }

  :where(.ds-prose) a:where(:not([class^="ds-"], [class*=" ds-"])) {
    color: var(--ds-link);
    text-decoration-line: underline;
    text-decoration-thickness: var(--ds-link-underline-thickness);
    text-underline-offset: var(--ds-link-underline-offset);
    text-decoration-color: var(--ds-link-underline);
  }

  :where(.ds-prose) img:where(:not([class^="ds-"], [class*=" ds-"])) {
    max-width: 100%;
    height: auto;
  }

  :where(.ds-prose) blockquote:where(:not([class^="ds-"], [class*=" ds-"])) {
    margin-inline: 0;
    padding: calc(var(--ds-space-3) + var(--ds-density, 0) * 2px) calc(var(--ds-space-4) + var(--ds-density, 0) * 2px);
    border-radius: calc(var(--ds-prose-radius, var(--ds-radius-card)) * var(--ds-shape, 1));
    background: var(--ds-surface-high);
    color: var(--ds-text);
  }

  /* A callout: its word and icon on a line of their own, on the quote's
     surface. */
  .ds-prose__callout {
    padding: calc(var(--ds-space-3) + var(--ds-density, 0) * 2px) calc(var(--ds-space-4) + var(--ds-density, 0) * 2px);
    border-radius: calc(var(--ds-prose-radius, var(--ds-radius-card)) * var(--ds-shape, 1));
    background: var(--ds-surface-high);
    color: var(--ds-text);
  }

  /* The tone is read only from the callout's own class: an inherited one would
     turn a plain note into an error. */
  .ds-prose__callout:is(.ds-tone-neutral, .ds-tone-primary, .ds-tone-info, .ds-tone-success, .ds-tone-warning, .ds-tone-error) {
    background: var(--ds-tone-container, var(--ds-surface-high));
    color: var(--ds-on-tone-container, var(--ds-text));
  }

  .ds-prose__callout > * {
    margin-block: 0;
  }

  .ds-prose__callout > * + * {
    margin-block-start: var(--ds-space-1);
  }

  .ds-prose__callout-title {
    display: flex;
    align-items: center;
    gap: var(--ds-space-2);
    font-weight: var(--ds-prose-strong-weight, var(--ds-weight-label));
  }

  .ds-prose__callout-title > svg {
    flex: none;
  }

  /* Links and inline code take the block's ink: the tint is a surface of its
     own, on which the link colour's contrast is not promised. */
  .ds-prose__callout :where(a:not([class^="ds-"], [class*=" ds-"])) {
    color: inherit;
  }

  /* Footnotes: the meta role under a hairline, the list in the prose's own
     indent. */
  .ds-prose__footnotes {
    padding-block-start: var(--ds-space-3);
    border-block-start: 1px solid var(--ds-line);
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
  }

  .ds-prose__footnotes > :is(ol, ul) {
    margin-block: 0;
  }

  /* A task list: the checkbox stands where the bullet stood (the list's
     indent), so items with and without one line up and wrapped lines hang.
     Three forms: the input directly in the item, or in its first <p> or
     <label>. */
  :where(.ds-prose) li:where(:has(> input[type="checkbox"]:first-child, > :is(p, label):first-child > input[type="checkbox"]:first-child)) {
    position: relative;
    margin-inline-start: calc(-1 * var(--ds-space-5));
    padding-inline-start: var(--ds-space-5);
    list-style: none;
  }

  :where(.ds-prose) input:where(li > [type="checkbox"]:first-child, li > :is(p, label):first-child > [type="checkbox"]:first-child) {
    position: absolute;
    /* 1lh is the text's line only with the text's font (an input has its own). */
    font: inherit;
    inset-block-start: calc((1lh - var(--ds-space-4)) / 2);
    inset-inline-start: 0;
    margin: 0;
  }

  :where(.ds-prose) input:where(li > [type="checkbox"]:first-child, li > :is(p, label):first-child > [type="checkbox"]:first-child):where(:not([class^="ds-"], [class*=" ds-"])) {
    appearance: none;
    box-sizing: border-box;
    width: var(--ds-space-4);
    height: var(--ds-space-4);
    border: 2px solid var(--ds-text-2);
    border-radius: calc(var(--ds-radius-check) * var(--ds-shape, 1));
    background: transparent;
    /* The ring rests (invisible) one width further out and snaps in. */
    outline-offset: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    transition: outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  :where(.ds-prose) input:where(li > [type="checkbox"]:first-child, li > :is(p, label):first-child > [type="checkbox"]:first-child):where(:not([class^="ds-"], [class*=" ds-"])):focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: var(--ds-focus-offset);
  }

  :where(.ds-prose) input:where(li > [type="checkbox"]:first-child, li > :is(p, label):first-child > [type="checkbox"]:first-child):where(:not([class^="ds-"], [class*=" ds-"])):checked {
    border-color: var(--ds-primary);
    background: var(--ds-primary);
  }

  /* The check: two borders, turned, so a strict Content-Security-Policy that
     blocks a data: mask (docs/install.md) never hides it. */
  :where(.ds-prose) input:where(li > [type="checkbox"]:first-child, li > :is(p, label):first-child > [type="checkbox"]:first-child):where(:not([class^="ds-"], [class*=" ds-"])):checked::before {
    content: '';
    position: absolute;
    inset: 0;
    box-sizing: border-box;
    width: 6px;
    height: 10px;
    margin: auto;
    border: 0 solid var(--ds-on-primary);
    border-inline-end-width: 2px;
    border-block-end-width: 2px;
    translate: 0 -1px;
    rotate: 45deg;
  }

  :where(.ds-prose) hr:where(:not([class^="ds-"], [class*=" ds-"])) {
    border: 0;
    border-top: 1px solid var(--ds-line);
  }

  /* A table of rendered text: hairline rows, a quiet head, tabular figures;
     wider than the text, it scrolls on its own. */
  :where(.ds-prose) table:where(:not([class^="ds-"], [class*=" ds-"])) {
    position: relative;
    display: block;
    max-width: 100%;
    overflow-x: auto;
    border-collapse: collapse;
    font: var(--ds-font-body);
    font-variant-numeric: tabular-nums;
    scrollbar-width: thin;
    scrollbar-color: var(--ds-line-2) transparent;
  }

  :where(.ds-prose) :is(th, td):where(:not([class^="ds-"], [class*=" ds-"])) {
    padding: calc(var(--ds-space-2) + var(--ds-density, 0) * 2px) calc(var(--ds-space-3) + var(--ds-density, 0) * 2px);
    border-bottom: 1px solid var(--ds-line);
    text-align: start;
    vertical-align: top;
  }

  :where(.ds-prose) th:where(:not([class^="ds-"], [class*=" ds-"])) {
    color: var(--ds-text-2);
    font: var(--ds-font-label);
  }

  /* A pre in prose is a code block (code.css draws it); its place in the
     rhythm is the prose's: margins reset, then the gap. */
  :where(.ds-prose) pre:where(:not([class^="ds-"], [class*=" ds-"])) {
    margin: 0;
  }

  :where(.ds-prose) > * + pre {
    margin-block-start: var(--_prose-gap);
  }

  /* Code inside a pre or a link is just text: no inline chip per line. */
  :where(.ds-prose) :where(pre, a) code {
    padding: 0;
    border: 0;
    background: none;
    color: inherit;
    font: inherit;
  }

  /* Inline code in prose takes the size of the text around it. */
  :where(.ds-prose) :not(pre) > code:where(:not([class^="ds-"], [class*=" ds-"])) {
    padding: 0 var(--ds-space-1);
    border: 1px solid var(--ds-line);
    border-radius: calc(var(--ds-radius-xs) * var(--ds-shape, 1));
    background: var(--ds-code-bg);
    font-family: var(--ds-font-mono);
    font-size: inherit;
  }

  /* A key: the code font in a hairline box, as .ds-kbd. */
  :where(.ds-prose) kbd:where(:not([class^="ds-"], [class*=" ds-"])) {
    display: inline-block;
    min-width: var(--ds-space-5);
    padding: 0 var(--ds-space-1);
    border: 1px solid var(--ds-line-2);
    border-radius: calc(var(--ds-radius-xs) * var(--ds-shape, 1));
    background: var(--ds-surface);
    color: var(--ds-text-2);
    font: var(--ds-font-code);
    text-align: center;
  }

  /* Marked text (a search hit, a highlight): on the tint. */
  :where(.ds-prose) mark:where(:not([class^="ds-"], [class*=" ds-"])) {
    padding-inline: 2px;
    border-radius: calc(var(--ds-radius-xs) * var(--ds-shape, 1));
    background: var(--ds-accent);
    color: var(--ds-on-accent);
  }

  /* The alignment of a column (DS.markdown writes a GFM table's). */
  :where(.ds-prose) :is(th, td):where(:not([class^="ds-"], [class*=" ds-"]))[data-align="center"] {
    text-align: center;
  }

  :where(.ds-prose) :is(th, td):where(:not([class^="ds-"], [class*=" ds-"]))[data-align="end"] {
    text-align: end;
  }

  /* Heading anchors: the heading's text links to itself; the icon shows on
     hover and focus. */
  .ds-prose__anchor {
    color: inherit;
    text-decoration: none;
    border-radius: calc(var(--ds-radius-xs) * var(--ds-shape, 1));
    outline-offset: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    transition: outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-prose__anchor:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: var(--ds-focus-offset);
  }

  .ds-prose__anchor > svg {
    margin-inline-start: var(--ds-space-2);
    color: var(--ds-text-2);
    vertical-align: -0.125em;
    opacity: 0;
    transition: opacity var(--ds-dur-instant) var(--ds-ease-out);
  }

  .ds-prose__anchor:focus-visible > svg {
    opacity: 1;
    transition-duration: var(--ds-dur-fast);
  }

  @media (hover: hover) {
    :is(h1, h2, h3, h4, h5, h6):hover > .ds-prose__anchor > svg {
      opacity: 1;
      transition-duration: var(--ds-dur-fast);
    }
  }

  /* A footnote reference: a small figure that leaves the line alone. */
  .ds-prose__fnref {
    position: relative;
    inset-block-start: -0.5em;
    font: var(--ds-font-caption);
    line-height: 1;
    vertical-align: baseline;
  }

  .ds-prose__fnref > a,
  .ds-prose__fnback {
    border-radius: calc(var(--ds-radius-xs) * var(--ds-shape, 1));
    color: var(--ds-link);
    outline-offset: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    transition: outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-prose__fnref > a {
    padding-inline: 1px;
    text-decoration: none;
  }

  .ds-prose__fnref > a:focus-visible,
  .ds-prose__fnback:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: var(--ds-focus-offset);
  }

  .ds-prose__fnback > svg {
    vertical-align: -0.2em;
  }

  /* The note a reference jumped to: the tint, so the eye finds it. */
  .ds-prose__footnotes li:target {
    border-radius: calc(var(--ds-radius-xs) * var(--ds-shape, 1));
    background: var(--ds-accent);
    color: var(--ds-on-accent);
  }

  /*
   * Compact, for a chat bubble or a narrow panel: the body role, one heading
   * size and tight blocks. After the rules it tightens; the same (zero)
   * specificity, so the order in this file decides and a page's class wins.
   * Its padding is tight already: 1px per density step instead of 2px, and a
   * cell keeps its side padding (2px per step would close a cell's 4px).
   */
  .ds-prose--compact {
    --ds-prose-font: var(--ds-font-body);
    --_prose-gap: calc(var(--ds-prose-gap, var(--ds-space-1)) + var(--ds-density, 0) * 1px);
  }

  :where(.ds-prose--compact) :is(h1, h2, h3, h4, h5, h6):where(:not([class^="ds-"], [class*=" ds-"])) {
    font: inherit;
    font-weight: var(--ds-weight-label);
  }

  :where(.ds-prose--compact) > * + :is(h1, h2, h3, h4, h5, h6):where(:not([class^="ds-"], [class*=" ds-"])) {
    margin-block-start: var(--ds-space-3);
  }

  :where(.ds-prose--compact) blockquote:where(:not([class^="ds-"], [class*=" ds-"])),
  .ds-prose--compact .ds-prose__callout {
    padding: calc(var(--ds-space-2) + var(--ds-density, 0) * 1px) calc(var(--ds-space-3) + var(--ds-density, 0) * 1px);
  }

  :where(.ds-prose--compact) :is(th, td):where(:not([class^="ds-"], [class*=" ds-"])) {
    padding: calc(var(--ds-space-1) + var(--ds-density, 0) * 1px) var(--ds-space-2);
  }

  @media (forced-colors: active) {
    /* A task box: the system's choice colours, its check in their opposite. */
    :where(.ds-prose) input:where(li > [type="checkbox"]:first-child, li > :is(p, label):first-child > [type="checkbox"]:first-child):where(:not([class^="ds-"], [class*=" ds-"])) {
      forced-color-adjust: none;
      border-color: CanvasText;
      background: Canvas;
    }

    :where(.ds-prose) input:where(li > [type="checkbox"]:first-child, li > :is(p, label):first-child > [type="checkbox"]:first-child):where(:not([class^="ds-"], [class*=" ds-"])):checked {
      border-color: Highlight;
      background: Highlight;
    }

    :where(.ds-prose) input:where(li > [type="checkbox"]:first-child, li > :is(p, label):first-child > [type="checkbox"]:first-child):where(:not([class^="ds-"], [class*=" ds-"])):checked::before {
      border-color: HighlightText;
    }

    :where(.ds-prose) blockquote:where(:not([class^="ds-"], [class*=" ds-"])),
    .ds-prose__callout {
      outline: 1px solid transparent;
    }

    :where(.ds-prose) mark:where(:not([class^="ds-"], [class*=" ds-"])) {
      forced-color-adjust: none;
      background: Mark;
      color: MarkText;
    }
  }

  @media print {
    :where(.ds-prose) table:where(:not([class^="ds-"], [class*=" ds-"])) {
      overflow: visible;
      white-space: pre-wrap;
    }

    .ds-prose__anchor > svg {
      display: none;
    }
  }
}

/* ── components/empty/empty.css ── */
/*
 * Empty state: centred, at most 400px. A tinted disc with the icon (24px),
 * a title, at most one line of what to do next and at most one action.
 *
 *   <div class="ds-empty">
 *     <span class="ds-empty__disc" aria-hidden="true"><svg ...></span>
 *     <p class="ds-empty__title">No devices yet</p>
 *     <p class="ds-empty__text">Add the first one to start the inventory.</p>
 *     <button class="ds-btn ds-btn--tonal" type="button">Add device</button>
 *
 * Where it stands (the variant is a placement, not a look):
 *   --section (or none)  in a card or a panel: the 2.x look
 *   --page               fills a page: more room, a 72px disc, the title type
 *   --inline             in a row, a list or a popup: disc or picture, words
 *                        and action side by side, left-aligned, 32px; 12px of
 *                        block padding that follows density only (neither the
 *                        size step nor --ds-empty-padding); actions take at
 *                        most half the row and stack in a narrow one
 *
 * Why it is empty (the disc's colours; the icon, words and action are the
 * page's, docs/components.md lists them per cause):
 *   --no-data       nothing yet: the tint
 *   --first-use     nothing yet, here is how to start: primary container
 *   --not-set-up    a step is missing: primary container
 *   --no-results    a filter or search left nothing: neutral
 *   --no-access     not allowed to see it: neutral
 *   --offline       cannot reach it now: warning container
 *   --error         it failed: error container
 *   .ds-tone-*      any other meaning, from the class on .ds-empty itself
 * An icon and words always say it, never the colour alone.
 *
 * A picture in place of the disc: <span class="ds-empty__media" aria-hidden="true">
 * <img ... alt=""></span>, at most --ds-empty-media-size high (120px; 160px
 * in --page). Two actions: .ds-empty__actions around them.
 *
 * Options (docs/options.md), read here:
 *   size      .ds-xs ... .ds-xl on it or any ancestor: 8px of disc and 8px of
 *             block padding per step (--inline: the disc only); the type stays
 *             that of its variant
 *   density   any container: 2px of padding per step. So the compact theme
 *             (density -2) gives 28px of block padding, 2.x's 32px with less
 *             room, on purpose.
 *   shape     the disc's radius times --ds-shape, never above half its size
 *   tone      above. target-min: only its buttons read it.
 *
 * No motion of its own; the page picks it by what brought the empty state
 * (docs/motion.md, "Data motion"):
 *   replacing a skeleton           .ds-reveal
 *   a filter, search or live update the rows leave through DS.motion.flip
 *                                  (they fade out in place), then
 *                                  DS.motion.enter(empty, 'fade'), no rise
 *   the filter cleared             DS.motion.leave(empty) while the rows
 *                                  enter through flip
 *   the user deleted the last item DS.motion.enter(disc, 'pop') on the disc
 *
 * A confirmation (a request sent, a job done): .ds-empty--done with a
 * pathLength="1" check in the disc:
 *
 *   <div class="ds-empty ds-empty--done" role="status">
 *     <span class="ds-empty__disc" aria-hidden="true"><svg ...>(check, 24)</svg></span>
 *     <p class="ds-empty__title">Request sent</p>
 *     <p class="ds-empty__text">We will answer within a day.</p>
 *
 * Its own entrance: the disc fades in and pops up on the spring
 * (ds-fade-in, ds-pop-in, --ds-dur-slow) after --ds-dur-base; a ring
 * widens and fades once behind it (ds-ripple on ::after) after
 * --ds-dur-slow; the check draws itself (ds-draw, --ds-dur-glide,
 * --ds-ease-out). Keyframes, so they play when the element is inserted or
 * shown (hidden removed), never again while a re-render keeps the node.
 * Forced colours: the disc keeps an outline (its fill is dropped).
 *
 * Hooks: --ds-empty-disc-size (48px; --page 72px, --inline 32px): the disc's
 * width and height (a confirmation page may want a larger one); the ring
 * follows, the glyph keeps the size of its markup. --ds-empty-disc-bg and
 * --ds-empty-disc-color (the tint), under any cause or tone;
 * --ds-empty-padding (32px, the md base of the block padding; not --inline);
 * --ds-empty-media-size (--inline: 32px).
 *
 * Progressive:
 * - text-wrap (the text avoids a lone last word): without it the line
 *   wraps as usual.
 */

@layer ds.components.empty {
  .ds-empty {
    --_disc: 48px;
    --_media: 120px;
    --_disc-bg: var(--ds-accent);
    --_disc-ink: var(--ds-on-accent-icon);
    display: grid;
    justify-items: center;
    gap: var(--ds-space-2);
    max-width: 400px;
    margin: 0 auto;
    padding: calc(var(--ds-empty-padding, var(--ds-space-8)) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 2px) calc(var(--ds-space-4) + var(--ds-density, 0) * 2px);
    text-align: center;
  }

  .ds-empty__disc {
    --_d: calc(var(--ds-empty-disc-size, var(--_disc)) + var(--ds-size-step, 0) * 8px);
    display: grid;
    place-items: center;
    width: var(--_d);
    height: var(--_d);
    margin-bottom: var(--ds-space-2);
    border-radius: min(calc(min(var(--ds-radius-action), calc(var(--_d) / 2)) * var(--ds-shape, 1)), calc(var(--_d) / 2));
    background: var(--ds-empty-disc-bg, var(--_disc-bg));
    color: var(--ds-empty-disc-color, var(--_disc-ink));
  }

  /* The slot for a picture, in place of the disc. */
  .ds-empty__media {
    display: grid;
    place-items: center;
    max-width: 100%;
    height: var(--ds-empty-media-size, var(--_media));
    margin-bottom: var(--ds-space-2);
    color: var(--ds-text-2);
  }

  .ds-empty__media > :is(img, svg) {
    display: block;
    max-width: 100%;
    height: 100%;
  }

  /* Why it is empty: the disc's colours. */
  .ds-empty--no-data {
    --_disc-bg: var(--ds-accent);
    --_disc-ink: var(--ds-on-accent-icon);
  }

  .ds-empty--first-use,
  .ds-empty--not-set-up {
    --_disc-bg: var(--ds-primary-container);
    --_disc-ink: var(--ds-on-primary-container);
  }

  .ds-empty--no-results,
  .ds-empty--no-access {
    --_disc-bg: var(--ds-surface-high);
    --_disc-ink: var(--ds-text-2);
  }

  .ds-empty--offline {
    --_disc-bg: var(--ds-warning-container);
    --_disc-ink: var(--ds-on-warning-container);
  }

  .ds-empty--error {
    --_disc-bg: var(--ds-error-container);
    --_disc-ink: var(--ds-on-error-container);
  }

  /* A tone from the class on the state itself; it wins over a cause. */
  .ds-empty:is(.ds-tone-neutral, .ds-tone-primary, .ds-tone-info, .ds-tone-success, .ds-tone-warning, .ds-tone-error) {
    --_disc-bg: var(--ds-tone-container);
    --_disc-ink: var(--ds-on-tone-container);
  }

  .ds-empty__title {
    margin: 0;
    color: var(--ds-text);
    font: var(--ds-font-subtitle);
  }

  .ds-empty__text {
    margin: 0;
    color: var(--ds-text-2);
    font: var(--ds-font-body);
    text-wrap: pretty;
  }

  .ds-empty > .ds-btn,
  .ds-empty__actions {
    margin-top: var(--ds-space-3);
  }

  .ds-empty__actions {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: var(--ds-space-2);
  }

  /* Page: fills a page or a whole panel. */
  .ds-empty--page {
    --_disc: 72px;
    --_media: 160px;
    max-width: 480px;
    padding-block: calc(var(--ds-empty-padding, var(--ds-space-12)) * 2 + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 2px);
  }

  .ds-empty--page > .ds-empty__title {
    font: var(--ds-font-title);
  }

  /* Section: the default, named. */
  .ds-empty--section {
    max-width: 400px;
  }

  /* Inline: in a row, a list or a popup. Disc, words, then the action. */
  .ds-empty--inline {
    --_disc: 32px;
    --_media: 32px;
    /* The actions take at most half a narrow row and stack there, so the
       words keep theirs (it stays this box's own width: a size container
       would collapse in a table cell or a popup that fits its content). */
    grid-template-columns: auto minmax(0, 1fr) fit-content(50%);
    justify-items: start;
    align-items: center;
    column-gap: var(--ds-space-3);
    row-gap: 0;
    max-width: none;
    padding: calc(var(--ds-space-3) + var(--ds-density, 0) * 2px) 0;
    text-align: start;
  }

  .ds-empty--inline > :is(.ds-empty__disc, .ds-empty__media) {
    grid-row: 1 / span 2;
    margin: 0;
  }

  /* Its width from the slot's height, not from the markup's. */
  .ds-empty--inline > .ds-empty__media > :is(img, svg) {
    width: auto;
  }

  .ds-empty--inline > :is(.ds-empty__title, .ds-empty__text) {
    grid-column: 2;
  }

  .ds-empty--inline > .ds-empty__title {
    font: var(--ds-font-label);
  }

  .ds-empty--inline > .ds-empty__text {
    font: var(--ds-font-meta);
  }

  .ds-empty--inline > :is(.ds-btn, .ds-empty__actions) {
    grid-column: 3;
    grid-row: 1 / span 2;
    justify-self: end;
    justify-content: flex-end;
    margin: 0;
  }

  /* The confirmation: the disc pops in, a ring widens behind it once, the
     check draws itself. */
  .ds-empty--done .ds-empty__disc {
    position: relative;
    /* The ring (z-index -1) widens behind the check, above the disc's fill. */
    isolation: isolate;
    animation:
      ds-fade-in var(--ds-dur-slow) var(--ds-ease-in-out) var(--ds-dur-base) backwards,
      ds-pop-in var(--ds-dur-slow) var(--ds-ease-spatial) var(--ds-dur-base) backwards;
  }

  .ds-empty--done .ds-empty__disc::after {
    content: '';
    position: absolute;
    inset: 0;
    z-index: -1;
    border-radius: inherit;
    background: var(--ds-accent);
    opacity: 0;
    pointer-events: none;
    animation: ds-ripple var(--ds-dur-slow) var(--ds-ease-out) var(--ds-dur-slow);
  }

  .ds-empty--done .ds-empty__disc [pathLength] {
    stroke-dasharray: 1;
  }

  /* The check draws on its <svg>; the pathLength="1" path inherits the
     stroke (Chromium can miss a change above a [pathLength] rule). */
  .ds-empty--done .ds-empty__disc > svg {
    animation: ds-draw var(--ds-dur-glide) var(--ds-ease-out) var(--ds-dur-slow) backwards;
  }

  @media (forced-colors: active) {
    .ds-empty--done .ds-empty__disc {
      outline: 1px solid CanvasText;
    }
  }
}

/* ── components/menu/menu.css ── */
/*
 * Menu (Material 3): actions for one item or the overflow of a toolbar, on
 * the popover elevation, opened from a button. Each item is an icon and a
 * label, with an optional description and shortcut; a checkable item shows a
 * check when checked (aria-checked, never colour alone); a divider separates
 * groups.
 *
 *   <button class="ds-btn ds-btn--quiet ds-btn--icon" type="button" aria-label="More actions"
 *           aria-haspopup="menu" aria-expanded="false" aria-controls="row-menu">(moreVertical)</button>
 *   <div class="ds-menu" role="menu" id="row-menu" aria-label="Actions" hidden data-state="open | closed" [data-placement="top"] [data-anchored]>
 *     <button class="ds-menu__item" role="menuitem" type="button">(pencil) <span class="ds-menu__label">Edit</span></button>
 *     <button class="ds-menu__item" role="menuitemcheckbox" type="button" aria-checked="true">(check, .ds-menu__check) <span class="ds-menu__label">Pinned</span></button>
 *     <div class="ds-menu__divider" role="separator"></div>
 *     <button class="ds-menu__item" role="menuitem" type="button" aria-disabled="true">(trash) <span class="ds-menu__label">Delete</span></button>
 *   </div>
 *
 * Groups of radio items under a heading, and a meta at an item's end (a
 * shortcut in a .ds-kbd, or "On" / "Off" of a menuitemcheckbox):
 *
 *   <div role="group" aria-labelledby="sort-h">
 *     <p class="ds-menu__heading" id="sort-h">Sort by</p>
 *     <button class="ds-menu__item" role="menuitemradio" type="button" aria-checked="true">(check, .ds-menu__check) <span class="ds-menu__label">Name</span></button>
 *     <button class="ds-menu__item" role="menuitemradio" type="button" aria-checked="false">(check, .ds-menu__check) <span class="ds-menu__label">Last seen</span></button>
 *   </div>
 *   <button class="ds-menu__item" role="menuitem" type="button">(copy) <span class="ds-menu__label">Copy link</span><span class="ds-menu__meta">Ctrl C</span></button>
 *
 * An item with a description, a shortcut, and the danger item (its label
 * names the consequence, so the colour is never alone):
 *
 *   <button class="ds-menu__item" role="menuitem" type="button">(archive)
 *     <span class="ds-menu__content"><span class="ds-menu__label">Archive</span>
 *       <span class="ds-menu__description">Hide it from every list.</span></span>
 *     <span class="ds-menu__shortcut">Ctrl E</span></button>
 *   <button class="ds-menu__item ds-menu__item--danger" role="menuitem" type="button">(trash) <span class="ds-menu__label">Delete device</span></button>
 *
 * A submenu (3.0): the item names it, and it sits inside the menu right
 * after the item; DS.menu places it beside the item in the top layer:
 *
 *   <button class="ds-menu__item" role="menuitem" type="button" aria-haspopup="menu" aria-expanded="false"
 *           aria-controls="move-menu">(folder) <span class="ds-menu__label">Move to</span>(chevronRight, .ds-menu__chevron)</button>
 *   <div class="ds-menu" role="menu" id="move-menu" aria-label="Move to" hidden>…</div>
 *
 * A search at the top of a long menu (3.0), and the row the system writes
 * when nothing matches:
 *
 *   <div class="ds-menu" id="assign" hidden>                       no role: a menu holds only items
 *     <div class="ds-menu__search">(search) <input type="search" aria-label="Search people" aria-controls="assign-list" placeholder="Search"></div>
 *     <div class="ds-menu__list" role="menu" id="assign-list" aria-label="Assign to">…items…</div>
 *     <p class="ds-menu__empty" role="none">No results</p>
 *   </div>
 *
 * A context menu (3.0): data-ds-contextmenu="#row-menu" on a row, a tile or
 * a region opens the menu at the pointer (right click, long press) or under
 * the focused element (Shift+F10, the ContextMenu key).
 *
 *   DS.overlay.open(menu, { opener: button });   DS.overlay.close(menu);   DS.menu.openAt(menu, { x, y, opener: row });
 *   <button data-ds-open="#row-menu" aria-haspopup="menu" aria-expanded="false">   the same, with its arrow keys
 *
 * DS.overlay (js/overlay.js) places it below the trigger, aligned with its
 * start edge (towards the start edge without room; above it when it does
 * not fit below and there is more room above; never taller than the room
 * on its side, so it never covers its trigger: it scrolls inside),
 * focuses the first enabled item (the last one when opened from ArrowUp),
 * moves focus with ArrowUp, ArrowDown, Home and End (wrapping; a heading is
 * no item, so they skip it) and to the next item whose label starts with
 * the typed letters (type-ahead), closes on
 * Escape (focus back on the trigger), on Tab, after an item's click
 * handlers ran, and on a pointerdown outside (focus stays where the pointer
 * put it), and sets aria-expanded on the trigger.
 *
 * Placement API: --ds-menu-x and --ds-menu-y (left and top, px, written by
 * DS.overlay where anchor positioning is missing).
 *
 * Motion (D17): as the combobox list, it grows out of its trigger. It fades
 * in over --ds-dur-fast while its clip opens from the trigger's edge
 * (--ds-clip-from) and it grows from --ds-scale-popup at the trigger
 * (--ds-motion-origin), both over --ds-dur-medium on the spring; the
 * resting clip reaches --ds-space-6 beyond the box, so the shadow is there
 * from the first frame. It leaves with a fade only (--ds-dur-instant).
 * Transitions keyed on data-state (DS.overlay), so a menu closed mid-way
 * turns back from where it is; without data-state (a page that toggles
 * hidden by hand) it plays ds-fade-in and ds-clip-in once.
 *
 * Options: a row's height is --ds-menu-item-height (48px, its md, comfortable
 * value) plus 8px per size step and 4px per density step, never below the
 * touch minimum (--ds-target-min); density also changes the menu's own block
 * padding; size changes the type (the body role by default); shape multiplies
 * the menu's radius (--ds-menu-radius). A row's side padding ignores density:
 * it is room for its icon and label. A row is square, so shape leaves it alone.
 *
 * Items: a 48px row in the body role, a state layer in the content colour
 * (hover, press in --ds-dur-micro, the focus layer and an inset ring that
 * snaps in), the ripple (js/ripple.js) and no press morph (a menu row is
 * not a pill). aria-disabled items stay focusable (their name is read) but
 * show the disabled ink and take no press.
 *
 * menuitemradio and menuitemcheckbox items show .ds-menu__check only when
 * aria-checked="true" (the page flips it; one radio of a group at a time).
 * .ds-menu__heading names a group (caption type, not focusable);
 * .ds-menu__meta sits at an item's end (meta type, tabular).
 *
 * Cut edges: a menu capped by the room on its side scrolls, and each edge
 * with more to show fades into the menu's surface: a sticky shade
 * (::before, ::after) in --ds-surface-popover, --ds-scroll-fade long
 * (default --ds-space-8; 0px turns it off), whose opacity is the
 * registered number --ds-scroll-edge-start or --ds-scroll-edge-end of
 * scroller.css. Not a mask: the menu is its own surface, and a mask would
 * cut its shadow. Where scroll timelines exist ds-scroll-edge-start and
 * ds-scroll-edge-end drive the numbers on the menu's scroll; elsewhere
 * DS.overlay attaches DS.dom.scrollEdges(menu, { axis: 'block' }) while it
 * is open, and data-ds-overflow-start / -end set them over --ds-dur-fast.
 * Focus moved by the keys stays clear of the shades (scroll-padding).
 *
 * Forced colours: the menu keeps an edge (its transparent outline), the
 * focused item its ring, a blocked item GrayText; the edge shades go; a danger
 * item keeps the system's text, its label says what it does; an item whose
 * submenu shows is Highlight on HighlightText.
 *
 * Print: an open menu is not printed.
 *
 * Progressive:
 * - anchor positioning (anchor-name on the trigger, position-anchor,
 *   position-area and position-try-fallbacks on the menu, behind @supports;
 *   DS.overlay opens the menu in the top layer with data-anchored, below the
 *   trigger, flipped above or towards
 *   the start edge when there is no room): without it the script writes
 *   --ds-menu-x/-y and sets data-placement="top" above.
 * - scrollbar-color and scrollbar-width (a thin scrollbar in a long menu):
 *   without them the platform scrollbar shows.
 * - scroll-driven animations (animation-timeline: scroll(), animation-range;
 *   the edge shades follow the scroll position): without them the
 *   data-ds-overflow-* attributes of DS.dom.scrollEdges() (attached by
 *   DS.overlay) set the shades, or none show.
 */

@layer ds.components.menu {
  /* Fixed, so no scrolling or clipping box cuts it off. inset, margin and
     border double as the reset of the UA box of a popover. Physical on
     purpose (D9): --ds-menu-x is a script coordinate from the left. */
  .ds-menu {
    position: fixed;
    inset: var(--ds-menu-y, 0px) auto auto var(--ds-menu-x, 0px);
    z-index: var(--ds-z-popover);
    display: flex;
    flex-direction: column;
    box-sizing: border-box;
    min-width: 112px;
    max-width: min(280px, calc(100vw - 2 * var(--ds-space-2)));
    max-height: calc(100vh - 2 * var(--ds-space-2));
    margin: 0;
    padding: calc(var(--ds-menu-padding, var(--ds-space-2)) + var(--ds-density, 0) * 2px) 0;
    overflow-y: auto;
    border: 0;
    border-radius: calc(var(--ds-menu-radius, var(--ds-radius-xs)) * var(--ds-shape, 1));
    background: var(--ds-surface-popover);
    color: var(--ds-text);
    box-shadow: var(--ds-elev-popover);
    scrollbar-width: thin;
    scrollbar-color: var(--ds-line-2) transparent;
    /* Focus moved by the keys lands clear of the edge shades. */
    scroll-padding-block: var(--ds-scroll-fade, var(--ds-space-8));
    /* Invisible; forced colors paint it, so the menu keeps an edge. */
    outline: 1px solid transparent;
    /* Grows at its trigger (originFrom() writes the origin); its clip rests
       --ds-space-6 beyond the box, room for the shadow. */
    transform-origin: var(--ds-motion-origin, 0% 0%);
    clip-path: inset(calc(-1 * var(--ds-space-6)));
  }

  /* Above the trigger: it is revealed from its bottom edge. */
  .ds-menu[data-placement="top"] {
    transform-origin: var(--ds-motion-origin, 0% 100%);
  }

  /* Shown by hand (no data-state): the reveal plays once. */
  .ds-menu:not([data-state]) {
    animation:
      ds-fade-in var(--ds-dur-fast) var(--ds-ease-in-out) backwards,
      ds-clip-in var(--ds-dur-medium) var(--ds-ease-spatial) backwards;
  }

  /* Driven by DS.overlay: transitions keyed on data-state, so a menu closed
     mid-way continues from where it is. */
  .ds-menu[data-state] {
    animation: none;
    transition:
      opacity var(--ds-dur-fast) var(--ds-ease-in-out),
      scale var(--ds-dur-medium) var(--ds-ease-spatial),
      clip-path var(--ds-dur-medium) var(--ds-ease-spatial);
  }

  /* The exit only fades, in --ds-dur-instant; scale and clip go back to
     their start once the menu is invisible. Closed, it takes no pointer. */
  .ds-menu[data-state="closed"] {
    opacity: 0;
    scale: var(--ds-motion-scale, var(--ds-scale-popup));
    clip-path: var(--ds-clip-from, inset(0 0 100% 0));
    pointer-events: none;
    transition:
      opacity var(--ds-dur-instant) var(--ds-ease-in-out),
      scale 0ms var(--ds-ease-in-out) var(--ds-dur-instant),
      clip-path 0ms var(--ds-ease-in-out) var(--ds-dur-instant);
  }

  .ds-menu[hidden] {
    display: none;
  }

  /* Anchor positioning: in the top layer (popover="manual"), below the
     trigger from its start edge or above it (data-placement="top", the
     side DS.overlay chose), towards the start edge without room (the
     margins flip with it); never taller than the room on its side, its
     position-area being its containing block. */
  @supports (position-area: block-end) {
    .ds-menu[data-anchored] {
      inset: auto;
      max-height: calc(100% - 2 * var(--ds-space-1));
      margin: var(--ds-space-1) 0;
      position-area: block-end span-inline-end;
      position-try-fallbacks: flip-block, flip-inline, flip-block flip-inline;
    }

    .ds-menu[data-anchored][data-placement="top"] {
      position-area: block-start span-inline-end;
    }
  }

  .ds-menu__item {
    position: relative;
    display: flex;
    flex-shrink: 0;
    align-items: center;
    gap: var(--ds-space-3);
    width: 100%;
    min-height: max(var(--ds-target-min, 0px), calc(var(--ds-menu-item-height, 48px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px));
    margin: 0;
    padding: 0 var(--ds-space-3);
    border: 0;
    border-radius: 0;
    background: transparent;
    color: var(--ds-text);
    font: var(--ds-menu-font, var(--ds-size-font, var(--ds-font-body)));
    text-align: start;
    text-decoration: none;
    cursor: pointer;
    -webkit-tap-highlight-color: transparent;
    /* An inset ring (the scrolling menu clips anything outside): it rests
       on the edge and snaps inward. */
    outline-offset: 0;
    transition: outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-menu__item svg {
    flex-shrink: 0;
    color: var(--ds-text-2);
  }

  .ds-menu__label {
    flex: 1;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  /* A label with a description under it: one block that takes the free width,
     with room above and below, since it may be taller than the row. */
  .ds-menu__content {
    display: grid;
    flex: 1;
    min-width: 0;
    padding-block: var(--ds-space-2);
  }

  .ds-menu__description {
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
    overflow-wrap: anywhere;
  }

  /* The check of a checkable item keeps its room when unchecked, so the
     labels line up; it shows only with aria-checked="true". */
  .ds-menu__item:not([aria-checked="true"]) .ds-menu__check {
    visibility: hidden;
  }

  /* State layer in the content colour. */
  .ds-menu__item::before {
    content: '';
    position: absolute;
    inset: 0;
    background: currentColor;
    opacity: 0;
    pointer-events: none;
    transition: opacity var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  @media (hover: hover) {
    .ds-menu__item:hover::before {
      opacity: var(--ds-state-hover);
    }
  }

  .ds-menu__item:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: calc(-1 * var(--ds-focus-width));
  }

  .ds-menu__item:focus-visible::before {
    opacity: var(--ds-state-focus);
    transition-duration: 0s;
  }

  /* Press-in in --ds-dur-micro (.ds-pressed: js/ripple.js holds it). */
  .ds-menu__item:active::before,
  .ds-menu__item.ds-pressed::before {
    opacity: var(--ds-state-pressed);
    transition-duration: var(--ds-dur-micro);
  }

  /* Cannot be chosen: the disabled ink, no hover and no press (no ripple
     either); the focus layer stays, so keyboard users find it. */
  .ds-menu__item[aria-disabled="true"],
  .ds-menu__item:disabled {
    opacity: var(--ds-disabled-opacity, var(--ds-state-disabled));
    color: var(--ds-disabled-ink, var(--ds-text));
    cursor: default;
  }

  .ds-menu__item[aria-disabled="true"] svg,
  .ds-menu__item:disabled svg {
    color: inherit;
  }

  @media (hover: hover) {
    .ds-menu__item[aria-disabled="true"]:hover::before {
      opacity: 0;
    }
  }

  .ds-menu__item[aria-disabled="true"]:is(:active, .ds-pressed)::before {
    opacity: 0;
  }

  .ds-menu__item[aria-disabled="true"]:focus-visible::before {
    opacity: var(--ds-state-focus);
  }

  .ds-menu__divider {
    flex-shrink: 0;
    height: 1px;
    margin: var(--ds-space-2) 0;
    background: var(--ds-line);
  }

  /* A group of items (role="group") and the items under a search
     (.ds-menu__list) are a column like the menu itself. */
  .ds-menu [role="group"],
  .ds-menu__list {
    display: flex;
    flex-direction: column;
    flex-shrink: 0;
  }

  /* The name of a group: not focusable, so the arrow keys pass it by. */
  .ds-menu__heading {
    flex-shrink: 0;
    margin: 0;
    padding: var(--ds-space-2) var(--ds-space-4) var(--ds-space-1);
    color: var(--ds-text-2);
    font: var(--ds-font-caption);
  }

  /* At an item's end: a shortcut (.ds-kbd) or the state word of a checkbox item. */
  .ds-menu__meta {
    flex-shrink: 0;
    margin-inline-start: auto;
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
    font-variant-numeric: tabular-nums;
  }

  .ds-menu__label + .ds-menu__meta {
    margin-inline-start: var(--ds-space-3);
  }

  /* The shortcut slot: meta type, in the same place as a meta. */
  .ds-menu__shortcut {
    flex-shrink: 0;
    margin-inline-start: var(--ds-space-3);
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
  }

  .ds-menu__item[aria-disabled="true"] .ds-menu__meta,
  .ds-menu__item:disabled .ds-menu__meta,
  .ds-menu__item[aria-disabled="true"] .ds-menu__shortcut,
  .ds-menu__item:disabled .ds-menu__shortcut,
  .ds-menu__item[aria-disabled="true"] .ds-menu__description,
  .ds-menu__item:disabled .ds-menu__description {
    color: inherit;
  }

  /* An action that destroys: the error ink on its label and icon, with a word
     that names it (the label), never the colour alone. No red background. */
  .ds-menu__item--danger {
    color: var(--ds-menu-danger-color, var(--ds-error));
  }

  .ds-menu__item--danger svg {
    color: inherit;
  }

  /* An item that opens a submenu: a chevron at its end; while its submenu
     shows it keeps the hover layer, so the path stays visible (the word is
     aria-expanded). */
  .ds-menu__chevron {
    flex-shrink: 0;
    margin-inline-start: auto;
  }

  .ds-menu__label + .ds-menu__chevron,
  .ds-menu__content + .ds-menu__chevron {
    margin-inline-start: var(--ds-space-3);
  }

  .ds-menu__item[aria-expanded="true"]::before {
    opacity: var(--ds-state-hover);
  }

  /* The search of a long menu: a field pinned at its top, flush with its
     edge, the hairline under it standing for the top's cut edge. */
  .ds-menu__search {
    position: sticky;
    inset-block-start: 0;
    z-index: var(--ds-z-raised);
    display: flex;
    flex-shrink: 0;
    align-items: center;
    gap: var(--ds-space-2);
    margin-block: calc(-1 * (var(--ds-menu-padding, var(--ds-space-2)) + var(--ds-density, 0) * 2px)) var(--ds-space-1);
    padding: 0 var(--ds-space-3);
    border-block-end: 1px solid var(--ds-line);
    background: var(--ds-surface-popover);
    color: var(--ds-text-2);
    /* An inset ring, as on the items: it rests on the edge and snaps inward. */
    outline-offset: 0;
    transition: outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-menu__search > input {
    flex: 1;
    min-width: 0;
    min-height: max(var(--ds-target-min, 0px), calc(var(--ds-menu-item-height, 48px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px));
    margin: 0;
    padding: 0;
    border: 0;
    background: transparent;
    color: var(--ds-text);
    font: var(--ds-font-input);
  }

  .ds-menu__search > input::placeholder {
    color: var(--ds-text-2);
    opacity: 1;
  }

  /* The ring sits on the row, inset, since the menu clips what lies outside. */
  .ds-menu__search > input:focus-visible {
    outline: none;
  }

  .ds-menu__search:has(input:focus-visible) {
    outline: var(--ds-focus-outline);
    outline-offset: calc(-1 * var(--ds-focus-width));
  }

  /* The pinned field is the top's edge: no shade over it. */
  .ds-menu:has(> .ds-menu__search)::before {
    display: none;
  }

  /* What the search says when nothing matches (written by the system). */
  .ds-menu__empty {
    flex-shrink: 0;
    margin: 0;
    padding: var(--ds-space-3) var(--ds-space-4);
    color: var(--ds-text-2);
    font: var(--ds-menu-font, var(--ds-size-font, var(--ds-font-body)));
  }

  /* A context menu's target on a touch screen: the long press is the
     menu's, so the platform's callout and text selection stay away. */
  @media (pointer: coarse) {
    .ds-theme [data-ds-contextmenu] {
      -webkit-touch-callout: none;
      -webkit-user-select: none;
      user-select: none;
    }
  }

  /* The cut edges of a long menu. The menu is its own surface (a mask
     would cut its shadow away), so a shade of that surface lies over each
     edge that has more to show, --ds-scroll-fade long, above the items:
     sticky at the edge, taking no room (the negative margin). Its number
     (--ds-scroll-edge-start or -end, registered in scroller.css) is 0 at
     rest; the menu's scroll timeline drives it where it exists, else the
     data-ds-overflow-* attributes of DS.dom.scrollEdges(), which
     DS.overlay attaches while the menu is open. */
  .ds-menu::before,
  .ds-menu::after {
    content: '';
    position: sticky;
    z-index: var(--ds-z-raised);
    flex: none;
    height: var(--ds-scroll-fade, var(--ds-space-8));
    pointer-events: none;
    transition:
      --ds-scroll-edge-start var(--ds-dur-fast) var(--ds-ease-in-out),
      --ds-scroll-edge-end var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  .ds-menu::before {
    inset-block-start: 0;
    margin-block-end: calc(-1 * var(--ds-scroll-fade, var(--ds-space-8)));
    background: linear-gradient(var(--ds-surface-popover), transparent);
    opacity: var(--ds-scroll-edge-start);
  }

  .ds-menu::after {
    inset-block-end: 0;
    margin-block-start: calc(-1 * var(--ds-scroll-fade, var(--ds-space-8)));
    background: linear-gradient(transparent, var(--ds-surface-popover));
    opacity: var(--ds-scroll-edge-end);
  }

  .ds-menu[data-ds-overflow-start]::before {
    --ds-scroll-edge-start: 1;
  }

  .ds-menu[data-ds-overflow-end]::after {
    --ds-scroll-edge-end: 1;
  }

  /* Scroll-linked, on the menu's scroll (the nearest scroller of its own
     shades): the shorthand first (it resets animation-timeline). */
  @supports (animation-timeline: scroll()) {
    .ds-menu::before {
      animation: ds-scroll-edge-start linear both;
      animation-timeline: scroll(nearest block);
      animation-range: 0 var(--ds-space-8);
    }

    .ds-menu::after {
      animation: ds-scroll-edge-end linear both;
      animation-timeline: scroll(nearest block);
      animation-range: calc(100% - var(--ds-space-8)) 100%;
    }
  }

  /* Blocked is one system colour (D8). The shades go: forced colours
     would keep their gradient in the theme's surface colour. An item whose
     submenu shows is an open disclosure: Highlight. */
  @media (forced-colors: active) {
    .ds-menu__item[aria-expanded="true"] {
      forced-color-adjust: none;
      background: Highlight;
      color: HighlightText;
    }

    .ds-menu__item[aria-expanded="true"] svg {
      color: inherit;
    }

    .ds-menu__item[aria-disabled="true"],
    .ds-menu__item:disabled {
      color: GrayText;
    }

    .ds-menu::before,
    .ds-menu::after {
      display: none;
    }
  }

  @media print {
    .ds-menu {
      display: none;
    }
  }
}

/* ── components/chip/chip.css ── */
/*
 * Filter chips on native checkboxes or radios: the input stays in the form
 * and in the tab order, visually hidden; selection shows the tint and a
 * check, never the tint alone.
 *
 *   <fieldset class="ds-chips">
 *     <legend class="ds-sr">Status</legend>
 *     <label class="ds-chip">
 *       <input class="ds-chip__input" type="checkbox" name="status" value="open">
 *       <span class="ds-chip__body"><svg class="ds-chip__check" ...>(check, 18px)</svg><span>Open</span></span>
 *     </label>
 *     <span class="ds-chips__divider" aria-hidden="true"></span>
 *   </fieldset>
 *
 * Selecting opens the room of the check: an empty slot before the label
 * (.ds-chip__body::after, the only property that moves is its width)
 * grows to the check's size on --ds-ease-out (it pushes layout, so it
 * never overshoots) and the neighbours on the line follow the reflow
 * every frame. The check lies over the slot (never a flex item) and draws
 * itself from the short arm after --ds-dur-micro (stroke-dashoffset, the
 * glyph needs pathLength="1" like the icon set's check). Deselecting
 * reverses it: the check leaves first, the slot closes after
 * --ds-dur-micro; radio chips grow and shrink at once, so a pair keeps
 * its width. Transitions only: a chip rendered selected stays still.
 * Across a wrap the chips glide by FLIP when DS.ripple.attach() wires the
 * row (a programmatic `checked` change, or a page without the script,
 * still jumps to the new line); meanwhile the row carries data-ds-glide
 * and every chip an opaque backing (--ds-chips-backdrop, the colour behind
 * the row, written by the script), so crossing chips never show through;
 * the toggled chip opens with its neighbour (clip-path on the body, its
 * label translated, both by the script), so the two never overlap.
 *
 * Press: the state layer in --ds-dur-micro (also while js/ripple.js holds
 * .ds-pressed) and the ripple; chips are not pills, so they do not morph.
 * A disabled chip shows no hover, press or ripple and takes the button's
 * disabled model (--ds-disabled-fill outline or container, --ds-disabled-ink
 * label and check, --ds-disabled-opacity), fading on --ds-dur-fast.
 * Keyboard focus: the ring is solid from the first frame and snaps from
 * offset + width to the offset (outline-offset, --ds-dur-fast), with the
 * focus layer (--ds-state-focus).
 *
 * aria-disabled="true" on the input looks and acts like disabled (the
 * click is blocked by the action guard); its focus layer stays.
 *
 * Action and input chips are buttons that act at once (a suggestion, an
 * active filter that removes itself), in a role="group" row:
 *
 *   <div class="ds-chips" role="group" aria-label="Active filters">
 *     <button class="ds-chip ds-chip--input" type="button" data-tip="Building C, second floor">
 *       <span class="ds-chip__body"><span class="ds-chip__label"><span class="ds-sr">Remove filter </span>Building C, second floor</span>(close 18 .ds-chip__trailing)</span></button>
 *     <button class="ds-chip" type="button"><span class="ds-chip__body">(user 18 .ds-chip__icon)<span class="ds-chip__label">Only my devices</span></span></button>
 *   </div>
 *
 *   .ds-chip--input   the tint (--ds-chip-input-bg, -color, -border); the
 *                     whole chip removes its value
 *   .ds-chips--wrap   on the row: labels wrap inside the chip (long
 *                     suggestions); a one-line chip keeps its height
 *
 * The body keeps every visual; no check slot; 16px padding, 8px next to a
 * leading icon or a trailing glyph (--ds-chip-check-size); the label ends
 * in an ellipsis once the body reaches --ds-chip-max-width (240px). Hover,
 * the focus ring (on the chip, snapping), the press in --ds-dur-micro and
 * the disabled model like a filter chip; no morph. A chip that stays on or
 * off is a filter chip, never a button with aria-pressed. A row whose chips
 * all went (.ds-chips:empty) takes no room.
 *
 * Options (src/core/options.css, docs/options.md), on the chip or any
 * ancestor; each is computed here, in the chip's own rule:
 *   size      .ds-xs ... .ds-xl: 8px of height per step (16, 24, 32, 40, 48px,
 *             never below its own line), 4px of side padding and 2px of check
 *             and icon per step, the type role of the size
 *   density   .ds-density-*: 4px of height per step; not the side padding
 *   shape     .ds-shape-*: multiplies the radius, at most half the height
 *   touch     .ds-touch: at least --ds-touch-target (48px) high
 *   tone      .ds-tone-* on the chip itself (an inherited tone stays out, so a
 *             chip in a tinted region keeps its look): a selected filter chip,
 *             an input chip and an action chip take the tone's container and
 *             its ink; a resting filter chip stays neutral. The word on the
 *             chip carries the meaning, the tone repeats it.
 *
 * Hooks: --ds-chip-height (32px), --ds-chip-padding-x (16px), --ds-chip-radius
 * (--ds-radius-chip), --ds-chip-font, --ds-chip-check-size (18px),
 * --ds-chip-disabled-border, --ds-chip-disabled-bg (selected),
 * --ds-chip-input-bg, --ds-chip-input-color, --ds-chip-input-border
 * (--ds-accent, --ds-on-accent), --ds-chip-max-width (240px). The glide
 * backing reads --ds-chips-backdrop (the script's), else --ds-flip-backdrop.
 * The computed values (--_box, --_radius, --_pad, --_near, --_check, --_tint,
 * --_on-tint) are private: never set them.
 */

@layer ds.components.chip {
  .ds-chips {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--ds-space-2);
    margin: 0;
    padding: 0;
    border: 0;
    min-width: 0;
  }

  /* A row whose chips all went (the last filter removed) takes no room. */
  .ds-chips:empty {
    display: none;
  }

  .ds-chips__divider {
    width: 1px;
    height: 20px;
    margin: 0 var(--ds-space-2);
    background: var(--ds-line);
  }

  /* Narrow screens wrap the chips; a divider would dangle at a line end. */
  @media (max-width: 720px) {
    .ds-chips__divider {
      display: none;
    }
  }

  .ds-chip {
    /* The options, computed here (docs/options.md); the body and its parts
       inherit them. The height: the hook plus 8px per size step and 4px per
       density step; never below the touch minimum. */
    --_box: max(var(--ds-target-min, 0px), calc(var(--ds-chip-height, 32px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px));
    /* The corners times the shape, at most half the box. */
    --_radius: min(calc(var(--ds-chip-radius, var(--ds-radius-chip)) * var(--ds-shape, 1)), calc(var(--_box) / 2));
    /* Side padding: 4px per size step, density leaves it alone; next to an
       icon, a trailing glyph or the check slot it is 8px less (at least 4px). */
    --_pad: calc(var(--ds-chip-padding-x, var(--ds-space-4)) + var(--ds-size-step, 0) * 4px);
    --_near: max(var(--ds-space-1), calc(var(--_pad) - var(--ds-space-2)));
    --_check: calc(var(--ds-chip-check-size, 18px) + var(--ds-size-step, 0) * 2px);
    position: relative;
    display: inline-flex;
    cursor: pointer;
  }

  /* The tone of the chip itself: its fills read these two (never an inherited
     tone: a chip in a tinted region keeps its look). */
  .ds-chip:is(.ds-tone-neutral, .ds-tone-primary, .ds-tone-info, .ds-tone-success, .ds-tone-warning, .ds-tone-error) {
    --_tint: var(--ds-tone-container);
    --_on-tint: var(--ds-on-tone-container);
  }

  /* The native input stays in the form and in the tab order, visually hidden. */
  .ds-chip__input {
    position: absolute;
    width: 1px;
    height: 1px;
    margin: 0;
    opacity: 0;
    pointer-events: none;
  }

  .ds-chip__body {
    position: relative;
    isolation: isolate;
    display: inline-flex;
    align-items: center;
    gap: var(--ds-space-2);
    /* Never below its own line, in the smallest size and density. */
    height: var(--_box);
    min-height: calc(1lh + 2px);
    /* The same in both states: the gap after the empty slot gives the
       label its 16px; selected the slot adds the check's room. */
    padding-block: 0;
    padding-inline: var(--_near) var(--_pad);
    border: 1px solid var(--ds-line-2);
    border-radius: var(--_radius);
    color: var(--ds-text-2);
    font: var(--ds-chip-font, var(--ds-size-font, var(--ds-font-chip)));
    white-space: nowrap;
    /* The ring rests (invisible) one width further out and snaps in. */
    outline-offset: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    transition:
      background-color var(--ds-dur-fast) var(--ds-ease-in-out),
      border-color var(--ds-dur-fast) var(--ds-ease-in-out),
      color var(--ds-dur-fast) var(--ds-ease-in-out),
      opacity var(--ds-dur-fast) var(--ds-ease-in-out),
      outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  /* State layer in the content colour. */
  .ds-chip__body::before {
    content: '';
    position: absolute;
    inset: -1px;
    z-index: -1;
    border-radius: inherit;
    background: currentColor;
    opacity: 0;
    transition: opacity var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  /* Hover and press only for an input that can change (a disabled chip
     shows neither; js/ripple.js gives it no ripple). */
  @media (hover: hover) {
    .ds-chip:hover .ds-chip__input:not(:disabled, [aria-disabled="true"]) + .ds-chip__body::before {
      opacity: var(--ds-state-hover);
    }
  }

  /* Keyboard focus: the layer appears with the ring and fades out on blur. */
  .ds-chip__input:focus-visible + .ds-chip__body::before {
    opacity: var(--ds-state-focus);
    transition-duration: 0s;
  }

  .ds-chip:active .ds-chip__input:not(:disabled, [aria-disabled="true"]) + .ds-chip__body::before,
  .ds-chip.ds-pressed .ds-chip__input:not(:disabled, [aria-disabled="true"]) + .ds-chip__body::before {
    opacity: var(--ds-state-pressed);
    transition-duration: var(--ds-dur-micro);
  }

  .ds-chip:has(.ds-chip__input:is(:disabled, [aria-disabled="true"])) {
    cursor: not-allowed;
  }

  /* The slot: the room of the check, first in the row (order), 0 wide at
     rest. Its width is the only thing that moves when the chip toggles;
     it closes after the check has begun to leave. */
  .ds-chip__body::after {
    content: '';
    order: -1;
    flex-shrink: 0;
    width: 0;
    transition: width var(--ds-dur-medium) var(--ds-ease-out) var(--ds-dur-micro);
  }

  .ds-chip__input:checked + .ds-chip__body::after {
    width: var(--_check);
    transition-delay: 0s;
  }

  /* Radio chips trade the selection: one slot opens while the other
     closes, at once, so the pair keeps its width. */
  .ds-chip__input[type="radio"] + .ds-chip__body::after {
    transition-delay: 0s;
  }

  /* DS.ripple.attach() measures the final layout of a toggle (a wrap?)
     with the slots at their end width for one frame. */
  .ds-chips[data-ds-snap] .ds-chip__body::after {
    transition: none;
  }

  /* While chips glide across a wrap (DS.ripple.attach()), each chip rests on
     an opaque backing in the colour behind the row, under its body: a chip
     that crosses another, transparent or still fading to its fill, never
     shows the other one through it. At once on and off; at rest it matches
     what is behind the row. */
  .ds-chips[data-ds-glide] .ds-chip {
    border-radius: var(--_radius);
    background-color: var(--ds-chips-backdrop, var(--ds-flip-backdrop, var(--ds-surface)));
  }

  /* The check lies over the slot, never a flex item, and fades: in at once
     (--ds-dur-micro, before the stroke starts), out with the stroke. The
     drawn stroke (pathLength="1") runs on the <svg>, and its path inherits
     it: from the short arm, after the check's fade-in; out faster and
     accelerating. Set on the path itself, Chromium missed the change of
     :checked (its style invalidation does not reach a [pathLength]
     selector on the camelCase SVG attribute), so the check drew late. */
  .ds-chip__check {
    position: absolute;
    top: calc(50% - var(--_check) / 2);
    inset-inline-start: var(--_near);
    width: var(--_check);
    height: var(--_check);
    opacity: 0;
    stroke-dashoffset: 1;
    transition:
      opacity var(--ds-dur-fast) var(--ds-ease-in),
      stroke-dashoffset var(--ds-dur-fast) var(--ds-ease-in);
  }

  .ds-chip__check [pathLength] {
    stroke-dasharray: 1;
  }

  .ds-chip__input:checked + .ds-chip__body {
    border-color: var(--_tint, var(--ds-accent));
    background: var(--_tint, var(--ds-accent));
    color: var(--_on-tint, var(--ds-on-accent));
  }

  .ds-chip__input:checked + .ds-chip__body .ds-chip__check {
    opacity: 1;
    stroke-dashoffset: 0;
    transition:
      opacity var(--ds-dur-micro) var(--ds-ease-in-out),
      stroke-dashoffset var(--ds-dur-medium) var(--ds-ease-out) var(--ds-dur-micro);
  }

  .ds-chip__input:focus-visible + .ds-chip__body {
    outline: var(--ds-focus-outline);
    outline-offset: var(--ds-focus-offset);
  }

  /* Disabled: the button model. The outline (or, selected, the container)
     takes the neutral fill and the label and check the disabled ink; a
     theme that dims instead (--ds-disabled-opacity, the fill and ink set
     to `initial`) keeps the chip's own colours. */
  .ds-chip__input:is(:disabled, [aria-disabled="true"]) + .ds-chip__body {
    border-color: var(--ds-chip-disabled-border, var(--ds-disabled-fill, var(--ds-line-2)));
    color: var(--ds-disabled-ink, var(--ds-text-2));
    opacity: var(--ds-disabled-opacity, var(--ds-state-disabled));
  }

  .ds-chip__input:checked:is(:disabled, [aria-disabled="true"]) + .ds-chip__body {
    border-color: var(--ds-chip-disabled-bg, var(--ds-disabled-fill, var(--ds-accent)));
    background: var(--ds-chip-disabled-bg, var(--ds-disabled-fill, var(--ds-accent)));
    color: var(--ds-disabled-ink, var(--ds-on-accent));
  }

  /*
   * Action and input chips: a <button> (or a link) that acts at once. The
   * element's own look is reset; the body keeps every visual. No check
   * slot; the padding follows a leading icon or a trailing glyph. Not a
   * pill, so no morph; a chip that stays on or off is a filter chip.
   */
  :is(button, a).ds-chip {
    margin: 0;
    padding: 0;
    border: 0;
    border-radius: var(--_radius);
    background: none;
    color: inherit;
    font: inherit;
    text-align: start;
    text-decoration: none;
    -webkit-tap-highlight-color: transparent;
    /* The ring rests (invisible) one width further out and snaps in. */
    outline-offset: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    transition: outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  :is(button, a).ds-chip > .ds-chip__body {
    max-width: var(--ds-chip-max-width, 240px);
    padding-inline: var(--_pad);
  }

  :is(button, a).ds-chip > .ds-chip__body:has(> .ds-chip__icon:first-child) {
    padding-inline-start: var(--_near);
  }

  :is(button, a).ds-chip > .ds-chip__body:has(> .ds-chip__trailing:last-child) {
    padding-inline-end: var(--_near);
  }

  :is(button, a).ds-chip > .ds-chip__body::after {
    content: none;
  }

  .ds-chip__icon,
  .ds-chip__trailing {
    flex-shrink: 0;
    width: var(--_check);
    height: var(--_check);
  }

  .ds-chip__label {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  @media (hover: hover) {
    :is(button, a).ds-chip:not(:disabled, [aria-disabled="true"]):hover > .ds-chip__body::before {
      opacity: var(--ds-state-hover);
    }
  }

  :is(button, a).ds-chip:focus-visible > .ds-chip__body::before {
    opacity: var(--ds-state-focus);
    transition-duration: 0s;
  }

  :is(button, a).ds-chip:not(:disabled, [aria-disabled="true"]):is(:active, .ds-pressed) > .ds-chip__body::before {
    opacity: var(--ds-state-pressed);
    transition-duration: var(--ds-dur-micro);
  }

  :is(button, a).ds-chip:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: var(--ds-focus-offset);
  }

  :is(button, a).ds-chip:is(:disabled, [aria-disabled="true"]) {
    cursor: not-allowed;
  }

  :is(button, a).ds-chip:is(:disabled, [aria-disabled="true"]) > .ds-chip__body {
    border-color: var(--ds-chip-disabled-border, var(--ds-disabled-fill, var(--ds-line-2)));
    color: var(--ds-disabled-ink, var(--ds-text-2));
    opacity: var(--ds-disabled-opacity, var(--ds-state-disabled));
  }

  /* An input chip: an active filter or a picked value; the whole chip removes it. */
  .ds-chip--input > .ds-chip__body {
    border-color: var(--_tint, var(--ds-chip-input-border, var(--ds-accent)));
    background: var(--_tint, var(--ds-chip-input-bg, var(--ds-accent)));
    color: var(--_on-tint, var(--ds-chip-input-color, var(--ds-on-accent)));
  }

  /* An action chip with a tone of its own takes it like an input chip. */
  :is(button, a).ds-chip:is(.ds-tone-neutral, .ds-tone-primary, .ds-tone-info, .ds-tone-success, .ds-tone-warning, .ds-tone-error):not(:disabled, [aria-disabled="true"]) > .ds-chip__body {
    border-color: var(--_tint);
    background: var(--_tint);
    color: var(--_on-tint);
  }

  .ds-chip--input:is(:disabled, [aria-disabled="true"]) > .ds-chip__body {
    border-color: var(--ds-chip-disabled-bg, var(--ds-disabled-fill, var(--ds-chip-input-border, var(--ds-accent))));
    background: var(--ds-chip-disabled-bg, var(--ds-disabled-fill, var(--ds-chip-input-bg, var(--ds-accent))));
    color: var(--ds-disabled-ink, var(--ds-chip-input-color, var(--ds-on-accent)));
  }

  /* Wrapping chips (long suggestions): the label wraps inside the chip; a
     one-line chip keeps its height, and the corners stay soft. */
  .ds-chips--wrap .ds-chip__body {
    height: auto;
    min-height: max(var(--_box), calc(1lh + 2px));
    padding-block: max(0px, calc((var(--_box) - 1lh) / 2 - 1px));
    white-space: normal;
  }

  .ds-chips--wrap .ds-chip__label {
    overflow: visible;
    overflow-wrap: anywhere;
  }

  /* Forced colors: the selected fill would be dropped, so a selected chip
     takes the system highlight; the check (stroke currentColor) follows
     in HighlightText. */
  @media (forced-colors: active) {
    .ds-chip__input:checked + .ds-chip__body {
      forced-color-adjust: none;
      border-color: Highlight;
      background: Highlight;
      color: HighlightText;
    }

    .ds-chip__input:checked:focus-visible + .ds-chip__body,
    .ds-chip__input[aria-disabled="true"]:focus-visible + .ds-chip__body {
      outline-color: CanvasText;
    }

    /* Disabled in GrayText; selected, a GrayText container with the check
       and label in Canvas (like the disabled switch). */
    .ds-chip__input:is(:disabled, [aria-disabled="true"]) + .ds-chip__body {
      forced-color-adjust: none;
      border-color: GrayText;
      background: Canvas;
      color: GrayText;
    }

    .ds-chip__input:checked:is(:disabled, [aria-disabled="true"]) + .ds-chip__body {
      border-color: GrayText;
      background: GrayText;
      color: Canvas;
    }

    /* An input chip keeps a real edge (its fill is dropped), as does an action
       chip with a tone; a blocked action or input chip turns GrayText. */
    .ds-chip--input > .ds-chip__body,
    :is(button, a).ds-chip:is(.ds-tone-neutral, .ds-tone-primary, .ds-tone-info, .ds-tone-success, .ds-tone-warning, .ds-tone-error):not(:disabled, [aria-disabled="true"]) > .ds-chip__body {
      border-color: CanvasText;
    }

    :is(button, a).ds-chip:is(:disabled, [aria-disabled="true"]) > .ds-chip__body {
      forced-color-adjust: none;
      border-color: GrayText;
      background: Canvas;
      color: GrayText;
    }
  }

  /* In a card's head row (card.css, an earlier sublayer) a chip hangs out of
     the title's line by its own height. */
  .ds-card__row > .ds-chip {
    margin-block: calc((var(--ds-card-title-line, 24px) - max(var(--ds-target-min, 0px), calc(var(--ds-chip-height, 32px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px))) / 2);
  }

  /* A chip in a current list row (list.css) takes the system colours again
     in forced colours, as the row's other controls do. */
  @media (forced-colors: active) {
    .ds-list__item:is([aria-current]:not([aria-current="false"]), :has(.ds-list__action[aria-current]:not([aria-current="false"]))) .ds-chip {
      forced-color-adjust: auto;
    }
  }
}

/* ── components/badge/badge.css ── */
/*
 * Badge: a count on a button, chip, tab or drawer item ("3 new"). Counts
 * only: a label of words is a tag (.ds-tag, status.css), a state is a
 * status chip (.ds-status).
 *
 *   <button class="ds-btn" type="button">(mail 16)Inbox <span class="ds-badge">3</span></button>
 *   <span class="ds-badge ds-tone-error">2</span>
 *   <span class="ds-badge" data-ds-badge="128" data-ds-badge-max="99"></span>   "99+" (badge.js)
 *   <span class="ds-badge ds-badge--dot ds-tone-error"><span class="ds-sr">New messages</span></span>
 *
 *   (none: the tint)
 *   .ds-tone-neutral  -primary  -info  -success  -warning  -error
 *   --dot                      a dot instead of a figure (--ds-badge-dot-size,
 *                              8px at md), in --ds-primary or the tone's full
 *                              colour, which hold 3:1 on a surface; needs a
 *                              word, in .ds-sr or beside it
 *
 * Options (docs/options.md), computed here into --_h:
 *   size      .ds-xs ... .ds-xl on the badge or any ancestor (a small button
 *             takes a small badge): 2px per step (16 ... 24px), a dot 2px per
 *             step. The caption type stays.
 *   shape     the radius times --ds-shape, never above half the height (a
 *             dot is a dot at any shape)
 *   tone      from the class on the badge itself: an inherited tone never
 *             recolours it (a badge in an error alert stays what it was)
 *   density, target-min: not read. It sits in a line or on a control, and
 *             neither makes it a target or gives it room to lose.
 *
 * A pill of at least --ds-badge-size (20px at md) in the caption type with
 * tabular figures, on --ds-badge-bg / --ds-badge-color (the tint,
 * --ds-accent / --ds-on-accent); the tones take their container and
 * on-container pair, and a toned badge needs its word in the row (colour
 * is never the only signal: "2 failed"). An empty badge (:empty) takes no
 * room, an empty dot does. On a tinted host (a pressed toggle, a tonal button, an open
 * disclosure button, a checked chip, an input chip, a selected table row)
 * the default badge turns to --ds-primary / --ds-on-primary and the
 * neutral one to --ds-surface / --ds-text-2, so it never melts into the
 * tint. In a blocked host (a disabled or aria-disabled button, chip, tab
 * or drawer item) it takes the disabled model: --ds-disabled-fill and
 * --ds-disabled-ink over any tone (GrayText in forced colours).
 *
 * Motion: colours glide on --ds-dur-fast. A count that appears pops in
 * (DS.motion.enter(badge, 'pop')), one that goes pops out
 * (DS.motion.leave(badge, 'pop', { then: 'hide' })); the number itself
 * changes at once, and nothing plays on load.
 *
 * Forced colours: Canvas / CanvasText with a CanvasText outline (GrayText
 * in a blocked host).
 *
 * Hooks: --ds-badge-size (20px, the md base), --ds-badge-dot-size (8px),
 * --ds-badge-radius (--ds-radius-action, never above half the size),
 * --ds-badge-bg (a dot: --ds-primary), --ds-badge-color.
 *
 * On an icon button's corner (.ds-badge--corner, a direct child of a
 * positioned host such as .ds-btn--icon or an avatar):
 *
 *   <button class="ds-btn ds-btn--quiet ds-btn--icon" type="button" aria-label="Notifications, 3 new">
 *     (bell 20)<span class="ds-badge ds-badge--corner ds-tone-error" aria-hidden="true">3</span></button>
 *
 * It hangs a quarter of its height over the top end corner (a dot sits
 * inside the corner, on the edge of a round host); a press on it is the
 * host's, which it belongs to. A ripple host clips while a ripple is inside, which
 * would cut it: a host that holds one keeps no clip and its ripple clips
 * itself instead (ripple.css). The host's name says the count: the badge is
 * aria-hidden.
 */

@layer ds.components.badge {
  .ds-badge {
    --_h: calc(var(--ds-badge-size, 20px) + var(--ds-size-step, 0) * 2px);
    --_fill: var(--ds-accent);
    display: inline-flex;
    flex-shrink: 0;
    align-items: center;
    justify-content: center;
    min-width: var(--_h);
    height: var(--_h);
    padding-inline: var(--ds-space-1);
    border-radius: min(calc(min(var(--ds-badge-radius, var(--ds-radius-action)), calc(var(--_h) / 2)) * var(--ds-shape, 1)), calc(var(--_h) / 2));
    background: var(--ds-badge-bg, var(--_fill));
    color: var(--ds-badge-color, var(--ds-on-accent));
    font: var(--ds-font-caption);
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
    transition:
      background-color var(--ds-dur-fast) var(--ds-ease-in-out),
      color var(--ds-dur-fast) var(--ds-ease-in-out),
      opacity var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  .ds-badge:empty {
    display: none;
  }

  /* A dot: no figure, always round; its word sits in .ds-sr or beside it.
     Nothing to read in it, so the fill itself has to hold 3:1 on a surface:
     the primary colour, not the tint. */
  .ds-badge--dot {
    --_h: calc(var(--ds-badge-dot-size, 8px) + var(--ds-size-step, 0) * 2px);
    --_fill: var(--ds-primary);
    padding-inline: 0;
    border-radius: 50%;
  }

  .ds-badge--dot:empty {
    display: inline-flex;
  }

  /* A tone from the class on the badge itself (.ds-tone-* sets the pair). */
  .ds-badge:is(.ds-tone-neutral, .ds-tone-primary, .ds-tone-info, .ds-tone-success, .ds-tone-warning, .ds-tone-error) {
    --ds-badge-bg: var(--ds-tone-container);
    --ds-badge-color: var(--ds-on-tone-container);
  }

  /* A figure on a tone's container; a dot has no figure, so it takes the
     tone's full colour, which holds 3:1 on a surface. */
  .ds-badge--dot:is(.ds-tone-neutral, .ds-tone-primary, .ds-tone-info, .ds-tone-success, .ds-tone-warning, .ds-tone-error) {
    --ds-badge-bg: var(--ds-tone);
  }

  .ds-badge.ds-tone-neutral:not(.ds-badge--dot) {
    --ds-badge-bg: var(--ds-surface-high);
    --ds-badge-color: var(--ds-text-2);
  }

  /* On a tinted host the tint badge would vanish: the strong pair instead.
     The hosts of later components (a selected table row, a blocked tab or
     drawer item) repeat these rules in their own stylesheets. */
  :is(.ds-btn[aria-pressed="true"], .ds-btn--tonal, .ds-btn--disclosure[aria-expanded="true"], .ds-btn[aria-haspopup="dialog"][aria-expanded="true"], .ds-chip__input:checked + .ds-chip__body, .ds-chip--input) .ds-badge:not(.ds-tone-neutral, .ds-tone-primary, .ds-tone-info, .ds-tone-success, .ds-tone-warning, .ds-tone-error) {
    --ds-badge-bg: var(--ds-primary);
    --ds-badge-color: var(--ds-on-primary);
  }

  :is(.ds-btn[aria-pressed="true"], .ds-btn--tonal, .ds-btn--disclosure[aria-expanded="true"], .ds-btn[aria-haspopup="dialog"][aria-expanded="true"], .ds-chip__input:checked + .ds-chip__body, .ds-chip--input) .ds-badge.ds-tone-neutral:not(.ds-badge--dot) {
    --ds-badge-bg: var(--ds-surface);
    --ds-badge-color: var(--ds-text-2);
  }

  /* On the primary fill a primary dot would vanish: the fill's ink instead. */
  .ds-btn--filled .ds-badge--dot:not(.ds-tone-neutral, .ds-tone-primary, .ds-tone-info, .ds-tone-success, .ds-tone-warning, .ds-tone-error) {
    --_fill: var(--ds-on-primary);
  }

  /* In a blocked host (disabled, aria-disabled) the disabled model, over
     any tone: the 12% container and the 38% ink. A theme that dims instead
     (--ds-disabled-fill and -ink set to initial) keeps the badge's colours
     and the host's opacity fades it. */
  :is(.ds-btn:disabled, .ds-btn[aria-disabled="true"]:not([aria-busy="true"]), .ds-chip__input:is(:disabled, [aria-disabled="true"]) + .ds-chip__body, :is(button, a).ds-chip:is(:disabled, [aria-disabled="true"])) .ds-badge {
    background: var(--ds-disabled-fill, var(--ds-badge-bg, var(--_fill)));
    color: var(--ds-disabled-ink, var(--ds-badge-color, var(--ds-on-accent)));
  }

  /* On the corner of its host (an icon button, an avatar, any positioned
     element that holds it as a direct child): out of the flow, over the top
     end corner, a quarter of its height outside. A dot sits inside the
     corner, on the edge of a round host. A press on it is the host's (it
     is the host's child, also where it hangs over). The host never clips while it
     ripples (ripple.css), so the badge stays whole. */
  .ds-badge--corner {
    position: absolute;
    inset-block-start: calc(var(--_h) / -4);
    inset-inline-end: calc(var(--_h) / -4);
  }

  .ds-badge--corner.ds-badge--dot {
    inset-block-start: calc(var(--_h) / 4);
    inset-inline-end: calc(var(--_h) / 4);
  }

  @media (forced-colors: active) {
    .ds-badge {
      forced-color-adjust: none;
      outline: 1px solid CanvasText;
      outline-offset: -1px;
      background: Canvas;
      color: CanvasText;
    }

    :is(.ds-btn:disabled, .ds-btn[aria-disabled="true"]:not([aria-busy="true"]), .ds-chip__input:is(:disabled, [aria-disabled="true"]) + .ds-chip__body, :is(button, a).ds-chip:is(:disabled, [aria-disabled="true"])) .ds-badge {
      outline-color: GrayText;
      color: GrayText;
    }
  }

  /* In a card's head row (card.css, an earlier sublayer) a badge sits on the
     title's line. */
  .ds-card__row > .ds-badge {
    margin-block: 0;
  }
}

/* ── components/sheet/sheet.css ── */
/*
 * Modal side sheet (Material 3): white, rounded on its leading corners, on
 * the overlay elevation, over a plain scrim (never blurred). The panel is
 * opaque throughout: it slides its full width in from the edge on the
 * spatial spring while the scrim fades (D16), and leaves faster than it
 * came, back to the edge, accelerating, without a fade; the scrim fades out
 * with it. At 600px and below it rises from the bottom and falls back down;
 * there it fills the screen, so it rises on --ds-ease-out: a spring would
 * carry its head past the top edge. A strip of its own background past its
 * outer edge (the bleed) covers the spring's overshoot, so the scrim never
 * shows at the screen edge. A close taken back mid-way continues from
 * where the panel is.
 *
 * Native markup (preferred): showModal() makes the page inert and gives
 * the sheet its modal semantics.
 *
 *   <dialog class="ds-sheet" aria-labelledby="sheet-title">
 *     <div class="ds-sheet__backdrop" data-ds-close></div>
 *     <section class="ds-sheet__panel"> ... (as below)
 *
 * Div markup (fallback), hidden until it opens:
 *
 *   <div class="ds-sheet" role="dialog" aria-modal="true" aria-labelledby="sheet-title" hidden>
 *     <div class="ds-sheet__backdrop" data-ds-close></div>
 *     <section class="ds-sheet__panel [ds-sheet__panel--wide]">
 *       <div class="ds-sheet__head">
 *         <div class="ds-sheet__heading">
 *           <h2 class="ds-sheet__title" id="sheet-title">Details</h2>
 *           <p class="ds-sheet__subtitle" aria-live="polite">12 of 240 devices</p>   (optional)
 *         </div>
 *         <button class="ds-btn ds-btn--quiet ds-btn--icon" type="button" aria-label="Close" data-ds-close>(close)</button>
 *       </div>
 *       <div class="ds-sheet__body" tabindex="0"> ... </div>
 *       <div class="ds-sheet__foot">                                    (optional)
 *         <p class="ds-meta">3 filters</p>
 *         <button class="ds-btn ds-btn--text" type="button">Reset</button>
 *         <button class="ds-btn ds-btn--filled" type="button" data-ds-close>Show 12 devices</button>
 *       </div>
 *
 * Open and close both with DS.overlay.open(sheet, { opener }) and
 * DS.overlay.close(sheet) (js/overlay.js), or declaratively with
 * [data-ds-open="#id"] on a button: focus, trap, Escape, the scroll lock and
 * data-state ("closed", then "open"; "closed" again to
 * leave). The motion runs on transitions keyed on data-state, so a
 * reversal continues from the current value in every engine.
 *
 *   .ds-sheet--closing   the exit by hand, without data-state (keyframes):
 *                        release the trap and focus the opener first, add
 *                        the class, and after DS.motion.settled(panel) hide
 *                        the sheet and remove the class in the same task.
 *                        On a native sheet it keeps the element shown and
 *                        stacked after close() took it out of the top
 *                        layer. During the exit the panel ignores the
 *                        pointer and the backdrop swallows clicks, so
 *                        nothing reaches the page under it.
 *
 * The hidden attribute hides the div sheet, also without .ds-base.
 *
 * Head: the title wraps (a long record name stays readable); in
 * .ds-sheet__heading a .ds-sheet__subtitle under it (meta type, one line,
 * ellipsis; empty, it takes no room). The head's buttons never shrink.
 * Foot: the sheet's actions, at the end, wrapping, above a hairline
 * (--ds-sheet-foot-border); a leading .ds-meta takes the start; it holds
 * the safe area, so the body above it ends with the normal gap; empty, it
 * takes no room. A lone .ds-btn directly in the body keeps its own width.
 *
 * Another record in an open sheet (previous/next, another row of the
 * table): keep the sheet open and swap only the body, inside
 * DS.motion.transition() with type 'forward' or 'back' for previous and
 * next, 'fade-through' for another row:
 *
 *   DS.motion.transition(() => { DS.dom.morphHtml(body, html); return body; }, { type: 'forward' });
 *
 * The body then takes the view's motion (ds-sheet-body, motion.css) while
 * head, panel and the page under the scrim stay still; without View
 * Transitions the body enters with .ds-enter--swap. A refresh of the same
 * record never calls transition(): a plain DS.dom.morphHtml(body, html),
 * since data never replays an entrance.
 *
 * Container transform (opt-in): DS.overlay.open(sheet, { opener: row,
 * container: true }) grows the row into the panel (js/overlay.js).
 *
 * data-scrolled on the panel while its body is scrolled: the head's
 * hairline shows then (where scroll timelines exist it follows the body's
 * scroll by itself). DS.overlay.open() sets it through
 * DS.dom.watchScrolled(body) (a 1px sentinel at the top of the body, never
 * a scroll listener); a sheet shown without DS.overlay calls it once. Do
 * not use <header> in the head: outside main content it would be a second
 * banner landmark.
 *
 * The on-screen keyboard: with DS.dom.followViewport() on the page, the
 * panel ends above it (--ds-keyboard-inset, 0px without it) while the
 * scrim covers the whole window.
 *
 * Docked panels (3.0): beside the content instead of over it, in a
 * layout that shares the room. DS.overlay opens them as a non-modal layer.
 *
 *   <div class="ds-sheet__layout">
 *     <div class="ds-sheet__main"> ... the list ... </div>
 *     <section class="ds-sheet__panel ds-sheet__panel--push" aria-labelledby="t" hidden>   (or --inspector)
 *       <div class="ds-sheet__resize" aria-label="Resize the details"></div>     (optional)
 *       <div class="ds-sheet__head"> ... </div>
 *       <div class="ds-sheet__body"> ... </div>
 *
 *   --push        the content narrows while the panel's width opens from 0
 *                 (the registered --ds-sheet-reveal, 0 to 1, over
 *                 --ds-dur-long on --ds-ease-out; back in --ds-dur-base,
 *                 --ds-ease-exit); its parts keep their width, uncovered
 *                 from the inline end; DS.sheet moves focus in
 *   --inspector   the same beside a list that stays usable; focus stays in
 *                 the list
 * No scrim, no radius, a hairline (--ds-sheet-docked-border) instead of
 * the shadow, --ds-sheet-docked-width (400px); it sticks in view in a
 * taller page. The layout is a container: under 720px the panel lies over
 * the main column with the overlay elevation, under 480px it takes its
 * whole width.
 *
 * Resizing (3.0): .ds-sheet__resize, the first child of a panel (modal or
 * docked), is a separator on its inner edge (DS.sheet writes its role,
 * values and the width, --ds-sheet-size, a runtime property): a hit strip
 * at least the touch target wide under .ds-touch, a pill that shows on
 * hover, focus and while it drags, always without hover (data-resizing on the panel, which
 * holds the docked width's transition). The modal sheet's separator sits on
 * its left edge (physical, like its slide); at 600px and below it has none.
 *
 * Options: density changes the padding of head, body and foot and the height
 * of the head; shape multiplies the radius; a size class on the sheet changes
 * only the controls inside (its width is --ds-sheet-width, or --wide).
 *
 * Forced colours: the transparent outline of the panel becomes its edge;
 * a docked panel's hairline stays; the separator's pill is CanvasText,
 * Highlight while focused or dragged.
 *
 * Hook: --ds-sheet-width (560px), --ds-sheet-width-wide (720px),
 * --ds-sheet-padding (--ds-space-6), --ds-sheet-head-height (64px),
 * --ds-sheet-radius (--ds-radius-dialog), --ds-sheet-foot-border
 * (1px solid --ds-line), --ds-sheet-docked-width (400px),
 * --ds-sheet-docked-border (1px solid --ds-line).
 *
 * Print: an open sheet is not printed (it floats over the page).
 *
 * At the floor, used directly: @starting-style and allow-discrete
 * transitions (a native sheet driven by hand, showModal() and close() of the
 * page without DS.overlay, plays the same transitions, also on close(); the
 * overlay property, where the engine has it, keeps it in the top layer
 * through every exit).
 *
 * Progressive:
 * - View Transitions (while DS.motion.transition() runs, data-ds-vt on
 *   <html>, the body of an open modal sheet is named ds-sheet-body, so a
 *   record swap moves only the body; a sheet shown inline, without
 *   data-state, [open] or aria-modal, is never named): without them the
 *   body enters with .ds-enter--swap.
 * - scroll-driven animations (animation-timeline, animation-range,
 *   scroll-timeline, timeline-scope; the head's hairline fades in over the
 *   first --ds-space-2 of the body's scroll, on the named timeline
 *   --ds-sheet-scroll scoped on the panel): without them data-scrolled
 *   shows it over --ds-dur-fast.
 * - scrollbar-color and scrollbar-width (a thin, quiet scrollbar on the
 *   body): without them the platform scrollbar shows.
 */

/*
 * How much of a docked panel's width is open (0 closed, 1 open): registered,
 * so the width it gives follows a transition, on --ds-ease-out (a size that
 * pushes the content never overshoots). Internal: written by the rules below
 * only, never inherited.
 */
@property --ds-sheet-reveal {
  syntax: '<number>';
  inherits: false;
  initial-value: 1;
}

@layer ds.components.sheet {
  .ds-sheet {
    position: fixed;
    inset: 0;
    z-index: var(--ds-z-drawer);
    /* Out of flow: no rhythm margin from a parent card (.ds-card > * + *). */
    margin: 0;
    display: flex;
    justify-content: flex-end;
    /* The panel ends above the on-screen keyboard (DS.dom.followViewport()
       writes its height); the scrim still covers the whole window. */
    padding-bottom: var(--ds-keyboard-inset, 0px);
    /* The bleed past the panel's outer edge never makes anything scroll. */
    overflow: clip;
  }

  /* A native <dialog> loses the UA box: it is the same full-window frame
     as the div. */
  dialog.ds-sheet {
    width: auto;
    height: auto;
    max-width: none;
    max-height: none;
    margin: 0;
    padding: 0 0 var(--ds-keyboard-inset, 0px);
    border: 0;
    background: transparent;
    color: inherit;
    overflow: clip;
  }

  dialog.ds-sheet::backdrop {
    background: transparent;
  }

  /* display: flex above outranks the UA rule that hides a closed dialog.
     --closing keeps it shown while its exit plays outside the top layer;
     data-state="open" keeps it shown when the page closes it natively
     (close(), a <form method="dialog">), until the close event, a task
     later, starts the exit from where it stands. */
  dialog.ds-sheet:not([open]):not(.ds-sheet--closing):not([data-state="open"]) {
    display: none;
  }

  .ds-sheet__backdrop {
    position: absolute;
    inset: 0;
    background: var(--ds-scrim);
  }

  /* With viewport-fit=cover the sheet keeps clear of the notch, the status
     bar and the home indicator, like the app frame (shell.css). Physical
     on purpose (D9): the panel slides in from the right edge, so its
     rounded corners and its bleed stay on the left. */
  .ds-sheet__panel {
    position: relative;
    width: min(100%, var(--ds-sheet-width, 560px));
    height: 100%;
    display: flex;
    flex-direction: column;
    padding-top: env(safe-area-inset-top);
    border-radius: calc(var(--ds-sheet-radius, var(--ds-radius-dialog)) * var(--ds-shape, 1)) 0 0 calc(var(--ds-sheet-radius, var(--ds-radius-dialog)) * var(--ds-shape, 1));
    background: var(--ds-surface-overlay);
    /* Its own ink on its own surface (a widget without .ds-base). */
    color: var(--ds-text);
    box-shadow: var(--ds-elev-overlay);
    /* Invisible; forced colors paint it, so the sheet keeps its edge. */
    outline: 1px solid transparent;
  }

  /* Bleed: the spring carries the panel a little past its resting edge
     (about 3 % of the travel, at most 5 %: 36px of a 720px panel); this
     strip of its own background beyond the outer edge keeps the scrim from
     showing at the screen edge. Off screen at rest, clipped by the sheet. */
  .ds-sheet__panel::after {
    content: '';
    position: absolute;
    top: 0;
    bottom: 0;
    left: 100%;
    width: var(--ds-space-12);
    background: inherit;
    pointer-events: none;
  }

  .ds-sheet__panel--wide {
    width: min(100%, var(--ds-sheet-width-wide, 720px));
  }

  .ds-sheet[hidden] {
    display: none;
  }

  /* Only the panel lets clicks through while it leaves; the backdrop
     swallows them until the sheet is hidden or removed. */
  .ds-sheet--closing .ds-sheet__panel,
  .ds-sheet[data-state="closed"] .ds-sheet__panel {
    pointer-events: none;
  }

  /* State-driven (DS.overlay): transitions, so a reversal continues from
     the current value. A transition takes the timing of the state it moves
     to. The panel only slides (opaque, no fade); the scrim fades out over
     the panel's exit time, so both end together. */
  .ds-sheet[data-state] .ds-sheet__backdrop {
    animation: none;
    transition: opacity var(--ds-dur-medium) var(--ds-ease-in-out);
  }

  .ds-sheet[data-state] .ds-sheet__panel {
    animation: none;
    transition: translate var(--ds-dur-long) var(--ds-ease-spatial);
  }

  .ds-sheet[data-state="closed"] .ds-sheet__backdrop {
    opacity: 0;
    transition: opacity var(--ds-dur-base) var(--ds-ease-in-out);
  }

  .ds-sheet[data-state="closed"] .ds-sheet__panel {
    translate: var(--ds-distance-sheet) 0;
    transition: translate var(--ds-dur-base) var(--ds-ease-exit);
  }

  /* Keyframes: markup driven by hand, without data-state. The full-width
     slide of the opaque panel is the one exit without ds-fade-out: it
     leaves the screen. */
  .ds-sheet:not([data-state]) .ds-sheet__backdrop {
    animation: ds-fade-in var(--ds-dur-medium) var(--ds-ease-in-out) backwards;
  }

  .ds-sheet:not([data-state]) .ds-sheet__panel {
    --ds-motion-distance: var(--ds-distance-sheet);
    animation: ds-shift-in var(--ds-dur-long) var(--ds-ease-spatial) backwards;
  }

  .ds-sheet--closing:not([data-state]) .ds-sheet__backdrop {
    animation: ds-fade-out var(--ds-dur-base) var(--ds-ease-in-out) forwards;
  }

  .ds-sheet--closing:not([data-state]) .ds-sheet__panel {
    --ds-motion-distance: var(--ds-distance-sheet);
    animation: ds-shift-out var(--ds-dur-base) var(--ds-ease-exit) forwards;
  }

  /* A native sheet driven by hand: the same transitions, keyed on [open].
     display and overlay step at the end of the exit, so close() animates
     and Chromium keeps the sheet in the top layer meanwhile. Under
     DS.overlay only overlay steps: --closing keeps display, and the sheet
     must not linger, invisible, once it is done. */
  dialog.ds-sheet:not([data-state]) {
    transition:
      display var(--ds-dur-base) allow-discrete,
      overlay var(--ds-dur-base) allow-discrete;
  }

  dialog.ds-sheet[data-state] {
    transition: overlay var(--ds-dur-base) allow-discrete;
  }

  dialog.ds-sheet:not([data-state]) .ds-sheet__backdrop {
    animation: none;
    transition: opacity var(--ds-dur-medium) var(--ds-ease-in-out);
  }

  dialog.ds-sheet:not([data-state]) .ds-sheet__panel {
    animation: none;
    transition: translate var(--ds-dur-long) var(--ds-ease-spatial);
  }

  dialog.ds-sheet:not([data-state]):not([open]) .ds-sheet__backdrop {
    opacity: 0;
    transition: opacity var(--ds-dur-base) var(--ds-ease-in-out);
  }

  dialog.ds-sheet:not([data-state]):not([open]) .ds-sheet__panel {
    translate: var(--ds-distance-sheet) 0;
    transition: translate var(--ds-dur-base) var(--ds-ease-exit);
  }

  /* Where the sheet enters from when showModal() shows it (a rule of its
     own, not nested). */
  @starting-style {
    dialog.ds-sheet[open]:not([data-state]) .ds-sheet__backdrop {
      opacity: 0;
    }

    dialog.ds-sheet[open]:not([data-state]) .ds-sheet__panel {
      translate: var(--ds-distance-sheet) 0;
    }
  }

  /* Header: 64px; its hairline shows only while the body scrolls under it. */
  .ds-sheet__head {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--ds-space-3);
    flex-shrink: 0;
    min-height: calc(var(--ds-sheet-head-height, 64px) + var(--ds-density, 0) * 4px);
    padding:
      calc(var(--ds-space-3) + var(--ds-density, 0) * 2px)
      max(var(--ds-space-3), env(safe-area-inset-right))
      calc(var(--ds-space-3) + var(--ds-density, 0) * 2px)
      calc(var(--ds-sheet-padding, var(--ds-space-6)) + var(--ds-density, 0) * 2px);
  }

  .ds-sheet__head::after {
    content: '';
    position: absolute;
    inset-inline: 0;
    bottom: 0;
    height: 1px;
    background: var(--ds-line);
    opacity: 0;
    transition: opacity var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  .ds-sheet__panel[data-scrolled] .ds-sheet__head::after {
    opacity: 1;
  }

  /* Where scroll timelines exist, the hairline follows the body's scroll
     position itself (over the first --ds-space-2), and data-scrolled, the
     fallback, changes nothing. The head is the body's sibling, so the body
     names its timeline and the panel widens the scope to the head.
     ds-scroll-fade names both ends, so a body without overflow (an
     inactive timeline) keeps the hairline's own opacity 0;
     animation-timeline comes after the shorthand, which resets it. */
  @supports (timeline-scope: none) {
    .ds-sheet__panel {
      timeline-scope: --ds-sheet-scroll;
    }

    .ds-sheet__body {
      scroll-timeline: --ds-sheet-scroll block;
    }

    .ds-sheet__head::after {
      animation: ds-scroll-fade linear both;
      animation-timeline: --ds-sheet-scroll;
      animation-range: 0 var(--ds-space-2);
    }
  }

  /* The title wraps: a long record name stays readable (2.0). */
  .ds-sheet__title {
    margin: 0;
    min-width: 0;
    color: var(--ds-text);
    font: var(--ds-font-title);
    letter-spacing: 0;
    overflow-wrap: anywhere;
  }

  .ds-sheet__head > .ds-btn {
    flex-shrink: 0;
  }

  /* Title and subtitle as one block that takes the head's free width. */
  .ds-sheet__heading {
    display: grid;
    flex: 1;
    min-width: 0;
  }

  .ds-sheet__subtitle {
    margin: 0;
    overflow: hidden;
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
    font-variant-numeric: tabular-nums;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .ds-sheet__subtitle:empty {
    display: none;
  }

  .ds-sheet__body {
    position: relative;
    flex: 1;
    overflow-y: auto;
    scrollbar-width: thin;
    scrollbar-color: var(--ds-line-2) transparent;
    padding:
      var(--ds-space-2)
      max(calc(var(--ds-sheet-padding, var(--ds-space-6)) + var(--ds-density, 0) * 2px), env(safe-area-inset-right))
      calc(var(--ds-space-8) + env(safe-area-inset-bottom))
      calc(var(--ds-sheet-padding, var(--ds-space-6)) + var(--ds-density, 0) * 2px);
    display: flex;
    flex-direction: column;
    gap: var(--ds-space-3);
    outline-offset: 0;
    transition: outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  /* A snackbar shown inside the sheet (toast.css) that stays until closed:
     the body keeps room for it at its end on top of its own padding
     (data-toast-reserve and --ds-toast-reserve, set by toast(), or by the
     page with reserve: false), so the sheet's actions can scroll clear of
     it. */
  .ds-sheet__body[data-toast-reserve] {
    padding-bottom: calc(var(--ds-space-8) + env(safe-area-inset-bottom) + var(--ds-toast-reserve, 0px));
    scroll-padding-bottom: var(--ds-toast-reserve, 0px);
  }

  /* A lone button keeps its own width (a column would stretch it). */
  .ds-sheet__body > .ds-btn {
    align-self: flex-start;
  }

  /* The sheet's actions: at the end, wrapping, above a hairline. The foot
     holds the safe area, so the body above it ends with its normal gap. */
  .ds-sheet__foot {
    display: flex;
    flex-shrink: 0;
    flex-wrap: wrap;
    justify-content: flex-end;
    align-items: center;
    gap: var(--ds-space-2);
    padding:
      calc(var(--ds-space-3) + var(--ds-density, 0) * 2px)
      max(calc(var(--ds-sheet-padding, var(--ds-space-6)) + var(--ds-density, 0) * 2px), env(safe-area-inset-right))
      calc(var(--ds-space-3) + var(--ds-density, 0) * 2px + env(safe-area-inset-bottom))
      calc(var(--ds-sheet-padding, var(--ds-space-6)) + var(--ds-density, 0) * 2px);
    border-top: var(--ds-sheet-foot-border, 1px solid var(--ds-line));
  }

  .ds-sheet__foot > .ds-meta:first-child {
    margin-inline-end: auto;
  }

  .ds-sheet__foot:empty {
    display: none;
  }

  .ds-sheet__body:has(+ .ds-sheet__foot:not(:empty)) {
    padding-bottom: var(--ds-space-3);
  }

  .ds-sheet__body[data-toast-reserve]:has(+ .ds-sheet__foot:not(:empty)) {
    padding-bottom: calc(var(--ds-space-3) + var(--ds-toast-reserve, 0px));
  }

  /* A tab stop for scrolling: the ring only for the keyboard, inside the
     edge so the panel does not clip it; it rests on the edge and snaps
     inward like every inset ring (.ds-sheet__body above). */
  .ds-sheet__body:focus {
    outline: none;
  }

  .ds-sheet__body:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: calc(-1 * var(--ds-focus-width));
  }

  /* Another record in an open sheet (DS.motion.transition() writes
     data-ds-vt on <html> while it runs): the body is a group of its own and
     takes the view's fade-through or shared axis (motion.css); head and
     panel stay still. Named only while a transition runs, and only in an
     open modal sheet (DS.overlay's data-state, a native sheet shown by
     hand, a div sheet shown by hand), never while it leaves: a group
     escapes the clip of the scroller around it, so a sheet shown inline
     in a page would paint over the top bar, and two named bodies would
     abort the transition. */
  .ds-theme[data-ds-vt] .ds-sheet[data-state="open"] .ds-sheet__body,
  .ds-theme[data-ds-vt] dialog.ds-sheet[open]:not([data-state], .ds-sheet--closing) .ds-sheet__body,
  .ds-theme[data-ds-vt] .ds-sheet[aria-modal="true"]:not([hidden], [data-state], .ds-sheet--closing) .ds-sheet__body {
    view-transition-name: ds-sheet-body;
  }

  /* ── Resizing (3.0) ───────────────────────────────── */

  /* The panel's width: a remembered or dragged width (--ds-sheet-size,
     written by DS.sheet) wins over the hook. */
  .ds-sheet > .ds-sheet__panel:has(> .ds-sheet__resize) {
    width: min(100%, var(--ds-sheet-size, var(--ds-sheet-width, 560px)));
  }

  .ds-sheet > .ds-sheet__panel--wide:has(> .ds-sheet__resize) {
    width: min(100%, var(--ds-sheet-size, var(--ds-sheet-width-wide, 720px)));
  }

  /* The separator on the panel's inner edge: a hit strip across the
     edge, at least the touch target under .ds-touch, with a pill in its
     middle that shows on hover, focus and while it drags. */
  .ds-sheet__resize {
    --_hit: max(var(--ds-target-min, 0px), var(--ds-space-4));
    position: absolute;
    inset-block: 0;
    inset-inline-start: calc(var(--_hit) / -2);
    z-index: var(--ds-z-raised);
    inline-size: var(--_hit);
    display: grid;
    place-items: center;
    cursor: col-resize;
    touch-action: none;
    outline-offset: 0;
    transition: outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-sheet__resize::before {
    content: '';
    inline-size: var(--ds-space-1);
    block-size: var(--ds-space-12);
    border-radius: calc(var(--ds-space-1) / 2);
    background: var(--ds-outline);
    opacity: 0;
    transition:
      opacity var(--ds-dur-fast) var(--ds-ease-in-out),
      background-color var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  @media (hover: hover) {
    .ds-sheet__resize:hover::before {
      opacity: 1;
    }
  }

  /* No hover to find it by: the pill stays, so a finger sees what to drag. */
  @media (hover: none) {
    .ds-sheet__resize::before {
      opacity: 1;
    }
  }

  .ds-sheet__resize:focus-visible::before,
  .ds-sheet__panel[data-resizing] > .ds-sheet__resize::before {
    opacity: 1;
    background: var(--ds-primary);
  }

  /* The ring on the pill, solid from the first frame (inset: the strip
     sits on the panel's edge). */
  .ds-sheet__resize:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: calc(-1 * var(--ds-focus-width));
  }

  .ds-sheet__panel[data-resizing] {
    user-select: none;
  }

  /* The modal sheet slides in from the right edge: its separator sits on
     the panel's left edge whatever the direction. */
  .ds-sheet .ds-sheet__resize {
    left: calc(var(--_hit) / -2);
    right: auto;
  }

  /* ── Docked panels (3.0): push and inspector ───────── */

  /* The region a docked panel shares: the page's content in
     .ds-sheet__main, the panel at its inline end. Narrower than
     --ds-sheet-docked-break (a container query), the panel lies over the
     main column instead of narrowing it. */
  .ds-sheet__layout {
    position: relative;
    display: flex;
    align-items: stretch;
    min-block-size: 0;
    container: ds-sheet-layout / inline-size;
  }

  .ds-sheet__main {
    flex: 1 1 0;
    min-inline-size: 0;
  }

  /* Docked: no scrim, no radius, a hairline instead of the shadow; its
     width opens from 0 (the content beside it narrows, on --ds-ease-out:
     a size that pushes never overshoots) while its parts keep their
     width and are uncovered from the inline end. It sticks in view in a
     taller page. */
  .ds-sheet__panel--push,
  .ds-sheet__panel--inspector {
    --_w: var(--ds-sheet-size, var(--ds-sheet-docked-width, 400px));
    position: sticky;
    inset-block-start: 0;
    flex: none;
    inline-size: calc(min(var(--_w), 100%) * var(--ds-sheet-reveal));
    block-size: auto;
    max-block-size: 100dvh;
    padding-top: 0;
    align-items: flex-end;
    overflow: clip;
    border-radius: 0;
    border-inline-start: var(--ds-sheet-docked-border, 1px solid var(--ds-line));
    background: var(--ds-surface);
    box-shadow: none;
  }

  .ds-sheet__panel--push::after,
  .ds-sheet__panel--inspector::after {
    display: none;
  }

  .ds-sheet__panel--push > *,
  .ds-sheet__panel--inspector > * {
    inline-size: min(var(--_w), 100cqi);
    max-inline-size: none;
  }

  .ds-sheet__panel--push > .ds-sheet__resize,
  .ds-sheet__panel--inspector > .ds-sheet__resize {
    inline-size: var(--_hit);
  }

  .ds-sheet__panel[hidden],
  .ds-sheet__panel--push[hidden],
  .ds-sheet__panel--inspector[hidden] {
    display: none;
  }

  .ds-sheet__panel--push[data-state],
  .ds-sheet__panel--inspector[data-state] {
    transition: --ds-sheet-reveal var(--ds-dur-long) var(--ds-ease-out);
  }

  .ds-sheet__panel--push[data-state="closed"],
  .ds-sheet__panel--inspector[data-state="closed"] {
    --ds-sheet-reveal: 0;
    pointer-events: none;
    transition: --ds-sheet-reveal var(--ds-dur-base) var(--ds-ease-exit);
  }

  /* A drag follows the pointer, so the width does not glide meanwhile. */
  .ds-sheet__panel--push[data-resizing],
  .ds-sheet__panel--inspector[data-resizing] {
    transition: none;
  }

  /* The separator must stay inside the clip of the panel. */
  .ds-sheet__panel--push > .ds-sheet__resize,
  .ds-sheet__panel--inspector > .ds-sheet__resize {
    inset-inline-start: 0;
  }

  .ds-sheet__panel--push .ds-sheet__head,
  .ds-sheet__panel--inspector .ds-sheet__head {
    min-height: calc(var(--ds-sheet-head-height, 64px) - var(--ds-space-2) + var(--ds-density, 0) * 4px);
  }

  .ds-sheet__panel--push .ds-sheet__body,
  .ds-sheet__panel--inspector .ds-sheet__body {
    padding-bottom: var(--ds-space-6);
  }

  /* Short of room, the docked panel lies over the main column (non-modal,
     its own elevation), the whole width on a phone. */
  @container ds-sheet-layout (max-width: 720px) {
    .ds-sheet__panel--push,
    .ds-sheet__panel--inspector {
      position: absolute;
      inset-block: 0;
      inset-inline-end: 0;
      max-block-size: none;
      z-index: var(--ds-z-raised);
      box-shadow: var(--ds-elev-overlay);
    }
  }

  @container ds-sheet-layout (max-width: 480px) {
    .ds-sheet__panel--push,
    .ds-sheet__panel--inspector {
      --_w: 100cqi;
      border-inline-start: 0;
    }

    .ds-sheet__panel--push > .ds-sheet__resize,
    .ds-sheet__panel--inspector > .ds-sheet__resize {
      display: none;
    }
  }

  @media (max-width: 600px) {
    .ds-sheet__panel,
    .ds-sheet__panel--wide,
    .ds-sheet > .ds-sheet__panel:has(> .ds-sheet__resize) {
      width: 100%;
      border-radius: 0;
    }

    .ds-sheet .ds-sheet__resize {
      display: none;
    }

    /* Phones: the sheet rises from the bottom and falls back down; the
       bleed sits below it. As tall as the screen, it rises on
       --ds-ease-out (every path), so the spring's overshoot never cuts
       off its head at the top edge; the exit keeps its tokens. */
    .ds-sheet__panel::after {
      top: 100%;
      inset-inline: 0;
      bottom: auto;
      width: auto;
      height: var(--ds-space-12);
    }

    .ds-sheet[data-state="open"] .ds-sheet__panel {
      transition: translate var(--ds-dur-long) var(--ds-ease-out);
    }

    .ds-sheet[data-state="closed"] .ds-sheet__panel {
      translate: 0 var(--ds-distance-sheet);
    }

    .ds-sheet:not([data-state]) .ds-sheet__panel {
      --ds-motion-distance: var(--ds-distance-sheet);
      animation: ds-lift-in var(--ds-dur-long) var(--ds-ease-out) backwards;
    }

    .ds-sheet--closing:not([data-state]) .ds-sheet__panel {
      --ds-motion-distance: var(--ds-distance-sheet);
      animation: ds-drop-out var(--ds-dur-base) var(--ds-ease-exit) forwards;
    }

    .ds-sheet__head {
      padding-left: max(var(--ds-space-4), env(safe-area-inset-left));
    }

    .ds-sheet__body {
      padding-inline: max(var(--ds-space-4), env(safe-area-inset-left)) max(var(--ds-space-4), env(safe-area-inset-right));
    }

    .ds-sheet__foot {
      padding-inline: max(var(--ds-space-4), env(safe-area-inset-left)) max(var(--ds-space-4), env(safe-area-inset-right));
    }
  }

  @media (max-width: 600px) {
    dialog.ds-sheet[open]:not([data-state]) .ds-sheet__panel {
      transition: translate var(--ds-dur-long) var(--ds-ease-out);
    }

    dialog.ds-sheet:not([data-state]):not([open]) .ds-sheet__panel {
      translate: 0 var(--ds-distance-sheet);
    }
  }

  @media (max-width: 600px) {
    @starting-style {
      dialog.ds-sheet[open]:not([data-state]) .ds-sheet__panel {
        translate: 0 var(--ds-distance-sheet);
      }
    }
  }

  @media (forced-colors: active) {
    .ds-sheet__resize::before {
      background: CanvasText;
      opacity: 1;
    }

    .ds-sheet__resize:focus-visible::before,
    .ds-sheet__panel[data-resizing] > .ds-sheet__resize::before {
      background: Highlight;
    }
  }

  @media print {
    .ds-sheet,
    .ds-sheet__panel--push,
    .ds-sheet__panel--inspector,
    .ds-sheet__resize {
      display: none;
    }
  }
}

/* ── components/dialog/dialog.css ── */
/*
 * Dialog (confirmation): a modal box over the whole window, above an open
 * side sheet (it may ask from inside one) and below snackbars. The scrim
 * fades in while the box fades, grows from just below full size and rises
 * a little on the spatial spring, from an origin towards its opener. It
 * leaves faster than it came, the same way back, accelerating. A close
 * taken back mid-way continues from where the box is.
 *
 * Native markup (preferred): showModal() makes the page inert and gives
 * the dialog its modal semantics, so the box carries no role.
 *
 *   <dialog class="ds-dialog" role="alertdialog" aria-labelledby="d-title" aria-describedby="d-text">
 *     <div class="ds-dialog__backdrop" data-ds-close></div>
 *     <div class="ds-dialog__box">
 *       <h2 class="ds-dialog__title" id="d-title">Delete 3 devices?</h2>
 *       <p class="ds-dialog__text" id="d-text">They are removed for everyone.</p>
 *       <div class="ds-dialog__actions">
 *         <button class="ds-btn ds-btn--text" type="button" data-ds-close autofocus>Cancel</button>
 *         <button class="ds-btn ds-btn--filled" type="button">Delete devices</button>
 *
 * Content taller than the window (a form, a long list): the body scrolls,
 * title and actions stay. A body with nothing focusable that scrolls is a
 * tab stop with a name.
 *
 *   <dialog class="ds-dialog ds-dialog--lg" aria-labelledby="p-title">
 *     <div class="ds-dialog__backdrop" data-ds-close></div>
 *     <div class="ds-dialog__box">
 *       <h2 class="ds-dialog__title" id="p-title">Choose an owner</h2>
 *       <div class="ds-dialog__body" [tabindex="0" role="region" aria-label="Owners"]> ... </div>
 *       <div class="ds-dialog__actions"> ... </div>
 *
 * Full screen (a task that needs the whole phone screen): a head with a
 * close icon button, the title and an optional text button at the end.
 *
 *   <dialog class="ds-dialog ds-dialog--full-narrow" aria-labelledby="f-title">
 *     <div class="ds-dialog__backdrop" data-ds-close></div>
 *     <div class="ds-dialog__box">
 *       <div class="ds-dialog__head">
 *         <button class="ds-btn ds-btn--quiet ds-btn--icon" type="button" aria-label="Close" data-ds-close>(close)</button>
 *         <h2 class="ds-dialog__title" id="f-title">New ticket</h2>
 *         <button class="ds-btn ds-btn--text" type="button">Save</button>
 *       </div>
 *       <div class="ds-dialog__body"> ... </div>
 *
 * Action sheet (the actions of a row on a phone): the menu's items, full
 * bleed, in a box at the bottom edge.
 *
 *   <dialog class="ds-dialog ds-dialog--bottom" aria-labelledby="a-title">
 *     <div class="ds-dialog__backdrop" data-ds-close></div>
 *     <div class="ds-dialog__box">
 *       <h2 class="ds-dialog__title" id="a-title">LAPTOP-0042</h2>
 *       <div class="ds-dialog__list">
 *         <button class="ds-menu__item" type="button">(pencil) <span class="ds-menu__label">Edit</span></button>
 *
 * Non-modal (3.0): the box alone, no frame and no backdrop, floating at
 * the end of the window; the page stays usable. DS.overlay opens it as a
 * non-modal layer (no trap, no inert, no scroll lock); DS.dialog moves focus
 * in when it opens.
 *
 *   <section class="ds-dialog__box ds-dialog__box--modeless" role="dialog" aria-labelledby="m-title" hidden>
 *     <div class="ds-dialog__head">
 *       <h2 class="ds-dialog__title" id="m-title">Export running</h2>
 *       <button class="ds-btn ds-btn--quiet ds-btn--icon" type="button" aria-label="Close" data-ds-close>(close)</button>
 *     </div>
 *     <div class="ds-dialog__body"> ... </div>
 *
 * What a question is about (confirm({ lines, facts })):
 * <ul class="ds-dialog__lines"><li>LAPTOP-0042</li> ...</ul> and
 * <dl class="ds-dialog__facts"><div><dt>Ticket</dt><dd>#1042</dd></div> ...</dl>.
 *
 * Form dialog: the box is the <form>, so Enter submits and the browser's
 * validation runs; DS.dialog (js/dialog.js) sends ds:submit and closes it.
 *
 *   <dialog class="ds-dialog" aria-labelledby="n-title">
 *     <div class="ds-dialog__backdrop" data-ds-close></div>
 *     <form class="ds-dialog__box" data-ds-dialog-form>
 *       <h2 class="ds-dialog__title" id="n-title">Rename</h2>
 *       <div class="ds-dialog__body"> ... fields ... </div>
 *       <div class="ds-dialog__actions">
 *         <button class="ds-btn ds-btn--text" type="button" data-ds-close>Cancel</button>
 *         <button class="ds-btn ds-btn--filled" type="submit">
 *           <span class="ds-btn__faces"><span class="ds-btn__face">Save</span>
 *             <span class="ds-btn__face ds-btn__face--busy" aria-hidden="true"><span class="ds-spinner ds-spinner--ink ds-sm"></span>Save</span></span>
 *         </button>
 *
 * Div markup (fallback): the same tree in a div; the box takes the role.
 *
 *   <div class="ds-dialog" hidden>
 *     <div class="ds-dialog__backdrop" data-ds-close></div>
 *     <div class="ds-dialog__box" role="alertdialog" aria-modal="true" aria-labelledby="d-title" aria-describedby="d-text">
 *
 * Open and close both with DS.overlay.open(dialog, { opener }) and
 * DS.overlay.close(dialog) (js/overlay.js), or declaratively with
 * [data-ds-open="#id"] on a button: focus, trap, Escape, the scroll lock and
 * data-state. [data-ds-close] (its 2.x name still works) closes it. The motion runs on transitions keyed on
 * data-state ("closed", then "open"; "closed" again to leave), so a
 * reversal continues from the current value in every engine. The scrim is
 * the __backdrop child; a native dialog's ::backdrop stays transparent.
 *
 *   .ds-dialog--hidden     not shown (or use the hidden attribute; it works
 *                          without .ds-base)
 *   .ds-dialog--closing    the exit by hand, without data-state (keyframes):
 *                          release the trap and focus the opener first, add
 *                          the class, and after DS.motion.settled(box) hide
 *                          the dialog and remove the class in the same task.
 *                          On a native dialog it keeps the element shown and
 *                          stacked (position: fixed, --ds-z-dialog) after
 *                          close() took it out of the top layer. The box
 *                          ignores the pointer during the exit, the backdrop
 *                          still catches clicks, so nothing reaches the page
 *                          under it.
 *   .ds-dialog--nested     over another open modal (a sheet, the modal
 *                          drawer): the lighter --ds-scrim-nested, so the
 *                          scrims add up to about 43%. DS.overlay sets it.
 *   .ds-dialog--contained  covers its positioned container instead of the
 *                          window (div markup only: a dialog inside an
 *                          embedded panel); in a container taller than
 *                          the window the box stays in the visible part
 *                          (position: sticky)
 *   .ds-dialog--sm         a narrower box (--ds-dialog-width-sm, 320px): a
 *                          short question
 *   .ds-dialog--lg         a wider box (--ds-dialog-width-lg, 560px): a list,
 *                          a form, a confirmation with a field. Its 2.x
 *                          name, ending in --wide, still works
 *   .ds-dialog--xl         the widest box (--ds-dialog-width-xl, 720px)
 *   .ds-dialog--full       the box fills the window (no padding around it,
 *                          radius --ds-dialog-full-radius, safe areas on
 *                          head and actions); it rises by
 *                          --ds-distance-lg on the spring over
 *                          --ds-dur-long with the fade, no scale, and
 *                          leaves dropping back in --ds-dur-base
 *   .ds-dialog--full-narrow  the same at 600px and below, a normal dialog
 *                          above
 *   .ds-dialog--scroll-outside  the window scrolls the whole box, which
 *                          keeps its content's height (a long read):
 *                          the frame scrolls, the scrim stays
 *   .ds-dialog--bottom     the action sheet: the box sits at the bottom edge
 *                          and rises its full height (--ds-distance-sheet)
 *                          on the spring over --ds-dur-long with the fade;
 *                          it drops back in --ds-dur-base
 *
 * Parts: .ds-dialog__body (with a title above and actions below, it is the
 * one part that scrolls: the box turns into a flex column; it shows a top
 * hairline while scrolled, data-scrolled on the box, which DS.overlay.open()
 * keeps through DS.dom.watchScrolled(); at a window 320px high or less the
 * box scrolls instead, WCAG 1.4.10; empty, its sentinel aside, it takes no
 * room, nor do empty actions), .ds-dialog__head (the full-screen top bar:
 * a close icon button with data-ds-close, the title, an optional text button)
 * and .ds-dialog__list (.ds-menu__item rows full bleed in the box;
 * DS.overlay moves focus through them with the arrow keys). A lone .ds-btn
 * directly in the body keeps its own width.
 *
 * The on-screen keyboard: with DS.dom.followViewport() on the page, every
 * dialog keeps clear of it (--ds-keyboard-inset, 0px without it): a
 * centred box centres in the window above the keyboard, a full-screen box
 * (--full, --full-narrow on phones) ends at its top edge, the action sheet
 * (--bottom) sits on it, a contained box sticks above it; the scrim keeps
 * covering the whole window. A box taller than the room scrolls its body.
 *
 * Fallback focus: a box that took focus because nothing inside could
 * (tabindex="-1", set by DS.overlay) shows no ring.
 *
 * At 600px and below the box moves on --ds-ease-out: a box nearly as wide
 * as the window never overshoots past it.
 *
 * The main action names the consequence. The one red button: a destructive
 * confirmation's filled button in the error tone (.ds-tone-error, D10);
 * DS.overlay.confirm({ destructive: true }) sets it.
 *
 * Options (the md has the table): density changes the box's padding, the
 * gap of its parts and the height of the full-screen head; shape multiplies
 * the radius; the widths above are the dialog's sizes, because a size class
 * on it would also change every control inside. Controls inside follow the
 * options around them as anywhere, and .ds-touch reaches them.
 *
 * Forced colours: the transparent border of the box becomes its edge (the
 * full-screen box is the window and needs none); the scrim goes with the
 * backdrop colour.
 *
 * Hooks: --ds-dialog-width (400px), --ds-dialog-width-sm (320px),
 * --ds-dialog-width-lg (560px), --ds-dialog-width-xl (720px),
 * --ds-dialog-padding
 * (--ds-space-6), --ds-dialog-radius (--ds-radius-dialog),
 * --ds-dialog-head-height (56px), --ds-dialog-height (auto; set it so a filtered list does not make the
 * box jump; capped by the window), --ds-dialog-full-radius (0),
 * --ds-dialog-border (an invisible hairline that forced colors paint, so
 * the dialog keeps its edge once shadow and scrim are gone; the full
 * screen dialog needs none), --ds-dialog-shadow, --ds-dialog-scrim
 * (--ds-scrim), --ds-dialog-modeless-inset (--ds-space-4, phones
 * --ds-space-2: the gap of a non-modal box to the window's edges).
 *
 * Print: an open dialog is not printed (it is not the page).
 *
 * At the floor, used directly: @starting-style and allow-discrete
 * transitions (a native dialog driven by hand, showModal() and close() of
 * the page without DS.overlay, plays the same transitions, also on close();
 * the overlay property, where the engine has it, keeps it in the top layer
 * through every exit).
 *
 * Progressive:
 * - scrollbar-color and scrollbar-width (a thin, quiet scrollbar on the
 *   body): without them the platform scrollbar shows.
 */

@layer ds.components.dialog {
  .ds-dialog {
    position: fixed;
    inset: 0;
    z-index: var(--ds-z-dialog);
    display: grid;
    place-items: center;
    /* Out of flow: no rhythm margin from a parent card (.ds-card > * + *)
       pushes the cover off its container or the window. */
    margin: 0;
    padding: var(--ds-space-4);
    /* The on-screen keyboard (DS.dom.followViewport() writes its height)
       covers the bottom of the window, not of the layout: the box centres
       in what is left above it, and the scrim still covers it all. */
    padding-bottom: calc(var(--ds-space-4) + var(--ds-keyboard-inset, 0px));
  }

  /* A native <dialog> loses the UA box: it is the same full-window grid
     as the div, and the box inside is the surface. */
  dialog.ds-dialog {
    width: auto;
    height: auto;
    max-width: none;
    max-height: none;
    margin: 0;
    border: 0;
    background: transparent;
    color: inherit;
    overflow: visible;
  }

  dialog.ds-dialog::backdrop {
    background: transparent;
  }

  /* display: grid above outranks the UA rule that hides a closed dialog.
     --closing keeps it shown while its exit plays outside the top layer;
     data-state="open" keeps it shown when the page closes it natively
     (close(), a <form method="dialog">), until the close event, a task
     later, starts the exit from where it stands. */
  dialog.ds-dialog:not([open]):not(.ds-dialog--closing):not([data-state="open"]) {
    display: none;
  }

  .ds-dialog--contained {
    position: absolute;
    z-index: var(--ds-z-popover);
    /* It covers its container, not the window: the keyboard is the
       sticky box's concern (below). */
    padding-bottom: var(--ds-space-4);
  }

  /* The container may be taller than the window (a long list, a grid cell
     the host stretches): the box sticks inside the visible part instead of
     centring below the fold, and stays centred when the container fits. A
     box taller than the window scrolls inside it. */
  .ds-dialog--contained .ds-dialog__box {
    position: sticky;
    top: var(--ds-space-4);
    bottom: calc(var(--ds-space-4) + var(--ds-keyboard-inset, 0px));
    max-height: min(100%, calc(100dvh - 2 * var(--ds-space-4) - var(--ds-keyboard-inset, 0px)));
  }

  .ds-dialog--hidden,
  .ds-dialog[hidden] {
    display: none;
  }

  .ds-dialog--nested {
    --ds-dialog-scrim: var(--ds-scrim-nested);
  }

  .ds-dialog__backdrop {
    position: absolute;
    inset: 0;
    background: var(--ds-dialog-scrim, var(--ds-scrim));
  }

  .ds-dialog__box {
    position: relative;
    width: min(var(--ds-dialog-width, 400px), 100%);
    max-height: 100%;
    overflow-y: auto;
    padding: calc(var(--ds-dialog-padding, var(--ds-space-6)) + var(--ds-density, 0) * 2px);
    display: grid;
    gap: calc(var(--ds-space-4) + var(--ds-density, 0) * 2px);
    border: var(--ds-dialog-border, 1px solid transparent);
    border-radius: calc(var(--ds-dialog-radius, var(--ds-radius-dialog)) * var(--ds-shape, 1));
    background: var(--ds-surface-overlay);
    box-shadow: var(--ds-dialog-shadow, var(--ds-elev-overlay));
    /* Its own ink on its own surface (a widget without .ds-base). */
    color: var(--ds-text);
    text-align: start;
  }

  /* Only the box lets clicks through while it leaves; the backdrop swallows
     them until the dialog is hidden or removed. */
  .ds-dialog--closing .ds-dialog__box,
  .ds-dialog[data-state="closed"] .ds-dialog__box {
    pointer-events: none;
  }

  /* State-driven (DS.overlay): transitions, so a reversal continues from
     the current value. A transition takes the timing of the state it moves
     to: the entrance from these rules, the exit from the closed ones. The
     opacity is opaque within --ds-dur-fast, before the spring has settled. */
  .ds-dialog[data-state] .ds-dialog__backdrop {
    animation: none;
    transition: opacity var(--ds-dur-medium) var(--ds-ease-in-out);
  }

  .ds-dialog[data-state] .ds-dialog__box {
    animation: none;
    transform-origin: var(--ds-motion-origin, 50% 50%);
    transition:
      opacity var(--ds-dur-fast) var(--ds-ease-in-out),
      scale var(--ds-dur-slow) var(--ds-ease-spatial),
      translate var(--ds-dur-slow) var(--ds-ease-spatial);
  }

  .ds-dialog[data-state="closed"] .ds-dialog__backdrop {
    opacity: 0;
    transition: opacity var(--ds-dur-base) var(--ds-ease-in-out);
  }

  .ds-dialog[data-state="closed"] .ds-dialog__box {
    opacity: 0;
    scale: var(--ds-scale-enter);
    translate: 0 var(--ds-distance-sm);
    transition:
      opacity var(--ds-dur-base) var(--ds-ease-in-out),
      scale var(--ds-dur-base) var(--ds-ease-exit),
      translate var(--ds-dur-base) var(--ds-ease-exit);
  }

  /* Keyframes: markup driven by hand, without data-state. The exit mirrors
     the entrance, movement-only plus the fade. The box rises the same
     --ds-distance-sm as on the state path; the keyframes keep the
     --ds-dur-medium of the hand path (docs/motion.md rule 3). */
  .ds-dialog:not([data-state]) .ds-dialog__backdrop {
    animation: ds-fade-in var(--ds-dur-medium) var(--ds-ease-in-out) backwards;
  }

  .ds-dialog:not([data-state]) .ds-dialog__box {
    --ds-motion-distance: var(--ds-distance-sm);
    animation:
      ds-fade-in var(--ds-dur-medium) var(--ds-ease-in-out) backwards,
      ds-grow-in var(--ds-dur-medium) var(--ds-ease-spatial) backwards;
  }

  .ds-dialog--closing:not([data-state]) .ds-dialog__backdrop {
    animation: ds-fade-out var(--ds-dur-base) var(--ds-ease-in-out) forwards;
  }

  .ds-dialog--closing:not([data-state]) .ds-dialog__box {
    --ds-motion-distance: var(--ds-distance-sm);
    animation:
      ds-fade-out var(--ds-dur-base) var(--ds-ease-in-out) forwards,
      ds-shrink-out var(--ds-dur-base) var(--ds-ease-exit) forwards;
  }

  /* A native dialog driven by hand: the same transitions, keyed on [open].
     display and overlay step at the end of the exit, so close() animates
     and Chromium keeps the dialog in the top layer meanwhile. Under
     DS.overlay only overlay steps: --closing keeps display, and the dialog
     must not linger, invisible, once it is done. */
  dialog.ds-dialog:not([data-state]) {
    transition:
      display var(--ds-dur-base) allow-discrete,
      overlay var(--ds-dur-base) allow-discrete;
  }

  dialog.ds-dialog[data-state] {
    transition: overlay var(--ds-dur-base) allow-discrete;
  }

  dialog.ds-dialog:not([data-state]) .ds-dialog__backdrop {
    animation: none;
    transition: opacity var(--ds-dur-medium) var(--ds-ease-in-out);
  }

  dialog.ds-dialog:not([data-state]) .ds-dialog__box {
    animation: none;
    transition:
      opacity var(--ds-dur-fast) var(--ds-ease-in-out),
      scale var(--ds-dur-slow) var(--ds-ease-spatial),
      translate var(--ds-dur-slow) var(--ds-ease-spatial);
  }

  dialog.ds-dialog:not([data-state]):not([open]) .ds-dialog__backdrop {
    opacity: 0;
    transition: opacity var(--ds-dur-base) var(--ds-ease-in-out);
  }

  dialog.ds-dialog:not([data-state]):not([open]) .ds-dialog__box {
    opacity: 0;
    scale: var(--ds-scale-enter);
    translate: 0 var(--ds-distance-sm);
    transition:
      opacity var(--ds-dur-base) var(--ds-ease-in-out),
      scale var(--ds-dur-base) var(--ds-ease-exit),
      translate var(--ds-dur-base) var(--ds-ease-exit);
  }

  /* Where the dialog enters from when showModal() shows it (a rule of its
     own, not nested). */
  @starting-style {
    dialog.ds-dialog[open]:not([data-state]) .ds-dialog__backdrop {
      opacity: 0;
    }

    dialog.ds-dialog[open]:not([data-state]) .ds-dialog__box {
      opacity: 0;
      scale: var(--ds-scale-enter);
      translate: 0 var(--ds-distance-sm);
    }
  }

  .ds-dialog__title {
    margin: 0;
    color: var(--ds-text);
    font: var(--ds-font-title);
    letter-spacing: 0;
    overflow-wrap: anywhere;
  }

  .ds-dialog__text {
    margin: 0;
    color: var(--ds-text-2);
    font: var(--ds-font-body);
  }

  /* The title and its text belong together. */
  .ds-dialog__title + .ds-dialog__text {
    margin-top: calc(-1 * var(--ds-space-2));
  }

  .ds-dialog__actions {
    display: flex;
    flex-wrap: wrap;
    justify-content: flex-end;
    align-items: center;
    gap: var(--ds-space-2);
    margin-top: var(--ds-space-2);
  }

  /* Fallback focus (DS.overlay focuses the box when nothing inside can
     take it): focus is in the trap, but there is nothing to point at. */
  .ds-dialog__box[tabindex="-1"]:focus {
    outline: none;
  }

  /* As tall as the hook asks (a list that filters keeps its height),
     never taller than the window. */
  .ds-dialog__box {
    height: var(--ds-dialog-height, auto);
  }

  /* The sizes: the width of the box (a size class on the dialog would also
     change every control inside). */
  .ds-dialog--sm .ds-dialog__box {
    width: min(var(--ds-dialog-width-sm, 320px), 100%);
  }

  .ds-dialog--lg .ds-dialog__box {
    width: min(var(--ds-dialog-width-lg, 560px), 100%);
  }

  .ds-dialog--xl .ds-dialog__box {
    width: min(var(--ds-dialog-width-xl, 720px), 100%);
  }

  /* With a body, the box is a column whose only scrolling part is the
     body: title, head and actions stay in view. */
  .ds-dialog__box:has(> .ds-dialog__body) {
    display: flex;
    flex-direction: column;
  }

  /* Only the column's items read it (without a body the box is a grid). A
     :has() before a combinator would make Chromium restyle the whole page
     on any text change, so this rule has none. */
  .ds-dialog__box > * {
    flex-shrink: 0;
  }

  /* The 12px around its content give room to focus rings and the halos of
     checks, which the scroller would clip. The hairline at its top shows
     while it is scrolled (data-scrolled on the box); a border, so forced
     colours keep it. */
  .ds-dialog__box > .ds-dialog__body {
    flex: 1 1 auto;
  }

  .ds-dialog__body {
    position: relative;
    min-height: 0;
    display: grid;
    align-content: start;
    gap: var(--ds-space-4);
    margin: calc(-1 * var(--ds-space-3));
    padding: var(--ds-space-3);
    overflow-y: auto;
    overscroll-behavior: contain;
    scroll-padding-block: var(--ds-space-3);
    scrollbar-width: thin;
    scrollbar-color: var(--ds-line-2) transparent;
    border-top: 1px solid transparent;
    outline-offset: 0;
    transition:
      outline-offset var(--ds-dur-fast) var(--ds-ease-out),
      border-color var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  .ds-dialog__box[data-scrolled] > .ds-dialog__body {
    border-top-color: var(--ds-line);
  }

  /* A scrolling body with nothing focusable is a tab stop (tabindex="0",
     role="region" and a name): an inset ring that rests on the edge and
     snaps inward, never clipped by the scroller. */
  .ds-dialog__body:focus {
    outline: none;
  }

  .ds-dialog__body:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: calc(-1 * var(--ds-focus-width));
  }

  /* The sentinel of DS.dom.watchScrolled() (DS.overlay.open() adds it) comes first. */
  .ds-dialog__title + .ds-dialog__body > .ds-dialog__text:first-child,
  .ds-dialog__title + .ds-dialog__body > [data-ds-sentinel]:first-child + .ds-dialog__text {
    margin-top: calc(-1 * var(--ds-space-2));
  }

  /* A lone button keeps its own width (a grid item would stretch). */
  .ds-dialog__body > .ds-btn {
    justify-self: start;
  }

  /* An empty body, its sentinel aside, takes no room. "No child but the
     sentinel" rather than :only-child inside :has(): Firefox does not
     restyle that when rows are added after the sentinel. Text nodes are
     no children to a selector, so a body of bare text carries
     data-ds-text (DS.dom.watchScrolled()) and stays. */
  .ds-dialog__body:empty,
  .ds-dialog__body:not([data-ds-text]):has(> [data-ds-sentinel]):not(:has(> :not([data-ds-sentinel]))),
  .ds-dialog__actions:empty {
    display: none;
  }

  /* The full-screen top bar (M3): close, title, an optional text action.
     It reaches into the box's padding, so the icon button lines up with
     the content edge. */
  .ds-dialog__head {
    display: flex;
    align-items: center;
    gap: var(--ds-space-2);
    min-height: calc(var(--ds-dialog-head-height, 56px) + var(--ds-density, 0) * 4px);
    margin: calc(-1 * var(--ds-space-3)) calc(-1 * var(--ds-space-3)) 0;
  }

  .ds-dialog__head > .ds-dialog__title {
    flex: 1;
    min-width: 0;
  }

  .ds-dialog__head > .ds-btn {
    flex-shrink: 0;
  }

  /* An action sheet's rows: menu items, full bleed in the box. */
  .ds-dialog__list {
    display: flex;
    flex-direction: column;
    margin: 0 calc(-1 * (var(--ds-dialog-padding, var(--ds-space-6)) + var(--ds-density, 0) * 2px));
    padding: 0;
  }

  .ds-dialog__list + .ds-dialog__actions {
    margin-top: 0;
  }

  /* The whole window: no padding around the box, safe areas inside it;
     it ends above the on-screen keyboard. */
  .ds-dialog--full {
    padding: 0 0 var(--ds-keyboard-inset, 0px);
  }

  .ds-dialog--full .ds-dialog__box {
    --_pad: calc(var(--ds-dialog-padding, var(--ds-space-6)) + var(--ds-density, 0) * 2px);
    width: 100%;
    height: 100%;
    max-height: none;
    border-radius: calc(var(--ds-dialog-full-radius, 0px) * var(--ds-shape, 1));
    padding:
      0
      max(var(--_pad), env(safe-area-inset-right))
      max(var(--_pad), env(safe-area-inset-bottom))
      max(var(--_pad), env(safe-area-inset-left));
  }

  .ds-dialog--full .ds-dialog__head {
    margin: 0 calc(var(--ds-space-2) - var(--ds-dialog-padding, var(--ds-space-6)) - var(--ds-density, 0) * 2px);
    padding-top: env(safe-area-inset-top);
  }

  /* The action sheet: at the bottom edge, above the home indicator, or
     above the on-screen keyboard while it is up. */
  .ds-dialog--bottom {
    place-items: end center;
    padding-bottom: max(env(safe-area-inset-bottom), calc(var(--ds-space-4) + var(--ds-keyboard-inset, 0px)));
  }

  /* While it hosts a snackbar region: while the box would overlap the stack,
     the dialog keeps the stack's room at its bottom (toast() sets the
     attribute and the property), so the box re-centres above it (no motion:
     the room comes with the message). */
  .ds-dialog[data-toast-reserve] {
    padding-bottom: var(--ds-toast-reserve, var(--ds-space-4));
  }

  /* A window 320px high or less (a phone on its side with the keyboard):
     the box scrolls as one, so every part stays reachable (WCAG 1.4.10). */
  @media (max-height: 320px) {
    .ds-dialog__box:has(> .ds-dialog__body) {
      display: grid;
    }

    .ds-dialog__body {
      min-height: auto;
      overflow: visible;
    }
  }

  /* Phones: a box nearly as wide as the window never overshoots past it;
     the movement decelerates instead of springing (every path). */
  @media (max-width: 600px) {
    .ds-dialog[data-state="open"] .ds-dialog__box {
      transition:
        opacity var(--ds-dur-fast) var(--ds-ease-in-out),
        scale var(--ds-dur-slow) var(--ds-ease-out),
        translate var(--ds-dur-slow) var(--ds-ease-out);
    }

    .ds-dialog:not([data-state]) .ds-dialog__box {
      animation:
        ds-fade-in var(--ds-dur-medium) var(--ds-ease-in-out) backwards,
        ds-grow-in var(--ds-dur-medium) var(--ds-ease-out) backwards;
    }

    /* The rule above matches a closing dialog too; the exit stays the
       exit (it accelerates and cannot overshoot). */
    .ds-dialog--closing:not([data-state]) .ds-dialog__box {
      animation:
        ds-fade-out var(--ds-dur-base) var(--ds-ease-in-out) forwards,
        ds-shrink-out var(--ds-dur-base) var(--ds-ease-exit) forwards;
    }

    /* Full screen on phones only, above the on-screen keyboard. */
    .ds-dialog--full-narrow {
      padding: 0 0 var(--ds-keyboard-inset, 0px);
    }

    .ds-dialog--full-narrow .ds-dialog__box {
      --_pad: calc(var(--ds-dialog-padding, var(--ds-space-6)) + var(--ds-density, 0) * 2px);
      width: 100%;
      height: 100%;
      max-height: none;
      border-radius: calc(var(--ds-dialog-full-radius, 0px) * var(--ds-shape, 1));
      padding:
        0
        max(var(--_pad), env(safe-area-inset-right))
        max(var(--_pad), env(safe-area-inset-bottom))
        max(var(--_pad), env(safe-area-inset-left));
    }

    .ds-dialog--full-narrow .ds-dialog__head {
      margin: 0 calc(var(--ds-space-2) - var(--ds-dialog-padding, var(--ds-space-6)) - var(--ds-density, 0) * 2px);
      padding-top: env(safe-area-inset-top);
    }
  }

  @media (max-width: 600px) {
    dialog.ds-dialog[open]:not([data-state]) .ds-dialog__box {
      transition:
        opacity var(--ds-dur-fast) var(--ds-ease-in-out),
        scale var(--ds-dur-slow) var(--ds-ease-out),
        translate var(--ds-dur-slow) var(--ds-ease-out);
    }
  }

  /* ── Full screen and action sheet: they rise, no scale ──
     After the phone rules, which they override: the full-screen box
     always rises on the spring (a 12px rise has nothing to overshoot past),
     the action sheet rises its full height from the bottom edge. Both
     fade in over --ds-dur-fast and leave in --ds-dur-base, dropping back,
     accelerating. */
  .ds-dialog--full[data-state] .ds-dialog__box,
  .ds-dialog--bottom[data-state] .ds-dialog__box {
    transition:
      opacity var(--ds-dur-fast) var(--ds-ease-in-out),
      translate var(--ds-dur-long) var(--ds-ease-spatial);
  }

  .ds-dialog--full[data-state="closed"] .ds-dialog__box,
  .ds-dialog--bottom[data-state="closed"] .ds-dialog__box {
    scale: none;
    transition:
      opacity var(--ds-dur-base) var(--ds-ease-in-out),
      translate var(--ds-dur-base) var(--ds-ease-exit);
  }

  .ds-dialog--full[data-state="closed"] .ds-dialog__box {
    translate: 0 var(--ds-distance-lg);
  }

  .ds-dialog--bottom[data-state="closed"] .ds-dialog__box {
    translate: 0 var(--ds-distance-sheet);
  }

  /* By hand (no data-state): the same rise as keyframes. */
  .ds-dialog--full:not([data-state]) .ds-dialog__box,
  .ds-dialog--bottom:not([data-state]) .ds-dialog__box {
    --ds-motion-distance: var(--ds-distance-lg);
    animation:
      ds-fade-in var(--ds-dur-fast) var(--ds-ease-in-out) backwards,
      ds-lift-in var(--ds-dur-long) var(--ds-ease-spatial) backwards;
  }

  .ds-dialog--bottom:not([data-state]) .ds-dialog__box {
    --ds-motion-distance: var(--ds-distance-sheet);
  }

  .ds-dialog--full.ds-dialog--closing:not([data-state]) .ds-dialog__box,
  .ds-dialog--bottom.ds-dialog--closing:not([data-state]) .ds-dialog__box {
    animation:
      ds-fade-out var(--ds-dur-base) var(--ds-ease-in-out) forwards,
      ds-drop-out var(--ds-dur-base) var(--ds-ease-exit) forwards;
  }

  @media (max-width: 600px) {
    .ds-dialog--full-narrow[data-state] .ds-dialog__box {
      transition:
        opacity var(--ds-dur-fast) var(--ds-ease-in-out),
        translate var(--ds-dur-long) var(--ds-ease-spatial);
    }

    .ds-dialog--full-narrow[data-state="closed"] .ds-dialog__box {
      scale: none;
      translate: 0 var(--ds-distance-lg);
      transition:
        opacity var(--ds-dur-base) var(--ds-ease-in-out),
        translate var(--ds-dur-base) var(--ds-ease-exit);
    }

    .ds-dialog--full-narrow:not([data-state]) .ds-dialog__box {
      --ds-motion-distance: var(--ds-distance-lg);
      animation:
        ds-fade-in var(--ds-dur-fast) var(--ds-ease-in-out) backwards,
        ds-lift-in var(--ds-dur-long) var(--ds-ease-spatial) backwards;
    }

    .ds-dialog--full-narrow.ds-dialog--closing:not([data-state]) .ds-dialog__box {
      animation:
        ds-fade-out var(--ds-dur-base) var(--ds-ease-in-out) forwards,
        ds-drop-out var(--ds-dur-base) var(--ds-ease-exit) forwards;
    }
  }

  /* A native full-screen dialog or action sheet driven by hand: the same
     rise on transitions, keyed on [open]. The open state names [open], so
     it outweighs the phone dialog's ease-out (dialog.ds-dialog[open]
     above). */
  dialog.ds-dialog--full:not([data-state]) .ds-dialog__box,
  dialog.ds-dialog--full[open]:not([data-state]) .ds-dialog__box,
  dialog.ds-dialog--bottom:not([data-state]) .ds-dialog__box,
  dialog.ds-dialog--bottom[open]:not([data-state]) .ds-dialog__box {
    animation: none;
    transition:
      opacity var(--ds-dur-fast) var(--ds-ease-in-out),
      translate var(--ds-dur-long) var(--ds-ease-spatial);
  }

  dialog.ds-dialog--full:not([data-state]):not([open]) .ds-dialog__box,
  dialog.ds-dialog--bottom:not([data-state]):not([open]) .ds-dialog__box {
    scale: none;
    transition:
      opacity var(--ds-dur-base) var(--ds-ease-in-out),
      translate var(--ds-dur-base) var(--ds-ease-exit);
  }

  dialog.ds-dialog--full:not([data-state]):not([open]) .ds-dialog__box {
    translate: 0 var(--ds-distance-lg);
  }

  dialog.ds-dialog--bottom:not([data-state]):not([open]) .ds-dialog__box {
    translate: 0 var(--ds-distance-sheet);
  }

  /* --full-narrow is a full-screen dialog at 600px and below: the same
     rise. */
  @media (max-width: 600px) {
    dialog.ds-dialog--full-narrow:not([data-state]) .ds-dialog__box,
    dialog.ds-dialog--full-narrow[open]:not([data-state]) .ds-dialog__box {
      animation: none;
      transition:
        opacity var(--ds-dur-fast) var(--ds-ease-in-out),
        translate var(--ds-dur-long) var(--ds-ease-spatial);
    }

    dialog.ds-dialog--full-narrow:not([data-state]):not([open]) .ds-dialog__box {
      scale: none;
      translate: 0 var(--ds-distance-lg);
      transition:
        opacity var(--ds-dur-base) var(--ds-ease-in-out),
        translate var(--ds-dur-base) var(--ds-ease-exit);
    }
  }

  @starting-style {
    dialog.ds-dialog--full[open]:not([data-state]) .ds-dialog__box {
      scale: none;
      translate: 0 var(--ds-distance-lg);
    }

    dialog.ds-dialog--bottom[open]:not([data-state]) .ds-dialog__box {
      scale: none;
      translate: 0 var(--ds-distance-sheet);
    }
  }

  @media (max-width: 600px) {
    @starting-style {
      dialog.ds-dialog--full-narrow[open]:not([data-state]) .ds-dialog__box {
        scale: none;
        translate: 0 var(--ds-distance-lg);
      }
    }
  }

  /* Scroll outside (3.0): the window scrolls the whole box, which keeps
     its content's height (a long read, a form that should scroll as one
     page). The frame is the scroller; the box sits at its top with the
     frame's padding around it, never cut by the window. */
  .ds-dialog--scroll-outside,
  dialog.ds-dialog--scroll-outside {
    place-items: start center;
    overflow-y: auto;
    overscroll-behavior: contain;
    scrollbar-width: thin;
    scrollbar-color: var(--ds-line-2) transparent;
  }

  .ds-dialog--scroll-outside .ds-dialog__box {
    max-height: none;
    overflow: visible;
    margin-block: var(--ds-space-8);
  }

  .ds-dialog--scroll-outside .ds-dialog__box:has(> .ds-dialog__body) {
    display: grid;
  }

  .ds-dialog--scroll-outside .ds-dialog__body {
    overflow: visible;
  }

  /* The backdrop stays put while the frame scrolls under it. */
  .ds-dialog--scroll-outside .ds-dialog__backdrop {
    position: fixed;
  }

  /* A list of what the question is about (the devices a delete takes):
     confirm({ lines }). */
  .ds-dialog__lines {
    margin: 0;
    padding-inline-start: var(--ds-space-5);
    color: var(--ds-text);
    font: var(--ds-font-body);
  }

  .ds-dialog__lines > li + li {
    margin-top: var(--ds-space-1);
  }

  /* The facts of a record a question is about (confirm({ facts })): the
     term in a column, the value beside it, hairlines between. */
  .ds-dialog__facts {
    display: grid;
    grid-template-columns: minmax(0, auto) minmax(0, 1fr);
    margin: 0;
    font: var(--ds-font-body);
  }

  .ds-dialog__facts > div {
    display: grid;
    grid-template-columns: subgrid;
    grid-column: 1 / -1;
    column-gap: var(--ds-space-4);
    padding-block: var(--ds-space-2);
    border-top: 1px solid var(--ds-line);
  }

  .ds-dialog__facts > div:first-child {
    border-top: 0;
  }

  .ds-dialog__facts dt {
    color: var(--ds-text-2);
  }

  .ds-dialog__facts dd {
    margin: 0;
    color: var(--ds-text);
    overflow-wrap: anywhere;
  }

  /* Non-modal (3.0): the box alone, without a frame or scrim, floating at
     the end of the window above the page, which stays usable (a compose
     window, a running task). DS.overlay opens it as a non-modal layer: no
     trap, no inert, no scroll lock; Escape closes it while it is the top
     layer and focus goes back to the opener when it was inside. */
  .ds-dialog__box--modeless {
    --_inset: var(--ds-dialog-modeless-inset, var(--ds-space-4));
    position: fixed;
    inset-block-end: calc(var(--_inset) + var(--ds-keyboard-inset, 0px));
    inset-inline-end: var(--_inset);
    z-index: var(--ds-z-popover);
    width: min(var(--ds-dialog-width, 400px), calc(100% - 2 * var(--_inset)));
    max-height: calc(100dvh - 2 * var(--_inset) - var(--ds-keyboard-inset, 0px));
    margin: 0;
  }

  .ds-dialog__box[hidden],
  .ds-dialog__box--modeless[hidden] {
    display: none;
  }

  .ds-dialog__box--modeless[data-state] {
    transform-origin: var(--ds-motion-origin, 100% 100%);
    transition:
      opacity var(--ds-dur-fast) var(--ds-ease-in-out),
      scale var(--ds-dur-slow) var(--ds-ease-spatial),
      translate var(--ds-dur-slow) var(--ds-ease-spatial);
  }

  .ds-dialog__box--modeless[data-state="closed"] {
    opacity: 0;
    scale: var(--ds-scale-enter);
    translate: 0 var(--ds-distance-md);
    pointer-events: none;
    transition:
      opacity var(--ds-dur-base) var(--ds-ease-in-out),
      scale var(--ds-dur-base) var(--ds-ease-exit),
      translate var(--ds-dur-base) var(--ds-ease-exit);
  }

  /* By hand, without data-state: the entrance of the state path. */
  .ds-dialog__box--modeless:not([data-state]) {
    --ds-motion-distance: var(--ds-distance-md);
    animation:
      ds-fade-in var(--ds-dur-medium) var(--ds-ease-in-out) backwards,
      ds-grow-in var(--ds-dur-medium) var(--ds-ease-spatial) backwards;
  }

  @media (max-width: 600px) {
    .ds-dialog__box--modeless {
      --_inset: var(--ds-dialog-modeless-inset, var(--ds-space-2));
    }

    .ds-dialog__box--modeless[data-state="open"] {
      transition:
        opacity var(--ds-dur-fast) var(--ds-ease-in-out),
        scale var(--ds-dur-slow) var(--ds-ease-out),
        translate var(--ds-dur-slow) var(--ds-ease-out);
    }
  }

  @media print {
    .ds-dialog,
    .ds-dialog__box--modeless {
      display: none;
    }
  }
}

/* ── components/table/table.css ── */
/*
 * Data tables (Material 3): a 48px header in the label style, 52px rows
 * divided by the passive hairline, a quiet hover. Numbers right-aligned
 * and tabular. Inside a card the table runs to the card's
 * edges, so the row hover spans the whole width and the first column lines
 * up with the card text. The wrapper scrolls sideways on narrow screens; a
 * sticky header needs a wrapper that also scrolls down: a bounded wrapper
 * (.ds-table--sticky-head with --ds-table-max-height, a stacking context of
 * its own, whose end hands the wheel on to the page) or the full-page table
 * (.ds-table-wrap--fill, which keeps the wheel).
 *
 *   <div class="ds-table-wrap">
 *     <table class="ds-table [ds-table--wide]">
 *       <thead><tr><th>Name</th><th class="ds-num">Count</th><th class="ds-col--secondary">Owner</th></tr></thead>
 *       <tbody><tr><td class="ds-col--text">...</td><td class="ds-num">12</td><td class="ds-col--secondary">...</td></tr></tbody>
 *       <tfoot><tr><th scope="row">Total</th><td class="ds-num">128</td><td class="ds-col--secondary"></td></tr></tfoot>
 *
 *   .ds-col--text       a text column that keeps a readable width
 *   .ds-col--secondary  dropped on phones (and in .ds-table--wide when the
 *                       content area is narrow); in a card the last
 *                       column still shown keeps the card's gutter
 *   .ds-link-btn        a button that reads like a link (opens a detail;
 *                       button.css)
 *   .ds-table--zebra    every other body row in --ds-table-zebra (a detail
 *                       row goes with its trigger; selection and the state
 *                       layers lie over it)
 *   .ds-table--bordered a hairline between the columns too, and around the
 *                       table outside a card or a full-page wrapper
 *   .ds-table--plain    no hairlines between the rows (with --zebra)
 *   <th aria-sort="ascending"><button class="ds-table__sort">Name (arrowUp .ds-table__sort-arrow)</button></th>
 *                       a sortable column; the arrow at the sorted column
 *                       says it, not the colour; every sort button keeps
 *                       the arrow's room, so moving the sort never shifts
 *                       the columns
 *   .ds-table__sort-arrow  on the arrow's svg: one up arrow for both
 *                       directions, which turns to point down for
 *                       aria-sort="descending" (opt-in: an unmarked svg
 *                       is never turned, so a page that renders arrowDown
 *                       for descending keeps its direction)
 *   <td class="ds-table__actions"><button class="ds-btn ds-btn--quiet ds-btn--icon" type="button" aria-label="Remove source 1">(close)</button></td>
 *                       the row's own actions at its end: end-aligned, as
 *                       narrow as its buttons, which hang into the cell's
 *                       padding (the row keeps its height); in an inner
 *                       .ds-hover-actions they show on demand
 *   tfoot               a summary row: label type, a hairline above, no
 *                       hover, press or row link
 *   .ds-table--sticky-head, .ds-table--sticky-foot
 *                       the header row, the summary row stays while the
 *                       rows scroll under it, in a wrapper bounded by
 *                       --ds-table-max-height (or a full-page wrapper)
 *   <div class="ds-selection-bar" role="toolbar" aria-label="Selected devices">
 *     <button class="ds-btn ds-btn--quiet ds-btn--icon" type="button" aria-label="Clear selection">(close)</button>
 *     <p class="ds-selection-bar__count" aria-live="polite">3 selected</p>
 *     <div class="ds-selection-bar__actions">...</div>
 *   </div>              the bar of a bulk selection, in --ds-accent: it
 *                       shares a .ds-swap slot with the toolbar
 *                       (DS.motion.crossfade() when the count goes from 0
 *                       to 1 and back), so the table never moves
 *
 * Stacked rows (a row of fields on a phone or in a side sheet):
 *   <table class="ds-table ds-table--stack">   (or ds-table--stack-wide)
 *     <tbody><tr><td data-label="Name"><input class="ds-input" aria-label="Name"></td> ...
 *   Each row becomes a block with a hairline border, each cell a label
 *   (its data-label, in the field label's type) above its content, a
 *   .ds-table__actions cell at the block's top end; the header stays for
 *   screen readers only. Always inside .ds-sheet__body and .ds-dialog,
 *   and in a view whose content area is at most 600px wide (--stack) or
 *   840px (--stack-wide, five or more field columns). No row hover and no
 *   fade; not for interactive rows, expandable rows or sort buttons, and
 *   a full-page wrapper or a pinned column steps aside while the rows
 *   stack. The three copies of the stacked block (sheet and dialog, 600px,
 *   840px) are kept identical by a test.
 *
 * Options (src/core/options.css, docs/options.md), on the table or any
 * ancestor; each is computed here, in the cells' own rule:
 *   size      .ds-xs ... .ds-xl: 8px of head and row height per step
 *   density   .ds-density-*: 4px of head and row height per step (rows 52,
 *             48, 44, 40px), 2px of cell padding per step
 *   touch     .ds-touch: head and rows at least --ds-touch-target high, the
 *             sort button's target as high (it hangs into the cell)
 *   shape     .ds-shape-*: multiplies the radius of the sort button, the
 *             full-page wrapper, a stacked block and the selection bar
 *   not type: the cells keep --ds-font-dense and the head --ds-font-label at
 *             every size, so a size class around a table only gives its
 *             rows room. No tone: a table shows no meaning of its own
 *             (a status chip in a cell does)
 *
 * Full-page tables and pinned columns:
 *   <div class="ds-table-wrap ds-table-wrap--fill"><table class="ds-table ds-table--pin-first">...</table></div>
 *   .ds-table-wrap--fill  the wrapper is its own card (hairline border,
 *                       card radius), fills what is left of a bounded
 *                       parent (.ds-view--fill) and scrolls both ways; its
 *                       header row is sticky, and long cells are cut with
 *                       an ellipsis at --ds-table-cell-max-width (a
 *                       tooltip shows a cut cell's text)
 *   .ds-table--pin-first  the first column stays while the others scroll
 *                       under it, on an opaque base; the row's layers lie
 *                       over it (registered colours, so they still fade);
 *                       a hairline at its end shows once the table has
 *                       scrolled (the wrapper drops its start
 *                       fade). In an interactive table
 *                       DS.ripple.attach() forwards a click on the row to
 *                       its row link (the pinned cell confines the link's
 *                       stretched area) and ripples the row in two parts
 *   .ds-table--pin-last the last column stays (the row's actions, a total),
 *                       the same way at the end edge: its hairline shows
 *                       while columns follow under it, and the wrapper
 *                       drops its end fade. Its cell stands above the row
 *                       link: its own room opens nothing, with no pointer,
 *                       no press and no ripple; a row's ripple reaches it
 *                       in a part of its own (DS.ripple.attach()), and it
 *                       finishes the ring of a row link in another cell.
 *                       DS.dom.scrollEdges() measures it, so a control that
 *                       Tab reaches under it scrolls clear of it
 *
 * Wrappers that scroll sideways fade at the end that still has columns
 * (in a card: .ds-table--wide when the content area is narrow, every table
 * on phones; .ds-table-wrap--fill always). The fades are the two numbers
 * of scroller.css (--ds-scroll-edge-start, --ds-scroll-edge-end): where
 * scroll timelines exist ds-scroll-edge-start and ds-scroll-edge-end drive
 * them on the wrapper's own scroll; elsewhere DS.dom.scrollEdges() writes
 * data-ds-overflow-start and -end (a card wrapper without it keeps the
 * static fade at its right edge). A wrapper with stacked rows never fades.
 * A wrapper whose cells hold nothing focusable is a tab stop
 * (tabindex="0" role="region" aria-label="..."): an inset ring that snaps
 * from its edge, unmasked while focused; around a wrapper with sticky rows or
 * a pinned column, whose cells would paint over it, the ring lies outside
 * the box and snaps in from one width further out.
 *
 * Hooks: --ds-table-row-hover, --ds-table-row-selected, --ds-table-head-height
 * (48px), --ds-table-row-height (52px; the cell padding follows the
 * heights), --ds-table-padding
 * (--ds-space-4, the cells' side padding; on phones 3/4 of it, below 360px
 * half), --ds-table-zebra
 * (--ds-surface-low), --ds-table-sticky-bg (the opaque base of sticky and
 * pinned cells and of the fill wrapper, default --ds-surface),
 * --ds-table-max-height (none),
 * --ds-table-cell-max-width (280px), --ds-table-fill-min-height
 * (240px), --ds-table-fill-max-height (none), --ds-selection-bar-height
 * (48px), --ds-scroll-fade (the fade length; in a card --ds-card-pad, 0px
 * turns the fades off).
 *
 * Runtime properties (written by DS.dom.scrollEdges(), read with a
 * fallback): --ds-scrollbar-height (the scrollbar strip stays unmasked),
 * --ds-table-pin-width (focus never lands under a pinned column).
 *
 * Internal (never set them): --ds-table-start-fade and
 * --ds-table-end-fade, 1 on every wrapper; 0 on one that holds a
 * .ds-table--pin-first or a .ds-table--pin-last (no fade over the pinned
 * column; the other end's fade stays). The private computed values of a
 * rule (--_h, --_box, --_room, --_pad, --_hang, and --_sticky-head,
 * --_sticky-foot, --_kept-head, --_kept-foot for the sticky rows' focus
 * offset) are private: never set them.
 *
 * Internal (each body row sets them, its cells read them; never set
 * them): --ds-table-row-layer, --ds-table-row-pace, --ds-table-row-tint,
 * --ds-table-row-line, --ds-table-row-ring. The row decides, the cells paint: no cell rule
 * sits behind a row's :has() (Chromium would restyle every table cell
 * of the page on each change anywhere in it).
 *
 * The sort button presses in --ds-dur-micro (also while js/ripple.js holds
 * .ds-pressed) and ripples; it is not a pill and does not morph. Keyboard
 * focus on the sort button: a ring that is solid from the first frame and
 * snaps from offset + width to the offset (outline-offset, --ds-dur-fast),
 * plus the focus layer. The link button (.ds-link-btn, button.css) is an
 * inline link: no ripple, no morph.
 *
 * Rows:
 *   hover                  a state layer on the cells (currentColor at
 *                          --ds-state-hover-lg), so it adds to a selected
 *                          row's colour; hook --ds-table-row-hover
 *   .ds-table--interactive every body row with a row link opens something:
 *                          its primary link or button carries
 *                          .ds-table__row-link, whose
 *                          ::after stretches over the row (the focus ring
 *                          sits on it, inset, so the scroller never clips
 *                          it); the row is positioned and every body row
 *                          has an identity transform, so it is the box of
 *                          the stretched area also in WebKit, which lays
 *                          rows out static (a row is then a stacking
 *                          context and the box of fixed descendants; not
 *                          while it holds a menu or combobox list that the
 *                          script places); WebKit makes the area as tall
 *                          as the table below the row's top, the rows
 *                          below, painted above it, keep their own
 *                          clicks, and a focused row clips its ring to
 *                          itself; the press is the cell layer at
 *                          --ds-state-pressed in --ds-dur-micro, or the
 *                          ripple (js/ripple.js, the row is a host); other
 *                          controls in the row stay above the link and
 *                          keep their own press (no row layer, no ripple);
 *                          the table draws separate borders (a positioned
 *                          row would cover collapsed hairlines in Firefox);
 *                          a row without a row link stays plain (no
 *                          pointer, no press, no ripple)
 *   .ds-table__row--selected, or a checked checkbox directly in a cell: the
 *                          row takes --ds-table-row-selected (default
 *                          --ds-accent) over --ds-dur-fast; the checkbox is
 *                          the cue that does not rely on colour, also in
 *                          the header cell (select all, indeterminate for
 *                          some); select all changes every row in one frame
 *   expandable             the trigger row holds
 *                          <button class="ds-btn ds-btn--quiet ds-btn--icon ds-table__toggle" aria-expanded="false" aria-controls="d1">(chevronDown .ds-chevron)</button>
 *                          and is followed by
 *                          <tr class="ds-table__detail" id="d1" inert><td colspan="N"><div class="ds-table__expand"><div>...</div></div></td></tr>
 *                          its header cell is named for screen readers:
 *                          <th scope="col"><span class="ds-sr">Details</span></th>
 *                          The detail opens by grid-template-rows (0fr to
 *                          1fr) over --ds-dur-medium on --ds-ease-out and
 *                          closes over --ds-dur-base on --ds-ease-in: it
 *                          pushes the rows below, so it never overshoots;
 *                          its content fades over --ds-dur-fast. One
 *                          hairline, below the detail. The page toggles
 *                          aria-expanded, sets inert on the collapsed
 *                          detail row and keys both rows (data-ds-key), so
 *                          flip() and morphHtml keep them together.
 *
 * Sorting: with .ds-table__sort-arrow the page renders the same up arrow
 * for both directions; aria-sort="descending" turns it 180deg on the
 * spring (--ds-dur-medium), when the header is patched in place
 * (DS.dom.morphHtml). Without the marker the arrow is what the page
 * renders (arrowUp or arrowDown), as before 1.4.
 *
 * Data motion (docs/motion.md, "Data motion"): sort, filter (also while
 * typing) and live data glide through DS.motion.flip with keyed rows and
 * DS.dom.morphHtml; figures in cells change at once and never count up.
 * A removed row goes at once while the rows below glide up. While rows
 * glide, flip() marks the tbody data-ds-glide and sets --ds-flip-backdrop
 * (the colour behind the table): every row gets an opaque backing in that
 * colour (the selection colour over it), so crossing rows never show
 * through each other.
 *
 * Forced colours: sticky and pinned cells are Canvas (nothing shows through
 * them), the pinned columns' hairlines and the fill wrapper's border
 * CanvasText, the selection bar keeps an outline, zebra and selection tints
 * go (the checkbox stays the cue), a plain table gets its row lines back.
 * Print:
 * wrappers show every column, unmasked and unclipped; the
 * full-page table is unbounded and unsticky, header text wraps, rows do not
 * break across pages, closed detail rows and the selection bar are hidden.
 *
 * :has() and container queries are baseline.
 * Progressive:
 * - scroll-driven edge fades (animation-timeline, the registered
 *   --ds-scroll-edge-* numbers of scroller.css; the pinned column's
 *   hairlines): without them DS.dom.scrollEdges() sets them through its
 *   attributes, or the static fade at the right edge stays (the hairlines
 *   then show with data-ds-overflow-start and -end).
 * - scrollbar-color and scrollbar-width (a thin scrollbar on the full-page
 *   table): without them the platform scrollbar shows.
 */

/*
 * Deprecated in 2.0 (removed in 3.0 at the earliest), unused: the widths
 * of the old scroll-linked edge fades (ds-edge-fade in motion.css). The
 * wrappers fade on --ds-scroll-edge-start and --ds-scroll-edge-end
 * (scroller.css) now.
 */
@property --ds-table-fade-start {
  syntax: '<length>';
  inherits: false;
  initial-value: 0px;
}

@property --ds-table-fade-end {
  syntax: '<length>';
  inherits: false;
  initial-value: 0px;
}

/*
 * The state layers of a pinned cell: its base is opaque (the columns that
 * scroll under it never show through), so hover, focus, press and the
 * selection lie over it as background images of these two colours.
 * Registered, so they fade like the other cells' background colour; they do
 * not inherit.
 */
@property --ds-table-sticky-layer {
  syntax: '<color>';
  inherits: false;
  initial-value: transparent;
}

@property --ds-table-sticky-tint {
  syntax: '<color>';
  inherits: false;
  initial-value: transparent;
}

@layer ds.components.table {
  /* Positioned, so absolutely placed descendants (the visually hidden header
     text .ds-sr) are clipped by the scroller instead of widening the page. */
  .ds-table-wrap {
    position: relative;
    overflow-x: auto;
    /* Focus moved by the keyboard never lands under a pinned first column
       (DS.dom.scrollEdges() writes its width), in a card as in a fill
       wrapper, nor under a pinned last one once the page sets its width. */
    scroll-padding-inline: var(--ds-table-pin-width, 0px) var(--ds-table-pin-last-width, 0px);
    /* The fade of each end, on (1) or off (0): a pinned column stays opaque. */
    --ds-table-start-fade: 1;
    --ds-table-end-fade: 1;
  }

  /* A pinned first column stays at the start edge, so the start fade would
     only wash out its text; its hairline tells that the table has
     scrolled. The end fade stays. */
  .ds-table-wrap:has(> .ds-table--pin-first) {
    --ds-table-start-fade: 0;
  }

  /* The same at the other end: the hairline of a pinned last column tells
     that columns follow under it. */
  .ds-table-wrap:has(> .ds-table--pin-last) {
    --ds-table-end-fade: 0;
  }

  /* A sticky row sticks to its scroller, and the wrapper is one (overflow-x
     makes it a scroller on both axes): it scrolls down once bounded. It sits
     mid-page, so a wheel at its end goes on to the page, and its sticky cells'
     z-indices stay inside it (a page's own sticky bar stays on top). */
  .ds-table-wrap:where(:has(> :is(.ds-table--sticky-head, .ds-table--sticky-foot))) {
    max-height: var(--ds-table-max-height, none);
    isolation: isolate;
  }

  /* Focus moved by the keyboard never lands under the sticky rows. The
     wrapper keeps what its own options make them, for whatever a script
     scrolls into view; what takes focus adds what the table's options add to
     that (below), since a class on the table never reaches the wrapper. */
  .ds-table-wrap:has(> .ds-table--sticky-head) {
    --_kept-head: max(var(--ds-target-min, 0px), calc(var(--ds-table-head-height, 48px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px));
    scroll-padding-block-start: var(--_kept-head);
  }

  .ds-table-wrap:has(> .ds-table--sticky-foot) {
    --_kept-foot: max(var(--ds-target-min, 0px), calc(var(--ds-table-row-height, 52px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px));
    scroll-padding-block-end: var(--_kept-foot);
  }

  .ds-table--sticky-head,
  .ds-table-wrap--fill > .ds-table {
    --_sticky-head: max(var(--ds-target-min, 0px), calc(var(--ds-table-head-height, 48px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px));
  }

  .ds-table--sticky-foot {
    --_sticky-foot: max(var(--ds-target-min, 0px), calc(var(--ds-table-row-height, 52px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px));
  }

  .ds-table--sticky-head > tbody :where(a[href], button, input, select, textarea, summary, [tabindex]),
  .ds-table-wrap--fill > .ds-table > tbody :where(a[href], button, input, select, textarea, summary, [tabindex]) {
    scroll-margin-block-start: max(0px, calc(var(--_sticky-head) - var(--_kept-head, 0px)));
  }

  .ds-table--sticky-foot > tbody :where(a[href], button, input, select, textarea, summary, [tabindex]) {
    scroll-margin-block-end: max(0px, calc(var(--_sticky-foot) - var(--_kept-foot, 0px)));
  }

  /* The edge numbers of scroller.css, from DS.dom.scrollEdges() where no
     scroll timeline drives them (the animations win where one does). They
     glide only once it has measured (data-ds-edges comes after the first
     edges): the first fades show still on load. */
  .ds-table-wrap[data-ds-edges] {
    transition:
      --ds-scroll-edge-start var(--ds-dur-fast) var(--ds-ease-in-out),
      --ds-scroll-edge-end var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  .ds-table-wrap[data-ds-overflow-start] {
    --ds-scroll-edge-start: 1;
  }

  .ds-table-wrap[data-ds-overflow-end] {
    --ds-scroll-edge-end: 1;
  }

  /* A wrapper that is a tab stop (nothing focusable in its cells): an inset
     ring, solid from the first frame, that snaps inward from the edge; the
     fades would cut it, so the focused wrapper shows unmasked. */
  .ds-table-wrap[tabindex] {
    outline-offset: 0;
    transition: outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-table-wrap[tabindex][data-ds-edges] {
    transition:
      --ds-scroll-edge-start var(--ds-dur-fast) var(--ds-ease-in-out),
      --ds-scroll-edge-end var(--ds-dur-fast) var(--ds-ease-in-out),
      outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-table-wrap[tabindex]:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: calc(-1 * var(--ds-focus-width));
  }

  /* Sticky and pinned cells have a z-index, so they paint over an outline
     inside the box: here the ring lies outside it, and rests one width
     further out. Focused, the wrapper stands above what follows it, which
     would cover the ring's lower edge. */
  .ds-table-wrap[tabindex]:where(.ds-table-wrap--fill, :has(> :is(.ds-table--sticky-head, .ds-table--sticky-foot, .ds-table--pin-first, .ds-table--pin-last))) {
    outline-offset: var(--ds-focus-width);
  }

  .ds-table-wrap[tabindex]:where(.ds-table-wrap--fill, :has(> :is(.ds-table--sticky-head, .ds-table--sticky-foot, .ds-table--pin-first, .ds-table--pin-last))):focus-visible {
    z-index: var(--ds-z-raised);
    outline-offset: 0;
  }

  .ds-card .ds-table-wrap {
    margin-inline: calc(-1 * var(--ds-card-pad));
  }

  .ds-table {
    width: 100%;
    border-collapse: collapse;
    /* Its own ink (a widget without .ds-base would take the host's). */
    color: var(--ds-text);
    font: var(--ds-font-dense);
    /* Dates, times and counts line up from row to row. */
    font-variant-numeric: tabular-nums;
  }

  /* The options, computed here (docs/options.md). Each cell names its
     height at size md, comfortable (--_h, the hook) and what its text line
     and hairline take (--_room); the box is never below the touch minimum
     (.ds-touch), and the block padding follows it, never more than
     --ds-space-3: a 20px line in a 48px head, a 24px status chip and the
     hairline in a 52px row, 7px in a 40px row. Density takes 2px of side
     padding per step as well. */
  .ds-table th,
  .ds-table td {
    --_box: max(var(--ds-target-min, 0px), var(--_h));
    --_pad: calc(var(--ds-table-padding, var(--ds-space-4)) + var(--ds-density, 0) * 2px);
    height: var(--_box);
    padding-block: min(var(--ds-space-3), max(0px, calc((var(--_box) - var(--_room)) / 2)));
    padding-inline: var(--_pad);
    border-bottom: 1px solid var(--ds-line);
    text-align: start;
    vertical-align: middle;
  }

  .ds-card .ds-table-wrap :is(th, td):first-child {
    padding-inline-start: var(--ds-card-pad);
  }

  .ds-card .ds-table-wrap :is(th, td):last-child {
    padding-inline-end: var(--ds-card-pad);
  }

  .ds-table caption {
    text-align: start;
  }

  .ds-table th {
    --_h: calc(var(--ds-table-head-height, 48px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px);
    --_room: calc(var(--ds-space-5) + 1px);
    color: var(--ds-text-2);
    font: var(--ds-font-label);
    white-space: nowrap;
  }

  .ds-table td {
    --_h: calc(var(--ds-table-row-height, 52px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px);
    --_room: calc(var(--ds-space-6) + 2px);
  }

  /*
   * The row holds the selection colour, its cells the state layer: the
   * layer adds to the selection instead of replacing it. The row decides
   * and its cells paint: each body row sets its state layer
   * (--ds-table-row-layer) and how fast it changes (--ds-table-row-pace),
   * the selection a pinned cell lays over its base (--ds-table-row-tint)
   * and the style of its hairline (--ds-table-row-line); its cells read
   * them. A cell rule behind a row's :has() would put every cell of the
   * page into Chromium's one :has() invalidation set, so each change
   * anywhere in the page restyled every table cell. Every body row starts
   * from these values, so a nested table never takes its outer row's
   * layer. Internal: a page never sets them.
   */
  .ds-table tbody tr {
    --ds-table-row-layer: transparent;
    --ds-table-row-pace: var(--ds-dur-fast);
    --ds-table-row-tint: transparent;
    --ds-table-row-line: solid;
    --ds-table-row-ring: none;
    transition: background-color var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  .ds-table tbody tr > :is(td, th) {
    border-bottom-style: var(--ds-table-row-line);
    background-color: var(--ds-table-row-layer);
    transition: background-color var(--ds-table-row-pace) var(--ds-ease-in-out);
  }

  @media (hover: hover) {
    .ds-table tbody tr:not(.ds-table__detail):hover {
      --ds-table-row-layer: var(--ds-table-row-hover, color-mix(in srgb, currentColor calc(var(--ds-state-hover-lg) * 100%), transparent));
    }
  }

  /* Selected rows (bulk selection): the checkbox in the row is the cue
     that does not rely on colour. Two rules: the class marks a row on its
     own (set by the page), and the :has() rule picks up a row whose
     checkbox is checked. */
  .ds-table tbody tr.ds-table__row--selected {
    --ds-table-row-tint: var(--ds-table-row-selected, var(--ds-accent));
    background-color: var(--ds-table-row-selected, var(--ds-accent));
  }

  .ds-table tbody tr:has(> :is(td, th) > input[type="checkbox"]:checked) {
    --ds-table-row-tint: var(--ds-table-row-selected, var(--ds-accent));
    background-color: var(--ds-table-row-selected, var(--ds-accent));
  }

  /* Zebra: the even rows, not counting detail rows (a detail row goes with
     its trigger). The :where() keeps it below the selected rows above, and
     the state layer on the cells adds to it; a pinned cell lays it over
     its base as it does the selection. The look modifiers name their own
     rows only: a nested table keeps its own look. */
  .ds-table--zebra > tbody > tr:where(:nth-child(even of :not(.ds-table__detail))),
  .ds-table--zebra > tbody > tr:where(:nth-child(even of :not(.ds-table__detail)) + .ds-table__detail) {
    --ds-table-row-tint: var(--ds-table-zebra, var(--ds-surface-low));
    background-color: var(--ds-table-zebra, var(--ds-surface-low));
  }

  /* No hairlines between the rows (a zebra needs none). */
  .ds-table--plain > tbody > tr {
    --ds-table-row-line: none;
  }

  /* A hairline between the columns, on the following cell, so a dropped
     .ds-col--secondary takes its line along; the :where() keeps it below
     a stacked cell's border: 0. Around the table only where nothing else
     draws its edge (a stacked table draws none: its rows are blocks). */
  .ds-table--bordered > * > tr > :is(th, td):where(:not(:first-child)) {
    border-inline-start: 1px solid var(--ds-line);
  }

  .ds-table--bordered:where(:not(.ds-card *, .ds-table-wrap--fill *)) {
    border: 1px solid var(--ds-line);
  }

  /* While rows glide (DS.motion.flip marks the tbody data-ds-glide with
     --ds-flip-backdrop, the colour behind the table), every row is opaque,
     so a row that crosses another never shows its text through. A
     background image: it switches at once (no colour transition), and the
     selection colour lies over the backing; the cells' state layer stays
     above both. At rest it matches what is behind the table. */
  .ds-table tbody[data-ds-glide] > tr {
    background-image: linear-gradient(var(--ds-flip-backdrop, var(--ds-surface)), var(--ds-flip-backdrop, var(--ds-surface)));
  }

  .ds-table--zebra > tbody[data-ds-glide] > tr:where(:nth-child(even of :not(.ds-table__detail))),
  .ds-table--zebra > tbody[data-ds-glide] > tr:where(:nth-child(even of :not(.ds-table__detail)) + .ds-table__detail) {
    background-image:
      linear-gradient(var(--ds-table-zebra, var(--ds-surface-low)), var(--ds-table-zebra, var(--ds-surface-low))),
      linear-gradient(var(--ds-flip-backdrop, var(--ds-surface)), var(--ds-flip-backdrop, var(--ds-surface)));
  }

  .ds-table tbody[data-ds-glide] > tr.ds-table__row--selected {
    background-image:
      linear-gradient(var(--ds-table-row-selected, var(--ds-accent)), var(--ds-table-row-selected, var(--ds-accent))),
      linear-gradient(var(--ds-flip-backdrop, var(--ds-surface)), var(--ds-flip-backdrop, var(--ds-surface)));
  }

  .ds-table tbody[data-ds-glide] > tr:has(> :is(td, th) > input[type="checkbox"]:checked) {
    background-image:
      linear-gradient(var(--ds-table-row-selected, var(--ds-accent)), var(--ds-table-row-selected, var(--ds-accent))),
      linear-gradient(var(--ds-flip-backdrop, var(--ds-surface)), var(--ds-flip-backdrop, var(--ds-surface)));
  }

  /*
   * Interactive rows: the row's primary link or button stretches over the
   * row (::after against the row, positioned and transformed). Other
   * controls in the row stay above it (zero specificity: a control's own
   * position wins). A row without a row link opens nothing, so it stays
   * plain.
   */
  /* Positioned rows paint after the table's collapsed borders (Firefox
     then covers a selected row's hairlines with its colour): separate
     borders, which each cell paints over its row. Only bottom borders are
     drawn, so the lines look the same. */
  .ds-table--interactive,
  .ds-table--sticky-head,
  .ds-table--sticky-foot,
  .ds-table--pin-last {
    border-collapse: separate;
    border-spacing: 0;
  }

  .ds-table--interactive tbody tr:not(.ds-table__detail):has(.ds-table__row-link) {
    position: relative;
    cursor: pointer;
    -webkit-tap-highlight-color: transparent;
  }

  /* WebKit lays a table row out static whatever its position, so the row
     link's ::after (and the row's ripple box) would stretch over the
     nearest positioned box around the table: every row's link over the
     whole table, the last on top, taking hover, clicks and the status bar
     URL of every row. An identity transform makes the row their containing
     block in every engine (it is also a stacking context, which the
     raised controls and the pinned cell stay inside). Every body row gets
     it: WebKit makes the area as tall as the table
     below the row's top, and a later row, painted above, keeps its own
     clicks also when it has no row link (or is a detail row). */
  .ds-table--interactive tbody tr {
    transform: translateX(0);
  }

  /* A menu or combobox list that the script places inside a row (no top
     layer: no popover or anchor positioning) is fixed or absolute against
     the viewport or its field: the transform would make the row its box,
     clipped by the scrolling wrapper and painted under the rows below. */
  .ds-table--interactive tbody tr:has(:is(.ds-menu, .ds-combo__popup):not([hidden], [data-anchored])) {
    transform: none;
  }

  :where(.ds-table--interactive tbody tr) :where(a[href], button, input, select, textarea, label, summary, [tabindex]):where(:not(.ds-table__row-link)) {
    position: relative;
    z-index: var(--ds-z-raised);
  }

  .ds-table__row-link::after {
    content: '';
    position: absolute;
    inset: 0;
    /* The ring rests at the row's edge and snaps inward. */
    outline-offset: 0;
    transition: outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-table--interactive .ds-table__row-link:focus-visible {
    outline: none;
  }

  /* Inset by the ring's width, so the scroller never clips it. */
  .ds-table__row-link:focus-visible::after {
    outline: var(--ds-focus-outline);
    outline-offset: calc(-1 * var(--ds-focus-width));
  }

  /* Keyboard focus: the focus layer on the cells, at once. WebKit gives a
     transformed row's absolute boxes the row's top and width but the
     table's height, so the link's ring would run on down to the table's
     end: the focused row clips what it holds to its own box (the inset
     ring and the cells' content lie inside it in every engine). Anchor
     positioning would size the area itself, but WebKit then restyles the
     link from its initial values on every load, so its underline and
     ring offset transition. */
  .ds-table--interactive tbody tr:not(.ds-table__detail):where(:has(.ds-table__row-link:focus-visible)):focus-within {
    --ds-table-row-layer: color-mix(in srgb, currentColor calc(var(--ds-state-focus) * 100%), transparent);
    --ds-table-row-pace: 0s;
    clip-path: inset(0);
  }

  /* A pinned last cell stands above the link's ring, so it finishes the ring:
     the end, top and bottom edges (below). The ring takes the place of the
     row's hairline, so its bottom edge lines up with the rest. */
  .ds-table--interactive.ds-table--pin-last:not(.ds-table--pin-first) tbody tr:not(.ds-table__detail):where(:has(.ds-table__row-link:focus-visible)):focus-within {
    --ds-table-row-line: none;
    --ds-table-row-ring: var(--ds-focus-outline);
  }

  /* Press-in in --ds-dur-micro (.ds-pressed: js/ripple.js holds it); not
     while a control inside the row is pressed (it has its own press), nor on
     the room of a pinned last cell, which opens nothing. */
  .ds-table--interactive tbody tr:not(.ds-table__detail):has(.ds-table__row-link):is(:active, .ds-pressed):not(:where(:has(:is(a[href], button, input, select, textarea, label, summary):not(.ds-table__row-link):active))):not(:where(.ds-table--pin-last tbody tr:has(> :is(td, th):last-child:active))) {
    --ds-table-row-layer: color-mix(in srgb, currentColor calc(var(--ds-state-pressed) * 100%), transparent);
    --ds-table-row-pace: var(--ds-dur-micro);
  }

  /*
   * Expandable rows: the detail row has no padding, height or hairline of
   * its own until it opens; the trigger row gives its hairline to the
   * detail, so there is one line, below the detail, which travels down as
   * it opens.
   */
  .ds-table tbody tr:has(+ .ds-table__detail) {
    --ds-table-row-line: none;
  }

  .ds-table .ds-table__detail > td,
  .ds-card .ds-table-wrap .ds-table__detail > td {
    height: auto;
    padding: 0;
  }

  /* The open state reaches the content through --_shown (and its curve):
     a rule that styled `... + .ds-table__detail .ds-table__expand > *`
     behind the row's :has() made Chromium restyle the whole page on every
     change anywhere. Each wrapper sets its own value, so a nested one stays
     closed until its own row opens. */
  .ds-table__expand {
    --_shown: 0;
    --_shown-ease: var(--ds-ease-in);
    display: grid;
    grid-template-rows: 0fr;
    transition: grid-template-rows var(--ds-dur-base) var(--ds-ease-in);
  }

  /* The content: horizontal room as the cells', vertical room as spacers
     inside the clip (a padding would stay as the collapsed height). */
  .ds-table__expand > * {
    min-height: 0;
    overflow: hidden;
    padding-inline: calc(var(--ds-table-padding, var(--ds-space-4)) + var(--ds-density, 0) * 2px);
    opacity: var(--_shown);
    transition: opacity var(--ds-dur-fast) var(--_shown-ease);
  }

  .ds-table__expand > *::before,
  .ds-table__expand > *::after {
    content: '';
    display: block;
    height: var(--ds-space-4);
  }

  .ds-table__expand > *::before {
    height: var(--ds-space-1);
  }

  .ds-card .ds-table-wrap .ds-table__expand > * {
    padding-inline: var(--ds-card-pad);
  }

  tr:has(.ds-table__toggle[aria-expanded="true"]) + .ds-table__detail .ds-table__expand {
    --_shown: 1;
    --_shown-ease: var(--ds-ease-in-out);
    grid-template-rows: 1fr;
    transition: grid-template-rows var(--ds-dur-medium) var(--ds-ease-out);
  }

  /* The 40px round toggle hangs out of the 20px text line, so the row
     keeps its height; its icon lines up with the column's text. Its margin
     box is the text line: aligned to the line's top (not its baseline),
     its centre is the line's centre. */
  .ds-table .ds-table__toggle {
    vertical-align: top;
    margin-block: calc((var(--ds-space-5) - max(var(--ds-target-min, 0px), calc(var(--ds-btn-icon-size, 40px) + var(--ds-size-step, 0) * 8px))) / 2);
    margin-inline: calc((var(--ds-space-5) - max(var(--ds-target-min, 0px), calc(var(--ds-btn-icon-size, 40px) + var(--ds-size-step, 0) * 8px))) / 2) 0;
  }

  .ds-table tbody tr:last-child :is(td, th) {
    border-bottom: none;
  }

  /*
   * Row actions: the last cell holds the row's own buttons, as narrow as
   * they are, at the row's end. The buttons hang into the cell's padding
   * (their margin box is the 20px text line), so the row keeps its height
   * and the last icon lines up with the column edge.
   */
  .ds-table td.ds-table__actions {
    width: 1%;
    white-space: nowrap;
    text-align: end;
  }

  .ds-table__actions .ds-btn {
    margin-block: calc((var(--ds-space-5) - max(var(--ds-target-min, 0px), calc(var(--ds-btn-height, 40px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px))) / 2);
    vertical-align: top;
  }

  .ds-table__actions .ds-btn--icon {
    margin-block: calc((var(--ds-space-5) - max(var(--ds-target-min, 0px), calc(var(--ds-btn-icon-size, 40px) + var(--ds-size-step, 0) * 8px))) / 2);
  }

  .ds-table__actions .ds-btn--icon:last-child {
    margin-inline-end: calc((var(--ds-space-5) - max(var(--ds-target-min, 0px), calc(var(--ds-btn-icon-size, 40px) + var(--ds-size-step, 0) * 8px))) / 2);
  }

  /* A summary row: label type, one hairline above it, none below; no row
     layers (tbody rules never reach it) and no row link. */
  .ds-table tfoot :is(th, td) {
    border-top: 1px solid var(--ds-line-2);
    border-bottom: 0;
    color: var(--ds-text);
    font: var(--ds-font-label);
    font-variant-numeric: tabular-nums;
  }

  /* Sort button in a header cell. Its 4px padding (the room of its state
     layer) hangs into the cell's padding, so the header keeps its height
     and the label lines up with the cells below. */
  .ds-table__sort {
    position: relative;
    isolation: isolate;
    display: inline-flex;
    align-items: center;
    gap: var(--ds-space-1);
    /* What hangs into the cell: its 4px padding, or under .ds-touch what the
       target adds to the 20px text line (the head keeps its height). */
    --_hang: max(var(--ds-space-1), calc((var(--ds-target-min, 0px) - var(--ds-space-5)) / 2));
    min-height: var(--ds-target-min, 0px);
    margin-block: calc(-1 * var(--_hang));
    margin-inline: calc(-1 * var(--ds-space-1));
    padding: var(--ds-space-1);
    border: 0;
    border-radius: calc(var(--ds-radius-xs) * var(--ds-shape, 1));
    background: transparent;
    color: inherit;
    font: inherit;
    text-align: start;
    white-space: inherit;
    cursor: pointer;
    -webkit-tap-highlight-color: transparent;
    /* The ring rests (invisible) one width further out and snaps in. */
    outline-offset: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    transition: outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-table__sort::before {
    content: '';
    position: absolute;
    inset: 0;
    z-index: -1;
    border-radius: inherit;
    background: currentColor;
    opacity: 0;
    pointer-events: none;
    transition: opacity var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  @media (hover: hover) {
    .ds-table__sort:hover::before {
      opacity: var(--ds-state-hover);
    }
  }

  .ds-table__sort:focus-visible::before {
    opacity: var(--ds-state-focus);
    transition-duration: 0s;
  }

  .ds-table__sort:active::before,
  .ds-table__sort.ds-pressed::before {
    opacity: var(--ds-state-pressed);
    transition-duration: var(--ds-dur-micro);
  }

  .ds-table__sort:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: var(--ds-focus-offset);
  }

  .ds-table__sort > svg {
    flex-shrink: 0;
  }

  /* A sortable column without its arrow keeps the arrow's room (the gap
     and the documented 16px arrow) in its padding, so a sort that moves to
     another column never resizes the columns. Padding, not an empty flex
     item: that would become the inline-flex button's baseline and move it
     down in its row. In a .ds-num column the room leads, as the arrow does. */
  .ds-table__sort:not(:has(> svg)) {
    padding-inline-end: calc(2 * var(--ds-space-1) + 16px);
  }

  /* Opt-in: one up arrow for both directions, which descending turns on
     the spring. An unmarked svg keeps the direction the page drew. */
  .ds-table__sort-arrow {
    transition: rotate var(--ds-dur-medium) var(--ds-ease-spatial);
  }

  .ds-table th[aria-sort="descending"] .ds-table__sort-arrow {
    rotate: 180deg;
  }

  /* A number column sorts with the arrow in front, so the figures keep
     their right edge. */
  .ds-table th.ds-num .ds-table__sort {
    flex-direction: row-reverse;
  }

  .ds-table th.ds-num .ds-table__sort:not(:has(> svg)) {
    padding-inline: calc(2 * var(--ds-space-1) + 16px) var(--ds-space-1);
  }

  .ds-table th:is([aria-sort="ascending"], [aria-sort="descending"]) {
    color: var(--ds-text);
  }

  /*
   * The full-page table: the wrapper is its own card and scrolls both
   * ways, so the header row sticks to its top. Separate borders: a sticky
   * cell keeps its own hairline. Its fades leave the border and the
   * scrollbars opaque: three mask layers, the fade over the padding box
   * (the box inside the border and the scrollbars) added to the ring
   * between the border box and the padding box.
   *
   * Every fade of a table wrapper runs left to right with the scroll
   * (LTR only, D9): the gradients keep their physical directions.
   */
  .ds-table-wrap--fill {
    display: block;
    flex: 1 1 auto;
    min-height: var(--ds-table-fill-min-height, 240px);
    max-height: var(--ds-table-fill-max-height, none);
    overflow: auto;
    overscroll-behavior: contain;
    isolation: isolate;
    border: 1px solid var(--ds-line);
    border-radius: calc(var(--ds-radius-card) * var(--ds-shape, 1));
    background: var(--ds-table-sticky-bg, var(--ds-surface));
    scrollbar-width: thin;
    scrollbar-color: var(--ds-line-2) transparent;
    /* Focus moved by the keyboard never lands under the header (nor, as
       in every wrapper, under the pinned column); what takes focus adds what
       the table's own options add to this. */
    --_kept-head: max(var(--ds-target-min, 0px), calc(var(--ds-table-head-height, 48px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px));
    scroll-padding-block-start: var(--_kept-head);
    mask-image:
      linear-gradient(to right, transparent, #000 calc(var(--ds-scroll-edge-start) * var(--ds-table-start-fade) * var(--ds-scroll-fade, var(--ds-space-8))), #000 calc(100% - var(--ds-scroll-edge-end) * var(--ds-table-end-fade) * var(--ds-scroll-fade, var(--ds-space-8))), transparent),
      linear-gradient(#000, #000),
      linear-gradient(#000, #000);
    mask-origin: padding-box, padding-box, border-box;
    mask-clip: padding-box, padding-box, border-box;
    mask-repeat: no-repeat;
    mask-composite: add, exclude;
  }

  @supports (animation-timeline: scroll()) {
    .ds-table-wrap--fill {
      animation: ds-scroll-edge-start linear both, ds-scroll-edge-end linear both;
      animation-timeline: scroll(self inline);
      animation-range: 0 var(--ds-space-8), calc(100% - var(--ds-space-8)) 100%;
    }
  }

  .ds-table-wrap--fill > .ds-table {
    border-collapse: separate;
    border-spacing: 0;
  }

  .ds-table-wrap--fill > .ds-table > thead th,
  .ds-table--sticky-head > thead th {
    position: sticky;
    inset-block-start: 0;
    z-index: var(--ds-z-sticky);
    background-color: var(--ds-table-sticky-bg, var(--ds-surface));
  }

  /* The summary row at the bottom edge, as the header at the top. */
  .ds-table--sticky-foot > tfoot :is(th, td) {
    position: sticky;
    inset-block-end: 0;
    z-index: var(--ds-z-sticky);
    background-color: var(--ds-table-sticky-bg, var(--ds-surface));
  }

  /* Long cells stay on one line and end in an ellipsis (a tooltip shows a
     cut cell's text). The rings of controls in a cell stay inside its
     padding; the row link's stretched area and the row's ripple belong to
     the row, so the cell does not clip them. */
  .ds-table-wrap--fill td {
    max-width: var(--ds-table-cell-max-width, 280px);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  /*
   * A pinned first column: sticky at the start, above the raised controls
   * of the cells that scroll under it (--ds-z-pinned), on an opaque base.
   * The row's layers would show the scrolled columns through a translucent
   * background colour, so they lie over the base as images of two
   * registered colours: --ds-table-sticky-tint (the selection) and
   * --ds-table-sticky-layer (hover, focus, press) above it.
   * The first cell is named :is(td, th):first-child, never a bare
   * :first-child: a bare one is tried on every element of the page and
   * marks every parent as depending on its first child, so each inserted
   * node restyles its siblings (Chromium: four times the style work of a
   * page load).
   */
  .ds-table--pin-first tbody tr:not(.ds-table__detail) > :is(td, th):first-child,
  .ds-table--pin-first thead th:first-child,
  .ds-table--pin-first tfoot tr > :is(td, th):first-child {
    inset-inline-start: 0;
  }

  .ds-table--pin-last tbody tr:not(.ds-table__detail) > :is(td, th):last-child,
  .ds-table--pin-last thead th:last-child,
  .ds-table--pin-last tfoot tr > :is(td, th):last-child {
    inset-inline-end: 0;
  }

  .ds-table--pin-first tbody tr:not(.ds-table__detail) > :is(td, th):first-child,
  .ds-table--pin-first thead th:first-child,
  .ds-table--pin-first tfoot tr > :is(td, th):first-child,
  .ds-table--pin-last tbody tr:not(.ds-table__detail) > :is(td, th):last-child,
  .ds-table--pin-last thead th:last-child,
  .ds-table--pin-last tfoot tr > :is(td, th):last-child {
    position: sticky;
    z-index: var(--ds-z-pinned);
    background-image:
      linear-gradient(var(--ds-table-sticky-layer), var(--ds-table-sticky-layer)),
      linear-gradient(var(--ds-table-sticky-tint), var(--ds-table-sticky-tint)),
      linear-gradient(var(--ds-table-sticky-bg, var(--ds-surface)), var(--ds-table-sticky-bg, var(--ds-surface)));
    transition:
      background-color var(--ds-dur-fast) var(--ds-ease-in-out),
      --ds-table-sticky-layer var(--ds-dur-fast) var(--ds-ease-in-out),
      --ds-table-sticky-tint var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  /* A body row's pinned cell lays the row's layer and selection over its
     base (the row decides them, as for the other cells). */
  .ds-table--pin-first tbody tr:not(.ds-table__detail) > :is(td, th):first-child,
  .ds-table--pin-last tbody tr:not(.ds-table__detail) > :is(td, th):last-child {
    --ds-table-sticky-layer: var(--ds-table-row-layer);
    --ds-table-sticky-tint: var(--ds-table-row-tint);
    transition:
      background-color var(--ds-table-row-pace) var(--ds-ease-in-out),
      --ds-table-sticky-layer var(--ds-table-row-pace) var(--ds-ease-in-out),
      --ds-table-sticky-tint var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  /* The room of a pinned last cell opens nothing, so it does not say it
     would; its controls keep their own pointer. */
  .ds-table--interactive.ds-table--pin-last tbody tr:not(.ds-table__detail) > :is(td, th):last-child {
    cursor: default;
  }

  /* The row link's ring on this cell (a border, so it stays in forced
     colours); the row decides, the cell paints. */
  .ds-table--interactive.ds-table--pin-last:not(.ds-table--pin-first) tbody tr:not(.ds-table__detail) > :is(td, th):last-child::before {
    content: '';
    position: absolute;
    inset: 0;
    border: var(--ds-table-row-ring);
    border-inline-start: 0;
    pointer-events: none;
  }

  /* The corners, where a sticky row meets a pinned column. */
  .ds-table-wrap--fill > .ds-table--pin-first > thead th:first-child,
  .ds-table-wrap--fill > .ds-table--pin-last > thead th:last-child,
  .ds-table--sticky-head.ds-table--pin-first > thead th:first-child,
  .ds-table--sticky-head.ds-table--pin-last > thead th:last-child,
  .ds-table--sticky-foot.ds-table--pin-first > tfoot tr > :is(td, th):first-child,
  .ds-table--sticky-foot.ds-table--pin-last > tfoot tr > :is(td, th):last-child {
    z-index: var(--ds-z-sticky-pinned);
  }

  /* The hairline at the pinned column's end: it shows once the table has
     scrolled away from its start (the cells under it are cut there).
     Without scroll timelines data-ds-overflow-start shows it. */
  .ds-table--pin-first tbody tr:not(.ds-table__detail) > :is(td, th):first-child::after,
  .ds-table--pin-first thead th:first-child::after,
  .ds-table--pin-first tfoot tr > :is(td, th):first-child::after {
    content: '';
    position: absolute;
    inset-block: 0;
    inset-inline-end: 0;
    width: 1px;
    background: var(--ds-line);
    opacity: 0;
    pointer-events: none;
    transition: opacity var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  .ds-table-wrap[data-ds-overflow-start] > .ds-table--pin-first tbody tr:not(.ds-table__detail) > :is(td, th):first-child::after,
  .ds-table-wrap[data-ds-overflow-start] > .ds-table--pin-first thead th:first-child::after,
  .ds-table-wrap[data-ds-overflow-start] > .ds-table--pin-first tfoot tr > :is(td, th):first-child::after {
    opacity: 1;
  }

  @supports (animation-timeline: scroll()) {
    .ds-table--pin-first tbody tr:not(.ds-table__detail) > :is(td, th):first-child::after,
    .ds-table--pin-first thead th:first-child::after,
    .ds-table--pin-first tfoot tr > :is(td, th):first-child::after {
      animation: ds-scroll-fade linear both;
      animation-timeline: scroll(nearest inline);
      animation-range: 0 var(--ds-space-2);
    }
  }

  /* The hairline at the start of a pinned last column: it shows while
     columns follow under it, and goes over the last of the scroll. Without
     scroll timelines data-ds-overflow-end shows it. */
  .ds-table--pin-last tbody tr:not(.ds-table__detail) > :is(td, th):last-child::after,
  .ds-table--pin-last thead th:last-child::after,
  .ds-table--pin-last tfoot tr > :is(td, th):last-child::after {
    content: '';
    position: absolute;
    inset-block: 0;
    inset-inline-start: 0;
    width: 1px;
    background: var(--ds-line);
    opacity: 0;
    pointer-events: none;
    transition: opacity var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  .ds-table-wrap[data-ds-overflow-end] > .ds-table--pin-last tbody tr:not(.ds-table__detail) > :is(td, th):last-child::after,
  .ds-table-wrap[data-ds-overflow-end] > .ds-table--pin-last thead th:last-child::after,
  .ds-table-wrap[data-ds-overflow-end] > .ds-table--pin-last tfoot tr > :is(td, th):last-child::after {
    opacity: 1;
  }

  @supports (animation-timeline: scroll()) {
    .ds-table--pin-last tbody tr:not(.ds-table__detail) > :is(td, th):last-child::after,
    .ds-table--pin-last thead th:last-child::after,
    .ds-table--pin-last tfoot tr > :is(td, th):last-child::after {
      animation: ds-scroll-fade linear both reverse;
      animation-timeline: scroll(nearest inline);
      animation-range: calc(100% - var(--ds-space-2)) 100%;
    }
  }

  /*
   * The bar of a bulk selection: it stands where the toolbar stood (one
   * .ds-swap slot, DS.motion.crossfade()), so the table never moves. The
   * count says the state, not the tint; it changes at once. The slot keeps
   * the bar's height (.ds-toolbar > .ds-swap: in form.css, the toolbar's
   * own stylesheet, which comes after this one).
   */
  .ds-selection-bar {
    display: flex;
    align-items: center;
    gap: var(--ds-space-2);
    min-height: max(var(--ds-target-min, 0px), calc(var(--ds-selection-bar-height, 48px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px));
    padding-inline: var(--ds-space-1) var(--ds-space-2);
    border-radius: calc(var(--ds-radius-md) * var(--ds-shape, 1));
    background: var(--ds-accent);
    color: var(--ds-on-accent);
  }

  .ds-selection-bar__count {
    margin: 0;
    font: var(--ds-font-label);
    font-variant-numeric: tabular-nums;
  }

  .ds-selection-bar__actions {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--ds-space-2);
    margin-inline-start: auto;
  }

  /*
   * Short cells (numbers, status chips, dates with .ds-nowrap) stay on one
   * line, and text cells keep a readable width instead of breaking word by
   * word. A wide table (.ds-table--wide) drops its secondary columns
   * whenever the content area is narrow, also next to the persistent drawer;
   * on phones every table does. A table that still does not fit scrolls
   * sideways, and a fade at the edge of its card tells that more columns
   * follow (statically: at the right edge, over the card's padding).
   */
  .ds-table td.ds-num,
  .ds-table .ds-status {
    white-space: nowrap;
  }

  .ds-table .ds-col--text {
    min-width: 168px;
  }

  @container ds-content (max-width: 1040px) {
    .ds-table--wide th {
      white-space: normal;
    }

    .ds-table--wide .ds-col--secondary {
      display: none;
    }

    /* In a card the last column still shown takes the card's gutter, as the
       last cell does while every column shows. The sibling :has() stays in
       the cell's own compound; the :where() keeps the rule at the weight of
       a plain card cell, so detail rows and stacked rows keep theirs. */
    .ds-card .ds-table-wrap :where(.ds-table--wide) :is(th, td):where(:not(.ds-col--secondary):not(:has(~ :not(.ds-col--secondary)))) {
      padding-inline-end: var(--ds-card-pad);
    }

    /* The static fade (no scroll timeline, no DS.dom.scrollEdges()); the
       scrollbar strip stays opaque. */
    .ds-card .ds-table-wrap:has(> .ds-table--wide) {
      mask-image: linear-gradient(to left, transparent, #000 calc(var(--ds-table-end-fade) * var(--ds-scroll-fade, var(--ds-card-pad)))), linear-gradient(#000, #000);
      mask-size: 100% calc(100% - var(--ds-scrollbar-height, 0px)), 100% var(--ds-scrollbar-height, 0px);
      mask-position: 0 0, 0 100%;
      mask-repeat: no-repeat;
    }

    /* DS.dom.scrollEdges() attached: a fade on each side that has more. */
    .ds-card .ds-table-wrap:where([data-ds-edges]):has(> .ds-table--wide) {
      mask-image: linear-gradient(to right, transparent, #000 calc(var(--ds-scroll-edge-start) * var(--ds-table-start-fade) * var(--ds-scroll-fade, var(--ds-card-pad))), #000 calc(100% - var(--ds-scroll-edge-end) * var(--ds-table-end-fade) * var(--ds-scroll-fade, var(--ds-card-pad))), transparent), linear-gradient(#000, #000);
    }

    /* Scroll-linked: a fade on each side that still has columns to show
       (the timeline is the wrapper's own inline scroll; the shorthand
       comes first, it resets animation-timeline). */
    @supports (animation-timeline: scroll()) {
      .ds-card .ds-table-wrap:has(> .ds-table--wide) {
