    .ds-table--pin-first thead th:first-child,
    .ds-table--pin-first tfoot tr > :is(td, th):first-child,
    .ds-table--pin-last tbody tr:not(.ds-table__detail) > :is(td, th):last-child,
    .ds-table--pin-last thead th:last-child,
