  /*
   * Input group: a unit or prefix inside the field (an aria-hidden
   * .ds-input-group__prefix or __suffix; the unit is in the label too) or a trailing
   * quiet icon button (a password reveal with aria-pressed). The group
   * draws the field (border, radius, background, height); the input inside
   * loses its box. The ring moves to the group while the input has the
   * focus, appearing at once and fading back on blur like a field's; a
   * focused trailing button shows its own ring instead. Invalid and
   * disabled (or read-only) follow the input.
   */
  .ds-input-group {
    /* The options, as on .ds-input: the group draws the field. */
    --_h: calc(var(--ds-input-height, 40px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px);
    --_box: max(var(--ds-target-min, 0px), var(--_h));
    --_radius: min(calc(var(--ds-input-radius, var(--ds-radius-field)) * var(--ds-shape, 1)), calc(var(--_box) / 2));
    --_px: calc(var(--ds-input-padding-x, var(--ds-space-3)) + var(--ds-size-step, 0) * 4px);
    display: flex;
    align-items: center;
    gap: var(--ds-space-2);
    min-width: 0;
    min-height: var(--_box);
    padding-inline: var(--_px);
    border: 1px solid var(--_field-state, var(--ds-input-border, var(--ds-outline)));
    border-radius: var(--_radius);
    background: var(--ds-input-bg, var(--ds-surface));
    color: var(--ds-text);
    transition:
      border-color var(--ds-dur-fast) var(--ds-ease-in-out),
      background-color var(--ds-dur-fast) var(--ds-ease-in-out),
      box-shadow var(--ds-dur-fast) var(--ds-ease-in-out);
