    padding-inline-end: var(--ds-space-1);
  }

  .ds-input-group > .ds-input,
  .ds-input-group > .ds-input:focus,
  .ds-input-group > .ds-input:focus-within {
    flex: 1 1 auto;
    align-self: stretch;
    min-width: 0;
    min-height: 0;
    padding-block: 0;
    padding-inline: 0;
    border: 0;
    border-radius: 0;
    background: transparent;
    box-shadow: none;
