    pointer-events: none;
  }

  .ds-input-group:has(> .ds-input-group__trailing:last-child > .ds-btn:last-child) {
    padding-inline-end: var(--ds-space-1);
  }

  .ds-input-group__prefix,
  .ds-input-group__suffix {
    flex: none;
    color: var(--ds-text-2);
    font: var(--ds-input-font, var(--ds-size-font, var(--ds-font-body)));
    font-weight: var(--ds-input-weight, var(--ds-weight-regular));
    user-select: none;
