    content: '';
    grid-area: 1 / 1 / 3 / 2;
    /* Spanning both rows, it holds the box at the touch minimum. */
    min-height: var(--ds-target-min, 0px);
    border: 1px solid transparent;
    border-start-start-radius: var(--_inset-radius);
    border-start-end-radius: var(--_inset-radius);
    background: var(--ds-surface-high);
    box-shadow: inset 0 -1px 0 0 var(--_field-state, var(--ds-input-border, var(--ds-outline)));
    pointer-events: none;
    transition:
