      box-shadow var(--ds-dur-fast) var(--ds-ease-in-out);
    box-sizing: border-box;
  }

  .ds-field--inset > .ds-field__label {
    grid-area: 1 / 1;
    padding: var(--_inset-y) var(--_inset-x) 0;
