  .ds-field--inset > .ds-input:focus,
  .ds-field--inset > .ds-input:focus-within {
    grid-area: 2 / 1;
    min-height: 0;
    padding-block: var(--ds-space-1) var(--_inset-y);
    padding-inline: var(--_inset-x);
    border: 0;
    border-radius: 0;
    background-color: transparent;
    box-shadow: none;
  }

  /* The room of the triangle (physical, like the rule it stands in for). */
  .ds-field--inset > select.ds-input,
  .ds-field--inset > select.ds-input:focus,
  .ds-field--inset > input.ds-input[list],
  .ds-field--inset > input.ds-input[list]:focus {
    padding-right: calc(var(--_px) + var(--ds-space-5));
  }

  /* An input group inside: the slots in the value's row, the group's own box
     gone. */
  .ds-field--inset > .ds-input-group,
  .ds-field--inset > .ds-input-group:has(> .ds-input:focus) {
    grid-area: 2 / 1;
    min-height: 0;
    padding-block: var(--ds-space-1) var(--_inset-y);
    padding-inline: var(--_inset-x);
    border: 0;
    border-radius: 0;
    background-color: transparent;
    box-shadow: none;
  }

