  .ds-field--inset > .ds-field__foot {
    margin-block-start: var(--ds-space-1);
    padding-inline: var(--_inset-x);
  }

  .ds-field--inset > .ds-field__hint:empty {
    margin-block-start: 0;
  }

  @media (hover: hover) {
    .ds-field--inset:hover:not(:focus-within, :has(> .ds-input:is(:disabled, [readonly], [aria-readonly="true"])), :has(> .ds-input-group > .ds-input:is(:disabled, [readonly], [aria-readonly="true"])))::before {
      background-color: var(--ds-surface-highest);
