  :is(.ds-check input[type="radio"], .ds-radio input, .ds-radio-input):checked {
    border-color: var(--ds-primary);
    color: var(--ds-primary);
  }

  :is(.ds-check input[type="checkbox"], .ds-table input[type="checkbox"]:where(:not(.ds-switch *, .ds-chip *)), .ds-checkbox):is(:checked, :indeterminate) {
    background: var(--ds-primary);
