    transition: clip-path var(--ds-dur-fast) var(--ds-ease-in);
  }

  :is(.ds-check input[type="checkbox"], .ds-table input[type="checkbox"]:where(:not(.ds-switch *, .ds-chip *)), .ds-checkbox):indeterminate::after {
    clip-path: inset(0);
    transition: clip-path var(--ds-dur-medium) var(--ds-ease-out);
