    }

    .ds-app--drawer[data-drawer-collapsed] .ds-drawer__back::after,
    .ds-app--drawer[data-drawer-collapsed] .ds-drawer__foot--pinned::before {
      margin-inline: var(--ds-space-2);
    }

    .ds-app--drawer:not([data-drawer-hidden]) .ds-topbar__menu[aria-pressed] {
      display: inline-flex;
    }

    .ds-app--drawer:not([data-drawer-hidden]) .ds-topbar:has(> .ds-topbar__menu[aria-pressed]) {
      padding-left: max(calc(var(--ds-drawer-icon-axis) - var(--_menu) / 2), env(safe-area-inset-left));
    }

    /* A brand of only a name: its text starts on the icons' edge (the
       axis less half a 20px icon) instead of a 32px mark centring there.
       The name as the brand's only child, not a :has() inside the :has()
       (no engine allows that nesting; it would drop the rule). */
    .ds-app--drawer:not([data-drawer-hidden]) .ds-topbar:has(> .ds-brand:first-child > .ds-brand__name:only-child, > .ds-topbar__menu:not([aria-pressed]):first-child + .ds-brand > .ds-brand__name:only-child) {
      padding-left: max(calc(var(--ds-drawer-icon-axis) - 10px), env(safe-area-inset-left));
    }
  }

  /* The docked drawer's way up stands in for the page head's back link:
     the page shows one of them (the exact complement of the modal query). */
  @media (width > 900px) {
    .ds-app--drawer:not([data-drawer-hidden]):has(> .ds-drawer .ds-drawer__back .ds-drawer__item) .ds-page-head__back {
      display: none;
    }
  }

  /* Between phone and docked drawer, a bar without the drawer starts where
     the panel does. */
  @media (min-width: 601px) and (max-width: 900px) {
    .ds-app:not(.ds-app--drawer) .ds-topbar,
    .ds-app--drawer[data-drawer-hidden] .ds-topbar {
      padding-left: max(var(--ds-space-4), env(safe-area-inset-left));
    }
  }

  /* Fade-through, outgoing half: quick and accelerating. Leaving the state
     snaps back without a transition, the incoming content enters itself.
     Deprecated in 2.0 (removed in 3.0 at the earliest) with its manual swap
     recipe: DS.motion.transition() replaces both. */
  .ds-view--leaving > * {
    opacity: 0;
    transition: opacity var(--ds-dur-instant) var(--ds-ease-in);
  }

  /*
   * View transitions (DS.motion.transition() writes data-ds-vt on <html>
   * while one runs; motion.css plays them). Only then are these named, so
   * a page without a transition carries no names. The view is its own
   * group and the top bar has none: it stays in the root snapshot, whose
   * crossfade leaves unchanged pixels still. The panel's name serves the
   * morph of a view without the drawer; the docked drawer is named for its
   * exit and return there. The modal drawer is never named: while it is
   * open or leaving, DS.motion.transition() lifts these names, so the view
   * crossfades in the root under it (close it inside the update).
   */
  .ds-theme[data-ds-vt] .ds-view {
    view-transition-name: ds-view;
  }

  .ds-theme[data-ds-vt] .ds-panel {
    view-transition-name: ds-panel;
  }

  @media (min-width: 901px) {
    .ds-theme[data-ds-vt] .ds-drawer {
      view-transition-name: ds-drawer;
    }
  }

  /* ── Modal drawer ─────────────────────────────── */

  /* A script that moves focus into the modal drawer uses the same query:
     (max-width: 900px). */
  @media (max-width: 900px) {
    .ds-app--drawer {
      grid-template-columns: minmax(0, 1fr);
      grid-template-areas:
        "top"
        "main";
    }

    .ds-app--drawer .ds-panel {
      margin-left: max(var(--ds-space-4), env(safe-area-inset-left));
    }

    .ds-app--drawer .ds-topbar {
      padding-left: max(var(--ds-space-2), env(safe-area-inset-left));
    }

    .ds-topbar__menu {
      display: inline-flex;
    }

    /* Physical on purpose (D9): the modal drawer slides in from the left
       edge (mirrored motion is not part of 2.0), so its corners, its bleed
       and its safe-area inset stay on that side. */
    .ds-drawer {
      position: fixed;
      top: 0;
      bottom: 0;
      left: 0;
      z-index: var(--ds-z-drawer);
      width: min(calc(var(--ds-drawer-width) + env(safe-area-inset-left)), calc(100vw - 56px));
      padding-top: env(safe-area-inset-top);
      border-radius: 0 calc(var(--ds-radius-dialog) * var(--ds-shape, 1)) calc(var(--ds-radius-dialog) * var(--ds-shape, 1)) 0;
      box-shadow: var(--ds-elev-overlay);
      /* Invisible, but forced colors drop fill, shadow and scrim and paint
         it: the sheet keeps an edge against the page, on its own edge
         whatever offset a page base gives focusable elements. */
      outline: 1px solid transparent;
      outline-offset: 0;
      /* An opaque sheet: it only slides on the spring, the scrim does the
         fading; the bleed covers the overshoot. Closing accelerates out in
         --ds-dur-base (0.44 of the entrance). A state change mid-flight
         starts the other transition from where the sheet is, on the curve
         of the new direction. */
      visibility: hidden;
      transform: translateX(calc(-1 * var(--ds-distance-sheet)));
      transition:
        transform var(--ds-dur-base) var(--ds-ease-exit),
        visibility 0ms linear var(--ds-dur-base);
    }

    .ds-app[data-drawer-open] .ds-drawer {
      visibility: visible;
      transform: none;
      transition:
        transform var(--ds-dur-long) var(--ds-ease-spatial),
        visibility 0ms;
    }

    /* Bleed: the spring carries the sheet a little past x = 0 (about 3 % of
       its width, at most 5 %); this strip of its own background left of it
       keeps the scrim from showing at the screen edge. The fixed drawer is
       its containing block, so it is off screen at rest and hidden with the
       drawer. It reaches 1px under the drawer's edge, so no antialiased seam
       lets the shadow through while the edge sits between pixels. */
    .ds-drawer::before {
      content: '';
      position: absolute;
      top: 0;
      bottom: 0;
      right: calc(100% - 1px);
      width: calc(var(--ds-space-8) + 1px);
      background: inherit;
      pointer-events: none;
    }

    /* The modal drawer is closed whenever the active item changes: the pill
       only has to be in place when it opens again, not glide while it leaves. */
    .ds-drawer .ds-drawer__indicator {
      transition: none;
    }

    /* Its labels change colour at once with it: the lists of the items
       without the colour entry. */
    .ds-drawer .ds-drawer__item {
      transition:
        border-radius var(--ds-dur-medium) var(--ds-ease-spatial),
        outline-offset var(--ds-dur-fast) var(--ds-ease-out);
    }

    .ds-drawer .ds-has-indicator .ds-drawer__item:active:not(:disabled, [aria-disabled="true"], [aria-busy="true"]),
    .ds-drawer .ds-has-indicator .ds-drawer__item.ds-pressed:not(:disabled, [aria-disabled="true"], [aria-busy="true"]) {
      transition:
        border-radius var(--ds-dur-micro) var(--ds-ease-out),
        outline-offset var(--ds-dur-fast) var(--ds-ease-out);
    }

    .ds-drawer .ds-drawer__item svg {
      transition: none;
    }

    /* Also while the item a click has just made active is still pressed;
       the press morph of the pill stays. */
    .ds-drawer .ds-has-indicator:has(.ds-drawer__item[aria-current="page"]:active:not(:disabled, [aria-disabled="true"], [aria-busy="true"])) > .ds-drawer__indicator,
    .ds-drawer .ds-has-indicator:has(.ds-drawer__item[aria-current="page"].ds-pressed:not(:disabled, [aria-disabled="true"], [aria-busy="true"])) > .ds-drawer__indicator {
      transition: --ds-indicator-radius var(--ds-dur-micro) var(--ds-ease-out);
    }

    /* The lock-up stays where the top bar shows it (menu button inset,
       the button's box, gap), so it does not jump while the drawer slides
       over. */
    .ds-drawer__head {
      display: flex;
      align-items: center;
      gap: var(--ds-space-3);
      flex-shrink: 0;
      height: var(--ds-topbar-height);
      padding-block: 0;
      padding-inline: calc(var(--ds-space-2) + max(var(--ds-target-min, 0px), calc(var(--ds-btn-icon-size, 40px) + var(--ds-size-step, 0) * 8px)) + var(--ds-space-2)) var(--ds-space-6);
    }

    .ds-scrim {
      display: block;
      position: fixed;
      inset: 0;
      z-index: var(--ds-z-drawer);
      background: var(--ds-scrim);
      visibility: hidden;
      opacity: 0;
      transition:
        opacity var(--ds-dur-base) var(--ds-ease-in),
        visibility 0ms linear var(--ds-dur-base);
    }

    /* The scrim fades in the same frame as the sheet starts. */
    .ds-app[data-drawer-open] .ds-scrim {
      visibility: visible;
      opacity: 1;
      transition:
        opacity var(--ds-dur-medium) var(--ds-ease-in-out),
        visibility 0ms;
    }

    /* The window crosses 900px: the drawer turns modal (or back) in place,
       without a slide or a scrim fade. The page sets the class for two
       frames (docs/components.md); the scrim comes before the drawer, so
       :has() reaches it. As specific as the open rules above, and later. */
    .ds-app .ds-drawer.ds-drawer--instant,
    .ds-app:has(> .ds-drawer--instant) > .ds-scrim {
      transition: none;
    }
  }

  /* The avatar names the person, so the text goes entirely (screen readers
     would hear the name twice). */
  @media (max-width: 720px) {
    .ds-account__text {
      display: none;
    }

    .ds-account__avatar {
      display: grid;
    }

    /* Only the avatar shows: without a button the capsule is round. */
    .ds-account--capsule:not(:has(> .ds-btn:not([hidden]))) {
      padding-inline-end: var(--ds-space-2);
    }

    /* The page offers its search in the view instead. */
    .ds-topbar__search {
      display: none;
    }

    .ds-view {
      --ds-content-pad-top: var(--ds-space-5);
      --ds-content-pad-x: var(--ds-space-4);
    }
  }

  /* 320px (400% zoom): no room for brand, avatar and sign-out. Without the
     avatar, name and email stay for screen readers, visually hidden. */
  @media (max-width: 359px) {
    .ds-account__avatar {
      display: none;
    }

    .ds-account__text {
      display: block;
      position: absolute;
      width: 1px;
      height: 1px;
      overflow: hidden;
      clip-path: inset(50%);
      white-space: nowrap;
    }
  }

  /* Phones: the panel spans the width, its rounded top stays. */
  @media (max-width: 600px) {
    .ds-panel,
    .ds-app--drawer .ds-panel,
    .ds-app--drawer[data-drawer-hidden] .ds-panel {
      margin: 0;
    }

    .ds-view {
      --ds-content-pad-bottom: calc(var(--ds-space-4) + var(--ds-toast-room) + var(--ds-space-2));
      padding-left: env(safe-area-inset-left);
      padding-right: env(safe-area-inset-right);
    }

    .ds-topbar,
    .ds-app--drawer[data-drawer-hidden] .ds-topbar {
      padding-left: max(var(--ds-space-4), env(safe-area-inset-left));
    }

    /* The brand gives way to the mode switch: the mark stays. */
    .ds-segmented ~ .ds-account .ds-account__text,
    .ds-app--drawer .ds-brand__name {
      display: none;
    }

    /* A brand of only a name keeps it: it has nothing else to show. */
    .ds-app--drawer .ds-brand:not(:has(> :not(.ds-brand__name))) .ds-brand__name {
      display: inline;
    }

    .ds-topbar .ds-segmented {
      margin-inline-start: var(--ds-space-2);
    }

    /* A title in the bar takes the brand's room: two lines of the label
       role; the brand keeps its mark (a brand of only a name goes). */
    .ds-topbar__title {
      display: -webkit-box;
      font: var(--ds-font-label);
      white-space: normal;
      -webkit-box-orient: vertical;
      -webkit-line-clamp: 2;
    }

    .ds-topbar:has(.ds-topbar__title) .ds-brand__name,
    .ds-topbar:has(.ds-topbar__title) .ds-brand:not(:has(> :not(.ds-brand__name))) {
      display: none;
    }
  }

  /*
   * ── 3.0: the frame's behaviours (shell.js) ───────
   *
   * Drawer filter: a search field between the actions and the list
   * (data-ds-drawer filters the list's items by their labels). Filtered
   * items, rows and groups take no room (data-ds-filtered, written by the
   * module, never by the page); .ds-drawer__empty says there is no match.
   * The rail has no room for the field: it goes there.
   */
  .ds-drawer__search {
    flex-shrink: 0;
    padding: var(--ds-space-1) var(--ds-space-3) var(--ds-space-2);
  }

  .ds-drawer [data-ds-filtered] {
    display: none;
  }

  .ds-drawer__empty {
    margin: 0;
    padding: var(--ds-space-3) var(--ds-space-4);
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
  }

  /* A badge (badge.css) at the end of an item or a group toggle: the place
     of a count, which it may replace when the count is news (unread). */
  .ds-drawer__item > .ds-badge,
  .ds-drawer__toggle > .ds-badge {
    margin-inline-start: auto;
  }

  @media (min-width: 901px) {
    .ds-app--drawer[data-drawer-collapsed] .ds-drawer__search {
      display: none;
    }

    /* On the rail a badge shrinks to a dot on the icon's corner, inside the
       square (a ripple host clips what lies outside it). Its figure stays
       in the markup and is read with the label; the dot takes the primary
       colour (a tone's full colour), which holds 3:1 on the backdrop. */
    .ds-app--drawer[data-drawer-collapsed] .ds-drawer__item > .ds-badge {
      position: absolute;
      inset-block-start: var(--ds-space-2);
      inset-inline-end: var(--ds-space-2);
      min-width: 0;
      width: var(--ds-badge-dot-size, var(--ds-space-2));
      height: var(--ds-badge-dot-size, var(--ds-space-2));
      padding: 0;
      overflow: hidden;
      border-radius: 50%;
      background: var(--ds-primary);
      color: transparent;
    }

    .ds-app--drawer[data-drawer-collapsed] .ds-drawer__item > .ds-badge:is(.ds-tone-neutral, .ds-tone-primary, .ds-tone-info, .ds-tone-success, .ds-tone-warning, .ds-tone-error) {
      background: var(--ds-tone);
    }
  }

  /*
   * The notification slot: an icon button of .ds-topbar__actions (the
   * notification centre opens from it) carries a .ds-badge--dot on its
   * icon's corner, inside its box (a ripple host clips what lies outside
   * it). The dot's word sits in its .ds-sr ("3 unread"), and the button's
   * name says it too.
   */
  .ds-topbar__actions .ds-btn--icon > .ds-badge--dot {
    position: absolute;
    inset-block-start: calc(50% - 10px);
    inset-inline-end: calc(50% - 10px);
    pointer-events: none;
  }

  /*
   * Account menu: the avatar in a quiet icon button (its state layer, ring,
   * ripple and target) opens a .ds-menu with the name and email at its
   * head (aria-hidden: the menu is named by them through aria-labelledby),
   * the theme switch (data-ds-scheme-switch: light, dark, auto) and sign
   * out. The trigger shows its disc at every width.
   */
  .ds-account__trigger .ds-account__avatar,
  .ds-account__head .ds-account__avatar {
    display: grid;
  }

  /* The trigger is a target of its own: it never shrinks. */
  .ds-account:has(> .ds-account__trigger) {
    flex: none;
  }

  /* A phone's bar full of actions: a brand of only a name ends in an
     ellipsis rather than pushing the account out (a mark stays whole). */
  @media (max-width: 600px) {
    .ds-topbar:has(> .ds-topbar__actions) > .ds-brand:not(:has(> :not(.ds-brand__name))) {
      flex-shrink: 1;
    }

    .ds-topbar:has(> .ds-topbar__actions) > .ds-brand:not(:has(> :not(.ds-brand__name))) > .ds-brand__name {
      min-width: 0;
      overflow: hidden;
      text-overflow: ellipsis;
    }
  }

  .ds-account__menu {
    width: min(var(--ds-account-menu-width, 280px), calc(100vw - 2 * var(--ds-space-2)));
    max-width: none;
  }

  .ds-account__head {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr);
    align-items: center;
    column-gap: var(--ds-space-3);
    padding: var(--ds-space-2) var(--ds-space-4) var(--ds-space-3);
  }

  .ds-account__head .ds-account__avatar {
    grid-row: span 2;
  }

  .ds-account__head :is(.ds-account__name, .ds-account__email) {
    text-align: start;
  }

  /*
   * App launcher: a .ds-menu laid out as a grid of apps (data-ds-launcher
   * adds the arrow keys of two dimensions). Each app is a menu item: an
   * icon on a tonal disc over a label of up to two lines; the current app
   * (aria-current="true") takes the tint on its disc and the label weight,
   * never colour alone.
   */
  .ds-launcher {
    display: grid;
    grid-template-columns: repeat(var(--ds-launcher-columns, 3), minmax(0, 1fr));
    gap: var(--ds-space-1);
    width: min(calc(var(--ds-launcher-columns, 3) * var(--ds-launcher-app-width, 96px) + 2 * var(--ds-space-2)), calc(100vw - 2 * var(--ds-space-2)));
    max-width: none;
    padding: calc(var(--ds-space-2) + var(--ds-density, 0) * 2px) var(--ds-space-2);
  }

  /* The edge shades and the parts that are no app span a whole row. */
  .ds-launcher::before,
  .ds-launcher::after,
  .ds-launcher > :not(.ds-menu__item) {
    grid-column: 1 / -1;
  }

  .ds-launcher__app {
    --_h: calc(var(--ds-launcher-app-height, 88px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px);
    flex-direction: column;
    justify-content: center;
    gap: var(--ds-space-1);
    min-height: max(var(--ds-target-min, 0px), var(--_h));
    /* Density takes its 4px off the padding too, so the content never
       holds the app taller than the step. */
    padding: calc(var(--ds-space-2) + var(--ds-density, 0) * 2px) var(--ds-space-1);
    border-radius: calc(var(--ds-radius-sm) * var(--ds-shape, 1));
    font: var(--ds-launcher-font, var(--ds-size-font, var(--ds-font-body)));
    font-weight: var(--ds-weight-regular);
    text-align: center;
  }

  .ds-launcher__app::before {
    border-radius: inherit;
  }

  .ds-launcher__icon {
    --_size: calc(var(--ds-launcher-icon-size, 40px) + var(--ds-size-step, 0) * 8px);
    display: grid;
    flex: none;
    place-items: center;
    width: var(--_size);
    height: var(--_size);
    border-radius: min(calc(min(var(--ds-radius-action), calc(var(--_size) / 2)) * var(--ds-shape, 1)), calc(var(--_size) / 2));
    background: var(--ds-surface-high);
    color: var(--ds-primary);
  }

  .ds-launcher__icon > svg {
    color: inherit;
  }

  .ds-launcher__label {
    display: -webkit-box;
    max-width: 100%;
    overflow: hidden;
    overflow-wrap: anywhere;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 2;
  }

  .ds-launcher__app[aria-current="true"] {
    font-weight: var(--ds-weight-label);
  }

  .ds-launcher__app[aria-current="true"] .ds-launcher__icon {
    background: var(--ds-accent);
    color: var(--ds-on-accent);
  }

  /*
   * Phone search: at 720px and below the bar's search is a sheet over the
   * whole frame, opened by .ds-topbar__search-open (data-ds-search-sheet,
   * DS.overlay). Its head is a back button and the field on the bar's
   * height; .ds-topbar__results below holds what the page shows for the
   * query and scrolls. It fades in while it slides down by
   * --ds-distance-md on the spring (--ds-dur-medium) and fades out faster
   * (--ds-dur-fast); data-state drives it, so a close mid-way turns back
   * from where it is. The bar takes the dialog layer meanwhile, so nothing
   * of the page paints over the sheet; the snackbars stay above.
   */
  .ds-topbar__search-open,
  .ds-topbar__search-back,
  .ds-topbar__results {
    display: none;
  }

  @media (max-width: 720px) {
    .ds-topbar__search-open {
      display: inline-flex;
    }
  }

  /* Open (DS.overlay writes data-state; the module opens it only at 720px
     and below, and closes it when the window widens). */
  .ds-topbar:has(> .ds-topbar__search[data-state]) {
    z-index: var(--ds-z-dialog);
  }

  .ds-topbar__search[data-state] {
    position: fixed;
    inset: 0;
    /* Above the bar's own positioned parts (its buttons), which follow it. */
    z-index: var(--ds-z-raised);
    display: grid;
    grid-template-columns: auto minmax(0, 1fr);
    grid-template-rows: var(--ds-topbar-height) minmax(0, 1fr);
    align-items: center;
    column-gap: var(--ds-space-1);
    max-width: none;
    margin: 0;
    padding-block: env(safe-area-inset-top) 0;
    padding-inline: max(var(--ds-space-2), env(safe-area-inset-left)) max(var(--ds-space-4), env(safe-area-inset-right));
    background: var(--ds-surface);
    /* Invisible; forced colours paint it, so the sheet keeps an edge. */
    outline: 1px solid transparent;
    transition:
      opacity var(--ds-dur-medium) var(--ds-ease-in-out),
      translate var(--ds-dur-medium) var(--ds-ease-spatial);
  }

  .ds-topbar__search[data-state="closed"] {
    opacity: 0;
    translate: 0 calc(-1 * var(--ds-distance-md));
    pointer-events: none;
    transition:
      opacity var(--ds-dur-fast) var(--ds-ease-in),
      translate var(--ds-dur-fast) var(--ds-ease-in);
  }

  .ds-topbar__search[data-state] .ds-topbar__search-back {
    display: inline-flex;
  }

  .ds-topbar__search[data-state] .ds-topbar__results {
    position: relative;
    display: block;
    grid-column: 1 / -1;
    align-self: stretch;
    min-height: 0;
    overflow-y: auto;
    padding-block: var(--ds-space-2) max(var(--ds-space-4), env(safe-area-inset-bottom));
    scrollbar-width: thin;
    scrollbar-color: var(--ds-line-2) transparent;
  }

  /*
   * Breadcrumbs that fold (data-ds-breadcrumbs; page.css draws the trail):
   * the crumbs that do not fit go into a menu behind .ds-breadcrumbs__more,
   * a small quiet icon button after the first crumb (the middle first, then
   * the first, then the parent; the current page never). The module marks
   * them data-ds-collapsed; the chevron goes before the first crumb that
   * shows. It replaces page.css's narrow rule (only the parent) with the
   * measured fold.
   */
  .ds-breadcrumbs[data-ds-breadcrumbs] li:not([data-ds-collapsed]) {
    display: flex;
  }

  .ds-breadcrumbs[data-ds-breadcrumbs] li[data-ds-collapsed] {
    display: none;
  }

  .ds-breadcrumbs[data-ds-breadcrumbs] li::before {
    content: none;
  }

  .ds-breadcrumbs[data-ds-breadcrumbs] li:not([data-ds-collapsed]) ~ li:not([data-ds-collapsed])::before {
    content: '';
  }

  .ds-breadcrumbs__more {
    flex: none;
  }

  /*
   * Forced colors (Windows contrast themes) drop the pill's fill: the
   * current destination and the selected option paint the selection
   * themselves, a choice in a set (SelectedItem, D8); the outline stays for
   * focus, a CanvasText ring inside that fill. Every icon follows the
   * forced text colour of its control (src/core/global.css); status stays
   * readable through the text that always goes with it.
   */
  @media (forced-colors: active) {
    /* The forced canvas would paint the tint over nothing: the bar stays
       flat (the hairline still marks the scrolled view). */
    .ds-topbar::before {
      display: none;
    }

    /* The shades would keep their gradient in the theme's surface colour:
       their opacity goes, the room they hold stays. */
    .ds-drawer__list::before,
    .ds-drawer__list::after {
      visibility: hidden;
    }

    .ds-drawer__indicator,
    .ds-segmented__indicator {
      display: none;
    }

    .ds-drawer__item[aria-current="page"],
    .ds-has-indicator .ds-drawer__item[aria-current="page"],
    .ds-segmented__option:is([aria-current="true"], [aria-checked="true"], [aria-pressed="true"]),
    .ds-has-indicator > .ds-segmented__option:is([aria-current="true"], [aria-checked="true"], [aria-pressed="true"]) {
      forced-color-adjust: none;
      background: SelectedItem;
      color: SelectedItemText;
    }

    .ds-drawer__item[aria-current="page"]:focus-visible,
    .ds-segmented__option:is([aria-current="true"], [aria-checked="true"], [aria-pressed="true"]):focus-visible {
      outline-color: CanvasText;
    }

    .ds-drawer__item[aria-disabled="true"],
    .ds-segmented__option:is(:disabled, [aria-disabled="true"]) {
      color: GrayText;
    }

    /* A sibling lying over the current row's fill: the forced button ink
       could match that fill, so it takes the fill's own ink. */
    .ds-drawer__row:has(> .ds-drawer__item[aria-current="page"]) > .ds-drawer__action {
      forced-color-adjust: none;
      color: SelectedItemText;
      outline-color: CanvasText;
    }

    /* The current app is a choice in a set; a launcher's discs keep their
       edges where fills are gone. */
    .ds-launcher__app[aria-current="true"] {
      forced-color-adjust: none;
      background: SelectedItem;
      color: SelectedItemText;
    }

    .ds-launcher__app[aria-current="true"] .ds-launcher__icon {
      background: transparent;
      color: inherit;
    }

    .ds-launcher__app[aria-current="true"]:focus-visible {
      outline-color: CanvasText;
    }

    .ds-launcher__icon {
      outline: 1px solid transparent;
    }

    /* A rail badge is a dot: the system's highlight. */
    .ds-app--drawer[data-drawer-collapsed] .ds-drawer__item > .ds-badge {
      forced-color-adjust: none;
      background: Highlight;
    }

    /* The disc keeps its edge where its fill is gone. */
    .ds-account__avatar {
      outline: 1px solid transparent;
    }
  }

  @media print {
    .ds-app {
      display: block;
      height: auto;
      background: var(--ds-surface);
    }

    .ds-topbar,
    .ds-drawer,
    .ds-scrim,
    .ds-skip,
    .ds-banner {
      display: none;
    }

    .ds-panel,
    .ds-view {
      display: block;
      height: auto;
      margin: 0;
      overflow: visible;
      border-radius: 0;
    }

    .ds-view::before {
      display: none;
    }

    /* Paper has no "on its way out": what is shown prints in full. */
    .ds-stale {
      opacity: 1;
    }

    /* A short card, a tile, an alert, a key-value row or a fact stays on
       one page. A card that holds a table may break (card.css): pushed
       whole to the next page inside a grid, it would print over the
       blocks after it. */
    .ds-card:not(:has(.ds-table-wrap, .ds-table)),
    .ds-tile,
    .ds-alert,
    .ds-kv-list li,
    .ds-facts > div {
      break-inside: avoid;
    }
  }
}

/* ── components/tabs/tabs.css ── */
/*
 * Tabs: sections of one page or record. The selected tab takes the primary
 * ink, the label weight and an indicator that glides between the tabs
 * (js/indicator.js); selected is indicator, weight and ARIA, never colour
 * alone.
 *
 *   <div class="ds-tabs" role="tablist" aria-label="Device">
 *     <button class="ds-tabs__tab" role="tab" type="button" id="t-overview" aria-selected="true" aria-controls="p-overview" data-label="Overview">Overview</button>
 *     <button class="ds-tabs__tab" role="tab" type="button" id="t-activity" aria-selected="false" aria-controls="p-activity" tabindex="-1" data-label="Activity">Activity<span class="ds-tabs__count"><span class="ds-sr">, </span>3</span></button>
 *   </div>
 *   <div class="ds-tabs__panel" role="tabpanel" id="p-overview" aria-labelledby="t-overview" tabindex="0"> ... </div>
 *   <div class="ds-tabs__panel" role="tabpanel" id="p-activity" aria-labelledby="t-activity" tabindex="0" hidden> ... </div>
 *
 *   Link tabs (navigation between pages of a record):
 *   <nav class="ds-tabs" aria-label="Device">
 *     <a class="ds-tabs__tab" href="/devices/42" aria-current="page" data-label="Overview">Overview</a> ...
 *   </nav>
 *
 *   A tab that closes (a wrapper, so the close button is no child of the tab;
 *   the button is for the pointer alone: a tablist owns only tabs, so it is
 *   hidden from the accessibility tree, and the tab's panel holds a named
 *   close action for the others, a screen reader on a touch screen above all):
 *   <span class="ds-tabs__item" role="none">
 *     <button class="ds-tabs__tab" role="tab" aria-keyshortcuts="Delete" ... data-label="Report">Report</button>
 *     <button class="ds-btn ds-btn--quiet ds-btn--icon ds-xs ds-tabs__close" type="button" tabindex="-1" aria-hidden="true" data-tip="Close">(close 16)</button>
 *   </span>
 *   <div class="ds-tabs__panel" ...> ... <button class="ds-btn ds-btn--text" type="button">Close Report</button></div>
 *
 *   Vertical, beside its panels:
 *   <div class="ds-tabs__columns">
 *     <div class="ds-tabs ds-tabs--vertical" role="tablist" aria-orientation="vertical" aria-label="Settings"> tabs </div>
 *     <div> panels </div>
 *   </div>
 *
 *   The behaviour (tabs.js, DS.tabs): data-ds-tabs on the row selects,
 *   moves the one tab stop, shows the panels, glides the indicator and
 *   closes tabs; the page listens to ds:change, ds:close and ds:add.
 *   <div class="ds-tabs" role="tablist" aria-label="Device" data-ds-tabs> ... </div>
 *
 *   A bar around the row, for a row that overflows into a "More" menu
 *   (data-ds-tabs-overflow) and for an add button; the hairline is the bar's:
 *   <div class="ds-tabs__bar">
 *     <div class="ds-tabs" role="tablist" aria-label="Reports" data-ds-tabs data-ds-tabs-overflow> ... </div>
 *     <button class="ds-btn ds-btn--quiet ds-btn--icon ds-tabs__add" type="button" aria-label="New report">(plus 20)</button>
 *   </div>
 *   The module writes the More button after the row (a quiet button,
 *   .ds-tabs__more, "More" and a chevron) and its .ds-menu; the tabs that do
 *   not fit carry hidden.
 *
 *   By hand, without the module (2.x):
 *   DS.indicator.create(tabs, { active: '[aria-selected="true"], [aria-current="page"]', className: 'ds-tabs__indicator' })
 *   DS.dom.roving(tabs)   (arrow keys, Home, End; the page's click handler selects;
 *                          vertical: { orientation: 'vertical' })
 *
 * data-label (the tab's text again) reserves the width of the heavier
 * selected weight, so a selection change moves nothing (as on the
 * segmented switch); an icon, a count or a badge keeps its place.
 *
 * Variants:
 *   .ds-tabs               a row of labels over a hairline; a bar under the
 *                          selected tab
 *   .ds-tabs--line         the same, named explicitly
 *   .ds-tabs--contained    a tinted tray (--ds-tabs-contained-bg), the
 *                          selected tab a surface pill that glides inside
 *                          it; as wide as its tabs, the row's height unchanged
 *   .ds-tabs--vertical     a column with the hairline and the bar at its end
 *                          (combines with --contained); the page sets
 *                          aria-orientation="vertical"; .ds-tabs__columns
 *                          lays it out beside the panels, over them at 600px
 *                          of the content
 *   .ds-tabs--fill         equal widths across the row
 *   .ds-tabs--flush        no hairline
 *
 * Parts: .ds-tabs__count (a count after the label, tabular meta figures; a
 * .ds-sr separator reads it with the label; a .ds-badge still works for
 * news), an icon as the tab's first child (svg, 18 or 20), .ds-tabs__item
 * with .ds-tabs__close (above), .ds-tabs__bar (the row with the buttons
 * after it: as wide as its container, the hairline under all of them; none
 * around a contained or flush row), .ds-tabs__more (the More button the
 * module writes, after the last tab that fits), .ds-tabs__add (an icon
 * button at the bar's end, the page's own).
 *
 * Options (src/core/options.css, docs/options.md), on the row or any
 * ancestor; each is computed here, in the tab's own rule:
 *   size      .ds-xs ... .ds-xl: 8px of height per step, 4px of side padding
 *             per step, the type role of the size (always at the regular
 *             weight: the selected tab alone is heavier)
 *   density   .ds-density-*: 4px of height per step (48, 44, 40, 36px); not
 *             the side padding, not the type
 *   shape     .ds-shape-*: multiplies the radius of the ring, the state
 *             layer (rest and pressed) and the contained tray and pill
 *   touch     .ds-touch: a tab is at least --ds-target-min high, also under
 *             the smallest size and density; the close button as well
 *   tone      none: a tab does not state a status (a count or a word in it
 *             may, through its own component)
 *
 * Blocked: :disabled or aria-disabled="true" (the disabled model; no
 * hover, press or morph, aria-disabled keeps its focus layer).
 *
 * Press: the state layer is a pill inside the tab (--ds-space-1 from its
 * top and bottom edge; the contained tab's own edges) that turns squarer
 * while pressed (--ds-radius-action-pressed times the shape, in
 * --ds-dur-micro, back on the spring) and ripples (js/ripple.js); nothing
 * moves. The keyboard ring is inset and snaps inward (outline-offset,
 * --ds-dur-fast) with the focus layer.
 *
 * Switching: ARIA tabs toggle `hidden` on the panels and enter the new one
 * (DS.motion.enter(panel, 'swap')); link tabs are navigation
 * (DS.motion.transition(update, { type: 'fade-through' })). The labels
 * change colour on the indicator's timing (--ds-indicator-dur).
 *
 * Overflow: the row scrolls sideways without a scrollbar (a vertical one
 * scrolls down); DS.dom.roving() scrolls a focused tab into view, and
 * DS.indicator.create(..., { reveal: true }) keeps the selected one in view.
 * With data-ds-tabs-overflow in a .ds-tabs__bar the tabs that do not fit
 * hide instead (hidden on the tab or its .ds-tabs__item) and the More menu
 * lists them; the selected tab always stays in the row.
 *
 * Hooks: --ds-tabs-height (48px, size md and comfortable),
 * --ds-tabs-padding-x (--ds-space-4), --ds-tabs-font (the size's role),
 * --ds-tabs-indicator-height (3px, the bar's thickness),
 * --ds-tabs-indicator-color (--ds-primary), --ds-tabs-contained-bg
 * (--ds-surface-high). The computed values (--_h, --_box, --_half,
 * --_radius, --_pad, --_inset, --_layer ...) are private: never set them.
 * One reader outside this file: the ripple box in ripple.css takes --_inset
 * and --_layer, inherited from the tab, so it lies exactly over the layer.
 *
 * Forced colours: the selected tab is a choice in a set (SelectedItem /
 * SelectedItemText, the indicator hidden), a focused one a CanvasText ring
 * inside; blocked tabs GrayText; the contained tray keeps an edge. The close
 * button of a selected tab lies over that fill: SelectedItemText, its ring
 * CanvasText.
 *
 * Print: the row wraps instead of scrolling.
 *
 * Progressive:
 * - scrollbar-color and scrollbar-width (the row hides its scrollbar while
 *   it scrolls sideways): without them the platform scrollbar shows under
 *   the row.
 */

@layer ds.components.tabs {
  .ds-tabs {
    position: relative;
    display: flex;
    min-width: 0;
    overflow-x: auto;
    overflow-y: hidden;
    border-bottom: 1px solid var(--ds-line);
    scrollbar-width: none;
  }

  .ds-tabs::-webkit-scrollbar {
    display: none;
  }

  .ds-tabs--line {
    border-bottom-color: var(--ds-line);
  }

  /* The bar: the row and the buttons after it share one hairline. The row
     takes the width of its tabs (so the More button follows the last one),
     a full-width row the rest. */
  .ds-tabs__bar {
    position: relative;
    display: flex;
    align-items: center;
    gap: var(--ds-space-1);
    min-width: 0;
    border-bottom: 1px solid var(--ds-line);
  }

  .ds-tabs__bar:has(> .ds-tabs:is(.ds-tabs--flush, .ds-tabs--contained)) {
    border-bottom: 0;
  }

  .ds-tabs__bar > .ds-tabs {
    flex: 0 1 auto;
    border-bottom: 0;
  }

  .ds-tabs__bar > .ds-tabs--fill {
    flex: 1 1 auto;
  }

  .ds-tabs__more,
  .ds-tabs__add {
    flex: none;
  }

  /* What overflows into the More menu, and the More button while nothing
     does: gone, whatever display the part sets. */
  .ds-tabs__tab[hidden],
  .ds-tabs__item[hidden],
  .ds-tabs__more[hidden] {
    display: none;
  }

  .ds-tabs--flush {
    border-bottom: 0;
  }

  .ds-tabs--fill > .ds-tabs__tab,
  .ds-tabs--fill > .ds-tabs__item {
    flex: 1 1 0;
  }

  /* The bar: the indicator's box is the selected tab; only its bottom edge
     is painted, in the hook colour (square: --ds-indicator-radius keeps its
     initial 0px). */
  .ds-tabs__indicator {
    background: linear-gradient(var(--ds-tabs-indicator-color, var(--ds-primary)), var(--ds-tabs-indicator-color, var(--ds-primary))) bottom / 100% var(--ds-tabs-indicator-height, 3px) no-repeat;
  }

  .ds-tabs__tab {
    /* The options, computed here. The height: the hook (size md,
       comfortable) plus 8px per size step and 4px per density step. */
    --_h: calc(var(--ds-tabs-height, 48px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px);
    /* What it measures: never below the touch minimum (.ds-touch). */
    --_box: max(var(--ds-target-min, 0px), var(--_h));
    --_half: calc(var(--_box) / 2);
    /* The ring's radius: the pill times the shape. */
    --_radius: min(calc(min(var(--ds-radius-action), var(--_half)) * var(--ds-shape, 1)), var(--_half));
    /* The state layer inside the tab: the same pill less its inset; pressed
       the role times the shape, never rounder than at rest. */
    --_inset: var(--ds-space-1);
    --_layer-half: calc(var(--_half) - var(--_inset));
    --_layer: min(calc(min(var(--ds-radius-action), var(--_layer-half)) * var(--ds-shape, 1)), var(--_layer-half));
    --_layer-pressed: min(calc(var(--ds-radius-action-pressed) * var(--ds-shape, 1)), var(--_layer));
    /* Side padding: 4px per size step; density leaves it alone. */
    --_pad: calc(var(--ds-tabs-padding-x, var(--ds-space-4)) + var(--ds-size-step, 0) * 4px);
    position: relative;
    display: inline-grid;
    grid-auto-flow: column;
    align-items: center;
    /* The rows pack in the middle: the 0px row of data-label takes none of
       the free height, so the label sits on the tab's centre. */
    align-content: center;
    justify-content: center;
    column-gap: var(--ds-space-2);
    flex: none;
    min-height: var(--_box);
    margin: 0;
    padding: 0 var(--_pad);
    border: 0;
    /* The ring follows this radius; the layer inside is a pill too. */
    border-radius: var(--_radius);
    background: none;
    color: var(--ds-text-2);
    font: var(--ds-tabs-font, var(--ds-size-font, var(--ds-font-label)));
    font-weight: var(--ds-weight-regular);
    text-decoration: none;
    white-space: nowrap;
    cursor: pointer;
    -webkit-tap-highlight-color: transparent;
    /* An inset ring (the scrolling row clips anything outside): it rests on
       the edge and snaps inward. */
    outline-offset: 0;
    transition:
      outline-offset var(--ds-dur-fast) var(--ds-ease-out),
      opacity var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  /* With the gliding indicator, the label changes colour while it arrives
     (on its timing, --ds-indicator-dur on the row). */
  .ds-has-indicator .ds-tabs__tab {
    transition:
      outline-offset var(--ds-dur-fast) var(--ds-ease-out),
      opacity var(--ds-dur-fast) var(--ds-ease-in-out),
      color var(--ds-indicator-dur, var(--ds-dur-medium)) var(--ds-ease-in-out);
  }

  /* The label once more in the selected weight, without height and unseen,
     under the text (a count or a badge keeps its column). */
  .ds-tabs__tab[data-label]::after {
    content: attr(data-label);
    grid-row: 2;
    grid-column: 1;
    height: 0;
    overflow: hidden;
    visibility: hidden;
    pointer-events: none;
    font-weight: var(--ds-weight-label);
  }

  /* A leading icon takes the first column, both rows of it (so the text
     does not flow in under the icon): the copy goes under the text. */
  .ds-tabs__tab[data-label] > svg:first-child {
    grid-row: 1 / span 2;
  }

  .ds-tabs__tab[data-label]:has(> svg:first-child)::after {
    grid-column: 2;
  }

  .ds-tabs__tab svg {
    flex-shrink: 0;
  }

  .ds-tabs__count {
    color: inherit;
    font: var(--ds-font-meta);
    font-variant-numeric: tabular-nums;
  }

  .ds-tabs__tab:is([aria-selected="true"], [aria-current="page"]) {
    color: var(--ds-primary);
    font-weight: var(--ds-weight-label);
  }

  /* State layer: a pill inside the tab, the colour of the label. */
  .ds-tabs__tab::before {
    content: '';
    position: absolute;
    inset: var(--_inset) 0;
    border-radius: var(--_layer);
    background: currentColor;
    opacity: 0;
    pointer-events: none;
    transition:
      opacity var(--ds-dur-fast) var(--ds-ease-in-out),
      border-radius var(--ds-dur-medium) var(--ds-ease-spatial);
  }

  @media (hover: hover) {
    .ds-tabs__tab:hover::before {
      opacity: var(--ds-state-hover);
    }
  }

  .ds-tabs__tab:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: calc(-1 * var(--ds-focus-width));
  }

  .ds-tabs__tab:focus-visible::before {
    opacity: var(--ds-state-focus);
    transition-duration: 0s, var(--ds-dur-medium);
  }

  .ds-tabs__tab:active::before,
  .ds-tabs__tab.ds-pressed::before {
    opacity: var(--ds-state-pressed);
    border-radius: var(--_layer-pressed);
    transition:
      opacity var(--ds-dur-micro) var(--ds-ease-in-out),
      border-radius var(--ds-dur-micro) var(--ds-ease-out);
  }

  /* Blocked: the disabled model, no hover, press or morph; an
     aria-disabled tab stays focusable and keeps its focus layer. */
  .ds-tabs__tab:is(:disabled, [aria-disabled="true"]) {
    color: var(--ds-disabled-ink);
    opacity: var(--ds-disabled-opacity);
    cursor: default;
  }

  @media (hover: hover) {
    .ds-tabs__tab:is(:disabled, [aria-disabled="true"]):hover::before {
      opacity: 0;
    }
  }

  .ds-tabs__tab:is(:disabled, [aria-disabled="true"]):is(:active, .ds-pressed)::before {
    opacity: 0;
    border-radius: var(--_layer);
  }

  .ds-tabs__tab[aria-disabled="true"]:focus-visible::before {
    opacity: var(--ds-state-focus);
  }

  /* A tab that closes: the tab fills the wrapper and keeps room at its end
     for the button lying over it (a small icon button, or a finger's target
     under .ds-touch), as a drawer row does. The button is a sibling: a
     button inside a button is no valid markup. */
  .ds-tabs__item {
    --_close: max(var(--ds-target-min, 0px), calc(var(--ds-btn-icon-size, 40px) - 16px));
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: center;
    flex: none;
  }

  .ds-tabs__item > .ds-tabs__tab {
    grid-area: 1 / 1 / 2 / 3;
    padding-inline-end: calc(var(--_close) + var(--ds-space-2));
  }

  .ds-tabs__close {
    grid-area: 1 / 2;
    margin-inline-end: var(--ds-space-1);
  }

  /* Contained: a tinted tray, the selected tab a pill of the surface inside
     it. The tab gives up what the tray's padding takes, so the row keeps
     the height of a line row. The indicator paints the pill; without it the
     tab paints itself. */
  .ds-tabs--contained {
    --_tab: calc(var(--ds-tabs-height, 48px) - 2 * var(--ds-space-1) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px);
    --_tab-half: calc(max(var(--ds-target-min, 0px), var(--_tab)) / 2);
    --_tab-radius: min(calc(min(var(--ds-radius-action), var(--_tab-half)) * var(--ds-shape, 1)), var(--_tab-half));
    --_tray-half: calc(var(--_tab-half) + var(--ds-space-1));
    gap: var(--ds-space-1);
    padding: var(--ds-space-1);
    border-bottom: 0;
    border-radius: min(calc(min(var(--ds-radius-action), var(--_tray-half)) * var(--ds-shape, 1)), var(--_tray-half));
    background: var(--ds-tabs-contained-bg, var(--ds-surface-high));
  }

  .ds-tabs--contained:not(.ds-tabs--fill, .ds-tabs--vertical) {
    width: fit-content;
    max-width: 100%;
  }

  .ds-tabs--contained .ds-tabs__tab {
    --_h: var(--_tab);
    --_inset: 0px;
  }

  .ds-tabs--contained .ds-tabs__tab:is([aria-selected="true"], [aria-current="page"]) {
    background: var(--ds-surface);
  }

  .ds-tabs--contained.ds-has-indicator .ds-tabs__tab:is([aria-selected="true"], [aria-current="page"]) {
    background: transparent;
  }

  .ds-tabs--contained > .ds-tabs__indicator {
    --ds-indicator-radius: var(--_tab-radius);
    background: var(--ds-surface);
  }

  /* Vertical: a column, the hairline and the bar at its inline end, the
     labels at its start. */
  .ds-tabs--vertical {
    flex-direction: column;
    overflow-x: hidden;
    overflow-y: auto;
    border-bottom: 0;
    border-inline-end: 1px solid var(--ds-line);
  }

  .ds-tabs--vertical.ds-tabs--contained,
  .ds-tabs--vertical.ds-tabs--flush {
    border-inline-end: 0;
  }

  .ds-tabs--vertical .ds-tabs__tab {
    justify-content: start;
    text-align: start;
  }

  .ds-tabs--vertical:not(.ds-tabs--contained) > .ds-tabs__indicator {
    background: linear-gradient(var(--ds-tabs-indicator-color, var(--ds-primary)), var(--ds-tabs-indicator-color, var(--ds-primary))) right / var(--ds-tabs-indicator-height, 3px) 100% no-repeat;
  }

  .ds-tabs__columns {
    display: grid;
    grid-template-columns: max-content minmax(0, 1fr);
    gap: var(--ds-space-6);
    min-width: 0;
  }

  @container ds-content (max-width: 600px) {
    .ds-tabs__columns {
      grid-template-columns: minmax(0, 1fr);
      gap: var(--ds-space-4);
    }
  }

  /* A panel takes focus as a whole (tabindex="0") when it holds nothing
     focusable; its ring snaps in like every ring. */
  .ds-tabs__panel {
    min-width: 0;
    outline-offset: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    transition: outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-tabs__panel:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: var(--ds-focus-offset);
  }

  /* A badge (badge.css) in a blocked tab: the disabled model, as in a
     blocked button (the badge's own --_fill as its colour). */
  .ds-tabs__tab:is(:disabled, [aria-disabled="true"]) .ds-badge {
    background: var(--ds-disabled-fill, var(--ds-badge-bg, var(--_fill)));
    color: var(--ds-disabled-ink, var(--ds-badge-color, var(--ds-on-accent)));
  }

  @media (forced-colors: active) {
    .ds-tabs__tab:is(:disabled, [aria-disabled="true"]) .ds-badge {
      outline-color: GrayText;
      color: GrayText;
    }
  }

  @media (forced-colors: active) {
    .ds-tabs__indicator {
      display: none;
    }

    .ds-tabs__tab:is([aria-selected="true"], [aria-current="page"]),
    .ds-tabs--contained .ds-tabs__tab:is([aria-selected="true"], [aria-current="page"]),
    .ds-tabs--contained.ds-has-indicator .ds-tabs__tab:is([aria-selected="true"], [aria-current="page"]) {
      forced-color-adjust: none;
      background: SelectedItem;
      color: SelectedItemText;
    }

    .ds-tabs__tab:is([aria-selected="true"], [aria-current="page"]):focus-visible {
      outline-color: CanvasText;
    }

    .ds-tabs__tab:is(:disabled, [aria-disabled="true"]) {
      color: GrayText;
    }

    /* A sibling lying over the selected tab's fill: the forced button ink
       could match that fill, so it takes the fill's own ink. */
    .ds-tabs__item:has(> .ds-tabs__tab:is([aria-selected="true"], [aria-current="page"])) > .ds-tabs__close {
      forced-color-adjust: none;
      color: SelectedItemText;
      outline-color: CanvasText;
    }

    /* The tray's tint is gone: its edge stays. */
    .ds-tabs--contained {
      outline: 1px solid CanvasText;
      outline-offset: -1px;
    }
  }

  @media print {
    .ds-tabs {
      flex-wrap: wrap;
      overflow: visible;
    }
  }
}

/* ── components/steps/steps.css ── */
/*
 * Steps of a form (a wizard) or the stages of a pipeline: where the user
 * is in a short sequence. A step is no button, unless it holds a
 * .ds-steps__link: then the user may go to it (back, or on).
 *
 *   <ol class="ds-steps" aria-label="Report a problem">
 *     <li class="ds-steps__step" data-status="done">
 *       <span class="ds-steps__mark">(check 16, its path with pathLength="1")</span>
 *       <span class="ds-steps__label">Device<span class="ds-sr">, done</span></span>
 *     </li>
 *     <li class="ds-steps__step" aria-current="step"><span class="ds-steps__mark">2</span><span class="ds-steps__label">Problem</span></li>
 *     <li class="ds-steps__step" data-status="error">
 *       <span class="ds-steps__mark">(alertCircle 16)</span>
 *       <span class="ds-steps__label">Contact</span><span class="ds-steps__hint">Add a phone number</span>
 *     </li>
 *     <li class="ds-steps__step" data-status="optional">
 *       <span class="ds-steps__mark">4</span>
 *       <span class="ds-steps__label">Photos</span><span class="ds-steps__hint">Optional</span>
 *     </li>
 *   </ol>
 *
 *   A column: <ol class="ds-steps ds-steps--vertical" aria-label="Report a problem"> (the same items)
 *   A bar instead of marks: <ol class="ds-steps ds-steps--bar" aria-label="Step 2 of 3"> (the same items)
 *   A stage path: <ol class="ds-steps ds-steps--path" aria-label="Ticket stages"> (the same items)
 *
 *   Clickable steps: the mark and the label in a link or a button, which
 *   carries aria-current="step" (DS.steps, steps.js, moves it):
 *   <ol class="ds-steps" aria-label="Report a problem" data-ds-steps>
 *     <li class="ds-steps__step" data-status="done"><button class="ds-steps__link" type="button"><span class="ds-steps__mark">(check)</span><span class="ds-steps__label">Device<span class="ds-sr">, done</span></span></button></li>
 *     <li class="ds-steps__step"><button class="ds-steps__link" type="button" aria-current="step"><span class="ds-steps__mark">2</span><span class="ds-steps__label">Problem</span></button></li>
 *     <li class="ds-steps__step"><span class="ds-steps__mark">3</span><span class="ds-steps__label">Contact</span></li>
 *   </ol>
 *
 * State, set by the page: data-status on a step (as on .ds-tasks; never
 * data-state, which DS.overlay writes on overlays) and aria-current="step"
 * on the current one; the others are upcoming.
 *   done       a finished step
 *   error      a step that needs attention: the error colours, an icon in
 *              its mark and a word (.ds-steps__hint, or a .ds-sr one)
 *   optional   an upcoming step the user may skip: a dashed ring and the
 *              word in its .ds-steps__hint
 *
 * Marks: a 24px disc. Done: --ds-primary with a check that draws itself
 * when the step turns done in place (re-render with DS.dom.morphHtml, so
 * the mark stays): the mark's stroke-dashoffset, which the pathLength="1"
 * check inherits, runs from 1 to 0 over --ds-dur-medium after
 * --ds-dur-micro; steps rendered with done ones stay still on load (a
 * transition, not a keyframe). Current: --ds-primary with --ds-on-primary
 * figures and the label weight on its label; upcoming: an --ds-outline ring
 * in --ds-text-2. The connector after a done step turns --ds-primary
 * (colours on --ds-dur-medium). Status is never colour alone: the check or
 * the icon, the word, the weight and aria-current. On narrow pages (600px
 * of the content and below) only the current label shows, in a row; the
 * others stay readable. .ds-steps__hint: a line of the meta role beside the
 * label (under it in a column), in the error colour on an error step; short
 * of room in a row it truncates with an ellipsis, before any label does.
 *
 * .ds-steps__link: a step the user may go to, a <button> (the page or
 * DS.steps moves the current step) or an <a href> (the next page marks its
 * own). Its state layer is a pill around the mark and the label that
 * reaches past them without moving them, at least --ds-target-min high
 * (.ds-touch); it turns squarer while pressed (--ds-radius-action-pressed
 * times the shape) and ripples; the ring sits outside and snaps in.
 * aria-disabled="true" blocks it (the disabled model). A step without one
 * is no target.
 *
 * --path: a stage path, the stages of a pipeline as chevrons that nest
 * (--ds-steps-path-height, 40px at size md and comfortable, 8px per size
 * step and 4px per density step, at least --ds-target-min; the ends' radius
 * times the shape): upcoming --ds-surface-high, done
 * --ds-primary-container with its check, current --ds-primary with the
 * label weight, error --ds-error with its icon. Number marks and hints are
 * read, not shown; a link fills its chevron, its ring inside. At 600px of
 * the content only the current label shows, as in a row, and the stages
 * take the room of what they show.
 *
 * --vertical: a column for long or wordy sequences; the connector runs from
 * mark to mark, labels and hints wrap and all of them stay at every width.
 *
 * --bar: one segment per step, --ds-steps-bar-height high; done and
 * current segments fill with --ds-primary, an error segment with --ds-error
 * (a clip that glides on --ds-ease-value over --ds-dur-glide), the rest is
 * --ds-accent. Marks, labels and hints are visually hidden: the list's
 * aria-label says where the user is.
 *
 * Options (src/core/options.css, docs/options.md), on the list or any
 * ancestor; each is computed here, in the step's own rule:
 *   size      .ds-xs ... .ds-xl: 4px of mark per step (16 to 32px), the type
 *             role of the size at the regular weight
 *   density   .ds-density-*: 2px per step off the room between the steps of
 *             a column; the row and the marks stay
 *   shape     .ds-shape-*: multiplies the mark's radius and the segments'
 *   touch     .ds-touch: a .ds-steps__link and a stage are at least
 *             --ds-target-min high; a plain step is no target
 *   tone      none: a step's status is data-status, with its icon and word
 *
 * Moving between steps: DS.motion.transition(update, { type: 'forward' })
 * (or 'back'). DS.steps (data-ds-steps) moves aria-current, announces the
 * step and sends ds:change when a step's button is pressed.
 *
 * Hooks: --ds-steps-bar-height (4px), --ds-steps-mark-size (--ds-space-6),
 * --ds-steps-font (the size's role), --ds-steps-gap (--ds-space-5: between
 * the steps of a column), --ds-steps-path-height (40px: a stage). The
 * computed --_mark, --_h, --_radius, --_tip and --_end are private: never
 * set them.
 *
 * Forced colours: done and current marks and segments Highlight, upcoming
 * ones a CanvasText outline, an error mark its icon on a CanvasText ring and
 * an error segment a CanvasText fill; connectors CanvasText, Highlight after
 * a done step. A stage path: the current stage Highlight, the others Canvas
 * with their words, checks and icons; a link's ring CanvasText.
 *
 * Print: marks and segments keep their colours (print-color-adjust): the
 * check of a done step is drawn on its filled mark.
 */

@layer ds.components.steps {
  .ds-steps {
    display: flex;
    align-items: center;
    gap: var(--ds-space-2);
    min-width: 0;
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .ds-steps__step {
    /* The options, computed here: 4px of mark per size step. */
    --_mark: calc(var(--ds-steps-mark-size, var(--ds-space-6)) + var(--ds-size-step, 0) * 4px);
    display: flex;
    align-items: center;
    gap: var(--ds-space-2);
    flex: 0 1 auto;
    min-width: 0;
    color: var(--ds-text-2);
    font: var(--ds-steps-font, var(--ds-size-font, var(--ds-font-body)));
    /* Every size role at the regular weight: the current label alone takes
       the label weight (below), whatever the size. */
    font-weight: var(--ds-weight-regular);
  }

  /* The connector: a hairline that takes the room between two steps. */
  .ds-steps__step + .ds-steps__step {
    flex: 1 1 0;
  }

  /* A row with hints has less room than equal shares can give: every step
     starts from its content, and only the steps with a hint give way, their
     hint first (its shrink factor, below). So no label goes, and no hint
     runs over the next mark. */
  .ds-steps:where(:not(.ds-steps--vertical, .ds-steps--bar)):has(> .ds-steps__step > .ds-steps__hint) > .ds-steps__step {
    flex-basis: auto;
    flex-shrink: 0;
  }

  .ds-steps:where(:not(.ds-steps--vertical, .ds-steps--bar)):has(> .ds-steps__step > .ds-steps__hint) > .ds-steps__step:has(> .ds-steps__hint) {
    flex-shrink: 1;
  }

  /* It gives way before the label (a shrink factor far above the label's,
     as on .ds-steps__hint), down to its minimum. */
  .ds-steps__step + .ds-steps__step::before {
    content: '';
    flex: 1 999 var(--ds-space-6);
    min-width: var(--ds-space-4);
    height: 1px;
    background: var(--ds-line);
    transition: background-color var(--ds-dur-medium) var(--ds-ease-in-out);
  }

  .ds-steps__step[data-status="done"] + .ds-steps__step::before {
    background: var(--ds-primary);
  }

  .ds-steps__mark {
    display: inline-grid;
    flex: none;
    place-items: center;
    width: var(--_mark);
    height: var(--_mark);
    border: 1px solid var(--ds-outline);
    /* A disc at the default shape and above (past 50% it stays a disc). */
    border-radius: calc(50% * var(--ds-shape, 1));
    color: var(--ds-text-2);
    font: var(--ds-font-caption);
    font-variant-numeric: tabular-nums;
    /* Inherited by the check of a done step: undrawn until the step is
       done. A transition, not a keyframe, so steps rendered with done ones
       stay still on load. */
    stroke-dashoffset: 1;
    transition:
      background-color var(--ds-dur-medium) var(--ds-ease-in-out),
      border-color var(--ds-dur-medium) var(--ds-ease-in-out),
      color var(--ds-dur-medium) var(--ds-ease-in-out),
      stroke-dashoffset var(--ds-dur-medium) var(--ds-ease-out) var(--ds-dur-micro);
  }

  .ds-steps__label {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  /* Truncates before the label or the connector give anything up: a factor
     far above theirs, not a literal of the design. */
  .ds-steps__hint {
    flex: 0 999 auto;
    min-width: 0;
    overflow: hidden;
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .ds-steps__step:is([data-status="done"], [data-status="error"], :is([aria-current="step"], :has(> .ds-steps__link[aria-current="step"]))) {
    color: var(--ds-text);
  }

  .ds-steps__step:is([data-status="done"], :is([aria-current="step"], :has(> .ds-steps__link[aria-current="step"]))) .ds-steps__mark:where(:not(.ds-steps--path *)) {
    border-color: var(--ds-primary);
    background: var(--ds-primary);
    color: var(--ds-on-primary);
  }

  .ds-steps__step:is([aria-current="step"], :has(> .ds-steps__link[aria-current="step"])) .ds-steps__label {
    font-weight: var(--ds-weight-label);
  }

  /* Needs attention: the error colours, an icon in the mark and a word. It
     outranks the current step: the error is what the user has to see. */
  .ds-steps__step[data-status="error"] .ds-steps__mark:where(:not(.ds-steps--path *)) {
    border-color: var(--ds-error);
    background: var(--ds-error);
    color: var(--ds-on-error);
  }

  .ds-steps__step[data-status="error"] > .ds-steps__hint {
    color: var(--ds-error);
  }

  /* May be skipped: the ring turns dashed, the hint says the word. */
  .ds-steps__step[data-status="optional"]:not(:is([aria-current="step"], :has(> .ds-steps__link[aria-current="step"]))) .ds-steps__mark:where(:not(.ds-steps--path *)) {
    border-style: dashed;
  }

  .ds-steps__mark [pathLength] {
    stroke-dasharray: 1;
  }

  /* The mark stays when a step turns done in place (DS.dom.morphHtml
     patches it), so its offset glides to 0 and the new check draws itself;
     the pathLength="1" path inherits it. */
  .ds-steps__step[data-status="done"] .ds-steps__mark {
    stroke-dashoffset: 0;
  }

  /*
   * A step the user may go back to (or on to): a link or a button around
   * its mark and label. The state layer is a pill around both that reaches
   * past them without moving them (negative margins), at least the touch
   * minimum high; it turns squarer while pressed and ripples. The ring sits
   * outside and snaps in.
   */
  .ds-steps__link {
    --_h: max(var(--ds-target-min, 0px), calc(var(--_mark) + 2 * var(--ds-space-1)));
    --_half: calc(var(--_h) / 2);
    --_radius: min(calc(min(var(--ds-radius-action), var(--_half)) * var(--ds-shape, 1)), var(--_half));
    --_radius-pressed: min(calc(var(--ds-radius-action-pressed) * var(--ds-shape, 1)), var(--_radius));
    position: relative;
    display: flex;
    align-items: center;
    gap: var(--ds-space-2);
    min-width: 0;
    min-height: var(--_h);
    margin: calc((var(--_mark) - var(--_h)) / 2) calc(-1 * var(--ds-space-2));
    padding: 0 var(--ds-space-2);
    border: 0;
    border-radius: var(--_radius);
    background: none;
    color: inherit;
    font: inherit;
    text-align: start;
    text-decoration: none;
    cursor: pointer;
    -webkit-tap-highlight-color: transparent;
    outline-offset: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    transition: outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-steps__link::before {
    content: '';
    position: absolute;
    inset: 0;
    border-radius: var(--_radius);
    background: currentColor;
    opacity: 0;
    pointer-events: none;
    transition:
      opacity var(--ds-dur-fast) var(--ds-ease-in-out),
      border-radius var(--ds-dur-medium) var(--ds-ease-spatial);
  }

  @media (hover: hover) {
    .ds-steps__link:hover::before {
      opacity: var(--ds-state-hover);
    }
  }

  .ds-steps__link:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: var(--ds-focus-offset);
  }

  .ds-steps__link:focus-visible::before {
    opacity: var(--ds-state-focus);
    transition-duration: 0s, var(--ds-dur-medium);
  }

  .ds-steps__link:active::before,
  .ds-steps__link.ds-pressed::before {
    opacity: var(--ds-state-pressed);
    border-radius: var(--_radius-pressed);
    transition:
      opacity var(--ds-dur-micro) var(--ds-ease-in-out),
      border-radius var(--ds-dur-micro) var(--ds-ease-out);
  }

  /* With the ripple (js/ripple.js) the flat layer stays at its hover value
     (focus value after a key) and the ripple brings the press. */
  :where(.ds-ripples) .ds-steps__link:where(:not([data-ds-ripple="off"], [data-ds-ripple="off"] *, [aria-disabled="true"])):is(:active, .ds-pressed)::before {
    opacity: 0;
  }

  @media (hover: hover) {
    :where(.ds-ripples) .ds-steps__link:where(:not([data-ds-ripple="off"], [data-ds-ripple="off"] *, [aria-disabled="true"])):is(:active, .ds-pressed)::before {
      opacity: var(--ds-state-hover);
    }
  }

  :where(.ds-ripples) .ds-steps__link:where(:not([data-ds-ripple="off"], [data-ds-ripple="off"] *, [aria-disabled="true"])):focus-visible:is(:active, .ds-pressed)::before {
    opacity: var(--ds-state-focus);
  }

  /* Blocked (a step not reachable yet): the disabled model, no hover,
     press or morph; it keeps its focus layer. */
  .ds-steps__link[aria-disabled="true"] {
    color: var(--ds-disabled-ink);
    opacity: var(--ds-disabled-opacity);
    cursor: default;
    transition:
      outline-offset var(--ds-dur-fast) var(--ds-ease-out),
      opacity var(--ds-dur-fast) var(--ds-ease-in-out),
      color var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  @media (hover: hover) {
    .ds-steps__link[aria-disabled="true"]:hover::before {
      opacity: 0;
    }
  }

  .ds-steps__link[aria-disabled="true"]:is(:active, .ds-pressed)::before {
    opacity: 0;
    border-radius: var(--_radius);
  }

  .ds-steps__link[aria-disabled="true"]:focus-visible::before {
    opacity: var(--ds-state-focus);
  }

  /* Narrow pages: the current label only, the others read but unseen (a
     column has the room). */
  @container ds-content (max-width: 600px) {
    .ds-steps:not(.ds-steps--vertical) > .ds-steps__step:not(:is([aria-current="step"], :has(> .ds-steps__link[aria-current="step"]))) :is(.ds-steps__label, .ds-steps__hint) {
      position: absolute;
      width: 1px;
      height: 1px;
      overflow: hidden;
      clip-path: inset(50%);
      white-space: nowrap;
    }

    /* The words that took the room are gone: every step gives way again. */
    .ds-steps:where(:not(.ds-steps--vertical, .ds-steps--bar)):has(> .ds-steps__step > .ds-steps__hint) > .ds-steps__step {
      flex-shrink: 1;
    }
  }

  /* The column: the mark in its own column, the connector from mark to mark
     (on the step it leaves, so it never depends on the next one), the text
     wraps beside the mark, its first line on the mark's centre. */
  .ds-steps--vertical {
    flex-direction: column;
    align-items: stretch;
    gap: 0;
  }

  .ds-steps--vertical > .ds-steps__step {
    position: relative;
    display: grid;
    grid-template-columns: var(--_mark) minmax(0, 1fr);
    column-gap: var(--ds-space-3);
    align-items: start;
    flex: none;
    padding-block-end: calc(var(--ds-steps-gap, var(--ds-space-5)) + var(--ds-density, 0) * 2px);
  }

  .ds-steps--vertical > .ds-steps__step:last-child {
    padding-block-end: 0;
  }

  .ds-steps--vertical > .ds-steps__step + .ds-steps__step::before {
    content: none;
  }

  .ds-steps--vertical > .ds-steps__step:not(:last-child)::after {
    content: '';
    position: absolute;
    inset-block: calc(var(--_mark) + var(--ds-space-1)) var(--ds-space-1);
    inset-inline-start: calc(var(--_mark) / 2);
    width: 1px;
    background: var(--ds-line);
    transition: background-color var(--ds-dur-medium) var(--ds-ease-in-out);
  }

  .ds-steps--vertical > .ds-steps__step[data-status="done"]:not(:last-child)::after {
    background: var(--ds-primary);
  }

  /* A link in a column spans both columns (its mark and label keep theirs). */
  .ds-steps--vertical .ds-steps__link {
    display: grid;
    grid-column: 1 / -1;
    grid-template-columns: subgrid;
    column-gap: var(--ds-space-3);
    align-items: start;
  }

  .ds-steps--vertical .ds-steps__label {
    grid-column: 2;
    min-height: var(--_mark);
    overflow: visible;
    align-content: center;
    white-space: normal;
  }

  .ds-steps--vertical .ds-steps__hint {
    grid-column: 2;
    overflow: visible;
    white-space: normal;
  }

  /* The bar: equal segments; done and current ones fill. */
  .ds-steps--bar {
    gap: var(--ds-space-1);
  }

  .ds-steps--bar > .ds-steps__step {
    position: relative;
    flex: 1 1 0;
    height: var(--ds-steps-bar-height, 4px);
    overflow: hidden;
    border-radius: calc(var(--ds-radius-xs) * var(--ds-shape, 1));
    background: var(--ds-accent);
  }

  .ds-steps--bar > .ds-steps__step + .ds-steps__step::before {
    content: none;
  }

  .ds-steps--bar > .ds-steps__step::after {
    content: '';
    position: absolute;
    inset: 0;
    background: var(--ds-primary);
    clip-path: inset(0 100% 0 0);
    transition: clip-path var(--ds-dur-glide) var(--ds-ease-value);
  }

  .ds-steps--bar > .ds-steps__step:is([data-status="done"], [data-status="error"], :is([aria-current="step"], :has(> .ds-steps__link[aria-current="step"])))::after {
    clip-path: inset(0);
  }

  .ds-steps--bar > .ds-steps__step[data-status="error"]::after {
    background: var(--ds-error);
  }

  .ds-steps--bar .ds-steps__mark {
    display: none;
  }

  .ds-steps--bar :is(.ds-steps__label, .ds-steps__hint) {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }

  /*
   * Stage path: the stages of a pipeline as chevrons that nest, the
   * current one filled, the done ones tonal with a check, the upcoming ones
   * on the surface. Labels sit inside; marks show only a check or an icon;
   * hints are read, not shown.
   */
  .ds-steps--path {
    align-items: stretch;
    gap: 0;
  }

  .ds-steps--path > .ds-steps__step {
    /* The options, computed here: 8px per size step, 4px per density step,
       at least the touch minimum; the ends' radius times the shape. */
    --_tip: var(--ds-space-3);
    --_h: max(var(--ds-target-min, 0px), calc(var(--ds-steps-path-height, 40px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px));
    --_end: min(calc(var(--ds-radius-action) * var(--ds-shape, 1)), calc(var(--_h) / 2));
    position: relative;
    flex: 1 1 0;
    justify-content: center;
    min-height: var(--_h);
    padding-inline: calc(var(--_tip) + var(--ds-space-2));
    margin-inline-start: calc(var(--ds-space-1) - var(--_tip));
    background: var(--ds-surface-high);
    color: var(--ds-text-2);
    clip-path: polygon(0 0, calc(100% - var(--_tip)) 0, 100% 50%, calc(100% - var(--_tip)) 100%, 0 100%, var(--_tip) 50%);
    transition:
      background-color var(--ds-dur-medium) var(--ds-ease-in-out),
      color var(--ds-dur-medium) var(--ds-ease-in-out);
  }

  .ds-steps--path > .ds-steps__step:first-child {
    margin-inline-start: 0;
    border-start-start-radius: var(--_end);
    border-end-start-radius: var(--_end);
    clip-path: polygon(0 0, calc(100% - var(--_tip)) 0, 100% 50%, calc(100% - var(--_tip)) 100%, 0 100%);
  }

  .ds-steps--path > .ds-steps__step:last-child {
    border-start-end-radius: var(--_end);
    border-end-end-radius: var(--_end);
    clip-path: polygon(0 0, 100% 0, 100% 100%, 0 100%, var(--_tip) 50%);
  }

  .ds-steps--path > .ds-steps__step:only-child {
    clip-path: none;
  }

  .ds-steps--path > .ds-steps__step + .ds-steps__step::before {
    content: none;
  }

  .ds-steps--path > .ds-steps__step[data-status="done"] {
    background: var(--ds-primary-container);
    color: var(--ds-on-primary-container);
  }

  .ds-steps--path > .ds-steps__step:is([aria-current="step"], :has(> .ds-steps__link[aria-current="step"])):not([data-status="error"]) {
    background: var(--ds-primary);
    color: var(--ds-on-primary);
  }

  .ds-steps--path > .ds-steps__step[data-status="error"] {
    background: var(--ds-error);
    color: var(--ds-on-error);
  }

  /* The mark: only a check or an icon, in the stage's ink. */
  .ds-steps--path .ds-steps__mark {
    width: auto;
    height: auto;
    border: 0;
    background: none;
    color: inherit;
  }

  .ds-steps--path > .ds-steps__step:not([data-status="done"], [data-status="error"]) .ds-steps__mark {
    display: none;
  }

  .ds-steps--path .ds-steps__hint {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }

  /* A stage that links fills its chevron; the ring lies inside it. */
  .ds-steps--path .ds-steps__link {
    flex: 1 1 auto;
    align-self: stretch;
    justify-content: center;
    min-height: 0;
    margin: 0 calc(-1 * var(--ds-space-2));
    border-radius: 0;
    outline-offset: 0;
  }

  .ds-steps--path .ds-steps__link::before {
    border-radius: 0;
  }

  .ds-steps--path .ds-steps__link:focus-visible {
    outline-offset: calc(-1 * var(--ds-focus-width));
  }

  /* Narrow pages: only the current label shows (as in a row), so the stages
     take the room of what they show and the current one its whole label. */
  @container ds-content (max-width: 600px) {
    .ds-steps--path > .ds-steps__step {
      flex: 1 1 auto;
    }
  }

  @media (forced-colors: active) {
    .ds-steps__mark {
      border-color: CanvasText;
    }

    .ds-steps__step:is([data-status="done"], :is([aria-current="step"], :has(> .ds-steps__link[aria-current="step"]))):not([data-status="error"]) .ds-steps__mark:where(:not(.ds-steps--path *)) {
      forced-color-adjust: none;
      border-color: Highlight;
      background: Highlight;
      color: HighlightText;
    }

    .ds-steps__step[data-status="error"] .ds-steps__mark:where(:not(.ds-steps--path *)) {
      border-color: CanvasText;
    }

    /* A hairline is a background, which forced colours would turn to Canvas;
       after a done step it follows the done mark. */
    .ds-steps__step + .ds-steps__step::before,
    .ds-steps--vertical > .ds-steps__step:not(:last-child)::after {
      forced-color-adjust: none;
      background: CanvasText;
    }

    .ds-steps__step[data-status="done"] + .ds-steps__step::before,
    .ds-steps--vertical > .ds-steps__step[data-status="done"]:not(:last-child)::after {
      background: Highlight;
    }

    .ds-steps--bar > .ds-steps__step {
      outline: 1px solid CanvasText;
      outline-offset: -1px;
    }

    .ds-steps--bar > .ds-steps__step::after {
      forced-color-adjust: none;
      background: Highlight;
    }

    .ds-steps--bar > .ds-steps__step[data-status="error"]::after {
      background: CanvasText;
    }

    /* The path: the current stage Highlight, the others on Canvas with their
       words (a done stage keeps its check, an error stage its icon). */
    .ds-steps--path > .ds-steps__step,
    .ds-steps--path > .ds-steps__step[data-status] {
      forced-color-adjust: none;
      background: Canvas;
      color: CanvasText;
    }

    .ds-steps--path > .ds-steps__step:is([aria-current="step"], :has(> .ds-steps__link[aria-current="step"])):not([data-status="error"]) {
      background: Highlight;
      color: HighlightText;
    }
  }

  /* Print: the filled marks and segments are backgrounds, which printing
     drops by default (the check of a done step would vanish with them). */
  @media print {
    .ds-steps {
      -webkit-print-color-adjust: exact;
      print-color-adjust: exact;
    }
  }
}

/* ── components/toast/toast.css ── */
/*
 * Snackbar (Material 3): the inverse surface on the overlay elevation, at
 * the bottom left of the content panel. Icon and text, never colour alone.
 * Place the region right after .ds-app: next to a persistent drawer (or
 * its rail) it then starts at the panel's edge by itself.
 * Enters with a fade and a short rise on the spatial spring, leaves with a
 * quick fade in place while the messages around it close the gap.
 *
 *   <div class="ds-toasts"></div>
 *   DS.overlay.toast(region, 'Saved.');                      // or { kind: 'error' }, { persistent: true }
 *   DS.overlay.toast(region, '3 devices deleted.', { action: { label: 'Undo', onClick } });
 *
 *   <div class="ds-toast [ds-toast--error | ds-toast--info]">  what toast() builds from a string
 *     <svg ...>(checkCircle | alertCircle, 20)</svg>
 *     <span class="ds-toast__text">Saved.</span>
 *     <button class="ds-btn ds-btn--text ds-sm ds-toast__action" type="button">Undo</button>   with `action`
 *     <button class="ds-btn ds-btn--quiet ds-btn--icon ds-toast__close" type="button" aria-label="Close" data-tip="Close">(close)</button>
 *
 *   .ds-toast--shown  runtime: toast() marks a message whose entrance has
 *                     played, so moving its region never replays it
 *
 * Waiting and progress (3.0, DS.toast.promise() and progress() build them):
 *
 *   <div class="ds-toast" aria-busy="true">
 *     <span class="ds-spinner ds-toast__spinner" aria-hidden="true"></span>
 *     <span class="ds-toast__text">Exporting 240 devices</span> (close button)
 *   <div class="ds-toast ds-toast--progress">
 *     <div class="ds-toast__body"><span class="ds-toast__text" id="t">Uploading 3 files</span>
 *       <div class="ds-progress ds-progress--flat"><div class="ds-progress__track" role="progressbar" aria-labelledby="t" ...>
 *         <div class="ds-progress__bar"></div></div></div></div>
 *     <span class="ds-toast__value" aria-hidden="true">40%</span> (close button)
 *
 * The spinner turns in the icon's place and colour; the bar runs in the
 * inverse primary on a track of the inverse ink. Either turns into the
 * outcome's icon and text in place.
 *
 * A stack (3.0): <div class="ds-toasts ds-toasts--stack"> keeps its
 * messages one behind the other, the newest in front, the others showing
 * an edge above it (--ds-space-2 apart and narrower, at the front's height:
 * --ds-toast-front, written by toast.js) with their content hidden. Focus
 * inside or a click on a message expands it (data-expanded, written by
 * toast.js), never hover; the messages glide between the two (FLIP). The
 * stack is --ds-toast-stack-width wide (400px), across the width on phones.
 * data-ds-toast-limit="1...5" on any region: how many show at once.
 *
 * Options: shape multiplies the radius. Size and density change nothing: a
 * snackbar floats above the region it reports on and keeps one size, and its
 * action keeps 32px at any density. The tones of a message built by hand are
 * .ds-tone-error and .ds-tone-info, the same as --error and --info (toast()
 * reads all four for its kind); the word always says it.
 *
 * Any text button in a message (.ds-toast__action, or one of a message
 * built by hand) takes the inverse primary ink (--ds-toast-action-color)
 * and sits at the end, before the close button.
 *
 * DS.overlay.toast() (js/toast.js) stacks at most three with FLIP, evicts
 * the oldest message that would close by itself or queues one behind three
 * that stay, restarts the same message instead of stacking it, replaces a
 * message by its key, pauses the timers on hover, focus and a hidden tab,
 * announces the text through two .ds-sr live regions next to the region
 * (the region and the messages are not live, so their buttons stay
 * reachable; toast() takes role and aria-live off an old region), keeps
 * focus off <body> when a focused message leaves, and moves the region
 * into an open dialog (in place) or side sheet (with the panel's edge and
 * above its foot, data-follow), so messages stay above its scrim and
 * usable.
 *
 * Hooks: --ds-toast-action-color (the text button's ink, default
 * --ds-inverse-primary), --ds-toast-close-size (the close button, 36px),
 * --ds-toast-radius (--ds-radius-sm), --ds-toast-stack-width (400px).
 *
 * Forced colours: the transparent outline of a message becomes its edge;
 * the spinner and the bar take their own system colours.
 *
 * Runtime properties: --ds-toast-left (the region's left edge; a page sets
 * it when the panel starts elsewhere, DS.overlay in a side sheet),
 * --ds-toast-bottom (its distance from the bottom edge, page-set),
 * --ds-toast-lift (written by DS.overlay only: the room above a sheet's
 * foot, the modal drawer's foot on phones, a shown save bar),
 * --ds-keyboard-inset (the on-screen keyboard, DS.dom.followViewport() on
 * <html>), --ds-toast-shift and --ds-toast-shift-y (written by DS.overlay
 * only: the glide from where the region stood), and --ds-toast-reserve with
 * data-toast-reserve (the room kept for messages that stay: toast() sets
 * them on .ds-view, a hosting .ds-sheet__body or .ds-dialog, whose own
 * stylesheets read them; the page only
 * with `reserve: false`). data-ds-toast-room="off" (page-set, 2.1) on one
 * of those layers: it keeps no room, the others still do.
 *
 * Progressive:
 * - View Transitions (while DS.motion.transition() runs, data-ds-vt on
 *   <html>, a region with messages is named ds-toasts, so motion.css keeps
 *   it live and still above the page's groups; in the root snapshot the
 *   panel's opaque image would cover it until the end. One region with
 *   messages per page: transition() lifts the name of any further one):
 *   without them nothing is named.
 *
 * Print: the region is not printed (a message is about the screen, now).
 */

@layer ds.components.toast {
  /* Physical on purpose (D9): --ds-toast-left is a script coordinate (the
     left edge of the content panel), and DS.overlay reads the computed
     left back. */
  .ds-toasts {
    position: fixed;
    left: var(--ds-toast-left, var(--ds-space-6));
    bottom: calc(var(--ds-toast-bottom, var(--ds-space-6)) + var(--ds-toast-lift, 0px) + var(--ds-keyboard-inset, 0px));
    /* Above the home indicator (viewport-fit=cover); a margin, so `bottom`
       stays the offset a script may mirror. */
    margin-bottom: env(safe-area-inset-bottom);
    z-index: var(--ds-z-toast);
    display: grid;
    justify-items: start;
    /* The stack keeps to the bottom edge: while a leaving message holds the
       region's height (DS.motion.flip()), the others stay where they are. */
    align-content: end;
    gap: var(--ds-space-2);
    max-width: min(560px, calc(100vw - var(--ds-toast-left, var(--ds-space-6)) - var(--ds-space-6)));
    pointer-events: none;
    /* Moving into or out of a side sheet, above a foot or a save bar, the
       messages on screen start where they stood and glide to the new place
       on both axes (DS.overlay sets the shift for one style flush). */
    translate: var(--ds-toast-shift, 0px) var(--ds-toast-shift-y, 0px);
    transition: translate var(--ds-dur-medium) var(--ds-ease-in-out);
  }

  /* Following a side sheet (DS.overlay.open / close) or a save bar: the
     messages arrive with the panel's edge, on the sheet's own timing. */
  .ds-toasts[data-follow="enter"] {
    transition-duration: var(--ds-dur-long);
    transition-timing-function: var(--ds-ease-spatial);
  }

  .ds-toasts[data-follow="exit"] {
    transition-duration: var(--ds-dur-base);
    transition-timing-function: var(--ds-ease-exit);
  }

  /* Beside the persistent drawer (above 900px, shell.css): the panel's
     left edge plus the usual 24px. */
  @media (min-width: 901px) {
    .ds-app--drawer:not([data-drawer-hidden]) ~ .ds-toasts {
      --ds-toast-left: calc(var(--ds-drawer-width) + env(safe-area-inset-left) + var(--ds-space-6));
    }

    /* Beside the rail (data-drawer-collapsed): its narrower column. */
    .ds-app--drawer[data-drawer-collapsed]:not([data-drawer-hidden]) ~ .ds-toasts {
      --ds-toast-left: calc(var(--ds-drawer-rail-width) + env(safe-area-inset-left) + var(--ds-space-6));
    }
  }

  /* Beside the open modal drawer (601px to 900px): next to it, never under
     it. On phones the region spans the width; DS.overlay lifts it above
     the drawer's foot instead. */
  @media (min-width: 601px) and (max-width: 900px) {
    .ds-app[data-drawer-open] ~ .ds-toasts {
      --ds-toast-left: calc(var(--ds-drawer-width) + env(safe-area-inset-left) + var(--ds-space-6));
    }
  }

  .ds-toast {
    display: flex;
    align-items: center;
    gap: var(--ds-space-3);
    min-height: 48px;
    max-width: 100%;
    padding: var(--ds-space-3) var(--ds-space-4);
    border-radius: calc(var(--ds-toast-radius, var(--ds-radius-sm)) * var(--ds-shape, 1));
    background: var(--ds-inverse);
    color: var(--ds-on-inverse);
    font: var(--ds-font-body);
    box-shadow: var(--ds-elev-overlay);
    /* Invisible; forced colors paint it, so the message keeps an edge. */
    outline: 1px solid transparent;
    pointer-events: auto;
    --ds-motion-distance: var(--ds-distance-md);
    --ds-leave-duration: var(--ds-dur-fast);
    animation:
      ds-fade-in var(--ds-dur-medium) var(--ds-ease-in-out) backwards,
      ds-lift-in var(--ds-dur-medium) var(--ds-ease-spatial) backwards;
  }

  /* Played once (mark it .ds-toast--shown; toast() does after the
     entrance): moving the region into or out of a side sheet re-inserts
     the message where moveBefore() is missing, which would restart it, so
     a message already on screen would blink out and rise again. enter() and
     .ds-leave still play: the motion utilities sit in the ds.utilities
     layer, which beats this rule whatever its specificity. */
  .ds-toast--shown:not(.ds-leave) {
    animation: none;
  }

  .ds-toast > svg {
    flex-shrink: 0;
    color: var(--ds-inverse-primary);
  }

  .ds-toast__text {
    min-width: 0;
    overflow-wrap: anywhere;
  }

  /* Waiting: the spinner in the icon's place, size and colour, one size
     whatever the region's size class, as the rest of a message. */
  .ds-toast__spinner {
    /* One step up from the spinner's 16px: the icon's 20px. */
    --ds-size-step: 1;
    --ds-spinner-color: var(--ds-inverse-primary);
    flex-shrink: 0;
  }

  /* Progress: the text over the bar, the share at the end of the row. */
  .ds-toast--progress {
    min-width: min(320px, 100%);
  }

  .ds-toast__body {
    display: grid;
    flex: 1;
    gap: var(--ds-space-2);
    min-width: 0;
  }

  .ds-toast--progress .ds-progress {
    --ds-size-step: 0;
    --ds-progress-bar: var(--ds-inverse-primary);
    --ds-progress-track: color-mix(in srgb, var(--ds-on-inverse) 24%, transparent);
    --ds-progress-stop: color-mix(in srgb, var(--ds-on-inverse) 24%, transparent);
  }

  .ds-toast__value {
    flex-shrink: 0;
    min-width: 4ch;
    font: var(--ds-font-label);
    font-variant-numeric: tabular-nums;
    text-align: end;
  }

  /* On the inverse surface a tone shows through its icon and its word, never
     a colour of its own, so these two take the plain ink. */
  .ds-toast--error > svg,
  .ds-toast--info > svg,
  .ds-toast.ds-tone-error > svg,
  .ds-toast.ds-tone-info > svg {
    color: var(--ds-on-inverse);
  }

  /* A text button in a message (the action of toast(), or Undo in a message
     built by hand): the inverse primary ink, readable on the inverse
     surface, at the end of the line; its pill overhangs the padding, so the
     message keeps its height. */
  .ds-toast > .ds-btn--text {
    --ds-btn-color: var(--ds-toast-action-color, var(--ds-inverse-primary));
    --ds-btn-hover-color: var(--ds-toast-action-color, var(--ds-inverse-primary));
    flex-shrink: 0;
    margin-block: calc(-1 * var(--ds-space-2));
    margin-inline-start: auto;
  }

  /* The action is 32px with 12px of side padding at any density: a snackbar
     floats above the region it reports on and keeps one size. */
  .ds-toast__action.ds-sm {
    --ds-density: 0;
    --ds-btn-padding-x: var(--ds-space-4);
  }

  .ds-toast > .ds-btn--text:focus-visible {
    outline-color: var(--ds-on-inverse);
  }

  /* The shared quiet icon button (state layers for hover and press), in the
     inverse text colour; toast.css loads after button.css, so these win. */
  .ds-toast__close {
    /* One size whatever the region's size class, as the action; only .ds-touch changes it. */
    --ds-size-step: 0;
    --ds-btn-icon-size: var(--ds-toast-close-size, 36px);
    --ds-btn-quiet-color: var(--ds-on-inverse);
    --ds-btn-hover-color: var(--ds-on-inverse);
    flex-shrink: 0;
    margin-block: calc(-1 * var(--ds-space-2));
    margin-inline: auto calc(-1 * var(--ds-space-2));
  }

  /* After an action the close button keeps close to it. */
  .ds-toast > .ds-btn--text + .ds-toast__close {
    margin-inline-start: calc(-1 * var(--ds-space-1));
  }

  .ds-toast__close:focus-visible {
    outline-color: var(--ds-on-inverse);
  }

  /* While a message that stays shows (toast() measures and sets both, or the
     page with `reserve: false`), the content panel keeps room for it at its
     end: the last form actions can scroll clear of it. The panel's own
     padding is the safe area (shell.css). A side sheet's body does the
     same while the message shows in it (sheet.css). */
  .ds-view[data-toast-reserve] {
    padding-bottom: calc(env(safe-area-inset-bottom) + var(--ds-toast-reserve, 0px));
    scroll-padding-bottom: var(--ds-toast-reserve, 0px);
  }

  /* The stack (3.0): one width, so the messages behind the front line up
     with it; collapsed, every message sits in the one cell, the newest
     (the last, painted on top) in front. */
  .ds-toasts--stack {
    justify-items: stretch;
    width: min(var(--ds-toast-stack-width, 400px), calc(100vw - var(--ds-toast-left, var(--ds-space-6)) - var(--ds-space-6)));
  }

  .ds-toasts--stack:not([data-expanded]) > .ds-toast {
    grid-area: 1 / 1;
    align-self: end;
  }

  /* Behind the front: its height, an edge above it, the content hidden
     (still in the tab order: focus on it expands the stack first). */
  .ds-toasts--stack:not([data-expanded]) > .ds-toast:nth-last-child(n + 2 of .ds-toast:not([data-ds-leaving])) {
    height: var(--ds-toast-front, auto);
    min-height: 0;
    margin-inline: var(--ds-space-3);
    margin-bottom: var(--ds-space-2);
    overflow: hidden;
  }

  /* Each layer further back is narrower, so the edges read as a stack and
     not as one taller message. */
  .ds-toasts--stack:not([data-expanded]) > .ds-toast:nth-last-child(n + 3 of .ds-toast:not([data-ds-leaving])) {
    margin-inline: var(--ds-space-6);
    margin-bottom: var(--ds-space-4);
  }

  .ds-toasts--stack:not([data-expanded]) > .ds-toast:nth-last-child(n + 2 of .ds-toast:not([data-ds-leaving])) > * {
    opacity: 0;
    pointer-events: none;
  }

  /* The content behind the front fades. Not the buttons: toast is a later
     sublayer than button, so a transition here would replace their whole
     list (press morph, focus snap, colours); their own list already fades
     opacity on the same duration and curve. */
  .ds-toasts--stack > .ds-toast > :not(.ds-btn) {
    transition: opacity var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  /* A region with messages, only while a transition runs (see the header). */
  .ds-theme[data-ds-vt] .ds-toasts:has(> .ds-toast) {
    view-transition-name: ds-toasts;
  }

  /* Phones: across the width, above the bottom edge. */
  @media (max-width: 600px) {
    .ds-toasts {
      inset-inline: var(--ds-space-4);
      bottom: calc(var(--ds-toast-bottom, var(--ds-space-4)) + var(--ds-toast-lift, 0px) + var(--ds-keyboard-inset, 0px));
      max-width: none;
      justify-items: stretch;
    }

    .ds-toasts--stack {
      width: auto;
    }
  }

  /* Forced colours: the spinner's and the bar's own system colours (these
     rules above would otherwise win over theirs by layer). */
  @media (forced-colors: active) {
    .ds-toast__spinner {
      --ds-spinner-color: Highlight;
    }

    .ds-toast--progress .ds-progress {
      --ds-progress-bar: Highlight;
      --ds-progress-stop: Highlight;
      --ds-progress-track: GrayText;
    }
  }

  /* Print: messages stay on the screen. */
  @media print {
    .ds-toasts {
      display: none;
    }
  }
}

/* ── components/savebar/savebar.css ── */
/*
 * Save bar: the unsaved edits of a view, saved or discarded together. A
 * floating bar at the bottom of the view, centred in the page column,
 * sticky while the view scrolls; it takes no room of its own (height 0),
 * the view keeps its end clear of it while it shows.
 *
 *   <main class="ds-view" id="main" tabindex="-1">
 *     <div class="ds-content"> ... </div>
 *     <div class="ds-savebar">
 *       <div class="ds-savebar__bar ds-presence" role="region" aria-label="Unsaved changes" hidden>
 *         <p class="ds-savebar__text">2 unsaved changes</p>
 *         <div class="ds-savebar__actions">
 *           <button class="ds-btn ds-btn--text" type="button">Discard</button>
 *           <button class="ds-btn ds-btn--filled" type="button"><span class="ds-btn__faces">...</span></button>
 *         </div>
 *       </div>
 *     </div>
 *   </main>
 *
 *   const bar = DS.overlay.savebar(document.querySelector('.ds-savebar'), { focusTarget: () => form });
 *   bar.show();  bar.hide();  bar.update(() => { text.textContent = ... });
 *
 * In the flow (.ds-savebar--inline): the actions of a long form that is not
 * in a card stay in reach at every width. The last child of the form, it
 * takes the room of its bar and sticks to the bottom of the scroller while
 * the form is on screen: a flat surface with a hairline, running to the
 * edges of the page (--ds-savebar-bleed). No script, and no
 * DS.overlay.savebar(): it always shows (or `hidden` by the page). With no
 * script to measure it, its room is the least height at the largest size plus
 * a row for the words over the actions: a .ds-view keeps that clear by itself, so a focused field
 * scrolls clear of the bar; a scroller of the page's own takes
 * .ds-savebar-scroller, and --ds-savebar-room sets more. Snackbars of the theme
 * rise by the same room.
 * .ds-form-actions--sticky (form.css) is the same on phones only and
 * inline above; take this one where the wide layout needs it too.
 *
 *   <form class="ds-form"> ...
 *     <div class="ds-savebar ds-savebar--inline">
 *       <div class="ds-savebar__bar" role="group" aria-label="Form actions">
 *         <p class="ds-savebar__text">Changes apply after a restart</p>
 *         <div class="ds-savebar__actions"> (the buttons) </div>
 *
 * Options (src/core/options.css, docs/options.md), on the bar or any
 * ancestor; each is computed here, in the rule that uses it:
 *   size      .ds-xs ... .ds-xl: the least height 8px per step (its buttons
 *             take the same size from the same class)
 *   density   .ds-density-*: the least height 4px per step, the block padding
 *             2px per step; side padding and type stay
 *   shape     .ds-shape-*: multiplies the radius of the floating bar
 *   touch     .ds-touch: at least --ds-touch-target high; its buttons follow
 *   tone      none: the bar shows no status of its own
 *
 * Motion: .ds-presence (motion.css) with --ds-motion-scale at
 * --ds-scale-enter from the bottom edge: it fades in and grows on the
 * spring, leaves faster; a toggle mid-way continues from where it is.
 *
 * Runtime (written by DS.overlay.savebar(), owned): data-ds-savebar on the
 * view while the bar shows, data-ds-savebar-rest after a hide at the end of
 * the page (the room stays until the page scrolls away from the end), and
 * --ds-savebar-height (the bar's height, px). The view's scroll padding and
 * the content's bottom padding keep the bar's room: its height, its offset
 * and --ds-space-2; the room of snackbars that stay (--ds-toast-reserve)
 * moves into the content's padding meanwhile (a padding of the view would
 * lift the sticky bar).
 *
 * Hooks: --ds-savebar-offset (distance from the view's bottom edge,
 * --ds-space-4), --ds-savebar-inset (from the view's sides, the page pad
 * --ds-content-pad-x), --ds-savebar-min-height (the base of its least
 * height, 56px), --ds-savebar-radius (--ds-radius-card), --ds-savebar-bg
 * (--ds-surface-popover, the floating surface: the dark theme lifts it like
 * a menu; in the flow --ds-surface), --ds-savebar-shadow (--ds-elev-overlay),
 * --ds-savebar-bleed (in the flow: how far it runs beyond the form,
 * --ds-content-pad-x), --ds-savebar-room (in the flow: the room its scroller
 * and the snackbars keep clear of it).
 *
 * Forced colours: the floating bar keeps an edge (its transparent outline);
 * the bar in the flow keeps its hairline; its buttons are the system's.
 */

@layer ds.components.savebar {
  .ds-savebar {
    position: sticky;
    bottom: 0;
    z-index: var(--ds-z-sticky);
    flex-shrink: 0;
    height: 0;
    /* Under short content it still sits at the view's bottom (the view is
       a flex column, shell.css). */
    margin-top: auto;
  }

  .ds-savebar__bar {
    position: absolute;
    bottom: var(--ds-savebar-offset, var(--ds-space-4));
    /* The page column: the view's pad on both sides, at most as wide as
       the page, centred. */
    inset-inline: var(--ds-savebar-inset, var(--ds-content-pad-x, var(--ds-space-8)));
    max-width: var(--ds-content-max);
    margin-inline: auto;
    box-sizing: border-box;
    --_h: calc(var(--ds-savebar-min-height, 56px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px);
    min-height: max(var(--ds-target-min, 0px), var(--_h));
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--ds-space-2) var(--ds-space-4);
    padding-block: calc(var(--ds-space-2) + var(--ds-density, 0) * 2px);
    padding-inline: var(--ds-space-5) var(--ds-space-3);
    border-radius: calc(var(--ds-savebar-radius, var(--ds-radius-card)) * var(--ds-shape, 1));
    background: var(--ds-savebar-bg, var(--ds-surface-popover));
    color: var(--ds-text);
    box-shadow: var(--ds-savebar-shadow, var(--ds-elev-overlay));
    /* Invisible; forced colors paint it, so the bar keeps an edge. */
    outline: 1px solid transparent;
    --ds-motion-scale: var(--ds-scale-enter);
    transform-origin: 50% 100%;
  }

  /* Hidden also without .ds-base; .ds-presence keeps it displayed through
     its exit (display steps with allow-discrete). */
  .ds-savebar__bar[hidden] {
    display: none;
  }

  .ds-savebar__text {
    flex: 1 1 12em;
    min-width: 0;
    margin: 0;
    font: var(--ds-font-body);
    color: var(--ds-text);
  }

  .ds-savebar__actions {
    display: flex;
    flex-wrap: wrap;
    justify-content: flex-end;
    gap: var(--ds-space-2);
    margin-inline-start: auto;
  }

  /* In the flow: its bar has its own room and sticks at the bottom edge; a
     flat surface with a static hairline, running to the page's edges and
     clear of the home indicator. */
  .ds-savebar--inline {
    height: auto;
    margin-block-start: 0;
    margin-inline: calc(-1 * var(--ds-savebar-bleed, var(--ds-content-pad-x, 0px)));
  }

  .ds-savebar--inline > .ds-savebar__bar {
    position: static;
    max-width: none;
    margin-inline: 0;
    padding-block-end: calc(var(--ds-space-2) + var(--ds-density, 0) * 2px + env(safe-area-inset-bottom));
    padding-inline: var(--ds-savebar-bleed, var(--ds-content-pad-x, 0px));
    border-block-start: 1px solid var(--ds-line);
    border-radius: 0;
    background: var(--ds-savebar-bg, var(--ds-surface));
    box-shadow: none;
    outline: none;
  }

  /* While it shows (or rests after a hide at the end of the page), the view
     keeps its end clear of it: scrolling into view stops above the bar, and
     the content's last element can scroll above it. */
  .ds-view[data-ds-savebar] {
    scroll-padding-bottom: max(calc(var(--ds-savebar-height, 0px) + var(--ds-savebar-offset, var(--ds-space-4)) + var(--ds-space-2)), var(--ds-toast-reserve, 0px));
  }

  /* In the flow no script measures the bar, and a field under a sticky bar
     counts as in view, so the scroller keeps the room itself: the least height
     at the largest size and a row for the words the bar wraps over its actions.
     It reads no size or density: those may sit on the bar, out of the scroller's
     reach, and too much room only moves a scroll a little further. A measured
     room wins: no specificity, so the floating bar's above does, and not on a
     view that keeps the room of snackbars that stay (toast.css, whose rule
     sits in an earlier sublayer). */
  :where(.ds-view:not([data-toast-reserve]), .ds-savebar-scroller):where(:has(.ds-savebar--inline > .ds-savebar__bar:not([hidden]))) {
    scroll-padding-block-end: var(--ds-savebar-room, calc(var(--ds-savebar-min-height, 56px) + 2 * 8px + var(--ds-space-8) + var(--ds-space-2) + env(safe-area-inset-bottom)));
  }

  /* Snackbars rise above it, as DS.overlay.savebar() lifts them above the
     floating bar (a value it writes on the region wins). */
  .ds-theme:has(.ds-savebar--inline > .ds-savebar__bar:not([hidden])) .ds-toasts {
    --ds-toast-lift: var(--ds-savebar-room, calc(var(--ds-savebar-min-height, 56px) + 2 * 8px + var(--ds-space-8) + var(--ds-space-2) + env(safe-area-inset-bottom)));
  }

  /* The room of snackbars that stay (data-toast-reserve, toast.css) moves
     from the view's padding to the content's: a padding of the view would
     lift the sticky bar off the view's bottom, and the messages above it
     with it. */
  .ds-view[data-ds-savebar][data-toast-reserve] {
    padding-bottom: env(safe-area-inset-bottom);
  }

  /* --ds-content-pad-bottom is the content's own (page.css), phones
     included. */
  .ds-view:is([data-ds-savebar], [data-ds-savebar-rest]) > .ds-content {
    padding-bottom: max(var(--ds-content-pad-bottom), calc(var(--ds-savebar-height, 0px) + var(--ds-savebar-offset, var(--ds-space-4)) + var(--ds-space-2)), var(--ds-toast-reserve, 0px));
  }

  /* Outside a .ds-view (no page pad to read) the phone pad. */
  @media (max-width: 720px) {
    .ds-savebar__bar {
      inset-inline: var(--ds-savebar-inset, var(--ds-content-pad-x, var(--ds-space-4)));
    }
  }

  @media (max-width: 600px) {
    .ds-savebar__bar {
      padding-inline-start: var(--ds-space-4);
    }
  }

  @media print {
    .ds-savebar {
      display: none;
    }
  }
}

/* ── components/calendar/calendar.css ── */
/*
 * Calendar: the month grid that every date picker shares (the grid of the
 * WAI-ARIA date picker dialog), inline on a page or inside a picker's
 * popover. DS.calendar (calendar.js) renders it from Intl in the page's
 * locale: the month titles, the weekday heads, the first day of the week,
 * the week numbers and a full date as each day's name.
 *
 *   <div class="ds-calendar" data-ds-calendar data-ds-value="2026-11-04"
 *        [data-ds-calendar-min="2026-01-01"] [data-ds-calendar-max]
 *        [data-ds-calendar-disabled="6,7,2026-12-24"] [data-ds-calendar-weeks]
 *        [data-ds-calendar-months="2"] [data-ds-calendar-mode="range"]></div>
 *
 * What the script renders inside, per month:
 *
 *   <div class="ds-calendar__months">
 *     <div class="ds-calendar__month" [data-turn="next | back"]>
 *       <div class="ds-calendar__caption">
 *         <button class="ds-btn ds-btn--quiet ds-btn--icon ds-calendar__nav" type="button" aria-label="Previous month">(chevronLeft)</button>
 *         <span class="ds-calendar__title" aria-live="polite">November 2026</span>
 *         <span class="ds-calendar__spacer"></span>   (in place of a button)
 *       </div>
 *       <table class="ds-calendar__grid" role="grid" aria-labelledby="(title)">
 *         <thead><tr>[<th class="ds-calendar__week" scope="col">]<th scope="col" abbr="Monday">M</th> ...</tr></thead>
 *         <tbody><tr>[<th class="ds-calendar__week" scope="row">45</th>]
 *           <td></td>   (a day of another month: empty)
 *           <td [aria-selected="true"] [data-range="start | middle | end | single"] [data-preview="..."]>
 *             <button class="ds-calendar__day" type="button" tabindex="-1 | 0" data-date="2026-11-04"
 *                     aria-label="Wednesday, November 4, 2026" [aria-current="date"] [aria-disabled="true"]>4</button>
 *           </td> ...
 *
 * States: the chosen day is filled in the action colour (aria-selected on
 * its cell); today has a ring in the action colour (aria-current="date");
 * a day that may not be picked takes the disabled ink and no press
 * (aria-disabled, still focusable so its name is read). A range lays a
 * band in --ds-accent from its start to its end (data-range), the two ends
 * filled; while the second end is chosen a lighter band previews it
 * (data-preview). Every state is an attribute, so none is told by colour
 * alone.
 *
 * Options (src/core/options.css, docs/options.md), on the calendar or any
 * ancestor; each is computed here, in the rule that uses it:
 *   size      .ds-xs ... .ds-xl: a day 8px per step from
 *             --ds-calendar-cell (40px), the type of the size
 *             (--ds-size-font, the body role by default)
 *   density   .ds-density-*: a day 4px per step
 *   shape     .ds-shape-*: multiplies the rest and pressed radius of a day
 *             (round at the default, square at .ds-shape-square)
 *   touch     .ds-touch: a day at least --ds-touch-target, whatever the
 *             size and the density
 *   tone      none: a calendar shows no status
 *
 * Press and focus: a day is an action (DS.ripple.attach() gives it the
 * ripple): a state layer in its ink (hover, press in --ds-dur-micro), the
 * press morph towards --ds-radius-action-pressed that springs back, and
 * the focus ring that snaps in. A blocked day shows neither hover nor
 * press.
 *
 * Motion: a turned page slides in from its side (DS.motion.enter(month,
 * 'slide'): ds-fade-in and ds-shift-in on the spring, --ds-motion-distance
 * from data-turn, mirrored right to left); the band and the fills change
 * colour over --ds-dur-fast.
 *
 * Forced colours: a chosen day and the band are SelectedItem /
 * SelectedItemText, the ends of a range carry a CanvasText ring inside the
 * fill, the preview a dashed edge, today keeps its ring (a border), a
 * blocked day is GrayText, and a focused chosen day a CanvasText ring.
 */

@layer ds.components.calendar {
  .ds-calendar {
    /* A day: the hook at md and comfortable, 8px per size step, 4px per
       density step, never below the touch minimum. */
    --_cell: max(var(--ds-target-min, 0px), calc(var(--ds-calendar-cell, 40px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px));
    display: inline-block;
    max-inline-size: 100%;
    color: var(--ds-text);
    font: var(--ds-calendar-font, var(--ds-size-font, var(--ds-font-body)));
  }

  /* One month, or two side by side; they wrap under each other when the
     room is too narrow. The clip keeps a turning page inside, with room
     for the focus ring. */
  .ds-calendar__months {
    display: flex;
    flex-wrap: wrap;
    gap: var(--ds-space-6);
    margin: calc(-1 * var(--ds-space-1));
    padding: var(--ds-space-1);
    overflow: clip;
  }

  .ds-calendar__month {
    min-inline-size: 0;
  }

  /* The page turns towards where it comes from (DS.motion.enter, 'slide'). */
  .ds-calendar__month[data-turn="next"] {
    --ds-motion-distance: var(--ds-distance-xl);
  }

  .ds-calendar__month[data-turn="back"] {
    --ds-motion-distance: calc(-1 * var(--ds-distance-xl));
  }

  .ds-calendar__month[data-turn="next"]:dir(rtl) {
    --ds-motion-distance: calc(-1 * var(--ds-distance-xl));
  }

  .ds-calendar__month[data-turn="back"]:dir(rtl) {
    --ds-motion-distance: var(--ds-distance-xl);
  }

  .ds-calendar__caption {
    display: flex;
    align-items: center;
    gap: var(--ds-space-1);
    margin-block-end: var(--ds-space-1);
  }

  .ds-calendar__title {
    flex: 1;
    min-inline-size: 0;
    overflow: hidden;
    font: var(--ds-font-label);
    text-align: center;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  /* As wide as the icon button it stands for, so the title stays centred. */
  .ds-calendar__spacer {
    flex: none;
    inline-size: max(var(--ds-target-min, 0px), calc(var(--ds-btn-icon-size, 40px) + var(--ds-size-step, 0) * 8px));
  }

  /* Right to left the arrows point the other way. */
  .ds-calendar__nav:dir(rtl) svg {
    scale: -1 1;
  }

  .ds-calendar__grid {
    border-collapse: collapse;
    border-spacing: 0;
    table-layout: fixed;
  }

  .ds-calendar__grid th {
    inline-size: var(--_cell);
    block-size: calc(var(--_cell) * 0.75);
    padding: 0;
    color: var(--ds-text-2);
    font: var(--ds-font-caption);
    text-align: center;
  }

  .ds-calendar__grid td {
    inline-size: var(--_cell);
    block-size: var(--_cell);
    padding: 0;
    text-align: center;
  }

  /* The week numbers: a narrower column in the quieter ink. */
  .ds-calendar__grid .ds-calendar__week {
    inline-size: calc(var(--_cell) * 0.75);
    color: var(--ds-text-3);
    font: var(--ds-font-caption);
    font-variant-numeric: tabular-nums;
  }

  .ds-calendar__day {
    --_half: calc(var(--_cell) / 2);
    --_radius: min(calc(min(var(--ds-radius-action), var(--_half)) * var(--ds-shape, 1)), var(--_half));
    position: relative;
    isolation: isolate;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    inline-size: var(--_cell);
    block-size: var(--_cell);
    margin: 0;
    padding: 0;
    /* Transparent at rest: today's ring, and the edge forced colours keep. */
    border: 1px solid transparent;
    border-radius: var(--_radius);
    background: transparent;
    color: var(--ds-text);
    font: inherit;
    font-variant-numeric: tabular-nums;
    cursor: pointer;
    -webkit-tap-highlight-color: transparent;
    /* The ring rests one width further out and snaps in. */
    outline-offset: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    transition:
      background-color var(--ds-dur-fast) var(--ds-ease-in-out),
      border-color var(--ds-dur-fast) var(--ds-ease-in-out),
      color var(--ds-dur-fast) var(--ds-ease-in-out),
      border-radius var(--ds-dur-medium) var(--ds-ease-spatial),
      outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  /* State layer in the day's ink. */
  .ds-calendar__day::before {
    content: '';
    position: absolute;
    inset: -1px;
    z-index: -1;
    border-radius: inherit;
    background: currentColor;
    opacity: 0;
    pointer-events: none;
    transition: opacity var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  @media (hover: hover) {
    .ds-calendar__day:hover:not([aria-disabled="true"])::before {
      opacity: var(--ds-state-hover);
    }
  }

  .ds-calendar__day:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: var(--ds-focus-offset);
  }

  .ds-calendar__day:focus-visible::before {
    opacity: var(--ds-state-focus);
    transition-duration: 0s;
  }

  /* Press-in in --ds-dur-micro (.ds-pressed: js/ripple.js holds it). */
  .ds-calendar__day:active:not([aria-disabled="true"])::before,
  .ds-calendar__day.ds-pressed:not([aria-disabled="true"])::before {
    opacity: var(--ds-state-pressed);
    transition-duration: var(--ds-dur-micro);
  }

  .ds-calendar__day:active:not(:disabled, [aria-disabled="true"], [aria-busy="true"]),
  .ds-calendar__day.ds-pressed:not(:disabled, [aria-disabled="true"], [aria-busy="true"]) {
    border-radius: min(calc(var(--ds-radius-action-pressed) * var(--ds-shape, 1)), var(--_radius));
    transition: border-radius var(--ds-dur-micro) var(--ds-ease-out);
  }

  /* With DS.ripple.attach() the ripple brings the press; the flat layer
     stays at its hover value. */
  :where(.ds-ripples) .ds-calendar__day:where(:not([data-ds-ripple="off"], [data-ds-ripple="off"] *, [aria-disabled="true"])):is(:active, .ds-pressed)::before {
    opacity: 0;
  }

  @media (hover: hover) {
    :where(.ds-ripples) .ds-calendar__day:where(:not([data-ds-ripple="off"], [data-ds-ripple="off"] *, [aria-disabled="true"])):is(:active, .ds-pressed)::before {
      opacity: var(--ds-state-hover);
    }
  }

  /* Today: a ring in the action colour (and aria-current="date"). */
  .ds-calendar__day[aria-current="date"] {
    border-color: var(--ds-calendar-today, var(--ds-primary));
    color: var(--ds-calendar-today, var(--ds-primary));
  }

  /* Blocked: the disabled ink, no hover and no press. */
  .ds-calendar__day[aria-disabled="true"] {
    color: var(--ds-disabled-ink);
    cursor: default;
  }

  /* The chosen day, and the two ends of a range: filled. */
  .ds-calendar td[aria-selected="true"] > .ds-calendar__day {
    border-color: transparent;
    background: var(--ds-calendar-selected-bg, var(--ds-primary));
    color: var(--ds-calendar-selected-color, var(--ds-on-primary));
  }

  /* The band of a range, under the day: whole cells in between, the inner
     half of the cells at the ends (logical, so it follows the writing
     direction). */
  .ds-calendar td:is([data-range], [data-preview]) {
    position: relative;
  }

  .ds-calendar td:is([data-range], [data-preview])::before {
    content: '';
    position: absolute;
    inset: 0;
    background: var(--ds-calendar-range-bg, var(--ds-accent));
    pointer-events: none;
  }

  .ds-calendar td:is([data-range="start"], [data-preview="start"])::before {
    inset-inline-start: 50%;
  }

  .ds-calendar td:is([data-range="end"], [data-preview="end"])::before {
    inset-inline-end: 50%;
  }

  .ds-calendar td:is([data-range="single"], [data-preview="single"])::before {
    content: none;
  }

  /* A day inside the band is no end: the band's ink, no fill. */
  .ds-calendar td[data-range="middle"] > .ds-calendar__day {
    border-color: transparent;
    background: transparent;
    color: var(--ds-on-accent);
  }

  /* The preview while the second end is chosen: the band at the pressed
     layer's strength; the anchor stays filled. */
  .ds-calendar td[data-preview]::before {
    background: color-mix(in srgb, var(--ds-calendar-range-bg, var(--ds-accent)) calc(var(--ds-state-pressed) * 100%), transparent);
  }

  @media (forced-colors: active) {
    .ds-calendar td[aria-selected="true"] > .ds-calendar__day {
      forced-color-adjust: none;
      border-color: SelectedItem;
      background: SelectedItem;
      color: SelectedItemText;
    }

    .ds-calendar td[data-range]::before {
      forced-color-adjust: none;
      background: SelectedItem;
    }

    .ds-calendar td[data-range="middle"] > .ds-calendar__day {
      color: SelectedItemText;
    }

    /* The ends: a ring of the text colour inside the fill. */
    .ds-calendar td:is([data-range="start"], [data-range="end"]) > .ds-calendar__day {
      border-color: CanvasText;
    }

    .ds-calendar td[data-preview]::before {
      border-block: 1px dashed CanvasText;
      background: none;
    }

    .ds-calendar__day[aria-current="date"] {
      border-color: CanvasText;
    }

    .ds-calendar__day[aria-disabled="true"] {
      color: GrayText;
    }

    .ds-calendar td[aria-selected="true"] > .ds-calendar__day:focus-visible {
      outline-color: CanvasText;
    }
  }
}

/* ── components/container/container.css ── */
/*
 * Container presets: three widths a region can have, as classes that
 * query the nearest container instead of the window, so a part of the
 * page reacts to the room it has (a side sheet, a card, the page beside
 * an open drawer).
 *
 *   <section class="ds-container">                   a container (inline size)
 *     <span class="ds-hide-compact">Last synced 09:12</span>
 *     <button class="ds-btn ds-only-compact" type="button">More</button>
 *     <div class="ds-cluster ds-stack-compact">actions ...</div>
 *   </section>
 *
 * The sizes (Material 3 window classes, applied to the container):
 *   compact    narrower than 600px (a phone, a side sheet, a narrow card)
 *   medium     600px to 839px
 *   expanded   840px and wider
 *
 *   .ds-hide-compact, .ds-hide-medium, .ds-hide-expanded   hidden at that size
 *   .ds-only-compact, .ds-only-medium, .ds-only-expanded   shown at that size only
 *   .ds-stack-compact   a flex row that turns into a column of full-width
 *                       items at the compact size (a form's or a head's
 *                       actions on a phone)
 *
 * Hide below or above a size by combining two: below expanded is
 * .ds-hide-compact.ds-hide-medium, above compact
 * .ds-hide-medium.ds-hide-expanded.
 *
 * The nearest container decides: a .ds-container, the page's content
 * (.ds-content, the styleguide stage) or a component that is one. With no
 * container around, no query matches: every element shows and nothing
 * stacks. .ds-container takes inline-size containment: its width no
 * longer follows its content, so it is a block, or a flex or grid item
 * with a width of its own.
 *
 * Hiding is display: none with !important, as the hidden attribute is:
 * the element leaves the layout and the accessibility tree, whatever
 * display a component gives it. Keep a name or an action that only one
 * size shows reachable at the others (an icon button's label, a "More"
 * menu).
 *
 * Options: none read; these classes have no look.
 */

@layer ds.components.container {
  .ds-container {
    container-type: inline-size;
  }

  /* One rule per size: what hides at it. */
  @container (width < 600px) {
    .ds-hide-compact,
    .ds-only-medium,
    .ds-only-expanded {
      display: none !important;
    }

    .ds-stack-compact {
      flex-direction: column;
      flex-wrap: nowrap;
      align-items: stretch;
    }

    /* Full width in the column: an auto margin would pull the item to one
       side instead. */
    .ds-stack-compact > .ds-push {
      margin-inline-start: 0;
    }
  }

  @container (600px <= width < 840px) {
    .ds-hide-medium,
    .ds-only-compact,
    .ds-only-expanded {
      display: none !important;
    }
  }

  @container (width >= 840px) {
    .ds-hide-expanded,
    .ds-only-compact,
    .ds-only-medium {
      display: none !important;
    }
  }
}

/* ── components/loadmore/loadmore.css ── */
/*
 * Load more and infinite scroll: the end of a list that grows by pages. A
 * status line and a "Load more" button; with data-ds-loadmore-auto the
 * element is also the sentinel of an infinite scroll (js/loadmore.js, an
 * IntersectionObserver), and the button stays as the way in for keyboards,
 * screen readers and a page whose footer must stay reachable:
 *
 *   <ul class="ds-list" id="devices" aria-label="Devices"> ... </ul>
 *   <div class="ds-loadmore" data-ds-loadmore data-ds-loadmore-for="#devices"
 *        data-ds-loadmore-loaded="50" data-ds-loadmore-total="1234" data-ds-loadmore-auto="3">
 *     <p class="ds-loadmore__status">(alertCircle 16 .ds-loadmore__icon)<span class="ds-loadmore__text">Showing 50 of 1,234</span></p>
 *     <button class="ds-btn ds-loadmore__button" type="button"><span class="ds-btn__faces">
 *       <span class="ds-btn__face">Load more</span>
 *       <span class="ds-btn__face ds-btn__face--busy" aria-hidden="true"><span class="ds-spinner ds-spinner--ink ds-sm"></span>Loading</span>
 *     </span></button>
 *   </div>
 *
 *   .ds-loadmore--inline   the status at the start and the button at the
 *                          end of one row (the foot of a list in a card)
 *
 * State, written by the system: data-state on .ds-loadmore, "loading",
 * "error" or "done" (none: ready). Loading: the button's busy face (after
 * --ds-delay-loader, DS.motion.busy()) and aria-busy on the list. Error:
 * the status says so in words, with the alert icon in the error ink, and
 * the button tries again. Done: the button goes and the status says that
 * everything shows; a button that had the focus hands it to the status.
 *
 * Options (src/core/options.css, docs/options.md), on .ds-loadmore or any
 * ancestor:
 *   size, shape, touch  reach the button, which computes them
 *   density             2px per step of the block padding (from
 *                       --ds-loadmore-padding, 16px) and the gap
 * The status keeps the meta role. There is no tone: the error state is
 * the error ink with an icon and words, never the colour alone.
 *
 * Forced colours: the icon and the status are text in the system colours;
 * the error still says so in words.
 *
 * Hooks: --ds-loadmore-padding (16px). The computed --_pad and --_gap are
 * private: never set them.
 *
 * No progressive feature (IntersectionObserver is at the floor).
 */

@layer ds.components.loadmore {
  .ds-loadmore {
    --_pad: max(0px, calc(var(--ds-loadmore-padding, var(--ds-space-4)) + var(--ds-density, 0) * 2px));
    --_gap: max(var(--ds-space-1), calc(var(--ds-space-2) + var(--ds-density, 0) * 2px));
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: var(--_gap);
    padding-block: var(--_pad);
    text-align: center;
  }

  .ds-loadmore--inline {
    flex-direction: row;
    flex-wrap: wrap;
    justify-content: space-between;
    padding-inline: var(--_pad);
    text-align: start;
  }

  .ds-loadmore__status {
    display: inline-flex;
    align-items: center;
    gap: var(--ds-space-1);
    margin: 0;
    border-radius: calc(var(--ds-radius-xs) * var(--ds-shape, 1));
    /* The ring rests (invisible) one width further out and snaps in. */
    outline-offset: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    transition: outline-offset var(--ds-dur-fast) var(--ds-ease-out);
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
    font-variant-numeric: tabular-nums;
  }

  /* An empty status (the page writes none, nothing loaded yet) takes no room. */
  .ds-loadmore__status:not(:has(.ds-loadmore__text:not(:empty))) {
    display: none;
  }

  .ds-loadmore__icon {
    display: none;
    flex: none;
  }

  .ds-loadmore[data-state="error"] .ds-loadmore__status {
    color: var(--ds-loadmore-error-color, var(--ds-error));
  }

  .ds-loadmore[data-state="error"] .ds-loadmore__icon {
    display: inline-block;
  }

  .ds-loadmore[data-state="done"] .ds-loadmore__button {
    display: none;
  }

  /* The status takes the focus from a button that went: a ring, not a box. */
  .ds-loadmore__status:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: var(--ds-focus-offset);
  }
}

/* ── components/popover/popover.css ── */
/*
 * Popover: an anchored, non-modal panel next to the control that opened it
 * (a filter form, a share box, a preview), on the popover elevation, with an
 * optional arrow at its anchor. It never traps focus and never dims the page:
 * a pointerdown outside it, Escape and focus leaving it close it.
 *
 *   <button class="ds-btn" type="button" aria-haspopup="dialog" aria-expanded="false" aria-controls="share"
 *           data-ds-popover="#share" [data-ds-popover-placement="bottom | top | start | end"]
 *           [data-ds-popover-align="start | center | end"] [data-ds-popover-trigger="click | hover"]>Share</button>
 *   <div class="ds-popover [ds-popover--arrow] [ds-popover--tip]" id="share" role="dialog" aria-labelledby="share-t" hidden
 *        data-state="open | closed" [data-placement="top | start | end"] [popover]>
 *     <div class="ds-popover__head">
 *       <h2 class="ds-popover__title" id="share-t">Share</h2>
 *       <button class="ds-btn ds-btn--quiet ds-btn--icon ds-popover__close" type="button" aria-label="Close" data-ds-close>(x)</button>
 *     </div>
 *     <div class="ds-popover__body">…</div>
 *     <div class="ds-popover__foot">…buttons…</div>
 *   </div>
 *
 *   DS.popover.open(el, { opener, placement, align, focus });   DS.popover.close(el);
 *
 * Variants: .ds-popover--arrow points at the anchor (a square turned by 45°,
 * on the edge that faces it, at --ds-popover-arrow from the box's start);
 * .ds-popover--tip is the help card of a toggletip, a rich tooltip and a
 * hover card: narrower (--ds-popover-tip-width), tighter, its title in the
 * label role and its text in the meta role.
 *
 * Parts: __head (the title and an optional close button), __title, __body
 * (the part that scrolls when the room on its side is short), __foot (the
 * actions, at the end), __close (pulls the close button into the head's
 * corner).
 *
 * Options: density steps the padding of every part (2px per step); shape
 * multiplies the radius (--ds-popover-radius); size and tone change nothing:
 * a popover holds the page's own content, which carries its own size.
 *
 * Placement (js/popover.js, through js/position.js): on the side asked for
 * (bottom by default, aligned with the anchor's start edge; flipped to the
 * other side when it does not fit there and that side has more room, kept
 * --ds-space-2 inside the viewport, never taller than the room on its side,
 * so its body scrolls), in the top layer as popover="manual", at the script
 * coordinates --ds-popover-x and --ds-popover-y; data-placement says the side
 * when it is not the bottom one, and follows scrolling and resizing.
 *
 * Motion: as a menu, it grows out of its anchor: it fades in over
 * --ds-dur-fast while it grows from --ds-scale-popup at the anchor
 * (--ds-motion-origin, the arrow's tip) and its clip opens from the anchor's
 * edge, both over --ds-dur-medium on the spring; it leaves with a fade
 * (--ds-dur-instant). Transitions keyed on data-state (DS.overlay), so a
 * popover closed mid-way turns back from where it is; without data-state (a
 * page that drops hidden by hand) ds-fade-in and ds-clip-in play once.
 *
 * Forced colours: its transparent outline becomes its edge; the arrow, which
 * forced colours would paint as a Canvas square without an edge, goes.
 *
 * Hooks: --ds-popover-width (360px), --ds-popover-tip-width (320px),
 * --ds-popover-tip-padding (--ds-space-3),
 * --ds-popover-padding (--ds-space-4), --ds-popover-radius (--ds-radius-md).
 *
 * Print: an open popover is not printed.
 *
 * Progressive:
 * - scrollbar-color and scrollbar-width (a thin scrollbar in a long body):
 *   without them the platform scrollbar shows.
 */

@layer ds.components.popover {
  /* Fixed, so no scrolling or clipping box cuts it off; inset, margin, border
     and overflow double as the reset of the UA box of a popover. Physical on
     purpose: --ds-popover-x is a script coordinate from the left. */
  .ds-popover {
    --_pad: calc(var(--ds-popover-padding, var(--ds-space-4)) + var(--ds-density, 0) * 2px);
    position: fixed;
    inset: var(--ds-popover-y, 0px) auto auto var(--ds-popover-x, 0px);
    z-index: var(--ds-z-popover);
    display: flex;
    flex-direction: column;
    box-sizing: border-box;
    width: max-content;
    min-width: 0;
    max-width: min(var(--ds-popover-width, 360px), calc(100vw - 2 * var(--ds-space-2)));
    max-height: calc(100vh - 2 * var(--ds-space-2));
    margin: 0;
    padding: 0;
    overflow: visible;
    border: 0;
    border-radius: calc(var(--ds-popover-radius, var(--ds-radius-md)) * var(--ds-shape, 1));
    background: var(--ds-surface-popover);
    color: var(--ds-text);
    font: var(--ds-font-body);
    text-align: start;
    box-shadow: var(--ds-elev-popover);
    /* Invisible; forced colors paint it, so the popover keeps an edge. It
       also stands for the ring when focus is on the panel itself (nothing
       inside takes it): the panel is the context, not a control. */
    outline: 1px solid transparent;
    /* Grows at its anchor (originFrom() writes the origin); its clip rests
       --ds-space-6 beyond the box, room for the shadow and the arrow. */
    transform-origin: var(--ds-motion-origin, 0% 0%);
    clip-path: inset(calc(-1 * var(--ds-space-6)));
  }

  .ds-popover[data-placement="top"] {
    transform-origin: var(--ds-motion-origin, 0% 100%);
  }

  /* Shown by hand (no data-state): the reveal plays once. */
  .ds-popover:not([data-state]) {
    animation:
      ds-fade-in var(--ds-dur-fast) var(--ds-ease-in-out) backwards,
      ds-clip-in var(--ds-dur-medium) var(--ds-ease-spatial) backwards;
  }

  /* Driven by DS.overlay: transitions keyed on data-state, so a popover
     closed mid-way continues from where it is. */
  .ds-popover[data-state] {
    animation: none;
    transition:
      opacity var(--ds-dur-fast) var(--ds-ease-in-out),
      scale var(--ds-dur-medium) var(--ds-ease-spatial),
      clip-path var(--ds-dur-medium) var(--ds-ease-spatial);
  }

  /* The exit only fades, in --ds-dur-instant; scale and clip go back to
     their start once it is invisible. Closed, it takes no pointer. */
  .ds-popover[data-state="closed"] {
    opacity: 0;
    scale: var(--ds-motion-scale, var(--ds-scale-popup));
    clip-path: var(--ds-clip-from, inset(0 0 100% 0));
    pointer-events: none;
    transition:
      opacity var(--ds-dur-instant) var(--ds-ease-in-out),
      scale 0ms var(--ds-ease-in-out) var(--ds-dur-instant),
      clip-path 0ms var(--ds-ease-in-out) var(--ds-dur-instant);
  }

  .ds-popover[hidden] {
    display: none;
  }

  .ds-popover__head {
    display: flex;
    flex-shrink: 0;
    align-items: center;
    gap: var(--ds-space-2);
    padding: var(--_pad) var(--_pad) 0;
  }

  .ds-popover__title {
    flex: 1;
    min-width: 0;
    margin: 0;
    color: var(--ds-text);
    font: var(--ds-font-subtitle);
    overflow-wrap: anywhere;
  }

  /* The close button sits in the head's corner: its own box overlaps the
     padding, so its glyph lines up with the text below. */
  .ds-popover__close {
    flex-shrink: 0;
    margin-block: calc(-1 * var(--ds-space-2));
    margin-inline-end: calc(-1 * var(--ds-space-2));
  }

  /* The part that scrolls when the popover is capped by the room on its side. */
  .ds-popover__body {
    position: relative;
    flex: 1 1 auto;
    min-height: 0;
    padding: var(--_pad);
    overflow: auto;
    overscroll-behavior: contain;
    color: var(--ds-text-2);
    scrollbar-width: thin;
    scrollbar-color: var(--ds-line-2) transparent;
  }

  .ds-popover__head + .ds-popover__body {
    padding-block-start: var(--ds-space-2);
  }

  .ds-popover__body > :first-child {
    margin-block-start: 0;
  }

  .ds-popover__body > :last-child {
    margin-block-end: 0;
  }

  .ds-popover__foot {
    display: flex;
    flex-shrink: 0;
    flex-wrap: wrap;
    justify-content: flex-end;
    align-items: center;
    gap: var(--ds-space-2);
    padding: 0 var(--_pad) var(--_pad);
  }

  .ds-popover__head:last-child {
    padding-block-end: var(--_pad);
  }

  /* The help card: a toggletip, a rich tooltip, a hover card. */
  .ds-popover--tip {
    --_pad: calc(var(--ds-popover-tip-padding, var(--ds-space-3)) + var(--ds-density, 0) * 2px);
    max-width: min(var(--ds-popover-tip-width, 320px), calc(100vw - 2 * var(--ds-space-2)));
    font: var(--ds-font-meta);
  }

  .ds-popover--tip .ds-popover__title {
    font: var(--ds-font-label);
  }

  .ds-popover--tip .ds-popover__head + .ds-popover__body {
    padding-block-start: var(--ds-space-1);
  }

  .ds-popover--tip .ds-popover__foot {
    justify-content: flex-start;
  }

  /*
   * The arrow: a square turned by 45° that straddles the edge facing the
   * anchor, in the panel's own surface; its centre is --ds-popover-arrow
   * (written by the script) from the box's start along that edge. Physical on
   * purpose on the block sides: the script coordinate runs from the left.
   */
  .ds-popover--arrow::before {
    content: '';
    position: absolute;
    top: calc(var(--ds-space-3) / -2);
    left: calc(var(--ds-popover-arrow, var(--ds-space-6)) - var(--ds-space-3) / 2);
    width: var(--ds-space-3);
    height: var(--ds-space-3);
    background: inherit;
    rotate: 45deg;
    pointer-events: none;
  }

  .ds-popover--arrow[data-placement="top"]::before {
    top: auto;
    bottom: calc(var(--ds-space-3) / -2);
  }

  .ds-popover--arrow:is([data-placement="start"], [data-placement="end"])::before {
    top: calc(var(--ds-popover-arrow, var(--ds-space-6)) - var(--ds-space-3) / 2);
    bottom: auto;
    left: auto;
  }

  /* Beside its anchor: the arrow on the edge that faces it. */
  .ds-popover--arrow[data-placement="start"]::before {
    inset-inline-end: calc(var(--ds-space-3) / -2);
  }

  .ds-popover--arrow[data-placement="end"]::before {
    inset-inline-start: calc(var(--ds-space-3) / -2);
  }

  @media (forced-colors: active) {
    .ds-popover--arrow::before {
      display: none;
    }
  }

  @media print {
    .ds-popover {
      display: none;
    }
  }
}

/* ── components/splitpane/splitpane.css ── */
/*
 * Split pane: two or three panes side by side (or stacked), with a divider
 * between each pair that resizes them: the WAI-ARIA window splitter
 * (js: DS.splitpane). Each pane scrolls on its own.
 *
 *   <div class="ds-splitpane" data-ds-splitpane data-ds-splitpane-store="devices">
 *     <section class="ds-splitpane__pane" id="device-list" aria-label="Devices" data-ds-splitpane-collapsible
 *              style="--ds-splitpane-size: 320px; --ds-splitpane-min: 240px; --ds-splitpane-max: 50%"> ... </section>
 *     <div class="ds-splitpane__divider" role="separator" tabindex="0" aria-controls="device-list" aria-label="Resize the device list"></div>
 *     <section class="ds-splitpane__pane ds-splitpane__pane--fill" aria-label="Details">
 *       <div class="ds-splitpane__body"> ... </div>
 *     </section>
 *   </div>
 *
 * Panes:
 *   .ds-splitpane__pane        a pane with a size of its own: the start size
 *                              in --ds-splitpane-size (any length or
 *                              percentage of the split pane; default 50%),
 *                              its limits in --ds-splitpane-min (0) and
 *                              --ds-splitpane-max (100%), set on the pane
 *   .ds-splitpane__pane--fill  the pane that takes the rest (one per split
 *                              pane; without one, the last pane does)
 *   .ds-splitpane__body        padded content of a pane (a pane itself has
 *                              no padding, so it can collapse to nothing);
 *                              a .ds-list right in a pane loses its frame
 *                              and runs to the pane's edges
 * The three are registered and do not inherit, so a split pane inside a
 * pane starts from the defaults. Three panes: give the outer two a size and
 * the middle one --fill (a list, the work area, an inspector).
 *
 * Dividers: .ds-splitpane__divider, between two panes, a hairline
 * (--ds-splitpane-line, --ds-line) with a grip in its middle
 * (--ds-splitpane-grip, --ds-outline) and a hit area wider than the line
 * (--ds-splitpane-hit, 12px; under .ds-touch half the touch target, 24px),
 * laid over the panes' edges. It resizes the pane named by aria-controls,
 * else the neighbour that does not fill. DS.splitpane writes role,
 * aria-orientation, aria-valuenow, -min and -max (the pane's share of the
 * split pane, in percent) and aria-valuetext while collapsed.
 *
 * Variants:
 *   .ds-splitpane              no frame: the split pane fills its place
 *                              (the content panel, a card's body)
 *   .ds-splitpane--outlined    the hairline frame and the card radius
 *                              (--ds-splitpane-radius, --ds-radius-card,
 *                              times --ds-shape) on --ds-surface: a split
 *                              view inside a page
 *   .ds-splitpane--stacked     the panes one above the other, the divider
 *                              across (it moves with ArrowUp and ArrowDown)
 *
 * Narrow: data-ds-splitpane-stack="<px>" stacks the panes while the split
 * pane is narrower than that (a phone): DS.splitpane measures it and writes
 * data-state="stacked", which lays it out as --stacked (the sizes and the
 * limits then apply to the heights, the divider moves with ArrowUp and
 * ArrowDown).
 *
 * Height: --ds-splitpane-height (100%: it fills a parent of a set height;
 * set a length where the parent grows with its content).
 *
 * Behaviour (DS.splitpane, docs: splitpane.md): drag a divider (pointer,
 * touch, pen); with the focus on it ArrowLeft and ArrowRight (stacked:
 * ArrowUp and ArrowDown) move it by data-ds-splitpane-step px (16; Shift:
 * four times that), Home and End to the pane's smallest and largest size,
 * Enter collapses and restores a pane marked data-ds-splitpane-collapsible
 * (so does a double click; dragging it below half its minimum snaps it
 * shut), Escape during a drag puts it back. data-ds-splitpane-store="<key>" remembers the sizes
 * and what is collapsed (DS.store). A button with
 * data-ds-splitpane-toggle="<pane id>" collapses and restores that pane and
 * carries aria-expanded.
 *
 * State (written by DS.splitpane): the split pane has data-state="stacked"
 * while it is narrower than data-ds-splitpane-stack; a pane collapses to nothing with
 * data-state="collapsed" (inert, its minimum lifted) and comes back through
 * data-state="expanding"; a divider being dragged has data-state="dragging"
 * (the line and the grip turn --ds-primary, the cursor stays on the whole
 * split pane, nothing selects).
 *
 * Options (src/core/options.css, docs/options.md), computed here:
 *   size      .ds-xs ... .ds-xl: the grip's length, 8px per step (32px at md)
 *   density   .ds-density-*: the padding of .ds-splitpane__body, 2px per
 *             step; the panes and the divider stay
 *   shape     .ds-shape-*: the frame of --outlined and the grip's ends
 *   touch     .ds-touch: the hit area at least half the touch target wide,
 *             the grip at least the touch target long
 *   tone      not read: a divider says nothing
 *
 * Motion: collapsing and restoring a pane glides its size
 * (--ds-splitpane-size, registered) over --ds-dur-medium on --ds-ease-out
 * (a size that pushes layout never overshoots), and continues from where it
 * is when it reverses; a drag and the keys move it at once. The line and the
 * grip change colour over --ds-dur-fast. Focus: a ring around the grip, solid
 * from the first frame, snapping from offset + width to the offset.
 *
 * Forced colours: the line and the grip in CanvasText, Highlight while
 * dragged; the ring takes the system colour.
 *
 * Hooks: --ds-splitpane-size, --ds-splitpane-min, --ds-splitpane-max (on a
 * pane), --ds-splitpane-height, --ds-splitpane-line, --ds-splitpane-grip,
 * --ds-splitpane-hit, --ds-splitpane-radius, --ds-splitpane-padding. --_hit,
 * --_grip, --_radius are private.
 *
 * No progressive features.
 */

/* The size and the limits of a pane: lengths that glide (a collapse) and
   stop at the pane (a split pane inside it starts from the defaults). */
@property --ds-splitpane-size {
  syntax: '<length-percentage>';
  inherits: false;
  initial-value: 50%;
}

@property --ds-splitpane-min {
  syntax: '<length-percentage>';
  inherits: false;
  initial-value: 0px;
}

@property --ds-splitpane-max {
  syntax: '<length-percentage>';
  inherits: false;
  initial-value: 100%;
}

@layer ds.components.splitpane {
  .ds-splitpane {
    display: flex;
    min-inline-size: 0;
    min-block-size: 0;
    block-size: var(--ds-splitpane-height, 100%);
    overflow: hidden;
  }

  :is(.ds-splitpane--stacked, .ds-splitpane[data-state="stacked"]) {
    flex-direction: column;
  }

  .ds-splitpane--outlined {
    border: 1px solid var(--ds-line);
    border-radius: calc(var(--ds-splitpane-radius, var(--ds-radius-card)) * var(--ds-shape, 1));
    background: var(--ds-surface);
  }

  .ds-splitpane__pane {
    position: relative;
    flex: 0 1 var(--ds-splitpane-size, 50%);
    min-inline-size: var(--ds-splitpane-min, 0px);
    max-inline-size: var(--ds-splitpane-max, 100%);
    min-block-size: 0;
    overflow: auto;
  }

  :is(.ds-splitpane--stacked, .ds-splitpane[data-state="stacked"]) > .ds-splitpane__pane {
    min-inline-size: 0;
    max-inline-size: none;
    min-block-size: var(--ds-splitpane-min, 0px);
    max-block-size: var(--ds-splitpane-max, 100%);
  }

  /* The pane that takes the rest: marked, or the last one. */
  .ds-splitpane__pane--fill,
  .ds-splitpane:not(:has(> .ds-splitpane__pane--fill)) > .ds-splitpane__pane:last-child {
    flex: 1 1 0;
    max-inline-size: none;
  }

  :is(.ds-splitpane--stacked, .ds-splitpane[data-state="stacked"]) > .ds-splitpane__pane--fill,
  :is(.ds-splitpane--stacked, .ds-splitpane[data-state="stacked"]):not(:has(> .ds-splitpane__pane--fill)) > .ds-splitpane__pane:last-child {
    max-block-size: none;
  }

  /* Collapsed, and on its way back: no minimum, so the size glides from
     nothing (the minimum would jump it there at once). */
  .ds-splitpane__pane:is([data-state="collapsed"], [data-state="expanding"]) {
    min-inline-size: 0;
    min-block-size: 0;
    overflow: hidden;
    transition: --ds-splitpane-size var(--ds-dur-medium) var(--ds-ease-out);
  }

  /* A list that fills a pane runs to its edges: the pane is its frame. */
  .ds-splitpane__pane > .ds-list {
    border: 0;
    border-radius: 0;
  }

  .ds-splitpane__body {
    padding: calc(var(--ds-splitpane-padding, var(--ds-space-4)) + var(--ds-density, 0) * 2px);
  }

  .ds-splitpane__divider {
    /* Half the touch target under .ds-touch: the hit area lies over both
       panes' edges, the grip (below) carries the full target. */
    --_hit: max(var(--ds-splitpane-hit, 12px), calc(var(--ds-target-min, 0px) / 2));
    --_grip: max(calc(32px + var(--ds-size-step, 0) * 8px), var(--ds-target-min, 0px));
    position: relative;
    z-index: var(--ds-z-raised);
    flex: 0 0 1px;
    align-self: stretch;
    background: var(--ds-splitpane-line, var(--ds-line));
    cursor: col-resize;
    touch-action: none;
    -webkit-tap-highlight-color: transparent;
    outline: none;
    transition: background-color var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  :is(.ds-splitpane--stacked, .ds-splitpane[data-state="stacked"]) > .ds-splitpane__divider {
    cursor: row-resize;
  }

  /* The hit area, centred on the line. */
  .ds-splitpane__divider::before {
    content: '';
    position: absolute;
    inset-block: 0;
    inset-inline-start: 50%;
    inline-size: var(--_hit);
    translate: -50% 0;
  }

  :is(.ds-splitpane--stacked, .ds-splitpane[data-state="stacked"]) > .ds-splitpane__divider::before {
    inset-block: auto;
    inset-inline: 0;
    inset-block-start: 50%;
    inline-size: auto;
    block-size: var(--_hit);
    translate: 0 -50%;
  }

  /* The grip: a short pill on the line, where the focus ring sits. */
  .ds-splitpane__divider::after {
    content: '';
    position: absolute;
    inset-block-start: 50%;
    inset-inline-start: 50%;
    inline-size: 4px;
    block-size: min(var(--_grip), 100%);
    translate: -50% -50%;
    border-radius: calc(var(--ds-radius-action) * var(--ds-shape, 1));
    background: var(--ds-splitpane-grip, var(--ds-outline));
    /* The ring rests (invisible) one width further out and snaps in. */
    outline-offset: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    transition:
      background-color var(--ds-dur-fast) var(--ds-ease-in-out),
      outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  :is(.ds-splitpane--stacked, .ds-splitpane[data-state="stacked"]) > .ds-splitpane__divider::after {
    inline-size: min(var(--_grip), 100%);
    block-size: 4px;
  }

  .ds-splitpane__divider:focus-visible::after {
    outline: var(--ds-focus-outline);
    outline-offset: var(--ds-focus-offset);
  }

  @media (hover: hover) {
    .ds-splitpane__divider:hover {
      background: var(--ds-outline);
    }

    .ds-splitpane__divider:hover::after {
      background: var(--ds-text-2);
    }
  }

  .ds-splitpane__divider[data-state="dragging"],
  .ds-splitpane__divider[data-state="dragging"]::after {
    background: var(--ds-primary);
  }

  /* While a divider is dragged: its cursor everywhere on the split pane,
     no text selected, and frames in a pane (a preview) keep no pointer. */
  .ds-splitpane:has(> .ds-splitpane__divider[data-state="dragging"]) {
    cursor: col-resize;
    user-select: none;
  }

  :is(.ds-splitpane--stacked, .ds-splitpane[data-state="stacked"]):has(> .ds-splitpane__divider[data-state="dragging"]) {
    cursor: row-resize;
  }

  .ds-splitpane:has(> .ds-splitpane__divider[data-state="dragging"]) > .ds-splitpane__pane {
    pointer-events: none;
  }

  @media (forced-colors: active) {
    .ds-splitpane__divider,
    .ds-splitpane__divider::after {
      forced-color-adjust: none;
      background: CanvasText;
    }

    .ds-splitpane__divider[data-state="dragging"],
    .ds-splitpane__divider[data-state="dragging"]::after {
      background: Highlight;
    }

    .ds-splitpane__divider:focus-visible::after {
      outline-color: CanvasText;
    }
  }

  @media print {
    .ds-splitpane {
      block-size: auto;
    }

    .ds-splitpane__pane {
      overflow: visible;
    }

    .ds-splitpane__divider::after {
      content: none;
    }
  }
}

/* ── components/upload/upload.css ── */
/*
 * File upload (3.0): a drop zone (.ds-dropzone of Drag and files), the line
 * that says why a file was refused, and the chosen files as rows or as a
 * grid of previews, each with its progress, retry and remove. DS.upload
 * (upload.js) renders the rows; the page uploads and reports progress.
 *
 *   <div class="ds-upload" data-ds-upload data-ds-upload-max-size="10 MB" data-ds-upload-max-files="5">
 *     <label class="ds-dropzone"> ... <input class="ds-dropzone__input" type="file" accept="image/*,.pdf" multiple> ... </label>
 *     <p class="ds-upload__error" hidden>(alertCircle 16)<span class="ds-upload__error-text"></span></p>
 *     <ul class="ds-list ds-upload__list" aria-label="Files"></ul>
 *   </div>
 *
 *   A row (written by DS.upload, list view):
 *   <li class="ds-list__item ds-upload__item" data-ds-key="upload-1" data-status="uploading" aria-busy="true">
 *     <span class="ds-list__media ds-upload__thumb"><img alt=""></span>   (or a .ds-list__icon)
 *     <span class="ds-list__text"><span class="ds-list__title ds-upload__name">devices.csv</span>
 *       <span class="ds-list__meta ds-upload__meta"><span class="ds-upload__status">1.2 MB · 40%</span></span>
 *       <div class="ds-progress ds-progress--flat ds-upload__bar"> ... </div></span>
 *     <span class="ds-list__actions ds-upload__actions">
 *       <button class="ds-btn ds-btn--quiet ds-btn--icon ds-sm ds-upload__retry" aria-label="Retry devices.csv" hidden>
 *       <button class="ds-btn ds-btn--quiet ds-btn--icon ds-sm ds-upload__remove" aria-label="Remove devices.csv"></span></li>
 *
 *   Previews: <ul class="ds-upload__grid" aria-label="Photos"></ul>; a tile is
 *   li.ds-upload__tile with .ds-upload__preview (the picture, or a
 *   .ds-upload__glyph), .ds-upload__caption (.ds-upload__name,
 *   .ds-upload__meta), the bar and .ds-upload__actions over the preview's
 *   top corner (tonal icon buttons, so they read on any picture).
 *
 * data-status (written by DS.upload): queued ("Waiting", no bar yet),
 * uploading (the share, glides), done (the check and "Uploaded"),
 * error (the alert icon and the reason in the error ink; a tile takes the
 * error edge; Retry shows). Status is never colour alone: icon and words.
 *
 * .ds-upload__error: the reason a file was refused, an icon and words in the
 * field's error ink (--ds-field-error-color); the zone's input carries
 * aria-invalid meanwhile (the zone's error edge) and names the line in its
 * aria-describedby. It fades in (ds-fade-in, --ds-dur-fast).
 *
 * Options (src/core/options.css, docs/options.md), on the upload or any
 * ancestor; each is computed here, in the rule that uses it:
 *   size      .ds-xs ... .ds-xl: a tile's least width 16px per step, the
 *             name's type role (--ds-size-font); rows follow the list, the
 *             zone the drop zone
 *   density   .ds-density-*: the gap between tiles and the caption's
 *             padding 2px per step; rows follow the list
 *   shape     .ds-shape-*: multiplies the tile's radius (the preview's
 *             corners follow)
 *   touch     .ds-touch: the buttons take --ds-touch-target (Button)
 *   tone      none: a file's status is data-status, with its icon and word
 *
 * Hooks: --ds-upload-tile (144px: a tile's least width at md),
 * --ds-upload-radius (--ds-radius-card), --ds-upload-gap (--ds-space-3:
 * between the zone, the error line and the files). The private --_tile,
 * --_radius and --_inner are computed here: never set them.
 *
 * Motion: rows and tiles come and go through DS.motion.flip() (they fade
 * in over --ds-dur-fast, the others glide); the bar glides on
 * --ds-ease-value (Progress).
 *
 * Forced colours: a tile and its preview keep their edges (CanvasText), a
 * failed tile a 2px edge; the words carry the status.
 */

@layer ds.components.upload {
  .ds-upload {
    display: grid;
    gap: calc(var(--ds-upload-gap, var(--ds-space-3)) + var(--ds-density, 0) * 2px);
    min-width: 0;
  }

  .ds-upload__error {
    display: flex;
    align-items: flex-start;
    gap: var(--ds-space-1);
    margin: 0;
    color: var(--ds-field-error-color, var(--ds-on-error-container));
    font: var(--ds-font-meta);
    animation: ds-fade-in var(--ds-dur-fast) var(--ds-ease-in-out) backwards;
  }

  .ds-upload__error[hidden] {
    display: none;
  }

  .ds-upload__error > svg {
    flex: none;
    margin-block-start: 1px;
  }

  .ds-upload__error-text {
    min-width: 0;
    overflow-wrap: anywhere;
  }

  /* ── Rows ─────────────────────────────────────── */

  /* A row list (list.css); empty, it takes no room. */
  .ds-upload__list {
    min-width: 0;
  }

  /* In a row the bar sits under the words (upload.js puts it there), so
     the actions stay on the first line down to a phone's width. */
  .ds-upload__item > .ds-list__text {
    flex-basis: 8rem;
  }

  .ds-upload__item .ds-upload__bar {
    margin-block-start: var(--ds-space-1);
  }

  .ds-upload__bar[hidden] {
    display: none;
  }

  /* A picture, never squeezed by a long name. */
  .ds-upload__thumb {
    flex: none;
  }

  .ds-upload__name {
    min-width: 0;
    overflow-wrap: anywhere;
  }

  .ds-upload__meta {
    display: flex;
    align-items: flex-start;
    gap: var(--ds-space-1);
    min-width: 0;
  }

  .ds-upload__status {
    min-width: 0;
  }

  /* On the first line of the words, which may wrap. */
  .ds-upload__status-icon {
    flex: none;
    margin-block: calc((1lh - 16px) / 2);
  }

  .ds-upload__actions {
    display: flex;
    flex: none;
    align-items: center;
    gap: var(--ds-space-1);
    margin-inline-start: auto;
  }

  .ds-upload__retry[hidden] {
    display: none;
  }

  .ds-upload__remove {
    flex: none;
  }

  /* A row that DS.motion.flip() brings in fades in quickly, as a list row. */
  .ds-upload__item {
    --ds-enter-duration: var(--ds-dur-fast);
  }

  /* ── Previews ─────────────────────────────────── */

  .ds-upload__grid {
    --_tile: max(96px, calc(var(--ds-upload-tile, 144px) + var(--ds-size-step, 0) * 16px));
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(min(100%, var(--_tile)), 1fr));
    gap: calc(var(--ds-space-3) + var(--ds-density, 0) * 2px);
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .ds-upload__grid:empty {
    display: none;
  }

  .ds-upload__tile {
    --ds-enter-duration: var(--ds-dur-fast);
    --_radius: calc(var(--ds-upload-radius, var(--ds-radius-card)) * var(--ds-shape, 1));
    --_inner: max(0px, calc(var(--_radius) - 1px));
    position: relative;
    display: grid;
    grid-template-rows: auto auto;
    align-content: start;
    gap: var(--ds-space-2);
    box-sizing: border-box;
    min-width: 0;
    padding-block-end: calc(var(--ds-space-3) + var(--ds-density, 0) * 2px);
    border: 1px solid var(--ds-line);
    border-radius: var(--_radius);
    background: var(--ds-surface);
    color: var(--ds-text);
    transition: border-color var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  .ds-upload__tile[data-status="error"] {
    border-color: var(--ds-error);
  }

  .ds-upload__preview {
    display: grid;
    place-items: center;
    aspect-ratio: 4 / 3;
    overflow: hidden;
    border-block-end: 1px solid var(--ds-line);
    border-start-start-radius: var(--_inner);
    border-start-end-radius: var(--_inner);
    background: var(--ds-surface-high);
    color: var(--ds-text-2);
  }

  .ds-upload__preview > img {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: cover;
  }

  .ds-upload__glyph {
    flex: none;
  }

  .ds-upload__caption {
    display: grid;
    gap: 2px;
    min-width: 0;
    padding-inline: calc(var(--ds-space-3) + var(--ds-density, 0) * 2px);
  }

  .ds-upload__caption > .ds-upload__name {
    overflow: hidden;
    color: var(--ds-text);
    font: var(--ds-size-font, var(--ds-font-label));
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .ds-upload__caption > .ds-upload__meta {
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
    font-variant-numeric: tabular-nums;
  }

  .ds-upload__tile > .ds-upload__bar {
    margin-inline: calc(var(--ds-space-3) + var(--ds-density, 0) * 2px);
  }

  /* Over the preview's top corner: tonal buttons read on any picture. */
  .ds-upload__tile > .ds-upload__actions {
    position: absolute;
    inset-block-start: var(--ds-space-2);
    inset-inline-end: var(--ds-space-2);
  }

  /* The status after the parts' own colours: the check, and the reason in
     the error ink. */
  [data-status="done"] > * > .ds-upload__meta > .ds-upload__status-icon {
    color: var(--ds-success);
  }

  [data-status="error"] > * > .ds-upload__meta {
    color: var(--ds-field-error-color, var(--ds-on-error-container));
  }

  @media (forced-colors: active) {
    .ds-upload__tile,
    .ds-upload__preview {
      border-color: CanvasText;
    }

    .ds-upload__tile[data-status="error"] {
      outline: 1px solid CanvasText;
      outline-offset: -2px;
    }

    .ds-upload__error,
    [data-status="error"] > * > .ds-upload__meta,
    [data-status="done"] > * > .ds-upload__meta > .ds-upload__status-icon {
      color: CanvasText;
    }
  }
}

/* ── components/datefield/datefield.css ── */
/*
 * Date field: a date, a time, a date and a time, or a range of dates,
 * typed part by part. It draws the box of a text field (the input's hooks,
 * so a theme that styles fields styles it too); DS.datefield
 * (datefield.js) renders one spinbutton per part in the locale's order,
 * with its separators, and keeps them in step.
 *
 *   <span class="ds-field__label" id="due-label">Due date</span>
 *   <div class="ds-datefield" role="group" aria-labelledby="due-label" data-ds-datefield data-ds-value="2026-11-04"
 *        [data-ds-datefield-type="date | time | datetime | range"] [data-ds-datefield-zone="local"]>
 *     [<span class="ds-datefield__leading" aria-hidden="true">(calendar)</span>]
 *     (rendered:)
 *     <span class="ds-datefield__input">
 *       <span class="ds-datefield__segment" role="spinbutton" contenteditable="true" aria-label="month"
 *             aria-valuenow="11" aria-valuetext="11 – November" [data-placeholder]>11</span>
 *       <span class="ds-datefield__literal" aria-hidden="true">/</span> ...
 *       (a range: two <span class="ds-datefield__group" role="group" aria-label="Start">,
 *        a .ds-datefield__literal.ds-datefield__between between them)
 *     </span>
 *     [<span class="ds-datefield__zone">GMT+1</span>]   (a datetime with data-ds-datefield-zone)
 *     [<button class="ds-btn ds-btn--quiet ds-btn--icon ds-datefield__toggle" type="button" aria-label="Choose date">(calendar)</button>]
 *   </div>
 *
 * Variants: the outlined box (default, .ds-datefield--outlined) and
 * .ds-datefield--filled on the tonal fill (also inside a .ds-field--filled).
 *
 * States: an empty part shows its placeholder (the first letter of its
 * name, "mm", in the quieter ink: data-placeholder); the focused part is
 * filled in the action colour, and the box takes the field's focus ring at
 * once; aria-invalid="true" (out of min and max, a day that does not exist,
 * a range that ends before it starts; the script sets it) draws the error
 * border, and the page shows a message under the field, so the colour is
 * never alone; aria-disabled="true" on the group: the disabled look, no
 * part takes focus; aria-readonly="true": the read-only look, focusable,
 * nothing changes.
 *
 * Options (src/core/options.css, docs/options.md), on the field or any
 * ancestor; each is computed here:
 *   size      .ds-xs ... .ds-xl: 8px of height per step from
 *             --ds-input-height (40px), 4px of side padding per step, the
 *             type of the size (--ds-size-font)
 *   density   .ds-density-*: 4px of height per step; type and side
 *             padding stay
 *   shape     .ds-shape-*: multiplies the box's radius and a part's
 *   touch     .ds-touch: at least --ds-touch-target high
 *   tone      none: the invalid look is the field's (aria-invalid)
 * On a phone (600px or less) the type is --ds-font-input (16px), so iOS
 * does not zoom into the field.
 *
 * Motion: border, fill and ink change over --ds-dur-fast; the focus ring
 * and the focused part appear at once.
 *
 * Forced colours: the box keeps its border (CanvasText, Highlight when
 * focused), the focused part is Highlight / HighlightText, a placeholder
 * GrayText, a disabled field GrayText.
 */

@layer ds.components.datefield {
  .ds-datefield {
    /* The options, as on a text field (form.css): the hooks are the input's. */
    --_h: calc(var(--ds-input-height, 40px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px);
    --_box: max(var(--ds-target-min, 0px), var(--_h));
    --_radius: min(calc(var(--ds-input-radius, var(--ds-radius-field)) * var(--ds-shape, 1)), calc(var(--_box) / 2));
    --_px: calc(var(--ds-input-padding-x, var(--ds-space-3)) + var(--ds-size-step, 0) * 4px);
    display: inline-flex;
    align-items: center;
    gap: var(--ds-space-2);
    box-sizing: border-box;
    min-inline-size: 0;
    max-inline-size: 100%;
    min-block-size: var(--_box);
    padding-inline: var(--_px);
    border: 1px solid var(--ds-input-border, var(--ds-outline));
    border-radius: var(--_radius);
    background: var(--ds-input-bg, var(--ds-surface));
    color: var(--ds-text);
    font: var(--ds-input-font, var(--ds-size-font, var(--ds-font-body)));
    font-weight: var(--ds-input-weight, var(--ds-weight-regular));
    cursor: text;
    transition:
      border-color var(--ds-dur-fast) var(--ds-ease-in-out),
      background-color var(--ds-dur-fast) var(--ds-ease-in-out),
      box-shadow var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  /* The default look, named explicitly. */
  .ds-datefield--outlined {
    border-color: var(--ds-input-border, var(--ds-outline));
    background-color: var(--ds-input-bg, var(--ds-surface));
  }

  /* On the tonal fill, no outline at rest (a state keeps its border). */
  .ds-datefield--filled,
  :where(.ds-field--filled) .ds-datefield:where(:not(.ds-datefield--outlined)) {
    border-color: transparent;
    background-color: var(--ds-surface-high);
  }

  /* A field that fills its row (in a form grid, a filter bar). */
  .ds-datefield--block {
    display: flex;
    inline-size: 100%;
  }

  /* With a button at its end, the button sits closer to the edge. */
  .ds-datefield:has(> .ds-datefield__toggle:last-child) {
    padding-inline-end: var(--ds-space-1);
  }

  @media (max-width: 600px) {
    .ds-datefield {
      font: var(--ds-input-font, var(--ds-font-input));
      font-weight: var(--ds-input-weight, var(--ds-weight-regular));
    }
  }

  @media (hover: hover) {
    .ds-datefield:hover:not(:focus-within, [aria-disabled="true"], [aria-readonly="true"], [aria-invalid="true"]) {
      border-color: var(--ds-text);
    }
  }

  /* Focus on a part: the field's ring, at once (the toggle button shows
     its own ring instead). */
  .ds-datefield:has(.ds-datefield__segment:focus) {
    border-color: var(--ds-input-focus-color, var(--ds-primary));
    box-shadow: inset 0 0 0 1px var(--ds-input-focus-color, var(--ds-primary));
    transition-duration: 0s;
  }

  .ds-datefield[aria-invalid="true"] {
    border-color: var(--ds-error);
  }

  .ds-datefield[aria-invalid="true"]:has(.ds-datefield__segment:focus) {
    border-color: var(--ds-error);
    box-shadow: inset 0 0 0 1px var(--ds-error);
  }

  .ds-datefield:is([aria-disabled="true"], [aria-readonly="true"]) {
    background: var(--ds-surface-low);
    color: var(--ds-text-2);
  }

  .ds-datefield[aria-disabled="true"],
  .ds-datefield[aria-readonly="true"]:where(:not(:focus-within)) {
    border-color: var(--ds-line);
  }

  .ds-datefield[aria-disabled="true"] {
    cursor: not-allowed;
  }

  .ds-datefield__leading {
    display: inline-flex;
    flex: none;
    color: var(--ds-text-2);
    pointer-events: none;
  }

  /* The parts: one line, numbers of one width, never wrapping. */
  .ds-datefield__input {
    display: inline-flex;
    flex: 1 1 auto;
    align-items: center;
    min-inline-size: 0;
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
  }

  .ds-datefield--block > .ds-datefield__input {
    flex: 1 1 auto;
  }

  .ds-datefield__group {
    display: inline-flex;
    align-items: center;
  }

  .ds-datefield__segment {
    box-sizing: content-box;
    min-inline-size: 1ch;
    padding-inline: 2px;
    border-radius: calc(var(--ds-radius-xs) * var(--ds-shape, 1));
    color: inherit;
    text-align: end;
    caret-color: transparent;
    outline: none;
    transition:
      background-color var(--ds-dur-fast) var(--ds-ease-in-out),
      color var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  .ds-datefield__segment::selection {
    background: transparent;
  }

  .ds-datefield__segment[data-placeholder] {
    color: var(--ds-text-3);
  }

  /* On the tonal fill text-3 falls short of 4.5:1; text-2 keeps it. */
  .ds-datefield--filled .ds-datefield__segment[data-placeholder],
  :where(.ds-field--filled) .ds-datefield .ds-datefield__segment[data-placeholder] {
    color: var(--ds-text-2);
  }

  /* The focused part: filled in the action colour, at once. */
  .ds-datefield__segment:focus {
    background: var(--ds-primary);
    color: var(--ds-on-primary);
    transition-duration: 0s;
  }

  .ds-datefield__literal {
    color: var(--ds-text-2);
    white-space: pre;
  }

  .ds-datefield__between {
    padding-inline: var(--ds-space-1);
  }

  /* The zone of a wall time: its offset, the long name as the description
     (and its tooltip). */
  .ds-datefield__zone {
    flex: none;
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
    white-space: nowrap;
  }

  /* The field's border does not add to the button's height. */
  .ds-datefield__toggle {
    flex: none;
    margin-block: -1px;
  }

  @media (forced-colors: active) {
    .ds-datefield:has(.ds-datefield__segment:focus) {
      border-color: Highlight;
    }

    .ds-datefield__segment:focus {
      forced-color-adjust: none;
      background: Highlight;
      color: HighlightText;
    }

    .ds-datefield__segment[data-placeholder]:not(:focus),
    .ds-datefield[aria-disabled="true"] {
      color: GrayText;
    }
  }
}

/* ── components/kveditor/kveditor.css ── */
/*
 * Key-value editor (3.0): rows of a key and a value (environment variables,
 * labels, headers), added and removed, filled by pasting KEY=value lines,
 * with a warning on a key that comes twice and secret values that hide
 * until revealed. DS.kveditor (kveditor.js) renders the rows.
 *
 *   <fieldset class="ds-kveditor ds-kveditor--code" data-ds-kveditor data-ds-kveditor-name="env">
 *     <legend class="ds-fieldset__legend">Environment variables</legend>
 *     <div class="ds-kveditor__head" aria-hidden="true"><span>Key</span><span>Value</span></div>
 *     <ul class="ds-kveditor__rows">
 *       <li class="ds-kveditor__row" data-ds-key="kv-1" [data-secret] [data-status="warning"]>
 *         <input class="ds-input ds-kveditor__key" aria-label="Key, row 1">
 *         <div class="ds-kveditor__value [ds-input-group]">
 *           <input class="ds-input ds-kveditor__input" aria-label="Value of API_URL">
 *           [<button class="ds-btn ds-btn--quiet ds-btn--icon ds-sm ds-kveditor__reveal" aria-pressed="false">(eye)</button>]
 *         </div>
 *         <button class="ds-btn ds-btn--quiet ds-btn--icon ds-kveditor__remove" aria-label="Remove API_URL">(close)</button>
 *         <p class="ds-kveditor__hint" hidden>(alert 16)<span>…</span></p>
 *       </li>
 *     </ul>
 *     <div class="ds-kveditor__foot"><button class="ds-btn ds-btn--text ds-kveditor__add">(plus) Add variable</button></div>
 *   </fieldset>
 *
 * A row is a grid: the key, the value (the wider), Remove; its hint spans
 * under them. Under 480px of the editor (a container query) the key and
 * Remove share the first line and the value takes the second, and a
 * hairline parts the rows. A secret value (data-secret) is the field's
 * input group with a reveal button (aria-pressed; the password field of
 * Form). A warning (data-status="warning": a key that comes twice, a value
 * without a key) gives the key the warning edge and says it in the hint,
 * with its icon, named by the key's aria-describedby.
 *
 * --code: keys and values in the monospace family (--ds-font-mono) at the
 * field's size, for names such as API_TOKEN.
 *
 * Options (src/core/options.css, docs/options.md), on the editor or any
 * ancestor; each is computed here, in the rule that uses it:
 *   size      .ds-xs ... .ds-xl: the fields and buttons step themselves
 *             (Form, Button)
 *   density   .ds-density-*: the room between the rows and inside a row
 *             2px per step; the fields 4px per step (Form)
 *   shape     .ds-shape-*: the fields and buttons follow (Form, Button)
 *   touch     .ds-touch: fields and buttons take --ds-touch-target
 *   tone      none: a warning is data-status, with its icon and words
 *
 * Hooks: --ds-kveditor-key-width (2fr: the key's share of a row beside the
 * value's 3fr), --ds-kveditor-gap (--ds-space-2: the room between the rows
 * and inside a row). The hint reads --ds-field-warning-color (Form). The private --_gap is
 * computed here: never set it.
 *
 * Motion: rows come and go through DS.motion.flip() (a new row fades in
 * over --ds-dur-fast, the others glide); the hint fades in (ds-fade-in).
 *
 * Forced colours: a warning key keeps a 2px CanvasText edge, the hint its
 * icon and words; fields and buttons are Form's and Button's.
 */

@layer ds.components.kveditor {
  .ds-kveditor {
    --_gap: max(var(--ds-space-1), calc(var(--ds-kveditor-gap, var(--ds-space-2)) + var(--ds-density, 0) * 2px));
    container: ds-kveditor / inline-size;
    display: grid;
    gap: var(--_gap);
    min-inline-size: 0;
    margin: 0;
    padding: 0;
    border: 0;
  }

  /* The column labels line up with the fields; on one column they go. */
  .ds-kveditor__head {
    display: grid;
    grid-template-columns: minmax(0, var(--ds-kveditor-key-width, 2fr)) minmax(0, 3fr) max(var(--ds-target-min, 0px), 40px);
    gap: var(--_gap);
    color: var(--ds-text-2);
    font: var(--ds-font-label);
  }

  .ds-kveditor__rows {
    display: grid;
    gap: var(--_gap);
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .ds-kveditor__rows:empty {
    display: none;
  }

  .ds-kveditor__row {
    --ds-enter-duration: var(--ds-dur-fast);
    display: grid;
    grid-template-columns: minmax(0, var(--ds-kveditor-key-width, 2fr)) minmax(0, 3fr) auto;
    align-items: start;
    gap: var(--ds-space-1) var(--_gap);
  }

  .ds-kveditor__key,
  .ds-kveditor__value {
    min-width: 0;
  }

  .ds-kveditor__value > .ds-kveditor__input {
    width: 100%;
  }

  .ds-kveditor__reveal,
  .ds-kveditor__remove {
    flex: none;
  }

  .ds-kveditor__hint {
    display: flex;
    grid-column: 1 / -1;
    align-items: flex-start;
    gap: var(--ds-space-1);
    margin: 0;
    color: var(--ds-field-warning-color, var(--ds-on-warning-container));
    font: var(--ds-font-meta);
    animation: ds-fade-in var(--ds-dur-fast) var(--ds-ease-in-out) backwards;
  }

  .ds-kveditor__hint[hidden] {
    display: none;
  }

  .ds-kveditor__hint > svg {
    flex: none;
    margin-block: calc((1lh - 16px) / 2);
  }

  .ds-kveditor__row[data-status="warning"] > .ds-kveditor__key {
    border-color: var(--ds-warning);
  }

  .ds-kveditor__foot {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--ds-space-2);
  }

  .ds-kveditor__add {
    justify-self: start;
  }

  .ds-kveditor--code :is(.ds-kveditor__key, .ds-kveditor__input) {
    font-family: var(--ds-font-mono);
  }

  /* One column: the key and Remove on the first line, the value under. */
  @container ds-kveditor (max-width: 480px) {
    .ds-kveditor__head {
      display: none;
    }

    .ds-kveditor__rows {
      gap: 0;
    }

    .ds-kveditor__row {
      grid-template-columns: minmax(0, 1fr) auto;
      padding-block: var(--_gap);
      border-block-start: 1px solid var(--ds-line);
    }

    .ds-kveditor__row:first-child {
      border-block-start: 0;
      padding-block-start: 0;
    }

    .ds-kveditor__row > .ds-kveditor__value {
      grid-column: 1;
      grid-row: 2;
    }

    .ds-kveditor__row > .ds-kveditor__remove {
      grid-column: 2;
      grid-row: 1;
    }
  }

  @media (forced-colors: active) {
    .ds-kveditor__row[data-status="warning"] > .ds-kveditor__key {
      outline: 1px solid CanvasText;
      outline-offset: -2px;
    }

    .ds-kveditor__hint {
      color: CanvasText;
    }
  }
}

/* ── components/listdetail/listdetail.css ── */
/*
 * List-detail layout: a list, the detail of what is picked in it and,
 * optionally, a sub-detail (a related record, a log line, a reply), as
 * columns that fold to fewer as the layout narrows, down to one with a back
 * button on a phone (js: DS.listdetail). Each column scrolls on its own.
 *
 *   <div class="ds-listdetail" data-ds-listdetail role="group" aria-label="Devices">
 *     <section class="ds-listdetail__list" aria-labelledby="ld-list-title">
 *       <header class="ds-listdetail__head"><h2 class="ds-listdetail__title" id="ld-list-title">Devices</h2></header>
 *       <ul class="ds-list ds-list--interactive"> ... <a class="ds-list__action" href="#d42" data-ds-listdetail-show="detail">LAPTOP-0042</a> ... </ul>
 *     </section>
 *     <section class="ds-listdetail__detail" aria-labelledby="ld-detail-title">
 *       <header class="ds-listdetail__head">
 *         <button class="ds-btn ds-btn--icon ds-btn--quiet ds-listdetail__back" type="button" aria-label="Back to devices">(arrowLeft 20)</button>
 *         <h2 class="ds-listdetail__title" id="ld-detail-title">LAPTOP-0042</h2>
 *       </header>
 *       <div class="ds-listdetail__body"> ... </div>
 *     </section>
 *     <section class="ds-listdetail__sub" aria-labelledby="ld-sub-title">
 *       <header class="ds-listdetail__head">
 *         <button class="ds-btn ds-btn--icon ds-btn--quiet ds-listdetail__back" type="button" aria-label="Back to LAPTOP-0042">(arrowLeft 20)</button>
 *         <h2 class="ds-listdetail__title" id="ld-sub-title">Ticket #42</h2>
 *         <button class="ds-btn ds-btn--icon ds-btn--quiet ds-listdetail__close" type="button" aria-label="Close the ticket">(close 20)</button>
 *       </header> ...
 *     </section>
 *   </div>
 *
 * Columns:
 *   .ds-listdetail__list     the list, --ds-listdetail-list-width (320px)
 *   .ds-listdetail__detail   the detail: takes the rest, at least
 *                            --ds-listdetail-detail-min (400px) beside
 *                            another column
 *   .ds-listdetail__sub      optional: the sub-detail,
 *                            --ds-listdetail-sub-width (360px), shown only
 *                            at the sub level
 * Parts:
 *   .ds-listdetail__head     a column's header row, sticky at its top: a back
 *                            button, the title, actions at the end
 *   .ds-listdetail__title    the column's title, one line with an ellipsis
 *   .ds-listdetail__body     padded content of a column
 *   .ds-listdetail__back     up one level: shown only while the column
 *                            before it is hidden (a phone; the detail while
 *                            the sub-detail pushes the list out)
 *   .ds-listdetail__close    up one level as well: shown only while the
 *                            column before it shows (the sub-detail beside
 *                            its detail)
 *   A .ds-list right in a column loses its frame and runs to its edges.
 *
 * What shows follows the level (data-state: "list" until something is
 * picked, "detail", "sub") and the layout's own width, which DS.listdetail
 * measures (so it folds inside a sheet or a narrow card as on a phone; no
 * size container, which would re-anchor the popups inside it). It writes
 * data-columns (how many fit) and data-shown (the levels that show):
 *   one column       narrower than the list and the detail's minimum
 *                    (--ds-listdetail-list-width + --ds-listdetail-detail-min,
 *                    720px): the level's own, with its back button
 *   two columns      the list and the detail; at the sub level the detail
 *                    and the sub-detail (the detail's back button brings the
 *                    list back)
 *   three columns    from that plus --ds-listdetail-sub-width (1080px): the
 *                    sub-detail beside both
 * Before the script runs, a window under 720px shows the list alone, or the
 * level data-ds-listdetail names.
 *
 * Variants:
 *   .ds-listdetail             no frame: it fills its place (the content
 *                              panel), hairlines between the columns
 *   .ds-listdetail--outlined   the hairline frame and the card radius
 *                              (--ds-listdetail-radius, --ds-radius-card,
 *                              times --ds-shape) on --ds-surface
 *
 * Height: --ds-listdetail-height (100%: it fills a parent of a set height).
 *
 * Options (src/core/options.css, docs/options.md), computed here:
 *   density   .ds-density-*: the padding of the head and the body, 2px per
 *             step, and the head's height, 4px per step (56px at the
 *             comfortable density)
 *   shape     .ds-shape-*: the frame of --outlined
 *   size      not read: it is a layout; a size class reaches the controls
 *             in it
 *   touch     .ds-touch: the head at least the touch target high (its back
 *             button is a target)
 *   tone      not read
 *
 * Motion: a column that comes into view by a change of level slides in
 * from the end and fades (DS.motion.enter, 'slide': ds-shift-in with
 * ds-fade-in over --ds-dur-slow, the movement on --ds-ease-spatial); going
 * back (data-direction="back") it comes from the start. The column that
 * goes is gone at once. Nothing plays when the layout folds by a resize.
 *
 * Forced colours: the hairlines and the frame are borders, so they stay.
 *
 * Hooks: --ds-listdetail-height, --ds-listdetail-list-width,
 * --ds-listdetail-detail-min, --ds-listdetail-sub-width, --ds-listdetail-line, --ds-listdetail-radius,
 * --ds-listdetail-head-height, --ds-listdetail-padding. --_head and --_pad
 * are private.
 *
 * No progressive features.
 */

@layer ds.components.listdetail {
  .ds-listdetail {
    display: flex;
    min-inline-size: 0;
    min-block-size: 0;
    block-size: var(--ds-listdetail-height, 100%);
    overflow: hidden;
    background: var(--ds-surface);
  }

  .ds-listdetail--outlined {
    border: 1px solid var(--ds-line);
    border-radius: calc(var(--ds-listdetail-radius, var(--ds-radius-card)) * var(--ds-shape, 1));
  }

  .ds-listdetail__list,
  .ds-listdetail__detail,
  .ds-listdetail__sub {
    position: relative;
    display: flex;
    flex-direction: column;
    min-inline-size: 0;
    min-block-size: 0;
    overflow: auto;
  }

  .ds-listdetail__list {
    flex: 0 0 var(--ds-listdetail-list-width, 320px);
  }

  .ds-listdetail__detail {
    flex: 1 1 0;
    min-inline-size: min(100%, var(--ds-listdetail-detail-min, 400px));
  }

  .ds-listdetail__sub {
    flex: 0 0 var(--ds-listdetail-sub-width, 360px);
  }

  .ds-listdetail__detail,
  .ds-listdetail__sub {
    border-inline-start: 1px solid var(--ds-listdetail-line, var(--ds-line));
  }

  /* Back from a level comes from the start; the default (deeper) from the end. */
  .ds-listdetail[data-direction="back"] > :is(.ds-listdetail__list, .ds-listdetail__detail, .ds-listdetail__sub) {
    --ds-motion-distance: calc(-1 * var(--ds-distance-xl));
  }

  .ds-listdetail__head {
    --_head: max(var(--ds-target-min, 0px), calc(var(--ds-listdetail-head-height, 56px) + var(--ds-density, 0) * 4px));
    position: sticky;
    inset-block-start: 0;
    z-index: var(--ds-z-raised);
    display: flex;
    flex: none;
    align-items: center;
    gap: var(--ds-space-2);
    min-block-size: var(--_head);
    padding-block: 0;
    padding-inline: calc(var(--ds-listdetail-padding, var(--ds-space-4)) + var(--ds-density, 0) * 2px);
    border-block-end: 1px solid var(--ds-listdetail-line, var(--ds-line));
    background: var(--ds-surface);
  }

  .ds-listdetail__title {
    flex: 1 1 auto;
    min-inline-size: 0;
    margin: 0;
    overflow: hidden;
    color: var(--ds-text);
    font: var(--ds-font-subtitle);
    white-space: nowrap;
    text-overflow: ellipsis;
  }

  /* An icon button at the start sits on the padding's edge, its icon in
     line with the text below it. */
  .ds-listdetail__back {
    flex: none;
    margin-inline-start: calc(-1 * var(--ds-space-2));
  }

  .ds-listdetail__close {
    flex: none;
    margin-inline-end: calc(-1 * var(--ds-space-2));
  }

  .ds-listdetail__body {
    --_pad: calc(var(--ds-listdetail-padding, var(--ds-space-4)) + var(--ds-density, 0) * 2px);
    padding: var(--_pad);
  }

  /* A list that fills a column runs to its edges: the column is its frame. */
  .ds-listdetail > * > .ds-list {
    border: 0;
    border-radius: 0;
  }

  /* What shows (data-shown, written by DS.listdetail from the layout's own
     width and the level): the columns it names; a back button where the
     column before it is out, a close button where it shows. */
  .ds-listdetail__back {
    display: none;
  }

  .ds-listdetail[data-shown]:not([data-shown~="list"]) > .ds-listdetail__list,
  .ds-listdetail[data-shown]:not([data-shown~="detail"]) > .ds-listdetail__detail,
  .ds-listdetail[data-shown]:not([data-shown~="sub"]) > .ds-listdetail__sub {
    display: none;
  }

  .ds-listdetail[data-shown]:not([data-shown~="list"]) > .ds-listdetail__detail .ds-listdetail__back,
  .ds-listdetail[data-shown]:not([data-shown~="detail"]) > .ds-listdetail__sub .ds-listdetail__back {
    display: revert-layer;
  }

  .ds-listdetail[data-shown]:not([data-shown~="list"]) > .ds-listdetail__detail .ds-listdetail__close,
  .ds-listdetail[data-shown]:not([data-shown~="detail"]) > .ds-listdetail__sub .ds-listdetail__close {
    display: none;
  }

  /* Nothing picked: the detail has nothing to close. */
  .ds-listdetail:not([data-state="detail"], [data-state="sub"]) > .ds-listdetail__detail .ds-listdetail__close {
    display: none;
  }

  /* The first column that shows has no hairline before it. */
  .ds-listdetail[data-shown]:not([data-shown~="list"]) > .ds-listdetail__detail,
  .ds-listdetail[data-shown]:not([data-shown~="list"], [data-shown~="detail"]) > .ds-listdetail__sub {
    border-inline-start: 0;
  }

  /* One column: the level's own takes the whole width. */
  .ds-listdetail[data-columns="1"] > :is(.ds-listdetail__list, .ds-listdetail__detail, .ds-listdetail__sub) {
    flex: 1 1 0;
  }

  /* Before the script (and without it): the sub-detail waits, a narrow
     window shows the list alone (or the level data-ds-listdetail names). */
  .ds-listdetail:not([data-shown], [data-ds-listdetail="sub"]) > .ds-listdetail__sub {
    display: none;
  }

  @media (max-width: 719.98px) {
    .ds-listdetail:not([data-shown]) > :is(.ds-listdetail__list, .ds-listdetail__detail, .ds-listdetail__sub) {
      flex: 1 1 0;
      border-inline-start: 0;
    }

    .ds-listdetail:not([data-shown]):is([data-ds-listdetail="detail"], [data-ds-listdetail="sub"]) > .ds-listdetail__list,
    .ds-listdetail:not([data-shown], [data-ds-listdetail="detail"]) > .ds-listdetail__detail {
      display: none;
    }
  }

  @media print {
    .ds-listdetail {
      block-size: auto;
    }

    .ds-listdetail__list,
    .ds-listdetail__detail,
    .ds-listdetail__sub {
      overflow: visible;
    }

    .ds-listdetail__head {
      position: static;
    }
  }
}

/* ── components/sort/sort.css ── */
/*
 * Sort control: the field and the direction of a list or a set of cards,
 * outside a table (a table sorts in its header, .ds-table__sort). Two
 * looks, one behaviour (js/sort.js, data-ds-sort):
 *
 * Inline: a label, a select of the fields and an order button whose words
 * say the direction in the field's terms ("A to Z", "Newest first"):
 *
 *   <div class="ds-sort" data-ds-sort role="group" aria-label="Sort devices">
 *     <label class="ds-sort__label" for="sort-field">Sort by</label>
 *     <select class="ds-input ds-sort__field" id="sort-field">
 *       <option value="name" data-ds-sort-type="text">Name</option>
 *       <option value="seen" data-ds-sort-type="date" data-ds-sort-default="descending">Last seen</option>
 *     </select>
 *     <button class="ds-btn ds-btn--quiet ds-sort__order" type="button">
 *       (arrowUp 20 .ds-sort__arrow)<span class="ds-sr">Order: </span>
 *       <span class="ds-sort__words"><span class="ds-sort__word">A to Z</span><span class="ds-sort__word">Z to A</span></span>
 *     </button>
 *   </div>
 *
 * Menu (.ds-sort--menu): one button that names the field and points the
 * direction, and a menu of the fields and the two directions:
 *
 *   <div class="ds-sort ds-sort--menu" data-ds-sort>
 *     <button class="ds-btn ds-sort__trigger" type="button" aria-haspopup="menu" aria-expanded="false" data-ds-open="#sort-menu">
 *       (sort 20)<span class="ds-sr">Sort by </span><span class="ds-sort__value">Name</span>
 *       <span class="ds-sr">, </span><span class="ds-sort__words ds-sr">(the two words)</span>(arrowUp 20 .ds-sort__arrow)</button>
 *     <div class="ds-menu" id="sort-menu" role="menu" aria-label="Sort" hidden>
 *       <div role="group" aria-labelledby="sort-by"><p class="ds-menu__heading" id="sort-by">Sort by</p>
 *         <button class="ds-menu__item" role="menuitemradio" aria-checked="true" type="button" data-ds-sort-field="name">(check 20 .ds-menu__check)<span class="ds-menu__label">Name</span></button> ...</div>
 *       <div class="ds-menu__divider" role="separator"></div>
 *       <div role="group" aria-labelledby="sort-order"><p class="ds-menu__heading" id="sort-order">Order</p>
 *         <button class="ds-menu__item" role="menuitemradio" type="button" data-ds-sort-direction="ascending">(check)<span class="ds-menu__label">A to Z</span></button> ...</div>
 *     </div>
 *   </div>
 *
 * State, written by the system: data-state="ascending" or "descending" on
 * .ds-sort. The arrow (.ds-sort__arrow, one up arrow for both directions)
 * turns 180deg for descending on the spring (--ds-dur-medium), as the
 * table's sort arrow does; the two words of the order button stack in one
 * grid cell, so the button keeps its width when they change, and only
 * the current one shows. The direction is never told by the arrow alone:
 * the words say it.
 *
 * Options (src/core/options.css, docs/options.md), on .ds-sort or any
 * ancestor: size, density, shape and touch reach its select and buttons,
 * which compute them in their own rules; the gap between them steps with
 * size (4px per step). The label keeps its role. There is no tone: a sort
 * shows no meaning of its own.
 *
 * Narrow: the inline control wraps at its gap; in a content area of at
 * most 480px its label goes (it stays the select's name).
 *
 * Forced colours: the arrow and the words are text, so they keep the
 * system's colours; nothing of its own.
 *
 * Hooks: --ds-sort-field-width (the select's least width, 160px). The
 * computed --_gap is private: never set it.
 *
 * No progressive feature.
 */

@layer ds.components.sort {
  .ds-sort {
    --_gap: max(var(--ds-space-1), calc(var(--ds-space-2) + var(--ds-size-step, 0) * 4px));
    display: inline-flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--_gap);
    min-width: 0;
    max-width: 100%;
  }

  /* The menu look is one button: it never wraps. */
  .ds-sort--menu {
    flex-wrap: nowrap;
  }

  .ds-sort__label {
    color: var(--ds-text-2);
    font: var(--ds-font-label);
    white-space: nowrap;
  }

  /* A select as wide as its longest field, at least the hook; never wider
     than the row. The least width is a length, not min(100%, …): a
     percentage counts as nothing in the control's max-content width, so a
     flex row would size it too narrow and wrap the order button. */
  .ds-sort__field {
    inline-size: auto;
    min-inline-size: var(--ds-sort-field-width, 160px);
    max-inline-size: 100%;
  }

  .ds-sort__order,
  .ds-sort__trigger {
    white-space: nowrap;
  }

  /* One up arrow for both directions: descending turns it to point down. */
  .ds-sort__arrow {
    flex: none;
    transition: rotate var(--ds-dur-medium) var(--ds-ease-spatial);
  }

  .ds-sort[data-state="descending"] .ds-sort__arrow {
    rotate: 180deg;
  }

  /* Both words in one cell: the button is as wide as the longer one. */
  .ds-sort__words {
    display: inline-grid;
  }

  .ds-sort__word {
    grid-area: 1 / 1;
  }

  .ds-sort:not([data-state="descending"]) .ds-sort__word:last-child,
  .ds-sort[data-state="descending"] .ds-sort__word:first-child:not(:last-child) {
    visibility: hidden;
  }

  /* The field's name on the menu trigger: one line, an ellipsis when the
     row is short. */
  .ds-sort__value {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  @container ds-content (max-width: 480px) {
    .ds-sort__label {
      position: absolute;
      width: 1px;
      height: 1px;
      overflow: hidden;
      clip-path: inset(50%);
      white-space: nowrap;
    }
  }
}

/* ── components/text/text.css ── */
/*
 * Text utilities: how a run of text wraps, cuts and sets its figures.
 *
 *   <p class="ds-clamp-2">At most two lines, then an ellipsis</p>
 *   <p class="ds-clamp" style="--ds-clamp-lines: 7">At most seven</p>
 *   <code class="ds-break">a-hash-or-url-that-breaks-anywhere</code>
 *   <span class="ds-mono">SN 4C1-77Q</span>             the code family, the text's size
 *   <span class="ds-tabular">1,284</span>               figures of one width
 *   <h2 class="ds-balance">A heading in lines of even length</h2>
 *   <p class="ds-pretty">A paragraph without a lone last word</p>
 *
 * .ds-nowrap (keep a value and its unit together) is one of the 2.x
 * utilities and stays there.
 *
 * .ds-clamp-* cut what does not fit: put the full text where it can be
 * read (a details view, the title of the page it leads to). One line cut
 * at its end, start or middle is .ds-truncate (truncate.css, with its
 * tooltip). On paper the clamps print in full.
 *
 * Options: none read; the text keeps the type role of where it stands
 * (size changes type through the components, not here).
 *
 * Hooks: --ds-clamp-lines (2) for .ds-clamp.
 *
 * Progressive:
 * - text-wrap (.ds-pretty: no lone last word): without it the paragraph
 *   wraps as usual. (.ds-balance is at the floor.)
 */

@layer ds.components.text {
  /* A fixed number of lines, then an ellipsis: the prefixed box is the one
     form every engine at the floor clamps with. */
  .ds-clamp,
  .ds-clamp-1,
  .ds-clamp-2,
  .ds-clamp-3,
  .ds-clamp-4,
  .ds-clamp-5 {
    display: -webkit-box;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: var(--ds-clamp-lines, 2);
    /* A flex or grid row that stretches it would show the lines after
       the ellipsis: it keeps its own height. */
    align-self: start;
    min-width: 0;
    overflow: hidden;
    overflow-wrap: anywhere;
  }

  .ds-clamp-1 {
    -webkit-line-clamp: 1;
  }

  .ds-clamp-2 {
    -webkit-line-clamp: 2;
  }

  .ds-clamp-3 {
    -webkit-line-clamp: 3;
  }

  .ds-clamp-4 {
    -webkit-line-clamp: 4;
  }

  .ds-clamp-5 {
    -webkit-line-clamp: 5;
  }

  /* Long tokens (hashes, URLs, serial numbers) break anywhere instead of
     widening their column; words still break between them first. */
  .ds-break {
    min-width: 0;
    overflow-wrap: anywhere;
  }

  /* The code family at the size of the text around it; the figures and
     letters keep their own width. */
  .ds-mono {
    font-family: var(--ds-font-mono);
    font-variant-ligatures: none;
  }

  .ds-tabular {
    font-variant-numeric: tabular-nums;
  }

  .ds-balance {
    text-wrap: balance;
  }

  .ds-pretty {
    text-wrap: pretty;
  }

  /* Paper is as wide as it is: cut text prints in full. */
  @media print {
    .ds-clamp,
    .ds-clamp-1,
    .ds-clamp-2,
    .ds-clamp-3,
    .ds-clamp-4,
    .ds-clamp-5 {
      display: block;
      overflow: visible;
    }
  }
}

/* ── components/toggletip/toggletip.css ── */
/*
 * Toggletip: the info button "i" next to a field label or a heading, which
 * opens a help card (a .ds-popover--tip: a title, a text and a link) on a
 * click or a tap, and says its text to a screen reader. Unlike a tooltip it
 * never opens on hover, and its card may hold a link the keyboard reaches.
 *
 *   <div class="ds-field">
 *     <label class="ds-field__label" for="serial">Serial number</label>
 *     <button class="ds-toggletip" type="button" aria-label="About the serial number"
 *             aria-expanded="false" aria-controls="serial-help" data-ds-toggletip="#serial-help">(info)</button>
 *     <div class="ds-popover ds-popover--tip ds-popover--arrow" id="serial-help" role="group" aria-label="Serial number" hidden>
 *       <div class="ds-popover__head"><h3 class="ds-popover__title">Serial number</h3></div>
 *       <div class="ds-popover__body"><p>On the sticker under the device, 8 to 12 letters and digits.</p></div>
 *       <div class="ds-popover__foot"><a class="ds-link-btn" href="#help">Where to find it</a></div>
 *     </div>
 *     <input class="ds-input" id="serial">
 *   </div>
 *
 * In a .ds-field the label and the button share the first row (the button
 * right after the label); anywhere else the button sits inline, centred on
 * the line (a heading, a table header, a key figure).
 *
 * Options: size steps the button, 4px per step from --ds-toggletip-size
 * (24px; an icon-only control: density leaves it); .ds-touch widens its hit
 * area to --ds-target-min around the glyph without moving the label (the
 * ::after box); shape multiplies its radius (a circle at the default, a
 * rounded square at square). Tone does not apply.
 *
 * States: a state layer in the content colour (hover, a press in
 * --ds-dur-micro, the focus layer), the focus ring that snaps from offset +
 * width to the offset, the press morph of a pill (--ds-radius-action-pressed
 * in --ds-dur-micro, back on the spring over --ds-dur-medium); open
 * (aria-expanded="true") it takes the primary ink. No ripple: a 24px glyph
 * next to a label, whose ripple would be smaller than the finger.
 *
 * Forced colours: open, it is Highlight on HighlightText (an open disclosure
 * button); disabled, GrayText.
 *
 * Hook: --ds-toggletip-size (24px).
 */

@layer ds.components.toggletip {
  .ds-toggletip {
    --_box: calc(var(--ds-toggletip-size, 24px) + var(--ds-size-step, 0) * 4px);
    --_half: calc(var(--_box) / 2);
    --_radius: min(calc(min(var(--ds-radius-action), var(--_half)) * var(--ds-shape, 1)), var(--_half));
    position: relative;
    display: inline-flex;
    flex-shrink: 0;
    align-items: center;
    justify-content: center;
    box-sizing: border-box;
    width: var(--_box);
    height: var(--_box);
    margin: 0;
    padding: 0;
    border: 0;
    border-radius: var(--_radius);
    background: transparent;
    color: var(--ds-text-2);
    font: inherit;
    vertical-align: middle;
    cursor: pointer;
    -webkit-tap-highlight-color: transparent;
    outline-offset: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    transition:
      border-radius var(--ds-dur-medium) var(--ds-ease-spatial),
      color var(--ds-dur-fast) var(--ds-ease-in-out),
      opacity var(--ds-dur-fast) var(--ds-ease-in-out),
      outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-toggletip svg {
    width: calc(var(--_box) - var(--ds-space-2));
    height: calc(var(--_box) - var(--ds-space-2));
    pointer-events: none;
  }

  /* The state layer in the content colour. */
  .ds-toggletip::before {
    content: '';
    position: absolute;
    inset: 0;
    border-radius: inherit;
    background: currentColor;
    opacity: 0;
    pointer-events: none;
    transition: opacity var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  /* The hit area: at least --ds-target-min around the glyph (.ds-touch), so a
     finger finds it while the label keeps its line. */
  .ds-toggletip::after {
    content: '';
    position: absolute;
    inset: min(0px, calc((var(--_box) - var(--ds-target-min, 0px)) / 2));
  }

  @media (hover: hover) {
    .ds-toggletip:hover::before {
      opacity: var(--ds-state-hover);
    }
  }

  .ds-toggletip:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: var(--ds-focus-offset);
  }

  .ds-toggletip:focus-visible::before {
    opacity: var(--ds-state-focus);
    transition-duration: 0s;
  }

  /* Press-in in --ds-dur-micro (:active, and .ds-pressed when a page's
     ripple holds it). */
  .ds-toggletip:active::before,
  .ds-toggletip.ds-pressed::before {
    opacity: var(--ds-state-pressed);
    transition-duration: var(--ds-dur-micro);
  }

  /* The press morph of a pill: the pressed role, never rounder than at rest. */
  .ds-toggletip:active:not(:disabled, [aria-disabled="true"], [aria-busy="true"]),
  .ds-toggletip.ds-pressed:not(:disabled, [aria-disabled="true"], [aria-busy="true"]) {
    border-radius: min(calc(var(--ds-radius-action-pressed) * var(--ds-shape, 1)), var(--_radius));
    transition:
      border-radius var(--ds-dur-micro) var(--ds-ease-out),
      color var(--ds-dur-fast) var(--ds-ease-in-out),
      opacity var(--ds-dur-fast) var(--ds-ease-in-out),
      outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  /* Open: its card shows; the word is aria-expanded, the ink only repeats it. */
  .ds-toggletip[aria-expanded="true"] {
    color: var(--ds-primary);
  }

  .ds-toggletip:disabled,
  .ds-toggletip[aria-disabled="true"] {
    opacity: var(--ds-disabled-opacity, var(--ds-state-disabled));
    color: var(--ds-disabled-ink, var(--ds-text-2));
    cursor: default;
  }

  @media (hover: hover) {
    .ds-toggletip:is(:disabled, [aria-disabled="true"]):hover::before {
      opacity: 0;
    }
  }

  .ds-toggletip:is(:disabled, [aria-disabled="true"]):is(:active, .ds-pressed)::before {
    opacity: 0;
  }

  /* In a field: the label and the button share the first row; what
     follows them spans both columns (selected from the button, not as
     children of a field that :has() one: Chromium restyles every ancestor
     of each DOM change anywhere on the page for that form, and lays the
     whole page out). */
  .ds-field:has(> .ds-field__label + .ds-toggletip) {
    grid-template-columns: auto 1fr;
    column-gap: var(--ds-space-1);
  }

  .ds-field > .ds-field__label + .ds-toggletip ~ * {
    grid-column: 1 / -1;
  }

  .ds-field > .ds-field__label:has(+ .ds-toggletip) {
    grid-column: 1;
    align-self: center;
  }

  .ds-field > .ds-field__label + .ds-toggletip {
    grid-column: 2;
    justify-self: start;
    align-self: center;
  }

  @media (forced-colors: active) {
    .ds-toggletip[aria-expanded="true"] {
      forced-color-adjust: none;
      background: Highlight;
      color: HighlightText;
    }

    .ds-toggletip:disabled,
    .ds-toggletip[aria-disabled="true"] {
      color: GrayText;
    }
  }
}

/* ── components/dashpanel/dashpanel.css ── */
/*
 * Dashboard panel: a titled block of a dashboard (a chart, a table, a
 * list, a few figures) with a menu at its end and the states its data goes
 * through: loading, refreshing, failed, nothing to show. Panels sit in a
 * grid (.ds-grid-2, an auto-fit grid) and fill their cell's height, so a
 * row of panels lines up whatever each one shows.
 *
 *   <section class="ds-dashpanel" aria-labelledby="p-tickets">
 *     <header class="ds-dashpanel__head">
 *       <div class="ds-dashpanel__heading">
 *         <h3 class="ds-dashpanel__title" id="p-tickets">Tickets per day</h3>
 *         <p class="ds-dashpanel__subtitle">Last 7 days</p>
 *       </div>
 *       <div class="ds-dashpanel__actions">
 *         <button class="ds-btn ds-btn--icon ds-btn--quiet ds-sm" type="button" aria-label="Actions for tickets per day"
 *                 aria-haspopup="menu" aria-expanded="false" aria-controls="p-tickets-menu" data-ds-open="#p-tickets-menu">(moreVertical 18)</button>
 *         <div class="ds-menu" id="p-tickets-menu" role="menu" aria-label="Tickets per day" hidden> ... </div>
 *       </div>
 *       <span class="ds-loadbar" aria-hidden="true"><span class="ds-loadbar__bar"></span></span>
 *     </header>
 *     <div class="ds-dashpanel__body"> ... </div>
 *     <div class="ds-dashpanel__foot"><span>Updated 09:12</span> <a href="/tickets">All tickets</a></div>
 *   </section>
 *
 * Parts:
 *   .ds-dashpanel__head      the title row: the heading, then the actions;
 *                            at least --ds-dashpanel-head-height (56px)
 *   .ds-dashpanel__heading   the title and the subtitle, as wide as it gets
 *   .ds-dashpanel__title     one line, an ellipsis when it is too long
 *                            (give the panel the whole title in its name)
 *   .ds-dashpanel__subtitle  the period, the unit or the source, one line
 *   .ds-dashpanel__actions   at the end: a status (.ds-status: stale data,
 *                            partial data), a small quiet icon button or two
 *                            and the menu button with its .ds-menu
 *   .ds-dashpanel__body      the content; it grows to fill the panel and is
 *                            at least --ds-dashpanel-body-min (160px) high,
 *                            so a state that replaces it keeps the place
 *   .ds-dashpanel__body--flush   no padding: a table, a list or a chart that
 *                            runs to the panel's edges
 *   .ds-dashpanel__foot      a hairline, then meta text and a link: when it
 *                            was updated, where the rest is
 *
 * States (the page sets them; status is never told by colour alone):
 *   loading      aria-busy="true" on the panel and a skeleton (loading.css)
 *                in the body; the loading bar of the head shows
 *   refreshing   DS.motion.refresh(body, load, { loadbar: false }): the body
 *                takes aria-busy="true" at once and dims (.ds-stale) after
 *                --ds-delay-loader; the loading bar of the head shows while
 *                the body is busy
 *   failed       an empty state in the body, .ds-empty--error with its icon,
 *                words and a "Try again" button
 *   no data      an empty state in the body, .ds-empty--no-data
 *   stale        a .ds-status (icon and word) in the actions
 * An empty state alone in the body sits in its middle. The loading bar
 * (.ds-loadbar, last in the head) lies along the head's lower edge and
 * shows only while the panel or its body is busy; it waits the loader delay
 * like every loading bar.
 *
 * Variants:
 *   .ds-dashpanel             outlined: the hairline on --ds-surface
 *   .ds-dashpanel--filled     --ds-surface-low, no hairline: a panel inside
 *                             a card or on a busy dashboard
 *   .ds-dashpanel--elevated   --ds-dashpanel-shadow (--ds-elev-1) instead of
 *                             the hairline
 *
 * Options (src/core/options.css, docs/options.md), computed here:
 *   density   .ds-density-*: the padding, 2px per step, and the head's
 *             height, 4px per step
 *   shape     .ds-shape-*: the corners
 *   touch     .ds-touch: the head at least the touch target high
 *   size      not read: a size class reaches the controls in it
 *   tone      not read: the empty state, a status or an alert in it says
 *             what is wrong, with an icon and a word
 *
 * Forced colours: the hairline stays (a border), the filled and the elevated
 * panel get a transparent border that becomes their edge.
 *
 * Hooks: --ds-dashpanel-padding (--ds-space-4), --ds-dashpanel-radius
 * (--ds-radius-card), --ds-dashpanel-bg (--ds-surface),
 * --ds-dashpanel-border (--ds-line), --ds-dashpanel-filled-bg
 * (--ds-surface-low), --ds-dashpanel-shadow (--elevated: --ds-elev-1),
 * --ds-dashpanel-head-height (56px), --ds-dashpanel-body-min (160px).
 * --_dashpanel-pad, --_dashpanel-radius, --_bg, --_border, --_shadow and
 * --_head are private.
 *
 * No progressive features.
 */

@layer ds.components.dashpanel {
  .ds-dashpanel {
    /* The padding and the corners, computed here and read by the parts (a
       density class on a part changes that part only where it computes its
       own); the names are the panel's own. */
    --_dashpanel-pad: calc(var(--ds-dashpanel-padding, var(--ds-space-4)) + var(--ds-density, 0) * 2px);
    --_dashpanel-radius: calc(var(--ds-dashpanel-radius, var(--ds-radius-card)) * var(--ds-shape, 1));
    --_bg: var(--ds-dashpanel-bg, var(--ds-surface));
    --_border: var(--ds-dashpanel-border, var(--ds-line));
    --_shadow: none;
    position: relative;
    display: flex;
    flex-direction: column;
    min-inline-size: 0;
    block-size: 100%;
    border: 1px solid var(--_border);
    border-radius: var(--_dashpanel-radius);
    background: var(--_bg);
    box-shadow: var(--_shadow);
    color: var(--ds-text);
  }

  .ds-dashpanel--filled {
    --_bg: var(--ds-dashpanel-filled-bg, var(--ds-surface-low));
    --_border: transparent;
  }

  .ds-dashpanel--elevated {
    --_border: transparent;
    --_shadow: var(--ds-dashpanel-shadow, var(--ds-elev-1));
  }

  .ds-dashpanel__head {
    --_head: max(var(--ds-target-min, 0px), calc(var(--ds-dashpanel-head-height, 56px) + var(--ds-density, 0) * 4px));
    position: relative;
    display: flex;
    flex: none;
    align-items: center;
    gap: var(--ds-space-2);
    min-block-size: var(--_head);
    padding-block: var(--ds-space-2);
    padding-inline: var(--_dashpanel-pad) calc(var(--_dashpanel-pad) - var(--ds-space-2));
  }

  .ds-dashpanel__heading {
    flex: 1 1 auto;
    min-inline-size: 0;
  }

  .ds-dashpanel__title,
  .ds-dashpanel__subtitle {
    margin: 0;
    overflow: hidden;
    white-space: nowrap;
    text-overflow: ellipsis;
  }

  .ds-dashpanel__title {
    color: var(--ds-text);
    font: var(--ds-font-subtitle);
  }

  .ds-dashpanel__subtitle {
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
  }

  .ds-dashpanel__actions {
    display: flex;
    flex: none;
    align-items: center;
    gap: var(--ds-space-1);
  }

  /* The loading bar along the head's lower edge, while the panel or its
     body is busy (it waits the loader delay, loading.css). */
  .ds-dashpanel__head > .ds-loadbar {
    position: absolute;
    inset-block: auto 0;
    inset-inline: 0;
    margin: 0;
  }

  .ds-dashpanel:not([aria-busy="true"], :has(> .ds-dashpanel__body[aria-busy="true"])) > .ds-dashpanel__head > .ds-loadbar {
    display: none;
  }

  .ds-dashpanel__body {
    position: relative;
    display: flex;
    flex: 1 1 auto;
    flex-direction: column;
    gap: calc(var(--ds-space-4) + var(--ds-density, 0) * 2px);
    min-inline-size: 0;
    min-block-size: var(--ds-dashpanel-body-min, 160px);
    padding: 0 var(--_dashpanel-pad) var(--_dashpanel-pad);
  }

  .ds-dashpanel__body--flush {
    padding: 0;
  }

  /* An empty state alone in the body (failed, no data) sits in its middle. */
  .ds-dashpanel__body > .ds-empty:only-child {
    margin-block: auto;
  }

  /* A list in a flush body runs to the panel's edges: a hairline above it,
     and at the panel's foot the panel's lower corners (inside its border). */
  .ds-dashpanel__body--flush > .ds-list {
    border-inline: 0;
    border-block-end: 0;
    border-radius: 0;
  }

  .ds-dashpanel > .ds-dashpanel__body--flush:last-child > .ds-list:last-child {
    border-end-start-radius: var(--_dashpanel-radius);
    border-end-end-radius: var(--_dashpanel-radius);
  }

  .ds-dashpanel__foot {
    display: flex;
    flex: none;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: var(--ds-space-2) var(--ds-space-4);
    padding: calc(var(--ds-space-3) + var(--ds-density, 0) * 2px) var(--_dashpanel-pad);
    border-block-start: 1px solid var(--ds-line);
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
  }

  @media print {
    .ds-dashpanel {
      break-inside: avoid;
    }

    .ds-dashpanel__head > .ds-loadbar {
      display: none;
    }
  }
}

/* ── components/filterbar/filterbar.css ── */
/*
 * Filter bar: a search and inline filters above a list, the applied
 * filters as chips with "Clear all", and a result count. When the bar is
 * too narrow for its filters they fold behind a "Filters" button that
 * opens them in a side sheet (js/filterbar.js):
 *
 *   <div class="ds-filterbar" data-ds-filterbar data-ds-filterbar-sheet="#filters-sheet" role="search" aria-label="Filter devices">
 *     <div class="ds-filterbar__row">
 *       <div class="ds-search ds-filterbar__search">(search)<input class="ds-input" type="search" name="q" aria-label="Search devices" placeholder="Search devices"></div>
 *       <div class="ds-filterbar__filters">
 *         <div class="ds-field"><label class="ds-field__label" for="status">Status</label>
 *           <select class="ds-input" id="status" name="status"><option value="">Any</option>...</select></div>
 *         <div class="ds-filterbar__range" role="group" aria-label="Storage in GB" data-ds-filter-label="Storage">
 *           <div class="ds-field">(min: data-ds-filter-bound="min")</div><div class="ds-field">(max)</div></div>
 *         ...
 *       </div>
 *       <button class="ds-btn ds-filterbar__more" type="button" aria-haspopup="dialog">(filter 20)Filters<span class="ds-badge ds-filterbar__badge" hidden></span></button>
 *       <p class="ds-filterbar__count">48 results</p>
 *     </div>
 *     <div class="ds-filterbar__applied" hidden>
 *       <div class="ds-chips ds-filterbar__chips" role="group" aria-label="Applied filters"></div>
 *       <button class="ds-btn ds-btn--text ds-filterbar__clear" type="button">Clear all</button>
 *     </div>
 *   </div>
 *   <dialog class="ds-sheet" id="filters-sheet" aria-labelledby="filters-title"> ... head ...
 *     <div class="ds-sheet__body" tabindex="0"></div>      (the filters move in here)
 *     <div class="ds-sheet__foot"><button class="ds-btn ds-btn--text ds-filterbar__clear" type="button">Clear all</button>
 *       <button class="ds-btn ds-btn--filled ds-filterbar__results" type="button" data-ds-close>Show 48 results</button></div>
 *   </dialog>
 *
 * The row: the search takes the room that is left, at least
 * --ds-filterbar-search-min (200px); the filters sit in one line after it,
 * their fields --ds-filterbar-field-width (160px) wide (the two fields of
 * a .ds-filterbar__range --ds-filterbar-range-width, 96px, each); the count
 * at the end. Without the script the row wraps. With it, data-folded (written by
 * the system when the row cannot hold them in one line) hides the filters
 * and shows .ds-filterbar__more, whose badge counts the applied filters
 * among them. In the sheet's body the filters stack, full width (a range's
 * two fields share the row).
 *
 * The applied row: input chips (chip.css), one per applied value, and
 * "Clear all" after them; it hides while nothing is applied (the hidden
 * attribute, written by the system). A chip names its filter and value in
 * words ("Status: Online"), so nothing depends on colour.
 *
 * Options (src/core/options.css, docs/options.md), on .ds-filterbar or
 * any ancestor:
 *   size, shape, touch  reach the search, fields, buttons and chips, which
 *                       compute them; the gaps step 4px per size step
 *   density             the gaps, 2px per step; and the controls' heights
 * The count keeps the meta role. There is no tone: a filter shows no
 * meaning of its own.
 *
 * Forced colours: the chips, fields and buttons keep their own models; the
 * bar adds no colour.
 *
 * Hooks: --ds-filterbar-search-min (200px), --ds-filterbar-field-width
 * (160px), --ds-filterbar-range-width (96px), --ds-filterbar-gap (12px). The computed --_gap and --_field are private: never
 * set it.
 *
 * No progressive feature in the stylesheet.
 */

@layer ds.components.filterbar {
  .ds-filterbar {
    --_gap: max(var(--ds-space-1), calc(var(--ds-filterbar-gap, var(--ds-space-3)) + var(--ds-size-step, 0) * 4px + var(--ds-density, 0) * 2px));
    display: grid;
    gap: var(--_gap);
    min-width: 0;
  }

  .ds-filterbar__row {
    /* A field's height, as form.css computes it: the count centres on it. */
    --_field: max(var(--ds-target-min, 0px), calc(var(--ds-input-height, 40px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px));
    display: flex;
    flex-wrap: wrap;
    align-items: flex-end;
    gap: var(--_gap);
    min-width: 0;
  }

  .ds-filterbar__search {
    flex: 1 1 var(--ds-filterbar-search-min, 200px);
    min-width: var(--ds-filterbar-search-min, 200px);
  }

  .ds-filterbar__filters {
    display: flex;
    flex: none;
    flex-wrap: nowrap;
    align-items: flex-end;
    gap: var(--_gap);
    max-width: 100%;
  }

  .ds-filterbar__filters .ds-field {
    width: var(--ds-filterbar-field-width, 160px);
  }

  /* A range: two fields of one name side by side, narrower than a field. */
  .ds-filterbar__range {
    display: flex;
    align-items: flex-end;
    gap: var(--ds-space-2);
    min-width: 0;
  }

  .ds-filterbar__filters .ds-filterbar__range > .ds-field {
    width: var(--ds-filterbar-range-width, 96px);
  }

  .ds-filterbar__more {
    display: none;
  }

  .ds-filterbar[data-folded] .ds-filterbar__filters {
    display: none;
  }

  .ds-filterbar[data-folded] .ds-filterbar__more {
    display: inline-flex;
  }

  .ds-filterbar__count {
    margin: 0;
    margin-inline-start: auto;
    margin-block-end: max(0px, calc((var(--_field) - 1lh) / 2));
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
  }

  .ds-filterbar__count:empty {
    display: none;
  }

  .ds-filterbar__chips {
    min-width: 0;
  }

  .ds-filterbar__clear,
  .ds-filterbar__results {
    flex: none;
    font-variant-numeric: tabular-nums;
  }

  .ds-filterbar__applied {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--ds-space-2);
    min-width: 0;
  }

  /* Hidden by the system while nothing is applied (or nothing folded). */
  .ds-filterbar__applied[hidden],
  .ds-filterbar__badge[hidden] {
    display: none;
  }

  /* The folded filters in the sheet: one column, every field full width. */
  .ds-sheet__body > .ds-filterbar__filters {
    display: grid;
    gap: max(var(--ds-space-3), calc(var(--ds-space-5) + var(--ds-density, 0) * 2px));
    align-items: start;
  }

  .ds-sheet__body > .ds-filterbar__filters .ds-field {
    width: auto;
  }

  .ds-sheet__body > .ds-filterbar__filters .ds-filterbar__range > .ds-field {
    flex: 1 1 0;
    width: auto;
    min-width: 0;
  }

}

/* ── components/picker/picker.css ── */
/*
 * Picker: the popover every date and time picker opens from its button (a
 * modal dialog: the WAI-ARIA date picker dialog), and its parts: the panes
 * side by side, the presets beside them, the foot with its actions.
 * DS.picker (picker.js) places, opens and closes it through DS.overlay.
 *
 *   <div class="ds-picker" data-ds-picker>
 *     <button class="ds-btn" type="button" data-ds-picker-toggle aria-haspopup="dialog" aria-expanded="false">Filters</button>
 *     <div class="ds-picker__popover" role="dialog" aria-modal="true" aria-label="Filters" hidden
 *          data-state="open | closed" [data-placement="top"]>
 *       <div class="ds-picker__panes">
 *         <div class="ds-picker__presets" role="group" aria-label="Presets">
 *           <button class="ds-picker__preset" type="button" [aria-current="true"]>Last 7 days</button> ...
 *         </div>
 *         <div class="ds-picker__pane">(a calendar, a list ...)</div>
 *       </div>
 *       <p class="ds-picker__heading">Recently used</p>
 *       <div class="ds-picker__foot">
 *         <button class="ds-btn ds-btn--text" type="button">Today</button>
 *         <span class="ds-picker__spacer"></span>
 *         <button class="ds-btn ds-btn--filled" type="button">Apply</button>
 *       </div>
 *     </div>
 *   </div>
 *
 * Presets: .ds-picker__preset is a row button in the body type; the one in
 * force carries aria-current="true" (the tint and the label weight, so not
 * by colour alone). It is an action: a state layer (hover, press in
 * --ds-dur-micro), the ripple, an inset focus ring that snaps in.
 *
 * Placement API: --ds-picker-x and --ds-picker-y (left and top, px,
 * written by DS.position.place() through DS.picker): fixed, and while open
 * in the top layer (popover="manual", which DS.picker sets), so no
 * scrolling, clipping or transformed box cuts it off or covers it.
 *
 * Options (src/core/options.css, docs/options.md), on the picker or any
 * ancestor; each is computed here:
 *   size      .ds-xs ... .ds-xl: a preset row 8px per step from
 *             --ds-picker-preset-height (40px); the content follows its
 *             own components (a calendar's days, a list's rows)
 *   density   .ds-density-*: a preset row 4px per step, the popover's
 *             padding 2px per step
 *   shape     .ds-shape-*: multiplies the popover's radius and a preset's
 *   touch     .ds-touch: a preset at least --ds-touch-target high
 *   tone      none
 *
 * Motion (as a menu): it fades in over --ds-dur-fast while its clip opens
 * from the button's edge (--ds-clip-from) and it grows from
 * --ds-scale-popup at the button (--ds-motion-origin), both over
 * --ds-dur-medium on the spring; it leaves with a fade (--ds-dur-instant).
 * Transitions keyed on data-state (DS.overlay), so a picker closed mid-way
 * turns back from where it is; shown by hand (no data-state) it plays
 * ds-fade-in and ds-clip-in once.
 *
 * Narrow (600px or less): panes and presets stack, the presets wrap into a
 * row of their own.
 *
 * Forced colours: the popover keeps an edge (its transparent outline), the
 * preset in force is SelectedItem / SelectedItemText, a focused one keeps
 * its ring.
 *
 * Progressive:
 * - scrollbar-color and scrollbar-width (a thin scrollbar on a scrolling
 *   pane): without them the platform scrollbar shows.
 */

@layer ds.components.picker {
  .ds-picker {
    position: relative;
    display: inline-block;
    max-inline-size: 100%;
    vertical-align: middle;
  }

  .ds-picker--block {
    display: block;
  }

  /* Fixed, so no scrolling or clipping box cuts it off. Physical on purpose:
     --ds-picker-x is a script coordinate from the left. */
  .ds-picker__popover {
    position: fixed;
    inset: var(--ds-picker-y, 0px) auto auto var(--ds-picker-x, 0px);
    z-index: var(--ds-z-popover);
    box-sizing: border-box;
    inline-size: max-content;
    max-inline-size: calc(100vw - 2 * var(--ds-space-2));
    max-block-size: calc(100vh - 2 * var(--ds-space-2));
    margin: 0;
    padding: calc(var(--ds-picker-padding, var(--ds-space-3)) + var(--ds-density, 0) * 2px);
    overflow: auto;
    overscroll-behavior: contain;
    border: 0;
    border-radius: calc(var(--ds-picker-radius, var(--ds-radius-lg)) * var(--ds-shape, 1));
    background: var(--ds-surface-popover);
    color: var(--ds-text);
    box-shadow: var(--ds-elev-popover);
    /* Invisible; forced colours paint it, so the popover keeps an edge. */
    outline: 1px solid transparent;
    transform-origin: var(--ds-motion-origin, 0% 0%);
    clip-path: inset(calc(-1 * var(--ds-space-6)));
  }

  .ds-picker__popover[data-placement="top"] {
    transform-origin: var(--ds-motion-origin, 0% 100%);
  }

  /* Shown by hand (no data-state): the reveal plays once. */
  .ds-picker__popover:not([data-state]) {
    animation:
      ds-fade-in var(--ds-dur-fast) var(--ds-ease-in-out) backwards,
      ds-clip-in var(--ds-dur-medium) var(--ds-ease-spatial) backwards;
  }

  /* Driven by DS.overlay: transitions keyed on data-state. */
  .ds-picker__popover[data-state] {
    animation: none;
    transition:
      opacity var(--ds-dur-fast) var(--ds-ease-in-out),
      scale var(--ds-dur-medium) var(--ds-ease-spatial),
      clip-path var(--ds-dur-medium) var(--ds-ease-spatial);
  }

  /* The exit only fades; scale and clip go back to their start once it is
     invisible. Closed, it takes no pointer. */
  .ds-picker__popover[data-state="closed"] {
    opacity: 0;
    scale: var(--ds-motion-scale, var(--ds-scale-popup));
    clip-path: var(--ds-clip-from, inset(0 0 100% 0));
    pointer-events: none;
    transition:
      opacity var(--ds-dur-instant) var(--ds-ease-in-out),
      scale 0ms var(--ds-ease-in-out) var(--ds-dur-instant),
      clip-path 0ms var(--ds-ease-in-out) var(--ds-dur-instant);
  }

  .ds-picker__popover[hidden] {
    display: none;
  }

  /* Panes side by side: presets, a calendar, a list. */
  .ds-picker__panes {
    display: flex;
    align-items: flex-start;
    gap: var(--ds-space-4);
  }

  .ds-picker__pane {
    position: relative;
    min-inline-size: 0;
  }

  /* A pane that scrolls inside the popover's height (a list of times). */
  .ds-picker__pane--scroll {
    align-self: stretch;
    max-block-size: var(--ds-picker-pane-height, 320px);
    overflow-y: auto;
    overscroll-behavior: contain;
    scrollbar-width: thin;
    scrollbar-color: var(--ds-line-2) transparent;
  }

  .ds-picker__presets {
    display: flex;
    flex: none;
    flex-direction: column;
    gap: 2px;
    min-inline-size: 160px;
    padding-inline-end: var(--ds-space-3);
    border-inline-end: 1px solid var(--ds-line);
  }

  .ds-picker__heading {
    margin: var(--ds-space-3) 0 var(--ds-space-1);
    padding-inline: var(--ds-space-3);
    color: var(--ds-text-2);
    font: var(--ds-font-caption);
  }

  .ds-picker__presets > .ds-picker__heading:first-child {
    margin-block-start: 0;
  }

  .ds-picker__preset {
    --_h: calc(var(--ds-picker-preset-height, 40px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px);
    --_box: max(var(--ds-target-min, 0px), var(--_h));
    --_radius: min(calc(min(var(--ds-radius-action), calc(var(--_box) / 2)) * var(--ds-shape, 1)), calc(var(--_box) / 2));
    position: relative;
    isolation: isolate;
    display: flex;
    align-items: center;
    gap: var(--ds-space-2);
    inline-size: 100%;
    min-block-size: var(--_box);
    margin: 0;
    padding: 0 var(--ds-space-3);
    border: 0;
    border-radius: var(--_radius);
    background: transparent;
    color: var(--ds-text);
    font: var(--ds-size-font, var(--ds-font-body));
    text-align: start;
    cursor: pointer;
    -webkit-tap-highlight-color: transparent;
    /* An inset ring: the list is tight; it rests on the edge and snaps in. */
    outline-offset: 0;
    transition:
      background-color var(--ds-dur-fast) var(--ds-ease-in-out),
      color var(--ds-dur-fast) var(--ds-ease-in-out),
      border-radius var(--ds-dur-medium) var(--ds-ease-spatial),
      outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-picker__preset::before {
    content: '';
    position: absolute;
    inset: 0;
    z-index: -1;
    border-radius: inherit;
    background: currentColor;
    opacity: 0;
    pointer-events: none;
    transition: opacity var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  @media (hover: hover) {
    .ds-picker__preset:hover::before {
      opacity: var(--ds-state-hover);
    }
  }

  .ds-picker__preset:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: calc(-1 * var(--ds-focus-width));
  }

  .ds-picker__preset:focus-visible::before {
    opacity: var(--ds-state-focus);
    transition-duration: 0s;
  }

  .ds-picker__preset:active::before,
  .ds-picker__preset.ds-pressed::before {
    opacity: var(--ds-state-pressed);
    transition-duration: var(--ds-dur-micro);
  }

  .ds-picker__preset:active:not(:disabled, [aria-disabled="true"], [aria-busy="true"]),
  .ds-picker__preset.ds-pressed:not(:disabled, [aria-disabled="true"], [aria-busy="true"]) {
    border-radius: min(calc(var(--ds-radius-action-pressed) * var(--ds-shape, 1)), var(--_radius));
    transition: border-radius var(--ds-dur-micro) var(--ds-ease-out);
  }

  /* With DS.ripple.attach() the ripple brings the press. */
  :where(.ds-ripples) .ds-picker__preset:where(:not([data-ds-ripple="off"], [data-ds-ripple="off"] *, :disabled, [aria-disabled="true"])):is(:active, .ds-pressed)::before {
    opacity: 0;
  }

  @media (hover: hover) {
    :where(.ds-ripples) .ds-picker__preset:where(:not([data-ds-ripple="off"], [data-ds-ripple="off"] *, :disabled, [aria-disabled="true"])):is(:active, .ds-pressed)::before {
      opacity: var(--ds-state-hover);
    }
  }

  /* The preset in force: the tint and the label's weight. */
  .ds-picker__preset[aria-current="true"] {
    background: var(--ds-accent);
    color: var(--ds-on-accent);
    font-weight: var(--ds-weight-label);
  }

  .ds-picker__preset:is(:disabled, [aria-disabled="true"]) {
    color: var(--ds-disabled-ink);
    cursor: default;
  }

  .ds-picker__preset:is(:disabled, [aria-disabled="true"])::before {
    opacity: 0;
  }

  /* Secondary text at a preset's end (a range, a shortcut). */
  .ds-picker__meta {
    margin-inline-start: auto;
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
    font-variant-numeric: tabular-nums;
  }

  .ds-picker__foot {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--ds-space-2);
    margin-block-start: var(--ds-space-3);
    padding-block-start: var(--ds-space-3);
    border-block-start: 1px solid var(--ds-line);
  }

  .ds-picker__spacer {
    flex: 1;
  }

  @media (max-width: 600px) {
    .ds-picker__panes {
      flex-direction: column;
      align-items: stretch;
    }

    .ds-picker__presets {
      flex-direction: row;
      flex-wrap: wrap;
      min-inline-size: 0;
      padding-inline-end: 0;
      padding-block-end: var(--ds-space-3);
      border-inline-end: 0;
      border-block-end: 1px solid var(--ds-line);
    }

    .ds-picker__presets > .ds-picker__heading {
      flex-basis: 100%;
    }

    .ds-picker__presets > .ds-picker__preset {
      inline-size: auto;
    }
  }

  @media (forced-colors: active) {
    .ds-picker__preset[aria-current="true"] {
      forced-color-adjust: none;
      background: SelectedItem;
      color: SelectedItemText;
    }

    .ds-picker__preset[aria-current="true"]:focus-visible {
      outline-color: CanvasText;
    }

    .ds-picker__preset:is(:disabled, [aria-disabled="true"]) {
      color: GrayText;
    }
  }
}

/* ── components/spacing/spacing.css ── */
/*
 * Spacing: the gap of a flex or grid container and, for the rare case, a
 * top margin, both on the space scale (--ds-space-1 ... --ds-space-12, a
 * 4px grid). Space between parts is the container's gap; a margin is
 * only for what a container cannot give (one block set apart in flowing
 * text, an item pushed to the end of a column).
 *
 *   <div class="ds-stack ds-gap-2">...</div>        8px between the parts
 *   <div class="ds-cluster ds-gap-6">...</div>
 *   <p class="ds-mt-4">...</p>                       16px above
 *   <div class="ds-mt-auto">...</div>                pushed to the end of a column
 *
 *   .ds-gap-0, -1, -2, -3, -4, -5, -6, -8, -10, -12   gap: --ds-space-<n> (0: none)
 *   .ds-mt-0, -1, -2, -3, -4, -5, -6, -8, -10, -12    margin-block-start: --ds-space-<n>
 *   .ds-mt-auto                                       margin-block-start: auto
 *
 * They come after every component but the ripple in the cascade, so
 * they set the gap of a stack, a cluster, a card's rows or a form row
 * whatever the component gives it. An exact step: density does not change it (the primitives'
 * own default gaps follow density, layout.css).
 *
 * Options: none read.
 */

@layer ds.components.spacing {
  .ds-gap-0 {
    gap: 0px;
  }

  .ds-gap-1 {
    gap: var(--ds-space-1);
  }

  .ds-gap-2 {
    gap: var(--ds-space-2);
  }

  .ds-gap-3 {
    gap: var(--ds-space-3);
  }

  .ds-gap-4 {
    gap: var(--ds-space-4);
  }

  .ds-gap-5 {
    gap: var(--ds-space-5);
  }

  .ds-gap-6 {
    gap: var(--ds-space-6);
  }

  .ds-gap-8 {
    gap: var(--ds-space-8);
  }

  .ds-gap-10 {
    gap: var(--ds-space-10);
  }

  .ds-gap-12 {
    gap: var(--ds-space-12);
  }

  .ds-mt-0 {
    margin-block-start: 0px;
  }

  .ds-mt-1 {
    margin-block-start: var(--ds-space-1);
  }

  .ds-mt-2 {
    margin-block-start: var(--ds-space-2);
  }

  .ds-mt-3 {
    margin-block-start: var(--ds-space-3);
  }

  .ds-mt-4 {
    margin-block-start: var(--ds-space-4);
  }

  .ds-mt-5 {
    margin-block-start: var(--ds-space-5);
  }

  .ds-mt-6 {
    margin-block-start: var(--ds-space-6);
  }

  .ds-mt-8 {
    margin-block-start: var(--ds-space-8);
  }

  .ds-mt-10 {
    margin-block-start: var(--ds-space-10);
  }

  .ds-mt-12 {
    margin-block-start: var(--ds-space-12);
  }

  /* In a flex column the auto margin takes the free space: this block and
     what follows go to the end (a card's links at its foot). */
  .ds-mt-auto {
    margin-block-start: auto;
  }
}

/* ── components/wizard/wizard.css ── */
/*
 * Form wizard (3.0): a form in steps on the Steps component, each step
 * checked before the next, Back and Next, and a summary step with an Edit
 * button per step. DS.wizard (wizard.js) moves between the panels, checks
 * them and writes the steps and the summary.
 *
 *   <form class="ds-wizard" data-ds-wizard aria-labelledby="report-title">
 *     <ol class="ds-steps ds-wizard__steps" aria-label="Report a problem"></ol>   (written by DS.wizard)
 *     <section class="ds-wizard__panel" aria-labelledby="s1">
 *       <h3 class="ds-wizard__title" id="s1">Device</h3> (fields) </section>
 *     <section class="ds-wizard__panel" data-ds-wizard-summary aria-labelledby="s4" hidden>
 *       <h3 class="ds-wizard__title" id="s4">Review</h3>
 *       <div class="ds-wizard__summary">            (written by DS.wizard)
 *         <section class="ds-wizard__group"><div class="ds-wizard__group-head">
 *           <h4 class="ds-wizard__group-title">Device</h4>
 *           <button class="ds-btn ds-btn--text ds-sm ds-wizard__edit" aria-label="Edit Device">Edit</button></div>
 *           <dl class="ds-facts ds-facts--rows"> ... </dl></section></div></section>
 *     <div class="ds-wizard__actions">
 *       <button class="ds-btn ds-wizard__back" type="button">Back</button>
 *       <button class="ds-btn ds-btn--filled ds-wizard__next" type="button">Next</button>
 *       <button class="ds-btn ds-btn--filled ds-wizard__submit" type="submit" hidden>Send report</button></div>
 *   </form>
 *
 * The panels stack in one column; only the current one shows (hidden on
 * the others). Its title takes the focus when a step opens (tabindex="-1",
 * with the ring on keyboard use). The actions sit under a hairline: Back at
 * the start, Next or the submit button at the end, one filled button in
 * the area; they wrap on a phone. An invalid field gets Form's error hint
 * (.ds-field__hint--error.ds-wizard__error, with its icon and words).
 *
 * Options (src/core/options.css, docs/options.md), on the wizard or any
 * ancestor; each is computed here, in the rule that uses it:
 *   size      .ds-xs ... .ds-xl: the steps, fields and buttons step
 *             themselves (Steps, Form, Button)
 *   density   .ds-density-*: the room between the parts, inside a panel and
 *             in the summary 2px per step
 *   shape     .ds-shape-*: the parts follow (Steps, Form, Button)
 *   touch     .ds-touch: fields and buttons take --ds-touch-target
 *   tone      none: a step's status is the Steps' data-status, with its
 *             icon and word
 *
 * Hooks: --ds-wizard-gap (--ds-space-6: between the steps, the panel and
 * the actions), --ds-wizard-panel-gap (--ds-space-4: inside a panel). The
 * private --_gap is computed here: never set it.
 *
 * Motion: the panel that opens plays .ds-enter--swap (DS.motion.enter);
 * a done step's check draws itself and its connector turns (Steps).
 *
 * Forced colours: the parts are Steps', Form's and Button's; the hairline
 * over the actions stays (CanvasText).
 */

@layer ds.components.wizard {
  .ds-wizard {
    --_gap: calc(var(--ds-wizard-gap, var(--ds-space-6)) + var(--ds-density, 0) * 2px);
    display: grid;
    gap: var(--_gap);
    min-width: 0;
  }

  .ds-wizard__steps {
    margin: 0;
  }

  .ds-wizard__panel {
    display: grid;
    align-content: start;
    gap: calc(var(--ds-wizard-panel-gap, var(--ds-space-4)) + var(--ds-density, 0) * 2px);
    min-width: 0;
  }

  .ds-wizard__panel[hidden] {
    display: none;
  }

  .ds-wizard__title {
    margin: 0;
    color: var(--ds-text);
    font: var(--ds-font-title);
    border-radius: calc(var(--ds-radius-xs) * var(--ds-shape, 1));
    outline-offset: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    transition: outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-wizard__title:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: var(--ds-focus-offset);
  }

  .ds-wizard__actions {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: flex-end;
    gap: var(--ds-space-2);
    padding-block-start: calc(var(--ds-space-4) + var(--ds-density, 0) * 2px);
    border-block-start: 1px solid var(--ds-line);
  }

  .ds-wizard__back {
    margin-inline-end: auto;
  }

  :is(.ds-wizard__back, .ds-wizard__next, .ds-wizard__submit)[hidden] {
    display: none;
  }

  .ds-wizard__error {
    max-inline-size: var(--ds-measure);
  }

  .ds-wizard__summary {
    display: grid;
    gap: calc(var(--ds-space-5) + var(--ds-density, 0) * 2px);
  }

  .ds-wizard__group {
    display: grid;
    gap: var(--ds-space-2);
    min-width: 0;
  }

  .ds-wizard__group-head {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: var(--ds-space-2);
  }

  .ds-wizard__group-title {
    margin: 0;
    color: var(--ds-text);
    font: var(--ds-font-subtitle);
  }

  .ds-wizard__edit {
    flex: none;
  }

  @media (forced-colors: active) {
    .ds-wizard__actions {
      border-block-start-color: CanvasText;
    }
  }
}

/* ── components/facets/facets.css ── */
/*
 * Facet filter panel: the filters of a list beside it, one facet per field
 * (checkboxes or radios with counts, a range of two fields), a search inside
 * a long facet, "Show all" after a limit, the applied filters as chips and
 * Clear all (js/facets.js). When the layout cannot hold the panel beside
 * the results it folds away behind a "Filters" button, which opens it in a
 * side sheet (on phones from the bottom):
 *
 *   <div class="ds-facets-layout">
 *     <section class="ds-facets" role="complementary" data-ds-facets data-ds-facets-sheet="#facets-sheet" aria-labelledby="facets-title">
 *       <div class="ds-facets__head"><h2 class="ds-facets__title" id="facets-title">Filters</h2>
 *         <button class="ds-btn ds-btn--text ds-facets__clear" type="button">Clear all</button></div>
 *       <div class="ds-facets__applied" hidden><div class="ds-chips ds-facets__chips" role="group" aria-label="Applied filters"></div></div>
 *       <fieldset class="ds-facet"><legend class="ds-facet__title">Status</legend>
 *         <div class="ds-facet__options">
 *           <label class="ds-check"><input type="checkbox" name="status" value="online"><span>Online</span><span class="ds-check__count">24</span></label> ...
 *         </div></fieldset>
 *       <fieldset class="ds-facet" data-ds-facet-limit="4"><legend class="ds-facet__title">Owner</legend>
 *         <div class="ds-search ds-facet__search">(search)<input class="ds-input" type="search" aria-label="Search owners" placeholder="Search owners"></div>
 *         <div class="ds-facet__options"> ... </div>
 *         <p class="ds-facet__empty" hidden></p>
 *         <button class="ds-btn ds-btn--text ds-facet__more" type="button" hidden></button></fieldset>
 *       <fieldset class="ds-facet"><legend class="ds-facet__title">Storage (GB)</legend>
 *         <div class="ds-facet__range"><div class="ds-field">(min: data-ds-filter-bound="min")</div>
 *           <span class="ds-facet__dash" aria-hidden="true">–</span><div class="ds-field">(max)</div></div></fieldset>
 *     </section>
 *     <div class="ds-facets-layout__main">
 *       <button class="ds-btn ds-facets__toggle" type="button" aria-haspopup="dialog">(filter 20)Filters<span class="ds-badge ds-facets__badge" hidden></span></button>
 *       <div class="ds-facets__applied" hidden>(chips, Clear all: optional, shown while folded)</div>
 *       <p class="ds-facets__count">48 results</p> ... the list ...
 *     </div>
 *   </div>
 *   <dialog class="ds-sheet" id="facets-sheet" aria-labelledby="facets-sheet-title"> ... head ...
 *     <div class="ds-sheet__body" tabindex="0"></div>       (the panel moves in here)
 *     <div class="ds-sheet__foot"><button class="ds-btn ds-btn--filled ds-facets__results" type="button" data-ds-close>Show 48 results</button></div>
 *   </dialog>
 *
 * The layout: the panel --ds-facets-width (280px) wide beside the main
 * part, which keeps at least --ds-facets-main-min (50%) of the row. Where
 * the row cannot hold both, the panel wraps above the main part (without
 * the script, which keeps it usable); the script then writes data-folded
 * on the layout instead: the panel hides and .ds-facets__toggle shows
 * (with a badge of the applied filters), and a .ds-facets__applied in the
 * main part (optional) shows the applied chips, which stay removable
 * without the sheet; unfolded it hides (the panel has its own). A facet's rows stack at full
 * width, the count at the end; a checked row's label takes the label
 * weight, so the choice shows by more than the check. Rows the system hides
 * (beyond the limit, or not matching the facet's search) take the hidden
 * attribute. --ds-facet-max-height (264px) lets a long facet scroll on its
 * own instead (.ds-facet--scroll). In the sheet the panel's title hides
 * (the sheet has one).
 *
 * Options (src/core/options.css, docs/options.md), on the layout, the
 * panel or any ancestor:
 *   size, shape, touch  reach the rows, fields, buttons and chips, which
 *                       compute them; the gaps step 4px per size step
 *   density             the gaps between facets 2px per step; and the
 *                       rows' heights (4px per step, form.css)
 * The titles keep the label role; there is no tone: a filter shows no
 * meaning of its own.
 *
 * Forced colours: the rows, fields, buttons and chips keep their own
 * models; the hairlines between facets are borders (CanvasText's line).
 *
 * Hooks: --ds-facets-width (280px), --ds-facets-main-min (50%),
 * --ds-facets-gap (24px), --ds-facet-max-height (264px, .ds-facet--scroll).
 * The computed --_gap and --_spread are private: never set them.
 *
 * Progressive:
 * - scrollbar-color (a thin, quiet scrollbar in .ds-facet--scroll): without
 *   it the platform's scrollbar.
 */

@layer ds.components.facets {
  .ds-facets-layout {
    --_gap: max(var(--ds-space-3), calc(var(--ds-facets-gap, var(--ds-space-6)) + var(--ds-size-step, 0) * 4px + var(--ds-density, 0) * 2px));
    display: flex;
    flex-wrap: wrap;
    align-items: flex-start;
    gap: var(--_gap);
    min-width: 0;
  }

  .ds-facets-layout > .ds-facets {
    flex: 1 1 var(--ds-facets-width, 280px);
  }

  .ds-facets-layout__main {
    flex: 999 1 0;
    min-width: min(100%, var(--ds-facets-main-min, 50%));
  }

  .ds-facets-layout[data-folded] > .ds-facets {
    display: none;
  }

  .ds-facets__toggle {
    display: none;
  }

  .ds-facets-layout[data-folded] .ds-facets__toggle {
    display: inline-flex;
  }

  /* The applied row beside the list: only while the panel is folded away. */
  .ds-facets-layout:not([data-folded]) > .ds-facets-layout__main .ds-facets__applied {
    display: none;
  }

  .ds-facets {
    --_gap: max(var(--ds-space-2), calc(var(--ds-space-4) + var(--ds-size-step, 0) * 4px + var(--ds-density, 0) * 2px));
    display: grid;
    gap: var(--_gap);
    min-width: 0;
  }

  .ds-facets__head {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: var(--ds-space-2);
    min-width: 0;
  }

  .ds-facets__title {
    margin: 0;
    color: var(--ds-text);
    font: var(--ds-font-subtitle);
  }

  /* In the sheet its own title says it. */
  .ds-sheet__body > .ds-facets .ds-facets__title {
    display: none;
  }

  .ds-sheet__body > .ds-facets .ds-facets__head {
    justify-content: flex-end;
  }

  .ds-facets__applied {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--ds-space-2);
    min-width: 0;
  }

  .ds-facets__chips {
    min-width: 0;
  }

  .ds-facets__clear {
    flex: none;
  }

  .ds-facet__search {
    min-width: 0;
  }

  .ds-facets__count {
    margin: 0;
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
    font-variant-numeric: tabular-nums;
  }

  .ds-facets__count:empty {
    display: none;
  }

  .ds-facets__results {
    font-variant-numeric: tabular-nums;
  }

  /* One facet: a fieldset with its legend, on a hairline after the one before. */
  .ds-facet {
    display: grid;
    gap: var(--ds-space-2);
    min-width: 0;
    margin: 0;
    padding: 0;
    border: 0;
  }

  .ds-facet + .ds-facet {
    padding-block-start: var(--_gap);
    border-block-start: 1px solid var(--ds-line);
  }

  /* Floated, the legend is no rendered legend in the fieldset's border (the
     hairline would run beside it) but an item of the grid, which ignores
     the float itself. */
  .ds-facet__title {
    float: inline-start;
    margin: 0;
    padding: 0;
    color: var(--ds-text);
    font: var(--ds-font-label);
  }

  .ds-facet__options {
    display: grid;
    grid-auto-rows: max-content;
    min-width: 0;
  }

  /* A long facet that scrolls on its own: the padding keeps the halo of
     every box inside the box (half the halo beyond the box, as form.css
     computes both), and the negative margin keeps the rows in line. */
  .ds-facet--scroll .ds-facet__options {
    --_spread: max(var(--ds-space-2), calc((max(var(--ds-target-min, 0px), calc(var(--ds-check-target, 40px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px)) - var(--ds-check-size, 18px) - var(--ds-size-step, 0) * 2px) / 2));
    position: relative;
    max-height: var(--ds-facet-max-height, 264px);
    overflow-y: auto;
    margin-inline: calc(var(--_spread) * -1);
    padding-inline: var(--_spread);
    scrollbar-color: var(--ds-line-2) transparent;
  }

  .ds-facet__options > .ds-check {
    display: flex;
  }

  .ds-facet__options > .ds-check[hidden],
  .ds-facet__empty[hidden],
  .ds-facet__more[hidden],
  .ds-facets__applied[hidden],
  .ds-facets__badge[hidden] {
    display: none;
  }

  .ds-facet__options > .ds-check:has(> input:checked) {
    font-weight: var(--ds-weight-label);
  }

  .ds-facet__empty {
    margin: 0;
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
  }

  .ds-facet__more {
    justify-self: start;
  }

  .ds-facet__range {
    display: flex;
    align-items: flex-end;
    gap: var(--ds-space-2);
    min-width: 0;
  }

  .ds-facet__range > .ds-field {
    flex: 1 1 0;
    min-width: 0;
  }

  .ds-facet__dash {
    flex: none;
    /* On the fields' middle line: half a field's height above the bottom. */
    margin-block-end: max(0px, calc((max(var(--ds-target-min, 0px), calc(var(--ds-input-height, 40px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px)) - 1lh) / 2));
    color: var(--ds-text-2);
    font: var(--ds-font-body);
  }
}

/* ── components/sticky/sticky.css ── */
/*
 * Sticky: a head, a foot or a side that stays in view while its scroller
 * moves, with a raised edge (a hairline and a shadow towards the content)
 * once content passes under it.
 *
 *   <div class="x-list" style="overflow: auto">           any scroller (or the page)
 *     <header class="ds-sticky ds-sticky--head">Tickets, filters</header>
 *     ...rows...
 *     <footer class="ds-sticky ds-sticky--foot">12 selected, actions</footer>
 *   </div>
 *   <aside class="ds-sticky ds-sticky--side">table of contents</aside>
 *   <th class="ds-sticky ds-sticky--start">LAPTOP-0042</th>   (a sideways scroller's first column)
 *
 *   .ds-sticky--head    sticks to the top (block start)
 *   .ds-sticky--foot    sticks to the bottom (block end)
 *   .ds-sticky--start   sticks to the inline start of a sideways scroller
 *   .ds-sticky--end     sticks to the inline end
 *   .ds-sticky--side    a side column that stays at the top beside long
 *                       content: no fill and no edge (nothing passes
 *                       under it), it keeps its own height in a flex or
 *                       grid row (align-self: start)
 *   .ds-sticky--flat    never raises an edge
 *
 * The raised edge. A ::after layer under the content of the sticky box
 * (its stacking context) carries the hairline on the edge that faces the
 * content and the shadow beyond it, at opacity 0 until content passes
 * under the box:
 * - with scroll-driven animations it follows its scroller's scroll
 *   timeline: the head and the start column raise it over the first
 *   --ds-space-2 of scroll, the foot and the end column lower it over the
 *   last --ds-space-2;
 * - else (the fallback) attributes the page attaches through DS.dom show
 *   it, over --ds-dur-fast: data-scrolled from
 *   DS.dom.watchScrolled(scroller, head) on the head itself, or on its
 *   scroller when the head is a child of it (watchScrolled(scroller)); the
 *   data-ds-overflow-end, data-ds-overflow-start attributes of
 *   DS.dom.scrollEdges(scroller, { axis: 'block' }) (foot) or
 *   DS.dom.scrollEdges(scroller) (start and end) on any scroller around
 *   it.
 * Both read the scroller, not the box: a head that sits lower in its
 * scroller raises its edge from the first scrolled pixel, before it
 * sticks (put a head first in its scroller).
 *
 * The box is opaque (--ds-sticky-bg, the surface) and above the content
 * that scrolls under it (--ds-z-sticky). Keyboard focus that moves under a
 * head or a foot scrolls clear of it: give the scroller
 * scroll-padding-block (the head's height) where it holds focusable rows.
 *
 * Options: none read; the box is a frame for its content, whose controls
 * compute their own size, density and touch.
 *
 * Hooks: --ds-sticky-offset (0px: the distance from the scroller's edge,
 * a top bar's height inside a page that scrolls under one), --ds-sticky-bg
 * (--ds-surface), --ds-sticky-line (--ds-line), --ds-sticky-shadow
 * (--ds-elev-1).
 *
 * Forced colours: the shadow goes, the hairline stays (a border); the
 * box is Canvas.
 *
 * Print: nothing sticks on paper; the box prints where it stands, with no
 * edge.
 *
 * Progressive:
 * - scroll-driven animations (animation-timeline: scroll(), animation-range;
 *   the edge follows the scroller's scroll timeline): without them the
 *   data-scrolled and data-ds-overflow-* attributes of DS.dom show it over
 *   --ds-dur-fast, or none shows.
 */

@layer ds.components.sticky {
  .ds-sticky {
    position: sticky;
    z-index: var(--ds-z-sticky);
    background: var(--ds-sticky-bg, var(--ds-surface));
  }

  .ds-sticky--head {
    inset-block-start: var(--ds-sticky-offset, 0px);
  }

  .ds-sticky--foot {
    inset-block-end: var(--ds-sticky-offset, 0px);
  }

  .ds-sticky--start {
    inset-inline-start: var(--ds-sticky-offset, 0px);
  }

  .ds-sticky--end {
    inset-inline-end: var(--ds-sticky-offset, 0px);
  }

  .ds-sticky--side {
    inset-block-start: var(--ds-sticky-offset, 0px);
    align-self: start;
    background: none;
  }

  /* The edge: under the box's content, above its fill (the box is a
     stacking context: sticky with a z-index). Opacity only. At the weight
     of one class, so the placement rules below set the edge's side. */
  .ds-sticky:where(.ds-sticky--head, .ds-sticky--foot, .ds-sticky--start, .ds-sticky--end)::after {
    content: '';
    position: absolute;
    inset: 0;
    z-index: -1;
    border: 0 solid var(--ds-sticky-line, var(--ds-line));
    box-shadow: var(--ds-sticky-shadow, var(--ds-elev-1));
    opacity: 0;
    pointer-events: none;
    transition: opacity var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  .ds-sticky--head::after {
    border-block-end-width: 1px;
  }

  .ds-sticky--foot::after {
    border-block-start-width: 1px;
  }

  .ds-sticky--start::after {
    border-inline-end-width: 1px;
  }

  .ds-sticky--end::after {
    border-inline-start-width: 1px;
  }

  .ds-sticky--head[data-scrolled]::after,
  [data-scrolled] > .ds-sticky--head::after,
  [data-ds-overflow-end] .ds-sticky--foot::after,
  [data-ds-overflow-start] .ds-sticky--start::after,
  [data-ds-overflow-end] .ds-sticky--end::after {
    opacity: 1;
  }

  .ds-sticky--flat::after {
    display: none;
  }

  /* The scroller's own scroll timeline (the table's pinned columns do the
     same): the head and the start column raise their edge over the first
     --ds-space-2 of scroll, the foot and the end column lower theirs over
     the last. Both ends of ds-scroll-fade are named, so a scroller that
     does not scroll (an inactive timeline) leaves the edge at its own
     opacity 0. The shorthand first (it resets animation-timeline). */
  @supports (animation-timeline: scroll()) {
    .ds-sticky--head::after {
      animation: ds-scroll-fade linear both;
      animation-timeline: scroll(nearest block);
      animation-range: 0 var(--ds-space-2);
    }

    .ds-sticky--foot::after {
      animation: ds-scroll-fade linear both reverse;
      animation-timeline: scroll(nearest block);
      animation-range: calc(100% - var(--ds-space-2)) 100%;
    }

    .ds-sticky--start::after {
      animation: ds-scroll-fade linear both;
      animation-timeline: scroll(nearest inline);
      animation-range: 0 var(--ds-space-2);
    }

    .ds-sticky--end::after {
      animation: ds-scroll-fade linear both reverse;
      animation-timeline: scroll(nearest inline);
      animation-range: calc(100% - var(--ds-space-2)) 100%;
    }
  }

  @media (forced-colors: active) {
    .ds-sticky::after {
      box-shadow: none;
    }
  }

  /* Paper: nothing sticks, and nothing passes under the box. */
  @media print {
    .ds-sticky {
      position: static;
    }

    .ds-sticky::after {
      display: none;
    }
  }
}

/* ── components/timepicker/timepicker.css ── */
/*
 * Time picker: a segmented time field and a list of times in a picker
 * popover. The field is a .ds-datefield (type time) and the popover a
 * .ds-picker__popover; DS.timepicker (timepicker.js) builds both inside
 * the root and owns the list:
 *
 *   <div class="ds-picker" data-ds-timepicker data-ds-value="09:30" [data-ds-timepicker-step="15"]>
 *     <div class="ds-datefield" role="group" aria-labelledby="start-label">
 *       <button class="ds-btn ds-btn--quiet ds-btn--icon ds-datefield__toggle" type="button" aria-label="Choose time">(clock)</button>
 *     </div>
 *     (rendered:)
 *     <div class="ds-picker__popover ds-timepicker__popover" role="dialog" aria-modal="true" aria-label="Choose time" hidden>
 *       <div class="ds-picker__pane ds-picker__pane--scroll">
 *         <div class="ds-timepicker__list" role="listbox" tabindex="0" aria-activedescendant="...">
 *           <div class="ds-timepicker__option" role="option" id="..." aria-selected="true" [data-active]>9:30 AM</div> ...
 *
 * The list: one row per time, in the hour cycle of the locale; the chosen
 * one (aria-selected) takes the tint and the label weight; the active one
 * (data-active, keyboard and pointer alike) the state layer, and while the
 * list has keyboard focus an inset ring. A row picks on a click and closes
 * the popover, so it takes no ripple (the layer is the feedback).
 *
 * Options (src/core/options.css, docs/options.md), on the picker or any
 * ancestor; each is computed here:
 *   size      .ds-xs ... .ds-xl: a row 8px per step from
 *             --ds-timepicker-option-height (40px), the type of the size
 *   density   .ds-density-*: a row 4px per step
 *   shape     .ds-shape-*: multiplies a row's radius
 *   touch     .ds-touch: a row at least --ds-touch-target high
 *   tone      none
 *
 * Motion: the active row's layer comes in over --ds-dur-micro and goes at
 * once (a held arrow key leaves no trail); the popover is the picker's.
 *
 * Forced colours: the chosen row is SelectedItem / SelectedItemText, the
 * active one carries a Highlight ring (CanvasText on the chosen one).
 */

@layer ds.components.timepicker {
  .ds-timepicker__popover {
    padding: var(--ds-space-2);
  }

  .ds-timepicker__list {
    display: flex;
    flex-direction: column;
    gap: 2px;
    min-inline-size: 128px;
    outline: none;
  }

  .ds-timepicker__option {
    --_h: calc(var(--ds-timepicker-option-height, 40px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px);
    --_box: max(var(--ds-target-min, 0px), var(--_h));
    position: relative;
    isolation: isolate;
    display: flex;
    flex: none;
    align-items: center;
    min-block-size: var(--_box);
    padding: 0 var(--ds-space-4);
    border-radius: min(calc(var(--ds-radius-sm) * var(--ds-shape, 1)), calc(var(--_box) / 2));
    color: var(--ds-text);
    font: var(--ds-size-font, var(--ds-font-body));
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
    cursor: pointer;
    -webkit-tap-highlight-color: transparent;
    outline-offset: 0;
    transition:
      background-color var(--ds-dur-fast) var(--ds-ease-in-out),
      outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  /* The active row's layer: in over --ds-dur-micro, out at once. */
  .ds-timepicker__option::before {
    content: '';
    position: absolute;
    inset: 0;
    z-index: -1;
    border-radius: inherit;
    background: currentColor;
    opacity: 0;
    pointer-events: none;
    transition: opacity 0ms var(--ds-ease-in-out);
  }

  .ds-timepicker__option[data-active]::before {
    opacity: var(--ds-state-hover);
    transition-duration: var(--ds-dur-micro);
  }

  .ds-timepicker__option[aria-selected="true"] {
    background: var(--ds-accent);
    color: var(--ds-on-accent);
    font-weight: var(--ds-weight-label);
  }

  /* Keyboard focus on the list: the active row carries the ring. */
  .ds-timepicker__list > .ds-timepicker__option[data-active] {
    outline-offset: 0;
    transition:
      background-color var(--ds-dur-fast) var(--ds-ease-in-out),
      outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-timepicker__list:focus-visible > .ds-timepicker__option[data-active] {
    outline: var(--ds-focus-outline);
    outline-offset: calc(-1 * var(--ds-focus-width));
  }

  @media (forced-colors: active) {
    .ds-timepicker__option[data-active] {
      outline: 2px solid Highlight;
      outline-offset: -2px;
    }

    .ds-timepicker__option[aria-selected="true"] {
      forced-color-adjust: none;
      background: SelectedItem;
      color: SelectedItemText;
    }

    .ds-timepicker__option[aria-selected="true"][data-active] {
      outline-color: CanvasText;
    }
  }
}

/* ── components/unsaved/unsaved.css ── */
/*
 * Unsaved-changes guard (3.0): dirty tracking of a form, wired to the Save
 * bar, the browser's question before the page unloads, Ctrl+S (Command+S
 * on Apple systems) and a guarded in-app navigation. DS.unsaved
 * (unsaved.js) does the work; the look is the Save bar's and Form's.
 *
 *   <form class="ds-form" data-ds-unsaved data-ds-unsaved-savebar="#device-bar">
 *     <div class="ds-field">           (takes Form's .ds-field--changed while its control differs)
 *       <label class="ds-field__label" for="name">Name <span class="ds-field__changed ds-sr">(changed)</span></label>
 *       <input class="ds-input" id="name" name="name" value="LAPTOP-0042"></div> ... </form>
 *   <div class="ds-savebar" id="device-bar">
 *     <div class="ds-savebar__bar ds-presence" role="region" aria-label="Unsaved changes" hidden>
 *       <p class="ds-savebar__text ds-unsaved__count" data-ds-unsaved-count></p>        (written: "2 unsaved changes")
 *       <div class="ds-savebar__actions">
 *         <button class="ds-btn ds-btn--text" type="button" data-ds-unsaved-discard>Discard</button>
 *         <button class="ds-btn ds-btn--filled" type="button" data-ds-unsaved-save>(Button's faces)</button>
 *   <nav data-ds-unsaved-link> (links that ask before they leave unsaved changes) </nav>
 *
 * The count (.ds-unsaved__count, on the element of data-ds-unsaved-count)
 * keeps its width while it changes (tabular figures).
 *
 * Options (src/core/options.css, docs/options.md): the guard draws
 * nothing of its own. Size, density, shape and touch are the Save bar's,
 * Form's and Button's, each computed in their rules; tone: none (a changed
 * field shows a dot and the word "(changed)", never colour alone).
 *
 * Hooks: none; the changed dot is --ds-field-changed-color (Form).
 *
 * Motion: the Save bar's (.ds-presence: rises on the spring, leaves
 * faster) and Form's changed dot (in on --ds-dur-fast, out on
 * --ds-dur-instant); a save runs the button's busy and done faces
 * (DS.motion.busy).
 *
 * Forced colours: the parts are the Save bar's, Form's and Button's.
 */

@layer ds.components.unsaved {
  .ds-unsaved__count {
    font-variant-numeric: tabular-nums;
  }
}

/* ── components/datepicker/datepicker.css ── */
/*
 * Date picker: a segmented date field and a calendar in a picker popover
 * (the WAI-ARIA date picker dialog); with type datetime the field takes the
 * time too, the popover a list of times beside the calendar, and the field
 * may name the zone of its wall time. DS.datepicker (datepicker.js) builds
 * the popover inside the root: the field is a .ds-datefield, the popover a
 * .ds-picker__popover with a .ds-calendar (and a .ds-timepicker__list).
 *
 *   <span class="ds-field__label" id="due-label">Due date</span>
 *   <div class="ds-picker" data-ds-datepicker data-ds-value="2026-11-04" [data-ds-datepicker-type="datetime"]>
 *     <div class="ds-datefield" role="group" aria-labelledby="due-label">
 *       <button class="ds-btn ds-btn--quiet ds-btn--icon ds-datefield__toggle" type="button" aria-label="Choose date">(calendar)</button>
 *     </div>
 *     (rendered:)
 *     <div class="ds-picker__popover" role="dialog" aria-modal="true" aria-label="Choose date" hidden>
 *       <div class="ds-picker__panes">
 *         <div class="ds-picker__pane"><div class="ds-calendar">...</div></div>
 *         [<div class="ds-picker__pane ds-datepicker__times"><div class="ds-timepicker__list">...</div></div>]
 *       </div>
 *       <div class="ds-picker__foot">(Today or Now) <span class="ds-picker__spacer"></span> (Clear)</div>
 *     </div>
 *   </div>
 *
 * The list of times is as tall as the calendar beside it and scrolls inside;
 * on a phone (600px or less) it goes under the calendar, 200px high.
 *
 * Options: those of the field, the calendar and the popover, each in its
 * own component (size, density, shape, touch); the date picker adds none.
 *
 * Motion: the popover's (it grows from the button); a turned month slides.
 *
 * Forced colours: the parts' own.
 *
 * Progressive:
 * - scrollbar-color and scrollbar-width (a thin scrollbar on the list of
 *   times): without them the platform scrollbar shows.
 */

@layer ds.components.datepicker {
  /* The times beside the calendar: as tall as it, scrolling inside. */
  .ds-datepicker__times {
    position: relative;
    align-self: stretch;
    inline-size: 128px;
    border-inline-start: 1px solid var(--ds-line);
  }

  .ds-datepicker__times > .ds-timepicker__list {
    position: absolute;
    inset: 0;
    padding-inline-start: var(--ds-space-2);
    overflow-y: auto;
    overscroll-behavior: contain;
    scrollbar-width: thin;
    scrollbar-color: var(--ds-line-2) transparent;
  }

  @media (max-width: 600px) {
    .ds-datepicker__times {
      inline-size: auto;
      border-inline-start: 0;
    }

    .ds-datepicker__times > .ds-timepicker__list {
      position: static;
      max-block-size: 200px;
      padding-inline-start: 0;
    }
  }
}

/* ── components/print/print.css ── */
/*
 * Print: what goes on paper and how it breaks into pages. Every component
 * already prints itself sensibly (the frame's bars and drawer stay off,
 * scrollers unroll, tables repeat their header); these classes are for
 * the page's own content.
 *
 *   <p class="ds-print-only">Printed on 2026-11-04 by Ada Lovelace</p>
 *   <div class="ds-cluster ds-print-hide">screen-only actions</div>
 *   <section class="ds-print-break-before">starts a new sheet</section>
 *   <figure class="ds-print-avoid">kept on one sheet</figure>
 *   <div class="ds-print-exact">a chart whose fills carry meaning</div>
 *   <div class="ds-print-urls">links print their address after them</div>
 *
 *   <article class="ds-print-page">                  a printable document (a report,
 *     <header>...</header> <table class="ds-table">   an invoice): a sheet on screen,
 *     ...                                             the paper's full width in print
 *   </article>
 *
 *   .ds-print-only     hidden on screen, shown on paper
 *   .ds-print-hide     shown on screen, hidden on paper
 *   .ds-print-break-before, .ds-print-break-after   a new sheet before or after it
 *   .ds-print-avoid    never split across two sheets (a figure, a card, a
 *                      total with its last rows)
 *   .ds-print-exact    prints its fills and colours as shown (the browser
 *                      drops backgrounds to save ink otherwise)
 *   .ds-print-urls     every http(s) link inside prints its address after
 *                      its text
 *   .ds-print-page     on screen a sheet of paper (--ds-print-page-width,
 *                      the surface, a soft shadow); in print the paper's
 *                      width, no frame, the light scheme of the theme
 *                      (light-dark() roles), headings kept with what
 *                      follows, figures and code whole, no line alone at
 *                      the top or foot of a sheet
 *
 * Hiding is display: none with !important, as the hidden attribute is.
 *
 * Options: shape multiplies the sheet's radius on screen; size, density,
 * tone and touch are its content's own.
 *
 * Hooks: --ds-print-page-width (210mm, an A4 sheet), --ds-print-page-pad
 * (--ds-space-10, the sheet's margin on screen; paper keeps the
 * browser's page margins).
 *
 * Forced colours: the sheet keeps a transparent outline that becomes its
 * edge where the shadow goes.
 */

@layer ds.components.print {
  .ds-print-page {
    box-sizing: border-box;
    max-inline-size: var(--ds-print-page-width, 210mm);
    margin-inline: auto;
    padding: var(--ds-print-page-pad, var(--ds-space-10));
    border-radius: calc(var(--ds-radius-card) * var(--ds-shape, 1));
    background: var(--ds-surface);
    color: var(--ds-text);
    box-shadow: var(--ds-elev-1);
    orphans: 3;
    widows: 3;
  }

  /* A sheet on a phone keeps a usable margin. */
  @container (width < 600px) {
    .ds-print-page {
      padding: var(--ds-print-page-pad, var(--ds-space-5));
    }
  }

  @media not print {
    .ds-print-only {
      display: none !important;
    }
  }

  @media (forced-colors: active) {
    .ds-print-page {
      outline: 1px solid transparent;
    }
  }

  @media print {
    .ds-print-hide {
      display: none !important;
    }

    .ds-print-break-before {
      break-before: page;
    }

    .ds-print-break-after {
      break-after: page;
    }

    .ds-print-avoid {
      break-inside: avoid;
    }

    .ds-print-exact {
      print-color-adjust: exact;
    }

    /* The address runs inline after the text, even where a component lays
       the link's ::after out as a box (the stretched link of an
       interactive card): paper has no click target to stretch. */
    .ds-print-urls a[href^="http"]::after {
      content: " (" attr(href) ")";
      position: static;
      inset: auto;
      display: inline;
      border-radius: 0;
      background: none;
      overflow-wrap: anywhere;
    }

    /* Paper: the full width of the sheet, no frame; the theme's light
       scheme, since paper is light whatever the screen shows. */
    .ds-print-page {
      max-inline-size: none;
      margin: 0;
      padding: 0;
      border-radius: 0;
      box-shadow: none;
      color-scheme: light;
    }

    .ds-print-page :is(h1, h2, h3, h4, h5, h6) {
      break-after: avoid;
      break-inside: avoid;
    }

    .ds-print-page :is(figure, img, pre, blockquote) {
      break-inside: avoid;
    }
  }
}

/* ── components/query/query.css ── */
/*
 * Query input (3.0): a search field whose filters become tokens
 * ("status:open", "priority:>2"), with suggestions for keys, operators and
 * values, saved queries and keyboard editing of the tokens. DS.query
 * (query.js) parses, suggests and writes the tokens; the field box, the
 * list and the tokens are Combobox's several-values box, its list and
 * Chips' input chips, so a query lines up with every field.
 *
 *   <div class="ds-query" data-ds-query data-ds-query-store="tickets" data-ds-query-name="q" data-ds-query-keys='[...]'>
 *     <label class="ds-field__label" for="q">Filter tickets</label>
 *     <div class="ds-query__row">
 *       <div class="ds-combo ds-combo--multi ds-query__box">
 *         <span class="ds-query__icon" aria-hidden="true">(search 20)</span>
 *         <span class="ds-query__tokens">                       (written by DS.query)
 *           <button class="ds-chip ds-chip--input ds-query__token" type="button" tabindex="-1">
 *             <span class="ds-chip__body"><span class="ds-chip__label"><span class="ds-sr">Remove filter Status is open</span>
 *               <span class="ds-query__key">Status:</span><span class="ds-query__value">open</span></span>
 *               (close 18 .ds-chip__trailing)</span></button></span>
 *         <input class="ds-input ds-combo__input ds-query__input" id="q">
 *         <button class="ds-combo__clear" type="button" hidden>(close 20)</button>
 *         <div class="ds-combo__popup" hidden>
 *           <div class="ds-combo__list"></div><p class="ds-combo__status" role="status"></p></div></div>
 *       <button class="ds-btn ds-btn--icon ds-query__save" type="button">(bookmark 20)</button>
 *     </div>
 *   </div>
 *
 * The tokens' run (.ds-query__tokens) takes no box of its own (display:
 * contents): the tokens wrap with the typing field in Combobox's box,
 * which gets its room around chips here too. A token reads key, operator
 * and value: the key at the label weight ("Status:" for "is"), any other
 * operator a mark with room on both sides ("≠", ">", "≥", "<", "≤"), the
 * value regular; a long
 * value ends in an ellipsis (Chips' --ds-chip-max-width). An invalid
 * token is an input chip in the error tone (.ds-tone-error on the chip)
 * with the alert icon and the reason in its name, never colour alone. The
 * search glyph leads the box; the save button sits beside it and lines up
 * with its first row.
 *
 * Options (src/core/options.css, docs/options.md), on the query or any
 * ancestor; each is computed where it is used:
 *   size      .ds-xs ... .ds-xl: the box, the tokens, the list and the
 *             save button step themselves (Combobox, Chips, Button); the
 *             glyph's room steps 4px per size step here
 *   density   .ds-density-*: the box, the tokens and the options (Combobox,
 *             Chips); the room before the glyph and between the box and the
 *             save button stay
 *   shape     .ds-shape-*: the box, the tokens, the list and the button
 *   touch     .ds-touch: box, tokens, options and the save button at least
 *             --ds-touch-target (48px)
 *   tone      none of its own: an invalid token takes the error tone with
 *             its icon and words
 *
 * Hooks: none of its own; the box reads Form's and Combobox's
 * (--ds-input-*, --ds-combo-*), the tokens Chips' (--ds-chip-*).
 *
 * Motion: the list's (Combobox: it grows out of the box on the spring,
 * leaves with a fade); a token comes and goes at once, its press is the
 * chip's.
 *
 * Forced colours: the box, list, tokens and button are their components';
 * the glyph takes CanvasText (global.css).
 */

@layer ds.components.query {
  .ds-query {
    display: grid;
    gap: var(--ds-space-1);
    min-width: 0;
  }

  .ds-query__row {
    display: flex;
    align-items: flex-start;
    gap: var(--ds-space-2);
    min-width: 0;
  }

  .ds-query__box {
    flex: 1 1 auto;
    min-width: 0;
  }

  /* The tokens wrap with the typing field as the box's own items. */
  .ds-query__tokens {
    display: contents;
  }

  /* Room around the chips, as Combobox gives its own chips. */
  .ds-query__box:has(> .ds-query__tokens > .ds-chip) {
    padding-block: calc(var(--ds-space-1) - 1px);
  }

  /* With tokens, the example query of the placeholder would read as one.
     From the run's side (not as a child of a box that :has() a chip:
     Chromium restyles every ancestor of each DOM change anywhere on the
     page for that form, and lays the whole page out). */
  .ds-query__box > .ds-query__tokens:has(> .ds-chip) ~ .ds-query__input::placeholder {
    color: transparent;
  }

  .ds-query__icon {
    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    inline-size: calc(var(--ds-space-8) + var(--ds-size-step, 0) * 4px);
    margin-inline-end: calc(-1 * var(--ds-space-1));
    color: var(--ds-text-2);
    pointer-events: none;
  }

  .ds-query__key {
    font-weight: var(--ds-weight-label);
  }

  .ds-query__op {
    padding-inline: var(--ds-space-1);
  }

  /* "Status: open": the colon is the key's, a space follows it. */
  .ds-query__key + .ds-query__value {
    margin-inline-start: var(--ds-space-1);
  }

  .ds-query__value {
    overflow-wrap: anywhere;
  }

  .ds-query__save {
    flex: none;
  }
}

/* ── components/views/views.css ── */
/*
 * Saved views: named sets of filters, a sort and columns, picked from a
 * menu; the built-in ones of the page, the user's own (remembered), a
 * default, and a link that carries the current one (js/views.js):
 *
 *   <div class="ds-views" data-ds-views data-ds-views-key="devices" data-ds-views-url="sync">
 *     <button class="ds-btn ds-views__trigger" type="button" aria-haspopup="menu" aria-expanded="false" data-ds-open="#views-menu">
 *       (layers 20)<span class="ds-sr">View: </span><span class="ds-views__name">All devices</span>
 *       <span class="ds-views__edited" hidden>Edited</span>(chevronDown 20 .ds-views__chevron)</button>
 *     <button class="ds-btn ds-btn--text ds-views__save" type="button" hidden>Save view</button>
 *     <div class="ds-menu" id="views-menu" role="menu" aria-label="Views" hidden>
 *       <div class="ds-views__list" role="group" aria-label="Views">
 *         <button class="ds-menu__item" role="menuitemradio" aria-checked="false" type="button" data-ds-view="all" data-ds-view-default>
 *           (check 20 .ds-menu__check)<span class="ds-menu__label">All devices</span></button>
 *         <button ... data-ds-view="offline" data-ds-view-state="status=offline&sort=-seen"> ... Offline</button>
 *         (the user's views: rendered by the system after them)
 *       </div>
 *       <div class="ds-menu__divider" role="separator"></div>
 *       <button class="ds-menu__item" role="menuitem" type="button" data-ds-views-action="save">(save 20)<span class="ds-menu__label">Save changes</span></button>
 *       ... create, rename, default, share ...
 *       <button class="ds-menu__item ds-menu__item--danger" role="menuitem" type="button" data-ds-views-action="delete">(trash 20)<span class="ds-menu__label">Delete view</span></button>
 *     </div>
 *   </div>
 *
 * The trigger names the current view (one line, an ellipsis after
 * --ds-views-name-max, 240px) and, while the page's state differs from
 * it, the word "Edited" (.ds-views__edited, written by the system): never
 * a dot alone. Its chevron turns while the menu is open. .ds-views__save
 * shows beside it while edited. In the menu the current view carries the
 * check (menuitemradio), the default view the star and the word
 * "Default" (.ds-views__default, at the row's end); actions that do not
 * apply are aria-disabled.
 *
 * Options (src/core/options.css, docs/options.md), on .ds-views or any
 * ancestor: size, density, shape and touch reach the buttons and the menu,
 * which compute them; the gap steps 4px per size step. There is no tone: a
 * view shows no meaning of its own; deleting is the menu's danger item and
 * the confirm dialog's error button (D10).
 *
 * Forced colours: the words are text, the buttons and the menu keep their
 * own models; nothing of its own.
 *
 * Hooks: --ds-views-name-max (240px). The computed --_gap is private.
 *
 * No progressive feature.
 */

@layer ds.components.views {
  .ds-views {
    --_gap: max(var(--ds-space-1), calc(var(--ds-space-2) + var(--ds-size-step, 0) * 4px));
    display: inline-flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--_gap);
    min-width: 0;
    max-width: 100%;
  }

  .ds-views__trigger {
    min-width: 0;
    max-width: 100%;
    white-space: nowrap;
  }

  .ds-views__name {
    min-width: 0;
    max-width: var(--ds-views-name-max, 240px);
    overflow: hidden;
    text-overflow: ellipsis;
  }

  /* A word, quieter than the name: the state differs from the saved view. */
  .ds-views__edited {
    flex: none;
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
    font-style: italic;
  }

  .ds-views__edited[hidden],
  .ds-views__save[hidden] {
    display: none;
  }

  .ds-views__chevron {
    flex: none;
    transition: rotate var(--ds-dur-medium) var(--ds-ease-spatial);
  }

  .ds-views__trigger[aria-expanded="true"] .ds-views__chevron {
    rotate: 180deg;
  }

  .ds-views__list {
    display: grid;
  }

  .ds-views__default {
    display: inline-flex;
    align-items: center;
    gap: var(--ds-space-1);
  }
}

/* ── components/datagrid/datagrid.css ── */
/*
 * Data grid (3.0): the parts js/datagrid.js (DS.datagrid) renders into a table.
 * The table's look stays table.css's (heights, hairlines, options, sticky
 * rows, pinned columns, selection, expandable rows, stacked rows); this
 * sheet adds only what the grid's options bring, so a plain table stays
 * plain and a grid without options looks like the table it was.
 *
 *   <div class="ds-table-wrap">
 *     <table class="ds-table ds-datagrid" data-ds-datagrid data-ds-config='{"select":"multiple","focus":"cell"}'>
 *       <thead><tr><th scope="col" data-ds-datagrid-col="name" data-ds-datagrid-sort>Device</th> ...</tr></thead>
 *       <tbody><tr data-ds-key="d1"><td>LAPTOP-0100</td> ...</tr></tbody>
 *     </table>
 *   </div>
 *
 * Parts the module writes (never by hand):
 *   .ds-datagrid__select    the selection column: a checkbox per row, the
 *                       header's select-all box (mixed for some)
 *   .ds-datagrid__toggle    the details column (a .ds-table__toggle per row)
 *   .ds-datagrid__actions   the header of the row actions column
 *   .ds-datagrid__grip      a .ds-grip button in a header cell that moves the
 *                       column (DS.dnd: pointer and keys); shown with the
 *                       cell's hover or focus, always where nothing hovers
 *   .ds-datagrid__resize    the separator at a header cell's end: drag, or
 *                       the arrow keys; Enter or a double click puts the
 *                       width back. A line in --ds-line-2 shows on hover
 *                       and focus, --ds-primary while it is dragged
 *   .ds-datagrid__rank      the place of a column in a multi-column sort
 *   .ds-datagrid__tree      a tree or group label: indented by its level
 *                       (--ds-datagrid-level, written per row) times
 *                       --ds-datagrid-indent, after its twist
 *   .ds-datagrid__twist     the toggle of a tree row or a row group, a
 *                       .ds-table__toggle whose .ds-datagrid__chevron turns
 *                       90deg on the spring when it opens
 *   .ds-datagrid__twist-room  the twist's room on a row without children
 *   .ds-datagrid__label, .ds-datagrid__count  a tree or group label and a group's
 *                       row count
 *   .ds-datagrid__group     a row group's head row: the label type on
 *                       --ds-datagrid-group-bg, its subtotals in the columns
 *   .ds-datagrid__state     the one row of the empty, no-results, loading and
 *                       error states (.ds-empty, .ds-loading inside)
 *   .ds-datagrid__editable  a cell that edits (Enter, F2, a double click)
 *   .ds-datagrid__editing   the cell while it edits, around .ds-datagrid__field
 *                       (the .ds-input.ds-datagrid__editor and, when the
 *                       value is refused, .ds-datagrid__message: an icon and
 *                       the words below the field)
 *   .ds-datagrid__every     the link button "Select all N" in the selection bar
 *   .ds-datagrid__point     the point a row's context menu opens at (fixed,
 *                       --ds-datagrid-point-x and -y, written per open)
 *   data-ds-datagrid-layout="fixed"  fixed columns (after a resize, and for
 *                       windowed rows): table-layout: fixed at
 *                       --ds-datagrid-width (written: the columns it shows);
 *                       cells end in an ellipsis
 *   data-ds-datagrid-dir    the direction of every sorted column, so the
 *                       arrow of a secondary sort turns as well
 *   data-ds-datagrid-resizing  the separator being dragged
 *
 * Keys (focus: 'cell' or 'row'): the focused cell or row shows the ring,
 * inset (it rests on the edge and snaps inward on --ds-dur-fast) and the
 * focus layer at once, as a row link does.
 *
 * Options (src/core/options.css): the grid's rows and head are the
 * table's, so size, density, touch and shape act through table.css. Here:
 *   touch     .ds-touch: the grip widens to a third of --ds-target-min
 *             and the separator's target to a quarter of it
 *   shape     .ds-shape-*: multiplies the radius of the grip and of the
 *             editor's message
 *   density   the group row and the state row follow the table's cells
 *   not type, no tone: the grid shows no meaning of its own (a status in
 *             a cell does)
 *
 * Hooks: --ds-datagrid-indent (--ds-space-6, a tree level's indent),
 * --ds-datagrid-group-bg (--ds-surface-low, a group's head row).
 *
 * Runtime properties (written by js/datagrid.js): --ds-datagrid-width,
 * --ds-datagrid-level, --ds-datagrid-point-x, --ds-datagrid-point-y.
 *
 * Forced colours: the separator's line is a border (CanvasText, Highlight
 * while dragged), the group row's tint goes (its label type and count
 * stay), the message keeps an edge; rings are outlines.
 * Print: no grip, separator or point; the editor prints its value.
 */

@layer ds.components.datagrid {
  /* Header cells hold the grip and the separator. A sticky or pinned
     header cell is positioned already (table.css): only the others become
     their box. */
  .ds-datagrid > thead > tr > th:not(:where(.ds-table--sticky-head > thead th, .ds-table-wrap--fill > .ds-table > thead th, .ds-table--pin-first > thead th:first-child, .ds-table--pin-last > thead th:last-child)) {
    position: relative;
  }

  /* Fixed columns (a resize, windowed rows): the widths the module wrote,
     the table as wide as the columns it shows. */
  .ds-datagrid[data-ds-datagrid-layout="fixed"] {
    table-layout: fixed;
    width: var(--ds-datagrid-width, 100%);
  }

  .ds-datagrid[data-ds-datagrid-layout="fixed"]:not(.ds-table--stack, .ds-table--stack-wide) > thead > tr > th {
    overflow-x: clip;
  }

  .ds-datagrid[data-ds-datagrid-layout="fixed"]:not(.ds-table--stack, .ds-table--stack-wide) > tbody > tr:not(.ds-table__detail, .ds-datagrid__state) > td:not(.ds-datagrid__editing) {
    overflow-x: clip;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  /* The system columns: as narrow as their control. */
  .ds-datagrid :is(th, td):is(.ds-datagrid__select, .ds-datagrid__toggle) {
    width: 1%;
    padding-inline-end: 0;
  }

  .ds-datagrid th.ds-datagrid__actions {
    width: 1%;
  }

  /* ── Sort rank ─────────────────────────────────── */

  .ds-datagrid__rank {
    min-inline-size: var(--ds-space-3);
    color: var(--ds-text-2);
    font: var(--ds-font-caption);
    font-variant-numeric: tabular-nums;
  }

  /* The arrow of every sorted column turns for descending (aria-sort marks
     only the first; table.css turns that one). */
  .ds-datagrid th[data-ds-datagrid-dir="descending"] .ds-table__sort-arrow {
    rotate: 180deg;
  }

  /* ── The grip ──────────────────────────────────── */

  /* In the cell's start padding, so the label keeps its line; as tall as
     the head. */
  .ds-datagrid__grip {
    --_w: max(var(--ds-space-4), calc(var(--ds-target-min, 0px) / 3));
    position: absolute;
    inset-block: 0;
    inset-inline-start: 0;
    z-index: var(--ds-z-raised);
    display: flex;
    align-items: center;
    justify-content: center;
    inline-size: var(--_w);
    padding: 0;
    border: 0;
    border-radius: calc(var(--ds-radius-xs) * var(--ds-shape, 1));
    background: transparent;
    color: var(--ds-text-2);
    opacity: 0;
    outline-offset: 0;
    transition:
      opacity var(--ds-dur-fast) var(--ds-ease-in-out),
      color var(--ds-dur-fast) var(--ds-ease-in-out),
      outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  /* A touch target (--ds-target-min, from .ds-touch on the table or any
     container) widens the grip past the cell's start padding: the padding
     grows with it, so the label stays clear. The table's side padding is
     computed again here (table.css: the hook, 2px per density step, the
     card's padding on a first cell, three quarters on phones, half at
     320px). */
  .ds-datagrid > thead > tr > th:has(> .ds-datagrid__grip) {
    padding-inline-start: max(calc(var(--ds-table-padding, var(--ds-space-4)) + var(--ds-density, 0) * 2px), calc(var(--ds-target-min, 0px) / 3));
  }

  .ds-card .ds-table-wrap .ds-datagrid > thead > tr > th:first-child:has(> .ds-datagrid__grip) {
    padding-inline-start: max(var(--ds-card-pad), calc(var(--ds-target-min, 0px) / 3));
  }

  @media (max-width: 600px) {
    .ds-datagrid > thead > tr > th:has(> .ds-datagrid__grip) {
      padding-inline-start: max(var(--ds-space-1), calc(var(--ds-table-padding, var(--ds-space-4)) * 0.75 + var(--ds-density, 0) * 2px), calc(var(--ds-target-min, 0px) / 3));
    }
  }

  @media (max-width: 359px) {
    .ds-datagrid > thead > tr > th:has(> .ds-datagrid__grip) {
      padding-inline-start: max(var(--ds-space-1), calc(var(--ds-table-padding, var(--ds-space-4)) * 0.5 + var(--ds-density, 0) * 2px), calc(var(--ds-target-min, 0px) / 3));
    }
  }

  .ds-datagrid th:focus-within > .ds-datagrid__grip,
  .ds-datagrid__grip[data-ds-dragging] {
    opacity: 1;
  }

  @media (hover: hover) {
    .ds-datagrid th:hover > .ds-datagrid__grip {
      opacity: 1;
    }

    .ds-datagrid__grip:hover {
      color: var(--ds-text);
    }
  }

  @media (hover: none) {
    .ds-datagrid__grip {
      opacity: 1;
    }
  }

  .ds-datagrid__grip:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: calc(-1 * var(--ds-focus-width));
  }

  /* The header cell being moved by its grip keeps an opaque base. */
  .ds-datagrid > thead th[data-ds-dragging] {
    background-color: var(--ds-table-sticky-bg, var(--ds-surface));
  }

  /* ── The separator ─────────────────────────────── */

  .ds-datagrid__resize {
    --_w: max(var(--ds-space-2), calc(var(--ds-target-min, 0px) / 4));
    position: absolute;
    inset-block: 0;
    inset-inline-end: 0;
    z-index: var(--ds-z-raised);
    inline-size: var(--_w);
    cursor: col-resize;
    touch-action: none;
    outline-offset: 0;
    transition: outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  /* The line: a border, so it stays in forced colours. */
  .ds-datagrid__resize::before {
    content: '';
    position: absolute;
    inset-block: var(--ds-space-2);
    inset-inline-end: 0;
    border-inline-end: 2px solid var(--ds-line-2);
    opacity: 0;
    transition: opacity var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  @media (hover: hover) {
    .ds-datagrid__resize:hover::before {
      opacity: 1;
    }
  }

  .ds-datagrid__resize:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: calc(-1 * var(--ds-focus-width));
  }

  .ds-datagrid__resize:focus-visible::before {
    opacity: 1;
    transition-duration: 0s;
  }

  .ds-datagrid__resize[data-ds-datagrid-resizing]::before {
    border-inline-end-color: var(--ds-primary);
    opacity: 1;
  }

  /* ── Focus: cells and rows of the APG grid ─────── */

  .ds-datagrid > :is(thead, tbody, tfoot) > tr > :is(td, th)[tabindex] {
    outline-offset: 0;
    transition: outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  /* A body cell keeps the table's layer pace (its row sets it, table.css). */
  .ds-datagrid > tbody > tr > :is(td, th)[tabindex] {
    transition:
      background-color var(--ds-table-row-pace) var(--ds-ease-in-out),
      outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-datagrid > :is(thead, tbody, tfoot) > tr > :is(td, th)[tabindex]:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: calc(-1 * var(--ds-focus-width));
  }

  /* The focus layer, at once: a body cell lays it over its row's colour
     (a pinned cell over its opaque base, through table.css). */
  .ds-datagrid > tbody > tr > :is(td, th)[tabindex]:focus-visible {
    --ds-table-row-layer: color-mix(in srgb, currentColor calc(var(--ds-state-focus) * 100%), transparent);
    --ds-table-row-pace: 0s;
  }

  .ds-datagrid > :is(thead, tfoot) > tr > :is(td, th)[tabindex]:focus-visible {
    background-image:
      linear-gradient(color-mix(in srgb, currentColor calc(var(--ds-state-focus) * 100%), transparent), color-mix(in srgb, currentColor calc(var(--ds-state-focus) * 100%), transparent)),
      linear-gradient(var(--ds-table-sticky-bg, var(--ds-surface)), var(--ds-table-sticky-bg, var(--ds-surface)));
  }

  .ds-datagrid > tbody > tr[tabindex] {
    outline-offset: 0;
    transition:
      background-color var(--ds-dur-fast) var(--ds-ease-in-out),
      outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-datagrid > tbody > tr[tabindex]:focus-visible {
    --ds-table-row-layer: color-mix(in srgb, currentColor calc(var(--ds-state-focus) * 100%), transparent);
    --ds-table-row-pace: 0s;
    outline: var(--ds-focus-outline);
    outline-offset: calc(-1 * var(--ds-focus-width));
  }

  /* ── Tree rows and row groups ──────────────────── */

  .ds-datagrid__tree {
    display: inline-flex;
    align-items: center;
    gap: var(--ds-space-2);
    padding-inline-start: calc(var(--ds-datagrid-level, 0) * var(--ds-datagrid-indent, var(--ds-space-6)));
    vertical-align: top;
  }

  /* The twist hangs out of the text line as the table's toggle does; a
     row without children keeps its room, so the labels of a level line up. */
  .ds-datagrid__twist-room {
    flex: none;
    inline-size: var(--ds-space-5);
  }

  .ds-datagrid .ds-datagrid__twist {
    flex: none;
    margin-inline: calc((var(--ds-space-5) - max(var(--ds-target-min, 0px), calc(var(--ds-btn-icon-size, 40px) + var(--ds-size-step, 0) * 8px))) / 2);
  }

  .ds-datagrid__chevron {
    transition: rotate var(--ds-dur-medium) var(--ds-ease-spatial);
  }

  .ds-datagrid__twist[aria-expanded="true"] > .ds-datagrid__chevron {
    rotate: 90deg;
  }

  .ds-datagrid__label {
    min-inline-size: 0;
  }

  .ds-datagrid__count {
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
    font-variant-numeric: tabular-nums;
  }

  .ds-datagrid > tbody > tr.ds-datagrid__group {
    --ds-table-row-tint: var(--ds-datagrid-group-bg, var(--ds-surface-low));
    background-color: var(--ds-datagrid-group-bg, var(--ds-surface-low));
  }

  /* A group's label is a row header (th): the last body row leaves the
     line above the summary row to it, as its td cells do (table.css). */
  .ds-datagrid > tbody > tr:last-child > th {
    border-bottom: none;
  }

  .ds-datagrid > tbody > tr.ds-datagrid__group > :is(th, td) {
    color: var(--ds-text);
    font: var(--ds-font-label);
    font-variant-numeric: tabular-nums;
  }

  /* ── The state row ─────────────────────────────── */

  .ds-datagrid > tbody > tr.ds-datagrid__state > td {
    height: auto;
    padding-block: var(--ds-space-4);
    border-bottom: 0;
  }

  @media (hover: hover) {
    .ds-datagrid > tbody > tr.ds-datagrid__state:hover {
      --ds-table-row-layer: transparent;
    }
  }

  .ds-datagrid__state .ds-empty--inline {
    max-inline-size: none;
  }

  /* ── Editing ───────────────────────────────────── */

  .ds-datagrid__editable {
    cursor: text;
  }

  .ds-datagrid > tbody > tr:has(> .ds-datagrid__editing) {
    position: relative;
    z-index: var(--ds-z-raised);
  }

  .ds-datagrid > tbody > tr > td.ds-datagrid__editing {
    padding-block: 0;
  }

  .ds-datagrid__field {
    position: relative;
    display: block;
  }

  .ds-datagrid__editor {
    inline-size: 100%;
    min-inline-size: calc(var(--ds-space-8) * 2);
  }

  .ds-datagrid__message {
    position: absolute;
    inset-block-start: calc(100% + var(--ds-space-1));
    inset-inline-start: 0;
    z-index: var(--ds-z-popover);
    display: flex;
    align-items: center;
    gap: var(--ds-space-1);
    inline-size: max-content;
    max-inline-size: calc(var(--ds-space-8) * 8);
    padding: var(--ds-space-1) var(--ds-space-2);
    border-radius: calc(var(--ds-radius-sm) * var(--ds-shape, 1));
    outline: 1px solid transparent;
    background: var(--ds-surface-popover);
    box-shadow: var(--ds-elev-2);
    color: var(--ds-error);
    font: var(--ds-font-meta);
    text-align: start;
    white-space: normal;
  }

  /* Under a figure (an end-aligned cell) the message hangs from the end,
     so it stays inside the table. */
  .ds-num > .ds-datagrid__field > .ds-datagrid__message {
    inset-inline: auto 0;
  }

  .ds-datagrid__message > svg {
    flex: none;
  }

  /* ── The selection bar's link, the menu's point ── */

  .ds-datagrid__every {
    margin-inline-start: var(--ds-space-2);
    color: inherit;
  }

  .ds-datagrid__point {
    position: fixed;
    inset-block-start: var(--ds-datagrid-point-y, 0px);
    inset-inline-start: var(--ds-datagrid-point-x, 0px);
    inline-size: 0;
    block-size: 0;
    pointer-events: none;
  }

  @media (forced-colors: active) {
    .ds-datagrid__resize::before {
      border-inline-end-color: CanvasText;
    }

    .ds-datagrid__resize[data-ds-datagrid-resizing]::before {
      border-inline-end-color: Highlight;
    }

    .ds-datagrid > tbody > tr.ds-datagrid__group {
      background-color: Canvas;
    }
  }

  @media print {
    .ds-datagrid__grip,
    .ds-datagrid__resize,
    .ds-datagrid__point {
      display: none;
    }
  }
}

/* ── components/daterange/daterange.css ── */
/*
 * Date range picker: a field of two dates and a picker popover with
 * presets ("Last 7 days", "This month") and two months side by side that
 * preview the range. DS.daterange (daterange.js) builds the popover inside
 * the root; the field is a .ds-datefield of type range, the months a
 * .ds-calendar in range mode, the presets .ds-picker__preset buttons.
 *
 *   <span class="ds-field__label" id="period-label">Period</span>
 *   <div class="ds-picker" data-ds-daterange data-ds-value="last-7-days">
 *     <div class="ds-datefield" role="group" aria-labelledby="period-label">
 *       (rendered: the two dates, then)
 *       <span class="ds-daterange__preset" id="...">Last 7 days</span>   (the preset in force; the field's description)
 *       <button class="ds-btn ds-btn--quiet ds-btn--icon ds-datefield__toggle" type="button" aria-label="Choose dates">(calendarRange)</button>
 *     </div>
 *     (rendered:)
 *     <div class="ds-picker__popover" role="dialog" aria-modal="true" aria-label="Choose dates" hidden>
 *       <div class="ds-picker__panes">
 *         <div class="ds-picker__presets" role="group" aria-label="Presets">(.ds-picker__preset ...)</div>
 *         <div class="ds-picker__pane"><div class="ds-calendar" (range, two months)>...</div></div>
 *       </div>
 *       <div class="ds-picker__foot">
 *         <span class="ds-daterange__summary" aria-live="polite">Nov 1 – 7, 2026</span>
 *         <span class="ds-picker__spacer"></span> (Clear)
 *       </div>
 *     </div>
 *   </div>
 *
 * The preset in force shows as a quiet tag inside the field (it is also
 * the field's description, so a screen reader hears "Last 7 days" with
 * the dates) and as the current preset in the list. At 480px or less
 * (the window, or the ds-content container) the tag steps aside, so the
 * two dates fit a phone. The foot says the
 * range being chosen, in words (Intl formatRange).
 *
 * Options: those of the field, the calendar and the popover, each in its
 * own component; the tag follows the field's size through its type.
 *
 * Motion: the popover's and the calendar's; the band and its preview
 * change colour over --ds-dur-fast.
 *
 * Forced colours: the tag keeps a border (CanvasText); the rest is the
 * parts' own.
 */

@layer ds.components.daterange {
  /* The preset in force, a quiet tag at the field's end. */
  .ds-daterange__preset {
    flex: none;
    max-inline-size: 40%;
    overflow: hidden;
    padding: 2px var(--ds-space-2);
    border: 1px solid transparent;
    border-radius: calc(var(--ds-radius-chip) * var(--ds-shape, 1));
    background: var(--ds-surface-high);
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .ds-daterange__preset[hidden] {
    display: none;
  }

  /* On a phone the two dates need the room; the preset stays the field's
     description and the current row of the list. */
  @media (max-width: 480px) {
    .ds-daterange__preset {
      display: none;
    }
  }

  @container ds-content (max-width: 480px) {
    .ds-daterange__preset {
      display: none;
    }
  }

  .ds-daterange__summary {
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
    font-variant-numeric: tabular-nums;
  }

  @media (forced-colors: active) {
    .ds-daterange__preset {
      border-color: CanvasText;
    }
  }
}

/* ── components/timerange/timerange.css ── */
/*
 * Time range with refresh: the range control of a monitoring view. A
 * button names the range and opens a picker popover with quick relative
 * ranges, an absolute from and to, and the ranges used recently; beside it
 * a refresh button and the auto-refresh interval. DS.timerange
 * (timerange.js) renders everything inside the root:
 *
 *   <div class="ds-timerange" data-ds-timerange data-ds-timerange-from="now-1h" data-ds-timerange-to="now"
 *        [data-ds-timerange-refresh="30s"] aria-label="Time range"></div>
 *
 *   (rendered:)
 *   <div class="ds-timerange" role="group" aria-label="Time range">
 *     <div class="ds-picker ds-timerange__range">
 *       <button class="ds-btn ds-timerange__trigger" type="button" aria-haspopup="dialog" aria-expanded="false">
 *         (clock) <span class="ds-btn__label ds-timerange__label">Last 1 hour</span> (chevronDown, .ds-timerange__chevron)</button>
 *       <div class="ds-picker__popover" role="dialog" aria-modal="true" aria-label="Time range" hidden>
 *         <div class="ds-picker__panes">
 *           <div class="ds-picker__presets ds-timerange__quick" role="group">(heading, .ds-picker__preset ...)</div>
 *           <div class="ds-picker__pane ds-timerange__absolute">
 *             <p class="ds-picker__heading">Absolute time range</p>
 *             <span class="ds-timerange__field-label">From</span> <div class="ds-datefield ds-datefield--block">...</div>
 *             <span class="ds-timerange__field-label">To</span> <div class="ds-datefield ds-datefield--block">...</div>
 *             <p class="ds-timerange__error" role="alert"></p>
 *             <button class="ds-btn ds-btn--filled ds-timerange__apply" type="button">Apply</button>
 *             <p class="ds-picker__heading">Recently used</p>
 *             <div class="ds-picker__presets" role="group">...</div>
 *     </div>
 *     <button class="ds-btn ds-btn--icon" type="button" aria-label="Refresh">(refresh)</button>
 *     <span class="ds-timerange__interval" [data-on]>
 *       <select class="ds-timerange__select" aria-label="Auto refresh"><option value="">Off</option> ...</select> (chevronDown)
 *     </span>
 *   </div>
 *
 * The interval is a native select drawn as an outlined pill, its chevron
 * over it; while an interval runs (data-on) it takes the tint, and its text
 * says the interval, so it is not told by colour alone. The error under
 * the fields has an icon of its own and the words.
 *
 * Options (src/core/options.css, docs/options.md), on the time range or any
 * ancestor: the trigger and the refresh button are buttons (their size,
 * density, shape and touch); the interval pill computes the same height
 * (--ds-btn-height, 8px per size step, 4px per density step, at least
 * --ds-target-min) and radius (the pill times --ds-shape). Tone: none.
 *
 * Motion: the popover's; the interval pill's tint over --ds-dur-fast; the
 * chevron of the trigger turns with the popover (aria-expanded), on the
 * spring.
 *
 * Forced colours: the interval pill keeps its border (ButtonBorder) and
 * the system's select colours; while on it is Highlight / HighlightText.
 */

@layer ds.components.timerange {
  .ds-timerange {
    display: inline-flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--ds-space-2);
    max-inline-size: 100%;
  }

  .ds-timerange__range {
    min-inline-size: 0;
  }

  .ds-timerange__trigger {
    max-inline-size: 100%;
  }

  .ds-timerange__label {
    min-inline-size: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    font-variant-numeric: tabular-nums;
  }

  /* The chevron turns over while the popover is open (a disclosure
     rotation), on the spring. */
  .ds-timerange__chevron {
    flex: none;
    transition: rotate var(--ds-dur-medium) var(--ds-ease-spatial);
  }

  .ds-timerange__trigger[aria-expanded="true"] .ds-timerange__chevron {
    rotate: 180deg;
  }

  .ds-timerange__absolute {
    display: flex;
    flex-direction: column;
    gap: var(--ds-space-1);
    inline-size: 280px;
    max-inline-size: 100%;
  }

  .ds-timerange__absolute > .ds-picker__heading:first-child {
    margin-block-start: 0;
    padding-inline: 0;
  }

  .ds-timerange__field-label {
    margin-block-start: var(--ds-space-2);
    color: var(--ds-text-2);
    font: var(--ds-font-label);
  }

  .ds-timerange__error {
    display: flex;
    align-items: flex-start;
    gap: var(--ds-space-1);
    margin: 0;
    color: var(--ds-on-error-container);
    font: var(--ds-font-meta);
  }

  .ds-timerange__error:empty {
    display: none;
  }

  .ds-timerange__apply {
    align-self: flex-start;
    margin-block-start: var(--ds-space-2);
  }

  .ds-timerange__quick {
    position: relative;
    max-block-size: 360px;
    overflow-y: auto;
    overscroll-behavior: contain;
  }

  /* The interval: a native select drawn as an outlined pill. */
  .ds-timerange__interval {
    --_h: calc(var(--ds-btn-height, 40px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px);
    --_box: max(var(--ds-target-min, 0px), var(--_h));
    --_half: calc(var(--_box) / 2);
    --_radius: min(calc(min(var(--ds-radius-action), var(--_half)) * var(--ds-shape, 1)), var(--_half));
    position: relative;
    display: inline-flex;
    align-items: center;
    /* Never under its line and border, as a button: they line up at every size. */
    block-size: max(var(--_box), calc(1lh + 2px));
    border: 1px solid var(--ds-line-2);
    border-radius: var(--_radius);
    color: var(--ds-action-ink);
    font: var(--ds-size-font, var(--ds-font-label));
    transition:
      background-color var(--ds-dur-fast) var(--ds-ease-in-out),
      border-color var(--ds-dur-fast) var(--ds-ease-in-out),
      color var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  .ds-timerange__interval[data-on] {
    border-color: transparent;
    background: var(--ds-accent);
    color: var(--ds-on-accent);
  }

  .ds-timerange__interval > .ds-timerange__chevron {
    position: absolute;
    inset-inline-end: var(--ds-space-3);
    pointer-events: none;
  }

  .ds-timerange__select {
    block-size: 100%;
    margin: 0;
    padding-block: 0;
    padding-inline: var(--ds-space-4) calc(var(--ds-space-4) + var(--ds-space-4));
    border: 0;
    border-radius: inherit;
    background: transparent;
    color: inherit;
    font: var(--ds-size-font, var(--ds-font-label));
    appearance: none;
    cursor: pointer;
    outline-offset: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    transition: outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-timerange__select:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: var(--ds-focus-offset);
  }

  @media (hover: hover) {
    .ds-timerange__interval:hover {
      border-color: var(--ds-text-2);
    }
  }

  @media (forced-colors: active) {
    .ds-timerange__interval {
      border-color: ButtonBorder;
    }

    .ds-timerange__interval[data-on] {
      forced-color-adjust: none;
      border-color: Highlight;
      background: Highlight;
      color: HighlightText;
    }

    .ds-timerange__select {
      appearance: auto;
      padding-inline-end: var(--ds-space-4);
    }

    .ds-timerange__interval > .ds-timerange__chevron {
      display: none;
    }
  }
}

/* ── components/duration/duration.css ── */
/*
 * Duration input: a text field that reads a length of time as people write
 * it ("1h 30m", "90 min", "1:30", PT1H30M) and writes it back in the
 * locale's short form once it is left. The box is the text field's
 * (.ds-input, form.css: its hooks, states and options); this sheet adds the
 * figures. DS.duration (duration.js) makes it a spinbutton and keeps the
 * value.
 *
 *   <span class="ds-field__label" id="timeout-label">Timeout</span>
 *   <input class="ds-input ds-duration" type="text" aria-labelledby="timeout-label" data-ds-duration
 *          data-ds-value="PT1H30M" [data-ds-duration-step="15m"] [data-ds-duration-min="1m"] [data-ds-duration-max="7d"]>
 *   (rendered: role="spinbutton", aria-valuenow in seconds, aria-valuetext "1 hour, 30 minutes";
 *    with data-ds-duration-name a hidden input with the ISO value after it)
 *
 * States: those of the text field. aria-invalid="true" (unreadable, or
 * outside min and max; the script sets it once the field is left) draws the
 * error border; the page shows the reason under the field, so the colour is
 * never alone. disabled and readonly as on any input.
 *
 * Options: the text field's (size, density, shape, touch), computed in
 * form.css; this sheet adds none. Tone: none.
 *
 * Motion: none of its own (the field's border and ring).
 *
 * Forced colours: the text field's.
 */

@layer ds.components.duration {
  /* Figures of one width, so a stepped value does not jitter. */
  .ds-duration {
    font-variant-numeric: tabular-nums;
  }
}

/* ── components/link/link.css ── */
/*
 * Link: a link that navigates, in four looks. Links are told apart from text
 * by the underline, not by colour alone (a link in running text always
 * keeps it); a standalone link sits apart from text and says what it is by
 * its place, its weight and its icon.
 *
 *   <a class="ds-link" href="/devices/42">LAPTOP-0042</a>
 *   <a class="ds-link ds-link--standalone" href="/devices">All devices (arrowRight 16, .ds-link__icon)</a>
 *   <a class="ds-link ds-link--external" href="https://example.com/manual" target="_blank" rel="noopener noreferrer">
 *     Product manual (external 16, .ds-link__icon)<span class="ds-sr"> (opens in a new tab)</span></a>
 *
 * Variants:
 *   .ds-link                 inline: the link colour (--ds-link) and the
 *                            shared underline geometry (the look of a link
 *                            in .ds-base, for pages and regions without it)
 *   .ds-link--standalone     a link on its own line or at the end of a card
 *                            ("All devices"): the label role, no underline
 *                            at rest, the underline on hover and keyboard
 *                            focus (forced colours: always), at least the
 *                            touch minimum high under .ds-touch; an
 *                            optional trailing icon (.ds-link__icon)
 *   .ds-link--external       leaves the product: a trailing external icon
 *                            (.ds-link__icon, DS.icons.external) and, with
 *                            target="_blank", rel="noopener noreferrer" and
 *                            a .ds-sr "(opens in a new tab)" in the markup;
 *                            combines with --standalone
 *   quiet                    a secondary link next to the main one:
 *                            .ds-link--quiet, which button.css styles
 *                            (with its twin .ds-link-btn--quiet)
 *   .ds-link__icon           an icon after the words (in a standalone link
 *                            also before them), 1em, on the text's centre
 *                            line; never moves
 *
 * Options (docs/options.md):
 *   size      a standalone link reads the size's type role
 *             (--ds-size-font, else the label role); an inline link takes
 *             the type of its text, so size changes nothing there
 *   touch     .ds-touch: a standalone link is at least --ds-target-min
 *             high (inline links in text are exempt, WCAG 2.5.8)
 *   shape     the focus ring's small radius (--ds-radius-xs) times
 *             --ds-shape
 *   density   nothing: a link has no box of its own to make denser
 *
 * Hooks: --ds-link-font (the type of a standalone link). The colours are the
 * link roles (--ds-link, --ds-link-underline, --ds-link-underline-hover,
 * --ds-link-underline-thickness, --ds-link-underline-offset).
 *
 * Motion: the underline colour and the ink fade on --ds-dur-fast; the focus
 * ring is solid from the first frame and snaps from offset + width to the
 * offset (outline-offset, --ds-dur-fast). A link is inline text: no state
 * layer, no ripple and no press morph (it would reach outside the line).
 * Hover never moves the icon. A press on touch screens darkens the
 * underline, as hover does.
 *
 * Forced colours: the system's LinkText; a standalone link keeps its
 * underline at rest, since colour no longer tells it apart.
 */

@layer ds.components.link {
  .ds-link {
    border-radius: calc(var(--ds-radius-xs) * var(--ds-shape, 1));
    color: var(--ds-link);
    text-decoration-line: underline;
    text-decoration-thickness: var(--ds-link-underline-thickness);
    text-decoration-color: var(--ds-link-underline);
    text-underline-offset: var(--ds-link-underline-offset);
    /* The ring rests (invisible) one width further out and snaps in. */
    outline-offset: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    -webkit-tap-highlight-color: transparent;
    transition:
      color var(--ds-dur-fast) var(--ds-ease-in-out),
      text-decoration-color var(--ds-dur-fast) var(--ds-ease-in-out),
      outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  @media (hover: hover) {
    .ds-link:hover {
      text-decoration-color: var(--ds-link-underline-hover);
    }
  }

  /* The press on touch screens, which show no hover. */
  .ds-link:active {
    text-decoration-color: var(--ds-link-underline-hover);
  }

  .ds-link:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: var(--ds-focus-offset);
  }

  /* The icon after the words of a link: the size of the text, on its
     centre line, with a small gap; it never moves. (Before the words only
     in a standalone link, whose gap places it.) */
  .ds-link__icon {
    display: inline-block;
    flex-shrink: 0;
    inline-size: 1em;
    block-size: 1em;
    margin-inline-start: var(--ds-space-1);
    vertical-align: -0.125em;
  }

  /* The external icon is a mark after the words, not a second subject: a
     little smaller than the text, so a link in a sentence keeps its line
     height. */
  .ds-link--external > .ds-link__icon {
    inline-size: 0.875em;
    block-size: 0.875em;
    vertical-align: -0.0625em;
  }

  /* Standalone: apart from text, so no underline at rest; the label role
     (or the size's), the underline on hover and focus. A target of its own:
     at least the touch minimum high under .ds-touch. */
  .ds-link--standalone {
    display: inline-flex;
    align-items: center;
    gap: var(--ds-space-1);
    min-block-size: var(--ds-target-min, 0px);
    font: var(--ds-link-font, var(--ds-size-font, var(--ds-font-label)));
    text-decoration-color: transparent;
  }

  /* In the flex box the gap places the icon, before or after the words. */
  .ds-link--standalone > .ds-link__icon {
    margin-inline-start: 0;
  }

  @media (hover: hover) {
    .ds-link--standalone:hover {
      text-decoration-color: var(--ds-link-underline-hover);
    }
  }

  .ds-link--standalone:active,
  .ds-link--standalone:focus-visible {
    text-decoration-color: var(--ds-link-underline-hover);
  }

  /* Forced colours: LinkText is a colour like any other there, so a
     standalone link keeps its underline. */
  @media (forced-colors: active) {
    .ds-link--standalone {
      text-decoration-color: LinkText;
    }
  }
}

/* ── components/toggle/toggle.css ── */
/*
 * Toggle group: a set of toggle buttons (aria-pressed) where one or several
 * are on. The buttons are .ds-btn toggles (button.css draws on and off); the
 * group lays them out and DS.toggle keeps their state.
 *
 *   <div class="ds-toggle-group" role="toolbar" aria-label="View" data-ds-toggle-group="single">
 *     <button class="ds-btn" type="button" aria-pressed="true" value="list">(list 16) List</button>
 *     <button class="ds-btn" type="button" aria-pressed="false" value="grid">(grid 16) Grid</button>
 *   </div>
 *
 * Connected (one pill outline): add .ds-btn-group (button-group.css), which
 * joins them and takes the gap away. A single toggle needs no group:
 *
 *   <button class="ds-btn ds-btn--quiet" type="button" aria-pressed="false" data-ds-toggle>Only open</button>
 *
 * Behaviour (DS.toggle, toggle.js): data-ds-toggle flips one button;
 * data-ds-toggle-group="single | multiple" serves every [aria-pressed]
 * button inside, with data-ds-toggle-group-required (single: one always on)
 * and data-ds-value; a role="toolbar" group is one tab stop with the
 * arrow keys (DS.a11y.roving), a role="group" keeps every button's own.
 *
 * Options (docs/options.md), on the group or any ancestor:
 *   size      the buttons' (button.css)
 *   density   the buttons' height, and the gap: 2px less per step (8px at
 *             the comfortable density, 2px at tight)
 *   shape     the buttons' radius
 *   touch     the buttons' touch minimum; the gap stays
 *
 * Hooks: --ds-toggle-group-gap (the gap between the toggles at the
 * comfortable density).
 *
 * State is never colour alone: a toggle that is on carries aria-pressed and
 * the tint (forced colours: Highlight, button.css); give text toggles an
 * icon that swaps to a check (.ds-icon-swap, b shows under
 * aria-pressed="true") and icon toggles a fillable glyph
 * (.ds-icon--fillable).
 *
 * Motion: the buttons' own (the fill fades on --ds-dur-fast, the press
 * morph); the group moves nothing.
 */

@layer ds.components.toggle {
  .ds-toggle-group {
    display: inline-flex;
    flex-wrap: wrap;
    align-items: center;
    gap: max(0px, calc(var(--ds-toggle-group-gap, var(--ds-space-2)) + var(--ds-density, 0) * 2px));
    max-inline-size: 100%;
    vertical-align: middle;
  }
}

/* ── components/button-group/button-group.css ── */
/*
 * Button group: connected buttons in one pill outline. The outer corners of
 * the first and the last button make the pill (at most half the height,
 * times --ds-shape, D11), the inner corners are square, and neighbours
 * share one border line; a filled or tonal group has a hairline divider in
 * its label colour between the buttons.
 *
 *   <div class="ds-btn-group" role="group" aria-label="Zoom">
 *     <button class="ds-btn" type="button">(minus 16) Out</button>
 *     <button class="ds-btn" type="button">Fit</button>
 *     <button class="ds-btn" type="button">(plus 16) In</button>
 *   </div>
 *
 * One look per group: outlined (the default), --filled or --tonal on every
 * button; icon buttons (--icon) or labelled ones. Toggles inside (a
 * .ds-toggle-group, aria-pressed) take the tint inside the group's outline
 * (an outlined toggle that is on keeps the line colour) and raise their
 * border over their neighbours'. A split button is a group of two (.ds-split-btn).
 *
 *   .ds-btn-group--block     fills its line; the buttons share it equally
 *                            and a label in .ds-btn__label ends in an
 *                            ellipsis when it is too narrow (a phone)
 *
 * Options (docs/options.md), on the group or any ancestor, computed in the
 * buttons' own rule here with the button's formula:
 *   size      the buttons' height and padding (button.css); the pill of the
 *             outer corners follows the height
 *   density   the buttons' height
 *   shape     the outer corners (and their press) times --ds-shape: a
 *             square theme has a square group
 *   touch     every button at least --ds-target-min high
 *
 * Hooks: --ds-btn-group-radius (the outer corners, default
 * --ds-radius-action), --ds-btn-group-divider (the line between two buttons;
 * default: their border colour, in a filled or tonal group the label colour
 * mixed into the fill). The buttons read the button hooks. The computed
 * values (--_g-box, --_g-half, --_g-rest, --_g-radius, --_g-divider) are
 * private.
 *
 * Press: the outer corners of the pressed button morph to the pressed
 * radius and spring back, like every pill; the inner corners stay square.
 * Focus: the ring of the focused button lies over its neighbours
 * (--ds-z-pinned); a hovered, pressed or on button raises its border
 * (--ds-z-raised).
 *
 * Forced colours: the buttons' system colours; the shared borders stay
 * ButtonBorder, a toggle that is on Highlight (button.css).
 */

@layer ds.components.button-group {
  .ds-btn-group {
    display: inline-flex;
    align-items: stretch;
    gap: 0;
    max-inline-size: 100%;
    vertical-align: middle;
  }

  .ds-btn-group > .ds-btn {
    /* The button's own box (button.css), for the pill of the outer corners. */
    --_g-box: max(var(--ds-target-min, 0px), var(--ds-btn-height-exact, calc(var(--ds-btn-height, 40px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px)));
    --_g-half: calc(var(--_g-box) / 2);
    --_g-rest: min(calc(min(var(--ds-btn-group-radius, var(--ds-radius-action)), var(--_g-half)) * var(--ds-shape, 1)), var(--_g-half));
    --_g-radius: var(--_g-rest);
    --_g-divider: var(--ds-btn-border, var(--ds-line-2));
    border-radius: 0;
  }

  .ds-btn-group > .ds-btn--icon {
    --_g-box: max(var(--ds-target-min, 0px), calc(var(--ds-btn-icon-size, 40px) + var(--ds-size-step, 0) * 8px));
  }

  /* The ends of the pill: the first and the last button of the group
     (another element in it, such as a menu, does not count). */
  .ds-btn-group > .ds-btn:not(.ds-btn ~ .ds-btn) {
    border-start-start-radius: var(--_g-radius);
    border-end-start-radius: var(--_g-radius);
  }

  .ds-btn-group > .ds-btn:not(:has(~ .ds-btn)) {
    border-start-end-radius: var(--_g-radius);
    border-end-end-radius: var(--_g-radius);
  }

  /* Neighbours share one line: each later button lies over the end border
     of the one before, in the divider colour. */
  .ds-btn-group > .ds-btn ~ .ds-btn {
    margin-inline-start: -1px;
    border-inline-start-color: var(--ds-btn-group-divider, var(--_g-divider));
  }

  /* An outlined toggle that is on keeps the group's outline (the segmented
     look): the tint fills it, the pill stays one line all round. */
  .ds-btn-group > .ds-btn[aria-pressed="true"]:not(.ds-btn--filled, .ds-btn--tonal, .ds-btn--quiet, .ds-btn--text, .ds-btn--ghost) {
    border-color: var(--ds-btn-group-divider, var(--ds-line-2));
  }

  /* In a filled or tonal group the line is the label colour in the fill,
     so the two targets read apart: as strong as dimmed content
     (--ds-state-disabled), so it reads as a seam, not as a label. */
  .ds-btn-group > :is(.ds-btn--filled, .ds-btn--tonal):not([aria-pressed="false"]) {
    --_g-divider: color-mix(in srgb, var(--ds-btn-color, var(--ds-on-primary)) calc(var(--ds-state-disabled) * 100%), var(--ds-btn-bg, var(--ds-primary)));
  }

  /* The press: the outer corners turn the pressed radius (times the shape,
     never rounder than at rest) and spring back on release, on the
     button's own transitions. Blocked buttons do not morph. */
  .ds-btn-group > .ds-btn:active:not(:disabled, [aria-disabled="true"], [aria-busy="true"], .ds-btn--done),
  .ds-btn-group > .ds-btn.ds-pressed:not(:disabled, [aria-disabled="true"], [aria-busy="true"], .ds-btn--done) {
    --_g-radius: min(calc(var(--ds-btn-radius-pressed, var(--ds-radius-action-pressed)) * var(--ds-shape, 1)), var(--_g-rest));
  }

  /* A hovered, pressed or on button shows its whole border; a focused one
     its whole ring. */
  @media (hover: hover) {
    .ds-btn-group > .ds-btn:hover {
      z-index: var(--ds-z-raised);
    }
  }

  .ds-btn-group > .ds-btn:is(:active, .ds-pressed, [aria-pressed="true"]) {
    z-index: var(--ds-z-raised);
  }

  .ds-btn-group > .ds-btn:focus-visible {
    z-index: var(--ds-z-pinned);
  }

  /* Full width: the buttons share the line; a label that does not fit ends
     in an ellipsis instead of pushing the group out. */
  .ds-btn-group--block {
    display: flex;
    inline-size: 100%;
    /* In a grid or flex parent too: never wider than its line because of
       its labels (they end in an ellipsis instead). */
    min-inline-size: 0;
  }

  .ds-btn-group--block > .ds-btn {
    flex: 1 1 0;
    min-inline-size: 0;
  }

  .ds-btn-group--block > .ds-btn > .ds-btn__label {
    min-inline-size: 0;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  .ds-btn-group--block > .ds-btn--icon {
    flex: 0 0 auto;
  }
}

/* ── components/menubutton/menubutton.css ── */
/*
 * Menu button: a button that opens a menu, with a chevron at its end that
 * turns while the menu is open. With a menu of radio items it is a choice
 * ("Sort: Name"): the button shows the chosen label.
 *
 *   <button class="ds-btn ds-menu-btn" type="button" aria-haspopup="menu" aria-expanded="false"
 *           aria-controls="sort-menu" data-ds-menubutton="#sort-menu">
 *     Sort: <span class="ds-menu-btn__value">Name</span>(chevronDown 16, .ds-chevron .ds-menu-btn__chevron)
 *   </button>
 *   <div class="ds-menu" id="sort-menu" role="menu" aria-label="Sort by" data-ds-menu-checks hidden>...</div>
 *
 * Any button look (.ds-btn, --filled, --tonal, --quiet, --text ...). An
 * icon-only menu button (moreVertical) has no chevron and needs no class of
 * this file: .ds-btn--icon with data-ds-menubutton. A menu trigger does not
 * take the pressed tint while open (button.css); the turned chevron and
 * aria-expanded say it.
 *
 *   .ds-menu-btn             the trigger: the end padding before a chevron
 *                            pulls in like a leading icon's (12px at md, 4px
 *                            more per size above, never more than the side
 *                            padding)
 *   .ds-menu-btn__value      the chosen label: one line, an ellipsis when
 *                            the button is narrower than its words
 *   .ds-menu-btn__chevron    the chevron (with .ds-chevron, which turns it
 *                            under aria-expanded="true" in --ds-dur-medium
 *                            on the spring, motion.css)
 *
 * Behaviour (DS.menubutton, menubutton.js): opens and closes the menu
 * through DS.overlay (click, Enter, Space; ArrowDown on the first item,
 * ArrowUp on the last), fills in aria-haspopup, aria-expanded and
 * aria-controls, mirrors the checked radio into .ds-menu-btn__value.
 *
 * Options: the button's (size, density, shape, touch); the chevron's end
 * padding steps with size like the side padding.
 *
 * Forced colours: the button's; the chevron is currentColor.
 */

@layer ds.components.menubutton {
  .ds-menu-btn {
    max-inline-size: 100%;
  }

  /* A chevron at the end sits closer to the edge, as a leading icon does at
     the start (never more than the side padding). */
  .ds-menu-btn:has(> .ds-menu-btn__chevron:last-child) {
    padding-inline-end: min(calc(var(--ds-btn-padding-x, var(--ds-space-4)) + var(--ds-size-step, 0) * 4px), calc(var(--ds-space-3) + max(var(--ds-size-step, 0), 0) * 4px));
  }

  .ds-menu-btn__value {
    min-inline-size: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .ds-menu-btn__chevron {
    flex-shrink: 0;
  }
}

/* ── components/splitbutton/splitbutton.css ── */
/*
 * Split button: one pill with two targets, the action and a menu (a button
 * group of two, button-group.css: the pill's ends, the square inner
 * corners and the divider between them).
 *
 *   <div class="ds-btn-group ds-split-btn" role="group" aria-label="Merge" data-ds-splitbutton>
 *     <button class="ds-btn ds-btn--filled ds-split-btn__action" type="button" value="merge">
 *       <span class="ds-split-btn__label">Merge</span></button>
 *     <button class="ds-btn ds-btn--filled ds-split-btn__toggle" type="button" aria-label="More merge options"
 *             aria-haspopup="menu" aria-expanded="false" aria-controls="merge-menu">(chevronDown 20, .ds-chevron)</button>
 *   </div>
 *   <div class="ds-menu" id="merge-menu" role="menu" aria-label="Merge options" hidden>...</div>
 *
 *   .ds-split-btn            the group (with .ds-btn-group and role="group")
 *   .ds-split-btn__action    the action: a .ds-btn in any look of the group
 *   .ds-split-btn__label     the action's words; a choice writes the chosen
 *                            label here; an ellipsis when it is too narrow
 *   .ds-split-btn__toggle    the menu button: the chevron only (20px), as
 *                            narrow as its padding allows (8px each side at
 *                            md, 2px per size step), never narrower than
 *                            the touch minimum under .ds-touch; the chevron
 *                            (.ds-chevron) turns while the menu is open
 *
 * One look on both buttons: --filled (the main action of its area),
 * --tonal or outlined.
 *
 * Behaviour (DS.splitbutton, splitbutton.js): the toggle opens the menu
 * through DS.menubutton and DS.overlay; with radio items the menu chooses
 * the action's variant (its label and value).
 *
 * Options: the buttons' (size, density, shape, touch: button.css and
 * button-group.css); the toggle's side padding steps with size only.
 *
 * Forced colours: the buttons' system colours; the divider stays
 * ButtonBorder.
 */

@layer ds.components.splitbutton {
  .ds-split-btn {
    flex-wrap: nowrap;
  }

  .ds-split-btn__action {
    min-inline-size: 0;
  }

  .ds-split-btn__label {
    min-inline-size: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  /* The menu half: the chevron and a little padding, so the action keeps
     the room; touch keeps it a full target. */
  .ds-split-btn__toggle {
    flex-shrink: 0;
    min-inline-size: var(--ds-target-min, 0px);
    padding-inline: calc(var(--ds-space-2) + var(--ds-size-step, 0) * 2px);
  }
}

/* ── components/copy/copy.css ── */
/*
 * Copy: a button that copies a value or a target's text (DS.copy), and the
 * value it sits next to. The button is a .ds-btn (an icon button with an
 * icon swap, or a labelled one with faces); this file lays out the value.
 *
 *   <span class="ds-copy ds-copy--field">
 *     <code class="ds-copy__value" id="api-key">ak_live_7f3a9c2e</code>
 *     <button class="ds-btn ds-btn--quiet ds-btn--icon ds-sm" type="button" aria-label="Copy the key"
 *             data-tip="Copy the key" data-ds-copy="#api-key">
 *       <span class="ds-icon-swap"><span class="ds-icon-swap__a">(copy 20)</span><span class="ds-icon-swap__b">(check 20)</span></span>
 *     </button>
 *   </span>
 *
 *   <button class="ds-btn" type="button" data-ds-copy data-ds-copy-value="https://example.com/t/4127">
 *     <span class="ds-btn__faces">
 *       <span class="ds-btn__face">(copy 16) Copy link</span>
 *       <span class="ds-btn__face ds-btn__face--done" aria-hidden="true">(check 16, pathLength 1)<span class="ds-copy__done"></span></span>
 *     </span>
 *   </button>
 *
 *   .ds-copy                 a value and its copy button in one line
 *   .ds-copy--field          the read-only field look: a box of the field
 *                            height (--ds-input-height, its size and density
 *                            steps, the touch minimum), the field radius
 *                            times --ds-shape, --ds-copy-field-bg; the value
 *                            fills it, the button sits at its end: an
 *                            icon button 8px lower than the field at every
 *                            size and density (32px at md), whatever size
 *                            class it carries
 *   .ds-copy__value          the value (a <code>, or a read-only <input>):
 *                            the code role (--ds-copy-font), one line with
 *                            an ellipsis, no box of its own; a click selects
 *                            all of it (user-select: all), so it can be
 *                            copied by hand as well
 *   .ds-copy__manual         written by DS.copy after the button when the
 *                            browser refuses to copy and nothing on the
 *                            page shows the text: a read-only field (with
 *                            .ds-copy__value) holding it, selected, to copy
 *                            by hand; gone on blur or Escape
 *   .ds-copy__done           the words of a done face; DS.copy writes the
 *                            strings' "Copied" into it
 *   [data-state="copied"]    on the button, written by DS.copy for
 *                            --ds-hold-status after a copy
 *
 * Options (docs/options.md):
 *   size      the field's height (8px per step) and the button's; the value
 *             keeps the code role
 *   density   the field's height, 4px per step
 *   shape     the field's radius
 *   touch     the field at least --ds-target-min high
 *
 * Hooks: --ds-copy-font (the value's type), --ds-copy-field-bg (the field
 * look's fill).
 *
 * Motion: the button's own: the icon swap crossfades with a small scale,
 * the faces roll and the check draws itself (button.css, motion.css).
 *
 * Forced colours: the field and the manual field keep their border
 * (ButtonBorder); the value is CanvasText.
 */

@layer ds.components.copy {
  .ds-copy {
    display: inline-flex;
    align-items: center;
    gap: var(--ds-space-1);
    min-inline-size: 0;
    max-inline-size: 100%;
    vertical-align: middle;
  }

  /* A <code>, or a read-only <input> (its value is what is copied): the
     same text either way, without the field's or the code chip's box. */
  .ds-copy__value {
    min-inline-size: 0;
    margin: 0;
    padding: 0;
    border: 0;
    background: none;
    overflow: hidden;
    color: var(--ds-text);
    font: var(--ds-copy-font, var(--ds-font-code));
    text-overflow: ellipsis;
    white-space: nowrap;
    user-select: all;
  }

  /* The read-only field: the height of a field (the input's formula), the
     value filling it, the button at its end. */
  .ds-copy--field {
    --_field: max(var(--ds-target-min, 0px), calc(var(--ds-input-height, 40px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px));
    display: flex;
    inline-size: 100%;
    min-block-size: var(--_field);
    padding-block: 0;
    padding-inline: calc(var(--ds-space-3) + var(--ds-size-step, 0) * 4px) var(--ds-space-1);
    border: 1px solid var(--ds-line-2);
    border-radius: min(calc(var(--ds-radius-field) * var(--ds-shape, 1)), calc(var(--_field) / 2));
    background: var(--ds-copy-field-bg, var(--ds-surface-low));
    /* The ring of a focused value (a read-only input) is the field's: it
       rests one width further out and snaps in. */
    outline-offset: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    transition: outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-copy--field > .ds-copy__value:focus-visible {
    outline: none;
  }

  .ds-copy--field:has(.ds-copy__value:focus-visible) {
    outline: var(--ds-focus-outline);
    outline-offset: var(--ds-focus-offset);
  }

  .ds-copy--field > .ds-copy__value {
    flex: 1 1 auto;
  }

  /* The icon button inside follows the field: 8px lower than it at every
     size and density (32px in the 40px field), never below the touch
     minimum (the field grows around it then). Through the button's own
     hook: the button adds its size step back, so its box is the field's
     less 8px whatever size class it carries. */
  .ds-copy--field > .ds-btn--icon {
    --ds-btn-icon-size: calc(var(--_field) - var(--ds-space-2) - var(--ds-size-step, 0) * 8px);
    flex-shrink: 0;
  }

  /* The manual fallback: the text in a small read-only field after the
     button, focused and selected. Its ring rests one width further out and
     snaps in, as every ring does. */
  .ds-copy__manual {
    inline-size: min(32ch, 100%);
    padding-block: var(--ds-space-1);
    padding-inline: var(--ds-space-2);
    border: 1px solid var(--ds-line-2);
    border-radius: calc(var(--ds-radius-field) * var(--ds-shape, 1));
    background: var(--ds-copy-field-bg, var(--ds-surface-low));
    outline-offset: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    transition: outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-copy__manual:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: var(--ds-focus-offset);
  }

  .ds-copy__done {
    white-space: nowrap;
  }
}

/* ── components/prioritybar/prioritybar.css ── */
/*
 * Priority action bar: a row of actions that folds the least important ones
 * into a "More" menu when it is too narrow for all of them (DS.prioritybar).
 *
 *   <div class="ds-priority-bar" role="toolbar" aria-label="Ticket actions" data-ds-prioritybar>
 *     <button class="ds-btn ds-btn--quiet" type="button" data-ds-priority="2">(pencil 16) Edit</button>
 *     <button class="ds-btn ds-btn--quiet" type="button">(userPlus 16) Assign</button>
 *     <button class="ds-btn ds-btn--quiet" type="button">(archive 16) Archive</button>
 *     [the module adds the More button and its menu]
 *   </div>
 *
 *   .ds-priority-bar         the row: one line, no wrap; it takes the width
 *                            its parent gives (a block, or a flex item that
 *                            grows), never the width of its actions
 *                            (contain: inline-size), so folding never
 *                            changes its size; as high as an icon button,
 *                            so the More button never changes its height
 *   .ds-priority-bar--end    the actions sit at the end (a page or card head)
 *   .ds-priority-bar__more   the More button (a quiet icon button the module
 *                            adds, or the bar's own); always the last item,
 *                            shown only while something is folded
 *   .ds-priority-bar__menu   its menu (a .ds-menu): the folded actions, at
 *                            least --ds-priority-bar-menu-width wide
 *   [data-ds-folded]         on a folded action (and on More while nothing
 *                            is folded), written by the system: not
 *                            displayed
 *
 * Actions: the bar's .ds-btn children in any look (quiet in a toolbar is
 * usual); data-ds-priority="<number>" keeps an action longer (the lower
 * folds first; among equals the last one). Any other child (a divider)
 * never folds and keeps its room.
 *
 * Options (docs/options.md), on the bar or any ancestor:
 *   size      the actions' (button.css) and the bar's height
 *   density   the actions' height and the gap: 1px less per step (4px at
 *             the comfortable density, 1px at tight)
 *   shape     the actions' radius
 *   touch     every action, More too, at least --ds-target-min
 *
 * Hooks: --ds-priority-bar-gap (between the actions, comfortable),
 * --ds-priority-bar-menu-width (the menu's least width).
 *
 * Motion: none of its own; an action folds and unfolds at once (a width
 * change is no moment to animate), the menu is DS.menu's.
 *
 * Forced colours: the buttons' and the menu's.
 */

@layer ds.components.prioritybar {
  .ds-priority-bar {
    display: flex;
    flex: 1 1 auto;
    flex-wrap: nowrap;
    align-items: center;
    gap: max(0px, calc(var(--ds-priority-bar-gap, var(--ds-space-1)) + var(--ds-density, 0) * 1px));
    min-inline-size: 0;
    min-block-size: max(var(--ds-target-min, 0px), calc(var(--ds-btn-icon-size, 40px) + var(--ds-size-step, 0) * 8px));
    /* Its width never follows its actions: folding cannot resize it. */
    contain: inline-size;
  }

  .ds-priority-bar--end {
    justify-content: flex-end;
  }

  .ds-priority-bar > * {
    flex-shrink: 0;
  }

  /* More is always the last item of the row, whatever follows it in the
     markup. */
  .ds-priority-bar__more {
    order: 1;
  }

  .ds-priority-bar > [data-ds-folded] {
    display: none;
  }

  .ds-priority-bar__menu {
    min-inline-size: var(--ds-priority-bar-menu-width, 200px);
  }
}

/* ── components/listbox/listbox.css ── */
/*
 * Listbox: a list of options to choose one or several from, in an
 * outlined box that scrolls on its own (the WAI listbox pattern). It is a
 * tab stop; the active option (data-active, aria-activedescendant on the
 * box) takes the state layer, the chosen ones (aria-selected) the tint, the
 * label weight and a check, never colour alone. Several values
 * (aria-multiselectable) show a box per option that fills and draws its
 * check. DS.listbox (listbox.js) brings the keys, type-ahead, the value and
 * the data path (rendered, filtered, windowed); it is also the list engine of
 * the combobox and the select panel.
 *
 *   <div class="ds-listbox" role="listbox" aria-labelledby="device-label" data-ds-listbox>
 *     <div class="ds-listbox__option" role="option" aria-selected="true" data-value="laptop-14">
 *       <span class="ds-listbox__check" aria-hidden="true">(check 16)</span>
 *       <span class="ds-listbox__name">Laptop 14</span>
 *       <span class="ds-listbox__description">For most desks</span>
 *       <span class="ds-listbox__meta">14 inch</span>
 *     </div>
 *     <div class="ds-listbox__group" role="group" aria-labelledby="g-1">
 *       <div class="ds-listbox__heading" id="g-1" role="presentation">Desktops</div> ... options
 *     </div>
 *   </div>
 *
 * One choice: the check stands at the end of the chosen option. Several:
 * the check is a box at the start (the checkbox's size, --ds-check-size)
 * that fills in the primary colour and draws its check. A
 * .ds-listbox__match marks the letters a filter matched (bold, underlined:
 * no colour alone). aria-disabled="true" on an option: the disabled ink, no
 * layer; on the listbox: every option so, and no tab stop.
 *
 * .ds-listbox--plain: no box, no cap of its own (inside a panel that has
 * both, the select panel's).
 *
 * Options (src/core/options.css, docs/options.md), on the listbox or any
 * ancestor; each is computed here, in the rule that uses it:
 *   size      .ds-xs ... .ds-xl: an option 8px per step (40px at md), the
 *             name's type role (--ds-size-font), the check box 2px per step
 *   density   .ds-density-*: an option 4px per step, its block padding 2px
 *             per step; side padding and type stay
 *   shape     .ds-shape-*: multiplies the box's radius and the check box's
 *   touch     .ds-touch: options at least --ds-touch-target (48px)
 *   tone      none: a listbox shows no status of its own
 *
 * Focus: the box takes the ring on :focus-visible (it rests one width
 * further out and snaps in on --ds-dur-fast) and its active option the
 * focus layer at once; under the pointer an option takes the hover layer.
 *
 * Motion: the active layer fades in over --ds-dur-micro and goes at once,
 * so a held arrow key leaves no trail; the check box fills over
 * --ds-dur-fast and its check is drawn left to right over --ds-dur-medium
 * (--ds-ease-out), as a checkbox's; the end check of one choice fades.
 *
 * Cut edges: the box fades each edge with more to show over
 * --ds-scroll-fade (the combobox list's mask on the registered numbers
 * --ds-scroll-edge-start and -end, registered in tokens.css, so the single
 * file works without scroller.css); DS.listbox attaches DS.dom.scrollEdges() on
 * the block axis, whose data-ds-overflow-start and -end set them (gliding
 * over --ds-dur-fast once it measured, data-ds-edges).
 *
 * Hooks: --ds-listbox-option-height (40px), --ds-listbox-max-height
 * (264px; none shows every option), --ds-listbox-radius (--ds-radius-field),
 * --ds-check-size (the box of several values, form.css's). The private
 * --_h, --_size are computed here: never set them.
 *
 * Forced colours: the box keeps its border, a chosen option is
 * SelectedItem / SelectedItemText (a CanvasText ring inside while it is the
 * active one), the active one a Highlight outline, a blocked one GrayText;
 * the check box keeps its edge in CanvasText.
 *
 * Progressive:
 * - scrollbar-color and scrollbar-width (a thin, quiet scrollbar): without
 *   them the platform scrollbar shows.
 */

@layer ds.components.listbox {
  .ds-listbox {
    position: relative;
    display: block;
    max-height: var(--ds-listbox-max-height, 264px);
    margin: 0;
    padding: var(--ds-space-1) 0;
    overflow-y: auto;
    border: 1px solid var(--ds-outline);
    border-radius: calc(var(--ds-listbox-radius, var(--ds-radius-field)) * var(--ds-shape, 1));
    background: var(--ds-surface);
    color: var(--ds-text);
    list-style: none;
    scrollbar-width: thin;
    scrollbar-color: var(--ds-line-2) transparent;
    /* The active option, scrolled into view, lands clear of the fades. */
    scroll-padding-block: var(--ds-scroll-fade, var(--ds-space-8));
    /* The ring rests one width further out and snaps in. */
    outline-offset: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    mask-image:
      linear-gradient(to bottom, transparent, #000 calc(var(--ds-scroll-edge-start) * var(--ds-scroll-fade, var(--ds-space-8))), #000 calc(100% - var(--ds-scroll-edge-end) * var(--ds-scroll-fade, var(--ds-space-8))), transparent),
      linear-gradient(#000, #000);
    mask-size: calc(100% - var(--ds-scrollbar-width, 0px)) 100%, var(--ds-scrollbar-width, 0px) 100%;
    mask-position: 0 0, 100% 0;
    mask-repeat: no-repeat;
    transition: outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  /* The fades glide only once DS.dom.scrollEdges() has measured
     (data-ds-edges): nothing moves on load. */
  .ds-listbox[data-ds-edges] {
    transition:
      outline-offset var(--ds-dur-fast) var(--ds-ease-out),
      --ds-scroll-edge-start var(--ds-dur-fast) var(--ds-ease-in-out),
      --ds-scroll-edge-end var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  .ds-listbox:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: var(--ds-focus-offset);
  }

  .ds-listbox--plain {
    max-height: none;
    padding: 0;
    overflow: visible;
    border: 0;
    border-radius: 0;
    background: transparent;
    mask-image: none;
  }

  .ds-listbox[data-ds-overflow-start] {
    --ds-scroll-edge-start: 1;
  }

  .ds-listbox[data-ds-overflow-end] {
    --ds-scroll-edge-end: 1;
  }

  .ds-listbox__group {
    margin: 0;
    padding: 0;
    list-style: none;
  }

  /* A line between groups, not above the first one that shows. */
  .ds-listbox__group:has(> .ds-listbox__option:not([hidden])) ~ .ds-listbox__group {
    margin-block-start: var(--ds-space-1);
    padding-block-start: var(--ds-space-1);
    border-block-start: 1px solid var(--ds-line);
  }

  .ds-listbox__option[hidden],
  .ds-listbox__group[hidden],
  .ds-listbox__group:not(:has(> .ds-listbox__option:not([hidden]))) {
    display: none;
  }

  .ds-listbox__heading {
    display: block;
    margin: 0;
    padding: var(--ds-space-2) var(--ds-space-4) var(--ds-space-1);
    color: var(--ds-text-2);
    font: var(--ds-font-caption);
    cursor: default;
  }

  /* One choice: the text, and the check at the end. */
  .ds-listbox__option {
    --_h: calc(var(--ds-listbox-option-height, 40px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px);
    position: relative;
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    align-content: center;
    align-items: center;
    column-gap: var(--ds-space-3);
    row-gap: 2px;
    min-height: max(var(--ds-target-min, 0px), var(--_h));
    margin: 0;
    padding: calc(var(--ds-space-2) + var(--ds-density, 0) * 2px) var(--ds-space-4);
    color: var(--ds-text);
    cursor: pointer;
    -webkit-tap-highlight-color: transparent;
  }

  .ds-listbox__option > :not(.ds-listbox__check) {
    grid-column: 1;
  }

  .ds-listbox__option > .ds-listbox__check {
    grid-column: 2;
    grid-row: 1 / span 3;
  }

  /* Several: the box first, the text after it. */
  .ds-listbox[aria-multiselectable="true"] .ds-listbox__option {
    grid-template-columns: auto minmax(0, 1fr);
  }

  .ds-listbox[aria-multiselectable="true"] .ds-listbox__option > :not(.ds-listbox__check) {
    grid-column: 2;
  }

  .ds-listbox[aria-multiselectable="true"] .ds-listbox__option > .ds-listbox__check {
    grid-column: 1;
  }

  /* The state layer: hover under a pointer, the active option's layer, and
     the focus layer while the box has keyboard focus. */
  .ds-listbox__option::before {
    content: '';
    position: absolute;
    inset: 0;
    background: var(--ds-text);
    opacity: 0;
    pointer-events: none;
    transition: opacity var(--ds-dur-micro) var(--ds-ease-in-out);
  }

  .ds-listbox__option:not([data-active])::before {
    transition-duration: 0ms;
  }

  @media (hover: hover) {
    .ds-listbox__option:hover:not([aria-disabled="true"], .ds-listbox[aria-disabled="true"] *)::before {
      opacity: var(--ds-state-hover);
    }
  }

  /* A listbox that is its own tab stop shows its active option only while
     it has the focus; in a panel the field keeps the focus. */
  .ds-listbox[tabindex]:not(:focus) .ds-listbox__option[data-active]:not([aria-disabled="true"])::before {
    opacity: 0;
  }

  .ds-listbox__option[data-active]:not([aria-disabled="true"])::before {
    opacity: var(--ds-state-hover);
  }

  .ds-listbox:focus-visible .ds-listbox__option[data-active]:not([aria-disabled="true"])::before {
    opacity: var(--ds-state-focus);
    transition-duration: 0s;
  }

  .ds-listbox__option[aria-selected="true"] {
    background: var(--ds-accent);
    color: var(--ds-on-accent);
  }

  .ds-listbox__name {
    position: relative;
    min-width: 0;
    overflow: hidden;
    font: var(--ds-size-font, var(--ds-font-body));
    font-weight: var(--ds-weight-regular);
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .ds-listbox__option[aria-selected="true"] .ds-listbox__name {
    font-weight: var(--ds-weight-label);
  }

  .ds-listbox__description,
  .ds-listbox__meta {
    position: relative;
    min-width: 0;
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
  }

  .ds-listbox__meta {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .ds-listbox__option[aria-selected="true"] :is(.ds-listbox__description, .ds-listbox__meta) {
    color: inherit;
  }

  /* The letters a filter matched: weight and a line, not colour. */
  .ds-listbox__match {
    background: transparent;
    color: inherit;
    font-weight: var(--ds-weight-label);
    text-decoration: underline;
    text-decoration-thickness: var(--ds-link-underline-thickness);
    text-underline-offset: var(--ds-link-underline-offset);
  }

  /* One choice: the check at the end, there only on the chosen option. */
  .ds-listbox__check {
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    color: inherit;
    opacity: 0;
    transition: opacity var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  .ds-listbox__option[aria-selected="true"] > .ds-listbox__check {
    opacity: 1;
  }

  /* Several: a box that fills and draws its check, as a checkbox does. */
  .ds-listbox[aria-multiselectable="true"] .ds-listbox__check {
    --_size: calc(var(--ds-check-size, 18px) + var(--ds-size-step, 0) * 2px);
    box-sizing: border-box;
    width: var(--_size);
    height: var(--_size);
    border: 2px solid var(--ds-text-2);
    border-radius: calc(var(--ds-radius-check) * var(--ds-shape, 1));
    background: transparent;
    color: var(--ds-on-primary);
    opacity: 1;
    transition:
      background-color var(--ds-dur-fast) var(--ds-ease-in-out),
      border-color var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  .ds-listbox[aria-multiselectable="true"] .ds-listbox__check svg {
    width: 100%;
    height: 100%;
    clip-path: inset(0 100% 0 0);
    opacity: 0;
    transition:
      opacity var(--ds-dur-fast) var(--ds-ease-in),
      clip-path 0s linear var(--ds-dur-fast);
  }

  .ds-listbox[aria-multiselectable="true"] .ds-listbox__option[aria-selected="true"] > .ds-listbox__check {
    border-color: var(--ds-primary);
    background: var(--ds-primary);
  }

  .ds-listbox[aria-multiselectable="true"] .ds-listbox__option[aria-selected="true"] > .ds-listbox__check svg {
    clip-path: inset(0);
    opacity: 1;
    transition:
      opacity 0s,
      clip-path var(--ds-dur-medium) var(--ds-ease-out) var(--ds-dur-micro);
  }

  /* Blocked: the disabled ink, no layer, no pointer. */
  .ds-listbox__option[aria-disabled="true"],
  .ds-listbox[aria-disabled="true"] .ds-listbox__option {
    color: var(--ds-disabled-ink, var(--ds-text));
    cursor: default;
  }

  .ds-listbox__option[aria-disabled="true"] :is(.ds-listbox__description, .ds-listbox__meta),
  .ds-listbox[aria-disabled="true"] :is(.ds-listbox__description, .ds-listbox__meta) {
    color: inherit;
  }

  .ds-listbox[aria-multiselectable="true"] .ds-listbox__option[aria-disabled="true"] > .ds-listbox__check,
  .ds-listbox[aria-multiselectable="true"][aria-disabled="true"] .ds-listbox__check {
    border-color: var(--ds-disabled-ink, var(--ds-text-2));
  }

  /* A chosen box that is blocked fills with the disabled fill, as a
     checked checkbox that is disabled does. */
  .ds-listbox[aria-multiselectable="true"] .ds-listbox__option[aria-disabled="true"][aria-selected="true"] > .ds-listbox__check,
  .ds-listbox[aria-multiselectable="true"][aria-disabled="true"] .ds-listbox__option[aria-selected="true"] > .ds-listbox__check {
    border-color: transparent;
    background: var(--ds-disabled-fill, var(--ds-primary));
    color: var(--ds-disabled-ink, var(--ds-on-primary));
  }

  .ds-listbox[aria-disabled="true"] {
    border-color: var(--ds-line);
    background: var(--ds-surface-low);
  }

  @media (forced-colors: active) {
    .ds-listbox__option[data-active] {
      outline: 2px solid Highlight;
      outline-offset: -2px;
    }

    .ds-listbox[tabindex]:not(:focus) .ds-listbox__option[data-active] {
      outline: none;
    }

    .ds-listbox__option[aria-selected="true"] {
      forced-color-adjust: none;
      background: SelectedItem;
      color: SelectedItemText;
    }

    .ds-listbox__option[aria-selected="true"][data-active] {
      outline-color: CanvasText;
    }

    .ds-listbox__option[aria-disabled="true"],
    .ds-listbox[aria-disabled="true"] .ds-listbox__option {
      color: GrayText;
    }

    .ds-listbox__option[aria-selected="true"][aria-disabled="true"] {
      background: Canvas;
      outline: 1px solid GrayText;
      outline-offset: -1px;
    }

    .ds-listbox[aria-multiselectable="true"] .ds-listbox__check {
      border-color: CanvasText;
    }

    .ds-listbox[aria-multiselectable="true"] .ds-listbox__option[aria-selected="true"] > .ds-listbox__check {
      border-color: SelectedItemText;
      background: SelectedItemText;
      color: SelectedItem;
    }

    .ds-listbox__match {
      text-decoration-color: currentColor;
    }
  }
}

/* ── components/number/number.css ── */
/*
 * Number input: a field that holds a number in the page's locale, with
 * stepper buttons at its end (or one at each end), a unit or a currency.
 * It is an input group of form.css: the group draws the field (border,
 * radius, height, ring, invalid and disabled), this file only places the
 * steppers and sets the figures.
 *
 *   <div class="ds-input-group ds-number" data-ds-number data-ds-number-min="0" data-ds-number-max="500" data-ds-number-step="5">
 *     <input class="ds-input" id="quota" type="text" inputmode="decimal" autocomplete="off" value="50">
 *     <span class="ds-input-group__suffix" aria-hidden="true">GB</span>
 *     <span class="ds-input-group__trailing ds-number__steps">
 *       <button class="ds-btn ds-btn--quiet ds-btn--icon ds-number__step ds-number__down" type="button" tabindex="-1" aria-label="Decrease">(minimize 18)</button>
 *       <button class="ds-btn ds-btn--quiet ds-btn--icon ds-number__step ds-number__up" type="button" tabindex="-1" aria-label="Increase">(plus 18)</button>
 *     </span>
 *   </div>
 *
 *   .ds-number--split: the minus first, the plus last, the figure centred
 *   (a quantity); the steppers are direct children, in any order:
 *   <div class="ds-input-group ds-number ds-number--split" data-ds-number data-ds-number-min="1">
 *     <input class="ds-input" ...>
 *     <button class="ds-btn ds-btn--quiet ds-btn--icon ds-number__step ds-number__down" ...>
 *     <button class="ds-btn ds-btn--quiet ds-btn--icon ds-number__step ds-number__up" ...></div>
 *
 * Currency and unit: data-ds-number-currency="EUR" or -unit="gigabyte" on
 * the group, with an empty .ds-input-group__prefix and __suffix: DS.number
 * writes the symbol where the locale writes it (€ before the figure in
 * English, after it in German). Both are aria-hidden: the spinbutton's
 * aria-valuetext says "19.90 euros".
 *
 * The figures are tabular, so a value that steps does not shift. Behaviour
 * (the keys, parsing and formatting, min, max and step, the held stepper)
 * is DS.number (number.js).
 *
 * Options (src/core/options.css, docs/options.md), from the group of
 * form.css and computed here for the steppers:
 *   size      .ds-xs ... .ds-xl: the field 8px per step; the steppers 8px
 *             per step too, always 8px less than the field (32px at md)
 *   density   .ds-density-*: 4px per step on the field and the steppers
 *   shape     .ds-shape-*: the field's corners; the steppers are actions:
 *             a pill at the default, square at 0 (D11)
 *   touch     .ds-touch: field and steppers at least --ds-touch-target
 * There is no tone: the field shows its state through aria-invalid and a
 * hint in words (form.css).
 *
 * Hooks: --ds-number-step-size (32px: the stepper at md and comfortable,
 * which size and density steps apply to).
 *
 * Forced colours: the steppers are buttons in the system's colours; at an
 * end a stepper is disabled, GrayText (button.css).
 */

@layer ds.components.number {
  .ds-number > .ds-input {
    font-variant-numeric: tabular-nums;
  }

  /* The steppers sit side by side at the end of the field, close to each
     other (the group's end padding gives way to a trailing button). */
  .ds-number__steps {
    gap: 0;
  }

  /* A stepper is an icon button 8px smaller than the field at every size
     and density (the icon button's own model follows size only), never
     under the touch minimum. */
  .ds-number__step {
    --ds-btn-icon-size: calc(var(--ds-number-step-size, 32px) + var(--ds-density, 0) * 4px);
    /* A held press repeats: no double-tap zoom, no text selection. */
    touch-action: manipulation;
    user-select: none;
  }

  /* Split: the minus at the start, the plus at the end, the figure in the
     middle. */
  .ds-number--split {
    padding-inline: var(--ds-space-1);
  }

  .ds-number--split > .ds-input {
    text-align: center;
  }

  /* Wherever the markup puts them (the field may come first, so a screen
     reader's cursor meets it first): the minus first, the plus last. */
  .ds-number--split > .ds-number__down {
    order: -1;
  }

  .ds-number--split > .ds-number__up {
    order: 1;
  }
}

/* ── components/tree/tree.css ── */
/*
 * Tree view (3.0): a hierarchy of rows that open and close, the APG tree
 * pattern. One tab stop; the arrow keys walk the rows, open and close
 * them; letters jump by label. DS.tree (tree.js) holds the keyboard, the
 * selection, the tri-state checks, lazy children and the drag.
 *
 *   <ul class="ds-tree" role="tree" aria-label="Files" data-ds-tree>
 *     <li class="ds-tree__item" role="treeitem" aria-expanded="true" data-ds-key="docs">
 *       <div class="ds-tree__row">
 *         <span class="ds-tree__toggle" aria-hidden="true">[icon chevronRight 16]</span>
 *         <span class="ds-tree__icon" aria-hidden="true">[icon folder 20][icon folderOpen 20]</span>
 *         <span class="ds-tree__label">Documents</span>
 *         <span class="ds-tree__meta">3 files</span>
 *         <span class="ds-tree__actions"><button class="ds-btn ds-btn--quiet ds-btn--icon ds-sm" type="button" tabindex="-1" aria-label="More for Documents">[icon moreVertical 18]</button></span>
 *       </div>
 *       <ul class="ds-tree__group" role="group">
 *         <li class="ds-tree__item" role="treeitem" aria-selected="false" data-ds-key="plan">
 *           <div class="ds-tree__row"><span class="ds-tree__icon" aria-hidden="true">[icon fileText 20]</span><span class="ds-tree__label">Plan.pdf</span></div>
 *         </li>
 *       </ul>
 *     </li>
 *     <li class="ds-tree__item" role="treeitem" aria-expanded="false" data-ds-tree-lazy data-ds-key="archive"> ... </li>
 *   </ul>
 *
 * Parts: a folder (aria-expanded on its item) has a .ds-tree__toggle
 * (a chevron that turns a quarter while it is open) and a .ds-tree__group
 * of child items; a leaf has neither, and its row keeps the toggle's room,
 * so labels line up. .ds-tree__icon holds a glyph, or two: the second
 * shows while the folder is open (folder, folderOpen: folder groups).
 * .ds-tree__label takes the room and ends in an ellipsis; .ds-tree__meta
 * a short fact (a count, a size) in the meta font; .ds-tree__actions the
 * row's buttons (tabindex="-1": DS.tree lets Tab reach those of the
 * focused row only); .ds-tree__grip the drag handle DS.tree writes with
 * drag on. A group draws a guide (a hairline below its folder's toggle).
 *
 * States: aria-selected="true" (one chosen row: the tint
 * --ds-tree-selected-bg and the label weight), aria-checked (checkbox mode:
 * an inert .ds-checkbox.ds-tree__check mirrors true, false and mixed),
 * aria-disabled="true" (the disabled model, no layer), aria-busy="true"
 * while lazy children load (a spinner in the toggle), data-state="error"
 * when they failed (.ds-tree__error says so in words). While a drag runs,
 * data-ds-tree-drop on an item marks the place: "before" a line above its
 * row, "after" a line below its subtree, "inside" its row framed.
 *
 * The row is a state layer and a ripple host: hover --ds-state-hover-lg,
 * the press in --ds-dur-micro (not while one of its buttons is pressed),
 * the focus layer and an inset ring while its item has keyboard focus. A
 * group opens and closes with its height where the browser animates to
 * auto (as .ds-collapsible: opens over --ds-dur-medium on --ds-ease-out,
 * closes on --ds-dur-base, accelerating); the chevron turns on the spring.
 *
 * Options (src/core/options.css, docs/options.md), on the tree or any
 * ancestor; each is computed here, in the rule that uses it:
 *   size      .ds-xs ... .ds-xl: a row 8px per step (24, 32, 40, 48,
 *             56px), the toggle and the indent 4px per step, the label the
 *             type role of the size (--ds-size-font, else the body font)
 *   density   .ds-density-*: a row 4px per step (40, 36, 32, 28px), its
 *             side padding 2px per step; not the type, not the indent
 *   shape     .ds-shape-*: multiplies the row's radius
 *   touch     .ds-touch: a row at least --ds-touch-target high; touch wins
 *             over size and density
 *   tone      none: a row's status is a chip or a word in it
 *
 * Hooks: --ds-tree-row-height (40px), --ds-tree-padding (--ds-space-2),
 * --ds-tree-indent (20px), --ds-tree-toggle-size (24px), --ds-tree-radius
 * (--ds-radius-sm), --ds-tree-selected-bg (--ds-accent), --ds-tree-guide
 * (--ds-line), --ds-tree-drop-color (--ds-primary).
 *
 * Forced colours: the selected row is SelectedItem / SelectedItemText (a
 * focused one has a CanvasText ring inside the fill), a blocked row
 * GrayText; the drop marks are Highlight; the guide keeps its edge.
 *
 * Progressive:
 * - interpolate-size: a group's height glides to and from auto; without
 *   it the group shows and hides at once.
 * - overflow-clip-margin: the focus ring of a row at the edge of an open
 *   group shows whole while it glides; without it the ring is clipped
 *   during the glide only.
 */

@layer ds.components.tree {
  .ds-tree,
  .ds-tree__group {
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .ds-tree {
    color: var(--ds-text);
    font: var(--ds-font-body);
  }

  .ds-tree:empty {
    display: none;
  }

  .ds-tree__item {
    position: relative;
    margin: 0;
    padding: 0;
    /* The ring is the row's: the item holds the focus, its row shows it. */
    outline: none;
  }

  /* One row: 8px per size step, 4px per density step from 40px; the toggle
     and the indent 4px per size step. */
  .ds-tree__row,
  .ds-tree__group {
    --_h: calc(var(--ds-tree-row-height, 40px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px);
    --_pad: max(0px, calc(var(--ds-tree-padding, var(--ds-space-2)) + var(--ds-density, 0) * 2px));
    --_toggle: calc(var(--ds-tree-toggle-size, 24px) + var(--ds-size-step, 0) * 4px);
    --_indent: calc(var(--ds-tree-indent, 20px) + var(--ds-size-step, 0) * 4px);
  }

  .ds-tree__row {
    position: relative;
    isolation: isolate;
    display: flex;
    align-items: center;
    gap: var(--ds-space-2);
    box-sizing: border-box;
    min-block-size: max(var(--ds-target-min, 0px), var(--_h));
    padding-inline: var(--_pad);
    border-radius: calc(var(--ds-tree-radius, var(--ds-radius-sm)) * var(--ds-shape, 1));
    color: var(--ds-text);
    -webkit-tap-highlight-color: transparent;
    user-select: none;
  }

  /* An inset ring: it rests on the row's edge and snaps inward. */
  .ds-tree__item > .ds-tree__row {
    outline-offset: 0;
    transition:
      background-color var(--ds-dur-fast) var(--ds-ease-in-out),
      outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  /* A leaf keeps the toggle's room, so its label lines up with a folder's. */
  .ds-tree__item:not([aria-expanded]) > .ds-tree__row {
    padding-inline-start: calc(var(--_pad) + var(--_toggle) + var(--ds-space-2));
  }

  .ds-tree__item:not([aria-disabled="true"]) > .ds-tree__row {
    cursor: pointer;
  }

  .ds-tree__row::before {
    content: '';
    position: absolute;
    inset: 0;
    z-index: -1;
    border-radius: inherit;
    background: currentColor;
    opacity: 0;
    pointer-events: none;
    transition: opacity var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  @media (hover: hover) {
    .ds-tree__item:not([aria-disabled="true"]) > .ds-tree__row:hover::before {
      opacity: var(--ds-state-hover-lg);
    }
  }

  /* Keyboard focus on the item: the focus layer and the ring at once. */
  .ds-tree__item:focus-visible > .ds-tree__row {
    outline: var(--ds-focus-outline);
    outline-offset: calc(-1 * var(--ds-focus-width));
  }

  .ds-tree__item:focus-visible > .ds-tree__row::before {
    opacity: var(--ds-state-focus);
    transition-duration: 0s;
  }

  /* Press-in in --ds-dur-micro (.ds-pressed: js/ripple.js holds it); not
     while one of the row's buttons is pressed (it has its own). */
  .ds-tree__item:not([aria-disabled="true"]) > .ds-tree__row:active:not(:has(:is(a[href], button):active))::before,
  .ds-tree__item:not([aria-disabled="true"]) > .ds-tree__row.ds-pressed::before {
    opacity: var(--ds-state-pressed);
    transition-duration: var(--ds-dur-micro);
  }

  /* With DS.ripple.attach() the ripple brings the press; the flat layer
     stays at its hover value. */
  :where(.ds-ripples) .ds-tree__item:not([aria-disabled="true"]) > .ds-tree__row:where(:not([data-ds-ripple="off"], [data-ds-ripple="off"] *)):is(:active, .ds-pressed)::before {
    opacity: 0;
  }

  @media (hover: hover) {
    :where(.ds-ripples) .ds-tree__item:not([aria-disabled="true"]) > .ds-tree__row:where(:not([data-ds-ripple="off"], [data-ds-ripple="off"] *)):is(:active, .ds-pressed)::before {
      opacity: var(--ds-state-hover-lg);
    }
  }

  :where(.ds-ripples) .ds-tree__item:focus-visible:not([aria-disabled="true"]) > .ds-tree__row:where(:not([data-ds-ripple="off"], [data-ds-ripple="off"] *)):is(:active, .ds-pressed)::before {
    opacity: var(--ds-state-focus);
  }

  /* The one chosen row: the tint and the label weight (never the colour alone). */
  .ds-tree__item[aria-selected="true"] > .ds-tree__row {
    background-color: var(--ds-tree-selected-bg, var(--ds-accent));
  }

  .ds-tree__item[aria-selected="true"] > .ds-tree__row > .ds-tree__label {
    font-weight: var(--ds-weight-label);
  }

  /* Blocked: the disabled model, no layer; its focus layer stays. */
  .ds-tree__item[aria-disabled="true"] > .ds-tree__row {
    color: var(--ds-disabled-ink);
    opacity: var(--ds-disabled-opacity);
    cursor: not-allowed;
  }

  .ds-tree__item[aria-disabled="true"] > .ds-tree__row :is(.ds-tree__meta, .ds-tree__icon, .ds-tree__toggle) {
    color: inherit;
  }

  /* The chevron: a quarter turn on the spring while the folder is open. */
  .ds-tree__toggle {
    display: grid;
    flex: none;
    place-items: center;
    width: var(--_toggle);
    height: var(--_toggle);
    color: var(--ds-text-2);
  }

  .ds-tree__toggle > svg {
    width: calc(var(--_toggle) * 2 / 3);
    height: calc(var(--_toggle) * 2 / 3);
    transition: rotate var(--ds-dur-medium) var(--ds-ease-spatial);
  }

  .ds-tree__item[aria-expanded="true"] > .ds-tree__row > .ds-tree__toggle > svg {
    rotate: 90deg;
  }

  /* Children on their way: the spinner (written by DS.tree) takes the chevron's place. */
  .ds-tree__toggle > .ds-tree__spinner {
    display: none;
  }

  .ds-tree__item[aria-busy="true"] > .ds-tree__row > .ds-tree__toggle > svg {
    display: none;
  }

  .ds-tree__item[aria-busy="true"] > .ds-tree__row > .ds-tree__toggle > .ds-tree__spinner {
    display: block;
  }

  /* The checkbox mirrors aria-checked; the row takes the pointer. */
  .ds-tree__check {
    pointer-events: none;
  }

  .ds-tree__icon {
    display: inline-flex;
    flex: none;
    color: var(--ds-text-2);
  }

  /* A second glyph shows while the folder is open (folder, folderOpen). */
  .ds-tree__icon > svg + svg,
  .ds-tree__item[aria-expanded="true"] > .ds-tree__row > .ds-tree__icon > svg:first-child:not(:only-child) {
    display: none;
  }

  .ds-tree__item[aria-expanded="true"] > .ds-tree__row > .ds-tree__icon > svg + svg {
    display: block;
  }

  .ds-tree__label {
    flex: 1 1 auto;
    min-width: 0;
    overflow: hidden;
    font: var(--ds-size-font, var(--ds-font-body));
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  /* A label that is a link reads as the row: the row is the affordance. */
  a.ds-tree__label {
    color: inherit;
    text-decoration: none;
  }

  .ds-tree__meta {
    flex: none;
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
  }

  .ds-tree__error {
    display: inline-flex;
    flex: none;
    align-items: center;
    gap: var(--ds-space-1);
    color: var(--ds-on-error-container);
    font: var(--ds-font-meta);
  }

  .ds-tree__actions {
    display: flex;
    flex: none;
    align-items: center;
    gap: var(--ds-space-1);
    margin-block: calc(-1 * var(--ds-space-1));
  }

  .ds-tree__grip {
    flex: none;
    touch-action: none;
    color: var(--ds-text-2);
  }

  /* Children: indented, with a guide below the folder's toggle. */
  .ds-tree__group {
    position: relative;
    padding-inline-start: var(--_indent);
  }

  .ds-tree__group::before {
    content: '';
    position: absolute;
    inset-block: 0;
    inset-inline-start: calc(var(--_pad) + var(--_toggle) / 2);
    border-inline-start: 1px solid var(--ds-tree-guide, var(--ds-line));
    pointer-events: none;
  }

  .ds-tree__item[aria-expanded="false"] > .ds-tree__group {
    display: none;
  }

  /* Opening and closing glide where the browser animates to auto, as
     .ds-collapsible: a closed group keeps its box at no height, so the
     transition has both ends; content-visibility keeps what it holds out
     of the focus and reading order, and steps at the end of a close. */
  @supports (interpolate-size: allow-keywords) {
    .ds-tree__group {
      interpolate-size: allow-keywords;
      overflow: clip;
      overflow-clip-margin: var(--ds-space-3);
      /* No content-visibility here: an opening group shows its rows at once,
         so the focus can move into it on the same key press. */
      transition:
        height var(--ds-dur-medium) var(--ds-ease-out),
        opacity var(--ds-dur-medium) var(--ds-ease-in-out);
    }

    .ds-tree__item[aria-expanded="false"] > .ds-tree__group {
      display: block;
      height: 0;
      opacity: 0;
      content-visibility: hidden;
      transition:
        height var(--ds-dur-base) var(--ds-ease-in),
        opacity var(--ds-dur-fast) var(--ds-ease-in),
        content-visibility var(--ds-dur-base) allow-discrete;
    }
  }

  /* The place a drag would drop at: a line above a row, below a subtree,
     or the folder's row framed. */
  .ds-tree__item[data-ds-tree-drop="before"] > .ds-tree__row::after,
  .ds-tree__item[data-ds-tree-drop="after"]::after {
    content: '';
    position: absolute;
    inset-inline: 0;
    border-top: 2px solid var(--ds-tree-drop-color, var(--ds-primary));
    pointer-events: none;
  }

  .ds-tree__item[data-ds-tree-drop="before"] > .ds-tree__row::after {
    top: -1px;
  }

  .ds-tree__item[data-ds-tree-drop="after"]::after {
    bottom: -1px;
  }

  .ds-tree__item[data-ds-tree-drop="inside"] > .ds-tree__row {
    outline: 2px solid var(--ds-tree-drop-color, var(--ds-primary));
    outline-offset: -2px;
  }

  /* While it is dragged the item keeps the row's corners for its raised look. */
  .ds-tree__item[data-ds-dragging] {
    border-radius: calc(var(--ds-tree-radius, var(--ds-radius-sm)) * var(--ds-shape, 1));
    background-color: var(--ds-surface);
  }

  @media (forced-colors: active) {
    .ds-tree__item[aria-selected="true"] > .ds-tree__row {
      forced-color-adjust: none;
      background: SelectedItem;
      color: SelectedItemText;
    }

    .ds-tree__item[aria-selected="true"] > .ds-tree__row :is(.ds-tree__meta, .ds-tree__icon, .ds-tree__toggle) {
      color: inherit;
    }

    .ds-tree__item[aria-selected="true"] > .ds-tree__row .ds-tree__actions {
      forced-color-adjust: auto;
    }

    .ds-tree__item[aria-selected="true"]:focus-visible > .ds-tree__row {
      outline-color: CanvasText;
    }

    .ds-tree__item[aria-disabled="true"] > .ds-tree__row {
      color: GrayText;
      opacity: 1;
    }

    .ds-tree__item[data-ds-tree-drop="before"] > .ds-tree__row::after,
    .ds-tree__item[data-ds-tree-drop="after"]::after {
      border-color: Highlight;
    }

    .ds-tree__item[data-ds-tree-drop="inside"] > .ds-tree__row {
      outline-color: Highlight;
    }

    .ds-tree__group::before {
      border-color: GrayText;
    }
  }
}

/* ── components/choices/choices.css ── */
/*
 * Choice list: a set of checkboxes (form.css's .ds-check rows) with what a
 * long set needs: a "select all" box that shows all, none or some
 * (indeterminate), a count, a filter field, columns and a box that scrolls
 * on its own. DS.choices (choices.js) keeps them in step.
 *
 *   <fieldset class="ds-field">
 *     <legend class="ds-field__label">Sites</legend>
 *     <div class="ds-choices ds-choices--columns ds-choices--scroll" data-ds-choices>
 *       <div class="ds-choices__tools">
 *         <input class="ds-input ds-choices__search" type="search" aria-label="Filter sites" placeholder="Filter">
 *         <label class="ds-check"><input type="checkbox" data-ds-choices-all><span>Select all</span></label>
 *         <span class="ds-choices__count"></span>
 *       </div>
 *       <div class="ds-choices__list" role="group" aria-label="Sites">
 *         <label class="ds-check"><input type="checkbox" name="site" value="a"><span>Building A</span></label> ...
 *       </div>
 *       <p class="ds-choices__empty" hidden>No results</p>
 *     </div>
 *   </fieldset>
 *
 * Variants:
 *   .ds-choices--columns  the rows fill columns of at least
 *                         --ds-choices-column-width (180px), at most
 *                         --ds-choices-columns (4), row by row, so the Tab
 *                         order follows the eye
 *   .ds-choices--scroll   the list is an outlined box that scrolls on its
 *                         own beyond --ds-choices-max-height (264px), its
 *                         cut edges fading (--ds-scroll-fade)
 *
 * The filter hides the rows that do not match (`hidden`) and marks the
 * matched letters in a .ds-choices__match (weight and a line, never colour
 * alone); .ds-choices__empty shows when nothing does. A checked row's label
 * takes the label weight.
 *
 * Options (src/core/options.css, docs/options.md): the rows are .ds-check
 * rows and compute size, density and touch themselves; here the gaps and
 * the box: density takes 2px per step off the box's padding; shape
 * multiplies the box's radius. No tone.
 *
 * Forced colours: the scrolling box keeps its border; the marks keep their
 * line in CanvasText.
 *
 * Hooks: --ds-choices-column-width (180px), --ds-choices-columns (4),
 * --ds-choices-max-height (264px), --ds-scroll-fade (scroller.css's). The
 * private --_gap, --_n are computed here: never set them.
 *
 * Progressive:
 * - scrollbar-color and scrollbar-width (a thin, quiet scrollbar): without
 *   them the platform scrollbar shows.
 */

@layer ds.components.choices {
  .ds-choices {
    display: grid;
    gap: var(--ds-space-2);
    min-width: 0;
  }

  /* Filter, "select all" and the count on one line that wraps. */
  .ds-choices__tools {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--ds-space-1) var(--ds-space-4);
  }

  .ds-choices__search {
    flex: 1 1 14rem;
    min-width: 0;
  }

  .ds-choices__count {
    margin-inline-start: auto;
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
    font-variant-numeric: tabular-nums;
  }

  .ds-choices__list {
    display: grid;
    grid-auto-rows: max-content;
    justify-items: start;
    min-width: 0;
  }

  .ds-choices__list > .ds-check[hidden] {
    display: none;
  }

  .ds-choices__list > .ds-check:has(> input:checked) {
    font-weight: var(--ds-weight-label);
  }

  /* Columns, filled row by row, so the Tab order follows the eye; never
     more than --ds-choices-columns, never narrower than the column width
     (one column where two do not fit). A grid, not CSS columns: in a box
     that scrolls, columns would overflow to the side. */
  .ds-choices--columns > .ds-choices__list {
    --_gap: var(--ds-space-6);
    --_n: var(--ds-choices-columns, 4);
    grid-template-columns: repeat(auto-fill, minmax(min(100%, max(var(--ds-choices-column-width, 180px), calc((100% - (var(--_n) - 1) * var(--_gap)) / var(--_n)))), 1fr));
    column-gap: var(--_gap);
    justify-items: stretch;
  }

  /* A long set in a box of its own that scrolls; its cut edges fade. */
  .ds-choices--scroll > .ds-choices__list {
    position: relative;
    max-height: var(--ds-choices-max-height, 264px);
    padding: calc(var(--ds-space-1) + var(--ds-density, 0) * 2px) var(--ds-space-4);
    overflow-y: auto;
    border: 1px solid var(--ds-line);
    border-radius: calc(var(--ds-radius-card) * var(--ds-shape, 1));
    scrollbar-width: thin;
    scrollbar-color: var(--ds-line-2) transparent;
    scroll-padding-block: var(--ds-scroll-fade, var(--ds-space-8));
    mask-image:
      linear-gradient(to bottom, transparent, #000 calc(var(--ds-scroll-edge-start) * var(--ds-scroll-fade, var(--ds-space-8))), #000 calc(100% - var(--ds-scroll-edge-end) * var(--ds-scroll-fade, var(--ds-space-8))), transparent),
      linear-gradient(#000, #000);
    mask-size: calc(100% - var(--ds-scrollbar-width, 0px)) 100%, var(--ds-scrollbar-width, 0px) 100%;
    mask-position: 0 0, 100% 0;
    mask-repeat: no-repeat;
  }

  /* The fades glide only once DS.dom.scrollEdges() has measured. */
  .ds-choices--scroll > .ds-choices__list[data-ds-edges] {
    transition:
      --ds-scroll-edge-start var(--ds-dur-fast) var(--ds-ease-in-out),
      --ds-scroll-edge-end var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  .ds-choices--scroll > .ds-choices__list[data-ds-overflow-start] {
    --ds-scroll-edge-start: 1;
  }

  .ds-choices--scroll > .ds-choices__list[data-ds-overflow-end] {
    --ds-scroll-edge-end: 1;
  }

  /* The letters the filter matched: weight and a line, not colour. */
  .ds-choices__match {
    background: transparent;
    color: inherit;
    font-weight: var(--ds-weight-label);
    text-decoration: underline;
    text-decoration-thickness: var(--ds-link-underline-thickness);
    text-underline-offset: var(--ds-link-underline-offset);
  }

  .ds-choices__empty {
    margin: 0;
    padding-block: var(--ds-space-2);
    color: var(--ds-text-2);
    font: var(--ds-font-body);
  }

  .ds-choices__empty[hidden] {
    display: none;
  }

  @media (forced-colors: active) {
    .ds-choices--scroll > .ds-choices__list {
      border-color: CanvasText;
    }

    .ds-choices__match {
      text-decoration-color: CanvasText;
    }
  }
}

/* ── components/jsonview/jsonview.css ── */
/*
 * JSON viewer (3.0): a JSON document as a tree that opens and closes, on
 * the tree view (.ds-tree, DS.tree), with a search bar. DS.jsonview
 * (jsonview.js) writes everything inside the element from the JSON.
 *
 *   <div class="ds-jsonview" role="region" data-ds-jsonview aria-label="Response of GET /devices/42">
 *     <script type="application/json">{ "id": 42, "name": "LAPTOP-0042" }</script>
 *   </div>
 *
 * What the module writes:
 *   <div class="ds-jsonview__bar">
 *     <span class="ds-jsonview__search"><input class="ds-input ds-jsonview__find" type="search" aria-label="Search keys and values">
 *       <span class="ds-jsonview__count">2 of 5</span> [previous] [next]</span> [expand all] [collapse all]
 *   </div>
 *   <p class="ds-jsonview__error" role="alert" hidden>[icon alertCircle] Not valid JSON: line 3, column 7.</p>
 *   <ul class="ds-tree ds-jsonview__tree" role="tree">
 *     <li class="ds-tree__item" role="treeitem" aria-expanded="false" data-ds-key="..."><div class="ds-tree__row">
 *       <span class="ds-tree__toggle">[icon chevronRight]</span>
 *       <span class="ds-tree__label"><span class="ds-jsonview__key">owner</span><span class="ds-jsonview__punct">: </span><span class="ds-jsonview__value ds-jsonview__value--object">{…}</span></span>
 *       <span class="ds-tree__meta">3 keys</span>
 *       <span class="ds-tree__actions ds-jsonview__actions">[copy value] [copy path]</span></div></li>
 *   </ul>
 *
 * Parts: an outlined block (--ds-jsonview-radius) with the bar on top and
 * the rows below, which scroll inside it past --ds-jsonview-max-height.
 * A row is a tree row in the code font: the key, ": ", the value; a value
 * says its type in its text as JSON writes it (quotes around a string,
 * the words true, false and null, braces and brackets around a container)
 * and in its colour (.ds-jsonview__value--string, --number, --boolean,
 * --null, --object, --array; hooks per type). A long value wraps. A
 * container's row ends in its size (3 keys, 120 items); one of more than
 * 100 entries opens into ranges (.ds-jsonview__range, "[0 … 99]"). A
 * search hit is a <mark class="ds-jsonview__mark">; the current match is
 * the tree's chosen row. The copy buttons (.ds-jsonview__actions) show on
 * the row the pointer is over, the focused row and the chosen row, and
 * always under a coarse pointer without hover.
 *
 * Options (src/core/options.css, docs/options.md): those of the tree view
 * (size, density, shape, touch) on its rows, from a 32px row
 * (--ds-jsonview-row-height) and a 16px indent; the text stays the code
 * font at every size. The bar's field and buttons follow their own
 * components. Tone: none; .ds-jsonview__error says what failed in words.
 *
 * Hooks: --ds-jsonview-row-height (32px), --ds-jsonview-indent (16px),
 * --ds-jsonview-max-height (none), --ds-jsonview-radius
 * (--ds-radius-card), --ds-jsonview-key (--ds-text),
 * --ds-jsonview-string (--ds-on-success-container), --ds-jsonview-number
 * (--ds-on-info-container), --ds-jsonview-boolean
 * (--ds-on-warning-container), --ds-jsonview-null (--ds-text-2),
 * --ds-jsonview-mark-bg (--ds-warning-container).
 *
 * Forced colours: the type colours give way to CanvasText (the syntax
 * still tells the types apart), a mark is Highlight / HighlightText, the
 * block keeps its border.
 */

@layer ds.components.jsonview {
  .ds-jsonview {
    --ds-tree-row-height: var(--ds-jsonview-row-height, 32px);
    --ds-tree-indent: var(--ds-jsonview-indent, 16px);
    display: flex;
    flex-direction: column;
    gap: var(--ds-space-2);
    box-sizing: border-box;
    min-width: 0;
    max-block-size: var(--ds-jsonview-max-height, none);
    padding: var(--ds-space-2);
    border: 1px solid var(--ds-line);
    border-radius: calc(var(--ds-jsonview-radius, var(--ds-radius-card)) * var(--ds-shape, 1));
    background: var(--ds-surface);
    color: var(--ds-text);
  }

  /* One line down to a phone: the field gives way, the buttons stay. */
  .ds-jsonview__bar {
    display: flex;
    align-items: center;
    gap: var(--ds-space-1);
  }

  .ds-jsonview__bar[hidden] {
    display: none;
  }

  .ds-jsonview__search {
    display: flex;
    flex: 1 1 0;
    align-items: center;
    gap: var(--ds-space-1);
    min-width: 0;
  }

  .ds-jsonview__find {
    flex: 1 1 auto;
    min-width: 6rem;
  }

  .ds-jsonview__bar > .ds-btn {
    flex: none;
  }

  .ds-jsonview__count {
    flex: none;
    min-width: 4em;
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
    font-variant-numeric: tabular-nums;
    text-align: center;
    white-space: nowrap;
  }

  .ds-jsonview__count:empty {
    display: none;
  }

  .ds-jsonview__error {
    display: flex;
    align-items: center;
    gap: var(--ds-space-2);
    margin: 0;
    padding: var(--ds-space-2) var(--ds-space-3);
    border-radius: calc(var(--ds-radius-sm) * var(--ds-shape, 1));
    background: var(--ds-error-container);
    color: var(--ds-on-error-container);
    font: var(--ds-font-body);
  }

  .ds-jsonview__error[hidden] {
    display: none;
  }

  .ds-jsonview__error > svg {
    flex: none;
  }

  .ds-jsonview__tree {
    position: relative;
    min-height: 0;
    overflow: auto;
    overscroll-behavior: contain;
  }

  /* The code font at every size; a long value wraps instead of hiding. */
  .ds-jsonview .ds-tree__label {
    font: var(--ds-font-code);
    white-space: normal;
    overflow-wrap: anywhere;
  }

  .ds-jsonview__key {
    color: var(--ds-jsonview-key, var(--ds-text));
    font-weight: var(--ds-weight-label);
  }

  .ds-jsonview__punct,
  .ds-jsonview__range {
    color: var(--ds-text-2);
  }

  .ds-jsonview__value--string {
    color: var(--ds-jsonview-string, var(--ds-on-success-container));
  }

  .ds-jsonview__value--number {
    color: var(--ds-jsonview-number, var(--ds-on-info-container));
    font-variant-numeric: tabular-nums;
  }

  .ds-jsonview__value--boolean {
    color: var(--ds-jsonview-boolean, var(--ds-on-warning-container));
  }

  .ds-jsonview__value--null {
    color: var(--ds-jsonview-null, var(--ds-text-2));
    font-style: italic;
  }

  .ds-jsonview__value--object,
  .ds-jsonview__value--array {
    color: var(--ds-text-2);
  }

  .ds-jsonview__mark {
    border-radius: calc(var(--ds-radius-xs) * var(--ds-shape, 1));
    background: var(--ds-jsonview-mark-bg, var(--ds-warning-container));
    color: var(--ds-on-warning-container);
  }

  /* The copy buttons: on the row in use, so a long document stays calm. */
  .ds-jsonview__actions {
    opacity: 0;
    transition: opacity var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  .ds-tree__item:is(:focus-visible, [aria-selected="true"]) > .ds-tree__row > .ds-jsonview__actions,
  .ds-jsonview__actions:focus-within {
    opacity: 1;
  }

  @media (hover: hover) {
    .ds-tree__row:hover > .ds-jsonview__actions {
      opacity: 1;
    }
  }

  @media (hover: none) {
    .ds-jsonview__actions {
      opacity: 1;
    }
  }

  @media (forced-colors: active) {
    .ds-jsonview__value,
    .ds-jsonview__key,
    .ds-jsonview__punct,
    .ds-jsonview__range {
      color: CanvasText;
    }

    .ds-tree__item[aria-selected="true"] > .ds-tree__row .ds-jsonview__value,
    .ds-tree__item[aria-selected="true"] > .ds-tree__row .ds-jsonview__key,
    .ds-tree__item[aria-selected="true"] > .ds-tree__row .ds-jsonview__punct {
      color: inherit;
    }

    .ds-jsonview__mark {
      forced-color-adjust: none;
      background: Highlight;
      color: HighlightText;
    }

    .ds-jsonview__error {
      border: 1px solid CanvasText;
    }
  }
}

/* ── components/password/password.css ── */
/*
 * Password: a password field (an input group of form.css) with a reveal
 * button, a strength meter under it and a caps-lock hint, each optional.
 *
 *   <div class="ds-field" data-ds-password>
 *     <label class="ds-field__label" for="pw">New password</label>
 *     <div class="ds-input-group">
 *       <input class="ds-input" id="pw" type="password" autocomplete="new-password" minlength="12" aria-describedby="pw-strength pw-caps">
 *       <span class="ds-input-group__trailing"><button class="ds-btn ds-btn--quiet ds-btn--icon ds-sm" type="button"
 *         aria-label="Show password" aria-pressed="false">(icon swap: eye, eyeOff)</button></span>
 *     </div>
 *     <div class="ds-password__meter" id="pw-strength">
 *       <span class="ds-password__bars" aria-hidden="true"><span></span><span></span><span></span><span></span></span>
 *       <span class="ds-password__strength"></span>
 *     </div>
 *     <small class="ds-field__hint ds-field__hint--warning ds-password__caps" id="pw-caps" hidden>(alert 16)Caps Lock is on.</small>
 *   </div>
 *
 * The meter: four bars and the level in words beside them, so the level
 * never shows by colour alone; DS.password writes data-level (0 to 4) on
 * .ds-password__meter and the words. Level 1 fills one bar in the error
 * colour, 2 two in the warning colour, 3 and 4 three and four in the
 * success colour; an empty bar is --ds-line. The meter always
 * takes its room, so the form below never jumps while a password is typed.
 * A bar's colour changes on --ds-dur-fast.
 *
 * The caps-lock hint is a warning hint of form.css, shown by DS.password
 * while Caps Lock is on (hidden hides it here, whatever the hint's own
 * display). The reveal is an icon button with aria-pressed in the group's
 * trailing slot; its icon swap follows aria-pressed (button.css).
 *
 * Options (src/core/options.css, docs/options.md): size, density, shape
 * and touch apply to the field and the reveal button as in form.css and
 * button.css; the bars' corners follow --ds-shape. The meter's type is
 * --ds-font-meta at every size. No tone: the level is the meaning.
 *
 * Hooks: --ds-password-bar-height (4px), --ds-password-meter-width
 * (the bars' widest, 240px).
 *
 * Forced colours: a filled bar is CanvasText, an empty one a CanvasText
 * outline; the word says the level.
 */

@layer ds.components.password {
  .ds-password__meter {
    display: flex;
    align-items: center;
    gap: var(--ds-space-3);
    min-height: var(--ds-space-5);
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
  }

  .ds-password__bars {
    display: grid;
    flex: 1 1 auto;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: var(--ds-space-1);
    max-inline-size: var(--ds-password-meter-width, 240px);
  }

  .ds-password__bars > span {
    block-size: var(--ds-password-bar-height, 4px);
    border-radius: calc(var(--ds-radius-xs) * var(--ds-shape, 1));
    background: var(--ds-line);
    transition: background-color var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  .ds-password__meter[data-level="1"] .ds-password__bars > :nth-child(-n + 1) {
    background: var(--ds-error);
  }

  .ds-password__meter[data-level="2"] .ds-password__bars > :nth-child(-n + 2) {
    background: var(--ds-warning);
  }

  .ds-password__meter[data-level="3"] .ds-password__bars > :nth-child(-n + 3),
  .ds-password__meter[data-level="4"] .ds-password__bars > span {
    background: var(--ds-success);
  }

  .ds-password__strength {
    flex: none;
    font-variant-numeric: tabular-nums;
  }

  /* A warning hint lays itself out (display: flex); hidden still hides it. */
  .ds-password__caps[hidden] {
    display: none;
  }

  @media (forced-colors: active) {
    .ds-password__bars > span {
      forced-color-adjust: none;
      outline: 1px solid CanvasText;
      outline-offset: -1px;
      background: Canvas;
    }

    .ds-password__meter[data-level="1"] .ds-password__bars > :nth-child(-n + 1),
    .ds-password__meter[data-level="2"] .ds-password__bars > :nth-child(-n + 2),
    .ds-password__meter[data-level="3"] .ds-password__bars > :nth-child(-n + 3),
    .ds-password__meter[data-level="4"] .ds-password__bars > span {
      background: CanvasText;
    }
  }
}

/* ── components/auditlog/auditlog.css ── */
/*
 * Audit log (3.0): who did what, when, and what changed, grouped by day.
 * Built from the timeline (.ds-timeline--activity, day headings, the
 * activity sentence with its avatar marker) and a description list of the
 * changed fields, old to new; a filter bar above it. DS.auditlog
 * (auditlog.js) draws it from the page's records and filters it by the
 * page's own controls; a page that renders on the server writes the same
 * markup itself.
 *
 *   <section class="ds-auditlog" aria-label="Audit log" data-ds-auditlog>
 *     <div class="ds-auditlog__filters" role="group" aria-label="Filter the log">
 *       [a .ds-search field, selects, .ds-chips, each data-ds-auditlog-filter="<name>"]
 *       <p class="ds-auditlog__count">12 of 48 events</p>
 *     </div>
 *     <ol class="ds-timeline ds-timeline--activity" role="list" aria-label="Events">
 *       <li class="ds-timeline__group" role="presentation"><h3 class="ds-timeline__day">Today</h3></li>
 *       <li class="ds-timeline__item ds-timeline__item--icon" data-ds-key="e81">
 *         <span class="ds-timeline__marker" aria-hidden="true">AL</span>
 *         <div class="ds-timeline__head">
 *           <p class="ds-timeline__title"><strong>Ada Lovelace</strong> changed <a href="/devices/42">LAPTOP-0042</a></p>
 *           <time class="ds-timeline__time" datetime="2026-10-12T14:05:00.000Z">14:05</time>
 *         </div>
 *         <p class="ds-auditlog__source">Web · 10.20.4.17</p>
 *         <dl class="ds-auditlog__diff">
 *           <div class="ds-auditlog__change"><dt>Owner</dt>
 *             <dd class="ds-auditlog__old"><span class="ds-sr">Before: </span><del>Grace Hopper</del></dd>
 *             <dd class="ds-auditlog__new"><span class="ds-sr">After: </span><ins>Ada Lovelace</ins></dd></div>
 *         </dl>
 *       </li>
 *     </ol>
 *     <div class="ds-empty" data-ds-auditlog-empty hidden> ... </div>
 *   </section>
 *
 * Parts: .ds-auditlog__filters (a wrapping bar for the page's chips,
 * selects and search; .ds-auditlog__count at its end in the meta font);
 * .ds-auditlog__source (where the change came from: a channel, an
 * address, in the meta font; a leading 16px icon sits on its line);
 * .ds-auditlog__diff, one .ds-auditlog__change per field: the field (dt),
 * the old value (.ds-auditlog__old, struck through, a quiet error tint)
 * and the new one (.ds-auditlog__new, underlined, a quiet success tint),
 * an arrow between (drawn by the row, with no text for a reader); a value
 * that was not set is .ds-auditlog__none (in words: "Not set"). Never
 * colour alone: the strike, the underline and the .ds-sr words "Before:"
 * and "After:" say which is which. Past `limit` entries (200) DS.auditlog
 * writes a .ds-btn.ds-auditlog__more under the list that draws the next
 * ones. Under 520px of the log's width the
 * field goes above its values, the old above the new. A hidden part (the
 * list with nothing to show, the empty state while there is) takes no
 * room, also without .ds-base.
 *
 * Options (src/core/options.css, docs/options.md), on the log or any
 * ancestor; each is computed here, in the rule that uses it:
 *   size      the timeline's (marker, title); a change row's block padding
 *             2px per step, the values in the body font at every size
 *   density   .ds-density-*: a change row's block padding 2px per step,
 *             the filter bar's gap 2px per step
 *   shape     .ds-shape-*: multiplies the radius of the diff and the tints
 *   tone      none of its own: an entry's status is a .ds-status in its
 *             head line (an icon and a word)
 *
 * Hooks: --ds-auditlog-field-width (10rem), --ds-auditlog-old-bg
 * (--ds-error-container), --ds-auditlog-new-bg (--ds-success-container),
 * --ds-auditlog-diff-radius (--ds-radius-sm).
 *
 * Forced colours: the tints give way; the strike and the underline stay,
 * and the values keep a transparent border that becomes their edge.
 */

@layer ds.components.auditlog {
  .ds-auditlog {
    container: ds-auditlog / inline-size;
    display: grid;
    gap: var(--ds-space-4);
    min-width: 0;
  }

  /* What DS.auditlog hides: the list without entries, the empty state
     while there are some (both have a display of their own). */
  .ds-auditlog > [hidden] {
    display: none;
  }

  .ds-auditlog__filters {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: max(var(--ds-space-1), calc(var(--ds-space-2) + var(--ds-density, 0) * 2px));
    margin: 0;
  }

  /* The search takes the room the other filters leave. */
  .ds-auditlog__filters > .ds-search {
    flex: 1 1 14rem;
  }

  /* A select or a date field takes its own width, not the row's. */
  .ds-auditlog__filters > .ds-input {
    flex: 0 1 auto;
    inline-size: auto;
    min-inline-size: 0;
  }

  .ds-auditlog__count {
    margin-block: 0;
    margin-inline: auto 0;
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
    font-variant-numeric: tabular-nums;
  }

  .ds-auditlog__source {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--ds-space-1);
    margin: var(--ds-space-1) 0 0;
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
  }

  .ds-auditlog__source > svg {
    flex: none;
  }

  /* The changed fields: field, old, arrow, new. */
  .ds-auditlog__diff {
    display: grid;
    grid-template-columns: minmax(0, var(--ds-auditlog-field-width, 10rem)) fit-content(40%) auto minmax(0, 1fr);
    margin: var(--ds-space-2) 0 0;
    max-width: var(--ds-measure);
    border: 1px solid var(--ds-line);
    border-radius: calc(var(--ds-auditlog-diff-radius, var(--ds-radius-sm)) * var(--ds-shape, 1));
    font: var(--ds-font-body);
  }

  .ds-auditlog__change {
    --_pad: max(var(--ds-space-1), calc(var(--ds-space-2) + var(--ds-size-step, 0) * 2px + var(--ds-density, 0) * 2px));
    display: grid;
    grid-column: 1 / -1;
    grid-template-columns: subgrid;
    align-items: baseline;
    column-gap: var(--ds-space-2);
    padding: var(--_pad) var(--ds-space-3);
    border-top: 1px solid var(--ds-line);
  }

  .ds-auditlog__change:first-child {
    border-top: 0;
  }

  .ds-auditlog__change > dt {
    color: var(--ds-text-2);
    overflow-wrap: anywhere;
  }

  .ds-auditlog__old,
  .ds-auditlog__new {
    justify-self: start;
    margin: 0;
    padding: 0 var(--ds-space-1);
    border: 1px solid transparent;
    border-radius: calc(var(--ds-radius-xs) * var(--ds-shape, 1));
    overflow-wrap: anywhere;
  }

  .ds-auditlog__old {
    background: var(--ds-auditlog-old-bg, var(--ds-error-container));
    color: var(--ds-on-error-container);
  }

  .ds-auditlog__new {
    background: var(--ds-auditlog-new-bg, var(--ds-success-container));
    color: var(--ds-on-success-container);
  }

  .ds-auditlog__old :is(del, s) {
    text-decoration-thickness: var(--ds-link-underline-thickness);
  }

  /* The underline of the new value has the links' geometry. */
  .ds-auditlog__new ins {
    text-decoration: underline;
    text-decoration-thickness: var(--ds-link-underline-thickness);
    text-underline-offset: var(--ds-link-underline-offset);
  }

  /* The arrow between old and new: drawn, not read (the words say it). */
  .ds-auditlog__change::after {
    content: '→' / '';
    grid-row: 1;
    grid-column: 3;
    color: var(--ds-text-2);
  }

  .ds-auditlog__change > .ds-auditlog__new {
    grid-row: 1;
    grid-column: 4;
  }

  /* A value that was not set: in words, quietly, and without the tint (it
     is neither what went nor what came). */
  .ds-auditlog__old:has(> .ds-auditlog__none),
  .ds-auditlog__new:has(> .ds-auditlog__none) {
    background: transparent;
  }

  /* A value that was not set: in words, quietly. */
  .ds-auditlog__none {
    color: var(--ds-text-2);
    font-style: italic;
  }

  /* The button that draws the next entries past the limit: under the
     list, at the start of the timeline's column. */
  .ds-auditlog__more {
    justify-self: start;
  }

  /* Narrow: the field above its values, the old above the new. */
  @container ds-auditlog (max-width: 520px) {
    .ds-auditlog__diff {
      grid-template-columns: minmax(0, 1fr);
    }

    .ds-auditlog__change {
      grid-template-columns: minmax(0, 1fr);
      row-gap: var(--ds-space-1);
    }

    .ds-auditlog__change > .ds-auditlog__new {
      grid-row: auto;
      grid-column: auto;
    }

    .ds-auditlog__change::after {
      display: none;
    }

    .ds-auditlog__count {
      flex-basis: 100%;
      margin-inline-start: 0;
    }
  }

  @media (forced-colors: active) {
    .ds-auditlog__old,
    .ds-auditlog__new {
      border-color: CanvasText;
    }
  }
}

/* ── components/secret/secret.css ── */
/*
 * Secret field: a value the server keeps and never sends back. While one is
 * stored the field shows a mask and "Set" in a read-only box, with Replace
 * and Clear; replacing shows an empty password field with Cancel; clearing
 * strikes the mask through and says "Removed when you save", with Undo.
 *
 *   <div class="ds-field ds-secret" data-ds-secret="set">
 *     <label class="ds-field__label" for="key">API key</label>
 *     <div class="ds-secret__stored">
 *       <span class="ds-secret__mask" aria-hidden="true">••••••••</span>
 *       <span class="ds-secret__status"></span>
 *       <span class="ds-secret__actions">
 *         <button class="ds-btn ds-btn--text ds-secret__replace" type="button">Replace</button>
 *         <button class="ds-btn ds-btn--text ds-secret__clear" type="button">Clear</button>
 *         <button class="ds-btn ds-btn--text ds-secret__undo" type="button">Undo</button>
 *       </span>
 *     </div>
 *     <div class="ds-secret__entry">
 *       <div class="ds-input-group"><input class="ds-input" id="key" name="api_key" type="password" autocomplete="off"></div>
 *       <button class="ds-btn ds-btn--text ds-secret__cancel" type="button">Cancel</button>
 *     </div>
 *     <input type="hidden" name="api_key_action" data-ds-secret-action>
 *   </div>
 *
 * data-state (empty, set, replace, clear) is written by DS.secret
 * (secret.js) and decides which parts show. Before the script runs (no
 * data-state) only the entry shows: a plain password field that still
 * works.
 *
 * The stored box is a field's box in the read-only look (--ds-surface-low,
 * a --ds-line edge, the field's height, corners and padding with every
 * option); its buttons are text buttons at its end, which wrap under the
 * mask in a narrow field. The status is words, never colour alone; while
 * clearing they take the warning ink and the mask is struck through.
 *
 * Options (src/core/options.css, docs/options.md), on the field or any
 * ancestor, computed here for the stored box as for a field (form.css):
 *   size      .ds-xs ... .ds-xl: 8px of height per step, 4px of padding
 *   density   .ds-density-*: 4px of height per step
 *   shape     .ds-shape-*: the box's corners (the field's radius)
 *   touch     .ds-touch: at least --ds-touch-target high
 * No tone.
 *
 * Hooks: the field's (--ds-input-height, --ds-input-padding-x,
 * --ds-input-radius; form.css) and --ds-field-warning-color.
 *
 * Forced colours: the box keeps its edge (a border, CanvasText); the
 * struck mask and the words say the state.
 */

@layer ds.components.secret {
  .ds-secret__stored {
    --_h: calc(var(--ds-input-height, 40px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px);
    --_box: max(var(--ds-target-min, 0px), var(--_h));
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0 var(--ds-space-3);
    min-width: 0;
    min-height: var(--_box);
    position: relative;
    padding-inline: calc(var(--ds-input-padding-x, var(--ds-space-3)) + var(--ds-size-step, 0) * 4px) var(--ds-space-1);
    border-radius: min(calc(var(--ds-input-radius, var(--ds-radius-field)) * var(--ds-shape, 1)), calc(var(--_box) / 2));
    background: var(--ds-surface-low);
    color: var(--ds-text);
  }

  /* The edge lies over the content, so the buttons take the box's whole
     height at every size and under .ds-touch without growing it. */
  .ds-secret__stored::after {
    content: "";
    position: absolute;
    inset: 0;
    border: 1px solid var(--ds-line);
    border-radius: inherit;
    pointer-events: none;
  }

  /* The text buttons follow the field: 8px lower than it at every size and
     density, never under the touch minimum (button.css computes it). */
  .ds-secret__actions > .ds-btn {
    --ds-btn-height: calc(var(--ds-input-height, 40px) - 8px);
  }

  .ds-secret__mask {
    color: var(--ds-text-2);
    font: var(--ds-input-font, var(--ds-size-font, var(--ds-font-body)));
    user-select: none;
  }

  .ds-secret__status {
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
  }

  .ds-secret__actions {
    display: inline-flex;
    flex-wrap: wrap;
    gap: var(--ds-space-1);
    margin-inline-start: auto;
  }

  .ds-secret__entry {
    display: flex;
    align-items: center;
    gap: var(--ds-space-2);
    min-width: 0;
  }

  .ds-secret__entry > :first-child {
    flex: 1 1 auto;
    min-width: 0;
  }

  .ds-secret__entry > .ds-btn {
    flex: none;
  }

  /* Which parts show in which state; before the script runs, only the entry. */
  .ds-secret:not([data-state="set"], [data-state="clear"]) > .ds-secret__stored,
  .ds-secret:is([data-state="set"], [data-state="clear"]) > .ds-secret__entry,
  .ds-secret:not([data-state="set"]) .ds-secret__replace,
  .ds-secret:not([data-state="set"]) .ds-secret__clear,
  .ds-secret:not([data-state="clear"]) .ds-secret__undo,
  .ds-secret:not([data-state="replace"]) .ds-secret__cancel {
    display: none;
  }

  .ds-secret[data-state="clear"] .ds-secret__mask {
    text-decoration: line-through;
  }

  .ds-secret[data-state="clear"] .ds-secret__status {
    color: var(--ds-field-warning-color, var(--ds-on-warning-container));
  }

  @media (forced-colors: active) {
    .ds-secret__stored::after {
      border-color: CanvasText;
    }
  }
}

/* ── components/taginput/taginput.css ── */
/*
 * Tag input: free values typed into one field box, each an input chip
 * before the typing field (labels, recipients, keywords). DS.taginput
 * (taginput.js) turns Enter, a comma and a pasted list into tags, checks
 * them (unique, `validate`, a pattern, a maximum) and removes them by
 * Backspace, Delete or a press on the chip.
 *
 *   <div class="ds-field">
 *     <label class="ds-field__label" for="labels">Labels</label>
 *     <div class="ds-taginput" data-ds-taginput data-ds-taginput-max="8" data-ds-value='["printer","floor-2"]'>
 *       <input class="ds-input ds-taginput__input" id="labels" aria-describedby="labels-hint">
 *     </div>
 *     <p class="ds-field__hint" id="labels-hint">Enter or a comma adds a label.</p>
 *   </div>
 *
 * The module writes the chips (button.ds-chip.ds-chip--input with
 * data-ds-taginput-tag, "Remove" and the name for a screen reader) before
 * the field and a .ds-taginput__message (role="status") after the box,
 * which says why a tag was refused (an icon and the words, never colour
 * alone; the field takes aria-invalid until the text changes).
 *
 * The box is the field (form.css's look and hooks: --ds-input-border,
 * --ds-input-bg, --ds-input-radius, --ds-input-focus-color): hover, focus,
 * error, disabled and read-only show on the box; the typing field inside is
 * only text. .ds-taginput--full (written by the module at the maximum)
 * keeps the field but quiets its cursor.
 *
 * Options (src/core/options.css, docs/options.md), on the box or any
 * ancestor; each is computed here, in the rule that uses it:
 *   size      .ds-xs ... .ds-xl: the box 8px per step (40px at md, at
 *             least --ds-space-6), as a field; the chips follow their own size
 *   density   .ds-density-*: the box 4px per step; side padding stays
 *   shape     .ds-shape-*: multiplies the box's radius
 *   touch     .ds-touch: the box at least --ds-touch-target (48px)
 *   tone      none on the box: an error is aria-invalid with its message
 *
 * Motion: a tag that comes fades in, and one that goes leaves while the
 * others glide into its place (DS.motion.flip); the message fades in over
 * --ds-dur-fast.
 *
 * Forced colours: the box keeps its border and takes the 2px Highlight
 * outline of a focused field; disabled is GrayText; input chips keep their
 * edge (chip.css).
 *
 * Hooks: --ds-input-height (40px), --ds-input-border, --ds-input-bg,
 * --ds-input-radius, --ds-input-focus-color (form.css's). The private
 * --_h, --_box are computed here: never set them.
 */

@layer ds.components.taginput {
  .ds-taginput {
    /* The field's formula (form.css), never less than a line of the field. */
    --_h: max(var(--ds-space-6), calc(var(--ds-input-height, 40px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px));
    --_box: max(var(--ds-target-min, 0px), var(--_h));
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--ds-space-1);
    min-height: var(--_box);
    padding-inline: var(--ds-space-1);
    border: 1px solid var(--ds-input-border, var(--ds-outline));
    border-radius: calc(var(--ds-input-radius, var(--ds-radius-field)) * var(--ds-shape, 1));
    background: var(--ds-input-bg, var(--ds-surface));
    cursor: text;
    transition:
      border-color var(--ds-dur-fast) var(--ds-ease-in-out),
      background-color var(--ds-dur-fast) var(--ds-ease-in-out),
      box-shadow var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  /* Room around the chips only: empty, the box is the field's height. */
  .ds-taginput:has(> .ds-chip) {
    padding-block: calc(var(--ds-space-1) - 1px);
  }

  /* The typing field is only text in the box. No border at all: forced
     colours would paint a transparent one as a second box. */
  .ds-taginput > .ds-taginput__input,
  .ds-taginput > .ds-taginput__input:focus,
  .ds-taginput > .ds-taginput__input:disabled,
  .ds-taginput > .ds-taginput__input[readonly],
  .ds-taginput > .ds-taginput__input[aria-invalid="true"] {
    flex: 1 1 8ch;
    width: auto;
    min-width: 8ch;
    min-height: calc(var(--_box) - 2 * var(--ds-space-1));
    padding-block: 0;
    padding-inline: var(--ds-space-2);
    border: 0;
    outline: none;
    background: transparent;
    box-shadow: none;
  }

  @media (hover: hover) {
    .ds-taginput:hover:not(:has(> .ds-taginput__input:is(:focus, :disabled, [readonly], [aria-invalid="true"]))) {
      border-color: var(--ds-text);
    }

    .ds-taginput:hover:has(> .ds-taginput__input[aria-invalid="true"]:not(:focus, :disabled, [readonly])) {
      border-color: var(--ds-on-error-container);
    }
  }

  .ds-taginput:has(> .ds-taginput__input:focus) {
    border-color: var(--ds-input-focus-color, var(--ds-primary));
    box-shadow: inset 0 0 0 1px var(--ds-input-focus-color, var(--ds-primary));
    transition-duration: 0s;
  }

  .ds-taginput:has(> .ds-taginput__input[aria-invalid="true"]) {
    border-color: var(--ds-error);
  }

  .ds-taginput:has(> .ds-taginput__input[aria-invalid="true"]:focus) {
    border-color: var(--ds-error);
    box-shadow: inset 0 0 0 1px var(--ds-error);
  }

  .ds-taginput:has(> .ds-taginput__input:is(:disabled, [readonly])) {
    border-color: var(--ds-line);
    background: var(--ds-surface-low);
    cursor: default;
  }

  .ds-taginput:has(> .ds-taginput__input:disabled) {
    cursor: not-allowed;
  }

  /* The chips of a disabled box take no pointer (the module disables their buttons too). */
  .ds-taginput:has(> .ds-taginput__input:disabled) > .ds-chip {
    pointer-events: none;
  }

  /* A read-only box only shows its tags. */
  .ds-taginput:has(> .ds-taginput__input[readonly]) > .ds-chip {
    pointer-events: none;
  }

  /* At the maximum the field stays (Backspace still removes), quieter. */
  .ds-taginput--full > .ds-taginput__input::placeholder {
    color: transparent;
  }

  .ds-form--rows .ds-field > .ds-taginput {
    max-width: var(--ds-form-rows-control-max, 480px);
  }

  /* Why a tag was refused: an icon and the words, under the box. */
  .ds-taginput__message {
    display: flex;
    align-items: flex-start;
    gap: var(--ds-space-1);
    margin: var(--ds-space-1) 0 0;
    color: var(--ds-error);
    font: var(--ds-font-meta);
    animation: ds-fade-in var(--ds-dur-fast) var(--ds-ease-in-out) both;
  }

  .ds-taginput__message:empty {
    display: none;
  }

  .ds-taginput__message > svg {
    flex: none;
    margin-block-start: 2px;
  }

  @media (forced-colors: active) {
    .ds-taginput:has(> .ds-taginput__input:focus) {
      border-color: Highlight;
      outline: 2px solid Highlight;
      outline-offset: -2px;
    }

    .ds-taginput:has(> .ds-taginput__input:disabled) {
      border-color: GrayText;
      color: GrayText;
    }

    .ds-taginput__message {
      color: CanvasText;
    }
  }
}

/* ── components/otp/otp.css ── */
/*
 * One-time code and PIN: a row of single-character cells. Each cell is a
 * field of form.css (border, ring, invalid, disabled, the 16px text on
 * phones); this file makes it a square-ish box with the character centred
 * and lays the row out.
 *
 *   <div class="ds-field">
 *     <span class="ds-field__label" id="code-l">Verification code</span>
 *     <div class="ds-otp" role="group" aria-labelledby="code-l" data-ds-otp>   (data-ds-otp-mask: a PIN)
 *       <input class="ds-input ds-otp__cell" inputmode="numeric" autocomplete="one-time-code">
 *       <input class="ds-input ds-otp__cell" inputmode="numeric" autocomplete="off"> ...
 *       <span class="ds-otp__sep" aria-hidden="true"></span>   (a gap between two groups: 3 + 3)
 *       <input type="hidden" name="code">
 *     </div>
 *   </div>
 *
 * An invalid code: aria-invalid="true" on the group, which DS.otp copies to
 * every cell (form.css draws a field's error look on each), with the
 * field's error hint in words.
 * disabled on the cells (or a disabled fieldset) quiets them.
 *
 * Behaviour (auto-advance, paste, the keys, naming the cells, the hidden
 * value) is DS.otp (otp.js).
 *
 * Options (src/core/options.css, docs/options.md), on the row or any
 * ancestor; computed here for the cells:
 *   size      .ds-xs ... .ds-xl: the field's 8px of height per step, and
 *             8px of width per step (in a narrow container a cell gives
 *             up to 40% of its width; on a phone the gaps are 4px)
 *   density   .ds-density-*: 4px of height per step, and 2px less gap
 *   shape     .ds-shape-*: the cells' corners (the field's radius)
 *   touch     .ds-touch: cells at least --ds-touch-target high and as wide
 *             where there is room (60% of it in a narrow row, so eight
 *             cells fit a phone)
 * No tone: an error shows through aria-invalid and a hint in words.
 *
 * Hooks: --ds-otp-cell-width (40px at md), --ds-otp-gap (8px),
 * --ds-otp-font (the character: --ds-font-subtitle; never under 16px).
 *
 * Forced colours: the cells are fields (form.css: the system's edge, a
 * Highlight outline on focus); the separator is a CanvasText dash.
 */

@layer ds.components.otp {
  .ds-otp {
    display: flex;
    /* A long code in a narrow container: the cells give up to 40% of their
       width (their height stays), so the code stays on one line. */
    flex-wrap: nowrap;
    align-items: center;
    gap: max(var(--ds-space-1), calc(var(--ds-otp-gap, var(--ds-space-2)) + var(--ds-density, 0) * 2px));
    max-inline-size: 100%;
  }

  .ds-otp > input.ds-otp__cell {
    --_w: max(var(--ds-target-min, 0px), calc(var(--ds-otp-cell-width, 40px) + var(--ds-size-step, 0) * 8px));
    flex: 0 1 var(--_w);
    /* The basis sizes the cell; a width of 0 keeps a grid or a flex row
       around the code from reserving the full widths as its minimum. */
    inline-size: 0;
    min-inline-size: calc(var(--_w) * 0.6);
    padding-inline: 0;
    text-align: center;
    font: var(--ds-otp-font, var(--ds-font-subtitle));
    font-variant-numeric: tabular-nums;
    caret-color: var(--ds-input-focus-color, var(--ds-primary));
  }

  /* On a phone the cells keep their width before the gaps do. */
  @media (max-width: 600px) {
    .ds-otp {
      gap: var(--ds-space-1);
    }
  }

  .ds-otp__sep {
    flex: none;
    inline-size: var(--ds-space-2);
    block-size: 2px;
    border-radius: calc(var(--ds-radius-xs) * var(--ds-shape, 1));
    background: var(--ds-outline);
  }

  @media (forced-colors: active) {
    .ds-otp__sep {
      background: CanvasText;
    }
  }
}

/* ── components/selectpanel/selectpanel.css ── */
/*
 * Select panel: a button that opens a popover with a filter, a list of
 * options to check (DS.listbox's .ds-listbox--plain) and an apply foot:
 * labels, assignees, filters. Nothing changes until Apply; Escape, a press
 * outside or Tab away discard. DS.selectpanel (selectpanel.js) opens and
 * closes it through DS.overlay, places it (DS.position) and keeps the
 * button's summary.
 *
 *   <div class="ds-selectpanel" data-ds-selectpanel>
 *     <button class="ds-btn ds-btn--outlined ds-selectpanel__trigger" type="button" aria-haspopup="dialog" aria-expanded="false">
 *       (tag 20) Labels <span class="ds-selectpanel__summary"></span> (chevronDown 20)
 *     </button>
 *     <div class="ds-selectpanel__panel" role="dialog" aria-label="Labels" hidden>
 *       <div class="ds-selectpanel__head">
 *         <input class="ds-input ds-selectpanel__search" type="search" aria-label="Filter labels" placeholder="Filter labels">
 *       </div>
 *       <div class="ds-listbox ds-listbox--plain ds-selectpanel__list" role="listbox" aria-multiselectable="true" aria-label="Labels">
 *         <div class="ds-listbox__option" role="option" aria-selected="false" data-value="bug">
 *           <span class="ds-listbox__check" aria-hidden="true">(check 16)</span><span class="ds-listbox__name">Bug</span></div> ...
 *       </div>
 *       <p class="ds-selectpanel__status" role="status"></p>
 *       <div class="ds-selectpanel__foot">
 *         <button class="ds-btn ds-btn--text" type="button" data-ds-selectpanel-clear>Clear</button>
 *         <button class="ds-btn ds-btn--filled" type="button" data-ds-selectpanel-apply>Apply</button>
 *       </div>
 *     </div>
 *   </div>
 *
 * The panel is a popup of DS.overlay: data-state (open, closed) drives its
 * motion; where the top layer and anchor positioning exist it opens as
 * popover="manual" (data-anchored) below the button or above it
 * (data-placement="top"), never taller than the room on that side;
 * elsewhere it stands under the button, absolute, its height capped by the
 * script. The list scrolls inside the panel; head, status and foot stay.
 * Without an Apply button every change applies at once.
 *
 * Options (src/core/options.css, docs/options.md), on the select panel or
 * any ancestor (the panel inherits them through the DOM, also in the top
 * layer):
 *   size, density, touch  the trigger is a .ds-btn and the options are
 *             listbox options: both compute them; the panel's padding takes
 *             2px per density step
 *   shape     .ds-shape-*: multiplies the panel's radius
 *   tone      none
 *
 * Motion: the panel grows from the button (DS.motion.originFrom: its clip
 * opens and it scales on --ds-ease-spatial over --ds-dur-medium while it
 * fades in over --ds-dur-fast) and leaves with a fade in --ds-dur-instant; a
 * close mid-way turns back from where it is.
 *
 * Forced colours: the panel keeps a transparent outline that becomes its
 * edge; the options are the listbox's.
 *
 * Hooks: --ds-selectpanel-width (320px), --ds-selectpanel-list-max-height
 * (320px), --ds-selectpanel-radius (--ds-radius-xs).
 *
 * Progressive:
 * - scrollbar-color and scrollbar-width (a thin, quiet scrollbar in the
 *   list): without them the platform scrollbar shows.
 * - CSS anchor positioning (position-anchor, position-area and
 *   position-try-fallbacks on the panel, behind @supports; DS.selectpanel
 *   then opens it in the top layer with data-anchored, so no scrolling box
 *   clips it): without it the panel is absolute under the button, and the
 *   script flips it up and caps its height.
 */

@layer ds.components.selectpanel {
  .ds-selectpanel {
    position: relative;
    display: inline-block;
    max-width: 100%;
    vertical-align: middle;
  }

  /* The button never outgrows the select panel's box: a long summary
     truncates instead of pushing the row. */
  .ds-selectpanel__trigger {
    max-width: 100%;
  }

  /* The summary of the choice, quieter than the name. */
  .ds-selectpanel__summary {
    min-width: 0;
    overflow: hidden;
    color: var(--ds-text-2);
    font-weight: var(--ds-weight-regular);
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .ds-selectpanel__summary:empty {
    display: none;
  }

  /* Disabled is one model: the summary takes the button's disabled ink with
     its name (in forced colours too, where that ink is GrayText). */
  .ds-selectpanel__trigger:is(:disabled, [aria-disabled="true"]) .ds-selectpanel__summary {
    color: inherit;
  }

  .ds-selectpanel__panel {
    position: absolute;
    top: calc(100% + var(--ds-space-1));
    inset-inline-start: 0;
    z-index: var(--ds-z-popover);
    display: flex;
    flex-direction: column;
    box-sizing: border-box;
    width: min(var(--ds-selectpanel-width, 320px), calc(100vw - 2 * var(--ds-space-2)));
    margin: 0;
    padding: 0;
    overflow: hidden;
    border: 0;
    border-radius: calc(var(--ds-selectpanel-radius, var(--ds-radius-xs)) * var(--ds-shape, 1));
    background: var(--ds-surface-popover);
    color: var(--ds-text);
    box-shadow: var(--ds-elev-popover);
    /* Invisible; forced colours paint it, so the panel keeps an edge. */
    outline: 1px solid transparent;
    /* Grows at its button (originFrom() writes the origin); its clip rests
       --ds-space-6 beyond the box, room for the shadow. */
    transform-origin: var(--ds-motion-origin, 0% 0%);
    clip-path: inset(calc(-1 * var(--ds-space-6)));
  }

  .ds-selectpanel__panel[data-placement="top"] {
    top: auto;
    bottom: calc(100% + var(--ds-space-1));
    transform-origin: var(--ds-motion-origin, 0% 100%);
  }

  /* Shown by hand (no data-state): the reveal plays once. */
  .ds-selectpanel__panel:not([data-state]) {
    animation:
      ds-fade-in var(--ds-dur-fast) var(--ds-ease-in-out) backwards,
      ds-clip-in var(--ds-dur-medium) var(--ds-ease-spatial) backwards;
  }

  /* Driven by DS.overlay: transitions keyed on data-state, so a panel
     closed mid-way continues from where it is. */
  .ds-selectpanel__panel[data-state] {
    animation: none;
    transition:
      opacity var(--ds-dur-fast) var(--ds-ease-in-out),
      scale var(--ds-dur-medium) var(--ds-ease-spatial),
      clip-path var(--ds-dur-medium) var(--ds-ease-spatial);
  }

  /* The exit only fades, in --ds-dur-instant; scale and clip go back to
     their start once the panel is invisible. */
  .ds-selectpanel__panel[data-state="closed"] {
    opacity: 0;
    scale: var(--ds-motion-scale, var(--ds-scale-popup));
    clip-path: var(--ds-clip-from, inset(0 0 100% 0));
    pointer-events: none;
    transition:
      opacity var(--ds-dur-instant) var(--ds-ease-in-out),
      scale 0ms var(--ds-ease-in-out) var(--ds-dur-instant),
      clip-path 0ms var(--ds-ease-in-out) var(--ds-dur-instant);
  }

  .ds-selectpanel__panel[hidden] {
    display: none;
  }

  /* Anchor positioning: in the top layer (popover="manual"), below the
     button from its start edge or above it (data-placement="top"); never
     taller than the room on its side. The UA box of a popover goes. */
  @supports (position-area: block-end) {
    .ds-selectpanel__panel[data-anchored] {
      position: fixed;
      inset: auto;
      height: auto;
      max-height: calc(100% - 2 * var(--ds-space-1));
      margin: var(--ds-space-1) 0;
      position-area: block-end span-inline-end;
      position-try-fallbacks: flip-block, flip-inline, flip-block flip-inline;
    }

    .ds-selectpanel__panel[data-anchored][data-placement="top"] {
      position-area: block-start span-inline-end;
    }
  }

  .ds-selectpanel__head {
    flex: none;
    padding: calc(var(--ds-space-3) + var(--ds-density, 0) * 2px) var(--ds-space-3) var(--ds-space-2);
    border-block-end: 1px solid var(--ds-line);
  }

  .ds-selectpanel__search {
    width: 100%;
  }

  /* The list scrolls inside the panel; head, status and foot stay. */
  .ds-selectpanel__list {
    /* Positioned, so scrollIntoView() and absolute content stay inside. */
    position: relative;
    flex: 0 1 auto;
    min-height: 0;
    max-height: var(--ds-selectpanel-list-max-height, 320px);
    padding-block: var(--ds-space-1);
    overflow-y: auto;
    scrollbar-width: thin;
    scrollbar-color: var(--ds-line-2) transparent;
  }

  .ds-selectpanel__status {
    flex: none;
    margin: 0;
    padding: var(--ds-space-2) var(--ds-space-4);
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
  }

  .ds-selectpanel__status:empty {
    display: none;
  }

  .ds-selectpanel__foot {
    flex: none;
    display: flex;
    flex-wrap: wrap;
    justify-content: flex-end;
    gap: var(--ds-space-2);
    padding: calc(var(--ds-space-2) + var(--ds-density, 0) * 2px) var(--ds-space-3);
    border-block-start: 1px solid var(--ds-line);
  }

  @media print {
    .ds-selectpanel__panel {
      display: none;
    }
  }
}

/* ── components/inlineedit/inlineedit.css ── */
/*
 * Inline edit: a value shown as text with an edit button, which turns into
 * a field with Save and Cancel in place. The view and the form are one
 * height (a field's at every option), so nothing below moves when it
 * switches.
 *
 *   <div class="ds-inlineedit" data-ds-inlineedit>   (data-state="view" | "edit", aria-busy: written by DS.inlineedit)
 *     <div class="ds-inlineedit__view">
 *       <span class="ds-inlineedit__value">LAPTOP-0042</span>
 *       <button class="ds-btn ds-btn--quiet ds-btn--icon ds-sm ds-inlineedit__edit" type="button" aria-label="Edit device name">(pencil 18)</button>
 *     </div>
 *     <div class="ds-inlineedit__form">
 *       <input class="ds-input ds-inlineedit__input" aria-label="Device name">
 *       <span class="ds-inlineedit__actions">
 *         <button class="ds-btn ds-btn--tonal ds-sm ds-inlineedit__save" type="button">(faces: Save, busy)</button>
 *         <button class="ds-btn ds-btn--text ds-sm ds-inlineedit__cancel" type="button">Cancel</button>
 *       </span>
 *     </div>
 *     <small class="ds-field__hint ds-field__hint--error ds-inlineedit__error" hidden></small>
 *   </div>
 *
 * Before the script runs (no data-state) only the view shows. The edit
 * button always shows (a button that appears on hover is out of reach on a
 * touch screen); a click on the value opens the field too. The actions wrap
 * under the field in a narrow container.
 *
 * Options (src/core/options.css, docs/options.md), on the component or any
 * ancestor:
 *   size      .ds-xs ... .ds-xl: the view's height follows the field's (8px
 *             per step); the field and the buttons are form.css's and
 *             button.css's, computed there
 *   density   .ds-density-*: 4px per step, as the field
 *   shape     .ds-shape-*: the field and the buttons
 *   touch     .ds-touch: the view, the field and every button at least
 *             --ds-touch-target
 * No tone: an error shows through aria-invalid and its message in words.
 *
 * Hooks: the field's (--ds-input-height; form.css) and
 * --ds-inlineedit-field-min (12rem: the narrowest the field gets before
 * the actions wrap under it).
 *
 * Forced colours: the field and the buttons are form.css's and button.css's;
 * the error is words with an icon.
 */

@layer ds.components.inlineedit {
  .ds-inlineedit {
    display: grid;
    gap: var(--ds-space-1);
    min-width: 0;
  }

  /* The view as high as the field it turns into. */
  .ds-inlineedit__view {
    --_h: calc(var(--ds-input-height, 40px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px);
    display: flex;
    align-items: center;
    gap: var(--ds-space-1);
    min-width: 0;
    min-height: max(var(--ds-target-min, 0px), var(--_h));
  }

  .ds-inlineedit__value {
    min-width: 0;
    overflow-wrap: anywhere;
    color: var(--ds-text);
    cursor: text;
  }

  .ds-inlineedit__value:empty::before {
    content: "\2014";
    color: var(--ds-text-2);
  }

  .ds-inlineedit__edit {
    flex: none;
  }

  .ds-inlineedit__form {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--ds-space-2);
    min-width: 0;
  }

  .ds-inlineedit__input {
    flex: 1 1 var(--ds-inlineedit-field-min, 12rem);
    width: auto;
    min-width: 0;
  }

  .ds-inlineedit__actions {
    display: inline-flex;
    flex: none;
    align-items: center;
    gap: var(--ds-space-1);
  }

  .ds-inlineedit__save,
  .ds-inlineedit__cancel {
    flex: none;
  }

  /* Which part shows: the view until the script says edit. */
  .ds-inlineedit:not([data-state="edit"]) > .ds-inlineedit__form,
  .ds-inlineedit[data-state="edit"] > .ds-inlineedit__view {
    display: none;
  }

  .ds-inlineedit__error[hidden] {
    display: none;
  }
}

/* ── components/orderedchoice/orderedchoice.css ── */
/*
 * Ordered choice: a multi-select whose order matters (the columns of a
 * table, the order of fallbacks, priorities). Every option is a row with a
 * grip and a checkbox; the checked ones count, in the order of the rows,
 * and each shows its place. DS.orderedchoice (orderedchoice.js) moves the
 * rows by drag and by keys (DS.dnd) and keeps the places.
 *
 *   <ol class="ds-orderedchoice" data-ds-orderedchoice aria-label="Columns">
 *     <li class="ds-orderedchoice__item">
 *       <button class="ds-btn ds-btn--quiet ds-btn--icon ds-grip" type="button" aria-label="Move Name">(grip 20)</button>
 *       <label class="ds-check"><input type="checkbox" value="name" checked><span>Name</span></label>
 *       <span class="ds-orderedchoice__rank"></span>
 *     </li> ...
 *   </ol>
 *
 * The rows stand on hairlines in an outlined box (as form.css's check
 * list). A checked row's label takes the label weight and its place shows
 * at the end in a .ds-orderedchoice__rank disc (a number and, for a screen
 * reader, "Position 2"); an unchecked row shows none. The row being moved
 * is drag.css's ([data-ds-dragging]: raised, the dragged state layer).
 * .ds-orderedchoice__status (written by the module) says why no more can be
 * checked at the maximum.
 *
 * Options (src/core/options.css, docs/options.md), on the list or any
 * ancestor: the checkbox rows compute size, density and touch themselves;
 * here the row's block padding takes 2px per density step (never below 0)
 * and the rank disc 4px per size step; shape multiplies the radii of the
 * box and the disc. No tone.
 *
 * Motion: rows glide to their new places (DS.dnd through DS.motion.flip);
 * the rank disc fades in and out over --ds-dur-fast.
 *
 * Forced colours: the box keeps its border; the rank disc keeps an edge in
 * CanvasText; the moved row is drag.css's Highlight outline.
 *
 * Hooks: --ds-orderedchoice-radius (--ds-radius-card). The private
 * --_rank is computed here: never set it.
 */

@layer ds.components.orderedchoice {
  .ds-orderedchoice {
    position: relative;
    display: grid;
    margin: 0;
    padding: 0;
    border: 1px solid var(--ds-line);
    border-radius: calc(var(--ds-orderedchoice-radius, var(--ds-radius-card)) * var(--ds-shape, 1));
    background: var(--ds-surface);
    list-style: none;
  }

  .ds-orderedchoice__item {
    position: relative;
    display: flex;
    align-items: center;
    gap: var(--ds-space-2);
    min-width: 0;
    padding-block: max(0px, calc(var(--ds-space-1) + var(--ds-density, 0) * 2px));
    padding-inline: var(--ds-space-1) var(--ds-space-4);
    background: var(--ds-surface);
  }

  .ds-orderedchoice__item + .ds-orderedchoice__item {
    border-block-start: 1px solid var(--ds-line);
  }

  .ds-orderedchoice__item:first-child {
    border-start-start-radius: inherit;
    border-start-end-radius: inherit;
  }

  .ds-orderedchoice__item:last-child {
    border-end-start-radius: inherit;
    border-end-end-radius: inherit;
  }

  /* The grip keeps its size beside a long label. */
  .ds-orderedchoice__item > .ds-grip {
    flex: none;
  }

  /* The label takes the room; a long one wraps. */
  .ds-orderedchoice__item > .ds-check {
    flex: 1 1 auto;
    min-width: 0;
  }

  .ds-orderedchoice__item:has(> .ds-check > input:checked) > .ds-check {
    font-weight: var(--ds-weight-label);
  }

  /* The place of a checked row: a disc with its number. */
  .ds-orderedchoice__rank {
    --_rank: calc(var(--ds-space-6) + var(--ds-size-step, 0) * 4px);
    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    min-width: var(--_rank);
    height: var(--_rank);
    padding-inline: var(--ds-space-1);
    box-sizing: border-box;
    border-radius: calc(var(--_rank) / 2 * var(--ds-shape, 1));
    background: var(--ds-accent);
    color: var(--ds-on-accent);
    font: var(--ds-font-caption);
    font-weight: var(--ds-weight-label);
    font-variant-numeric: tabular-nums;
    opacity: 1;
    transition: opacity var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  .ds-orderedchoice__rank:empty {
    opacity: 0;
    transition-duration: var(--ds-dur-instant);
  }

  .ds-orderedchoice__status {
    margin: var(--ds-space-1) 0 0;
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
  }

  .ds-orderedchoice__status:empty {
    display: none;
  }

  @media (forced-colors: active) {
    .ds-orderedchoice {
      border-color: CanvasText;
    }

    .ds-orderedchoice__rank {
      border: 1px solid CanvasText;
    }
  }
}

/* ── components/transfer/transfer.css ── */
/*
 * Transfer list: two lists side by side, the available options and the
 * chosen ones, with buttons that move the marked options across (dueling
 * lists): a role's permissions, the devices of a group. Each side is a
 * listbox of several values (DS.listbox) with an optional filter; DS.transfer
 * (transfer.js) moves the options and keeps the value.
 *
 *   <div class="ds-transfer" data-ds-transfer>
 *     <div class="ds-transfer__side" data-ds-transfer-side="source">
 *       <span class="ds-transfer__title" id="avail">Available</span>
 *       <input class="ds-input ds-transfer__search" type="search" aria-label="Filter available">
 *       <div class="ds-listbox ds-transfer__list" role="listbox" aria-multiselectable="true" aria-labelledby="avail"> options </div>
 *     </div>
 *     <div class="ds-transfer__actions" role="group" aria-label="Move">
 *       <button class="ds-btn ds-btn--outlined ds-btn--icon" type="button" data-ds-transfer-add aria-label="Add the marked">(arrowRight)</button>
 *       <button class="ds-btn ds-btn--outlined ds-btn--icon" type="button" data-ds-transfer-remove aria-label="Remove the marked">(arrowLeft)</button>
 *     </div>
 *     <div class="ds-transfer__side" data-ds-transfer-side="target"> ... the chosen ... </div>
 *   </div>
 *
 * Both lists take one height (--ds-transfer-list-height, 264px), so the
 * buttons stand between them in the middle. Where the transfer is 560px
 * wide or less (a container query on itself) the sides stack and the
 * buttons turn a quarter (their arrows point down and up).
 *
 * Options (src/core/options.css, docs/options.md): the lists are listboxes
 * and the buttons icon buttons; both compute size, density, shape and touch
 * themselves. Here only the gaps. No tone.
 *
 * Forced colours: the lists are the listbox's.
 *
 * Hooks: --ds-transfer-list-height (264px).
 */

@layer ds.components.transfer {
  .ds-transfer {
    container-type: inline-size;
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
    align-items: center;
    gap: var(--ds-space-3);
  }

  /* The list sits at the bottom of its side, so both lists line up when
     only one side has a filter. */
  .ds-transfer__side {
    display: flex;
    flex-direction: column;
    gap: var(--ds-space-2);
    min-width: 0;
    align-self: stretch;
  }

  .ds-transfer__side > .ds-transfer__list {
    margin-block-start: auto;
  }

  .ds-transfer__title {
    color: var(--ds-text);
    font: var(--ds-font-label);
  }

  .ds-transfer__search {
    width: 100%;
  }

  .ds-transfer__list {
    height: var(--ds-transfer-list-height, 264px);
    max-height: none;
  }

  .ds-transfer__actions {
    display: flex;
    flex-direction: column;
    gap: var(--ds-space-2);
  }

  /* Narrow: one side above the other, the arrows a quarter turned. */
  @container (max-width: 560px) {
    .ds-transfer__actions {
      flex-direction: row;
      justify-content: center;
    }

    .ds-transfer__actions svg {
      rotate: 90deg;
    }

    /* The grid cannot query its own width; its children take a row each. */
    .ds-transfer > * {
      grid-column: 1 / -1;
    }
  }
}

/* ── components/typeconfirm/typeconfirm.css ── */
/*
 * Type-to-confirm: a destructive confirmation that waits for the name of
 * what goes. The dialog, the field and the buttons are dialog.css's,
 * form.css's and button.css's; this file sets the name in the label, which
 * reads as the exact text to type.
 *
 *   <form class="ds-dialog__box ds-typeconfirm" data-ds-typeconfirm="LAPTOP-0042">
 *     <h2 class="ds-dialog__title">...</h2> <p class="ds-dialog__text">...</p>
 *     <div class="ds-field">
 *       <label class="ds-field__label ds-typeconfirm__label" for="c"></label>
 *         (written by DS.typeconfirm: Type <strong class="ds-typeconfirm__name">LAPTOP-0042</strong> to confirm)
 *       <input class="ds-input ds-typeconfirm__input" id="c" autocomplete="off" spellcheck="false" autocapitalize="off">
 *       <small class="ds-field__hint ds-field__hint--error ds-typeconfirm__error" hidden></small>
 *     </div>
 *     <div class="ds-dialog__actions"> <button class="ds-btn ds-btn--text" type="button" data-ds-close>Cancel</button>
 *       <button class="ds-btn ds-btn--filled ds-tone-error ds-typeconfirm__confirm" type="submit">Delete device</button>
 *   </form>
 *
 * The confirm button is the one red button D10 allows: filled, in the
 * error tone, its label naming the consequence. It is aria-disabled until
 * the name matches (button.css's blocked look; DS.motion's action guard
 * blocks it). Behaviour is DS.typeconfirm (typeconfirm.js).
 *
 * Options: those of the dialog, the field and the button, computed there.
 * The name keeps the label's size in the monospace family at every size.
 * No tone of its own: the button's error tone is the D10 exception.
 *
 * Forced colours: the name is CanvasText like the label; the blocked button
 * GrayText (button.css).
 */

@layer ds.components.typeconfirm {
  /* The exact text to type: the monospace family, the label's size, whole
     words never hyphenated, and a pointer selects it at once. */
  .ds-typeconfirm__label {
    overflow-wrap: anywhere;
  }

  .ds-typeconfirm .ds-typeconfirm__name {
    font-family: var(--ds-font-mono);
    font-weight: var(--ds-weight-label);
    overflow-wrap: anywhere;
    user-select: all;
  }

  .ds-typeconfirm__input {
    font-family: var(--ds-font-mono);
  }

  .ds-typeconfirm__confirm {
    flex: none;
  }

  .ds-typeconfirm__error[hidden] {
    display: none;
  }
}

/* ── components/errorsummary/errorsummary.css ── */
/*
 * Error summary: the problems of a form in an error alert at its top, each
 * a link to its field. The box, the icon, the tone and the title are
 * alert.css's (.ds-alert.ds-tone-error, .ds-alert__title); this file sets
 * the list of links and the focus the summary takes.
 *
 *   <form class="ds-form" novalidate>
 *     <div class="ds-alert ds-tone-error ds-errorsummary" data-ds-errorsummary tabindex="-1" hidden>
 *       (alertCircle 20)
 *       <div class="ds-alert__text">
 *         <h2 class="ds-alert__title ds-errorsummary__title"></h2>       (written: "There are 2 problems")
 *         <ul class="ds-errorsummary__list"></ul>                          (written: <li><a href="#name">...</a></li>)
 *       </div>
 *     </div>
 *     (fields)
 *   </form>
 *
 * Behaviour (which fields, the words, the focus, the live list) is
 * DS.errorsummary (errorsummary.js).
 *
 * The summary takes the focus after a failed submit: it shows the focus
 * ring of every control on :focus-visible (--ds-focus-outline, solid from
 * the first frame, offset snapping on --ds-dur-fast), after a submit from
 * the keyboard always, after a pointer submit where the engine honours
 * focus({ focusVisible: true }) (errorsummary.js). Its links are the
 * alert's ink, underlined with the link geometry and in the label weight,
 * each on a line of its own.
 *
 * Options (src/core/options.css, docs/options.md): the alert's (padding by
 * size and density, the corners by shape), computed in alert.css; the
 * links take at least --ds-target-min high under .ds-touch. The tone is
 * the error's, always with the icon and the words.
 *
 * Forced colours: the alert's edge (alert.css); the links are LinkText.
 */

@layer ds.components.errorsummary {
  .ds-errorsummary {
    outline-offset: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    transition: outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  /* Focused by the script after a submit: the ring every control shows, so
     the eye lands where reading starts. */
  .ds-errorsummary:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: var(--ds-focus-offset);
  }

  .ds-errorsummary[hidden] {
    display: none;
  }

  .ds-errorsummary__title {
    margin: 0;
  }

  .ds-errorsummary__list {
    display: grid;
    gap: var(--ds-space-1);
    margin: var(--ds-space-1) 0 0;
    padding: 0;
    list-style: none;
  }

  .ds-errorsummary__list a {
    display: inline-flex;
    align-items: center;
    min-height: var(--ds-target-min, 0px);
    /* The alert's ink, which its tone keeps readable in every scheme. */
    color: inherit;
    font-weight: var(--ds-weight-label);
    text-decoration: underline;
    text-decoration-thickness: var(--ds-link-underline-thickness);
    text-underline-offset: var(--ds-link-underline-offset);
  }

  .ds-errorsummary__list a {
    outline-offset: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    transition: outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-errorsummary__list a:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: var(--ds-focus-offset);
  }

  @media (forced-colors: active) {
    .ds-errorsummary__list a {
      color: LinkText;
    }
  }
}

/* ── components/search/search.css ── */
/*
 * Search field: the filled search pill of form.css (.ds-search) with a
 * clear button, the shortcut hint, a result count and a list of recent
 * searches. form.css draws the pill, the icon and the key; this file places
 * the clear button, keeps room for it and for a key of any width, and sets
 * the count and the list's rows.
 *
 *   <div class="ds-search" data-ds-search data-ds-search-recent="devices" data-ds-search-count="dev-count">
 *     (search icon 20)
 *     <input class="ds-input" id="q" type="search" aria-label="Search devices" placeholder="Search devices" data-ds-hotkey="/">
 *     <kbd class="ds-kbd ds-search__key" aria-hidden="true"></kbd>
 *     <button class="ds-btn ds-btn--quiet ds-btn--icon ds-search__clear" type="button" hidden>(close 18)</button>
 *     (written by DS.search: <div class="ds-combo__popup ds-search__popup"> <ul class="ds-combo__list" role="listbox">
 *        <li class="ds-combo__option">(history 18 .ds-search__history)<span class="ds-combo__name">laptop</span></li> ...
 *      <div class="ds-search__foot"><button class="ds-btn ds-btn--text ds-search__forget">Clear recent searches</button></div></div>)
 *   </div>
 *   <span class="ds-search__count" id="dev-count"></span>   (anywhere: beside the search, in a toolbar)
 *
 * Behaviour (clear, the key's text, the count and its announcement, the
 * recent searches) is DS.search (search.js); --ds-search-key-room is the
 * key's measured width, written there.
 *
 * Options (src/core/options.css, docs/options.md), from the pill of
 * form.css and computed here for the clear button:
 *   size      .ds-xs ... .ds-xl: the pill 8px per step; the clear button
 *             8px per step too, always 8px lower than the pill
 *   density   .ds-density-*: 4px per step on the pill and the button
 *   shape     .ds-shape-*: the pill; the clear button is an action, a pill
 *             at the default and square at 0 (D11)
 *   touch     .ds-touch: pill and clear button at least --ds-touch-target;
 *             the key is never shown on a touch screen (form.css)
 * No tone. The count is words ("12 results", "No results").
 *
 * Hooks: --ds-search-clear-size (32px: the clear button at md and
 * comfortable, which size and density steps apply to). The list takes the
 * combobox's hooks (--ds-combo-radius, --ds-combo-option-height).
 *
 * Forced colours: the clear button is a system button; the list is the
 * combobox's (a transparent outline that becomes its edge, the active row
 * in Highlight); the foot's rule is CanvasText.
 */

@layer ds.components.search {
  /* A key of any width ("Ctrl+K" as well as "/"): the room DS.search measured. */
  .ds-search > .ds-input:has(~ .ds-search__key) {
    padding-inline-end: calc(var(--ds-search-key-room, var(--ds-space-5)) + var(--ds-space-3) + var(--ds-space-2));
  }

  /* The clear button's room, whichever is wider: it or the key (they never show together). */
  .ds-search > .ds-input:has(~ .ds-search__clear) {
    --_clear: max(var(--ds-target-min, 0px), calc(var(--ds-search-clear-size, 32px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px));
    padding-inline-end: max(calc(var(--_clear) + 2 * var(--ds-space-1)), calc(var(--ds-search-key-room, 0px) + var(--ds-space-3) + var(--ds-space-2)));
  }

  /* The system's clear button replaces the engine's own. */
  .ds-search:has(> .ds-search__clear) > .ds-input::-webkit-search-cancel-button {
    display: none;
  }

  /* An icon button 8px lower than the pill at every size and density (the
     icon button's own model follows size only), never under the touch
     minimum, at the pill's end. */
  .ds-search__clear {
    --ds-btn-icon-size: calc(var(--ds-search-clear-size, 32px) + var(--ds-density, 0) * 4px);
    position: absolute;
    inset-inline-end: var(--ds-space-1);
  }

  .ds-search__clear[hidden] {
    display: none;
  }

  .ds-search__count {
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
  }

  /* The list of recent searches: a combobox list under the pill, a row is
     the history icon and the words. */
  .ds-search__popup .ds-combo__option {
    grid-template-columns: auto minmax(0, 1fr);
    align-items: center;
    column-gap: var(--ds-space-3);
  }

  .ds-search__history {
    color: var(--ds-text-2);
  }

  .ds-search__foot {
    display: flex;
    padding: var(--ds-space-1) var(--ds-space-2);
    border-block-start: 1px solid var(--ds-line);
  }

  /* The one action of the foot, at its end. */
  .ds-search__forget {
    margin-inline-start: auto;
  }

  @media (forced-colors: active) {
    .ds-search__foot {
      border-block-start-color: CanvasText;
    }

    .ds-search__history {
      color: inherit;
    }
  }
}

/* ── components/meter/meter.css ── */
/*
 * Meter variants: a share of a known whole (disk used, a quota, a score)
 * as a segmented bar, a ring, a gauge or a bar gauge, with threshold
 * marks. The linear meter itself is .ds-meter (chart.css); this file adds
 * its segmented look and its threshold marks, and the radial and bar
 * gauges. Every one reads the registered share --ds-share (0 ... 1, set by
 * the page with style.setProperty, as on a chart mark) and glides to a new
 * one on --ds-ease-value over --ds-dur-glide; the first render fills from
 * zero with .ds-enter--fill (DS.motion.enterAll(marks, 'fill')).
 *
 *   <span class="ds-meter ds-meter--segmented" role="meter" aria-label="Password strength"
 *         aria-valuemin="0" aria-valuemax="4" aria-valuenow="3" aria-valuetext="Strong" style="--ds-share: .75"></span>
 *
 *   <span class="ds-meter" role="meter" aria-label="Disk" ... style="--ds-share: .62">
 *     <span class="ds-meter__threshold" style="--ds-share: .8" aria-hidden="true"></span></span>
 *
 *   <div class="ds-gauge [ds-gauge--arc]" role="meter" aria-label="CPU" aria-valuemin="0"
 *        aria-valuemax="100" aria-valuenow="72" aria-valuetext="72%, high" style="--ds-share: .72">
 *     <span class="ds-gauge__threshold" style="--ds-share: .9" aria-hidden="true"></span>
 *     <span class="ds-gauge__value" aria-hidden="true">72%</span>
 *     <span class="ds-gauge__label" aria-hidden="true">CPU</span>
 *   </div>
 *
 *   <div class="ds-bar-gauge" role="meter" aria-labelledby="..." ... style="--ds-share: .84;
 *        --ds-bar-gauge-warning: .7; --ds-bar-gauge-error: .9">
 *     <span class="ds-bar-gauge__label" id="...">Memory</span>
 *     <span class="ds-bar-gauge__value">84%</span>
 *     <span class="ds-bar-gauge__track" aria-hidden="true"></span>
 *     <span class="ds-bar-gauge__note">(alert 16) High</span>
 *   </div>
 *
 *   .ds-meter--segmented   the meter in --ds-meter-segments equal parts
 *                          (5) with --ds-meter-segment-gap (2px) between
 *                          them: a score in steps (password strength, a
 *                          rating). Set a share that ends on a segment.
 *   .ds-meter__threshold   a mark across the track at its own --ds-share:
 *                          a limit or a target. Its meaning is the page's
 *                          words (aria-valuetext, a note): never the mark
 *                          alone
 *   .ds-gauge              a ring (360 degrees) with the figure inside
 *   .ds-gauge--arc         a gauge: an arc of 240 degrees, open at the
 *                          bottom, with round ends
 *   .ds-gauge__threshold   a tick across the ring at its own --ds-share
 *   .ds-bar-gauge          a thick bar of cells under a label and a figure;
 *                          the cells past --ds-bar-gauge-warning and
 *                          --ds-bar-gauge-error (shares, set on the element;
 *                          default: none) light in the warning and error
 *                          colours, so the zones show on the track as well
 *                          as in the fill. The figure and a note
 *                          (.ds-bar-gauge__note, an icon and a word) say
 *                          the state: never the colour alone
 *
 * Tone: from the class on the meter itself, as on .ds-meter (an inherited
 * tone would recolour every gauge of a tinted region): primary, info and
 * success the tone, neutral, warning and error the chart roles. A bar
 * gauge takes its zones instead (a tone on it sets the first zone).
 *
 * Options (src/core/options.css, docs/options.md), on the meter or any
 * ancestor; each is computed here, in the rule that uses it:
 *   size      .ds-xs ... .ds-xl: a gauge 16px per step (96px at md) and its
 *             ring 2px per step (8px); a bar gauge's track 2px per step
 *             (12px); the type of a gauge's figure follows its size; a
 *             segmented meter as .ds-meter (1px per step)
 *   density   .ds-density-*: the gap between a bar gauge's rows, 1px per
 *             step; not the gauges, which are figures, not rows
 *   shape     .ds-shape-*: the threshold marks' ends (a segmented meter's
 *             ends as .ds-meter); a ring stays round, the arc's ends with
 *             it, and a bar gauge's cells are square, as LED cells are
 *   touch     not read: nothing here is a target
 *
 * Accessibility: role="meter" with aria-valuemin, -max, -now and a
 * aria-valuetext that says the state in words; the visible figure and
 * label inside a gauge are aria-hidden, since the meter says them.
 * Forced colours: the fill in CanvasText, the track Canvas with a
 * CanvasText edge, the marks CanvasText; the unlit parts of a segmented
 * meter and the unlit cells of a bar gauge GrayText, since their masks
 * cut any edge away; a bar gauge's zones hatch (warning 45 degrees, error
 * 135 degrees) on lit and unlit cells alike, so they stay apart without
 * colour. Printed, the fills keep their colours.
 *
 * conic-gradient(), sin() and cos() (the arc's round ends) and
 * mask-image are at the browser floor: no fallbacks.
 *
 * Hooks: --ds-meter-segments (5), --ds-meter-segment-gap (2px),
 * --ds-meter-threshold (--ds-text), --ds-gauge-size (96px),
 * --ds-gauge-thickness (8px), --ds-gauge-track (--ds-chart-track),
 * --ds-gauge-color (--ds-chart-1), --ds-bar-gauge-height (12px),
 * --ds-bar-gauge-cells (20), --ds-bar-gauge-warning and
 * --ds-bar-gauge-error (shares; default none).
 */

@layer ds.components.meter {
  /* ── Segmented meter ── */

  /* Track and fill both cut into equal parts: the mask leaves a gap after
     every part but the last. */
  .ds-meter--segmented {
    --_n: var(--ds-meter-segments, 5);
    --_gap: var(--ds-meter-segment-gap, 2px);
    mask-image: repeating-linear-gradient(to right, #000 0 calc((100% + var(--_gap)) / var(--_n) - var(--_gap)), transparent 0 calc((100% + var(--_gap)) / var(--_n)));
  }

  /* ── Threshold marks ── */

  /* A mark across a linear meter at its own share, 3px beyond the track
     on both sides; a hairline of the surface keeps it apart from the fill. */
  .ds-meter__threshold {
    position: absolute;
    inset-block: -3px;
    inset-inline-start: calc(var(--ds-share) * 100% - 1px);
    width: 2px;
    border-radius: calc(var(--ds-radius-xs) * var(--ds-shape, 1));
    background: var(--ds-meter-threshold, var(--ds-text));
    box-shadow: 0 0 0 1px var(--ds-surface);
    transition: none;
  }

  /* A segmented meter's mask would cut a mark in a gap: none there. */
  .ds-meter--segmented > .ds-meter__threshold {
    display: none;
  }

  /* ── Ring and gauge ── */

  .ds-gauge {
    --_s: max(calc(var(--ds-size-step, 0) * 16px + var(--ds-gauge-size, 96px)), 48px);
    --_t: max(calc(var(--ds-gauge-thickness, 8px) + var(--ds-size-step, 0) * 2px), 4px);
    /* The radius the ring's centre line runs on. */
    --_r: calc((var(--_s) - var(--_t)) / 2);
    --_from: 0deg;
    --_sweep: 360deg;
    --_fill: var(--ds-gauge-color, var(--ds-chart-1));
    --_track: var(--ds-gauge-track, var(--ds-chart-track));
    /* Where the fill ends; it follows the gliding share. */
    --_a: calc(var(--_from) + var(--ds-share) * var(--_sweep));
    position: relative;
    display: inline-grid;
    flex-shrink: 0;
    align-content: center;
    justify-items: center;
    width: var(--_s);
    height: var(--_s);
    color: var(--ds-text);
    text-align: center;
    transition: --ds-share var(--ds-dur-glide) var(--ds-ease-value);
  }

  /* The ring: a conic fill up to the share over the track, masked to a
     band of --_t. */
  .ds-gauge::before {
    content: '';
    position: absolute;
    inset: 0;
    border-radius: 50%;
    background: conic-gradient(from var(--_from), var(--_fill) calc(var(--ds-share) * var(--_sweep)), var(--_track) 0 var(--_sweep), transparent 0);
    mask-image: radial-gradient(farthest-side, transparent calc(100% - var(--_t) - .5px), #000 calc(100% - var(--_t)));
  }

  /* An arc of 240 degrees, open at the bottom, with round ends: a disc of
     the ring's width at each end of the track and of the fill (the fill's
     start disc only once there is a fill). */
  .ds-gauge--arc {
    --_from: -120deg;
    --_sweep: 240deg;
  }

  .ds-gauge--arc::before {
    background:
      radial-gradient(circle calc(var(--_t) / 2) at calc(50% + var(--_r) * sin(var(--_a))) calc(50% - var(--_r) * cos(var(--_a))), color-mix(in srgb, var(--_fill) calc(min(1, var(--ds-share) * 1000) * 100%), var(--_track)) calc(100% - .5px), transparent),
      radial-gradient(circle calc(var(--_t) / 2) at calc(50% + var(--_r) * sin(var(--_from))) calc(50% - var(--_r) * cos(var(--_from))), color-mix(in srgb, var(--_fill) calc(min(1, var(--ds-share) * 1000) * 100%), var(--_track)) calc(100% - .5px), transparent),
      radial-gradient(circle calc(var(--_t) / 2) at calc(50% + var(--_r) * sin(var(--_from) + var(--_sweep))) calc(50% - var(--_r) * cos(var(--_from) + var(--_sweep))), var(--_track) calc(100% - .5px), transparent),
      conic-gradient(from var(--_from), var(--_fill) calc(var(--ds-share) * var(--_sweep)), var(--_track) 0 var(--_sweep), transparent 0);
  }

  .ds-gauge:is(.ds-tone-primary, .ds-tone-info, .ds-tone-success) {
    --_fill: var(--ds-tone);
  }

  .ds-gauge.ds-tone-neutral {
    --_fill: var(--ds-chart-neutral);
  }

  .ds-gauge.ds-tone-warning {
    --_fill: var(--ds-chart-warning);
  }

  .ds-gauge.ds-tone-error {
    --_fill: var(--ds-chart-error);
  }

  /* The figure scales with the gauge: the title type at md, a sixth of a
     step either way; the label under it in the meta type. */
  .ds-gauge__value {
    position: relative;
    font: var(--ds-font-title);
    font-size: calc(var(--_s) / 4);
    line-height: calc(var(--_s) / 3);
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
  }

  .ds-gauge__label {
    position: relative;
    max-width: calc(var(--_s) - var(--_t) * 3);
    overflow: hidden;
    color: var(--ds-text-2);
    font: var(--ds-font-caption);
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  /* A tick across the ring at its own share, turned about the centre. */
  .ds-gauge__threshold {
    position: absolute;
    inset-block-start: -2px;
    inset-inline-start: calc(50% - 1px);
    width: 2px;
    height: calc(var(--_t) + 4px);
    border-radius: calc(var(--ds-radius-xs) * var(--ds-shape, 1));
    background: var(--ds-meter-threshold, var(--ds-text));
    box-shadow: 0 0 0 1px var(--ds-surface);
    transform-origin: 50% calc(var(--_s) / 2 + 2px);
    rotate: calc(var(--_from) + var(--ds-share) * var(--_sweep));
  }

  /* ── Bar gauge ── */

  .ds-bar-gauge {
    --_t: max(calc(var(--ds-bar-gauge-height, 12px) + var(--ds-size-step, 0) * 2px), 4px);
    --_cells: var(--ds-bar-gauge-cells, 20);
    --_gap: 2px;
    --_ok: var(--ds-chart-1);
    --_warn: var(--ds-chart-warning);
    --_error: var(--ds-chart-error);
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: baseline;
    column-gap: var(--ds-space-3);
    row-gap: calc(var(--ds-space-1) + var(--ds-density, 0) * 1px);
    min-width: 0;
    color: var(--ds-text);
    transition: --ds-share var(--ds-dur-glide) var(--ds-ease-value);
  }

  .ds-bar-gauge:is(.ds-tone-primary, .ds-tone-info, .ds-tone-success) {
    --_ok: var(--ds-tone);
  }

  .ds-bar-gauge.ds-tone-neutral {
    --_ok: var(--ds-chart-neutral);
  }

  .ds-bar-gauge__label {
    min-width: 0;
    overflow: hidden;
    font: var(--ds-font-body);
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .ds-bar-gauge__value {
    font: var(--ds-font-label);
    font-variant-numeric: tabular-nums;
    text-align: end;
    white-space: nowrap;
  }

  /*
   * The track: every cell in its zone's colour (hard stops at the two
   * shares), cut into cells by the mask. Lit cells (up to the share) show
   * the colour; the rest show it mixed into the track, so the zones read on
   * an empty gauge too. Two layers: the lit part clipped at the share over
   * the unlit one.
   */
  .ds-bar-gauge__track {
    --_zones: linear-gradient(to right, var(--_ok) 0 calc(var(--ds-bar-gauge-warning, 1) * 100%), var(--_warn) 0 calc(var(--ds-bar-gauge-error, 1) * 100%), var(--_error) 0);
    position: relative;
    grid-column: 1 / -1;
    height: var(--_t);
    background: var(--_zones);
    mask-image: repeating-linear-gradient(to right, #000 0 calc((100% + var(--_gap)) / var(--_cells) - var(--_gap)), transparent 0 calc((100% + var(--_gap)) / var(--_cells)));
  }

  /* Unlit: the track over the zone colours, a quarter of them showing. */
  .ds-bar-gauge__track::before {
    content: '';
    position: absolute;
    inset: 0;
    background: color-mix(in srgb, var(--ds-chart-track) 75%, transparent);
    clip-path: inset(0 0 0 calc(var(--ds-share) * 100%));
  }

  .ds-bar-gauge__note {
    display: inline-flex;
    grid-column: 1 / -1;
    align-items: center;
    gap: var(--ds-space-1);
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
  }

  .ds-bar-gauge__note svg {
    flex: none;
  }

  /* A row of bar gauges: the tracks line up, density spaces the rows. */
  .ds-bar-gauge + .ds-bar-gauge {
    margin-block-start: calc(var(--ds-space-4) + var(--ds-density, 0) * 2px);
  }

  @media (forced-colors: active) {
    .ds-gauge::before,
    .ds-gauge--arc::before {
      forced-color-adjust: none;
      background: conic-gradient(from var(--_from), CanvasText calc(var(--ds-share) * var(--_sweep)), GrayText 0 var(--_sweep), transparent 0);
    }

    .ds-meter__threshold,
    .ds-gauge__threshold {
      forced-color-adjust: none;
      background: CanvasText;
      box-shadow: 0 0 0 1px Canvas;
    }

    /* The mask cuts the track's edge away: the unlit parts in GrayText. */
    .ds-meter--segmented {
      background: GrayText;
    }

    /* Each zone a hatch from its share to the end: a layer as wide as the
       zone, at the end (none without the share), the error zone over the
       warning one. Lit cells hatch in CanvasText, unlit ones in GrayText. */
    .ds-bar-gauge__track {
      --_warn-zone: calc((1 - var(--ds-bar-gauge-warning, 1)) * 100%) 100%;
      --_error-zone: calc((1 - var(--ds-bar-gauge-error, 1)) * 100%) 100%;
      forced-color-adjust: none;
      background:
        repeating-linear-gradient(135deg, CanvasText 0 2px, Canvas 2px 4px) right / var(--_error-zone) no-repeat,
        repeating-linear-gradient(45deg, CanvasText 0 2px, Canvas 2px 4px) right / var(--_warn-zone) no-repeat,
        CanvasText;
    }

    .ds-bar-gauge__track::before {
      background:
        repeating-linear-gradient(135deg, GrayText 0 2px, Canvas 2px 4px) right / var(--_error-zone) no-repeat,
        repeating-linear-gradient(45deg, GrayText 0 2px, Canvas 2px 4px) right / var(--_warn-zone) no-repeat,
        GrayText;
    }
  }

  @media print {
    .ds-gauge::before,
    .ds-bar-gauge__track,
    .ds-bar-gauge__track::before {
      -webkit-print-color-adjust: exact;
      print-color-adjust: exact;
    }
  }
}

/* ── components/bar-list/bar-list.css ── */
/*
 * Bar list: ranked rows of a label and a value, each on a bar as long as
 * its share of the largest value (top pages, tickets per device, errors
 * per service). The page sorts the rows and sets each share; the bar says
 * nothing the figure does not, so the figure always shows.
 *
 *   <ol class="ds-bar-list" aria-label="Open tickets per device type">
 *     <li class="ds-bar-list__item" style="--ds-share: 1">
 *       <span class="ds-bar-list__label">(printer 16) <span>Printers</span></span>
 *       <span class="ds-bar-list__value">412</span>
 *     </li>
 *     <li class="ds-bar-list__item ds-tone-error" style="--ds-share: .42">
 *       <a class="ds-bar-list__label" href="...">Laptops</a>
 *       <span class="ds-bar-list__value">173</span>
 *     </li>
 *   </ol>
 *
 *   .ds-bar-list__item    a row: the bar behind the label, the figure at
 *                         its end; --ds-share (0 ... 1, registered) is
 *                         the bar's length, set by the page
 *   .ds-bar-list__label   the label, an optional 16px icon before it; an
 *                         <a> when the row opens something (the link, not
 *                         the row, takes focus); a long one ends in an
 *                         ellipsis on its bar
 *   .ds-bar-list__value   the figure, tabular, never cut
 *   .ds-bar-list--plain   the bar in the track colour, for a list where
 *                         every row shares one meaning and a tint would
 *                         be loud
 *
 * Tone: from the class on the row itself (an inherited tone would tint
 * every row of a tinted region): the bar takes the tone's container and
 * the label its ink. The tone adds nothing a word does not: the label or
 * the figure says why the row stands out.
 *
 * Options (src/core/options.css, docs/options.md), on the list or any
 * ancestor; each is computed here, in the rule that uses it:
 *   size      .ds-xs ... .ds-xl: the row 8px per step (32px at md)
 *   density   .ds-density-*: the row 4px per step, the gap between rows
 *             1px per step
 *   shape     .ds-shape-*: the bar's corners times --ds-shape (never above
 *             half the row)
 *   touch     .ds-touch: a row whose label is a link is at least
 *             --ds-target-min high
 *   tone      above
 *
 * The share glides on --ds-ease-value over --ds-dur-glide when it changes;
 * the first render fills from zero with .ds-enter--fill
 * (DS.motion.enterAll(rows, 'fill')). Reorders go through DS.motion.flip.
 *
 * Accessibility: an <ol> (ranked) or <ul> with a name; each row reads its
 * label and figure. The bar is a background and says nothing of its own.
 * Forced colours: the bar is an outline of CanvasText that ends (closed)
 * at its share, the text CanvasText. Printed, the bars keep their colours.
 *
 * Hooks: --ds-bar-list-height (32px), --ds-bar-list-bar (--ds-accent),
 * --ds-bar-list-ink (--ds-text).
 */

@layer ds.components.bar-list {
  .ds-bar-list {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    gap: calc(var(--ds-space-1) + var(--ds-density, 0) * 1px) var(--ds-space-4);
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .ds-bar-list__item {
    --_h: calc(var(--ds-bar-list-height, 32px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px);
    --_radius: min(calc(var(--ds-radius-sm) * var(--ds-shape, 1)), calc(var(--_h) / 2));
    --_bar: var(--ds-bar-list-bar, var(--ds-accent));
    --_ink: var(--ds-bar-list-ink, var(--ds-text));
    display: grid;
    grid-template-columns: subgrid;
    grid-column: 1 / -1;
    align-items: center;
    min-height: var(--_h);
    transition: --ds-share var(--ds-dur-glide) var(--ds-ease-value);
  }

  /* A row that holds a link is a target: touch makes it tall enough. */
  .ds-bar-list__item:has(> a.ds-bar-list__label) {
    min-height: max(var(--ds-target-min, 0px), var(--_h));
  }

  .ds-bar-list__label {
    position: relative;
    isolation: isolate;
    display: flex;
    align-items: center;
    gap: var(--ds-space-2);
    align-self: stretch;
    min-width: 0;
    padding-inline: var(--ds-space-2);
    border-radius: var(--_radius);
    color: var(--_ink);
    font: var(--ds-font-label);
    text-decoration: none;
  }

  /* A link's inset ring rests on the edge; only its offset moves. */
  a.ds-bar-list__label {
    outline-offset: 0;
    transition: outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  /* The bar: behind the label, clipped at the share, so its end keeps its
     corners as it glides. */
  .ds-bar-list__label::before {
    content: '';
    position: absolute;
    inset: 0;
    z-index: -1;
    border-radius: inherit;
    background: var(--_bar);
    clip-path: inset(0 calc((1 - var(--ds-share, 0)) * 100%) 0 0 round var(--_radius));
  }

  .ds-bar-list__label:dir(rtl)::before {
    clip-path: inset(0 0 0 calc((1 - var(--ds-share, 0)) * 100%) round var(--_radius));
  }

  .ds-bar-list__label > svg {
    flex: none;
  }

  .ds-bar-list__label > span,
  .ds-bar-list__label:not(:has(> *)) {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  @media (hover: hover) {
    a.ds-bar-list__label:hover > span,
    a.ds-bar-list__label:not(:has(> span)):hover {
      text-decoration: underline;
    }
  }

  a.ds-bar-list__label:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: calc(-1 * var(--ds-focus-width));
  }

  .ds-bar-list__value {
    color: var(--ds-text);
    font: var(--ds-font-label);
    font-variant-numeric: tabular-nums;
    text-align: end;
    white-space: nowrap;
  }

  .ds-bar-list--plain .ds-bar-list__item {
    --_bar: var(--ds-chart-track);
  }

  .ds-bar-list__item:is(.ds-tone-neutral, .ds-tone-primary, .ds-tone-info, .ds-tone-success, .ds-tone-warning, .ds-tone-error) {
    --_bar: var(--ds-tone-container);
    --_ink: var(--ds-on-tone-container);
  }

  /* The outline closes at the share: the box ends there instead of a clip,
     which would cut the outline's end away. */
  @media (forced-colors: active) {
    .ds-bar-list__label::before,
    .ds-bar-list__label:dir(rtl)::before {
      inset-inline-end: calc((1 - var(--ds-share, 0)) * 100%);
      background: transparent;
      outline: 1px solid CanvasText;
      outline-offset: -1px;
      clip-path: none;
    }
  }

  @media print {
    .ds-bar-list__label::before {
      -webkit-print-color-adjust: exact;
      print-color-adjust: exact;
    }
  }
}

/* ── components/category-bar/category-bar.css ── */
/*
 * Category bar: the parts of a whole on one bar, with a legend that names
 * each part and its figure (tickets by status, storage by kind, a budget
 * spent per team). A segmented meter of unequal parts.
 *
 *   <figure class="ds-category-bar">
 *     <figcaption class="ds-category-bar__head">
 *       <span class="ds-category-bar__label">Tickets by status</span>
 *       <span class="ds-category-bar__total">240</span>
 *     </figcaption>
 *     <div class="ds-category-bar__track" role="img"
 *          aria-label="Open 120 (50%), in progress 72 (30%), closed 48 (20%)">
 *       <span class="ds-category-bar__part" style="--ds-share: .5"></span>
 *       <span class="ds-category-bar__part ds-category-bar__part--s2" style="--ds-share: .3"></span>
 *       <span class="ds-category-bar__part ds-category-bar__part--s3" style="--ds-share: .2"></span>
 *       <span class="ds-category-bar__marker" style="--ds-share: .8"></span>
 *     </div>
 *     <ul class="ds-legend" aria-hidden="true">
 *       <li><span class="ds-legend__key"></span>Open <span class="ds-category-bar__value">120</span></li>
 *       ...
 *     </ul>
 *   </figure>
 *
 *   .ds-category-bar__part      a part as wide as its --ds-share of the
 *                               whole (flex-grow: the shares need not add
 *                               up to 1; what is left over stays track);
 *                               --s2 ... --s4 the series colours of the
 *                               legend's keys, a .ds-tone-* on the part its
 *                               chart role
 *   .ds-category-bar__marker    a mark across the bar at its own share (a
 *                               target, a limit)
 *   .ds-category-bar__value     a figure inside a legend entry, tabular
 *   .ds-category-bar--rest      the track shows what the parts leave over
 *                               (their shares add up to less than 1:
 *                               a budget not spent yet). Leave a part of
 *                               no share out: it would still take a gap
 *
 * The parts are --ds-space-1 / 2 apart (a gap of the surface), so they
 * stay apart where two colours are close.
 *
 * Options (src/core/options.css, docs/options.md), on the bar or any
 * ancestor; each is computed here, in the rule that uses it:
 *   size      .ds-xs ... .ds-xl: the track 2px per step (8px at md)
 *   density   .ds-density-*: the gap between its rows 1px per step
 *   shape     .ds-shape-*: the track's ends and the parts' inner corners
 *             times --ds-shape
 *   tone      on a part itself (an inherited tone would recolour every
 *             part): neutral, warning and error the chart roles, the
 *             others the tone; always named in the legend
 *   touch     not read: nothing here is a target
 *
 * The shares glide on --ds-ease-value over --ds-dur-glide (registered;
 * the width follows); the first render fills from zero with
 * .ds-enter--fill on the parts.
 *
 * Accessibility: the track is role="img" with a label that names every
 * part with its figure; the legend repeats it for the eye and is
 * aria-hidden (or the track is aria-hidden and the legend is read: one of
 * the two). Forced colours: the parts are CanvasText, series 2 to 4
 * hatched like the legend keys, with a Canvas gap; the marker CanvasText.
 *
 * Hooks: --ds-category-bar-height (8px), --ds-category-bar-gap (2px).
 */

@layer ds.components.category-bar {
  .ds-category-bar {
    display: grid;
    gap: calc(var(--ds-space-2) + var(--ds-density, 0) * 1px);
    min-width: 0;
    margin: 0;
  }

  .ds-category-bar__head {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: var(--ds-space-3);
    min-width: 0;
    color: var(--ds-text);
    font: var(--ds-font-label);
  }

  .ds-category-bar__label {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .ds-category-bar__total,
  .ds-category-bar__value {
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
  }

  .ds-category-bar__value {
    color: var(--ds-text);
  }

  .ds-category-bar__track {
    --_h: max(calc(var(--ds-category-bar-height, 8px) + var(--ds-size-step, 0) * 2px), 2px);
    --_radius: min(calc(min(var(--ds-radius-action), calc(var(--_h) / 2)) * var(--ds-shape, 1)), calc(var(--_h) / 2));
    position: relative;
    display: flex;
    gap: var(--ds-category-bar-gap, 2px);
    height: var(--_h);
    border-radius: var(--_radius);
  }

  /* Shares that add up to less than 1 leave that much of the flex room
     free: the track shows it. */
  .ds-category-bar--rest .ds-category-bar__track {
    background: var(--ds-chart-track);
  }

  .ds-category-bar__part {
    --_fill: var(--ds-chart-1);
    flex: var(--ds-share, 0) 1 0;
    min-width: 0;
    background: var(--_fill);
    transition: --ds-share var(--ds-dur-glide) var(--ds-ease-value);
  }

  /* The ends of the bar are the first and the last part's; the track does
     not clip, so a marker may reach past it. */
  .ds-category-bar__part:first-child {
    border-start-start-radius: var(--_radius);
    border-end-start-radius: var(--_radius);
  }

  .ds-category-bar__part:nth-last-child(1 of .ds-category-bar__part) {
    border-start-end-radius: var(--_radius);
    border-end-end-radius: var(--_radius);
  }

  .ds-category-bar__part--s2 {
    --_fill: var(--ds-chart-2);
  }

  .ds-category-bar__part--s3 {
    --_fill: var(--ds-chart-3);
  }

  .ds-category-bar__part--s4 {
    --_fill: var(--ds-chart-4);
  }

  .ds-category-bar__part:is(.ds-tone-primary, .ds-tone-info, .ds-tone-success) {
    --_fill: var(--ds-tone);
  }

  .ds-category-bar__part.ds-tone-neutral {
    --_fill: var(--ds-chart-neutral);
  }

  .ds-category-bar__part.ds-tone-warning {
    --_fill: var(--ds-chart-warning);
  }

  .ds-category-bar__part.ds-tone-error {
    --_fill: var(--ds-chart-error);
  }

  /* A mark across the bar at its own share, 3px past it on both sides; it
     never moves with the parts. */
  .ds-category-bar__marker {
    position: absolute;
    inset-block: -3px;
    inset-inline-start: calc(var(--ds-share) * 100% - 1px);
    width: 2px;
    border-radius: calc(var(--ds-radius-xs) * var(--ds-shape, 1));
    background: var(--ds-text);
    box-shadow: 0 0 0 1px var(--ds-surface);
    transition: none;
  }

  @media (forced-colors: active) {
    .ds-category-bar__track {
      forced-color-adjust: none;
      outline: 1px solid CanvasText;
      background: Canvas;
    }

    .ds-category-bar__part {
      background: CanvasText;
    }

    .ds-category-bar__part--s2 {
      background: repeating-linear-gradient(45deg, CanvasText 0 2px, Canvas 2px 4px);
    }

    .ds-category-bar__part--s3 {
      background: repeating-linear-gradient(135deg, CanvasText 0 2px, Canvas 2px 4px);
    }

    .ds-category-bar__part--s4 {
      background: repeating-linear-gradient(90deg, CanvasText 0 2px, Canvas 2px 4px);
    }

    .ds-category-bar__marker {
      forced-color-adjust: none;
      background: CanvasText;
      box-shadow: 0 0 0 1px Canvas;
    }
  }

  @media print {
    .ds-category-bar__part,
    .ds-category-bar--rest .ds-category-bar__track {
      -webkit-print-color-adjust: exact;
      print-color-adjust: exact;
    }
  }
}

/* ── components/lozenge/lozenge.css ── */
/*
 * State label (lozenge): the workflow state of one item in a bold, filled
 * pill: open, in review, merged, closed, draft. One per item, in its head
 * (a ticket's title row, a change request), where the state is the first
 * thing to read. A status chip (.ds-status) says how a thing is doing; a
 * tag (.ds-tag) adds a word; the lozenge says where an item stands in its
 * workflow.
 *
 *   <span class="ds-lozenge ds-tone-success">(circleDot 16) <span>Open</span></span>
 *   <span class="ds-lozenge ds-tone-neutral">(pencil 16) <span>Draft</span></span>
 *   <span class="ds-lozenge ds-lozenge--subtle ds-tone-error">(circleX 16) <span>Closed</span></span>
 *
 *   (none)              filled: the tone's colour with its on-colour
 *   --subtle            the tone's container pair, for a list of many
 *   .ds-tone-*          from the class on the lozenge itself (an inherited
 *                       tone would recolour every state in a tinted
 *                       region); without one, neutral
 *
 * Always a word, and usually an icon: the state is never the colour
 * alone, and the same state keeps the same icon everywhere.
 *
 * Options (src/core/options.css, docs/options.md), on the lozenge or any
 * ancestor; each is computed here, in the rule that uses it:
 *   size      .ds-xs ... .ds-xl: 4px per step (28px at md), the side
 *             padding 2px per step; the type and the icon stay
 *   shape     .ds-shape-*: the radius times --ds-shape (a pill at the
 *             default, never rounder than half its height)
 *   tone      above
 *   density, touch: not read. A lozenge is no target and sits in a line.
 *
 * Accessibility: plain text in the item's head; nothing takes focus. A
 * state that changes while the page is open is announced by the page
 * (DS.a11y.announce), not by the lozenge.
 * Forced colours: a transparent outline becomes its CanvasText edge, the
 * text CanvasText.
 *
 * Hooks: --ds-lozenge-height (28px), --ds-lozenge-radius
 * (--ds-radius-action).
 *
 * A state that changes glides its colours over --ds-dur-medium; render
 * with DS.dom.morphHtml so the element stays and the class change
 * transitions.
 */

@layer ds.components.lozenge {
  .ds-lozenge {
    --_h: calc(var(--ds-lozenge-height, 28px) + var(--ds-size-step, 0) * 4px);
    --_half: calc(max(var(--_h), 1lh) / 2);
    --_bg: var(--ds-text-2);
    --_ink: var(--ds-surface);
    display: inline-flex;
    align-items: center;
    gap: var(--ds-space-1);
    min-height: var(--_h);
    max-width: 100%;
    padding: 0 calc(var(--ds-space-3) + var(--ds-size-step, 0) * 2px);
    border-radius: min(calc(min(var(--ds-lozenge-radius, var(--ds-radius-action)), var(--_half)) * var(--ds-shape, 1)), var(--_half));
    outline: 1px solid transparent;
    outline-offset: -1px;
    background: var(--_bg);
    color: var(--_ink);
    font: var(--ds-font-label);
    white-space: nowrap;
    vertical-align: middle;
    transition: background-color var(--ds-dur-medium) var(--ds-ease-in-out), color var(--ds-dur-medium) var(--ds-ease-in-out);
  }

  .ds-lozenge > svg {
    flex: none;
    width: 16px;
    height: 16px;
  }

  .ds-lozenge:has(> svg:first-child) {
    padding-inline-start: calc(var(--ds-space-2) + var(--ds-size-step, 0) * 2px);
  }

  .ds-lozenge > span {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  .ds-lozenge:is(.ds-tone-neutral, .ds-tone-primary, .ds-tone-info, .ds-tone-success, .ds-tone-warning, .ds-tone-error) {
    --_bg: var(--ds-tone);
    --_ink: var(--ds-on-tone);
  }

  .ds-lozenge--subtle {
    --_bg: var(--ds-surface-high);
    --_ink: var(--ds-text);
  }

  .ds-lozenge--subtle:is(.ds-tone-neutral, .ds-tone-primary, .ds-tone-info, .ds-tone-success, .ds-tone-warning, .ds-tone-error) {
    --_bg: var(--ds-tone-container);
    --_ink: var(--ds-on-tone-container);
  }

  @media print {
    .ds-lozenge {
      -webkit-print-color-adjust: exact;
      print-color-adjust: exact;
    }
  }
}

/* ── components/result/result.css ── */
/*
 * Result page: the whole page, or a whole panel, says how a request ended
 * when there is nothing else to show: done, not allowed (403), not found
 * (404), failed (500), down for maintenance, offline. A disc with the
 * cause's icon (or a picture), the code, a title that says what happened,
 * one line of what to do, the way out, and a reference for support.
 *
 *   <main class="ds-result ds-result--not-found" aria-labelledby="result-title">
 *     <span class="ds-result__disc" aria-hidden="true">(mapPin 32)</span>
 *     <p class="ds-result__code">404</p>
 *     <h1 class="ds-result__title" id="result-title">Page not found</h1>
 *     <p class="ds-result__text">The address may be mistyped, or the page has moved.</p>
 *     <div class="ds-result__actions">
 *       <a class="ds-btn ds-btn--filled" href="/">Go to the overview</a>
 *       <a class="ds-btn ds-btn--text" href="/search">Search</a>
 *     </div>
 *     <p class="ds-result__meta">Reference 9F2C-118A</p>
 *   </main>
 *
 * Causes (the disc's colours; the icon, words and actions are the page's,
 * docs/components.md suggests them per cause):
 *   --success      done: the success container
 *   --forbidden    403, not allowed: neutral
 *   --not-found    404: the accent tint
 *   --error        500, it failed: the error container
 *   --maintenance  down on purpose, back soon: the warning container
 *   --offline      no connection: the warning container
 *   .ds-tone-*     any other meaning, from the class on .ds-result itself
 * The icon and the words always say it, never the colour alone; the code
 * is a figure for support, never the only word.
 *
 * Parts: .ds-result__media (a picture in place of the disc, at most
 * --ds-result-media-size high), .ds-result__code (the status code, in the
 * display type, quiet), .ds-result__title, .ds-result__text,
 * .ds-result__actions (one filled button at most, and a text button),
 * .ds-result__meta (a reference, a time: caption type, selectable).
 *
 * Options (src/core/options.css, docs/options.md), on it or any ancestor;
 * each is computed here, in the rule that uses it:
 *   size      .ds-xs ... .ds-xl: the disc 8px per step (80px at md) and
 *             the block padding 8px per step; the type stays
 *   density   .ds-density-*: the block padding 4px per step, the gaps 1px
 *   shape     .ds-shape-*: the disc's radius times --ds-shape (round at
 *             the default, never rounder than half its size)
 *   tone      above
 *   touch     only its buttons read it
 *
 * In a phone's width the actions stack, full width. No motion of its own:
 * a result that replaces content after a request comes in with .ds-reveal
 * (docs/motion.md).
 *
 * Accessibility: one h1 (the title; a result inside a panel takes the
 * panel's heading level), the landmark or panel named by it. After a
 * request in a single-page app, focus goes to the title (tabindex="-1")
 * so the result is read. Forced colours: the disc keeps an outline (its
 * fill is dropped).
 *
 * Hooks: --ds-result-disc-size (80px), --ds-result-media-size (200px),
 * --ds-result-padding (--ds-space-12).
 *
 * Progressive:
 * - text-wrap: pretty (the text avoids a lone last word): without it the
 *   line wraps as usual.
 */

@layer ds.components.result {
  .ds-result {
    --_disc-bg: var(--ds-accent);
    --_disc-ink: var(--ds-on-accent-icon);
    display: grid;
    justify-items: center;
    align-content: center;
    gap: calc(var(--ds-space-2) + var(--ds-density, 0) * 1px);
    max-width: 560px;
    min-height: min(100%, 100svh);
    margin: 0 auto;
    padding: calc(var(--ds-result-padding, var(--ds-space-12)) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px) var(--ds-space-4);
    text-align: center;
  }

  .ds-result__disc {
    --_d: calc(var(--ds-result-disc-size, 80px) + var(--ds-size-step, 0) * 8px);
    display: grid;
    place-items: center;
    width: var(--_d);
    height: var(--_d);
    margin-bottom: var(--ds-space-3);
    border-radius: min(calc(min(var(--ds-radius-action), calc(var(--_d) / 2)) * var(--ds-shape, 1)), calc(var(--_d) / 2));
    outline: 1px solid transparent;
    background: var(--_disc-bg);
    color: var(--_disc-ink);
  }

  .ds-result__media {
    display: grid;
    place-items: center;
    max-width: 100%;
    height: var(--ds-result-media-size, 200px);
    margin-bottom: var(--ds-space-3);
    color: var(--ds-text-2);
  }

  .ds-result__media > :is(img, svg) {
    display: block;
    max-width: 100%;
    height: 100%;
  }

  .ds-result__code {
    margin: 0;
    color: var(--ds-text-2);
    font: var(--ds-font-headline);
    font-variant-numeric: tabular-nums;
  }

  .ds-result__title {
    margin: 0;
    color: var(--ds-text);
    font: var(--ds-font-display);
    text-wrap: balance;
  }

  /* Focused after a request, so it is read; it shows no ring of its own
     (it is no control), the page's skip target style aside. */
  .ds-result__title:focus {
    outline: none;
  }

  .ds-result__text {
    max-width: var(--ds-measure);
    margin: 0;
    color: var(--ds-text-2);
    font: var(--ds-font-body);
    text-wrap: pretty;
  }

  .ds-result__actions {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: var(--ds-space-2);
    margin-top: var(--ds-space-4);
  }

  .ds-result__meta {
    margin: var(--ds-space-4) 0 0;
    color: var(--ds-text-2);
    font: var(--ds-font-caption);
    font-variant-numeric: tabular-nums;
    user-select: text;
  }

  .ds-result--success {
    --_disc-bg: var(--ds-success-container);
    --_disc-ink: var(--ds-on-success-container);
  }

  .ds-result--forbidden {
    --_disc-bg: var(--ds-surface-high);
    --_disc-ink: var(--ds-text-2);
  }

  .ds-result--not-found {
    --_disc-bg: var(--ds-accent);
    --_disc-ink: var(--ds-on-accent-icon);
  }

  .ds-result--error {
    --_disc-bg: var(--ds-error-container);
    --_disc-ink: var(--ds-on-error-container);
  }

  .ds-result--maintenance,
  .ds-result--offline {
    --_disc-bg: var(--ds-warning-container);
    --_disc-ink: var(--ds-on-warning-container);
  }

  /* A tone from the class on the result itself; it wins over a cause. */
  .ds-result:is(.ds-tone-neutral, .ds-tone-primary, .ds-tone-info, .ds-tone-success, .ds-tone-warning, .ds-tone-error) {
    --_disc-bg: var(--ds-tone-container);
    --_disc-ink: var(--ds-on-tone-container);
  }

  /* A phone: the actions stack, full width, the filled one first. */
  @container (max-width: 480px) {
    .ds-result__actions {
      flex-direction: column;
      justify-self: stretch;
    }
  }

  @media (max-width: 480px) {
    .ds-result__actions {
      flex-direction: column;
      justify-self: stretch;
    }

    .ds-result__title {
      font: var(--ds-font-headline);
    }
  }
}

/* ── components/formatted/formatted.css ── */
/*
 * Formatted values and relative times: figures written by DS.formatted
 * ([data-ds-format]: number, compact, percent, currency, bytes,
 * duration) and times written by DS.format ([data-ds-time], "3 min ago")
 * keep tabular figures and never break inside. One that rounds its value
 * carries the exact value in a tooltip (data-tip, written by the
 * behaviour): a dotted underline says so, as on <abbr>.
 *
 *   <span data-ds-format="bytes" data-ds-value="1536"></span>
 *   <time data-ds-time datetime="2026-11-04T09:00:00Z">Nov 4, 09:00</time>
 *
 *   .ds-value--plain   no underline under a value with a tip (a table
 *                      cell full of them: the tip still shows)
 *
 * Options: none read; the value takes the type of where it stands. Tone:
 * never; a figure's meaning is in its words or its column.
 * Forced colours: the underline is the text colour. Accessibility: the
 * text is read; the exact value is the tooltip's description, shown on
 * hover and on keyboard focus (give an element tabindex="0" where its
 * exact value matters to a keyboard user).
 */

@layer ds.components.formatted {
  :where(.ds-theme) :is([data-ds-format], time[data-ds-time]) {
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
  }

  /* :where() keeps this at one attribute (0,1,0), so .ds-value--plain wins. */
  :where(.ds-theme) :where([data-ds-format], time[data-ds-time])[data-tip] {
    text-decoration: underline dotted;
    text-decoration-color: var(--ds-text-3);
    text-underline-offset: var(--ds-link-underline-offset);
    cursor: help;
  }

  .ds-value--plain[data-tip] {
    text-decoration: none;
    cursor: auto;
  }

  @media (forced-colors: active) {
    :where(.ds-theme) :where([data-ds-format], time[data-ds-time])[data-tip] {
      text-decoration-color: CanvasText;
    }
  }
}

/* ── components/kbd/kbd.css ── */
/*
 * Key combos: a shortcut as the keys of this platform, one .ds-kbd (the
 * key of utilities.css) per key, written by DS.kbd from data-ds-kbd.
 *
 *   <kbd class="ds-kbd-combo" data-ds-kbd="mod+shift+k"></kbd>
 *     becomes, on Apple systems:
 *   <kbd class="ds-kbd-combo" data-ds-kbd="mod+shift+k">
 *     <span class="ds-kbd-combo__keys" aria-hidden="true"><span class="ds-kbd-combo__combo">
 *       <kbd class="ds-kbd">⇧</kbd><kbd class="ds-kbd">⌘</kbd><kbd class="ds-kbd">K</kbd></span></span>
 *     <span class="ds-sr">Shift Command K</span></kbd>
 *
 *   .ds-kbd-combo__keys   the keys, hidden from assistive technology (the
 *                         .ds-sr text says them in words)
 *   .ds-kbd-combo__combo  one combo's keys, on one line
 *   .ds-kbd-combo__plus   "+" between two keys, where the platform
 *                         writes it (not on Apple systems)
 *   .ds-kbd-combo__then   "then" between the combos of a sequence
 *
 * The keys sit on one line and never break inside a combo; a sequence may
 * wrap between its combos. In a menu item's meta or a tooltip the combo
 * takes the type of where it stands, the keys keep the code font.
 *
 * Options: none read; a key keeps the size of utilities.css (.ds-shape-*
 * multiplies its radius there). Forced colours: the keys keep their edge
 * (a border), the separators the text colour.
 */

@layer ds.components.kbd {
  .ds-kbd-combo {
    display: inline-flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--ds-space-1);
    font: inherit;
    vertical-align: baseline;
  }

  .ds-kbd-combo__keys {
    display: contents;
  }

  .ds-kbd-combo__plus,
  .ds-kbd-combo__then {
    color: var(--ds-text-2);
    font: var(--ds-font-caption);
  }

  /* A combo stays on one line; only a sequence wraps, between its combos. */
  .ds-kbd-combo__combo {
    display: inline-flex;
    align-items: center;
    gap: var(--ds-space-1);
    white-space: nowrap;
  }
}

/* ── components/truncate/truncate.css ── */
/*
 * Truncate: a text too long for its place, cut at its end, its start or
 * its middle with an ellipsis, whole in a tooltip while it is cut and
 * always whole for a screen reader (DS.truncate, data-ds-truncate).
 *
 *   <span class="ds-truncate" data-ds-truncate="end">Replace the toner of every printer on floor 2</span>
 *   <span class="ds-truncate" data-ds-truncate="middle">inventory-export-2026-11-04-final.csv</span>
 *   <a href="..."><span class="ds-truncate" data-ds-truncate="start">/devices/north/floor-2/printer-7</span></a>
 *
 *   .ds-truncate          one line, at most as wide as its container; the
 *                         end is cut by text-overflow, the start and the
 *                         middle by the module (.ds-truncate__shown, with
 *                         the whole text in a .ds-sr beside it)
 *   .ds-truncate--lines   up to --ds-truncate-lines lines (2), then the
 *                         end is cut: CSS alone, no tooltip (use
 *                         expandable text where all of it matters)
 *
 * In a flex row the element itself shrinks (min-width: 0); give the row's
 * other parts flex: none. A link or a button may be the .ds-truncate
 * itself: its name stays whole, and focusing it shows the tooltip.
 *
 * Options: none read; it takes the type of where it stands. Forced
 * colours: nothing of its own. No motion. On paper it prints in full.
 *
 * Hooks: --ds-truncate-lines (2).
 */

@layer ds.components.truncate {
  .ds-truncate {
    display: inline-block;
    min-width: 0;
    max-width: 100%;
    overflow: hidden;
    white-space: nowrap;
    text-overflow: ellipsis;
    vertical-align: bottom;
  }

  /* The module's cut: spaces kept as typed, never a wrap. */
  .ds-truncate__shown {
    white-space: pre;
  }

  .ds-truncate--lines {
    display: -webkit-box;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: var(--ds-truncate-lines, 2);
    line-clamp: var(--ds-truncate-lines, 2);
    white-space: normal;
    overflow-wrap: anywhere;
  }

  /* Paper is as wide as it is: cut text prints in full. */
  @media print {
    .ds-truncate {
      overflow: visible;
      white-space: normal;
    }
  }
}

/* ── components/expandable/expandable.css ── */
/*
 * Expandable text: a long text shows its first --ds-expandable-lines (3)
 * and a "Show more" button (DS.expandable, data-ds-expandable), which the
 * module adds only while the text is longer than those lines.
 *
 *   <div class="ds-expandable" data-ds-expandable [data-state="closed | open"]>
 *     <div class="ds-expandable__text" id="...">A description of many lines ...</div>
 *     <button class="ds-link-btn ds-expandable__toggle" type="button" aria-expanded="false" aria-controls="...">Show more</button>
 *   </div>
 *
 * data-state is the system's: "closed" clamps the text, "open" shows it
 * whole, none (no script, or a text that fits) shows it whole without a
 * toggle. The toggle is the inline text link of the button component.
 *
 * Options: none read; the text takes the type of where it stands, the
 * lines are the hook. No motion: the text opens and closes at once (its
 * height pushes the layout, and a clamp has no height to glide between).
 * Forced colours: nothing of its own.
 *
 * Hooks: --ds-expandable-lines (3).
 */

@layer ds.components.expandable {
  .ds-expandable {
    display: grid;
    justify-items: start;
    gap: var(--ds-space-1);
    min-width: 0;
  }

  .ds-expandable__text {
    justify-self: stretch;
    min-width: 0;
    overflow-wrap: anywhere;
  }

  .ds-expandable[data-state="closed"] > .ds-expandable__text {
    display: -webkit-box;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: var(--ds-expandable-lines, 3);
    line-clamp: var(--ds-expandable-lines, 3);
    overflow: hidden;
  }

  .ds-expandable__toggle {
    font: var(--ds-font-label);
  }
}

/* ── components/hits/hits.css ── */
/*
 * Search hits: the hits of a search in a text, each a
 * <mark class="ds-hit"> written by DS.hits (data-ds-hits on the
 * container), or by the page itself (a server that marks its results).
 *
 *   <ul data-ds-hits="toner">
 *     <li>Replace the <mark class="ds-hit" data-ds-hit>toner</mark> on floor 2</li>
 *
 *   .ds-hit   the hit: the warning container behind the text, its ink,
 *              rounded corners that hug the letters (times --ds-shape)
 *
 * Options: shape only (the corners); the mark takes the type of its text.
 * A mark is not a status: it says "this matched", and the search field
 * above says what was searched. Forced colours: the system's Mark and
 * MarkText. Printed, the background stays.
 *
 * Hooks: --ds-hit-bg (--ds-warning-container), --ds-hit-color
 * (--ds-on-warning-container).
 */

@layer ds.components.hits {
  .ds-hit {
    padding: 0 1px;
    margin: 0 -1px;
    border-radius: calc(var(--ds-radius-xs) * var(--ds-shape, 1));
    background: var(--ds-hit-bg, var(--ds-warning-container));
    color: var(--ds-hit-color, var(--ds-on-warning-container));
    box-decoration-break: clone;
    -webkit-box-decoration-break: clone;
  }

  @media (forced-colors: active) {
    .ds-hit {
      forced-color-adjust: none;
      background: Mark;
      color: MarkText;
    }
  }

  @media print {
    .ds-hit {
      -webkit-print-color-adjust: exact;
      print-color-adjust: exact;
    }
  }
}

/* ── components/tracker/tracker.css ── */
/*
 * Tracker: a row of status cells, one per day, run or check (uptime over
 * 90 days, the last 30 runs of a job), a summary in words above it and the
 * span under it. Each state has its own shape, so it reads without its
 * colour: problems stand to the full height, the calm states stay low, and
 * the doubtful ones are dashed.
 *
 *   <figure class="ds-tracker">
 *     <figcaption class="ds-tracker__head">
 *       <span class="ds-tracker__label">Printer 7</span>
 *       <span class="ds-tracker__summary">99.2% uptime, 2 failures in 90 days</span>
 *     </figcaption>
 *     <div class="ds-tracker__cells" role="group" aria-label="Printer 7, last 90 days" data-ds-tracker>
 *       <span class="ds-tracker__cell ds-tracker__cell--success" role="img" aria-label="Nov 3: up" data-tip="Nov 3: up"></span>
 *       <span class="ds-tracker__cell ds-tracker__cell--error" role="img" aria-label="Nov 4: down 42 min" data-tip="Nov 4: down 42 min"></span>
 *       ...
 *     </div>
 *     <div class="ds-tracker__axis"><span>90 days ago</span><span>Today</span></div>
 *   </figure>
 *
 *   .ds-tracker__cell--success   low (60%), solid: up, passed
 *   .ds-tracker__cell--info      low, dashed: maintenance, skipped
 *   .ds-tracker__cell--warning   full height, dashed: degraded, flaky
 *   .ds-tracker__cell--error     full height, solid: down, failed
 *   .ds-tracker__cell--empty     a stub at the foot: no data
 *   .ds-tracker__legend          the states named, each with a small cell
 *
 * The whole cell is the target of its tooltip; the shape is drawn by its
 * background, so a low cell still answers at its full height.
 *
 * Options (src/core/options.css, docs/options.md), on the tracker or any
 * ancestor; each is computed here, in the rule that uses it:
 *   size      .ds-xs ... .ds-xl: the row 4px per step (32px at md)
 *   density   .ds-density-*: the gap between head, row and axis 1px per
 *             step
 *   shape     .ds-shape-*: the cells' corners times --ds-shape
 *   tone      not read: the state classes carry the meaning, each with its
 *             own shape and word
 *   touch     not read: the cells are one tab stop with the arrow keys,
 *             and a tap shows a cell's tooltip
 *
 * Behaviour (DS.tracker, data-ds-tracker on the row): one tab stop, the
 * arrow keys, Home and End move between the cells; a focused cell shows
 * its tooltip (DS.overlay.tooltips). Narrow, below 480px of the row, the
 * gap closes to 1px so 90 cells fit a phone.
 *
 * Accessibility: the row is a named group of role="img" cells, each named
 * with its date and state; the summary says what the row adds up to. A
 * screen reader hears the summary first, then may walk the cells.
 * Forced colours: the cells are CanvasText with their shapes; the empty
 * stub GrayText; a focused cell its ring.
 *
 * Hooks: --ds-tracker-height (32px), --ds-tracker-gap (2px).
 *
 * No motion: a cell that changes state takes its new colour and shape at
 * once (a live row re-renders with DS.dom.morphHtml). Its focus ring snaps
 * as everywhere.
 */

@layer ds.components.tracker {
  .ds-tracker {
    display: grid;
    gap: calc(var(--ds-space-2) + var(--ds-density, 0) * 1px);
    min-width: 0;
    margin: 0;
  }

  .ds-tracker__head {
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    justify-content: space-between;
    column-gap: var(--ds-space-3);
    min-width: 0;
  }

  .ds-tracker__label {
    min-width: 0;
    overflow: hidden;
    color: var(--ds-text);
    font: var(--ds-font-label);
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .ds-tracker__summary {
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
    font-variant-numeric: tabular-nums;
  }

  .ds-tracker__cells {
    --_h: max(calc(var(--ds-tracker-height, 32px) + var(--ds-size-step, 0) * 4px), 16px);
    container-type: inline-size;
    display: flex;
    height: var(--_h);
    min-width: 0;
  }

  .ds-tracker__cell {
    --_fill: var(--ds-success);
    /* How high the shape stands, and its dashes (none: solid). */
    --_high: 60%;
    --_dash: var(--_fill);
    flex: 1 1 0;
    min-width: 2px;
    border-radius: calc(var(--ds-radius-xs) * var(--ds-shape, 1) / 2);
    background:
      repeating-linear-gradient(to top, var(--_fill) 0 4px, var(--_dash) 4px 6px)
      bottom / 100% var(--_high) no-repeat;
    outline-offset: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    transition: outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-tracker__cell:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: var(--ds-focus-offset);
  }

  .ds-tracker__cell--success {
    --_fill: var(--ds-success);
  }

  .ds-tracker__cell--info {
    --_fill: var(--ds-info);
    --_dash: transparent;
  }

  .ds-tracker__cell--warning {
    --_fill: var(--ds-chart-warning);
    --_dash: transparent;
    --_high: 100%;
  }

  .ds-tracker__cell--error {
    --_fill: var(--ds-chart-error);
    --_high: 100%;
  }

  .ds-tracker__cell--empty {
    --_fill: var(--ds-chart-track);
    --_high: 4px;
  }

  /* The gap as a margin, so the container query below can close it. */
  .ds-tracker__cells > .ds-tracker__cell + .ds-tracker__cell {
    margin-inline-start: var(--ds-tracker-gap, 2px);
  }

  /* Many cells in a narrow row: the gap closes so each keeps its width. */
  @container (max-width: 479px) {
    .ds-tracker__cells > .ds-tracker__cell + .ds-tracker__cell {
      margin-inline-start: min(var(--ds-tracker-gap, 2px), 1px);
    }
  }

  .ds-tracker__axis {
    display: flex;
    justify-content: space-between;
    gap: var(--ds-space-3);
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
  }

  /* The states named, each with a small cell of its own shape. */
  .ds-tracker__legend {
    display: flex;
    flex-wrap: wrap;
    gap: var(--ds-space-1) var(--ds-space-4);
    margin: 0;
    padding: 0;
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
    list-style: none;
  }

  .ds-tracker__legend > li {
    display: inline-flex;
    align-items: center;
    gap: var(--ds-space-2);
  }

  .ds-tracker__legend .ds-tracker__cell {
    flex: none;
    width: 6px;
    height: 16px;
  }

  @media (forced-colors: active) {
    .ds-tracker__cell {
      forced-color-adjust: none;
      --_fill: CanvasText;
    }

    .ds-tracker__cell:is(.ds-tracker__cell--info, .ds-tracker__cell--warning) {
      --_dash: Canvas;
    }

    .ds-tracker__cell--empty {
      --_fill: GrayText;
    }

    .ds-tracker__cell:focus-visible {
      outline-color: Highlight;
    }
  }

  @media print {
    .ds-tracker__cell {
      -webkit-print-color-adjust: exact;
      print-color-adjust: exact;
    }
  }
}

/* ── components/labelgroup/labelgroup.css ── */
/*
 * Label group: the tags of one item on one line, as many as fit, then a
 * "+N" button that shows all of them in a popup (a ticket's labels in a
 * table row, a device's groups in a card head).
 *
 *   <div class="ds-label-group" data-ds-label-group>
 *     <ul class="ds-label-group__list" aria-label="Labels of ticket 42">
 *       <li><span class="ds-tag">Printer</span></li>
 *       <li><span class="ds-tag ds-tone-warning">Waiting</span></li>
 *       ...
 *     </ul>
 *   </div>
 *
 * Written by DS.labelgroup (data-ds-label-group), after the list:
 *
 *   <button class="ds-btn ds-btn--tonal ds-label-group__more" type="button"
 *           aria-haspopup="dialog" aria-expanded="false" aria-controls="..."
 *           aria-label="+3 more, show all 8"><span aria-hidden="true">+3</span></button>
 *   <div class="ds-label-group__popup" role="dialog" aria-label="Labels of ticket 42" tabindex="-1" hidden>
 *     <ul class="ds-label-group__all">...every tag again...</ul>
 *   </div>
 *
 *   .ds-label-group           one line: the list, then the button
 *   .ds-label-group__list     the tags that fit (the others hidden); one
 *                             left alone ends in an ellipsis
 *   .ds-label-group__more     a tonal button as high as a tag
 *   .ds-label-group__popup    every tag, wrapping, in a popup at the
 *                             button (DS.overlay)
 *   .ds-label-group__all      the list in the popup
 *
 * Options (src/core/options.css, docs/options.md), on the group or any
 * ancestor; each is computed here, in the rule that uses it:
 *   size      .ds-xs ... .ds-xl: the button 4px per step, as the tags
 *             (24px at md); its side padding 2px per step
 *   shape     .ds-shape-*: the button's pill and the popup's corners times
 *             --ds-shape
 *   touch     .ds-touch: the button at least --ds-touch-target high
 *   density, tone: not read (the tags carry their own tones and words).
 *
 * The popup: placed below the button (above it without room), in the top
 * layer and anchored where the engine can (data-anchored), else by the
 * script (--ds-label-group-x / -y, fixed). It opens and closes through
 * DS.overlay: it fades in and grows from the button on the spring, the
 * exit only fades; Escape closes it and focus goes back to the button;
 * a pointerdown outside it or focus that leaves it closes it too.
 * Transitions keyed on data-state, so a close mid-way turns back from
 * where it is.
 *
 * Progressive:
 * - anchor positioning (position-area and position-try-fallbacks on the
 *   popup in the top layer, behind @supports (position-area: block-end)):
 *   without it the script places the popup by --ds-label-group-x/-y.
 *
 * Forced colours: the popup's transparent outline becomes its edge; the
 * button is a button (button.css).
 *
 * Hooks: --ds-label-group-gap (--ds-space-1).
 */

@layer ds.components.labelgroup {
  .ds-label-group {
    display: flex;
    align-items: center;
    gap: var(--ds-label-group-gap, var(--ds-space-1));
    min-width: 0;
  }

  /* One line: what does not fit is hidden by the module, so nothing here
     wraps. The padding keeps room for a tag's focus ring inside the clip. */
  .ds-label-group__list {
    display: flex;
    align-items: center;
    gap: var(--ds-label-group-gap, var(--ds-space-1));
    min-width: 0;
    margin: calc(-1 * (var(--ds-focus-offset) + var(--ds-focus-width)));
    padding: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    overflow: hidden;
    list-style: none;
  }

  .ds-label-group__list > li {
    display: flex;
    flex: none;
    max-width: 100%;
    min-width: 0;
  }

  .ds-label-group__list > [hidden] {
    display: none;
  }

  /* A tag left alone in too little room ends in an ellipsis. */
  .ds-label-group__list > li > .ds-tag {
    display: block;
    align-content: center;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  .ds-label-group__list > li > .ds-tag > svg {
    margin-inline-end: var(--ds-space-1);
    vertical-align: middle;
  }

  .ds-label-group__more {
    --ds-btn-height-exact: calc(var(--ds-tag-height, 24px) + var(--ds-size-step, 0) * 4px);
    --ds-btn-padding-x: calc(var(--ds-space-2) - var(--ds-size-step, 0) * 2px);
    --ds-btn-font: var(--ds-font-caption);
    /* As high as a tag also at xs, where the caption's line and the
       button's border would make it 2px taller. */
    block-size: max(var(--ds-target-min, 0px), calc(var(--ds-tag-height, 24px) + var(--ds-size-step, 0) * 4px));
    flex: none;
    font-variant-numeric: tabular-nums;
  }

  .ds-label-group__more[hidden] {
    display: none;
  }

  /* Fixed, so no scrolling or clipping box cuts it off. inset, margin and
     border double as the reset of the UA box of a popover. Physical on
     purpose (D9): --ds-label-group-x is a script coordinate from the left. */
  .ds-label-group__popup {
    position: fixed;
    inset: var(--ds-label-group-y, 0px) auto auto var(--ds-label-group-x, 0px);
    z-index: var(--ds-z-popover);
    box-sizing: border-box;
    width: max-content;
    max-width: min(320px, calc(100vw - 2 * var(--ds-space-2)));
    max-height: calc(100vh - 2 * var(--ds-space-2));
    margin: 0;
    padding: var(--ds-space-3);
    overflow-y: auto;
    border: 0;
    border-radius: calc(var(--ds-radius-sm) * var(--ds-shape, 1));
    background: var(--ds-surface-popover);
    color: var(--ds-text);
    box-shadow: var(--ds-elev-popover);
    /* Invisible; forced colours paint it, so the popup keeps an edge. */
    outline: 1px solid transparent;
    outline-offset: 0;
    transform-origin: var(--ds-motion-origin, 0% 0%);
    clip-path: inset(calc(-1 * var(--ds-space-6)));
    transition: outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-label-group__popup[data-placement="top"] {
    transform-origin: var(--ds-motion-origin, 0% 100%);
  }

  .ds-label-group__popup[hidden] {
    display: none;
  }

  /* Driven by DS.overlay: transitions keyed on data-state, so a popup
     closed mid-way continues from where it is. */
  .ds-label-group__popup[data-state] {
    transition:
      opacity var(--ds-dur-fast) var(--ds-ease-in-out),
      scale var(--ds-dur-medium) var(--ds-ease-spatial),
      clip-path var(--ds-dur-medium) var(--ds-ease-spatial),
      outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  /* The exit only fades, in --ds-dur-instant; scale and clip go back to
     their start once it is invisible. Closed, it takes no pointer. */
  .ds-label-group__popup[data-state="closed"] {
    opacity: 0;
    scale: var(--ds-motion-scale, var(--ds-scale-popup));
    clip-path: var(--ds-clip-from, inset(0 0 100% 0));
    pointer-events: none;
    transition:
      opacity var(--ds-dur-instant) var(--ds-ease-in-out),
      scale 0ms var(--ds-ease-in-out) var(--ds-dur-instant),
      clip-path 0ms var(--ds-ease-in-out) var(--ds-dur-instant);
  }

  .ds-label-group__popup:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: calc(-1 * var(--ds-focus-width));
  }

  @supports (position-area: block-end) {
    .ds-label-group__popup[data-anchored] {
      inset: auto;
      max-height: calc(100% - 2 * var(--ds-space-1));
      margin: var(--ds-space-1) 0;
      position-area: block-end span-inline-end;
      position-try-fallbacks: flip-block, flip-inline, flip-block flip-inline;
    }

    .ds-label-group__popup[data-anchored][data-placement="top"] {
      position-area: block-start span-inline-end;
    }
  }

  .ds-label-group__all {
    display: flex;
    flex-wrap: wrap;
    gap: var(--ds-space-2) var(--ds-label-group-gap, var(--ds-space-1));
    margin: 0;
    padding: 0;
    list-style: none;
  }

  @media print {
    .ds-label-group__popup {
      display: none;
    }
  }
}

/* ── components/image/image.css ── */
/*
 * Image: a picture in a frame of a fixed shape, cropped or fitted, with a
 * tint while it loads, words and an icon where it fails, and a caption.
 *
 *   <figure class="ds-image ds-image--wide">
 *     <span class="ds-image__frame" data-ds-image>
 *       <img src="printer-7.jpg" alt="Printer 7 by the window" loading="lazy" width="640" height="480">
 *     </span>
 *     <figcaption class="ds-image__caption">Printer 7, second floor</figcaption>
 *   </figure>
 *
 *   .ds-image              a <figure> (or a <div>): the frame and its caption
 *   .ds-image__frame       the box of the picture: its shape (the ratio),
 *                          its corners and the tint behind it; the picture
 *                          fills it
 *   .ds-image__caption     a line under it, in the meta type
 *   .ds-image__fallback    in the frame, shown where the picture failed (an
 *                          icon and the alt text); DS.image writes one when
 *                          the frame has none
 *
 * Aspect (the frame's shape): the picture's own without a modifier;
 *   --square (1 / 1), --photo (4 / 3), --wide (16 / 9), or any ratio in
 *   --ds-image-ratio. Fit: cover (cropped, the default); --contain shows
 *   the whole picture on the tint. A frame of its own shape keeps its place
 *   while the picture loads, so nothing below it moves (give a picture
 *   without one its width and height attributes).
 *
 * Behaviour (DS.image, data-ds-image on the frame): data-state "loading",
 * "loaded" or "error" on the frame. A picture that arrives after the start
 * fades in (--ds-dur-medium); one in the cache shows at once. A failed one
 * tries data-ds-image-fallback (another source) once, then shows the
 * fallback. Lazy loading is the browser's: loading="lazy" on the <img>.
 * Without the module the picture shows as it loads, and a failed one shows
 * the browser's own sign.
 *
 * Options (src/core/options.css, docs/options.md), on the image or any
 * ancestor; each is computed here, in the rule that uses it:
 *   shape     .ds-shape-*: the frame's corners times --ds-shape
 *   density   .ds-density-*: the gap to the caption 1px per step
 *   size, tone, touch: not read. A picture is as large as its place.
 *
 * Accessibility: the <img> carries the alt text (empty for decoration).
 * Where it fails, the fallback shows that text and a screen reader reads
 * it there; the icon is hidden. A caption names the picture for the eye;
 * the alt text still describes it. Forced colours: the frame keeps an edge,
 * the fallback CanvasText.
 *
 * Hooks: --ds-image-ratio (the picture's own), --ds-image-radius
 * (--ds-radius-sm), --ds-image-bg (--ds-surface-high).
 */

@layer ds.components.image {
  .ds-image {
    display: grid;
    gap: calc(var(--ds-space-2) + var(--ds-density, 0) * 1px);
    min-width: 0;
    max-width: 100%;
    margin: 0;
  }

  .ds-image__frame {
    position: relative;
    display: block;
    min-width: 0;
    overflow: hidden;
    aspect-ratio: var(--ds-image-ratio, auto);
    border-radius: calc(var(--ds-image-radius, var(--ds-radius-sm)) * var(--ds-shape, 1));
    background: var(--ds-image-bg, var(--ds-surface-high));
    /* Invisible; forced colours paint it, so the frame keeps an edge. */
    outline: 1px solid transparent;
    outline-offset: -1px;
  }

  /* 100% of a frame of its own shape; a frame without one (its height
     from the content) takes the picture's own height. */
  .ds-image__frame > img {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: cover;
    opacity: 1;
    transition: opacity var(--ds-dur-medium) var(--ds-ease-in-out);
  }

  .ds-image--square .ds-image__frame {
    aspect-ratio: var(--ds-image-ratio, 1 / 1);
  }

  .ds-image--photo .ds-image__frame {
    aspect-ratio: var(--ds-image-ratio, 4 / 3);
  }

  .ds-image--wide .ds-image__frame {
    aspect-ratio: var(--ds-image-ratio, 16 / 9);
  }

  .ds-image--contain .ds-image__frame > img {
    object-fit: contain;
  }

  /* Loading: the tint holds the place; the picture fades in once it is there. */
  .ds-image__frame[data-state="loading"] > img {
    opacity: 0;
    transition-duration: var(--ds-dur-fast);
  }

  .ds-image__fallback {
    display: none;
    place-content: center;
    justify-items: center;
    gap: var(--ds-space-1);
    min-height: 96px;
    height: 100%;
    padding: var(--ds-space-3);
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
    text-align: center;
    overflow-wrap: anywhere;
  }

  .ds-image__fallback > svg {
    color: var(--ds-text-3);
  }

  .ds-image__frame[data-state="error"] > img {
    display: none;
  }

  .ds-image__frame[data-state="error"] > .ds-image__fallback {
    display: grid;
  }

  .ds-image__caption {
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
  }

  @media (forced-colors: active) {
    .ds-image__frame {
      outline-color: CanvasText;
    }

    .ds-image__fallback,
    .ds-image__fallback > svg {
      color: CanvasText;
    }
  }
}

/* ── components/composer/composer.css ── */
/*
 * Composer: the message field of a conversation. One filled shell holds
 * the textarea, which grows with its text up to --ds-composer-max-height,
 * and its actions, which stay at the bottom; attachments sit as chips above
 * the text; a slash-command palette and @-mentions open as a listbox at the
 * caret. The shell is a form: Enter sends, Shift+Enter breaks the line.
 *
 *   <form class="ds-composer" data-ds-composer data-ds-composer-draft="ticket-42">
 *     <ul class="ds-composer__attachments" aria-label="Attachments"></ul>
 *     <button class="ds-btn ds-btn--quiet ds-btn--icon" type="button" aria-label="Attach files" data-tip="Attach files" data-ds-composer-attach>(paperclip)</button>
 *     <input class="ds-composer__picker" type="file" multiple hidden>
 *     <textarea class="ds-composer__input ds-input--grow" rows="1" aria-label="Message" placeholder="Message"></textarea>
 *     <button class="ds-btn ds-btn--quiet ds-btn--icon" type="button" aria-label="Dictate" aria-pressed="false">(mic)</button>
 *     <button class="ds-btn ds-btn--filled ds-btn--icon" type="submit" aria-label="Send" data-tip="Send">
 *       <span class="ds-icon-swap" data-swap="a"><span class="ds-icon-swap__a">(send)</span><span class="ds-icon-swap__b">(square)</span></span></button>
 *     <div class="ds-composer__palette" role="listbox" aria-label="Commands" data-ds-composer-trigger="/" popover="manual" hidden>
 *       <div class="ds-composer__option" role="option" data-value="/summarize">(sparkles)
 *         <span class="ds-composer__option-label">/summarize</span><span class="ds-composer__option-hint">Sum up the ticket</span></div>
 *       <div class="ds-composer__empty" hidden>No results</div>
 *     </div>
 *   </form>
 *
 * The simple 2.x markup (a textarea and a send button in .ds-composer)
 * still works and looks as before: the textarea's own side padding (12px)
 * and the shell's (4px) add up to the 2.x 16px.
 *
 * Parts:
 *   .ds-composer__input        the textarea (rows="1"); it grows with its
 *                              text (field-sizing, else DS.dom.autosize(),
 *                              which the module calls) up to
 *                              --ds-composer-max-height, then scrolls
 *   .ds-composer__attachments  a list of chips on a line of its own above
 *                              the text; empty, it takes no room
 *   .ds-composer__attachment   one chip: a file glyph, the name (an
 *                              ellipsis past --ds-composer-chip-max-width),
 *                              the size (.ds-composer__attachment-size) and
 *                              a remove button (.ds-btn--icon .ds-xs)
 *   .ds-composer__picker       the hidden file input the attach button opens
 *   .ds-composer__palette      the listbox popup at the caret (popover,
 *                              placed by the script: --ds-composer-palette-x
 *                              and -y in the viewport's terms); one per
 *                              trigger character (data-ds-composer-trigger:
 *                              "/" for commands, "@" for mentions)
 *   .ds-composer__option       a row: an icon, .ds-composer__option-label
 *                              and .ds-composer__option-hint; the active one
 *                              (aria-selected="true", focus stays in the
 *                              textarea) takes the focus layer and an inset
 *                              bar, so it shows without colour too
 *   .ds-composer__empty        the "No results" row, shown by the script
 *
 * States, written by the module (DS.composer):
 *   data-state="busy"          a reply is being generated: the submit
 *                              button turns into Stop (its icon swap shows
 *                              b, its name the string stop)
 *   data-ds-dragover           files are over the composer
 *                              (DS.dom.dropzone()): a dashed ring and the
 *                              drop tint
 *   :has(> .ds-composer__input:disabled)  the disabled model
 *
 * Options (src/core/options.css, docs/options.md), on the composer or any
 * ancestor; each is computed here, in the part's own rule:
 *   size      .ds-xs ... .ds-xl: the field row 8px per step (the field's
 *             height, --ds-input-height), the text of the size's role; the
 *             palette rows 8px per step
 *   density   .ds-density-*: 4px of the field row and of the palette rows
 *             per step; the chips 4px per step
 *   shape     .ds-shape-*: multiplies the shell's, the chips' and the
 *             palette's radius
 *   touch     .ds-touch: the field row and the palette rows at least
 *             --ds-touch-target high; the buttons follow their own rule
 * There is no tone: the composer means nothing by colour. Field text is
 * --ds-font-input (16px) on screens up to 600px, where iOS would zoom.
 *
 * Hooks: --ds-composer-radius (--ds-radius-2xl), --ds-composer-max-height
 * (220px), --ds-composer-bg (--ds-surface-high), --ds-composer-chip-max-width
 * (200px), --ds-composer-chip-height (40px), --ds-composer-palette-width (320px), --ds-composer-option-height
 * (40px), --ds-composer-palette-radius (--ds-radius-xs). Reads
 * --ds-input-height and --ds-input-focus-color of the field. The computed
 * values (--_box, --_row) are private: never set them.
 *
 * Motion: the ring follows the field model on the shell (at once while
 * focus is inside, fading back on blur). The palette fades in on
 * --ds-dur-fast and grows from --ds-scale-popup at the caret on the spring
 * (--ds-dur-medium); it leaves in --ds-dur-instant, fading only.
 * Transitions keyed on data-state (DS.overlay), so a palette closed
 * mid-way turns back from where it is. A chip that arrives or goes plays
 * DS.motion.enter / leave ('pop'). The send icon swaps to stop through
 * .ds-icon-swap.
 *
 * Forced colours: the shell and the chips keep a transparent border (their
 * edge there) and the shell shows a Highlight outline while focused; the
 * palette keeps a transparent outline as its edge; the active option is
 * SelectedItem / SelectedItemText; the drop state a dashed Highlight edge.
 *
 * Progressive:
 * - field-sizing (the textarea grows with its text): without it
 *   DS.dom.autosize() sets its height from the text.
 */

@layer ds.components.composer {
  .ds-composer {
    display: flex;
    flex-wrap: wrap;
    align-items: flex-end;
    gap: var(--ds-space-1);
    min-width: 0;
    padding: var(--ds-space-1);
    border: 1px solid transparent;
    border-radius: calc(var(--ds-composer-radius, var(--ds-radius-2xl)) * var(--ds-shape, 1));
    background: var(--ds-composer-bg, var(--ds-surface-high));
    color: var(--ds-text);
    transition:
      border-color var(--ds-dur-fast) var(--ds-ease-in-out),
      background-color var(--ds-dur-fast) var(--ds-ease-in-out),
      box-shadow var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  /* The ring of the field model, at once while focus is inside; a click on
     an attachment's remove button or the palette keeps it. */
  .ds-composer:focus-within {
    border-color: var(--ds-input-focus-color, var(--ds-primary));
    background: var(--ds-surface);
    box-shadow: inset 0 0 0 1px var(--ds-input-focus-color, var(--ds-primary));
    transition-duration: 0s;
  }

  .ds-composer > .ds-composer__input {
    --_box: max(var(--ds-target-min, 0px), calc(var(--ds-input-height, 40px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px));
    position: relative;
    flex: 1 1 0;
    min-width: 0;
    min-height: var(--_box);
    max-height: var(--ds-composer-max-height, 220px);
    margin: 0;
    padding-block: max(0px, calc((var(--_box) - 1lh) / 2));
    padding-inline: var(--ds-space-3) var(--ds-space-1);
    overflow-y: auto;
    border: 0;
    background: transparent;
    color: var(--ds-text);
    font: var(--ds-input-font, var(--ds-size-font, var(--ds-font-body)));
    font-weight: var(--ds-input-weight, var(--ds-weight-regular));
    resize: none;
  }

  @supports (field-sizing: content) {
    .ds-composer > .ds-composer__input {
      field-sizing: content;
    }
  }

  /* The shell draws the ring. */
  .ds-composer__input:focus {
    outline: none;
  }

  /* On the tonal fill text-3 falls short of 4.5:1; text-2 keeps it. */
  .ds-composer__input::placeholder {
    color: var(--ds-text-2);
    opacity: 1;
  }

  .ds-composer > .ds-btn {
    flex: none;
  }

  /* Blocked: the field and its actions take the disabled model. */
  .ds-composer:has(> .ds-composer__input:disabled) {
    background: var(--ds-disabled-fill, var(--ds-surface-high));
    color: var(--ds-disabled-ink, var(--ds-text));
  }

  .ds-composer > .ds-composer__input:disabled {
    color: var(--ds-disabled-ink, var(--ds-text));
    opacity: var(--ds-disabled-opacity, var(--ds-state-disabled));
    cursor: not-allowed;
  }

  /* Files over the composer: a dashed ring and the drop tint, at once. */
  .ds-composer[data-ds-dragover] {
    border-style: dashed;
    border-color: var(--ds-input-focus-color, var(--ds-primary));
    background: color-mix(in srgb, var(--ds-input-focus-color, var(--ds-primary)) calc(var(--ds-state-hover) * 100%), var(--ds-surface));
    transition-duration: 0s;
  }

  .ds-composer__picker {
    display: none;
  }

  /* ── Attachments ───────────────────────────────── */

  .ds-composer__attachments {
    display: flex;
    flex-wrap: wrap;
    flex-basis: 100%;
    order: -1;
    gap: var(--ds-space-2);
    min-width: 0;
    margin: 0;
    padding: var(--ds-space-2) var(--ds-space-2) var(--ds-space-1);
    list-style: none;
  }

  .ds-composer__attachments:empty {
    display: none;
  }

  .ds-composer__attachment {
    --_h: max(var(--ds-target-min, 0px), calc(var(--ds-composer-chip-height, 40px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px));
    display: inline-flex;
    align-items: center;
    gap: var(--ds-space-2);
    min-width: 0;
    max-width: 100%;
    min-height: var(--_h);
    padding-block: 0;
    padding-inline: var(--ds-space-3) var(--ds-space-1);
    border: 1px solid var(--ds-line-2);
    border-radius: calc(var(--ds-radius-chip) * var(--ds-shape, 1));
    background: var(--ds-surface);
    color: var(--ds-text);
    font: var(--ds-size-font, var(--ds-font-label));
  }

  .ds-composer__attachment > svg {
    flex: none;
    color: var(--ds-text-2);
  }

  .ds-composer__attachment-name {
    min-width: 0;
    max-width: var(--ds-composer-chip-max-width, 200px);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .ds-composer__attachment-size {
    flex: none;
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
    font-variant-numeric: tabular-nums;
  }

  .ds-composer__attachment > .ds-btn {
    flex: none;
  }

  /* ── The palette ───────────────────────────────── */

  /* Fixed, so no scrolling box cuts it off (in the top layer as a popover).
     inset, margin and border double as the reset of the UA box of a
     popover. Physical on purpose: --ds-composer-palette-x is a script
     coordinate from the left. */
  .ds-composer__palette {
    position: fixed;
    inset: var(--ds-composer-palette-y, 0px) auto auto var(--ds-composer-palette-x, 0px);
    z-index: var(--ds-z-popover);
    display: flex;
    flex-direction: column;
    box-sizing: border-box;
    width: min(var(--ds-composer-palette-width, 320px), calc(100vw - 2 * var(--ds-space-2)));
    max-height: min(320px, calc(100vh - 2 * var(--ds-space-2)));
    margin: 0;
    padding: calc(var(--ds-space-2) + var(--ds-density, 0) * 2px) 0;
    overflow-y: auto;
    border: 0;
    border-radius: calc(var(--ds-composer-palette-radius, var(--ds-radius-xs)) * var(--ds-shape, 1));
    background: var(--ds-surface-popover);
    color: var(--ds-text);
    box-shadow: var(--ds-elev-popover);
    /* Invisible; forced colors paint it, so the palette keeps an edge. */
    outline: 1px solid transparent;
    transform-origin: var(--ds-motion-origin, 0% 100%);
    /* At rest closed: the open state is DS.overlay's data-state="open".
       The exit only fades, in --ds-dur-instant; the scale goes back to its
       start once the palette is invisible. Closed, it takes no pointer. */
    opacity: 0;
    scale: var(--ds-motion-scale, var(--ds-scale-popup));
    pointer-events: none;
    transition:
      opacity var(--ds-dur-instant) var(--ds-ease-in-out),
      scale 0ms var(--ds-ease-in-out) var(--ds-dur-instant);
  }

  .ds-composer__palette[data-state="open"] {
    opacity: 1;
    scale: 1;
    pointer-events: auto;
    transition:
      opacity var(--ds-dur-fast) var(--ds-ease-in-out),
      scale var(--ds-dur-medium) var(--ds-ease-spatial);
  }

  .ds-composer__palette[hidden] {
    display: none;
  }

  .ds-composer__option {
    position: relative;
    display: flex;
    flex-shrink: 0;
    align-items: center;
    gap: var(--ds-space-3);
    min-height: max(var(--ds-target-min, 0px), calc(var(--ds-composer-option-height, 40px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px));
    padding: 0 var(--ds-space-3);
    color: var(--ds-text);
    font: var(--ds-size-font, var(--ds-font-body));
    cursor: pointer;
  }

  .ds-composer__option[hidden] {
    display: none;
  }

  .ds-composer__option > svg {
    flex: none;
    color: var(--ds-text-2);
  }

  .ds-composer__option-label {
    flex: none;
    white-space: nowrap;
  }

  .ds-composer__option-hint {
    flex: 1;
    min-width: 0;
    overflow: hidden;
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  /* The state layer in the content colour: hover, and the active option at
     the focus strength with a bar on its start edge (never colour alone). */
  .ds-composer__option::before {
    content: '';
    position: absolute;
    inset: 0;
    background: currentColor;
    opacity: 0;
    pointer-events: none;
    transition: opacity var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  @media (hover: hover) {
    .ds-composer__option:hover::before {
      opacity: var(--ds-state-hover);
    }
  }

  .ds-composer__option[aria-selected="true"]::before {
    opacity: var(--ds-state-focus);
    transition-duration: 0s;
  }

  .ds-composer__option::after {
    content: '';
    position: absolute;
    inset-block: var(--ds-space-1);
    inset-inline-start: 0;
    inline-size: var(--ds-focus-width);
    border-radius: var(--ds-focus-width);
    background: var(--ds-primary);
    opacity: 0;
    transition: opacity var(--ds-dur-instant) var(--ds-ease-in-out);
  }

  .ds-composer__option[aria-selected="true"]::after {
    opacity: 1;
    transition-duration: 0s;
  }

  .ds-composer__option:active::before {
    opacity: var(--ds-state-pressed);
    transition-duration: var(--ds-dur-micro);
  }

  .ds-composer__option[aria-disabled="true"] {
    color: var(--ds-disabled-ink, var(--ds-text));
    opacity: var(--ds-disabled-opacity, var(--ds-state-disabled));
    cursor: default;
  }

  .ds-composer__empty {
    padding: var(--ds-space-2) var(--ds-space-3);
    color: var(--ds-text-2);
    font: var(--ds-font-body);
  }

  .ds-composer__empty[hidden] {
    display: none;
  }

  @media (max-width: 600px) {
    /* 2px more than the box asks for, around the taller line: 44px at md. */
    .ds-composer > .ds-composer__input {
      padding-block: max(0px, calc((var(--_box) - 1lh) / 2 + 2px));
      font: var(--ds-input-font, var(--ds-font-input));
      font-weight: var(--ds-input-weight, var(--ds-weight-regular));
    }
  }

  @media (forced-colors: active) {
    .ds-composer:focus-within {
      outline: 2px solid Highlight;
      outline-offset: -2px;
    }

    .ds-composer[data-ds-dragover] {
      border-color: Highlight;
    }

    .ds-composer__attachment {
      border-color: CanvasText;
    }

    .ds-composer__option[aria-selected="true"] {
      forced-color-adjust: none;
      background: SelectedItem;
      color: SelectedItemText;
    }

    .ds-composer__option[aria-selected="true"] > svg,
    .ds-composer__option[aria-selected="true"] .ds-composer__option-hint {
      color: SelectedItemText;
    }

    .ds-composer__option[aria-disabled="true"] {
      color: GrayText;
    }
  }

  @media print {
    .ds-composer__palette {
      display: none;
    }
  }
}

/* ── components/message/message.css ── */
/*
 * Message: one turn of a conversation. Four roles: the user's own (a
 * bubble at the end side), the assistant's (full width, no bubble, an
 * avatar at the start), a system line (centred, quiet) and a tool result
 * (a framed block). A streaming reply shows a cursor at the end of its
 * text; a reply that stopped or failed says so in a note; the footer holds
 * its actions (copy, retry, edit, feedback).
 *
 *   <article class="ds-message ds-message--assistant" data-ds-message aria-labelledby="m1-author">
 *     <div class="ds-message__avatar" aria-hidden="true">(bot 20)</div>
 *     <div class="ds-message__main">
 *       <header class="ds-message__head">
 *         <span class="ds-message__author" id="m1-author">Assistant</span>
 *         <time class="ds-message__time" datetime="2026-11-04T09:41:00Z" data-ds-time>09:41</time>
 *       </header>
 *       <div class="ds-message__content ds-prose ds-prose--compact"><p>The battery of laptop 4 ...</p></div>
 *       <footer class="ds-message__footer" role="group" aria-label="Message actions">
 *         <button class="ds-btn ds-btn--quiet ds-btn--icon ds-sm" type="button" aria-label="Copy" data-tip="Copy"
 *           data-ds-message-action="copy">(icon swap: copy / check)</button>
 *         <button class="ds-btn ds-btn--quiet ds-btn--icon ds-sm" type="button" aria-label="Retry" data-tip="Retry"
 *           data-ds-message-action="retry">(refresh)</button>
 *       </footer>
 *     </div>
 *   </article>
 *
 * Roles (the variant):
 *   .ds-message--assistant   the default look: full width, no bubble
 *   .ds-message--user        the content in a bubble (--ds-message-user-bg)
 *                            at the end side, at most --ds-message-user-max
 *                            wide; an avatar goes to the end side
 *   .ds-message--system      a quiet centred line (meta type, text-2): a
 *                            join, a handover, a reset; no avatar, no footer
 *   .ds-message--tool        a tool's result: the content framed
 *                            (--ds-message-tool-bg, a line), code type
 *
 * Parts:
 *   .ds-message__avatar      a round slot (--ds-message-avatar-size, 32px)
 *                            for an icon, initials or an <img>
 *   .ds-message__main        the column: head, content, note, footer
 *   .ds-message__head        author, time and labels (an AI label), meta type
 *   .ds-message__author      the name, label weight
 *   .ds-message__time        the time, text-2
 *   .ds-message__content     the text; with .ds-prose .ds-prose--compact for
 *                            rendered markdown
 *   .ds-message__note        a line under the content with an icon and a
 *                            word: why a reply ended early (written by the
 *                            module for the partial and error states, or by
 *                            the page)
 *   .ds-message__footer      the actions, quiet icon buttons and a
 *                            .ds-feedback; at the end side for the user
 *
 * States, written by the module (DS.message) as data-state, with
 * aria-busy="true" while streaming:
 *   streaming   the cursor at the end of the text (the last paragraph or
 *               list item, or the empty content), the footer kept but
 *               invisible, so nothing moves when it comes
 *   partial     stopped before its end: the note says "Stopped"
 *   error       failed: the note says why (the error tone, an icon and a
 *               word, never the colour alone)
 *   (none)      complete
 *
 * Options (src/core/options.css, docs/options.md), on the message or any
 * ancestor; each is computed here, in the part's own rule:
 *   size      .ds-xs ... .ds-xl: the avatar 8px per step; the text keeps
 *             its role (a conversation reads at body size)
 *   density   .ds-density-*: 2px less per step between head, content and
 *             footer, and of the bubble's and the tool frame's padding
 *   shape     .ds-shape-*: multiplies the bubble's and the tool frame's
 *             radius; the avatar stays round
 *   touch     the footer's buttons follow their own rule
 * There is no tone: the role is the variant; the error state takes the
 * error ink with its icon and word.
 *
 * Hooks: --ds-message-avatar-size (32px), --ds-message-gap (8px),
 * --ds-message-user-bg (--ds-surface-high), --ds-message-user-color
 * (--ds-text), --ds-message-user-max (80%), --ds-message-radius
 * (--ds-radius-xl), --ds-message-tool-bg (--ds-surface-low). The computed
 * values (--_gap, --_pad, --_avatar) are private: never set them.
 *
 * Motion: none of its own. The cursor stands still (the text that streams
 * in is the motion); a footer that comes after a stream is already in
 * place. A copy swaps its icon to a check through .ds-icon-swap.
 *
 * Forced colours: the bubble and the tool frame keep a transparent border
 * (their edge there); the cursor is CanvasText; the error note keeps its
 * icon and word in the system colours.
 *
 * Print: the footer goes; the cursor too.
 */

@layer ds.components.message {
  .ds-message {
    --_gap: max(0px, calc(var(--ds-message-gap, var(--ds-space-2)) + var(--ds-density, 0) * 2px));
    display: flex;
    align-items: flex-start;
    gap: var(--ds-space-3);
    min-width: 0;
    color: var(--ds-text);
    font: var(--ds-font-body);
  }

  .ds-message__avatar {
    --_avatar: max(16px, calc(var(--ds-message-avatar-size, 32px) + var(--ds-size-step, 0) * 8px));
    position: relative;
    display: grid;
    flex: none;
    place-items: center;
    inline-size: var(--_avatar);
    block-size: var(--_avatar);
    overflow: hidden;
    border-radius: 50%;
    background: var(--ds-surface-high);
    color: var(--ds-text-2);
    font: var(--ds-font-caption);
    font-weight: var(--ds-weight-label);
  }

  .ds-message__avatar > img {
    inline-size: 100%;
    block-size: 100%;
    object-fit: cover;
  }

  .ds-message__main {
    display: flex;
    flex: 1 1 auto;
    flex-direction: column;
    align-items: flex-start;
    gap: var(--_gap);
    min-width: 0;
  }

  .ds-message__head {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--ds-space-1) var(--ds-space-2);
    min-width: 0;
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
  }

  .ds-message__author {
    color: var(--ds-text);
    font-weight: var(--ds-weight-label);
  }

  .ds-message__time {
    color: var(--ds-text-2);
    font-variant-numeric: tabular-nums;
  }

  .ds-message__content {
    align-self: stretch;
    min-width: 0;
    margin: 0;
    overflow-wrap: anywhere;
  }

  /* The default look, named: a message inside another role's region stays a reply. */
  .ds-message--assistant {
    flex-direction: row;
  }

  /* ── The user's bubble ─────────────────────────── */

  .ds-message--user {
    flex-direction: row-reverse;
  }

  .ds-message--user > .ds-message__main {
    align-items: flex-end;
  }

  .ds-message--user .ds-message__content {
    --_pad: max(var(--ds-space-1), calc(var(--ds-space-3) + var(--ds-density, 0) * 2px));
    align-self: flex-end;
    max-inline-size: var(--ds-message-user-max, 80%);
    padding: calc(var(--_pad) - 2px) calc(var(--_pad) + var(--ds-space-1));
    border: 1px solid transparent;
    border-radius: calc(var(--ds-message-radius, var(--ds-radius-xl)) * var(--ds-shape, 1));
    background: var(--ds-message-user-bg, var(--ds-surface-high));
    color: var(--ds-message-user-color, var(--ds-text));
    white-space: pre-wrap;
  }

  /* ── System line ───────────────────────────────── */

  .ds-message--system {
    justify-content: center;
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
    text-align: center;
  }

  .ds-message--system > .ds-message__main {
    flex: 0 1 auto;
    align-items: center;
  }

  .ds-message--system .ds-message__content {
    display: inline-flex;
    align-items: center;
    gap: var(--ds-space-2);
  }

  .ds-message--system .ds-message__content > svg {
    flex: none;
  }

  /* ── Tool result ───────────────────────────────── */

  .ds-message--tool .ds-message__content {
    --_pad: max(var(--ds-space-1), calc(var(--ds-space-3) + var(--ds-density, 0) * 2px));
    position: relative;
    padding: var(--_pad);
    overflow-x: auto;
    border: 1px solid var(--ds-line);
    border-radius: calc(var(--ds-message-radius, var(--ds-radius-xl)) / 2 * var(--ds-shape, 1));
    background: var(--ds-message-tool-bg, var(--ds-surface-low));
    font: var(--ds-font-code);
    white-space: pre-wrap;
  }

  /* ── States ────────────────────────────────────── */

  /* The cursor: a block at the end of the text, in the text's colour. It
     follows the last paragraph, heading or list item, or stands alone in an
     empty content before the first words. */
  .ds-message[data-state="streaming"] .ds-message__content:not(:has(> *))::after,
  .ds-message[data-state="streaming"] .ds-message__content > :is(p, h1, h2, h3, h4, h5, h6, blockquote):last-child::after,
  .ds-message[data-state="streaming"] .ds-message__content > :is(ul, ol):last-child > li:last-child::after {
    content: '';
    display: inline-block;
    inline-size: .5em;
    block-size: 1em;
    margin-inline-start: 2px;
    border-radius: calc(var(--ds-radius-xs) / 2);
    background: currentColor;
    vertical-align: text-bottom;
  }

  /* Kept in the layout, so the reply does not move when the footer comes. */
  .ds-message[data-state="streaming"] .ds-message__footer {
    visibility: hidden;
  }

  .ds-message__note {
    display: inline-flex;
    margin: 0;
    align-items: center;
    gap: var(--ds-space-2);
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
  }

  .ds-message__note > svg {
    flex: none;
  }

  .ds-message[data-state="error"] .ds-message__note {
    color: var(--ds-on-error-container);
  }

  .ds-message[data-state="error"] .ds-message__note > svg {
    color: var(--ds-error);
  }

  .ds-message__note[hidden] {
    display: none;
  }

  /* ── Footer ────────────────────────────────────── */

  /* Quiet icon buttons: their glyph lines up with the text above (the
     button's own padding hangs into the gutter). */
  .ds-message__footer {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 2px;
    margin-inline-start: calc(-1 * var(--ds-space-2));
  }

  .ds-message--user .ds-message__footer {
    margin-inline: 0 calc(-1 * var(--ds-space-2));
  }

  @media (forced-colors: active) {
    .ds-message--user .ds-message__content,
    .ds-message--tool .ds-message__content {
      border-color: CanvasText;
    }

    .ds-message[data-state="streaming"] .ds-message__content:not(:has(> *))::after,
    .ds-message[data-state="streaming"] .ds-message__content > :is(p, h1, h2, h3, h4, h5, h6, blockquote):last-child::after,
    .ds-message[data-state="streaming"] .ds-message__content > :is(ul, ol):last-child > li:last-child::after {
      background: CanvasText;
    }

    .ds-message[data-state="error"] .ds-message__note,
    .ds-message[data-state="error"] .ds-message__note > svg {
      color: CanvasText;
    }
  }

  @media print {
    .ds-message__footer {
      display: none;
    }

    .ds-message[data-state="streaming"] .ds-message__content:not(:has(> *))::after,
    .ds-message[data-state="streaming"] .ds-message__content > :is(p, h1, h2, h3, h4, h5, h6, blockquote):last-child::after,
    .ds-message[data-state="streaming"] .ds-message__content > :is(ul, ol):last-child > li:last-child::after {
      content: none;
    }
  }
}

/* ── components/transcript/transcript.css ── */
/*
 * Transcript: the scrolling log of a conversation. It sticks to its end
 * while the reader is there, shows a "Latest" pill with the count of new
 * messages once they scrolled up, loads earlier messages at the top
 * without moving what is on screen, and separates the days.
 *
 *   <div class="ds-transcript" data-ds-transcript role="region" aria-label="Conversation" tabindex="0">
 *     <div class="ds-transcript__earlier">
 *       <button class="ds-btn ds-btn--text" type="button" data-ds-transcript-earlier>Load earlier messages</button></div>
 *     <div class="ds-transcript__list" role="log" aria-label="Messages">
 *       <h3 class="ds-transcript__day">Yesterday</h3>
 *       <article class="ds-message ...">...</article>
 *     </div>
 *     <div class="ds-jump"><div class="ds-presence" hidden>
 *       <button class="ds-btn ds-btn--tonal ds-transcript__latest" type="button">(arrowDown 20)
 *         <span>Latest</span> <span class="ds-transcript__unread"></span></button></div></div>
 *   </div>
 *
 * The page gives it a block size (a flex child of a column that holds the
 * composer, or a height); it scrolls on the block axis. The jump (.ds-jump,
 * scroller.css) is written by the module when the markup has none.
 *
 * Parts:
 *   .ds-transcript__list     the messages and days, in a column at most
 *                            --ds-transcript-max-width wide, centred; a
 *                            short conversation rests at the bottom, next
 *                            to the composer
 *   .ds-transcript__day      a day separator: its text centred between two
 *                            lines (a heading, so a reader can jump by day)
 *   .ds-transcript__earlier  the row of the "load earlier" button at the top
 *   .ds-transcript__latest   the pill's button: a raised tonal pill
 *   .ds-transcript__unread   the count of new messages in it ("3 new"),
 *                            empty and gone while there is none
 *
 * Options (src/core/options.css, docs/options.md), on the transcript or
 * any ancestor; each is computed here, in the part's own rule:
 *   density   .ds-density-*: 4px less between messages per step
 *             (--ds-transcript-gap), 2px less of the list's padding
 *   size, shape, touch: reach the messages and buttons inside; the log
 *             itself has no height, radius or target of its own
 * There is no tone.
 *
 * Hooks: --ds-transcript-max-width (768px), --ds-transcript-gap (24px),
 * --ds-transcript-pad (--ds-space-4). The computed values are private.
 *
 * Motion: the pill comes and goes as a .ds-presence (motion.css); "Latest"
 * scrolls smoothly within one screen, else at once (DS.dom.followEnd()).
 * Loading earlier messages keeps the message on screen in place.
 *
 * Forced colours: the focused log shows the system ring; the day lines are
 * CanvasText; the unread count keeps an edge.
 *
 * Print: the log shows all of its content; the pill and the load row go.
 */

@layer ds.components.transcript {
  /* overflow-anchor: none, since the module keeps the message on screen in
     place itself (the engines' own anchoring stops at the top, where
     earlier messages come in). */
  .ds-transcript {
    position: relative;
    display: flex;
    flex-direction: column;
    min-height: 0;
    overflow-x: hidden;
    overflow-y: auto;
    overflow-anchor: none;
    overscroll-behavior: contain;
  }

  /* The tab stop that scrolls: an inset ring, solid from the first frame,
     that snaps from the edge inward. */
  .ds-transcript[tabindex] {
    outline-offset: 0;
    transition: outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-transcript[tabindex]:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: calc(-1 * var(--ds-focus-width));
  }

  .ds-transcript__list {
    --_pad: max(0px, calc(var(--ds-transcript-pad, var(--ds-space-4)) + var(--ds-density, 0) * 2px));
    display: flex;
    flex-direction: column;
    gap: max(var(--ds-space-2), calc(var(--ds-transcript-gap, 24px) + var(--ds-density, 0) * 4px));
    box-sizing: border-box;
    inline-size: 100%;
    max-inline-size: var(--ds-transcript-max-width, 768px);
    margin-block-start: auto;
    margin-inline: auto;
    padding: var(--_pad);
  }

  .ds-transcript__day {
    display: flex;
    align-items: center;
    gap: var(--ds-space-3);
    margin: 0;
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
    font-weight: var(--ds-weight-label);
    text-align: center;
  }

  .ds-transcript__day::before,
  .ds-transcript__day::after {
    content: '';
    flex: 1 1 0;
    border-block-start: 1px solid var(--ds-line);
  }

  .ds-transcript__earlier {
    display: flex;
    justify-content: center;
    padding-block: var(--ds-space-2) 0;
  }

  .ds-transcript__earlier[hidden] {
    display: none;
  }

  .ds-transcript__latest {
    box-shadow: var(--ds-elev-2);
  }

  .ds-transcript__unread {
    display: inline-flex;
    align-items: center;
    min-block-size: 20px;
    padding-inline: var(--ds-space-2);
    border: 1px solid transparent;
    border-radius: calc(var(--ds-radius-action) * var(--ds-shape, 1));
    background: var(--ds-primary);
    color: var(--ds-on-primary);
    font: var(--ds-font-caption);
    font-weight: var(--ds-weight-label);
    font-variant-numeric: tabular-nums;
  }

  .ds-transcript__unread:empty {
    display: none;
  }

  @media (forced-colors: active) {
    .ds-transcript__day::before,
    .ds-transcript__day::after {
      border-color: CanvasText;
    }

    .ds-transcript__unread {
      border-color: CanvasText;
    }
  }

  @media print {
    .ds-transcript {
      overflow: visible;
    }

    .ds-transcript__earlier {
      display: none;
    }
  }
}

/* ── components/suggestions/suggestions.css ── */
/*
 * Suggestions: follow-up prompts as a row of action chips under a reply or
 * over the composer. The row scrolls sideways (with the fades of
 * .ds-scroll-x) and a mouse can drag it; or it wraps.
 *
 *   <div class="ds-suggestions ds-scroll-x" role="group" aria-label="Suggested questions"
 *     data-ds-suggestions data-ds-suggestions-for="composer-1">
 *     <button class="ds-chip" type="button" data-value="Show the battery report">
 *       <span class="ds-chip__body">(sparkles 18 .ds-chip__icon)<span class="ds-chip__label">Show the battery report</span></span></button>
 *     <button class="ds-chip" type="button"><span class="ds-chip__body"><span class="ds-chip__label">Open a ticket</span></span></button>
 *   </div>
 *
 * Variants:
 *   (default)              one row that scrolls sideways; add .ds-scroll-x
 *                          (scroller.css) for its thin scrollbar and the
 *                          fades at the ends that have more
 *   .ds-suggestions--wrap  the chips wrap onto more lines (no scrolling,
 *                          no .ds-scroll-x)
 *
 * States, written by the module (DS.suggestions):
 *   data-ds-overflow-start, data-ds-overflow-end  (DS.dom.scrollEdges())
 *                          more to scroll: the row takes the grab cursor
 *                          where the pointer is fine
 *   data-state="dragging"  a mouse drags the row: the grabbing cursor, no
 *                          text selection, no press layer on the chips
 *
 * Options (src/core/options.css, docs/options.md): size, density, shape,
 * touch and tone reach the chips (chip.css); the row adds 2px less of gap
 * per density step.
 *
 * Hooks: --ds-suggestions-gap (--ds-space-2). The computed values are
 * private.
 *
 * Motion: none of its own; a drag follows the pointer 1:1 and a chip
 * scrolled to by keyboard comes into view clear of the fades.
 *
 * Forced colours: the chips keep their edges (chip.css).
 */

@layer ds.components.suggestions {
  .ds-suggestions {
    position: relative;
    display: flex;
    align-items: center;
    gap: max(var(--ds-space-1), calc(var(--ds-suggestions-gap, var(--ds-space-2)) + var(--ds-density, 0) * 2px));
    min-width: 0;
    margin: 0;
    padding: var(--ds-space-1) 0;
    overflow-x: auto;
    overflow-y: hidden;
    overscroll-behavior-x: contain;
    list-style: none;
  }

  .ds-suggestions > * {
    flex: none;
  }

  .ds-suggestions--wrap {
    flex-wrap: wrap;
    overflow: visible;
  }

  @media (pointer: fine) {
    .ds-suggestions:is([data-ds-overflow-start], [data-ds-overflow-end]):not(.ds-suggestions--wrap) {
      cursor: grab;
    }
  }

  .ds-suggestions[data-state="dragging"] {
    cursor: grabbing;
    user-select: none;
  }

  /* A drag is no press: the chips under the pointer show no layer. */
  .ds-suggestions[data-state="dragging"] > * {
    pointer-events: none;
  }
}

/* ── components/feedback/feedback.css ── */
/*
 * Feedback: thumbs up and down on a reply, optionally with a dialog that
 * asks why. Two quiet icon toggle buttons (aria-pressed) whose thumb fills
 * while pressed, an optional question before them and a status after.
 *
 *   <div class="ds-feedback" role="group" aria-label="Rate this answer" data-ds-feedback
 *     data-ds-feedback-reason="reason-dialog">
 *     <span class="ds-feedback__label" aria-hidden="true">Helpful?</span>
 *     <button class="ds-btn ds-btn--quiet ds-btn--icon ds-sm" type="button" aria-pressed="false" aria-label="Helpful"
 *       data-tip="Helpful" data-ds-feedback-value="up">(thumbUp 18 .ds-icon--fillable)</button>
 *     <button class="ds-btn ds-btn--quiet ds-btn--icon ds-sm" type="button" aria-pressed="false" aria-label="Not helpful"
 *       data-tip="Not helpful" data-ds-feedback-value="down">(thumbDown 18 .ds-icon--fillable)</button>
 *     <span class="ds-feedback__status"></span>
 *   </div>
 *
 * Parts:
 *   .ds-feedback__label    the question, meta type in text-2 (the group's
 *                          name says it to a screen reader)
 *   .ds-feedback__status   the thanks the module writes once feedback is
 *                          given (empty: no room)
 *
 * States: aria-pressed on the chosen button (the button's on look and the
 * filled thumb, .ds-icon--fillable: never the colour alone); with
 * data-ds-feedback-lock the module makes both buttons aria-disabled once
 * feedback is given (the chosen one keeps its on look).
 *
 * Options (src/core/options.css, docs/options.md): size, shape and touch
 * reach the buttons (button.css); density takes 1px of the gap per step.
 * There is no tone.
 *
 * Hooks: none of its own; the buttons read the button's.
 *
 * Motion: the thumb fills on --ds-dur-fast (utilities.css); the reason
 * dialog opens and closes through DS.overlay.
 *
 * Forced colours: the pressed button is Highlight / HighlightText
 * (button.css); the status is text.
 */

@layer ds.components.feedback {
  .ds-feedback {
    display: inline-flex;
    flex-wrap: wrap;
    align-items: center;
    gap: max(0px, calc(2px + var(--ds-density, 0) * 1px));
    min-width: 0;
  }

  .ds-feedback__label,
  .ds-feedback__status {
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
  }

  .ds-feedback__label {
    margin-inline-end: var(--ds-space-1);
  }

  .ds-feedback__status {
    margin-inline-start: var(--ds-space-2);
  }

  .ds-feedback__status:empty {
    display: none;
  }
}

/* ── components/ailabel/ailabel.css ── */
/*
 * AI label: marks content a model generated, with an icon and a word, and
 * optionally a toggletip that explains it. A small pill in a message head,
 * next to a summary or a field a model filled.
 *
 *   <span class="ds-ailabel">(sparkles 16)<span>AI generated</span></span>
 *
 *   <button class="ds-ailabel" type="button" aria-expanded="false" aria-controls="ai-tip-1" data-ds-ailabel>
 *     (sparkles 16)<span>AI</span><span class="ds-sr">: about this content</span></button>
 *   <div class="ds-ailabel__tip" id="ai-tip-1" role="dialog" aria-labelledby="ai-tip-1-title" popover="manual" hidden>
 *     <p class="ds-ailabel__title" id="ai-tip-1-title">Generated by AI</p>
 *     <p>A language model wrote this answer from the device data. Check what matters.</p>
 *     <a href="/help/ai">How the assistant works</a>
 *   </div>
 *
 * Variants:
 *   (default)            the tonal pill (--ds-ailabel-bg, -color: the
 *                        primary container pair)
 *   .ds-ailabel--outlined  a line, no fill
 *   .ds-ailabel--plain   no box: the icon and the word in text-2
 *   .ds-ailabel--icon    the icon alone, round; the word goes into the
 *                        name (aria-label or a .ds-sr span), never lost
 *
 * Parts:
 *   .ds-ailabel__tip     the explainer: a non-modal popover the module
 *                        opens through DS.overlay, placed under the label
 *                        (above without room) by the script
 *                        (--ds-ailabel-x, --ds-ailabel-y in the
 *                        viewport's terms)
 *   .ds-ailabel__title   its first line, label weight
 *
 * As a button (the toggletip): the state layer of the content colour
 * (hover, focus, press in --ds-dur-micro), the focus ring that snaps in,
 * aria-expanded while the tip is open (the pressed layer stays). Its
 * target reaches --ds-target-min through an invisible margin (::after), so
 * the pill stays small under .ds-touch. Like an inline link, it has no
 * ripple and no press morph.
 *
 * Options (src/core/options.css, docs/options.md), on the label or any
 * ancestor; each is computed here, in the label's own rule:
 *   size      .ds-xs ... .ds-xl: 4px of height per step (16 to 32px; 24px
 *             at md), the icon 2px per step; caption type
 *   density   .ds-density-*: 2px less height per step (never below 16px)
 *   shape     .ds-shape-*: multiplies the radius, at most half the height;
 *             the tip's radius too
 *   touch     .ds-touch: the button's target at least --ds-touch-target
 * There is no tone: the label means "generated", in its icon and word.
 *
 * Hooks: --ds-ailabel-height (24px), --ds-ailabel-bg
 * (--ds-primary-container), --ds-ailabel-color
 * (--ds-on-primary-container), --ds-ailabel-tip-width (320px). The
 * computed values (--_h, --_radius, --_icon) are private.
 *
 * Motion: the tip fades in on --ds-dur-fast and grows from
 * --ds-scale-popup at the label on the spring (--ds-dur-medium); it leaves
 * in --ds-dur-instant, fading only. Keyed on data-state (DS.overlay), so a
 * tip closed mid-way turns back from where it is.
 *
 * Forced colours: the pill keeps its edge (a transparent border), the
 * button its ring, the open button Highlight / HighlightText; the tip a
 * transparent outline as its edge.
 *
 * Print: the tip goes; the label stays.
 */

@layer ds.components.ailabel {
  .ds-ailabel {
    --_h: max(16px, calc(var(--ds-ailabel-height, 24px) + var(--ds-size-step, 0) * 4px + var(--ds-density, 0) * 2px));
    --_radius: min(calc(var(--ds-radius-action) * var(--ds-shape, 1)), calc(var(--_h) / 2));
    --_icon: calc(16px + var(--ds-size-step, 0) * 2px);
    position: relative;
    isolation: isolate;
    display: inline-flex;
    flex: none;
    align-items: center;
    gap: var(--ds-space-1);
    box-sizing: border-box;
    block-size: var(--_h);
    margin: 0;
    padding-block: 0;
    padding-inline: calc(var(--ds-space-2) - 1px) var(--ds-space-2);
    border: 1px solid transparent;
    border-radius: var(--_radius);
    background: var(--ds-ailabel-bg, var(--ds-primary-container));
    color: var(--ds-ailabel-color, var(--ds-on-primary-container));
    font: var(--ds-font-caption);
    font-weight: var(--ds-weight-label);
    line-height: 1;
    white-space: nowrap;
    vertical-align: middle;
  }

  .ds-ailabel > svg {
    flex: none;
    inline-size: var(--_icon);
    block-size: var(--_icon);
  }

  .ds-ailabel--outlined {
    border-color: var(--ds-line-2);
    background: transparent;
    color: var(--ds-text-2);
  }

  .ds-ailabel--plain {
    padding-inline: 0;
    background: transparent;
    color: var(--ds-text-2);
  }

  .ds-ailabel--icon {
    justify-content: center;
    inline-size: var(--_h);
    padding: 0;
  }

  /* ── As the toggletip's button ─────────────────── */

  button.ds-ailabel {
    cursor: pointer;
    -webkit-tap-highlight-color: transparent;
    outline-offset: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    transition: outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  /* The state layer, in the content colour. */
  button.ds-ailabel::before {
    content: '';
    position: absolute;
    inset: -1px;
    z-index: -1;
    border-radius: inherit;
    background: currentColor;
    opacity: 0;
    pointer-events: none;
    transition: opacity var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  /* The target reaches --ds-target-min, centred on the pill. */
  button.ds-ailabel::after {
    content: '';
    position: absolute;
    inset: min(0px, calc((100% - var(--ds-target-min, 0px)) / 2));
  }

  @media (hover: hover) {
    button.ds-ailabel:hover::before {
      opacity: var(--ds-state-hover);
    }
  }

  button.ds-ailabel:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: var(--ds-focus-offset);
  }

  button.ds-ailabel:focus-visible::before {
    opacity: var(--ds-state-focus);
    transition-duration: 0s;
  }

  button.ds-ailabel:active::before,
  button.ds-ailabel[aria-expanded="true"]::before {
    opacity: var(--ds-state-pressed);
    transition-duration: var(--ds-dur-micro);
  }

  /* ── The explainer ─────────────────────────────── */

  /* Fixed, so no scrolling box cuts it off (in the top layer as a popover).
     inset, margin and border double as the reset of the UA box of a
     popover. Physical on purpose: --ds-ailabel-x is a script coordinate
     from the left. */
  .ds-ailabel__tip {
    position: fixed;
    inset: var(--ds-ailabel-y, 0px) auto auto var(--ds-ailabel-x, 0px);
    z-index: var(--ds-z-popover);
    box-sizing: border-box;
    inline-size: max-content;
    max-inline-size: min(var(--ds-ailabel-tip-width, 320px), calc(100vw - 2 * var(--ds-space-2)));
    margin: 0;
    padding: var(--ds-space-3) var(--ds-space-4);
    overflow: auto;
    border: 0;
    border-radius: calc(var(--ds-radius-md) * var(--ds-shape, 1));
    background: var(--ds-surface-popover);
    color: var(--ds-text);
    box-shadow: var(--ds-elev-popover);
    font: var(--ds-font-dense);
    white-space: normal;
    /* Invisible; forced colors paint it, so the tip keeps an edge. */
    outline: 1px solid transparent;
    transform-origin: var(--ds-motion-origin, 0% 0%);
    opacity: 0;
    scale: var(--ds-motion-scale, var(--ds-scale-popup));
    pointer-events: none;
    transition:
      opacity var(--ds-dur-instant) var(--ds-ease-in-out),
      scale 0ms var(--ds-ease-in-out) var(--ds-dur-instant);
  }

  .ds-ailabel__tip[data-state="open"] {
    opacity: 1;
    scale: 1;
    pointer-events: auto;
    transition:
      opacity var(--ds-dur-fast) var(--ds-ease-in-out),
      scale var(--ds-dur-medium) var(--ds-ease-spatial);
  }

  .ds-ailabel__tip[hidden] {
    display: none;
  }

  .ds-ailabel__tip > * {
    margin: 0;
  }

  .ds-ailabel__tip > * + * {
    margin-block-start: var(--ds-space-2);
  }

  .ds-ailabel__title {
    display: flex;
    align-items: center;
    gap: var(--ds-space-2);
    font-weight: var(--ds-weight-label);
  }

  @media (forced-colors: active) {
    .ds-ailabel {
      border-color: CanvasText;
    }

    button.ds-ailabel[aria-expanded="true"] {
      forced-color-adjust: none;
      background: Highlight;
      color: HighlightText;
    }
  }

  @media print {
    .ds-ailabel__tip {
      display: none;
    }
  }
}

/* ── components/tearsheet/tearsheet.css ── */
/*
 * Tearsheet: a tall create or edit flow over the page (a new device with
 * its network and owner, a bulk edit), taller than a dialog and with its
 * own head, steps and foot. It is a modal dialog of the dialog component
 * (DS.overlay opens and closes it; the box is .ds-dialog__box), anchored
 * to the bottom of the window with a gap above, rising from the bottom
 * edge. Its backdrop does not close it: a stray click never loses a
 * half-filled form.
 *
 *   <dialog class="ds-dialog ds-tearsheet" aria-labelledby="t-title" data-ds-tearsheet>
 *     <div class="ds-dialog__backdrop"></div>
 *     <form class="ds-dialog__box ds-tearsheet__box" novalidate>       (or a div)
 *       <div class="ds-tearsheet__head">
 *         <div class="ds-tearsheet__heading">
 *           <p class="ds-tearsheet__label">Devices</p>                 (optional)
 *           <h2 class="ds-dialog__title" id="t-title">Add a device</h2>
 *           <p class="ds-tearsheet__description">Register it ...</p>   (optional)
 *           <p class="ds-tearsheet__progress"></p>        (DS.tearsheet writes it)
 *         </div>
 *         <button class="ds-btn ds-btn--quiet ds-btn--icon" type="button" aria-label="Close" data-ds-close>(close)</button>
 *       </div>
 *       <div class="ds-tearsheet__main">
 *         <nav class="ds-tearsheet__steps" aria-label="Steps">          (optional)
 *           <ol class="ds-steps ds-steps--vertical"> ... </ol>
 *         </nav>
 *         <div class="ds-tearsheet__body">
 *           <section class="ds-tearsheet__step" aria-labelledby="s1"> <h3 id="s1" tabindex="-1">Device</h3> ... </section>
 *           <section class="ds-tearsheet__step" aria-labelledby="s2" hidden> ... </section>
 *         </div>
 *       </div>
 *       <div class="ds-tearsheet__foot">
 *         <button class="ds-btn ds-btn--text" type="button" data-ds-close>Cancel</button>
 *         <button class="ds-btn ds-btn--outlined" type="button" data-ds-tearsheet-back>Back</button>
 *         <button class="ds-btn ds-btn--filled" type="button" data-ds-tearsheet-next>Next</button>
 *         <button class="ds-btn ds-btn--filled" type="submit" data-ds-tearsheet-submit>Add device</button>
 *       </div>
 *
 * Variants:
 *   (default)           as wide as --ds-tearsheet-width (1200px), never wider
 *                       than the window less --ds-space-8 on each side
 *   .ds-tearsheet--narrow  --ds-tearsheet-width-narrow (640px): a short form,
 *                       usually without the step rail
 *   stacked             a tearsheet opened over another (DS.tearsheet sets
 *                       data-stacked on the one below): the lower box recedes
 *                       (scale --ds-scale-enter, up by --ds-distance-lg) and
 *                       the upper one sits --ds-space-4 lower, so the edge of
 *                       the one below shows above it
 *
 * Parts: the head (a label, the title, a description, the close button;
 * a hairline under it), the main area (the step rail at the start, on
 * --ds-surface-low, and the body, the one part that scrolls, with a thin
 * scrollbar), the foot (the actions at the end; the first of several,
 * Cancel or a .ds-meta line, takes the start; a hairline above it). Only the
 * current .ds-tearsheet__step shows; DS.tearsheet writes `hidden` on the
 * others, and on the Back, Next and submit buttons that do not apply.
 *
 * Options: density changes the padding of head, body, rail and foot (2px
 * per step); shape multiplies the box's top radius; a size class reaches
 * the controls inside only. There is no tone.
 *
 * Phones (600px and below): the box fills the window (no gap, no radius,
 * safe areas on head and foot) and the rail gives way to the progress
 * line (.ds-tearsheet__progress, "Step 2 of 4: Network") in the head,
 * which also shows in a tearsheet without a rail.
 *
 * Motion: state-driven on data-state like every dialog. The box rises its
 * full height from the bottom edge over --ds-dur-long on --ds-ease-out (a
 * box as tall as the window would show the page under it if it sprang
 * past its rest) while it fades in over --ds-dur-fast; it drops back in
 * --ds-dur-base, accelerating. Stacking moves the lower box on the spring
 * over --ds-dur-slow, and back. By hand (no data-state) the keyframes
 * ds-lift-in and ds-drop-out with the fades.
 *
 * Forced colours: the box keeps the dialog's transparent border as its
 * edge; the hairlines of head, rail and foot are borders, so they stay.
 *
 * Hooks: --ds-tearsheet-width (1200px), --ds-tearsheet-width-narrow
 * (640px), --ds-tearsheet-gap (--ds-space-12: the room above the box),
 * --ds-tearsheet-padding (--ds-space-6), --ds-tearsheet-rail-width
 * (256px), --ds-tearsheet-radius (--ds-radius-dialog).
 *
 * Print: an open tearsheet is not printed (the dialog's rule).
 *
 * Progressive:
 * - scrollbar-color and scrollbar-width (a thin, quiet scrollbar on the
 *   body): without them the platform scrollbar shows.
 */

@layer ds.components.tearsheet {
  /* The frame: the box at the bottom, the gap above it. */
  .ds-tearsheet {
    --_gap: var(--ds-tearsheet-gap, var(--ds-space-12));
    place-items: end center;
    padding: var(--_gap) var(--ds-space-8) 0;
  }

  .ds-tearsheet.ds-dialog--nested {
    padding-top: calc(var(--_gap) + var(--ds-space-4));
  }

  .ds-tearsheet .ds-dialog__box {
    --_pad: calc(var(--ds-tearsheet-padding, var(--ds-space-6)) + var(--ds-density, 0) * 2px);
    --_radius: calc(var(--ds-tearsheet-radius, var(--ds-radius-dialog)) * var(--ds-shape, 1));
    display: grid;
    grid-template-rows: auto minmax(0, 1fr) auto;
    gap: 0;
    width: min(var(--ds-tearsheet-width, 1200px), 100%);
    height: 100%;
    max-height: none;
    padding: 0;
    overflow: hidden;
    border-radius: var(--_radius) var(--_radius) 0 0;
  }

  .ds-tearsheet--narrow .ds-dialog__box {
    width: min(var(--ds-tearsheet-width-narrow, 640px), 100%);
  }

  /* Head: label, title and description; the close button at the end. */
  .ds-tearsheet__head {
    display: flex;
    align-items: flex-start;
    gap: var(--ds-space-3);
    padding-block: var(--_pad);
    padding-inline: var(--_pad) calc(var(--_pad) - var(--ds-space-2));
    border-bottom: 1px solid var(--ds-line);
  }

  .ds-tearsheet__heading {
    display: grid;
    gap: var(--ds-space-1);
    flex: 1;
    min-width: 0;
  }

  .ds-tearsheet__head > .ds-btn {
    flex-shrink: 0;
    margin-top: calc(-1 * var(--ds-space-2));
  }

  .ds-tearsheet__label {
    margin: 0;
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
  }

  .ds-tearsheet__description {
    margin: 0;
    max-width: 72ch;
    color: var(--ds-text-2);
    font: var(--ds-font-body);
  }

  .ds-tearsheet__label:empty,
  .ds-tearsheet__description:empty {
    display: none;
  }

  /* "Step 2 of 4: Network", written by DS.tearsheet: shown where no rail
     says it (a tearsheet without one, and phones). */
  .ds-tearsheet__progress {
    margin: 0;
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
    font-variant-numeric: tabular-nums;
  }

  .ds-tearsheet__progress:empty,
  .ds-tearsheet__box:has(> .ds-tearsheet__main > .ds-tearsheet__steps) .ds-tearsheet__progress {
    display: none;
  }

  /* Main: the rail and the body side by side; only the body scrolls. */
  .ds-tearsheet__main {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    min-height: 0;
  }

  .ds-tearsheet__main:has(> .ds-tearsheet__steps) {
    grid-template-columns: var(--ds-tearsheet-rail-width, 256px) minmax(0, 1fr);
  }

  .ds-tearsheet__steps {
    position: relative;
    min-height: 0;
    overflow-y: auto;
    padding: var(--_pad);
    border-inline-end: 1px solid var(--ds-line);
    background: var(--ds-surface-low);
  }

  .ds-tearsheet__body {
    position: relative;
    min-height: 0;
    overflow-y: auto;
    overscroll-behavior: contain;
    scrollbar-width: thin;
    scrollbar-color: var(--ds-line-2) transparent;
    padding: var(--_pad);
    outline-offset: 0;
    transition: outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-tearsheet__body:focus {
    outline: none;
  }

  .ds-tearsheet__body:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: calc(-1 * var(--ds-focus-width));
  }

  /* A step: a column of the page's fields, at a readable width. */
  .ds-tearsheet__step {
    display: grid;
    align-content: start;
    gap: calc(var(--ds-space-4) + var(--ds-density, 0) * 2px);
    max-width: 720px;
  }

  .ds-tearsheet__step[hidden] {
    display: none;
  }

  /* The step's heading: the subtitle role, no margins of its own. */
  .ds-tearsheet__step > :is(h2, h3, h4):first-child {
    margin: 0;
    color: var(--ds-text);
    font: var(--ds-font-subtitle);
  }

  /* The heading focus lands on when the step changes: no ring of its own
     (it is no control), the step's content follows. */
  .ds-tearsheet__step [tabindex="-1"]:focus {
    outline: none;
  }

  /* Foot: the actions at the end; Cancel or a meta line takes the start. */
  .ds-tearsheet__foot {
    display: flex;
    flex-wrap: wrap;
    justify-content: flex-end;
    align-items: center;
    gap: var(--ds-space-2);
    padding: calc(var(--ds-space-4) + var(--ds-density, 0) * 2px) var(--_pad);
    border-top: 1px solid var(--ds-line);
  }

  /* The first of several (Cancel, or a line of meta) takes the start. */
  .ds-tearsheet__foot > :first-child:not(:last-child) {
    margin-inline-end: auto;
  }

  .ds-tearsheet__foot > [hidden] {
    display: none;
  }

  /* Motion, state-driven: the box rises its full height and fades in,
     drops back accelerating. A transition takes the timing of the state it
     moves to. */
  .ds-tearsheet[data-state] .ds-dialog__box {
    transition:
      opacity var(--ds-dur-fast) var(--ds-ease-in-out),
      scale var(--ds-dur-slow) var(--ds-ease-spatial),
      translate var(--ds-dur-long) var(--ds-ease-out);
  }

  .ds-tearsheet[data-state="closed"] .ds-dialog__box {
    scale: none;
    translate: 0 var(--ds-distance-sheet);
    transition:
      opacity var(--ds-dur-base) var(--ds-ease-in-out),
      translate var(--ds-dur-base) var(--ds-ease-exit);
  }

  /* Stacked: the tearsheet under another one recedes on the spring, and
     comes back when the upper one closes. */
  .ds-tearsheet[data-stacked][data-state="open"] .ds-dialog__box {
    scale: var(--ds-scale-enter);
    translate: 0 calc(-1 * var(--ds-distance-lg));
    transition:
      opacity var(--ds-dur-fast) var(--ds-ease-in-out),
      scale var(--ds-dur-slow) var(--ds-ease-spatial),
      translate var(--ds-dur-slow) var(--ds-ease-spatial);
  }

  .ds-tearsheet[data-stacked] .ds-dialog__box {
    transform-origin: 50% 0;
  }

  /* By hand (no data-state): the keyframes, movement with the fades. */
  .ds-tearsheet:not([data-state]) .ds-dialog__box {
    --ds-motion-distance: var(--ds-distance-sheet);
    animation:
      ds-fade-in var(--ds-dur-fast) var(--ds-ease-in-out) backwards,
      ds-lift-in var(--ds-dur-long) var(--ds-ease-out) backwards;
  }

  .ds-tearsheet.ds-dialog--closing:not([data-state]) .ds-dialog__box {
    --ds-motion-distance: var(--ds-distance-sheet);
    animation:
      ds-fade-out var(--ds-dur-base) var(--ds-ease-in-out) forwards,
      ds-drop-out var(--ds-dur-base) var(--ds-ease-exit) forwards;
  }

  /* A native tearsheet shown by hand (showModal() without DS.overlay). */
  dialog.ds-tearsheet:not([data-state]) .ds-dialog__box {
    animation: none;
    transition:
      opacity var(--ds-dur-fast) var(--ds-ease-in-out),
      translate var(--ds-dur-long) var(--ds-ease-out);
  }

  dialog.ds-tearsheet:not([data-state]):not([open]) .ds-dialog__box {
    scale: none;
    translate: 0 var(--ds-distance-sheet);
    transition:
      opacity var(--ds-dur-base) var(--ds-ease-in-out),
      translate var(--ds-dur-base) var(--ds-ease-exit);
  }

  @starting-style {
    dialog.ds-tearsheet[open]:not([data-state]) .ds-dialog__box {
      opacity: 0;
      scale: none;
      translate: 0 var(--ds-distance-sheet);
    }
  }

  /* Phones: the whole window, the rail a row of steps above the body. */
  @media (max-width: 600px) {
    .ds-tearsheet,
    .ds-tearsheet.ds-dialog--nested {
      padding: 0 0 var(--ds-keyboard-inset, 0px);
    }

    .ds-tearsheet .ds-dialog__box,
    .ds-tearsheet--narrow .ds-dialog__box {
      width: 100%;
      border-radius: 0;
    }

    .ds-tearsheet__head {
      padding-top: max(var(--_pad), env(safe-area-inset-top));
      padding-inline: max(var(--ds-space-4), env(safe-area-inset-left)) max(var(--ds-space-2), env(safe-area-inset-right));
    }

    .ds-tearsheet__main:has(> .ds-tearsheet__steps) {
      grid-template-columns: minmax(0, 1fr);
    }

    /* The rail gives way to the progress line in the head. */
    .ds-tearsheet__steps {
      display: none;
    }

    .ds-tearsheet__box:has(> .ds-tearsheet__main > .ds-tearsheet__steps) .ds-tearsheet__progress:not(:empty) {
      display: block;
    }

    .ds-tearsheet__body {
      padding-inline: max(var(--ds-space-4), env(safe-area-inset-left)) max(var(--ds-space-4), env(safe-area-inset-right));
    }

    .ds-tearsheet__foot {
      padding-inline: max(var(--ds-space-4), env(safe-area-inset-left)) max(var(--ds-space-4), env(safe-area-inset-right));
      padding-bottom: calc(var(--ds-space-4) + var(--ds-density, 0) * 2px + env(safe-area-inset-bottom));
    }

    .ds-tearsheet[data-stacked][data-state="open"] .ds-dialog__box {
      scale: none;
      translate: none;
    }
  }
}

/* ── components/loadingoverlay/loadingoverlay.css ── */
/*
 * Loading overlay: blocks one region of the page (a card, a table, a form,
 * a pane) while work on it runs, with a spinner and a message; the rest of
 * the page stays usable. Not for the whole page (that is the app's start,
 * .ds-boot) and not for content that is still to come (a skeleton).
 *
 *   <section class="ds-card" aria-labelledby="dev-title">            (the region: positioned)
 *     ... the content ...
 *     <div class="ds-loadingoverlay" hidden data-ds-loadingoverlay>
 *       <div class="ds-loadingoverlay__box" role="status">
 *         <span class="ds-spinner" aria-hidden="true"></span>
 *         <p class="ds-loadingoverlay__message">Saving LAPTOP-0042 ...</p>
 *         <p class="ds-loadingoverlay__detail">3 of 12 settings</p>      (optional)
 *         <button class="ds-btn ds-btn--text" type="button" data-ds-loadingoverlay-cancel>Cancel</button>   (optional)
 *       </div>
 *     </div>
 *
 * Or without markup: DS.loadingoverlay.show(region, { message }) builds it
 * as the region's last child (js/loadingoverlay.js).
 *
 * It covers the region (absolute, inset 0, the region's radius): a veil of
 * the surface at --ds-state-stale over the content (.ds-loadingoverlay--opaque:
 * the plain surface, for content that must not show while it changes), and
 * in its middle the box, a card on the popover elevation that sticks in
 * view when the region is taller than the window. A determinate ring
 * (.ds-spinner--determinate with --ds-progress) may replace the arc. The
 * veil takes the pointer at once; DS.loadingoverlay makes the region's
 * content inert, sets aria-busy="true" on the region, moves focus that was
 * in it to the box (or its cancel button) and back, and says the message.
 *
 * State (DS.loadingoverlay): data-state="open" while it blocks, "closed"
 * while it leaves; `hidden` once it left. A region that is static gets
 * position: relative from the script (an inline style it owns); give it
 * yourself to keep the script out of your layout.
 *
 * Options: size on the region or the overlay (the spinner's size step and
 * the message's type follow the size classes); density changes the box's
 * padding and gap (2px per step); shape multiplies the box's radius; touch
 * reaches the cancel button. No tone: waiting is no status.
 *
 * Motion: it shows only after --ds-delay-loader (a fast save shows nothing,
 * though the region is blocked from the first frame): the veil and the box
 * fade in over --ds-dur-fast, the box rises --ds-distance-sm on
 * --ds-ease-out; once shown it stays for --ds-hold-loader at least
 * (DS.motion.loaderHoldMs), then fades out over --ds-dur-instant.
 *
 * Forced colours: the veil is the Canvas (the content under it is blocked
 * anyway); the box keeps its edge (a transparent border that becomes
 * CanvasText); the spinner takes the system colours of the spinner.
 *
 * Hooks: --ds-loadingoverlay-veil (the surface at --ds-state-stale),
 * --ds-loadingoverlay-radius (--ds-radius-card), --ds-loadingoverlay-padding
 * (--ds-space-5), --ds-loadingoverlay-spinner-size (32px).
 */

@layer ds.components.loadingoverlay {
  .ds-loadingoverlay {
    position: absolute;
    inset: 0;
    z-index: var(--ds-z-sticky);
    display: grid;
    place-items: center;
    padding: var(--ds-space-4);
    border-radius: inherit;
    background: var(--ds-loadingoverlay-veil, color-mix(in srgb, var(--ds-surface) calc(var(--ds-state-stale) * 100%), transparent));
    color: var(--ds-text);
    cursor: progress;
    /* Hidden until --ds-delay-loader passed; it blocks from the first frame. */
    opacity: 0;
  }

  .ds-loadingoverlay[hidden] {
    display: none;
  }

  .ds-loadingoverlay--opaque {
    background: var(--ds-surface);
  }

  .ds-loadingoverlay__box {
    --_pad: calc(var(--ds-loadingoverlay-padding, var(--ds-space-5)) + var(--ds-density, 0) * 2px);
    position: sticky;
    inset-block: var(--ds-space-6);
    display: grid;
    justify-items: center;
    gap: calc(var(--ds-space-3) + var(--ds-density, 0) * 2px);
    max-width: min(320px, 100%);
    padding: var(--_pad) calc(var(--_pad) + var(--ds-space-2));
    border: 1px solid transparent;
    border-radius: calc(var(--ds-loadingoverlay-radius, var(--ds-radius-card)) * var(--ds-shape, 1));
    background: var(--ds-surface-popover);
    box-shadow: var(--ds-elev-popover);
    text-align: center;
    cursor: default;
  }

  .ds-loadingoverlay__box > .ds-spinner {
    --ds-spinner-size: var(--ds-loadingoverlay-spinner-size, 32px);
  }

  .ds-loadingoverlay__box:focus {
    outline: none;
  }

  .ds-loadingoverlay__message {
    margin: 0;
    color: var(--ds-text);
    font: var(--ds-size-font, var(--ds-font-body));
    overflow-wrap: anywhere;
  }

  .ds-loadingoverlay__detail {
    margin: calc(-1 * var(--ds-space-2)) 0 0;
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
    font-variant-numeric: tabular-nums;
  }

  .ds-loadingoverlay__message:empty,
  .ds-loadingoverlay__detail:empty {
    display: none;
  }

  /* State-driven: in after the loader delay, out at once. */
  .ds-loadingoverlay[data-state] {
    transition: opacity var(--ds-dur-instant) var(--ds-ease-in-out);
  }

  .ds-loadingoverlay[data-state] > .ds-loadingoverlay__box {
    translate: 0 var(--ds-distance-sm);
    transition: translate var(--ds-dur-instant) var(--ds-ease-in);
  }

  .ds-loadingoverlay[data-state="open"] {
    opacity: 1;
    transition: opacity var(--ds-dur-fast) var(--ds-ease-in-out) var(--ds-delay-loader);
  }

  .ds-loadingoverlay[data-state="open"] > .ds-loadingoverlay__box {
    translate: none;
    transition: translate var(--ds-dur-fast) var(--ds-ease-out) var(--ds-delay-loader);
  }

  /* Leaving: it lets the pointer through at once. */
  .ds-loadingoverlay[data-state="closed"] {
    pointer-events: none;
  }

  /* Shown by hand (no data-state): visible after the loader delay. */
  .ds-loadingoverlay:not([data-state]) {
    opacity: 1;
    animation: ds-fade-in var(--ds-dur-fast) var(--ds-ease-in-out) var(--ds-delay-loader) backwards;
  }

  @media (forced-colors: active) {
    .ds-loadingoverlay {
      background: Canvas;
    }
  }

  @media print {
    .ds-loadingoverlay {
      display: none;
    }
  }
}

/* ── components/lightbox/lightbox.css ── */
/*
 * Lightbox: the images of a gallery (the photos of a device, the
 * attachments of a ticket) one at a time over the whole window, with
 * thumbnails, the arrow keys, zoom and pan, a caption and swipe on touch.
 *
 * The gallery, the page's markup: links (or buttons) to the full images.
 *
 *   <ul class="ds-lightbox__gallery" aria-label="Photos of LAPTOP-0042" data-ds-lightbox>
 *     <li><a class="ds-lightbox__item" href="lid.jpg" data-caption="The lid, scratched on the left">
 *       <img src="lid-thumb.jpg" alt="The lid of LAPTOP-0042"></a></li>
 *     ...
 *   </ul>
 *
 * The viewer, built by DS.lightbox with DOM APIs (a modal dialog that
 * DS.overlay opens and closes):
 *
 *   <dialog class="ds-dialog ds-lightbox" aria-label="Photos of LAPTOP-0042">
 *     <div class="ds-dialog__backdrop" data-ds-close></div>
 *     <div class="ds-dialog__box ds-lightbox__box">
 *       <div class="ds-lightbox__bar">
 *         <p class="ds-lightbox__count">Image 2 of 6</p>
 *         <button class="ds-btn ds-btn--ghost ds-btn--icon" type="button" aria-label="Zoom out">(minimize)</button>
 *         <button class="ds-btn ds-btn--ghost ds-btn--icon" type="button" aria-label="Zoom in">(plus)</button>
 *         <button class="ds-btn ds-btn--ghost ds-btn--icon" type="button" aria-label="Close" data-ds-close>(close)</button>
 *       </div>
 *       <div class="ds-lightbox__stage">
 *         <button class="ds-btn ds-btn--ghost ds-btn--icon ds-lightbox__nav ds-lightbox__nav--prev" type="button" aria-label="Previous">(chevronLeft)</button>
 *         <figure class="ds-lightbox__figure">
 *           <div class="ds-lightbox__frame"><img class="ds-lightbox__image" alt="..."></div>
 *           <figcaption class="ds-lightbox__caption">...</figcaption>
 *         </figure>
 *         <button class="ds-btn ds-btn--ghost ds-btn--icon ds-lightbox__nav ds-lightbox__nav--next" type="button" aria-label="Next">(chevronRight)</button>
 *       </div>
 *       <div class="ds-lightbox__thumbs" role="group" aria-label="Images">
 *         <button class="ds-lightbox__thumb" type="button" aria-label="Image 1 of 6" aria-current="true"><img alt=""></button> ...
 *       </div>
 *
 * The viewer is dark in both colour schemes (--ds-lightbox-bg, its ink
 * --ds-lightbox-ink): the inverse surface in the light scheme, the backdrop
 * in the dark one. Its buttons are ghost buttons, in that ink. The image
 * fits the frame; zoomed, it is scaled by --ds-lightbox-zoom and moved by
 * --ds-lightbox-x and --ds-lightbox-y (runtime properties DS.lightbox
 * writes on the frame), and the frame shows the move cursor.
 *
 * States, written by DS.lightbox: data-zoomed on the frame while it is
 * zoomed, data-dragging while a pointer pans or swipes (the image follows
 * it without a transition), data-loading while the image loads (a spinner
 * after --ds-delay-loader), data-failed when it did not load (an icon and
 * the words in .ds-lightbox__error), aria-current="true" on the current
 * thumbnail (a ring and the full opacity; the others are dimmed). A
 * pressed item or thumbnail shows a currentColor state layer (::before).
 *
 * Options: shape multiplies the radius of the gallery's items and of the
 * thumbnails; density changes the gallery's gap and the bar's padding;
 * size and touch reach the buttons (the thumbnails are at least the touch
 * target under .ds-touch). No tone.
 *
 * Phones (600px and below): the arrows lie over the image's sides, the
 * thumbnails are smaller, the caption takes the safe area.
 *
 * Motion: the viewer opens as a dialog (the box fades and grows from
 * --ds-scale-enter over --ds-dur-slow on the spring); a new image enters
 * with DS.motion.enter()'s swap; zoom and pan glide over --ds-dur-medium on
 * --ds-ease-out (a size that fills the frame never overshoots); a drag
 * follows the pointer; a swipe that does not go far enough glides back.
 *
 * Forced colours: the current thumbnail's ring is SelectedItem (a choice in
 * a set); the gallery's items and the thumbnails keep a CanvasText edge;
 * the error's icon and words are CanvasText.
 *
 * Hooks: --ds-lightbox-bg, --ds-lightbox-ink, --ds-lightbox-thumb-size
 * (56px, 48px on phones), --ds-lightbox-item-size (120px: the gallery's
 * columns), --ds-lightbox-radius (--ds-radius-sm: items and thumbnails).
 *
 * Progressive:
 * - scrollbar-color and scrollbar-width (a thin scrollbar on the row of
 *   thumbnails): without them the platform scrollbar shows.
 */

@layer ds.components.lightbox {
  /* ── The gallery ─────────────────────────────────── */

  .ds-lightbox__gallery {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(var(--ds-lightbox-item-size, 120px), 1fr));
    gap: calc(var(--ds-space-2) + var(--ds-density, 0) * 1px);
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .ds-lightbox__gallery > li {
    display: contents;
  }

  .ds-lightbox__item {
    position: relative;
    display: block;
    aspect-ratio: 1;
    overflow: hidden;
    padding: 0;
    border: 1px solid var(--ds-line);
    border-radius: calc(var(--ds-lightbox-radius, var(--ds-radius-sm)) * var(--ds-shape, 1));
    background: var(--ds-surface-low);
    color: var(--ds-text);
    cursor: zoom-in;
    outline-offset: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    transition: outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-lightbox__item > img {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: cover;
  }

  /* The state layer over the image: hover and press. */
  .ds-lightbox__item::before {
    content: '';
    position: absolute;
    inset: 0;
    background: currentColor;
    opacity: 0;
    pointer-events: none;
    transition: opacity var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  @media (hover: hover) {
    .ds-lightbox__item:hover::before {
      opacity: var(--ds-state-hover);
    }
  }

  .ds-lightbox__item:active::before {
    opacity: var(--ds-state-pressed);
    transition-duration: var(--ds-dur-micro);
  }

  .ds-lightbox__item:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: var(--ds-focus-offset);
  }

  /* ── The viewer ──────────────────────────────────── */

  .ds-lightbox {
    padding: 0;
  }

  /* The viewer is its own dark surface: the blocked look and the focus
     ring of its controls follow its ink, so they read on it. */
  .ds-lightbox__box {
    --_ink: var(--ds-lightbox-ink, light-dark(var(--ds-on-inverse), var(--ds-text)));
    --_bg: var(--ds-lightbox-bg, light-dark(var(--ds-inverse), var(--ds-backdrop)));
    --ds-disabled-ink: color-mix(in srgb, var(--_ink) calc(var(--ds-state-disabled) * 100%), transparent);
    --ds-focus-outline: var(--ds-focus-width) solid var(--_ink);
    display: grid;
    grid-template-rows: auto minmax(0, 1fr) auto;
    gap: 0;
    width: 100%;
    height: 100%;
    max-height: none;
    padding: 0;
    overflow: hidden;
    border-radius: 0;
    background: var(--_bg);
    color: var(--_ink);
    box-shadow: none;
  }

  .ds-lightbox__bar {
    display: flex;
    align-items: center;
    gap: var(--ds-space-1);
    padding:
      calc(var(--ds-space-2) + var(--ds-density, 0) * 2px + env(safe-area-inset-top))
      max(var(--ds-space-2), env(safe-area-inset-right))
      calc(var(--ds-space-2) + var(--ds-density, 0) * 2px)
      max(var(--ds-space-4), env(safe-area-inset-left));
  }

  .ds-lightbox__count {
    flex: 1;
    min-width: 0;
    margin: 0;
    font: var(--ds-font-label);
    font-variant-numeric: tabular-nums;
  }

  .ds-lightbox__stage {
    position: relative;
    display: grid;
    grid-template-columns: auto minmax(0, 1fr) auto;
    align-items: center;
    gap: var(--ds-space-2);
    min-height: 0;
    padding-inline: var(--ds-space-2);
  }

  .ds-lightbox__figure {
    display: grid;
    grid-template-rows: minmax(0, 1fr) auto;
    gap: var(--ds-space-3);
    height: 100%;
    min-height: 0;
    margin: 0;
  }

  .ds-lightbox__frame {
    --_zoom: var(--ds-lightbox-zoom, 1);
    position: relative;
    display: grid;
    place-items: center;
    min-height: 0;
    overflow: hidden;
    touch-action: none;
    user-select: none;
    cursor: zoom-in;
  }

  .ds-lightbox__frame[data-zoomed] {
    cursor: grab;
  }

  .ds-lightbox__frame[data-dragging] {
    cursor: grabbing;
  }

  .ds-lightbox__image {
    display: block;
    max-width: 100%;
    max-height: 100%;
    object-fit: contain;
    scale: var(--_zoom);
    translate: var(--ds-lightbox-x, 0px) var(--ds-lightbox-y, 0px);
    transition:
      scale var(--ds-dur-medium) var(--ds-ease-out),
      translate var(--ds-dur-medium) var(--ds-ease-out);
  }

  /* A drag follows the pointer. */
  .ds-lightbox__frame[data-dragging] > .ds-lightbox__image {
    transition: none;
  }

  .ds-lightbox__frame[data-failed] > .ds-lightbox__image {
    display: none;
  }

  /* Loading: the spinner after the loader delay, over the frame. */
  .ds-lightbox__frame > .ds-spinner {
    position: absolute;
    inset: 0;
    margin: auto;
    visibility: hidden;
  }

  .ds-lightbox__frame[data-loading] > .ds-spinner {
    visibility: visible;
    animation-delay: var(--ds-delay-loader);
  }

  .ds-lightbox__error {
    display: none;
    align-items: center;
    gap: var(--ds-space-2);
    margin: 0;
    font: var(--ds-font-body);
  }

  .ds-lightbox__frame[data-failed] > .ds-lightbox__error {
    display: flex;
  }

  .ds-lightbox__caption {
    min-height: 1lh;
    margin: 0;
    font: var(--ds-font-body);
    text-align: center;
    overflow-wrap: anywhere;
  }

  .ds-lightbox__caption:empty {
    visibility: hidden;
  }

  .ds-lightbox__thumbs {
    position: relative;
    display: flex;
    justify-content: safe center;
    gap: var(--ds-space-2);
    overflow-x: auto;
    overscroll-behavior: contain;
    scrollbar-width: thin;
    scrollbar-color: var(--_ink) transparent;
    padding:
      var(--ds-space-2)
      max(var(--ds-space-4), env(safe-area-inset-right))
      calc(var(--ds-space-3) + env(safe-area-inset-bottom))
      max(var(--ds-space-4), env(safe-area-inset-left));
  }

  .ds-lightbox__thumbs:empty {
    display: none;
  }

  .ds-lightbox__thumb {
    --_t: max(var(--ds-target-min, 0px), var(--ds-lightbox-thumb-size, 56px));
    position: relative;
    flex: none;
    width: var(--_t);
    height: var(--_t);
    overflow: hidden;
    padding: 0;
    border: 1px solid transparent;
    border-radius: calc(var(--ds-lightbox-radius, var(--ds-radius-sm)) * var(--ds-shape, 1));
    background: transparent;
    color: inherit;
    cursor: pointer;
    opacity: var(--ds-state-stale);
    outline-offset: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    transition:
      opacity var(--ds-dur-fast) var(--ds-ease-in-out),
      outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-lightbox__thumb > img {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: cover;
  }

  /* The press: a state layer over the picture, in --ds-dur-micro, and the full opacity. */
  .ds-lightbox__thumb::before {
    content: '';
    position: absolute;
    inset: 0;
    background: currentColor;
    opacity: 0;
    pointer-events: none;
    transition: opacity var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  @media (hover: hover) {
    .ds-lightbox__thumb:hover {
      opacity: 1;
    }
  }

  .ds-lightbox__thumb:active {
    opacity: 1;
    transition-duration: var(--ds-dur-micro);
  }

  .ds-lightbox__thumb:active::before {
    opacity: var(--ds-state-pressed);
    transition-duration: var(--ds-dur-micro);
  }

  /* The current image: full opacity and a ring in the ink (not colour alone: aria-current). */
  .ds-lightbox__thumb[aria-current="true"] {
    opacity: 1;
    box-shadow: inset 0 0 0 2px var(--_ink);
  }

  .ds-lightbox__thumb:focus-visible {
    opacity: 1;
    outline: var(--ds-focus-outline);
    outline-offset: var(--ds-focus-offset);
  }

  @media (max-width: 600px) {
    .ds-lightbox__stage {
      grid-template-columns: minmax(0, 1fr);
      padding-inline: 0;
    }

    .ds-lightbox__figure {
      grid-column: 1;
      grid-row: 1;
    }

    /* The arrows lie over the image's sides, on a veil of the canvas so
       they read on any image. */
    .ds-lightbox__nav {
      --ds-btn-bg: color-mix(in srgb, var(--_bg) calc(var(--ds-state-stale) * 100%), transparent);
      position: absolute;
      inset-block-start: 50%;
      z-index: var(--ds-z-raised);
      translate: 0 -50%;
    }

    .ds-lightbox__nav--prev {
      inset-inline-start: var(--ds-space-1);
    }

    .ds-lightbox__nav--next {
      inset-inline-end: var(--ds-space-1);
    }

    .ds-lightbox__thumb {
      --_t: max(var(--ds-target-min, 0px), var(--ds-lightbox-thumb-size, 48px));
    }
  }

  @media (forced-colors: active) {
    .ds-lightbox__item,
    .ds-lightbox__thumb {
      border-color: CanvasText;
    }

    .ds-lightbox__thumb[aria-current="true"] {
      forced-color-adjust: none;
      box-shadow: inset 0 0 0 3px SelectedItem;
    }

    .ds-lightbox__error {
      color: CanvasText;
    }
  }

  @media print {
    .ds-lightbox {
      display: none;
    }
  }
}

/* ── components/bottomsheet/bottomsheet.css ── */
/*
 * Bottom sheet: a panel that rises from the bottom edge (a phone's filters,
 * the details of a pin on a map, a short choice), with a drag handle,
 * detents (the heights it rests at) and drag to dismiss. It is a modal side
 * sheet (DS.overlay opens and closes it: the trap, the inert page, the
 * scroll lock, Escape, focus return) laid out at the bottom at every width:
 * the whole width on a phone, at most --ds-bottomsheet-width (640px) and
 * centred on a wider screen.
 *
 *   <dialog class="ds-sheet ds-bottomsheet" aria-labelledby="bs-title" data-ds-bottomsheet data-ds-bottomsheet-detents="0.5 1">
 *     <div class="ds-sheet__backdrop" data-ds-close></div>
 *     <section class="ds-sheet__panel ds-bottomsheet__panel">
 *       <button class="ds-bottomsheet__handle" type="button" aria-label="Resize the sheet"></button>
 *       <div class="ds-sheet__head">
 *         <h2 class="ds-sheet__title" id="bs-title">Filters</h2>
 *         <button class="ds-btn ds-btn--quiet ds-btn--icon" type="button" aria-label="Close" data-ds-close>(close)</button>
 *       </div>
 *       <div class="ds-sheet__body" tabindex="0"> ... </div>
 *       <div class="ds-sheet__foot"> ... </div>                       (optional)
 *     </section>
 *   </dialog>
 *
 * Detents (data-ds-bottomsheet-detents, fractions of the panel's full
 * height, which is the window less --ds-bottomsheet-gap): the panel is
 * that tall and DS.bottomsheet moves it down by the runtime property
 * --ds-bottomsheet-offset, so a detent shows its share; the runtime
 * property --ds-bottomsheet-rest (the offset of the detent it rests at)
 * pads the panel's end, so the foot and the end of the body stay in the
 * window at every detent. Without detents the
 * panel is as tall as its content (at most the full height) and rests fully
 * up.
 *
 * The handle: a 32 x 4px pill in a target at least the touch target tall,
 * a button (Enter and Space go to the next detent, ArrowUp and ArrowDown
 * the larger and the smaller one). The head and the handle drag: the panel
 * follows the finger (data-dragging holds its transition: the named motion
 * exception of the bottom sheet, conventions section 8), and on release it
 * springs to the nearest detent the throw reaches, or leaves when it is
 * thrown below half of the smallest one.
 *
 * Options: density and shape as for the side sheet (padding, the head's
 * height; the radius of the top corners times --ds-shape); size and touch
 * reach the controls inside. No tone.
 *
 * Motion (state-driven on data-state): the panel rises its full height on
 * the spatial spring over --ds-dur-long while the scrim fades; a detent
 * change springs there over --ds-dur-long; it drops back down in
 * --ds-dur-base, accelerating. The bleed (a strip of the panel's own
 * background below its bottom edge) covers the spring's overshoot. By hand
 * (no data-state): ds-lift-in, and ds-drop-out its full height.
 *
 * Forced colours: the panel keeps the side sheet's transparent outline as
 * its edge; the handle's pill is CanvasText (Highlight while it has focus
 * or drags).
 *
 * Hooks: --ds-bottomsheet-width (640px), --ds-bottomsheet-gap
 * (--ds-space-12: the room above the panel at its full height),
 * --ds-bottomsheet-radius (--ds-radius-dialog).
 */

@layer ds.components.bottomsheet {
  /* At the bottom edge, centred: the panel's room is the window. */
  .ds-bottomsheet {
    justify-content: center;
    align-items: flex-end;
  }

  .ds-bottomsheet__panel {
    --_radius: calc(var(--ds-bottomsheet-radius, var(--ds-radius-dialog)) * var(--ds-shape, 1));
    --_full: calc(100dvh - var(--ds-bottomsheet-gap, var(--ds-space-12)) - var(--ds-keyboard-inset, 0px));
    width: min(100%, var(--ds-bottomsheet-width, 640px));
    height: auto;
    max-height: var(--_full);
    padding-top: 0;
    border-radius: var(--_radius) var(--_radius) 0 0;
  }

  /* With detents the panel is as tall as its largest one may show; the
     part below the window at the resting detent is padding, so the foot
     sits at the window's edge and the body scrolls within what shows (a
     drag leaves it as it is: --ds-bottomsheet-rest changes only at rest). */
  .ds-bottomsheet[data-detents] .ds-bottomsheet__panel {
    height: var(--_full);
    padding-bottom: var(--ds-bottomsheet-rest, 0px);
  }

  /* The bleed sits below the panel (the spring carries it up a little). */
  .ds-bottomsheet__panel::after {
    inset-block-start: 100%;
    inset-inline: 0;
    width: auto;
    height: var(--ds-space-12);
  }

  /* State-driven: up from below on the spring, to its detent's offset. */
  .ds-bottomsheet[data-state] .ds-bottomsheet__panel {
    translate: 0 var(--ds-bottomsheet-offset, 0px);
    transition: translate var(--ds-dur-long) var(--ds-ease-spatial);
  }

  .ds-bottomsheet[data-state="closed"] .ds-bottomsheet__panel {
    translate: 0 var(--ds-distance-sheet);
    transition: translate var(--ds-dur-base) var(--ds-ease-exit);
  }

  /* A drag: the panel follows the finger. */
  .ds-bottomsheet[data-state] .ds-bottomsheet__panel[data-dragging] {
    transition: none;
    user-select: none;
  }

  /* By hand, without data-state: the keyframes rise and drop the full height. */
  .ds-bottomsheet:not([data-state]) .ds-bottomsheet__panel {
    --ds-motion-distance: var(--ds-distance-sheet);
    animation: ds-lift-in var(--ds-dur-long) var(--ds-ease-spatial) backwards;
  }

  .ds-bottomsheet.ds-sheet--closing:not([data-state]) .ds-bottomsheet__panel {
    --ds-motion-distance: var(--ds-distance-sheet);
    animation:
      ds-drop-out var(--ds-dur-base) var(--ds-ease-exit) forwards,
      ds-fade-out var(--ds-dur-base) var(--ds-ease-in-out) forwards;
  }

  /* The handle: a pill at the top, a target as tall as the touch target. */
  .ds-bottomsheet__handle {
    display: grid;
    place-items: center;
    flex: none;
    align-self: center;
    width: max(var(--ds-target-min, 0px), var(--ds-space-12));
    height: max(var(--ds-target-min, 0px), var(--ds-space-6));
    margin: 0;
    padding: 0;
    border: 0;
    border-radius: var(--_radius);
    background: transparent;
    color: var(--ds-text-2);
    cursor: grab;
    touch-action: none;
    outline-offset: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    transition: outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-bottomsheet__handle::before {
    content: '';
    width: var(--ds-space-8);
    height: var(--ds-space-1);
    border-radius: calc(var(--ds-space-1) / 2);
    background: currentColor;
    opacity: var(--ds-state-stale);
    transition: opacity var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  @media (hover: hover) {
    .ds-bottomsheet__handle:hover::before {
      opacity: 1;
    }
  }

  .ds-bottomsheet__handle:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: var(--ds-focus-offset);
  }

  .ds-bottomsheet__handle:focus-visible::before,
  .ds-bottomsheet__panel[data-dragging] .ds-bottomsheet__handle::before {
    opacity: 1;
  }

  .ds-bottomsheet__panel[data-dragging] .ds-bottomsheet__handle {
    cursor: grabbing;
  }

  /* The head drags too: it says so where a pointer hovers it. */
  .ds-bottomsheet .ds-bottomsheet__panel > .ds-sheet__head {
    touch-action: none;
    cursor: grab;
  }

  @media (max-width: 600px) {
    .ds-bottomsheet__panel {
      border-radius: var(--_radius) var(--_radius) 0 0;
    }

    .ds-bottomsheet[data-state="open"] .ds-bottomsheet__panel {
      transition: translate var(--ds-dur-long) var(--ds-ease-spatial);
    }

    .ds-bottomsheet:not([data-state]) .ds-bottomsheet__panel {
      animation: ds-lift-in var(--ds-dur-long) var(--ds-ease-spatial) backwards;
    }
  }

  @media (forced-colors: active) {
    .ds-bottomsheet__handle::before {
      background: CanvasText;
      opacity: 1;
    }

    .ds-bottomsheet__handle:focus-visible::before,
    .ds-bottomsheet__panel[data-dragging] .ds-bottomsheet__handle::before {
      background: Highlight;
    }
  }
}

/* ── components/highlight/highlight.css ── */
/*
 * Syntax highlighting (D13): the tokens DS.highlight writes, each a span
 * coloured by a code role. Text-level: it styles nothing but the token
 * spans, so it works in a .ds-code-block, a pre in .ds-prose, a code
 * block of DS.code or any element of the page.
 *
 *   <pre class="ds-code-block"><code data-ds-highlight="json">{ "id": 42 }</code></pre>
 *   (DS.highlight writes) <span class="ds-highlight__property">"id"</span>: <span class="ds-highlight__number">42</span>
 *
 * Kinds and the role each reads (a theme sets the roles, never a token
 * class):
 *   keyword                 --ds-code-keyword
 *   string, regex           --ds-code-string
 *   number, constant        --ds-code-number   (true, null, a hex colour)
 *   comment                 --ds-code-comment
 *   function, tag           --ds-code-function (a call, a definition, an
 *                                               HTML or XML tag name)
 *   type                    --ds-code-type     (a class, a built-in type, a
 *                                               CSS class or id selector)
 *   property, attribute,    --ds-code-property (an object key, a CSS
 *   variable                                    property, an attribute, $VAR)
 *   meta                    --ds-code-meta     (a decorator, a doctype, a
 *                                               shell prompt, diff headers)
 *   inserted, deleted       --ds-code-inserted, --ds-code-deleted (diff
 *                                               lines; their + and - stay,
 *                                               so a change never rests on
 *                                               the colour)
 *   punctuation             --ds-text-2
 *   operator                the text colour
 * The code roles are colour roles of tokens.css, with their dark values in
 * themes/dark.css and their contrast values in themes/contrast.css: each
 * reaches 4.5:1 on --ds-code-bg in the light and the dark scheme, 7:1
 * under themes/contrast.css (the tests check the pairs).
 *
 * Options: none. The tokens keep the size, weight and font of the code
 * around them (.ds-code-block's code role); size, density, shape and tone
 * are the block's.
 *
 * Forced colours: every token takes the text colour (the system's), so the
 * code reads as plain text; diff lines keep their + and -.
 */

@layer ds.components.highlight {
  .ds-highlight__keyword {
    color: var(--ds-code-keyword);
  }

  .ds-highlight__string,
  .ds-highlight__regex {
    color: var(--ds-code-string);
  }

  .ds-highlight__number,
  .ds-highlight__constant {
    color: var(--ds-code-number);
  }

  .ds-highlight__comment {
    color: var(--ds-code-comment);
  }

  .ds-highlight__function,
  .ds-highlight__tag {
    color: var(--ds-code-function);
  }

  .ds-highlight__type {
    color: var(--ds-code-type);
  }

  .ds-highlight__property,
  .ds-highlight__attribute,
  .ds-highlight__variable {
    color: var(--ds-code-property);
  }

  .ds-highlight__meta {
    color: var(--ds-code-meta);
  }

  .ds-highlight__inserted {
    color: var(--ds-code-inserted);
  }

  .ds-highlight__deleted {
    color: var(--ds-code-deleted);
  }

  .ds-highlight__punctuation {
    color: var(--ds-text-2);
  }

  .ds-highlight__operator {
    color: inherit;
  }
}

/* ── components/markdown/markdown.css ── */
/*
 * Markdown (DS.markdown, markdown.js): the renderer writes bare markup for
 * .ds-prose, so this file holds only the moment before it runs. An element
 * with data-ds-markdown shows its source with the line breaks kept until
 * DS.markdown renders it (data-state="rendered"), so the text reads where
 * the module is missing or late.
 *
 *   <div class="ds-prose" data-ds-markdown>## Notes ...</div>
 *   <div class="ds-prose" data-ds-markdown><script type="text/markdown">## Notes ...</script></div>
 *
 * Options: none of its own; the prose around it takes them.
 *
 * Forced colours, motion: nothing of its own.
 */

@layer ds.components.markdown {
  :where(.ds-theme) [data-ds-markdown]:not([data-state="rendered"]) {
    white-space: pre-line;
  }
}

/* ── components/code/code.css ── */
/*
 * Code: .ds-code-block for a block of code or a raw request (a pre in
 * .ds-prose looks the same), and .ds-code, the frame around one or more
 * blocks with a header, line numbers, marked lines, tabs for several files
 * and a folded height (DS.code, code.js).
 *
 *   <pre class="ds-code-block" tabindex="0" aria-label="Request"><code>GET /devices/42</code></pre>
 *   <pre class="ds-code-block ds-code-block--wrap">...</pre>   (long lines wrap)
 *
 *   <figure class="ds-code ds-code--lines" data-ds-code data-ds-code-max="12">
 *     <div class="ds-code__head ds-sm">
 *       <span class="ds-code__title">device.json</span>             (or a .ds-tabs ds-tabs--flush tablist)
 *       <span class="ds-code__lang"></span>
 *       <span class="ds-code__actions"> wrap toggle, copy button (.ds-btn--quiet.ds-btn--icon) </span>
 *     </div>
 *     <pre class="ds-code-block" tabindex="0" data-ds-code-lang="json" data-ds-code-mark="2"><code>...</code></pre>
 *     <div class="ds-code__foot"><button class="ds-btn ds-btn--text" type="button" data-ds-code-expand aria-expanded="false"><span class="ds-code__expand-label">Show more</span>(chevronDown .ds-chevron)</button></div>
 *   </figure>
 *
 * .ds-code-block: the code role on --ds-code-bg in a card's radius, one
 * line per line, scrolling sideways (a thin scrollbar); give it
 * tabindex="0" and a name only when it can scroll, so a keyboard reaches it
 * (an inset ring, solid from the first frame). A code element inside loses
 * the inline chip. --wrap wraps long lines instead. In .ds-prose--compact
 * its padding is tighter. Outside prose it has no margin; in prose the
 * prose's rhythm spaces it.
 *
 * .ds-code: the frame on --ds-code-bg in --ds-code-block-radius (the
 * blocks inside give up their own corners), a hairline under the header.
 * The header: the title (the code role, one line with an ellipsis) or a
 * .ds-tabs ds-tabs--flush tablist of files, the language (the meta role,
 * --ds-text-2) and the actions at its end; .ds-sm on it keeps its controls
 * one step under the text. Lines (DS.code writes them):
 * .ds-code__line, one per line; .ds-code--lines numbers them in a gutter
 * (the meta role's colour, as wide as the largest number, not selectable
 * and not copied); .ds-code__line--mark (a <mark>) tints a line and gives
 * it a bar at its start, so it never rests on the colour;
 * .ds-code__line--inserted and --deleted tint a diff's lines (their + and -
 * stay). data-state="collapsed" (DS.code) folds the block to
 * data-ds-code-max lines with a fade above .ds-code__foot, whose text
 * button (.ds-chevron turning with aria-expanded) unfolds it; without a
 * data-state the foot is gone.
 *
 * Options (src/core/options.css, docs/options.md), on the block or any
 * ancestor; each is computed here:
 *   density   .ds-density-*: 2px off the block's padding per step (1px in
 *             .ds-prose--compact), so the lines and the gutter follow; the
 *             header's tabs follow their own density
 *   shape     .ds-shape-*: multiplies the radius of the block and the frame
 *   size      not read: the code keeps its role; the header's controls are
 *             .ds-sm (one step under the text)
 *   touch     .ds-touch: the header's tabs and buttons grow to the touch
 *             target (their own rules), so the header does
 *   tone      not read: code states no status
 *
 * Hooks: --ds-code-block-radius (--ds-radius-card).
 *
 * Motion: the fold glides: the block's height (a named exception of the
 * animate list, meta.json) over --ds-dur-medium on --ds-ease-out to open,
 * --ds-dur-base on --ds-ease-in to close (0.8 of the opening), set by
 * DS.code from the current height, so a reversal continues from where it
 * is; the fade follows on --ds-dur-fast. A tab's block swaps in
 * (DS.motion.enter, 'swap'), the tabs' indicator glides.
 *
 * Forced colours: the block and the frame keep their edges (a transparent
 * outline); a marked line keeps its bar in Highlight; the header keeps its
 * hairline.
 *
 * Print: code blocks wrap and unclip; a folded block unfolds.
 *
 * Progressive:
 * - scrollbar-color and scrollbar-width (a thin, quiet scrollbar under a
 *   code block): without them the platform scrollbar shows.
 */

@layer ds.components.code {
  /* A pre in prose is a code block: one look for both. The padding is
     computed here and read by the lines (DS.code). */
  :where(.ds-prose) pre:where(:not([class^="ds-"], [class*=" ds-"])),
  .ds-code-block {
    --_pad-block: calc(var(--ds-space-4) + var(--ds-density, 0) * 2px);
    --_pad-inline: calc(var(--ds-space-4) + var(--ds-density, 0) * 2px);
    position: relative;
    margin-inline: 0;
    padding: var(--_pad-block) var(--_pad-inline);
    overflow-x: auto;
    border-radius: calc(var(--ds-code-block-radius, var(--ds-radius-card)) * var(--ds-shape, 1));
    background: var(--ds-code-bg);
    color: var(--ds-text);
    font: var(--ds-font-code);
    white-space: pre;
    tab-size: 2;
    hyphens: manual;
    overflow-wrap: normal;
    scrollbar-width: thin;
    scrollbar-color: var(--ds-line-2) transparent;
    /* An inset ring (the block clips anything outside): it rests on the
       edge and snaps inward. */
    outline-offset: 0;
    transition: outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  /* No margin of its own, except where prose spaces its blocks. */
  .ds-code-block:where(:not(.ds-prose > *)) {
    margin-block: 0;
  }

  .ds-code-block:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: calc(-1 * var(--ds-focus-width));
  }

  .ds-code-block--wrap {
    white-space: pre-wrap;
    overflow-wrap: anywhere;
  }

  /* Code inside a block is just text: no inline chip. */
  .ds-code-block code,
  .ds-code-block :where(a) code {
    padding: 0;
    border: 0;
    background: none;
    color: inherit;
    font: inherit;
  }

  /* Compact prose (a chat bubble): tighter, 1px per density step. */
  :where(.ds-prose--compact) pre:where(:not([class^="ds-"], [class*=" ds-"])),
  .ds-prose--compact .ds-code-block {
    --_pad-block: calc(var(--ds-space-2) + var(--ds-density, 0) * 1px);
    --_pad-inline: calc(var(--ds-space-3) + var(--ds-density, 0) * 1px);
  }

  /*
   * The frame: header, blocks and foot on one surface. The blocks give up
   * their corners to it.
   */
  .ds-code {
    display: flex;
    flex-direction: column;
    min-width: 0;
    margin-inline: 0;
    border-radius: calc(var(--ds-code-block-radius, var(--ds-radius-card)) * var(--ds-shape, 1));
    background: var(--ds-code-bg);
    overflow: clip;
  }

  .ds-code:where(:not(.ds-prose > *)) {
    margin-block: 0;
  }

  .ds-code > .ds-code-block {
    border-radius: 0;
    overflow-y: hidden;
    /* The fold glides (DS.code sets the height from where it is). */
    transition:
      height var(--ds-dur-medium) var(--ds-ease-out),
      outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-code[data-state="collapsed"] > .ds-code-block {
    /* The folded lines and the top padding: the cut falls on a line, under the fade. */
    block-size: calc(var(--ds-code-max, 12) * 1lh + var(--_pad-block));
    transition:
      height var(--ds-dur-base) var(--ds-ease-in),
      outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-code__head {
    display: flex;
    align-items: center;
    gap: var(--ds-space-2);
    min-width: 0;
    padding-block: var(--ds-space-1);
    padding-inline: calc(var(--ds-space-4) + var(--ds-density, 0) * 2px) var(--ds-space-1);
    border-block-end: 1px solid var(--ds-line);
  }

  /* Files as tabs: the row fills the header, its bar on the hairline. */
  .ds-code__head:has(> .ds-tabs) {
    padding-block: 0;
    padding-inline-start: 0;
  }

  .ds-code__head > .ds-tabs {
    flex: 1 1 auto;
    min-width: 0;
    align-self: stretch;
  }

  .ds-code__title {
    flex: 1 1 auto;
    min-width: 0;
    overflow: hidden;
    color: var(--ds-text);
    font: var(--ds-font-code);
    white-space: nowrap;
    text-overflow: ellipsis;
  }

  .ds-code__lang {
    flex: none;
    margin-inline-start: auto;
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
    white-space: nowrap;
  }

  .ds-code__title + .ds-code__lang,
  .ds-tabs + .ds-code__lang {
    margin-inline-start: 0;
  }

  .ds-code__actions {
    display: flex;
    flex: none;
    align-items: center;
    margin-inline-start: auto;
  }

  /* After a row of tabs that may scroll, a hairline keeps the word apart
     from a tab cut at the row's end. */
  .ds-tabs + .ds-code__lang {
    padding-inline-start: var(--ds-space-2);
    border-inline-start: 1px solid var(--ds-line);
  }

  .ds-code__lang + .ds-code__actions {
    margin-inline-start: 0;
  }

  /* Lines: the block's padding moves onto them, so a mark spans the width. */
  .ds-code-block:has(> code > .ds-code__line) {
    padding-inline: 0;
  }

  .ds-code-block > code:has(> .ds-code__line) {
    display: block;
    min-inline-size: 100%;
    inline-size: max-content;
  }

  .ds-code-block--wrap > code:has(> .ds-code__line) {
    inline-size: auto;
  }

  .ds-code__line {
    position: relative;
    display: block;
    padding-inline: var(--_pad-inline, var(--ds-space-4));
    background: none;
    color: inherit;
  }

  /* The gutter: the number in the line's start padding, never copied. */
  .ds-code--lines .ds-code__line {
    --_gutter: calc(var(--ds-code-digits, 2) * 1ch + var(--ds-space-4));
    padding-inline-start: calc(var(--_pad-inline, var(--ds-space-4)) + var(--_gutter));
  }

  .ds-code--lines .ds-code__line::before {
    content: attr(data-line);
    position: absolute;
    inset-inline-start: var(--_pad-inline, var(--ds-space-4));
    inline-size: calc(var(--ds-code-digits, 2) * 1ch);
    color: var(--ds-text-2);
    text-align: end;
    user-select: none;
  }

  /* A marked line: a tint and a bar at its start (the bar carries it in
     forced colours and for anyone who cannot tell the tint). */
  .ds-code__line--mark {
    border-inline-start: 2px solid var(--ds-primary);
    padding-inline-start: calc(var(--_pad-inline, var(--ds-space-4)) - 2px);
    background: color-mix(in srgb, var(--ds-primary) 10%, transparent);
  }

  .ds-code--lines .ds-code__line--mark {
    padding-inline-start: calc(var(--_pad-inline, var(--ds-space-4)) + var(--_gutter) - 2px);
  }

  .ds-code--lines .ds-code__line--mark::before {
    inset-inline-start: calc(var(--_pad-inline, var(--ds-space-4)) - 2px);
  }

  .ds-code__line--inserted {
    background: color-mix(in srgb, var(--ds-code-inserted) 10%, transparent);
  }

  .ds-code__line--deleted {
    background: color-mix(in srgb, var(--ds-code-deleted) 10%, transparent);
  }

  /* The foot: the button that unfolds, a fade over the folded lines. */
  .ds-code__foot {
    position: relative;
    display: flex;
    justify-content: center;
    padding: var(--ds-space-1);
    border-block-start: 1px solid var(--ds-line);
  }

  .ds-code__expand-label {
    white-space: nowrap;
  }

  .ds-code:not([data-state]) > .ds-code__foot {
    display: none;
  }

  .ds-code__foot::before {
    content: '';
    position: absolute;
    inset-inline: 0;
    inset-block-end: 100%;
    block-size: var(--ds-space-10);
    background: linear-gradient(to bottom, transparent, var(--ds-code-bg));
    opacity: 0;
    pointer-events: none;
    transition: opacity var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-code[data-state="collapsed"] > .ds-code__foot::before {
    opacity: 1;
  }

  @media (forced-colors: active) {
    :where(.ds-prose) pre:where(:not([class^="ds-"], [class*=" ds-"])),
    .ds-code-block,
    .ds-code {
      outline: 1px solid transparent;
    }

    /* The frame is the edge; a framed block's own focus ring stays. */
    .ds-code > .ds-code-block:not(:focus-visible) {
      outline: 0;
    }

    .ds-code__line--mark {
      border-inline-start-color: Highlight;
    }
  }

  @media print {
    :where(.ds-prose) pre:where(:not([class^="ds-"], [class*=" ds-"])),
    .ds-code-block {
      overflow: visible;
      white-space: pre-wrap;
    }

    .ds-code[data-state="collapsed"] > .ds-code-block {
      block-size: auto;
    }

    .ds-code__foot {
      display: none;
    }
  }
}

/* ── components/toc/toc.css ── */
/*
 * Jump links, table of contents: the sections of a long page, the one being
 * read marked as the reader scrolls (scroll-spy, toc.js). A column beside
 * the content (sticky with .ds-toc--sticky) or a bar over it (.ds-toc--bar,
 * the section anchors of an object page).
 *
 *   <nav class="ds-toc ds-toc--sticky" aria-labelledby="toc-title" data-ds-toc>
 *     <p class="ds-toc__title" id="toc-title">On this page</p>
 *     <ol class="ds-toc__list">
 *       <li><a class="ds-toc__link" href="#overview" aria-current="location">Overview</a></li>
 *       <li><a class="ds-toc__link" href="#hardware">Hardware</a>
 *         <ol class="ds-toc__list">
 *           <li><a class="ds-toc__link" href="#storage">Storage</a></li>
 *         </ol></li>
 *       <li><a class="ds-toc__link" href="#history">History<span class="ds-toc__count"><span class="ds-sr">, </span>3</span></a></li>
 *     </ol>
 *   </nav>
 *
 *   A bar of anchors: <nav class="ds-toc ds-toc--bar ds-toc--sticky" aria-label="Sections" data-ds-toc> (the same list; nested lists stay off the bar)
 *
 * Current: aria-current="location" on the link of the section being read
 * (toc.js writes it). It takes the primary ink, the label weight (in a
 * column; a bar keeps the weight, so the links after it never move) and
 * the indicator (DS.indicator, .ds-toc__indicator): a bar on the column's
 * line at its start, under the link in a bar; never colour alone.
 *
 * Variants:
 *   .ds-toc            a column: a hairline at its start, a row per link,
 *                      nested lists indented (the bar stays on the line)
 *   .ds-toc--bar       a row of anchors over a hairline, as line tabs; it
 *                      scrolls sideways without a scrollbar and keeps the
 *                      current one in view; only the first level shows
 *   .ds-toc--sticky    sticks: a column --ds-toc-top below the top of its
 *                      scroller (scrolling itself when taller than the
 *                      view; at 600px of the content it sits above the
 *                      text and stops sticking), a bar at the top on
 *                      --ds-toc-bg
 *
 * Parts: .ds-toc__title (the meta role, text-2), .ds-toc__list,
 * .ds-toc__link, .ds-toc__count (a count after the label, tabular).
 *
 * Options (src/core/options.css, docs/options.md), on the toc or any
 * ancestor; each is computed here, in the link's own rule:
 *   size      .ds-xs ... .ds-xl: 8px of height per step (a column row 32px,
 *             a bar 48px at md), 4px of side padding per step, the type
 *             role of the size at the regular weight
 *   density   .ds-density-*: 4px of height per step; not the padding
 *   shape     .ds-shape-*: multiplies the radius of the ring and the state
 *             layer, at rest and pressed
 *   touch     .ds-touch: a link is at least --ds-target-min high
 *   tone      none: a link states no status
 *
 * Press: the state layer is a pill inside the link (in a bar --ds-space-1
 * from its top and bottom edge) that turns squarer while pressed
 * (--ds-radius-action-pressed times the shape, in --ds-dur-micro, back on
 * the spring) and ripples (js/ripple.js); the keyboard ring is inset and
 * snaps inward. The label changes colour on the indicator's timing.
 *
 * Hooks: --ds-toc-height (32px: a column row at md, comfortable),
 * --ds-toc-bar-height (48px: a bar's link), --ds-toc-padding-x
 * (--ds-space-3), --ds-toc-font (the size's role), --ds-toc-indicator-width
 * (3px), --ds-toc-indicator-color (--ds-primary), --ds-toc-top
 * (--ds-space-4: where a sticky column stops), --ds-toc-bg (--ds-backdrop:
 * under a sticky bar). The computed --_h, --_box, --_half, --_radius,
 * --_layer and --_pad are private.
 *
 * Forced colours: the current link is a choice in a set (SelectedItem /
 * SelectedItemText, the indicator hidden), a focused one a CanvasText ring
 * inside; the hairlines stay CanvasText.
 *
 * Print: the toc stays off the paper (its links lead nowhere there).
 *
 * Progressive:
 * - scrollbar-color and scrollbar-width (a bar hides its scrollbar while it
 *   scrolls sideways): without them the platform scrollbar shows under the
 *   bar.
 */

@layer ds.components.toc {
  .ds-toc {
    min-width: 0;
  }

  .ds-toc__title {
    margin: 0 0 var(--ds-space-2);
    padding-inline-start: calc(var(--ds-toc-padding-x, var(--ds-space-3)) + var(--ds-size-step, 0) * 4px);
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
  }

  .ds-toc__list {
    position: relative;
    display: grid;
    min-width: 0;
    margin: 0;
    padding: 0;
    list-style: none;
  }

  /* The column's line: the start edge of the top list; the indicator's bar
     lies on it. */
  .ds-toc:not(.ds-toc--bar) > .ds-toc__list::before {
    content: '';
    position: absolute;
    inset-block: 0;
    inset-inline-start: 0;
    width: 1px;
    background: var(--ds-line);
    pointer-events: none;
  }

  .ds-toc__link {
    /* The options, computed here: the hook (size md, comfortable) plus 8px
       per size step and 4px per density step, never below the touch
       minimum. */
    --_h: calc(var(--ds-toc-height, 32px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px);
    --_box: max(var(--ds-target-min, 0px), var(--_h));
    --_half: calc(var(--_box) / 2);
    --_radius: min(calc(min(var(--ds-radius-action), var(--_half)) * var(--ds-shape, 1)), var(--_half));
    --_inset: 0px;
    --_layer-half: calc(var(--_half) - var(--_inset));
    --_layer: min(calc(min(var(--ds-radius-action), var(--_layer-half)) * var(--ds-shape, 1)), var(--_layer-half));
    --_layer-pressed: min(calc(var(--ds-radius-action-pressed) * var(--ds-shape, 1)), var(--_layer));
    /* Side padding: 4px per size step; density leaves it alone. */
    --_pad: calc(var(--ds-toc-padding-x, var(--ds-space-3)) + var(--ds-size-step, 0) * 4px);
    position: relative;
    display: flex;
    align-items: center;
    gap: var(--ds-space-2);
    min-height: var(--_box);
    min-width: 0;
    padding: var(--ds-space-1) var(--_pad);
    border-radius: var(--_radius);
    color: var(--ds-text-2);
    font: var(--ds-toc-font, var(--ds-size-font, var(--ds-font-label)));
    font-weight: var(--ds-weight-regular);
    text-decoration: none;
    -webkit-tap-highlight-color: transparent;
    outline-offset: 0;
    transition:
      outline-offset var(--ds-dur-fast) var(--ds-ease-out),
      color var(--ds-indicator-dur, var(--ds-dur-medium)) var(--ds-ease-in-out);
  }

  /* Nested sections: indented by padding, so every link starts on the line
     and the bar meets it. */
  .ds-toc__list .ds-toc__list .ds-toc__link {
    padding-inline-start: calc(var(--_pad) + var(--ds-space-4));
  }

  .ds-toc__list .ds-toc__list .ds-toc__list .ds-toc__link {
    padding-inline-start: calc(var(--_pad) + var(--ds-space-8));
  }

  .ds-toc__link[aria-current]:not([aria-current="false"]) {
    color: var(--ds-primary);
    font-weight: var(--ds-weight-label);
  }

  /* In a bar the links sit side by side: a heavier current one would push
     the ones after it sideways at every change of the scroll-spy, and the
     indicator would glide to a moving target. The weight stays; the ink and
     the indicator under the link mark it. */
  .ds-toc--bar .ds-toc__link[aria-current]:not([aria-current="false"]) {
    font-weight: var(--ds-weight-regular);
  }

  .ds-toc__count {
    margin-inline-start: auto;
    color: inherit;
    font: var(--ds-font-meta);
    font-variant-numeric: tabular-nums;
  }

  /* State layer: a pill inside the link, the colour of the label. */
  .ds-toc__link::before {
    content: '';
    position: absolute;
    inset: var(--_inset) 0;
    border-radius: var(--_layer);
    background: currentColor;
    opacity: 0;
    pointer-events: none;
    transition:
      opacity var(--ds-dur-fast) var(--ds-ease-in-out),
      border-radius var(--ds-dur-medium) var(--ds-ease-spatial);
  }

  @media (hover: hover) {
    .ds-toc__link:hover::before {
      opacity: var(--ds-state-hover);
    }
  }

  .ds-toc__link:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: calc(-1 * var(--ds-focus-width));
  }

  .ds-toc__link:focus-visible::before {
    opacity: var(--ds-state-focus);
    transition-duration: 0s, var(--ds-dur-medium);
  }

  .ds-toc__link:active::before,
  .ds-toc__link.ds-pressed::before {
    opacity: var(--ds-state-pressed);
    border-radius: var(--_layer-pressed);
    transition:
      opacity var(--ds-dur-micro) var(--ds-ease-in-out),
      border-radius var(--ds-dur-micro) var(--ds-ease-out);
  }

  /* With the ripple (js/ripple.js) the flat layer stays at its hover value
     (focus value after a key) and the ripple brings the press. */
  :where(.ds-ripples) .ds-toc__link:where(:not([data-ds-ripple="off"], [data-ds-ripple="off"] *)):is(:active, .ds-pressed)::before {
    opacity: 0;
  }

  @media (hover: hover) {
    :where(.ds-ripples) .ds-toc__link:where(:not([data-ds-ripple="off"], [data-ds-ripple="off"] *)):is(:active, .ds-pressed)::before {
      opacity: var(--ds-state-hover);
    }
  }

  :where(.ds-ripples) .ds-toc__link:where(:not([data-ds-ripple="off"], [data-ds-ripple="off"] *)):focus-visible:is(:active, .ds-pressed)::before {
    opacity: var(--ds-state-focus);
  }

  /* The indicator of the column: a bar on the line, at the link's start (the
     box is the link's; its clip glides). */
  .ds-toc__indicator {
    box-sizing: border-box;
    border-inline-start: var(--ds-toc-indicator-width, 3px) solid var(--ds-toc-indicator-color, var(--ds-primary));
  }

  /* Sticky: a column stops --ds-toc-top below the top of its scroller and
     scrolls itself when taller than the view. */
  .ds-toc--sticky:not(.ds-toc--bar) {
    position: sticky;
    top: var(--ds-toc-top, var(--ds-space-4));
    align-self: start;
    max-height: calc(100dvh - 2 * var(--ds-toc-top, var(--ds-space-4)));
    overflow-y: auto;
    overscroll-behavior: contain;
  }

  /* Narrow content: a column no longer fits beside the text and sits above
     it, so it stops sticking (it would cover what it lies over). */
  @container ds-content (max-width: 600px) {
    .ds-toc--sticky:not(.ds-toc--bar) {
      position: static;
      max-height: none;
      overflow-y: visible;
    }
  }

  /* ── Bar ─────────────────────────────────────── */

  .ds-toc--bar > .ds-toc__title {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }

  .ds-toc--bar > .ds-toc__list {
    display: flex;
    overflow-x: auto;
    overflow-y: hidden;
    border-bottom: 1px solid var(--ds-line);
    scrollbar-width: none;
  }

  .ds-toc--bar > .ds-toc__list::-webkit-scrollbar {
    display: none;
  }

  .ds-toc--bar > .ds-toc__list > li {
    flex: none;
  }

  .ds-toc--bar .ds-toc__list .ds-toc__list {
    display: none;
  }

  .ds-toc--bar .ds-toc__link {
    --_h: calc(var(--ds-toc-bar-height, 48px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px);
    --_inset: var(--ds-space-1);
    padding-block: 0;
    padding-inline: calc(var(--_pad) + var(--ds-space-1));
    white-space: nowrap;
  }

  .ds-toc--bar .ds-toc__count {
    margin-inline-start: 0;
  }

  .ds-toc--bar .ds-toc__indicator {
    border-inline-start: 0;
    border-block-end: var(--ds-toc-indicator-width, 3px) solid var(--ds-toc-indicator-color, var(--ds-primary));
  }

  .ds-toc--bar.ds-toc--sticky {
    position: sticky;
    top: 0;
    z-index: var(--ds-z-sticky);
    background: var(--ds-toc-bg, var(--ds-backdrop));
  }

  @media (forced-colors: active) {
    .ds-toc__indicator {
      display: none;
    }

    /* A hairline is a background, which forced colours would turn to Canvas. */
    .ds-toc:not(.ds-toc--bar) > .ds-toc__list::before {
      forced-color-adjust: none;
      background: CanvasText;
    }

    .ds-toc__link[aria-current]:not([aria-current="false"]) {
      forced-color-adjust: none;
      background: SelectedItem;
      color: SelectedItemText;
    }

    .ds-toc__link[aria-current]:not([aria-current="false"]):focus-visible {
      outline-color: CanvasText;
    }
  }

  @media print {
    .ds-toc {
      display: none;
    }
  }
}

/* ── components/backtop/backtop.css ── */
/*
 * Back to top: a button that appears once the reader has scrolled a long
 * page (or a long box) down, and takes them back to its top (backtop.js).
 * Its look is the button's (an elevated icon button, or one with a label);
 * this file places it and hides it until it is needed.
 *
 *   At the end of the scrolling content (the page's, or a box's):
 *   <button class="ds-btn ds-btn--elevated ds-btn--icon ds-backtop" type="button" data-ds-backtop hidden>(arrowUp 20)</button>
 *
 *   With a label (an extended button):
 *   <button class="ds-btn ds-btn--elevated ds-backtop" type="button" data-ds-backtop hidden>(arrowUp 18) Back to top</button>
 *
 *   Fixed to the window's corner instead (a page that scrolls the window):
 *   <button class="ds-btn ds-btn--elevated ds-btn--icon ds-backtop ds-backtop--fixed" type="button" data-ds-backtop hidden> ... </button>
 *
 * Variants:
 *   .ds-backtop          sticks to the bottom end of its scroller (its
 *                        content edge, inside the scroller's padding), from
 *                        the end of the content it sits in (it takes its
 *                        own row there, so it never covers the last line)
 *   .ds-backtop--fixed   fixed to the window's bottom end corner, clear of
 *                        the safe areas
 *
 * Shown and hidden: the module sets `hidden` (owned state) and plays the
 * scale entrance and exit (DS.motion.enter / leave, 'scale'); without the
 * module the button stays where the page put it.
 *
 * Options: size, density, shape and touch are the button's own (it computes
 * them in its rule); this file reads none. Tone: none (no status).
 *
 * Hooks: --ds-backtop-offset (--ds-space-6: the room to the scroller's or
 * the window's bottom and end edges).
 *
 * Forced colours: the button's own edge and ink.
 *
 * Print: off the paper.
 */

@layer ds.components.backtop {
  .ds-backtop {
    position: sticky;
    inset-block-end: var(--ds-backtop-offset, var(--ds-space-6));
    z-index: var(--ds-z-sticky);
    display: flex;
    /* As much room before it as it keeps from the bottom: at the end of the
       scroll it rises by that much and lands just under the last line. */
    margin-block-start: var(--ds-backtop-offset, var(--ds-space-6));
    margin-inline: auto 0;
  }

  /* A block of its own (so the auto margin puts it at the end) that keeps
     the button's width: an icon button sets its own, a labelled one its
     content's. */
  .ds-backtop:not(.ds-btn--icon) {
    width: fit-content;
  }

  .ds-backtop--fixed {
    position: fixed;
    inset-block-end: max(var(--ds-backtop-offset, var(--ds-space-6)), env(safe-area-inset-bottom));
    inset-inline-end: max(var(--ds-backtop-offset, var(--ds-space-6)), env(safe-area-inset-right));
    margin: 0;
  }

  /* Hidden until the reader has scrolled: gone whatever display the button sets. */
  .ds-backtop[hidden] {
    display: none;
  }

  @media print {
    .ds-backtop {
      display: none;
    }
  }
}

/* ── components/diff/diff.css ── */
/*
 * Diff view: the changes of one or more files from unified diff text
 * (git diff, diff -u), as a review or an audit shows them. diff.js parses
 * the text and renders the files; without the script the source reads as
 * a plain code block.
 *
 *   <div class="ds-diff" data-ds-diff data-ds-diff-view="unified" aria-label="Changes">
 *     <pre class="ds-diff__source">diff --git a/src/sync.js b/src/sync.js ...</pre>
 *   </div>
 *   .ds-diff--wrap      long lines wrap in the unified view too (the split
 *                       view always wraps: its two columns share the width)
 *
 * What diff.js renders into .ds-diff__files (the page writes none of it):
 *   <section class="ds-diff__file">
 *     <div class="ds-diff__head">
 *       <button class="ds-btn ds-btn--quiet ds-btn--icon ds-sm ds-diff__toggle" aria-expanded="true">(chevronDown .ds-chevron)</button>
 *       <h3 class="ds-diff__name"><span class="ds-diff__path ds-diff__path--old">old</span>(arrowRight .ds-diff__arrow)<span class="ds-diff__path">new</span></h3>
 *       <span class="ds-diff__status">Renamed</span>
 *       <span class="ds-diff__stat"><span class="ds-diff__count" data-kind="add">+12</span><span class="ds-diff__count" data-kind="del">−3</span></span>
 *     </div>
 *     <div class="ds-diff__body" tabindex="0" role="region">
 *       <table class="ds-diff__table" data-view="unified|split">
 *         <thead class="ds-diff__cols"> (the column names, for screen readers only)
 *         <tr class="ds-diff__hunk"><td><span class="ds-diff__hunk-head">(load button .ds-diff__expand)<span class="ds-diff__range">@@ -1,5 +1,6 @@</span> <span class="ds-diff__section">function sync()</span></span></td></tr>
 *         <tr class="ds-diff__line"><td class="ds-diff__num" data-kind="add" data-line="12"></td> <td class="ds-diff__sign"> <td class="ds-diff__code">... <ins class="ds-diff__word">3</ins></td></tr>
 *         <tr class="ds-diff__fold"><td><button class="ds-btn ds-btn--quiet ds-sm ds-diff__expand">Show 14 unchanged lines</button></td></tr>
 *         <tr class="ds-diff__note"><td>No newline at end of file</td></tr>
 *     <p class="ds-diff__empty">Binary file, not shown</p>
 *
 * Every cell of a line carries data-kind (add, del, ctx; empty: the blank
 * side of a split row). An added line is on --ds-diff-add-bg with a "+"
 * in the sign column, a removed one on --ds-diff-del-bg with a "−", and a
 * hidden word ("Added", "Removed") for screen readers: the sign carries
 * the meaning, never the colour alone. Changed words are ins and del on
 * --ds-diff-add-word / --ds-diff-del-word. Line numbers and signs are
 * generated content (attr(data-line)) that a selection never copies.
 * The file header sticks while its file scrolls under it
 * (--ds-diff-sticky-top below a fixed bar).
 *
 * Options (src/core/options.css, docs/options.md), on the view or any
 * ancestor; each is computed here:
 *   density   .ds-density-*: 1px of block padding per step off each code
 *             line (24, 22, 20, 20px rows) and 2px off the file header's
 *   size      .ds-xs ... .ds-xl: 1px of block padding per step on each line
 *             (the code keeps its role: --ds-diff-font); the header's
 *             buttons follow their own size rules
 *   shape     .ds-shape-*: multiplies the radius of each file block
 *   touch     .ds-touch: the header's and the folds' buttons grow (button
 *             rules); the lines are no targets
 *   not tone: the colours are the kinds of change, each with its sign
 *
 * Accessibility: each file is a section (unnamed: no landmark of its own)
 * under its heading (data-ds-diff-heading, default h3); its toggle is a
 * disclosure button named by the heading (aria-expanded); the table has
 * column headers for screen readers; the body is a named, focusable region
 * (the one landmark per file) that scrolls sideways with the arrow keys. A fold's button opens the lines and the
 * focus moves to the first of them.
 *
 * Forced colours: the colours go; the signs and words stay, inserted
 * words are underlined and removed ones struck through, and the hunk rows
 * keep a rule above them.
 *
 * Hooks: --ds-diff-bg (--ds-code-bg), --ds-diff-add-bg, --ds-diff-del-bg,
 * --ds-diff-add-word, --ds-diff-del-word, --ds-diff-hunk-bg,
 * --ds-diff-radius (--ds-radius-card), --ds-diff-font (--ds-font-code),
 * --ds-diff-sticky-top (0px), --ds-diff-split-min (720px: the width from
 * which data-ds-diff-view="auto" shows the split view).
 *
 * Print: lines wrap, nothing scrolls, the headers stop sticking.
 *
 * Progressive:
 * - scrollbar-color and scrollbar-width (a thin scrollbar under a wide
 *   file): without them the platform scrollbar shows.
 */

@layer ds.components.diff {
  .ds-diff {
    --_bg: var(--ds-diff-bg, var(--ds-code-bg));
    --_radius: calc(var(--ds-diff-radius, var(--ds-radius-card)) * var(--ds-shape, 1));
    /* Read by diff.js for data-ds-diff-view="auto". */
    --_split-min: var(--ds-diff-split-min, 720px);
    display: block;
    min-inline-size: 0;
    color: var(--ds-text);
  }

  .ds-diff__source {
    position: relative;
    margin: 0;
    padding: var(--ds-space-4);
    overflow-x: auto;
    border-radius: var(--_radius);
    background: var(--_bg);
    font: var(--ds-diff-font, var(--ds-font-code));
    white-space: pre;
  }

  .ds-diff__files {
    display: flex;
    flex-direction: column;
    gap: var(--ds-space-4);
  }

  .ds-diff__file {
    min-inline-size: 0;
    border: 1px solid var(--ds-line);
    border-radius: var(--_radius);
    background: var(--_bg);
    overflow: clip;
  }

  /* The header sticks while its file scrolls under it (clip, unlike hidden, keeps the page the scroller). */
  .ds-diff__head {
    position: sticky;
    inset-block-start: var(--ds-diff-sticky-top, 0px);
    z-index: var(--ds-z-sticky);
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--ds-space-1) var(--ds-space-2);
    padding-block: calc(var(--ds-space-2) + var(--ds-density, 0) * 2px);
    padding-inline: var(--ds-space-2) var(--ds-space-3);
    background: var(--ds-surface);
  }

  .ds-diff__name {
    display: flex;
    flex: 1 1 12rem;
    flex-wrap: wrap;
    align-items: center;
    gap: 0 var(--ds-space-1);
    min-inline-size: 0;
    margin: 0;
    color: var(--ds-text);
    font: var(--ds-diff-font, var(--ds-font-code));
    font-weight: var(--ds-weight-label);
    overflow-wrap: anywhere;
  }

  .ds-diff__toggle {
    flex: none;
  }

  .ds-diff__path {
    min-inline-size: 0;
  }

  .ds-diff__path--old {
    color: var(--ds-text-2);
    font-weight: var(--ds-weight-regular);
  }

  .ds-diff__arrow {
    flex: none;
    color: var(--ds-text-2);
  }

  .ds-diff__status {
    padding: 0 var(--ds-space-2);
    border: 1px solid var(--ds-line-2);
    border-radius: calc(var(--ds-radius-xs) * var(--ds-shape, 1));
    color: var(--ds-text-2);
    font: var(--ds-font-caption);
    white-space: nowrap;
  }

  .ds-diff__stat {
    display: inline-flex;
    gap: var(--ds-space-2);
    font: var(--ds-font-caption);
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
  }

  .ds-diff__count[data-kind="add"] {
    color: var(--ds-on-success-container);
  }

  .ds-diff__count[data-kind="del"] {
    color: var(--ds-on-error-container);
  }

  .ds-diff__body {
    position: relative;
    overflow-x: auto;
    border-block-start: 1px solid var(--ds-line);
    scrollbar-width: thin;
    scrollbar-color: var(--ds-line-2) transparent;
    /* An inset ring: the block clips anything outside it. */
    outline-offset: 0;
    transition: outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-diff__body:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: calc(-1 * var(--ds-focus-width));
  }

  .ds-diff__empty {
    margin: 0;
    padding: var(--ds-space-4);
    border-block-start: 1px solid var(--ds-line);
    color: var(--ds-text-2);
    font: var(--ds-font-body);
  }

  .ds-diff__files > .ds-diff__empty {
    border: 1px solid var(--ds-line);
    border-radius: var(--_radius);
  }

  .ds-diff__table {
    --_pad: max(0px, calc(2px + var(--ds-density, 0) * 1px + var(--ds-size-step, 0) * 1px));
    min-inline-size: 100%;
    border-collapse: collapse;
    border-spacing: 0;
    color: var(--ds-text);
    font: var(--ds-diff-font, var(--ds-font-code));
    tab-size: 4;
  }

  .ds-diff__table[data-view="split"] {
    inline-size: 100%;
    table-layout: fixed;
  }

  /* The column names: for screen readers; the row takes no room. */
  .ds-diff__cols :is(th, td) {
    padding: 0;
    border: 0;
  }

  .ds-diff__table :is(td, th) {
    padding: var(--_pad) 0;
    vertical-align: top;
  }

  .ds-diff__num {
    inline-size: calc(var(--ds-diff-digits, 3) * 1ch + 2 * var(--ds-space-2));
    min-inline-size: calc(var(--ds-diff-digits, 3) * 1ch + 2 * var(--ds-space-2));
    color: var(--ds-text-2);
    font-variant-numeric: tabular-nums;
    text-align: end;
    white-space: nowrap;
    user-select: none;
  }

  .ds-diff__table .ds-diff__num {
    padding-inline: var(--ds-space-2);
  }

  .ds-diff__num::before {
    content: attr(data-line);
  }

  .ds-diff__sign {
    inline-size: 2ch;
    color: var(--ds-text-2);
    text-align: center;
    user-select: none;
  }

  .ds-diff__sign[data-kind="add"]::before {
    content: "+";
    content: "+" / "";
  }

  .ds-diff__sign[data-kind="del"]::before {
    content: "\2212";
    content: "\2212" / "";
  }

  .ds-diff__code {
    inline-size: 100%;
    white-space: pre;
  }

  .ds-diff__table .ds-diff__code {
    padding-inline: var(--ds-space-1) var(--ds-space-4);
  }

  .ds-diff__table[data-view="split"] .ds-diff__code {
    inline-size: auto;
  }

  .ds-diff__table[data-view="split"] .ds-diff__code,
  .ds-diff--wrap .ds-diff__code {
    white-space: pre-wrap;
    overflow-wrap: anywhere;
  }

  /* The halves of a split row meet at a rule. */
  .ds-diff__table[data-view="split"] .ds-diff__code + .ds-diff__num {
    border-inline-start: 1px solid var(--ds-line);
  }

  /* The kinds of change: a fill per line, a stronger one for the gutter and the words. */
  .ds-diff__line > [data-kind="add"] {
    background: var(--ds-diff-add-bg, color-mix(in oklab, var(--ds-success-container) 45%, var(--_bg)));
  }

  .ds-diff__line > [data-kind="del"] {
    background: var(--ds-diff-del-bg, color-mix(in oklab, var(--ds-error-container) 45%, var(--_bg)));
  }

  .ds-diff__line > .ds-diff__num[data-kind="add"] {
    background: var(--ds-success-container);
    color: var(--ds-on-success-container);
  }

  .ds-diff__line > .ds-diff__num[data-kind="del"] {
    background: var(--ds-error-container);
    color: var(--ds-on-error-container);
  }

  .ds-diff__sign[data-kind="add"] {
    color: var(--ds-on-success-container);
  }

  .ds-diff__sign[data-kind="del"] {
    color: var(--ds-on-error-container);
  }

  .ds-diff__line > [data-kind="empty"] {
    background: color-mix(in oklab, var(--ds-line) 40%, var(--_bg));
  }

  .ds-diff__word {
    border-radius: calc(var(--ds-radius-xs) * var(--ds-shape, 1));
    color: inherit;
    text-decoration: none;
  }

  ins.ds-diff__word {
    background: var(--ds-diff-add-word, var(--ds-success-container));
  }

  del.ds-diff__word {
    background: var(--ds-diff-del-word, var(--ds-error-container));
  }

  /* A line the fold opened keeps the focus until the next Tab; it shows a ring like any row. */
  .ds-diff__line {
    outline-offset: 0;
    transition: outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-diff__line:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: calc(-1 * var(--ds-focus-width));
  }

  .ds-diff__hunk > td {
    padding: var(--_pad) var(--ds-space-2);
    border-block-start: 1px solid transparent;
    background: var(--ds-diff-hunk-bg, color-mix(in oklab, var(--ds-info-container) 45%, var(--_bg)));
    color: var(--ds-on-info-container);
  }

  .ds-diff__hunk-head {
    display: flex;
    align-items: center;
    gap: var(--ds-space-2);
    min-block-size: 20px;
    white-space: pre;
  }

  .ds-diff__range {
    font-variant-numeric: tabular-nums;
  }

  .ds-diff__section {
    color: var(--ds-text-2);
  }

  .ds-diff__fold > td,
  .ds-diff__note > td {
    padding: var(--_pad) var(--ds-space-2);
    color: var(--ds-text-2);
  }

  .ds-diff__fold > td {
    background: color-mix(in oklab, var(--ds-line) 25%, var(--_bg));
  }

  /* The fold's button sits in the row's own height; its target reaches the touch minimum. */
  .ds-diff__fold .ds-diff__expand {
    margin-block: calc(-1 * var(--_pad));
  }

  .ds-diff__hunk .ds-diff__expand {
    margin-block: calc(-1 * var(--ds-space-1));
  }

  @media (forced-colors: active) {
    ins.ds-diff__word {
      text-decoration: underline;
    }

    del.ds-diff__word {
      text-decoration: line-through;
    }

    .ds-diff__hunk > td {
      border-block-start-color: CanvasText;
    }
  }

  @media print {
    .ds-diff__head {
      position: static;
    }

    .ds-diff__body,
    .ds-diff__source {
      overflow: visible;
    }

    .ds-diff__code,
    .ds-diff__source {
      white-space: pre-wrap;
      overflow-wrap: anywhere;
    }
  }
}

/* ── components/logview/logview.css ── */
/*
 * Log viewer: a long, growing log (a device's output, a build, a job) with
 * only the lines near the viewport in the page (DS.virtual), ANSI colours on
 * theme roles, levels as an icon and a word, a level filter, search, wrap,
 * timestamps, copy and a "Latest" pill while the reader is away from the
 * end. logview.js renders everything; without the script the source reads
 * as a plain block of text.
 *
 *   <div class="ds-logview" data-ds-logview aria-label="Device log">
 *     <pre class="ds-logview__source">2026-11-04T09:00:01Z INFO Device started ...</pre>
 *   </div>
 *
 * What logview.js renders (the page writes none of it):
 *   <div class="ds-logview__bar" data-ds-keep>
 *     <div class="ds-logview__find">
 *       <div class="ds-search ds-logview__search">(search)<input class="ds-input" type="search"></div>
 *       <span class="ds-logview__found">3 of 12</span>
 *       <button class="ds-btn ds-btn--quiet ds-btn--icon" data-ds-logview-act="previous|next|only"> (only: aria-pressed)
 *     </div>
 *     <div class="ds-logview__tools"><button class="ds-btn ds-btn--quiet ds-btn--icon" data-ds-logview-act="wrap|time|copy"> (wrap, time: aria-pressed)</div>
 *     <div class="ds-logview__filters">
 *       <fieldset class="ds-chips ds-logview__levels"><label class="ds-chip ds-logview__chip" data-level="error">
 *         <input class="ds-chip__input" type="checkbox" checked><span class="ds-chip__body">(check)(icon .ds-logview__glyph)Error<span class="ds-logview__tally">12</span></span></label> ...</fieldset>
 *       <span class="ds-logview__count">4,000 lines</span>
 *     </div>
 *   </div>
 *   <div class="ds-logview__scroller" data-ds-keep>
 *     <div class="ds-logview__lines" role="listbox" aria-multiselectable="true">
 *       <div class="ds-logview__line" role="option" aria-selected="false" data-level="error">
 *         <span class="ds-logview__num" data-line="812"></span>
 *         <span class="ds-logview__time">09:00:01.123</span>
 *         <span class="ds-logview__level">(icon)<span class="ds-logview__word">Error</span></span>
 *         <span class="ds-logview__text">... <span class="ds-logview__ansi" data-fg="red" data-sgr="bold">...</span> <mark class="ds-logview__match">...</mark></span>
 *       </div> ...
 *     </div>
 *     <p class="ds-logview__empty">No lines yet</p>
 *     <div class="ds-jump"><div class="ds-presence ds-logview__latest" hidden><button class="ds-btn ds-btn--elevated ds-sm">(arrowDown) Latest</button></div></div>
 *   </div>
 *
 * The script writes on the view data-wrap (lines wrap) and data-time
 * ("time", "full" or "off": no timestamp column), and on the lines the
 * runtime properties --ds-logview-chars (the longest message),
 * --ds-logview-digits (of the highest line number),
 * --ds-logview-time-chars and --ds-logview-level-chars (the longest level
 * word), so the columns line up and the lines are as
 * wide as the longest.
 *
 * Levels: fatal and error lines lie on a tint of --ds-error-container,
 * warnings on --ds-warning-container (a stack trace under them too); each
 * line with a level shows its icon and its word, so the colour never stands
 * alone. ANSI: the eight colours (the bright ones and 256 or true colours
 * take the nearest) read the hooks --ds-logview-black ... -white, whose
 * defaults are roles (red --ds-error, green --ds-success, yellow
 * --ds-warning, blue --ds-primary, cyan and magenta mixes of two roles,
 * black --ds-text-2, white --ds-text); a background is that colour at a
 * fifth over the ground. Bold, dim, italic, underline, strike and inverse
 * are data-sgr words.
 *
 * Options (src/core/options.css, docs/options.md), on the view or any
 * ancestor; each is computed here:
 *   density   .ds-density-*: 1px of block padding per step off each line
 *             (24, 22, 20, 20px rows) and 2px off the bar's
 *   size      .ds-xs ... .ds-xl: 1px of block padding per step on each
 *             line (the text keeps its role: --ds-logview-font); the bar's
 *             controls are .ds-sm-sized by their own rules
 *   shape     .ds-shape-*: multiplies the radius of the frame and of the
 *             match marks
 *   touch     .ds-touch: the bar's buttons, chips and the pill reach the
 *             touch target (their own rules); lines stay compact
 *   not tone: the levels are the colours, each with its icon and word
 *
 * Narrow (the view under 30rem, a container query): the level word hides
 * (still read), the search takes a row of its own, the chips scroll
 * sideways.
 *
 * Accessibility: the lines are a multi-select listbox named by the view's
 * aria-label (one tab stop, the arrow keys, Space, Shift and Ctrl+A select,
 * Ctrl+C copies, Ctrl+F goes to the search); a line is an option whose name
 * is its time, level word and text (the line number is not read). The
 * search field says the count through aria-describedby; filters, copies and
 * matches are announced politely.
 *
 * Forced colours: the tints go, the icon and the word stay; a selected line
 * is SelectedItem, a match Mark and the current match Highlight.
 *
 * Hooks: --ds-logview-height (400px), --ds-logview-bg (--ds-code-bg),
 * --ds-logview-radius (--ds-radius-card), --ds-logview-font
 * (--ds-font-code), --ds-logview-error-bg, --ds-logview-warn-bg,
 * --ds-logview-match, --ds-logview-match-current and the eight ANSI colours
 * --ds-logview-black, -red, -green, -yellow, -blue, -magenta, -cyan, -white.
 *
 * Motion: the "Latest" pill comes and goes with .ds-presence (motion.css);
 * nothing else moves. Lines arrive in place; following them is a scroll.
 *
 * Print: the lines that are rendered print, wrapped; the bar and the pill
 * do not.
 *
 * Progressive:
 * - scrollbar-color and scrollbar-width (thin scrollbars on the lines and
 *   on the chips): without them the platform scrollbars show.
 */

@layer ds.components.logview {
  .ds-logview {
    --_bg: var(--ds-logview-bg, var(--ds-code-bg));
    --_radius: calc(var(--ds-logview-radius, var(--ds-radius-card)) * var(--ds-shape, 1));
    container-type: inline-size;
    display: flex;
    flex-direction: column;
    min-inline-size: 0;
    block-size: var(--ds-logview-height, 400px);
    border: 1px solid var(--ds-line);
    border-radius: var(--_radius);
    background: var(--_bg);
    color: var(--ds-text);
    overflow: clip;
  }

  .ds-logview__source {
    position: relative;
    flex: 1 1 auto;
    min-block-size: 0;
    margin: 0;
    padding: var(--ds-space-3) var(--ds-space-4);
    overflow: auto;
    font: var(--ds-logview-font, var(--ds-font-code));
    white-space: pre;
  }

  /* ── The bar ─────────────────────────────────────── */

  .ds-logview__bar {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--ds-space-2) var(--ds-space-3);
    padding-block: calc(var(--ds-space-2) + var(--ds-density, 0) * 2px);
    padding-inline: var(--ds-space-3);
    border-block-end: 1px solid var(--ds-line);
    background: var(--ds-surface);
  }

  .ds-logview__find {
    display: flex;
    flex: 1 1 22rem;
    align-items: center;
    gap: var(--ds-space-1);
    min-inline-size: 0;
  }

  .ds-logview__search {
    flex: 1 1 10rem;
    min-inline-size: 0;
  }

  .ds-logview__found {
    flex: none;
    color: var(--ds-text-2);
    font: var(--ds-font-caption);
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
  }

  .ds-logview__found:empty {
    display: none;
  }

  .ds-logview__tools {
    display: flex;
    flex: none;
    align-items: center;
    gap: var(--ds-space-1);
    margin-inline-start: auto;
  }

  .ds-logview__filters {
    display: flex;
    flex: 1 1 100%;
    align-items: center;
    gap: var(--ds-space-3);
    min-inline-size: 0;
  }

  /* One row of chips that scrolls sideways when it does not fit; the room around them keeps their focus rings. */
  .ds-logview__levels {
    position: relative;
    flex: 0 1 auto;
    flex-wrap: nowrap;
    min-inline-size: 0;
    margin: calc(-1 * var(--ds-space-1));
    padding: var(--ds-space-1);
    overflow-x: auto;
    scrollbar-width: thin;
    scrollbar-color: var(--ds-line-2) transparent;
  }

  .ds-logview__glyph {
    flex: none;
  }

  .ds-logview__tally {
    color: var(--ds-text-2);
    font-variant-numeric: tabular-nums;
  }

  .ds-logview__count {
    margin-inline-start: auto;
    color: var(--ds-text-2);
    font: var(--ds-font-caption);
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
  }

  /* ── The lines ───────────────────────────────────── */

  .ds-logview__scroller {
    position: relative;
    flex: 1 1 auto;
    min-block-size: 0;
    overflow: auto;
    overscroll-behavior: contain;
    scrollbar-width: thin;
    scrollbar-color: var(--ds-line-2) transparent;
  }

  /* The pill stays in sight while the lines scroll sideways. */
  .ds-logview__scroller > .ds-jump {
    position: sticky;
    inset-inline-start: 0;
  }

  .ds-logview__lines {
    display: block;
    min-inline-size: max(100%, calc((var(--ds-logview-digits, 3) + var(--ds-logview-time-chars, 8) + var(--ds-logview-chars, 0) + var(--ds-logview-level-chars, 7)) * 1ch + 20px + 3 * var(--ds-space-3) + var(--ds-space-4)));
    inline-size: max-content;
    padding-block: var(--ds-space-1);
    font: var(--ds-logview-font, var(--ds-font-code));
  }

  .ds-logview[data-wrap] .ds-logview__lines {
    min-inline-size: 0;
    inline-size: auto;
  }

  .ds-logview__line {
    --_pad: max(0px, calc(2px + var(--ds-density, 0) * 1px + var(--ds-size-step, 0) * 1px));
    position: relative;
    /* The hover layer (z-index -1) stays above the level tint, below the text. */
    isolation: isolate;
    display: grid;
    grid-template-columns: calc(var(--ds-logview-digits, 3) * 1ch) calc(var(--ds-logview-time-chars, 8) * 1ch) calc(var(--ds-logview-level-chars, 7) * 1ch + 20px) minmax(0, 1fr);
    column-gap: var(--ds-space-3);
    align-items: start;
    padding-block: var(--_pad);
    padding-inline: var(--ds-space-3) var(--ds-space-4);
    color: var(--ds-text);
    cursor: default;
    outline-offset: 0;
    transition:
      background-color var(--ds-dur-fast) var(--ds-ease-in-out),
      outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-logview[data-time="off"] .ds-logview__line {
    grid-template-columns: calc(var(--ds-logview-digits, 3) * 1ch) calc(var(--ds-logview-level-chars, 7) * 1ch + 20px) minmax(0, 1fr);
  }

  .ds-logview[data-time="off"] .ds-logview__time {
    display: none;
  }

  .ds-logview__line:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: calc(-1 * var(--ds-focus-width));
  }

  /* The hover layer: currentColor over the line, under its text. */
  .ds-logview__line::before {
    content: "";
    position: absolute;
    inset: 0;
    z-index: -1;
    background: currentColor;
    opacity: 0;
    pointer-events: none;
    transition: opacity var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  @media (hover: hover) {
    .ds-logview__line:hover::before {
      opacity: var(--ds-state-hover);
    }
  }

  .ds-logview__line[data-level="error"],
  .ds-logview__line[data-level="fatal"] {
    background: var(--ds-logview-error-bg, color-mix(in oklab, var(--ds-error-container) 45%, transparent));
  }

  .ds-logview__line[data-level="warn"] {
    background: var(--ds-logview-warn-bg, color-mix(in oklab, var(--ds-warning-container) 45%, transparent));
  }

  /* A selected line: the primary container, and a bar at its start, so it never rests on the colour. */
  .ds-logview__line[aria-selected="true"] {
    background: color-mix(in oklab, var(--ds-primary-container) 70%, transparent);
  }

  .ds-logview__line[aria-selected="true"]::after {
    content: "";
    position: absolute;
    inset-block: 0;
    inset-inline-start: 0;
    inline-size: 3px;
    background: var(--ds-primary);
  }

  /* Each cell keeps its spaces; the spaces between the cells only space a line's name. */
  .ds-logview__num,
  .ds-logview__time,
  .ds-logview__level,
  .ds-logview__text {
    white-space: pre;
  }

  .ds-logview__num {
    color: var(--ds-text-2);
    font-variant-numeric: tabular-nums;
    text-align: end;
    user-select: none;
  }

  .ds-logview__num::before {
    content: attr(data-line);
  }

  .ds-logview__time {
    overflow: hidden;
    color: var(--ds-text-2);
    font-variant-numeric: tabular-nums;
    text-overflow: ellipsis;
  }

  .ds-logview__level {
    display: inline-flex;
    align-items: center;
    gap: var(--ds-space-1);
    min-inline-size: 0;
    color: var(--ds-text-2);
  }

  .ds-logview__level > svg {
    flex: none;
  }

  .ds-logview__line[data-level="fatal"] .ds-logview__level,
  .ds-logview__line[data-level="error"] .ds-logview__level {
    color: var(--ds-on-error-container);
  }

  .ds-logview__line[data-level="fatal"] .ds-logview__level {
    font-weight: var(--ds-weight-title);
  }

  .ds-logview__line[data-level="warn"] .ds-logview__level {
    color: var(--ds-on-warning-container);
  }

  .ds-logview__line[data-level="info"] .ds-logview__level {
    color: var(--ds-on-info-container);
  }

  .ds-logview__chip[data-level="fatal"] .ds-logview__glyph,
  .ds-logview__chip[data-level="error"] .ds-logview__glyph {
    color: var(--ds-error);
  }

  .ds-logview__chip[data-level="warn"] .ds-logview__glyph {
    color: var(--ds-warning);
  }

  .ds-logview__chip[data-level="info"] .ds-logview__glyph {
    color: var(--ds-info);
  }

  .ds-logview__text {
    min-inline-size: 0;
    tab-size: 4;
  }

  .ds-logview[data-wrap] .ds-logview__text {
    white-space: pre-wrap;
    overflow-wrap: anywhere;
  }

  .ds-logview__empty {
    margin: 0;
    padding: var(--ds-space-6) var(--ds-space-4);
    color: var(--ds-text-2);
    font: var(--ds-font-body);
    text-align: center;
  }

  /* ── ANSI ────────────────────────────────────────── */

  .ds-logview__ansi[data-fg="black"] {
    color: var(--ds-logview-black, var(--ds-text-2));
  }

  .ds-logview__ansi[data-fg="red"] {
    color: var(--ds-logview-red, var(--ds-error));
  }

  .ds-logview__ansi[data-fg="green"] {
    color: var(--ds-logview-green, var(--ds-success));
  }

  .ds-logview__ansi[data-fg="yellow"] {
    color: var(--ds-logview-yellow, var(--ds-warning));
  }

  .ds-logview__ansi[data-fg="blue"] {
    color: var(--ds-logview-blue, var(--ds-primary));
  }

  .ds-logview__ansi[data-fg="magenta"] {
    color: var(--ds-logview-magenta, color-mix(in oklab, var(--ds-error) 50%, var(--ds-primary)));
  }

  .ds-logview__ansi[data-fg="cyan"] {
    color: var(--ds-logview-cyan, color-mix(in oklab, var(--ds-info) 50%, var(--ds-success)));
  }

  .ds-logview__ansi[data-fg="white"] {
    color: var(--ds-logview-white, var(--ds-text));
  }

  .ds-logview__ansi[data-bg] {
    border-radius: calc(var(--ds-radius-xs) * var(--ds-shape, 1));
  }

  .ds-logview__ansi[data-bg="black"] {
    background: color-mix(in oklab, var(--ds-logview-black, var(--ds-text-2)) 20%, transparent);
  }

  .ds-logview__ansi[data-bg="red"] {
    background: color-mix(in oklab, var(--ds-logview-red, var(--ds-error)) 20%, transparent);
  }

  .ds-logview__ansi[data-bg="green"] {
    background: color-mix(in oklab, var(--ds-logview-green, var(--ds-success)) 20%, transparent);
  }

  .ds-logview__ansi[data-bg="yellow"] {
    background: color-mix(in oklab, var(--ds-logview-yellow, var(--ds-warning)) 20%, transparent);
  }

  .ds-logview__ansi[data-bg="blue"] {
    background: color-mix(in oklab, var(--ds-logview-blue, var(--ds-primary)) 20%, transparent);
  }

  .ds-logview__ansi[data-bg="magenta"] {
    background: color-mix(in oklab, var(--ds-logview-magenta, color-mix(in oklab, var(--ds-error) 50%, var(--ds-primary))) 20%, transparent);
  }

  .ds-logview__ansi[data-bg="cyan"] {
    background: color-mix(in oklab, var(--ds-logview-cyan, color-mix(in oklab, var(--ds-info) 50%, var(--ds-success))) 20%, transparent);
  }

  .ds-logview__ansi[data-bg="white"] {
    background: color-mix(in oklab, var(--ds-logview-white, var(--ds-text)) 12%, transparent);
  }

  .ds-logview__ansi[data-sgr~="bold"] {
    font-weight: var(--ds-weight-title);
  }

  .ds-logview__ansi[data-sgr~="dim"]:not([data-fg]) {
    color: var(--ds-text-2);
  }

  .ds-logview__ansi[data-sgr~="italic"] {
    font-style: italic;
  }

  .ds-logview__ansi[data-sgr~="underline"] {
    text-decoration-line: underline;
  }

  .ds-logview__ansi[data-sgr~="strike"] {
    text-decoration-line: line-through;
  }

  .ds-logview__ansi[data-sgr~="underline"][data-sgr~="strike"] {
    text-decoration-line: underline line-through;
  }

  .ds-logview__ansi[data-sgr~="inverse"]:not([data-bg]) {
    background: color-mix(in oklab, currentColor 18%, transparent);
  }

  /* ── Search ──────────────────────────────────────── */

  .ds-logview__match {
    border-radius: calc(var(--ds-radius-xs) * var(--ds-shape, 1));
    background: var(--ds-logview-match, var(--ds-warning-container));
    color: var(--ds-on-warning-container);
  }

  .ds-logview__match--current {
    background: var(--ds-logview-match-current, var(--ds-warning));
    color: var(--ds-on-warning);
  }

  /* ── Narrow ──────────────────────────────────────── */

  @container (max-width: 30rem) {
    .ds-logview__find {
      flex-basis: 100%;
    }

    .ds-logview__line {
      grid-template-columns: calc(var(--ds-logview-digits, 3) * 1ch) calc(var(--ds-logview-time-chars, 8) * 1ch) 16px minmax(0, 1fr);
      column-gap: var(--ds-space-2);
      padding-inline: var(--ds-space-2) var(--ds-space-3);
    }

    .ds-logview[data-time="off"] .ds-logview__line {
      grid-template-columns: calc(var(--ds-logview-digits, 3) * 1ch) 16px minmax(0, 1fr);
    }

    /* The word is still read: the icon's shape and the word's name carry the level. */
    .ds-logview__word {
      position: absolute;
      inline-size: 1px;
      block-size: 1px;
      overflow: hidden;
      clip-path: inset(50%);
      white-space: nowrap;
    }
  }

  @media (forced-colors: active) {
    .ds-logview__line[aria-selected="true"] {
      background: SelectedItem;
      color: SelectedItemText;
    }

    .ds-logview__line[aria-selected="true"] :is(.ds-logview__num, .ds-logview__time, .ds-logview__level) {
      color: SelectedItemText;
    }

    .ds-logview__match {
      background: Mark;
      color: MarkText;
    }

    .ds-logview__match--current {
      background: Highlight;
      color: HighlightText;
    }
  }

  @media print {
    .ds-logview {
      block-size: auto;
    }

    .ds-logview__bar,
    .ds-logview__scroller > .ds-jump {
      display: none;
    }

    .ds-logview__scroller {
      overflow: visible;
    }

    .ds-logview__lines {
      min-inline-size: 0;
      inline-size: auto;
    }

    .ds-logview__text {
      white-space: pre-wrap;
      overflow-wrap: anywhere;
    }
  }
}

/* ── components/object/object.css ── */
/*
 * Object page: one record on one page. The page head with its key facts,
 * the section anchors (a bar of jump links) under it, and the sections as
 * cards; an edit mode turns a section, or all of them, into its inline-edit
 * form (object.js).
 *
 *   <div class="ds-object" data-ds-object>
 *     <header class="ds-page-head ds-page-head--sticky" data-ds-page-head>
 *       ... <h1 class="ds-page-head__title" id="obj-title" tabindex="-1">LAPTOP-0042</h1> ...
 *       <div class="ds-page-head__actions">
 *         <button class="ds-btn" type="button" data-ds-object-cancel hidden>Cancel</button>
 *         <button class="ds-btn ds-btn--filled" type="button" data-ds-object-save hidden>Save all</button>
 *         <button class="ds-btn ds-btn--filled" type="button" data-ds-object-edit>Edit</button>
 *       </div>
 *       <dl class="ds-page-head__details"> key facts </dl>
 *     </header>
 *     <nav class="ds-toc ds-toc--bar ds-toc--sticky" aria-label="Sections" data-ds-toc> links to the sections </nav>
 *     <section class="ds-card ds-object__section" id="general" aria-labelledby="general-title">
 *       <div class="ds-object__head">
 *         <h2 class="ds-object__title" id="general-title">General</h2>
 *         <button class="ds-btn ds-btn--text ds-sm ds-object__edit" type="button" data-ds-object-edit aria-describedby="general-title">Edit</button>
 *       </div>
 *       <div class="ds-object__view"> <dl class="ds-facts ds-facts--rows"> ... </dl> </div>
 *       <form class="ds-form ds-object__form" hidden> fields ...
 *         <div class="ds-form-actions"><button class="ds-btn" type="button" data-ds-object-cancel>Cancel</button><button class="ds-btn ds-btn--filled" type="submit">Save</button></div>
 *       </form>
 *     </section>
 *   </div>
 *
 * Layout: a column of --ds-object-gap (--ds-space-5). The head and the bar
 * stick one under the other: the module writes the head's height as
 * --ds-object-head and the bar's as --ds-object-bar on the .ds-object (runtime
 * properties: never set them), the bar sticks at --ds-object-head, and a
 * section's scroll-margin-top keeps its title clear of both when a jump
 * scrolls to it.
 *
 * Parts: .ds-object__section (a section, a .ds-card), .ds-object__head (its
 * title row: the title, the section's edit action at its end),
 * .ds-object__title (the title role), .ds-object__edit (the section's edit
 * action, a small text button, gone while the section edits), .ds-object__view
 * and .ds-object__form (the two faces; the module owns their hidden).
 *
 * State, written by the module: data-editing on a section that shows its
 * form, and on the .ds-object while every section does (edit mode).
 *
 * Options: size, density, shape and tone reach the controls and the cards
 * inside (each computes its own); the object page's own rhythm is layout.
 *
 * Hooks: --ds-object-gap (--ds-space-5: between the parts).
 *
 * Forced colours: the cards keep their edges; a section that edits shows its
 * form (the state is the form, never a colour).
 *
 * Print: the bar of anchors and the edit actions stay off the paper (the
 * head prints in place).
 */

@layer ds.components.object {
  .ds-object {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    gap: var(--ds-object-gap, var(--ds-space-5));
    align-content: start;
    min-width: 0;
  }

  /* The head carries no bottom margin of its own here: the gap is the rhythm. */
  .ds-object > .ds-page-head {
    margin-bottom: 0;
  }

  /* A condensed head keeps the room of what folded (page.css). */
  .ds-object > .ds-page-head[data-scrolled] {
    margin-bottom: var(--ds-page-head-fold, 0px);
  }

  /* The bar of anchors sticks under the head (its height, written by the
     module), on the same ground. */
  .ds-object > .ds-toc--bar.ds-toc--sticky {
    top: calc(var(--ds-page-head-top, 0px) + var(--ds-object-head, 0px));
  }

  /* A sticky head and the bar under it are one band: the bar takes the
     head's hairline, so the head drops its own. */
  .ds-object > .ds-page-head--sticky:has(+ .ds-toc--bar)::after {
    display: none;
  }

  /* The bar follows the head with no gap, so nothing shows between them. */
  .ds-object > .ds-page-head + .ds-toc--bar {
    margin-top: calc(-1 * var(--ds-object-gap, var(--ds-space-5)));
  }

  .ds-object__section {
    display: grid;
    gap: var(--ds-space-3);
    min-width: 0;
    /* A jump lands with the title clear of the head and the bar. */
    scroll-margin-top: calc(var(--ds-page-head-top, 0px) + var(--ds-object-head, 0px) + var(--ds-object-bar, 0px) + var(--ds-space-4));
  }

  .ds-object__head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--ds-space-3);
    min-width: 0;
  }

  .ds-object__title {
    margin: 0;
    color: var(--ds-text);
    font: var(--ds-font-title);
    overflow-wrap: anywhere;
  }

  /* The section's edit action: its text ends on the card's content edge
     (it hangs its padding into the gutter, as in a card's link row). */
  .ds-object__edit {
    flex: none;
    margin-inline-end: calc(-1 * var(--ds-space-3));
  }

  .ds-object__section[data-editing] .ds-object__edit,
  .ds-object__view[hidden],
  .ds-object__form[hidden] {
    display: none;
  }

  .ds-object__view,
  .ds-object__form {
    min-width: 0;
  }

  @media print {
    .ds-object > .ds-toc,
    .ds-object__edit {
      display: none;
    }
  }
}

/* ── components/terminal/terminal.css ── */
/*
 * Terminal frame: the chrome around a terminal emulator the page brings
 * (xterm.js or its own): a head with the title, the connection status and
 * the page's actions, the screen the emulator mounts into, and a key bar
 * with the keys a soft keyboard lacks. terminal.js renders the status and
 * the key bar; the emulator, the connection and what a key does are the
 * page's.
 *
 *   <div class="ds-terminal" data-ds-terminal data-ds-terminal-status="connected" aria-label="Shell on device 42">
 *     <div class="ds-terminal__head">
 *       <span class="ds-terminal__title">ada@device-42: ~</span>
 *       <span class="ds-terminal__actions"> the page's quiet icon buttons </span>
 *     </div>
 *     <div class="ds-terminal__screen"> the emulator mounts here </div>
 *   </div>
 *
 * What terminal.js renders (the page writes none of it):
 *   <span class="ds-status ds-terminal__status ds-tone-success" role="status">(plug)<span>Connected</span></span>
 *     before the actions; connecting: .ds-status--running with its spinner;
 *     disconnected: the neutral chip with a broken link
 *   <div class="ds-terminal__keys" role="toolbar" aria-label="Terminal keys">
 *     <button class="ds-btn ds-btn--outlined ds-terminal__key" data-ds-terminal-key="esc" tabindex="0">Esc</button>
 *     ... Ctrl and Alt with aria-pressed; the arrows .ds-btn--icon with an aria-label
 *   </div>
 *
 * The script writes on the frame data-bar ("auto", "always", "off") and
 * data-status (connecting, connected, disconnected). The key bar shows
 * with data-bar="always", and with "auto" (the default) under a coarse
 * pointer only: a phone or a tablet, where the soft keyboard has no Esc,
 * Tab, Ctrl or arrows.
 *
 * Variant:
 *   --fill    the frame takes its container's height and the screen the
 *             rest of it (a terminal page), instead of
 *             --ds-terminal-height
 *
 * Plain output: a page without an emulator (a replay, a read-only session)
 * writes a <pre> into the screen; spans with data-fg (black, red, green,
 * yellow, blue, magenta, cyan, white) take the ANSI colours and data-sgr
 * "bold" or "dim" the weight. DS.terminal.theme(el) reads the same colours
 * for an emulator (xterm.js's ITheme), so both show the theme's roles.
 *
 * Options (src/core/options.css, docs/options.md), on the frame or any
 * ancestor; each is computed here:
 *   size      .ds-xs ... .ds-xl: 8px per step on the head's height; the
 *             keys are buttons and follow their own rule; the screen keeps
 *             its type (--ds-terminal-font): the emulator sets its cells
 *   density   .ds-density-*: 4px per step off the head, 2px off the
 *             padding of the screen and the bar
 *   shape     .ds-shape-*: the frame's corners (the keys are pills by the
 *             button's rule)
 *   touch     .ds-touch: the keys reach the touch target (the button's
 *             rule); the head's actions are the page's buttons
 *   not tone: the status chip carries its own, always with its icon and
 *             word
 *
 * Narrow (the frame under 20rem, a container query): the status word
 * hides (the chip keeps its icon and is still read), the title ellipsizes,
 * the key bar scrolls sideways.
 *
 * Accessibility: the frame is a group named by its aria-label, else by
 * the title; the status chip is a polite live region; the key bar is a
 * toolbar with one tab stop (arrow keys, Home, End), whose keys never take
 * the focus from the screen; Ctrl and Alt are toggle buttons
 * (aria-pressed). The screen shows a focus ring while the emulator inside
 * has the focus.
 *
 * Forced colours: the frame and the head keep their lines (CanvasText);
 * the colours of the output go, the status keeps its icon and word, a
 * held modifier is Highlight (the button's toggle).
 *
 * Hooks: --ds-terminal-height (360px), --ds-terminal-bg (--ds-code-bg),
 * --ds-terminal-fg (--ds-text), --ds-terminal-cursor (--ds-primary),
 * --ds-terminal-selection (--ds-primary-container), --ds-terminal-radius
 * (--ds-radius-card), --ds-terminal-font (--ds-font-code) and the eight
 * ANSI colours --ds-terminal-black ... -white (defaults: roles).
 *
 * Motion: the status chip's colour glides (.ds-status); the keys press as
 * buttons; nothing else moves.
 *
 * Print: the head and the screen print; the key bar does not.
 *
 * Progressive:
 * - scrollbar-color and scrollbar-width (a thin scrollbar on the key bar):
 *   without them the platform scrollbar shows.
 */

@layer ds.components.terminal {
  .ds-terminal {
    --_bg: var(--ds-terminal-bg, var(--ds-code-bg));
    --_fg: var(--ds-terminal-fg, var(--ds-text));
    --_cursor: var(--ds-terminal-cursor, var(--ds-primary));
    --_selection: var(--ds-terminal-selection, var(--ds-primary-container));
    --_on-selection: var(--ds-on-primary-container);
    --_black: var(--ds-terminal-black, var(--ds-text-2));
    --_red: var(--ds-terminal-red, var(--ds-error));
    --_green: var(--ds-terminal-green, var(--ds-success));
    --_yellow: var(--ds-terminal-yellow, var(--ds-warning));
    --_blue: var(--ds-terminal-blue, var(--ds-primary));
    --_magenta: var(--ds-terminal-magenta, color-mix(in oklab, var(--ds-error) 50%, var(--ds-primary)));
    --_cyan: var(--ds-terminal-cyan, color-mix(in oklab, var(--ds-info) 50%, var(--ds-success)));
    --_white: var(--ds-terminal-white, var(--ds-text));
    --_radius: calc(var(--ds-terminal-radius, var(--ds-radius-card)) * var(--ds-shape, 1));
    container-type: inline-size;
    display: flex;
    flex-direction: column;
    min-inline-size: 0;
    border: 1px solid var(--ds-line);
    border-radius: var(--_radius);
    background: var(--_bg);
    color: var(--_fg);
    overflow: clip;
  }

  .ds-terminal--fill {
    block-size: 100%;
  }

  /* ── The head ────────────────────────────────────── */

  .ds-terminal__head {
    --_h: calc(48px + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px);
    display: flex;
    align-items: center;
    gap: var(--ds-space-2) var(--ds-space-3);
    min-block-size: var(--_h);
    padding-inline: var(--ds-space-4) var(--ds-space-2);
    border-block-end: 1px solid var(--ds-line);
    background: var(--ds-surface);
    color: var(--ds-text);
  }

  .ds-terminal__title {
    flex: 1 1 auto;
    min-inline-size: 0;
    overflow: hidden;
    font: var(--ds-terminal-font, var(--ds-font-code));
    font-weight: var(--ds-weight-label);
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .ds-terminal__status {
    flex: none;
  }

  .ds-terminal__actions {
    display: flex;
    flex: none;
    align-items: center;
    gap: var(--ds-space-1);
    margin-inline-start: auto;
  }

  .ds-terminal__title + .ds-terminal__actions,
  .ds-terminal__status + .ds-terminal__actions {
    margin-inline-start: 0;
  }

  /* ── The screen ──────────────────────────────────── */

  .ds-terminal__screen {
    position: relative;
    flex: 1 1 auto;
    block-size: var(--ds-terminal-height, 360px);
    min-block-size: 0;
    padding-block: calc(var(--ds-space-2) + var(--ds-density, 0) * 2px);
    padding-inline: var(--ds-space-3);
    overflow: hidden;
    background: var(--_bg);
    color: var(--_fg);
    font: var(--ds-terminal-font, var(--ds-font-code));
    caret-color: var(--_cursor);
    outline-offset: 0;
    transition: outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-terminal--fill > .ds-terminal__screen {
    flex: 1 1 0;
    block-size: auto;
  }

  /* The emulator inside has the focus (its own text area, or the screen itself). */
  .ds-terminal__screen:focus-visible,
  .ds-terminal__screen:has(:focus-visible) {
    outline: var(--ds-focus-outline);
    outline-offset: calc(-1 * var(--ds-focus-width));
  }

  .ds-terminal__screen ::selection {
    background: var(--_selection);
    color: var(--_on-selection);
  }

  /* Plain output: a <pre> the page writes, its spans coloured like ANSI. */
  .ds-terminal__screen > pre {
    block-size: 100%;
    margin: 0;
    overflow: auto;
    font: inherit;
    white-space: pre-wrap;
    overflow-wrap: anywhere;
  }

  .ds-terminal__screen [data-fg="black"] {
    color: var(--_black);
  }

  .ds-terminal__screen [data-fg="red"] {
    color: var(--_red);
  }

  .ds-terminal__screen [data-fg="green"] {
    color: var(--_green);
  }

  .ds-terminal__screen [data-fg="yellow"] {
    color: var(--_yellow);
  }

  .ds-terminal__screen [data-fg="blue"] {
    color: var(--_blue);
  }

  .ds-terminal__screen [data-fg="magenta"] {
    color: var(--_magenta);
  }

  .ds-terminal__screen [data-fg="cyan"] {
    color: var(--_cyan);
  }

  .ds-terminal__screen [data-fg="white"] {
    color: var(--_white);
  }

  .ds-terminal__screen [data-sgr~="bold"] {
    font-weight: var(--ds-weight-label);
  }

  .ds-terminal__screen [data-sgr~="dim"] {
    color: var(--ds-text-2);
  }

  /* What DS.terminal.theme() reads its colours with: no box, never seen. */
  .ds-terminal__probe {
    position: absolute;
    inline-size: 0;
    block-size: 0;
    overflow: hidden;
    pointer-events: none;
  }

  /* ── The key bar ─────────────────────────────────── */

  .ds-terminal__keys {
    position: relative;
    display: none;
    flex: none;
    align-items: center;
    gap: var(--ds-space-2);
    padding-block: calc(var(--ds-space-2) + var(--ds-density, 0) * 2px);
    padding-inline: var(--ds-space-3);
    overflow-x: auto;
    border-block-start: 1px solid var(--ds-line);
    background: var(--ds-surface);
    overscroll-behavior-x: contain;
    scrollbar-width: thin;
    scrollbar-color: var(--ds-line-2) transparent;
  }

  .ds-terminal[data-bar="always"] > .ds-terminal__keys {
    display: flex;
  }

  .ds-terminal__keys[hidden] {
    display: none;
  }

  .ds-terminal__key {
    flex: none;
  }

  /* Keys, not actions: a narrower side padding (the button's hook), so more fit on a phone. */
  .ds-terminal__key:not(.ds-btn--icon) {
    --ds-btn-padding-x: var(--ds-space-3);
  }

  @media (pointer: coarse) {
    .ds-terminal[data-bar="auto"] > .ds-terminal__keys {
      display: flex;
    }

    .ds-terminal[data-bar="auto"] > .ds-terminal__keys[hidden] {
      display: none;
    }
  }

  /* ── Narrow ──────────────────────────────────────── */

  @container (max-width: 20rem) {
    .ds-terminal__head {
      padding-inline-start: var(--ds-space-3);
    }

    /* The chip keeps its icon; its word is still read. */
    .ds-terminal__status > span:last-child {
      position: absolute;
      inline-size: 1px;
      block-size: 1px;
      overflow: hidden;
      clip-path: inset(50%);
      white-space: nowrap;
    }
  }

  @media (forced-colors: active) {
    .ds-terminal,
    .ds-terminal__head,
    .ds-terminal__keys {
      border-color: CanvasText;
    }
  }

  @media print {
    .ds-terminal__keys {
      display: none;
    }

    .ds-terminal__screen {
      block-size: auto;
    }
  }
}

/* ── components/shimmer/shimmer.css ── */
/*
 * Shimmer: "something is at work" on the text itself (an assistant's
 * "Thinking", a job's "Running npm test"): a soft glint that travels over
 * the words, left to right, a pass and a pause, and nothing else on the
 * line moves (plans/wheel-and-shimmer.md).
 *
 *   <span class="ds-shimmer" data-shimmer="Running npm test">Running npm test</span>
 *   <span class="ds-wheel__line ds-shimmer" data-shimmer="Thinking">Thinking</span>   a wheel line (wheel.css)
 *
 * data-shimmer is the text as it reads (the same words and spaces), in one
 * weight (a bold word in a regular line is wider than its copy). The wave
 * is a copy of the text on top (::after), in the line's own type, so it
 * lies on the letters and is cut with the same ellipsis.
 * The copy's alternative text is empty (content: attr() / ""), so the
 * accessible name stays the text's own.
 *
 * Look: the copy in --ds-shimmer-glint (white in every theme: over dark
 * text a faint sheen passing, over light text in the dark theme a soft
 * glint), shown through a horizontal mask only in a soft band: transparent
 * to 32%, --ds-shimmer-peak at 50% (its alpha is the glint's strength at
 * the crest: 55% of the text, a sheen in the background, never wiping the
 * words out), transparent from 68% of a tile --ds-shimmer-length (480px)
 * long, repeated along the line.
 *
 * Motion: the tile travels one --ds-shimmer-length per --ds-loop-shimmer
 * (4.55s, the shape loader's round; until the token lands it runs on
 * --ds-loop-loader, the same value), linear, on the progress wave's
 * keyframe (ds-progress-wave, which moves the mask by
 * --ds-progress-wave-length, set here to the tile): about 105px/s, so a
 * short text sees one slow pass and a pause. The mask is the only repaint.
 * Remove the class (or data-shimmer) when the work ends: the glint goes at
 * once, the text stays.
 *
 * Options: none. It takes the type and colour of its text; size, density,
 * shape and tone have nothing to act on.
 *
 * Hooks: --ds-shimmer-length (480px, one tile: the band and the pause after
 * it). Roles (tokens.css; a theme sets them): --ds-shimmer-glint (white;
 * the text colour under themes/contrast.css), --ds-shimmer-peak (the text
 * at 55%; transparent under themes/contrast.css, so no glint).
 *
 * Forced colours: the copy is left out (content: none); the text stays.
 */

@layer ds.components.shimmer {
  .ds-shimmer {
    position: relative;
    display: inline-block;
    min-width: 0;
    max-width: 100%;
    vertical-align: bottom;
    overflow: hidden;
    white-space: nowrap;
    text-overflow: ellipsis;
  }

  .ds-shimmer[data-shimmer]::after {
    --ds-progress-wave-length: var(--ds-shimmer-length, 480px);
    content: attr(data-shimmer) / "";
    position: absolute;
    inset: 0;
    overflow: hidden;
    white-space: nowrap;
    text-overflow: ellipsis;
    color: var(--ds-shimmer-glint);
    pointer-events: none;
    mask-image: linear-gradient(90deg, transparent 0 32%, var(--ds-shimmer-peak) 50%, transparent 68% 100%);
    mask-size: var(--ds-shimmer-length, 480px) 100%;
    mask-repeat: repeat-x;
    animation: ds-progress-wave var(--ds-loop-loader) linear infinite;
  }

  @media (forced-colors: active) {
    .ds-shimmer[data-shimmer]::after {
      content: none;
    }
  }
}

/* ── components/wheel/wheel.css ── */
/*
 * Wheel: a live status line whose text changes often ("Thinking", "Running
 * npm test", "Writing"), readable at every step and quiet enough to stay in
 * the background (plans/wheel-and-shimmer.md). A new line pushes the old
 * one out, like the drum of a counter.
 *
 *   <span class="ds-wheel">
 *     <span class="ds-wheel__line" data-ds-key="Thinking">Thinking</span>
 *   </span>
 *
 *   DS.dom.morphHtml(container, markup, DS.wheel.hooks);   a new key rolls in
 *   DS.wheel.roll(slot, 'Running npm test');                without a morph
 *   <span class="ds-wheel" data-ds-wheel="Thinking"></span>  DS.init(): a change of the attribute rolls
 *
 * Every line is keyed by what it says: drawn with DS.dom.morphHtml() and
 * DS.wheel.hooks, a new text is a new key, so the morph inserts a line and
 * removes the old one, and the hooks turn them. The same key with other
 * children (a figure that ticks inside the line) is patched in place and
 * does not roll. A line may also be a .ds-shimmer (shimmer.css).
 *
 * The slot is one grid cell (like .ds-swap) with a soft edge: --ds-wheel-fade
 * of room above and below, given back by a negative margin, and a static
 * vertical mask (nothing in the mask animates). Each line is as wide as its
 * text, capped at the slot, and cut with an ellipsis.
 *
 * Motion (wheel.js, el.animate(), so an exit starts from wherever an
 * interrupted entrance is): both lines glide together, one line apart
 * (--ds-wheel-travel, 100%: a line's own height), on --ds-dur-slow and
 * --ds-ease-in-out: the old line up and out through the top edge, the new
 * one up from below. Each line's opacity runs on its glide's curve, so a
 * line is only as visible as it is inside the slot. Only translate and
 * opacity, on the standard curve: never 3D, never a blur. Every line shows for at least
 * --ds-hold-status; a quick run of changes rolls once, to the last. A slot
 * that is new shows its line at once.
 *
 * Options: none of its own. It takes the type, colour and line height of
 * where it sits (a status row, a summary), so size and density reach it
 * through its host; shape and tone have nothing to act on.
 *
 * Hooks: --ds-wheel-travel (100%, how far a line glides as it goes or
 * comes; wheel.js reads it through --_travel), --ds-wheel-fade
 * (--ds-space-3, the soft edge above and below).
 *
 * Accessibility: the leaving line is aria-hidden and inert. The slot is no
 * live region of its own: a page that wants the changes announced puts it
 * in one (aria-live="polite") and keeps ticking figures out of it.
 *
 * Forced colours: nothing of its own; the mask is a shape, so it stays.
 */

@layer ds.components.wheel {
  .ds-wheel {
    --_fade: var(--ds-wheel-fade, var(--ds-space-3));
    /* What wheel.js reads: the hook, or one line's own height. */
    --_travel: var(--ds-wheel-travel, 100%);
    display: inline-grid;
    grid-template-columns: minmax(0, 1fr);
    min-width: 0;
    max-width: 100%;
    vertical-align: bottom;
    padding-block: var(--_fade);
    margin-block: calc(-1 * var(--_fade));
    mask-image: linear-gradient(to bottom, transparent, #000 var(--_fade), #000 calc(100% - var(--_fade)), transparent);
  }

  /* Every child is a line: the page's own lines in a morph need no class. */
  .ds-wheel > *,
  .ds-wheel__line {
    grid-area: 1 / 1;
    justify-self: start;
    min-width: 0;
    max-width: 100%;
    overflow: hidden;
    white-space: nowrap;
    text-overflow: ellipsis;
  }
}

/* ── components/thinking/thinking.css ── */
/*
 * Thinking indicator: what an assistant or an agent is doing right now,
 * while it works: the step it is on (a wheel line with the shimmer), the
 * thought it has, how long it has been at it and how many tokens it used.
 *
 *   <div class="ds-thinking" data-ds-thinking="Reading the device list"
 *        data-ds-thinking-since="2026-11-05T09:00:00Z" data-ds-thinking-tokens="1240">
 *     <span class="ds-thinking__icon">[icon sparkle 20]</span>
 *     <span class="ds-thinking__step" aria-live="polite"><span class="ds-wheel"></span></span>
 *     <span class="ds-thinking__meta"><time class="ds-thinking__time"></time><span class="ds-thinking__tokens"></span></span>
 *     <p class="ds-thinking__thought">Comparing the warranty dates of 40 devices</p>
 *   </div>
 *
 * Parts:
 *   __icon     optional, a glyph before the step (aria-hidden by the module)
 *   __step     the step: a .ds-wheel the module rolls (wheel.css), its line a
 *              .ds-shimmer while it works (shimmer.css); a polite live region,
 *              so a new step is spoken once and nothing else is
 *   __meta     the elapsed time (__time) and the tokens (__tokens), quiet,
 *              tabular, joined by a dot; they tick outside the live region
 *   __thought  optional, the current thought: two lines at most, cut with
 *              an ellipsis
 *
 * State: data-ds-thinking-done (or set({ done: true })) ends it: the time
 * stops, the shimmer goes, and data-state="done" is written. The module
 * (thinking.js) writes the time, the tokens and the step; the page writes
 * the thought, or set({ thought }).
 *
 * Layout: the step with the meta right after it, the thought under them.
 * The icon hangs in the start padding, centred on the first line, so what
 * wraps lines up with the step. When step and meta do not fit on a line,
 * the meta wraps under the step (a narrow column, a phone).
 *
 * Options (src/core/options.css, docs/options.md), on the block or any
 * ancestor:
 *   size      .ds-xs ... .ds-xl: the step's type (--ds-size-font) and the
 *             icon, 4px per step; meta and thought keep their roles
 *   density   .ds-density-*: the gaps, 2px per step
 *   shape, tone, touch: not read; it is no target and shows no meaning of
 *             its own (an error is the message's, not the indicator's)
 *
 * Hooks: --ds-thinking-font (the step's type, default --ds-size-font, else
 * --ds-font-label), --ds-thinking-gap (--ds-space-2, the base the density
 * applies to), --ds-thinking-icon-color (--ds-primary).
 *
 * Motion: the wheel's turn and the shimmer's travel (their own files);
 * nothing else moves. The time and the token count change in place.
 *
 * Forced colours: the icon takes CanvasText; the shimmer's copy goes
 * (shimmer.css), the text stays.
 */

@layer ds.components.thinking {
  .ds-thinking {
    --_gap: max(0px, calc(var(--ds-thinking-gap, var(--ds-space-2)) + var(--ds-density, 0) * 2px));
    --_icon: calc(20px + var(--ds-size-step, 0) * 4px);
    position: relative;
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    column-gap: var(--_gap);
    row-gap: calc(var(--_gap) / 2);
    min-width: 0;
    color: var(--ds-text);
  }

  /* The icon hangs in the start padding, centred on the step's first line,
     so whatever wraps lines up with the step. */
  .ds-thinking:has(> .ds-thinking__icon) {
    padding-inline-start: calc(var(--_icon) + var(--_gap));
  }

  .ds-thinking__icon {
    position: absolute;
    inset-block-start: calc((1lh - var(--_icon)) / 2);
    inset-inline-start: 0;
    display: flex;
    color: var(--ds-thinking-icon-color, var(--ds-primary));
    font: var(--ds-thinking-font, var(--ds-size-font, var(--ds-font-label)));
  }

  .ds-thinking__icon > svg {
    width: var(--_icon);
    height: var(--_icon);
  }

  /* The meta follows the step; when both do not fit, the meta wraps under
     it and a long step is cut on its own line. */
  .ds-thinking__step {
    display: flex;
    flex: 0 1 auto;
    min-width: 0;
    font: var(--ds-thinking-font, var(--ds-size-font, var(--ds-font-label)));
  }

  .ds-thinking__meta {
    display: flex;
    flex: none;
    align-items: baseline;
    gap: var(--ds-space-1);
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
  }

  /* The dot between time and tokens, only when both show. */
  .ds-thinking__time:not(:empty) ~ .ds-thinking__tokens:not(:empty)::before {
    content: "\00b7" / "";
    margin-inline-end: var(--ds-space-1);
  }

  .ds-thinking__time:empty,
  .ds-thinking__tokens:empty {
    display: none;
  }

  .ds-thinking__thought {
    display: -webkit-box;
    flex: 1 0 100%;
    min-width: 0;
    margin: 0;
    overflow: hidden;
    color: var(--ds-text-2);
    font: var(--ds-font-body);
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 2;
    line-clamp: 2;
    overflow-wrap: anywhere;
  }

  .ds-thinking__thought:empty {
    display: none;
  }

  @media (forced-colors: active) {
    .ds-thinking__icon {
      color: CanvasText;
    }
  }
}

/* ── components/toolcall/toolcall.css ── */
/*
 * Tool call: one call an assistant or agent made (a command, a search, an
 * API), as a row that opens: its name and arguments, its status with a
 * word, how long it took; opened, its input, its output and the calls it
 * made itself. Built on the disclosure row (disclosure.css): the summary
 * presses like a row, the body opens as a .ds-collapsible.
 *
 *   <details class="ds-collapsible ds-disclosure ds-disclosure--row ds-toolcall" data-status="running"
 *            data-ds-toolcall data-ds-toolcall-since="2026-11-05T09:00:00Z">
 *     <summary>
 *       <span class="ds-toolcall__icon">[icon terminal 20]</span>
 *       <span class="ds-disclosure__title ds-toolcall__title">
 *         <span class="ds-toolcall__name">run_tests</span> <span class="ds-toolcall__args">npm test -- devices</span></span>
 *       <span class="ds-toolcall__status"><span class="ds-toolcall__mark"><span class="ds-spinner"></span></span><span class="ds-toolcall__word">Running</span></span>
 *       <time class="ds-toolcall__time"></time>
 *       [icon chevronDown 20 .ds-chevron]
 *     </summary>
 *     <div class="ds-disclosure__body ds-toolcall__body">
 *       <div class="ds-toolcall__part"><p class="ds-toolcall__label">Input</p>
 *         <pre class="ds-toolcall__code" tabindex="0" aria-label="Input"><code>{ "script": "test" }</code></pre></div>
 *       <div class="ds-toolcall__part ds-toolcall__part--error"><p class="ds-toolcall__label">Output</p>
 *         <pre class="ds-toolcall__code" tabindex="0" aria-label="Output">...</pre></div>
 *       <div class="ds-toolcall__calls"> (nested .ds-toolcall rows) </div>
 *     </div>
 *   </details>
 *
 * Status (data-status on the row, with an icon and a word, never colour
 * alone): pending (an hourglass, waiting to run or for approval), running (the
 * spinner), done (a check in a circle, --ds-success), failed (the alert
 * circle and the word in --ds-error), cancelled (a ban). toolcall.js
 * writes the mark for set({ status }); a page that renders the row writes
 * it in its markup.
 *
 * Parts: __icon (the tool's glyph), __name (in the code type), __args (a
 * quiet one-line summary of the arguments, cut with an ellipsis), __time
 * (the duration, tabular), __part with a __label and a __code block (the
 * code type, scrolling past --ds-toolcall-code-max-height; give it
 * tabindex="0" and a name so the keyboard can scroll it; a code block of the
 * system may stand in its place), __part--error (an output that failed:
 * its label and edge in --ds-error), __calls (the calls this one made:
 * rows on a rail, without a frame of their own).
 *
 * The frame: a hairline at --ds-toolcall-radius (--ds-radius-card) times
 * --ds-shape, clipping the row's state layer at its corners. Rows in a
 * .ds-toolcall-list stack with --ds-space-2 between them.
 *
 * Options (src/core/options.css, docs/options.md), on the row or any
 * ancestor; computed here and in the disclosure row:
 *   size      .ds-xs ... .ds-xl: the summary's height (8px per step, the
 *             disclosure row's own steps) and its type; the code keeps its
 *             role
 *   density   .ds-density-*: the summary's height (4px per step) and the
 *             room of the body, 2px per step
 *   shape     the frame's and the code's radius times --ds-shape
 *   touch     .ds-touch: the summary is at least --ds-touch-target high
 *   tone      not read: the status shows the meaning, with its word
 *
 * Hooks: --ds-toolcall-height (40px, the summary's base height),
 * --ds-toolcall-radius (--ds-radius-card), --ds-toolcall-code-max-height
 * (240px), --ds-toolcall-code-bg (--ds-surface-low).
 *
 * Motion: the disclosure's (the body opens as a .ds-collapsible, the
 * chevron turns); a status that changes swaps its mark at once.
 *
 * Forced colours: the frame and the code's edge stay (borders); the marks
 * and the icon take CanvasText, and every status keeps its word; the
 * spinner takes its system colours (spinner.css).
 *
 * Progressive:
 * - scrollbar-color and scrollbar-width (a thin, quiet scrollbar on the
 *   code): without them the platform scrollbar shows.
 */

@layer ds.components.toolcall {
  .ds-toolcall {
    --_radius: calc(var(--ds-toolcall-radius, var(--ds-radius-card)) * var(--ds-shape, 1));
    --_room: max(0px, calc(var(--ds-space-3) + var(--ds-density, 0) * 2px));
    --ds-disclosure-row-height: var(--ds-toolcall-height, 40px);
    --ds-disclosure-row-padding: var(--ds-space-3);
    container-type: inline-size;
    display: block;
    min-width: 0;
    border: 1px solid var(--ds-line);
    border-radius: var(--_radius);
    background: var(--ds-surface);
    overflow: clip;
  }

  .ds-toolcall-list {
    display: grid;
    gap: var(--ds-space-2);
    min-width: 0;
  }

  /* Room above and below the line is the height's: a small row is as low
     as its steps say. */
  .ds-toolcall > summary {
    gap: var(--ds-space-2);
    padding-block: var(--ds-space-1);
    font: var(--ds-size-font, var(--ds-font-label));
  }

  .ds-toolcall__icon {
    display: inline-flex;
    flex: none;
    color: var(--ds-text-2);
  }

  .ds-toolcall__title {
    display: flex;
    align-items: baseline;
    gap: var(--ds-space-2);
    overflow: hidden;
    white-space: nowrap;
    overflow-wrap: normal;
  }

  .ds-toolcall__name {
    flex: none;
    max-width: 100%;
    overflow: hidden;
    text-overflow: ellipsis;
    font: var(--ds-font-code);
    font-weight: var(--ds-weight-label);
  }

  .ds-toolcall__args {
    flex: 0 1 auto;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    color: var(--ds-text-2);
    font: var(--ds-font-code);
  }

  .ds-toolcall__status {
    display: inline-flex;
    flex: none;
    align-items: center;
    gap: var(--ds-space-1);
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
  }

  .ds-toolcall__mark {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 16px;
    height: 16px;
  }

  .ds-toolcall__mark > svg {
    width: 16px;
    height: 16px;
  }

  /* The word stays whole: with the mark it is the status. */
  .ds-toolcall__word {
    white-space: nowrap;
  }

  .ds-toolcall[data-status="done"] > summary .ds-toolcall__mark {
    color: var(--ds-success);
  }

  .ds-toolcall[data-status="failed"] > summary .ds-toolcall__status {
    color: var(--ds-error);
  }

  .ds-toolcall__time {
    flex: none;
    min-width: 3ch;
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
    font-variant-numeric: tabular-nums;
    text-align: end;
  }

  .ds-toolcall__time:empty {
    display: none;
  }

  /* A narrow row (each row is its own container) lets the time go; the
     arguments are cut shorter. */
  @container (max-width: 359.98px) {
    .ds-toolcall__time {
      display: none;
    }
  }

  .ds-toolcall__body {
    display: grid;
    gap: var(--_room);
    min-width: 0;
  }

  .ds-toolcall > .ds-toolcall__body {
    padding-top: var(--ds-space-1);
  }

  .ds-toolcall__part {
    display: grid;
    gap: var(--ds-space-1);
    min-width: 0;
  }

  .ds-toolcall__label {
    margin: 0;
    color: var(--ds-text-2);
    font: var(--ds-font-caption);
  }

  .ds-toolcall__code {
    position: relative;
    max-height: var(--ds-toolcall-code-max-height, 240px);
    margin: 0;
    padding: var(--ds-space-2) var(--ds-space-3);
    overflow: auto;
    border: 1px solid var(--ds-line);
    border-radius: calc(var(--ds-radius-sm) * var(--ds-shape, 1));
    background: var(--ds-toolcall-code-bg, var(--ds-surface-low));
    color: var(--ds-text);
    font: var(--ds-font-code);
    white-space: pre;
    tab-size: 2;
    scrollbar-width: thin;
    scrollbar-color: var(--ds-line-2) transparent;
    outline-offset: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    transition: outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-toolcall__code:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: var(--ds-focus-offset);
  }

  /* A closed call holds no ring: the snap back of a ring that left as the
     call closed would never end in Firefox, which does not run transitions
     in the hidden content of a closed <details>. */
  .ds-toolcall:not([open]) .ds-toolcall__code {
    transition: none;
  }

  .ds-toolcall__part--error > .ds-toolcall__label {
    color: var(--ds-error);
  }

  .ds-toolcall__part--error > .ds-toolcall__code {
    border-color: var(--ds-error);
  }

  /* Nested calls: rows on a rail under the icon, no frame of their own. */
  .ds-toolcall__calls {
    display: grid;
    min-width: 0;
    margin-inline-start: calc(var(--ds-space-3) + 9px);
    border-inline-start: 2px solid var(--ds-line);
  }

  .ds-toolcall__calls > .ds-toolcall {
    --ds-disclosure-row-padding: var(--ds-space-2);
    border: 0;
    border-radius: 0;
    background: transparent;
  }

  .ds-toolcall__calls > .ds-toolcall > .ds-toolcall__body {
    padding-inline-start: calc(var(--ds-space-2) + var(--ds-space-3));
  }

  @media (forced-colors: active) {
    .ds-toolcall__icon,
    .ds-toolcall__mark,
    .ds-toolcall[data-status] > summary .ds-toolcall__mark {
      color: CanvasText;
    }
  }
}

/* ── components/reasoning/reasoning.css ── */
/*
 * Reasoning disclosure: an assistant's thinking, collapsed under a summary
 * line ("Thinking" while it runs, "Thought for 12s" or the page's own
 * summary when done), the thoughts a press away. Built on the plain
 * disclosure (disclosure.css): the summary presses like a pill, the body
 * opens as a .ds-collapsible.
 *
 *   <details class="ds-collapsible ds-disclosure ds-reasoning" data-ds-reasoning
 *            data-ds-reasoning-since="2026-11-05T09:00:00Z" data-ds-reasoning-auto>
 *     <summary>
 *       <span class="ds-reasoning__icon">[icon sparkle 18]</span>
 *       <span class="ds-reasoning__summary"></span> <time class="ds-reasoning__time"></time>
 *       [icon chevronDown 20 .ds-chevron]
 *     </summary>
 *     <div class="ds-disclosure__body ds-reasoning__body">
 *       <div class="ds-reasoning__text" tabindex="0" aria-label="Thoughts"><p>...</p><p>...</p></div>
 *     </div>
 *   </details>
 *
 * Parts: __icon (optional, quiet), __summary (the line: reasoning.js writes
 * "Thinking" with the shimmer while it runs and "Thought for {time}" at the
 * end, unless the page wrote its own), __time (optional: the time while it
 * runs, the total beside a summary of the page's own), __body (on the
 * .ds-disclosure__body: the rail), __text (the thoughts: quiet body type on
 * a rail, scrolling past --ds-reasoning-max-height; while it runs it stays
 * at its end, DS.dom.followEnd()).
 *
 * State: data-state="running" or "done", written by the module from
 * data-ds-reasoning-done (or set({ done })).
 *
 * Options (src/core/options.css, docs/options.md), on it or any ancestor;
 * the summary's are the plain disclosure's (size: 8px of height per step
 * and its type; density: 4px; shape: its radius; touch: its target):
 *   density   .ds-density-*: the room above the thoughts, 2px per step
 *   tone      not read: it shows no meaning
 *
 * Hooks: --ds-reasoning-max-height (320px), --ds-reasoning-rail
 * (--ds-line, the rail's colour).
 *
 * Motion: the disclosure's (the body opens as a .ds-collapsible, the
 * chevron turns), the shimmer on the running summary; with
 * data-ds-reasoning-auto it opens when it starts and closes when it ends,
 * unless the reader toggled it.
 *
 * Forced colours: the rail stays (a border); the summary keeps its words,
 * the shimmer's copy goes.
 *
 * Progressive:
 * - scrollbar-color and scrollbar-width (a thin, quiet scrollbar on the
 *   thoughts): without them the platform scrollbar shows.
 */

@layer ds.components.reasoning {
  .ds-reasoning > summary {
    color: var(--ds-text-2);
  }

  .ds-reasoning__icon {
    display: inline-flex;
    flex: none;
  }

  .ds-reasoning__summary {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .ds-reasoning__time {
    flex: none;
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
    font-variant-numeric: tabular-nums;
  }

  .ds-reasoning__time:empty {
    display: none;
  }

  .ds-reasoning__body {
    min-width: 0;
    padding-top: max(0px, calc(var(--ds-space-2) + var(--ds-density, 0) * 2px));
  }

  .ds-reasoning__text {
    position: relative;
    max-height: var(--ds-reasoning-max-height, 320px);
    margin-inline-start: var(--ds-space-2);
    padding-inline: var(--ds-space-3) var(--ds-space-2);
    overflow-y: auto;
    border-inline-start: 2px solid var(--ds-reasoning-rail, var(--ds-line));
    color: var(--ds-text-2);
    font: var(--ds-font-body);
    overflow-wrap: anywhere;
    scrollbar-width: thin;
    scrollbar-color: var(--ds-line-2) transparent;
    outline-offset: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    transition: outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-reasoning__text:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: var(--ds-focus-offset);
  }

  .ds-reasoning__text > * {
    margin-block: 0 var(--ds-space-2);
  }

  .ds-reasoning__text > :last-child {
    margin-block-end: 0;
  }
}

/* ── components/cite/cite.css ── */
/*
 * Sources and citations: numbered markers in an answer's text that open a
 * card with their source, and the list of every source under it.
 *
 *   <p>Eleven laptops leave warranty before March<button class="ds-cite" type="button"
 *      aria-controls="src-1-card" aria-label="Source 1: Warranty register" data-ds-cite>1</button>.</p>
 *
 *   <div class="ds-cite__card" id="src-1-card" popover="manual" hidden>
 *     <p class="ds-cite__source"><img class="ds-cite__icon" src="..." alt="">example.com</p>
 *     <a class="ds-cite__title" href="https://example.com/warranty">Warranty register 2026</a>
 *     <p class="ds-cite__snippet">The warranty of LAPTOP-0042 ends on 28 February 2027 ...</p>
 *   </div>
 *
 *   <ol class="ds-cite-list" aria-label="Sources">
 *     <li class="ds-cite-list__item" id="src-1">
 *       <span class="ds-cite-list__number">1</span>
 *       <span class="ds-cite-list__body"><a class="ds-cite__title" href="...">Warranty register 2026</a>
 *         <span class="ds-cite__source">example.com</span></span>
 *     </li>
 *   </ol>
 *
 * The marker (.ds-cite): a small pill with the number in the caption type,
 * tabular, on --ds-cite-bg (--ds-surface-high) in --ds-text-2, a little
 * raised from the baseline. Its hit area reaches at least 24px (and
 * --ds-target-min under .ds-touch) through ::after, without moving the
 * line. Hover lays --ds-state-hover of its colour over it (::before),
 * the press --ds-state-pressed in --ds-dur-micro; open (aria-expanded,
 * which cite.js writes) it turns --ds-accent / --ds-on-accent. Keyboard
 * focus: the ring, solid from the first frame, snapping in from offset +
 * width. Like a text link it has no ripple and no press morph.
 *
 * The card (.ds-cite__card): a popup in the top layer (popover="manual"),
 * opened and closed through DS.overlay, placed under the marker (above it
 * without room; --ds-cite-x and --ds-cite-y, written by cite.js), at most
 * --ds-cite-card-width wide: the source (__source: an optional 16px
 * __icon, a favicon or a glyph, and the site in the meta type), the title
 * (__title, a link in the label type), an optional snippet (__snippet,
 * three lines at most) and anything else the page adds.
 *
 * The list (.ds-cite-list): the sources in order, each a __number (the
 * same pill as the marker) and a __body with the title and the source.
 *
 * Options (src/core/options.css, docs/options.md):
 *   size      .ds-xs ... .ds-xl: the marker, 2px per step (18px at md);
 *             its type stays the caption
 *   density   the list's rows, 2px of room per step
 *   shape     the marker's and the card's corners times --ds-shape (the
 *             marker stays a pill at the default)
 *   touch     .ds-touch: the marker's hit area is --ds-target-min
 *   tone      not read: a source shows no meaning
 *
 * Hooks: --ds-cite-size (18px, the marker's md height), --ds-cite-bg
 * (--ds-surface-high), --ds-cite-card-width (320px), --ds-cite-card-radius
 * (--ds-radius-card).
 *
 * Motion: the card's entrance and exit are the popups' (transitions keyed
 * on data-state by DS.overlay): it fades in on --ds-dur-fast and grows
 * from --ds-scale-popup at the marker on the spring (--ds-dur-medium),
 * and fades out in --ds-dur-instant. The marker's layers fade on
 * --ds-dur-fast.
 *
 * Forced colours: the marker keeps a CanvasText edge (open: Highlight,
 * HighlightText), the card its transparent outline as its edge.
 */

@layer ds.components.cite {
  .ds-cite {
    --_h: max(14px, calc(var(--ds-cite-size, 18px) + var(--ds-size-step, 0) * 2px));
    --_reach: max(0px, calc((max(24px, var(--ds-target-min, 0px)) - var(--_h)) / 2));
    position: relative;
    isolation: isolate;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    box-sizing: border-box;
    min-width: var(--_h);
    height: var(--_h);
    margin: 0;
    margin-inline-start: var(--ds-space-1);
    padding: 0 var(--ds-space-1);
    border: 1px solid transparent;
    border-radius: min(calc(var(--ds-radius-action) * var(--ds-shape, 1)), calc(var(--_h) / 2));
    background: var(--ds-cite-bg, var(--ds-surface-high));
    color: var(--ds-text-2);
    font: var(--ds-font-caption);
    font-variant-numeric: tabular-nums;
    line-height: 1;
    vertical-align: .15em;
    cursor: pointer;
    -webkit-tap-highlight-color: transparent;
    outline-offset: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    transition:
      background-color var(--ds-dur-fast) var(--ds-ease-in-out),
      color var(--ds-dur-fast) var(--ds-ease-in-out),
      outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  /* The state layer. */
  .ds-cite::before {
    content: "";
    position: absolute;
    inset: -1px;
    z-index: -1;
    border-radius: inherit;
    background: currentColor;
    opacity: 0;
    pointer-events: none;
    transition: opacity var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  /* The hit area: at least 24px (the touch target under .ds-touch). */
  .ds-cite::after {
    content: "";
    position: absolute;
    inset: calc(-1 * var(--_reach));
  }

  @media (hover: hover) {
    .ds-cite:hover::before {
      opacity: var(--ds-state-hover);
    }
  }

  .ds-cite:focus-visible::before {
    opacity: var(--ds-state-focus);
    transition-duration: 0s;
  }

  .ds-cite:active::before {
    opacity: var(--ds-state-pressed);
    transition-duration: var(--ds-dur-micro);
  }

  .ds-cite:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: var(--ds-focus-offset);
  }

  .ds-cite[aria-expanded="true"] {
    background: var(--ds-accent);
    color: var(--ds-on-accent);
  }

  /* The card: a popup in the top layer. */
  .ds-cite__card {
    position: fixed;
    inset: var(--ds-cite-y, 0px) auto auto var(--ds-cite-x, 0px);
    z-index: var(--ds-z-popover);
    display: grid;
    gap: var(--ds-space-1);
    box-sizing: border-box;
    width: max-content;
    max-width: min(var(--ds-cite-card-width, 320px), calc(100vw - 2 * var(--ds-space-2)));
    max-height: calc(100vh - 2 * var(--ds-space-2));
    margin: 0;
    padding: var(--ds-space-3) var(--ds-space-4);
    overflow-y: auto;
    border: 0;
    border-radius: calc(var(--ds-cite-card-radius, var(--ds-radius-card)) * var(--ds-shape, 1));
    background: var(--ds-surface-popover);
    color: var(--ds-text);
    box-shadow: var(--ds-elev-popover);
    font: var(--ds-font-body);
    /* Invisible; forced colours paint it, so the card keeps an edge. */
    outline: 1px solid transparent;
    transform-origin: var(--ds-motion-origin, 50% 0%);
  }

  .ds-cite__card[data-placement="top"] {
    transform-origin: var(--ds-motion-origin, 50% 100%);
  }

  .ds-cite__card[hidden] {
    display: none;
  }

  /* Driven by DS.overlay: transitions keyed on data-state, so a card closed
     mid-way turns back from where it is. */
  .ds-cite__card[data-state] {
    transition:
      opacity var(--ds-dur-fast) var(--ds-ease-in-out),
      scale var(--ds-dur-medium) var(--ds-ease-spatial);
  }

  /* The exit only fades, in --ds-dur-instant; the scale goes back once the
     card is invisible. Closed, it takes no pointer. */
  .ds-cite__card[data-state="closed"] {
    opacity: 0;
    scale: var(--ds-scale-popup);
    pointer-events: none;
    transition:
      opacity var(--ds-dur-instant) var(--ds-ease-in-out),
      scale 0ms var(--ds-ease-in-out) var(--ds-dur-instant);
  }

  .ds-cite__card > * {
    margin: 0;
  }

  .ds-cite__source {
    display: flex;
    align-items: center;
    gap: var(--ds-space-2);
    min-width: 0;
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
    overflow-wrap: anywhere;
  }

  .ds-cite__icon {
    flex: none;
    width: 16px;
    height: 16px;
    border-radius: calc(var(--ds-radius-xs) * var(--ds-shape, 1));
  }

  .ds-cite__title {
    color: var(--ds-link);
    font: var(--ds-font-label);
    text-decoration-line: underline;
    text-decoration-color: var(--ds-link-underline);
    text-decoration-thickness: var(--ds-link-underline-thickness);
    text-underline-offset: var(--ds-link-underline-offset);
    overflow-wrap: anywhere;
    border-radius: calc(var(--ds-radius-xs) * var(--ds-shape, 1));
    outline-offset: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    transition:
      text-decoration-color var(--ds-dur-fast) var(--ds-ease-in-out),
      outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  @media (hover: hover) {
    .ds-cite__title:hover {
      text-decoration-color: var(--ds-link-underline-hover);
    }
  }

  .ds-cite__title:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: var(--ds-focus-offset);
  }

  .ds-cite__snippet {
    display: -webkit-box;
    overflow: hidden;
    color: var(--ds-text-2);
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 3;
    line-clamp: 3;
  }

  /* The list of sources. */
  .ds-cite-list {
    --_room: max(0px, calc(var(--ds-space-2) + var(--ds-density, 0) * 2px));
    display: grid;
    gap: var(--_room);
    min-width: 0;
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .ds-cite-list__item {
    display: flex;
    align-items: baseline;
    gap: var(--ds-space-2);
    min-width: 0;
  }

  .ds-cite-list__number {
    --_h: max(14px, calc(var(--ds-cite-size, 18px) + var(--ds-size-step, 0) * 2px));
    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    box-sizing: border-box;
    min-width: var(--_h);
    height: var(--_h);
    padding: 0 var(--ds-space-1);
    border: 1px solid transparent;
    border-radius: min(calc(var(--ds-radius-action) * var(--ds-shape, 1)), calc(var(--_h) / 2));
    background: var(--ds-cite-bg, var(--ds-surface-high));
    color: var(--ds-text-2);
    font: var(--ds-font-caption);
    font-variant-numeric: tabular-nums;
    line-height: 1;
  }

  .ds-cite-list__body {
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    column-gap: var(--ds-space-2);
    min-width: 0;
  }

  @media (forced-colors: active) {
    .ds-cite,
    .ds-cite-list__number {
      border-color: CanvasText;
    }

    .ds-cite::before {
      display: none;
    }

    .ds-cite[aria-expanded="true"] {
      forced-color-adjust: none;
      border-color: Highlight;
      background: Highlight;
      color: HighlightText;
    }
  }
}

/* ── components/plan/plan.css ── */
/*
 * Plan card: a plan an assistant or agent proposes before it acts, its
 * steps, and the person's decision (approve or reject), in a frame.
 *
 *   <section class="ds-plan" data-ds-plan aria-labelledby="plan-title">
 *     <div class="ds-plan__head">
 *       <span class="ds-plan__icon">[icon clipboardCheck 20]</span>
 *       <h3 class="ds-plan__title" id="plan-title">Replace the swollen batteries</h3>
 *       <span class="ds-plan__state"></span>
 *     </div>
 *     <p class="ds-plan__lead">Nothing changes until you approve.</p>
 *     <ol class="ds-tasks ds-plan__steps" aria-label="Steps">
 *       <li class="ds-tasks__item" data-status="pending"><span class="ds-tasks__mark"></span>
 *         <span class="ds-tasks__text">Find the laptops with a battery ticket</span></li>
 *     </ol>
 *     <div class="ds-plan__actions">
 *       <button class="ds-btn ds-btn--filled" type="button" data-ds-plan-action="approve">Approve</button>
 *       <button class="ds-btn" type="button" data-ds-plan-action="reject">Reject</button>
 *     </div>
 *     <p class="ds-plan__note">Proposed by the assistant at 09:12</p>
 *   </section>
 *
 * Parts: __head (an optional __icon, the __title and the __state, which
 * plan.js fills with a 16px __glyph and the word), __lead (optional: what
 * the plan does, what it leaves alone), __steps (on a .ds-tasks list: the
 * steps, each with its status as the work goes on), __actions (the
 * decision: one filled Approve, Reject, and any action of the page's own,
 * such as Edit), __note (optional, quiet: who proposed or decided, when).
 *
 * State (data-state, written by plan.js from data-ds-plan-state or a
 * decision; never colour alone): waiting (the hourglass and "Waiting for
 * approval"), approved (a check in a circle in --ds-success and
 * "Approved"), rejected (a crossed circle and "Rejected"; the steps turn
 * quiet). Once decided, the actions go.
 *
 * Options (src/core/options.css, docs/options.md), on it or any ancestor:
 *   density   .ds-density-*: the padding and the room between the parts,
 *             2px per step (the steps and the buttons follow their own)
 *   shape     the frame's corners times --ds-shape (the buttons follow
 *             their own)
 *   size      the buttons and the steps follow their own; the title keeps
 *             its role
 *   touch     the buttons' target (button.css)
 *   tone      not read: the state shows the meaning, with its word
 *
 * Hooks: --ds-plan-padding (--ds-space-4, the padding at the default
 * density), --ds-plan-radius (--ds-radius-card), --ds-plan-bg
 * (--ds-surface), --ds-plan-border (--ds-line).
 *
 * Motion: once decided the actions leave (DS.motion.leave(), .ds-leave:
 * --ds-dur-fast); back to waiting they enter (.ds-enter). The state's
 * word and glyph change in place.
 *
 * Forced colours: the frame keeps its border, the glyph follows the
 * word's forced text colour (global.css), the word stays.
 */

@layer ds.components.plan {
  .ds-plan {
    --_pad: max(var(--ds-space-2), calc(var(--ds-plan-padding, var(--ds-space-4)) + var(--ds-density, 0) * 2px));
    --_gap: max(var(--ds-space-1), calc(var(--ds-space-3) + var(--ds-density, 0) * 2px));
    display: grid;
    gap: var(--_gap);
    min-width: 0;
    margin: 0;
    padding: var(--_pad);
    border: 1px solid var(--ds-plan-border, var(--ds-line));
    border-radius: calc(var(--ds-plan-radius, var(--ds-radius-card)) * var(--ds-shape, 1));
    background: var(--ds-plan-bg, var(--ds-surface));
    color: var(--ds-text);
  }

  .ds-plan > * {
    margin: 0;
  }

  .ds-plan__head {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--ds-space-1) var(--ds-space-2);
    min-width: 0;
  }

  .ds-plan__icon {
    display: inline-flex;
    flex: none;
    color: var(--ds-primary);
  }

  .ds-plan__icon > svg {
    width: 20px;
    height: 20px;
  }

  .ds-plan__title {
    flex: 1 1 12em;
    min-width: 0;
    margin: 0;
    color: var(--ds-text);
    font: var(--ds-font-subtitle);
    overflow-wrap: anywhere;
    border-radius: calc(var(--ds-radius-xs) * var(--ds-shape, 1));
    outline-offset: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    transition: outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  /* Focus lands here once the actions went (tabindex="-1"); a ring only for the keyboard. */
  .ds-plan__title:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: var(--ds-focus-offset);
  }

  .ds-plan__state {
    display: inline-flex;
    flex: none;
    align-items: center;
    gap: var(--ds-space-1);
    color: var(--ds-text-2);
    font: var(--ds-font-caption);
  }

  .ds-plan__state:empty {
    display: none;
  }

  .ds-plan__glyph {
    flex: none;
    width: 16px;
    height: 16px;
    color: var(--ds-text-2);
  }

  .ds-plan[data-state="waiting"] .ds-plan__glyph {
    color: var(--ds-primary);
  }

  .ds-plan[data-state="approved"] .ds-plan__glyph {
    color: var(--ds-success);
  }

  .ds-plan__lead {
    color: var(--ds-text-2);
    font: var(--ds-font-body);
  }

  .ds-plan__steps {
    min-width: 0;
  }

  .ds-plan[data-state="rejected"] .ds-plan__steps .ds-tasks__text {
    color: var(--ds-text-2);
  }

  .ds-plan__actions {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--ds-space-2);
  }

  .ds-plan__actions[hidden] {
    display: none;
  }

  .ds-plan__note {
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
  }
}

/* ── components/question/question.css ── */
/*
 * Question card: a question an assistant or agent asks while it works,
 * with options to choose (one or several), an answer of one's own, and
 * Answer and Skip, in a frame. Once answered it keeps the choice in view
 * and says it in a line.
 *
 *   <form class="ds-question" data-ds-question aria-labelledby="q-title">
 *     <div class="ds-question__head">
 *       <span class="ds-question__icon">[icon helpCircle 20]</span>
 *       <h3 class="ds-question__title" id="q-title">Which laptops should get new batteries?</h3>
 *     </div>
 *     <p class="ds-question__hint">The assistant waits for your answer.</p>
 *     <div class="ds-radios ds-question__options" role="radiogroup" aria-labelledby="q-title">
 *       <label class="ds-radio"><input type="radio" name="q1" value="all">
 *         <span><strong>All three</strong><small>LAPTOP-0007, -0019 and -0031</small></span></label>
 *       ...
 *     </div>
 *     <div class="ds-field ds-question__other">
 *       <label class="ds-field__label" for="q-other">Something else</label>
 *       <input class="ds-input" id="q-other" name="other" autocomplete="off">
 *     </div>
 *     <p class="ds-field__hint ds-field__hint--error ds-question__error" hidden></p>
 *     <div class="ds-question__actions">
 *       <button class="ds-btn ds-btn--filled" type="submit">Answer</button>
 *       <button class="ds-btn ds-btn--text" type="button" data-ds-question-skip>Skip</button>
 *     </div>
 *     <p class="ds-question__answer" hidden></p>
 *   </form>
 *
 * Parts: __head (an optional __icon and the __title), __hint (optional:
 * why it asks, what happens next), __options (the choices: radio cards in
 * .ds-radios for one, checkbox cards in .ds-check-cards for several; their
 * look is form.css's), __other (optional: a .ds-field for an answer of
 * one's own), __error (the message of an answer without a choice, written
 * by question.js), __actions (Answer, the one filled button, and Skip),
 * __answer (the line once decided: a 16px __glyph and "Answered: ..." or
 * "Skipped", written by question.js).
 *
 * State (data-state, written by question.js; never colour alone):
 * waiting, answered (the check in a circle in --ds-success and the
 * words), skipped (a crossed-out circle and "Skipped"). Once decided, the
 * controls are disabled (the choice stays in view) and the actions go.
 *
 * Options (src/core/options.css, docs/options.md), on it or any ancestor:
 *   density   .ds-density-*: the padding and the room between the parts,
 *             2px per step (the cards, the field and the buttons follow
 *             their own)
 *   shape     the frame's corners times --ds-shape (the cards and the
 *             buttons follow their own)
 *   size      the cards, the field and the buttons follow their own; the
 *             title keeps its role
 *   touch     the targets of the cards, the field and the buttons
 *   tone      not read: the state shows the meaning, with its word
 *
 * Hooks: --ds-question-padding (--ds-space-4, the padding at the default
 * density), --ds-question-radius (--ds-radius-card), --ds-question-bg
 * (--ds-surface), --ds-question-border (--ds-line).
 *
 * Motion: once decided the actions leave (DS.motion.leave(), .ds-leave)
 * and the answer line fades in (ds-fade-in, --ds-dur-fast); opened again
 * the actions enter. The error message is form.css's.
 *
 * Forced colours: the frame keeps its border, the glyph follows the
 * line's forced text colour (global.css), the cards are form.css's.
 */

@layer ds.components.question {
  .ds-question {
    --_pad: max(var(--ds-space-2), calc(var(--ds-question-padding, var(--ds-space-4)) + var(--ds-density, 0) * 2px));
    --_gap: max(var(--ds-space-1), calc(var(--ds-space-3) + var(--ds-density, 0) * 2px));
    display: grid;
    gap: var(--_gap);
    min-width: 0;
    margin: 0;
    padding: var(--_pad);
    border: 1px solid var(--ds-question-border, var(--ds-line));
    border-radius: calc(var(--ds-question-radius, var(--ds-radius-card)) * var(--ds-shape, 1));
    background: var(--ds-question-bg, var(--ds-surface));
    color: var(--ds-text);
  }

  .ds-question > * {
    margin: 0;
  }

  .ds-question__head {
    display: flex;
    align-items: center;
    gap: var(--ds-space-2);
    min-width: 0;
  }

  .ds-question__icon {
    display: inline-flex;
    flex: none;
    align-self: flex-start;
    color: var(--ds-primary);
  }

  .ds-question__icon > svg {
    width: 20px;
    height: 20px;
  }

  .ds-question__title {
    min-width: 0;
    margin: 0;
    color: var(--ds-text);
    font: var(--ds-font-subtitle);
    overflow-wrap: anywhere;
  }

  .ds-question__hint {
    color: var(--ds-text-2);
    font: var(--ds-font-body);
  }

  .ds-question__options {
    min-width: 0;
  }

  .ds-question__other {
    min-width: 0;
  }

  .ds-question__error[hidden] {
    display: none;
  }

  .ds-question__actions {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--ds-space-2);
  }

  .ds-question__actions[hidden] {
    display: none;
  }

  .ds-question__answer {
    display: flex;
    align-items: flex-start;
    gap: var(--ds-space-2);
    color: var(--ds-text);
    font: var(--ds-font-label);
    border-radius: calc(var(--ds-radius-xs) * var(--ds-shape, 1));
    outline-offset: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    transition: outline-offset var(--ds-dur-fast) var(--ds-ease-out);
    animation: ds-fade-in var(--ds-dur-fast) var(--ds-ease-in-out) backwards;
  }

  .ds-question__answer[hidden] {
    display: none;
  }

  /* Focus lands here once decided (tabindex="-1"); a ring only for the keyboard. */
  .ds-question__answer:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: var(--ds-focus-offset);
  }

  .ds-question__glyph {
    flex: none;
    width: 16px;
    height: 16px;
    margin-block-start: calc((1lh - 16px) / 2);
    color: var(--ds-text-2);
  }

  .ds-question[data-state="answered"] .ds-question__glyph {
    color: var(--ds-success);
  }
}

/* ── components/usage/usage.css ── */
/*
 * Usage meter: what an assistant or agent used (tokens, and what they
 * cost) against a budget: a title, a meter, the figures and, near or over
 * the budget, a status with an icon and a word.
 *
 *   <section class="ds-usage" data-ds-usage data-ds-usage-used="182400" data-ds-usage-budget="250000"
 *            data-ds-usage-cost="3.12" data-ds-usage-cost-budget="5" data-ds-usage-currency="USD"
 *            aria-labelledby="usage-title">
 *     <div class="ds-usage__head">
 *       <h3 class="ds-usage__title" id="usage-title">Tokens this month</h3>
 *       <span class="ds-usage__status" hidden></span>
 *     </div>
 *     <span class="ds-meter ds-usage__meter" role="meter" aria-labelledby="usage-title"></span>
 *     <p class="ds-usage__figures"><span class="ds-usage__value"></span><span class="ds-usage__cost"></span></p>
 *     <p class="ds-usage__note">Resets on 1 December.</p>
 *   </section>
 *
 * Parts: __head (the __title and the __status), __meter (on a .ds-meter of
 * chart.css: the share, its tone near and over the budget), __figures (the
 * __value, tokens, and the __cost, both tabular, on one line that wraps),
 * __note (optional: when it resets, what the budget covers).
 *
 * The status (data-state="near" or "over" on the root, written by
 * usage.js, never colour alone): the __status shows an icon (__icon: the
 * warning triangle in --ds-warning near, the alert circle in --ds-error
 * over) and the word ("Near the budget", "Over budget") in --ds-text;
 * the meter takes the warning or error chart role. Without a budget there
 * is no share and no status: the figures alone, the meter hidden.
 *
 * Variant:
 *   .ds-usage--inline  one row: the title, the meter (at most
 *                      --ds-usage-inline-meter wide) and the figures, for
 *                      a composer's foot or a toolbar; it wraps when the
 *                      row is too narrow.
 *
 * Options (src/core/options.css, docs/options.md), on it or any ancestor:
 *   size      .ds-xs ... .ds-xl: the meter's thickness (chart.css, 1px
 *             per step); the type stays
 *   density   .ds-density-*: the room between the parts, 2px per step
 *   shape     the meter's ends (chart.css)
 *   tone      not read: the status shows the meaning, with its word
 *   touch     not read: nothing in it is a target
 *
 * Hooks: --ds-usage-gap (--ds-space-2, the room between the parts at the
 * default density), --ds-usage-inline-meter (160px).
 *
 * Motion: the meter's share glides (--ds-share on --ds-ease-value over
 * --ds-dur-glide, chart.css); the figures and the status change in place.
 *
 * Forced colours: the meter takes its system colours (chart.css); the icon
 * follows the word's forced text colour (global.css) and the word stays.
 */

@layer ds.components.usage {
  .ds-usage {
    --_gap: max(0px, calc(var(--ds-usage-gap, var(--ds-space-2)) + var(--ds-density, 0) * 2px));
    display: grid;
    gap: var(--_gap);
    min-width: 0;
    margin: 0;
    color: var(--ds-text);
  }

  .ds-usage__head {
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    justify-content: space-between;
    gap: var(--ds-space-1) var(--ds-space-3);
    min-width: 0;
  }

  .ds-usage__title {
    margin: 0;
    color: var(--ds-text);
    font: var(--ds-font-label);
  }

  .ds-usage__status {
    display: inline-flex;
    align-items: center;
    gap: var(--ds-space-1);
    color: var(--ds-text);
    font: var(--ds-font-caption);
  }

  .ds-usage__status[hidden] {
    display: none;
  }

  .ds-usage__icon {
    flex: none;
    align-self: center;
    width: 16px;
    height: 16px;
    color: var(--ds-warning);
  }

  .ds-usage[data-state="over"] .ds-usage__icon {
    color: var(--ds-error);
  }

  .ds-usage__meter {
    min-width: 0;
  }

  /* Without a budget (the module hides it): the meter's display would win over the UA rule. */
  .ds-usage__meter[hidden] {
    display: none;
  }

  .ds-usage__figures {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    gap: var(--ds-space-1) var(--ds-space-3);
    margin: 0;
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
    font-variant-numeric: tabular-nums;
  }

  /* A figure the page does not show takes no room. */
  .ds-usage__value:empty,
  .ds-usage__cost:empty {
    display: none;
  }

  .ds-usage__note {
    margin: 0;
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
  }

  /* One row: title, meter, figures. */
  .ds-usage--inline {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    column-gap: var(--ds-space-3);
  }

  .ds-usage--inline .ds-usage__head {
    flex: none;
    justify-content: flex-start;
  }

  .ds-usage--inline .ds-usage__title {
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
  }

  .ds-usage--inline .ds-usage__meter {
    flex: 1 1 var(--ds-space-8);
    max-width: var(--ds-usage-inline-meter, 160px);
  }

  .ds-usage--inline .ds-usage__figures {
    flex: none;
    justify-content: flex-start;
  }

  .ds-usage--inline .ds-usage__note {
    flex-basis: 100%;
  }
}

/* ── components/presence/presence.css ── */
/*
 * Presence: whether a person can be reached now, as a dot and a word.
 * Four states, each with its own shape as well as its colour, so a state
 * reads without colour (forced colours, a grey screen) and the word says it
 * to everyone:
 *
 *   <span class="ds-presence-label"><span class="ds-presence-dot ds-presence-dot--online"></span>Online</span>
 *   <span class="ds-presence-label"><span class="ds-presence-dot ds-presence-dot--away"></span>Away</span>
 *   <span class="ds-presence-label"><span class="ds-presence-dot ds-presence-dot--busy"></span>Busy</span>
 *   <span class="ds-presence-label"><span class="ds-presence-dot ds-presence-dot--offline"></span>Offline</span>
 *
 *   .ds-presence-dot--online    a filled disc (--ds-success)
 *   .ds-presence-dot--away      a ring, its lower half filled (--ds-warning)
 *   .ds-presence-dot--busy      a filled disc with a bar across (--ds-error)
 *   .ds-presence-dot--offline   an empty ring (--ds-outline)
 *   .ds-presence-label          the dot and its word on one line; the word
 *                               takes the type and the ink around it
 *
 * The dot is decoration: the word next to it, in .ds-sr inside it, or in
 * the label of the avatar it sits on (avatar.css: "Ada Lovelace, online")
 * carries the state. Every fill holds 3:1 on the surfaces (the icon pairs of
 * theme-rules.mjs).
 *
 * Not the motion utility .ds-presence (motion.css), which fades toggled
 * elements in and out.
 *
 * Options (docs/options.md), computed here into --_dot:
 *   size      .ds-xs ... .ds-xl on the dot or any ancestor: 2px per step
 *             (6 ... 14px around the 10px md dot); the stroke is a fifth
 *   shape     not read: a presence dot is round at every shape, so the
 *             four shapes stay told apart
 *   tone      not read: each state has its colour
 *   density, target-min: not read; a dot is no target
 *
 * Hooks: --ds-presence-dot-size (10px, the md base), --ds-presence-ground
 * (--ds-surface: the hollow of the away, busy and offline dots, the ground
 * they lie on), --ds-presence-online (--ds-success), --ds-presence-away
 * (--ds-warning), --ds-presence-busy (--ds-error), --ds-presence-offline
 * (--ds-outline).
 *
 * Motion: a state change glides its colours (--ds-dur-medium,
 * --ds-ease-in-out), as a status chip does; the shape changes at once.
 *
 * Forced colours: the shapes in CanvasText on Canvas, so the four states
 * stay apart without their colours.
 */

@layer ds.components.presence {
  .ds-presence-dot {
    --_dot: calc(var(--ds-presence-dot-size, 10px) + var(--ds-size-step, 0) * 2px);
    --_stroke: calc(var(--_dot) / 5);
    --_ink: var(--ds-presence-offline, var(--ds-outline));
    --_ground: var(--ds-presence-ground, var(--ds-surface));
    display: inline-block;
    flex-shrink: 0;
    box-sizing: border-box;
    inline-size: var(--_dot);
    block-size: var(--_dot);
    border: var(--_stroke) solid var(--_ink);
    border-radius: 50%;
    background-color: var(--_ground);
    vertical-align: middle;
    transition:
      background-color var(--ds-dur-medium) var(--ds-ease-in-out),
      border-color var(--ds-dur-medium) var(--ds-ease-in-out);
  }

  /* An empty ring; also the look of a dot without a state. */
  .ds-presence-dot--offline {
    --_ink: var(--ds-presence-offline, var(--ds-outline));
  }

  .ds-presence-dot--online {
    --_ink: var(--ds-presence-online, var(--ds-success));
    background-color: var(--_ink);
  }

  /* Half filled: the lower half of the ring's hollow takes the ink. */
  .ds-presence-dot--away {
    --_ink: var(--ds-presence-away, var(--ds-warning));
    background-image: linear-gradient(to top, var(--_ink) 50%, transparent 50%);
  }

  /* A bar across the filled disc, in the ground's colour. */
  .ds-presence-dot--busy {
    --_ink: var(--ds-presence-busy, var(--ds-error));
    background-color: var(--_ink);
    background-image: linear-gradient(var(--_ground), var(--_ground));
    background-position: center;
    background-size: 70% var(--_stroke);
    background-repeat: no-repeat;
  }

  .ds-presence-label {
    display: inline-flex;
    align-items: center;
    gap: var(--ds-space-2);
    min-inline-size: 0;
  }

  @media (forced-colors: active) {
    .ds-presence-dot {
      forced-color-adjust: none;
      --_ink: CanvasText;
      --_ground: Canvas;
    }
  }
}

/* ── components/avatar/avatar.css ── */
/*
 * Avatar: a person (a disc) or an entity (a square: a team, a device, a
 * service) as a picture, initials or an icon. A group stacks several and
 * ends with "+N".
 *
 *   <span class="ds-avatar" role="img" aria-label="Ada Lovelace">AL</span>
 *   <span class="ds-avatar ds-avatar--hue-3" data-ds-avatar="Ada Lovelace"></span>   (avatar.js: initials, hue, name)
 *   <span class="ds-avatar ds-sm" aria-hidden="true">AL</span> Ada Lovelace            (next to the name)
 *   <span class="ds-avatar" role="img" aria-label="Ada Lovelace"><img src="..." alt=""></span>
 *   <img class="ds-avatar" src="..." alt="">                                            (a picture alone, next to the name)
 *   <span class="ds-avatar" role="img" aria-label="Unknown user">(user 20)</span>
 *   <span class="ds-avatar ds-avatar--square" role="img" aria-label="Build service">(server 20)</span>
 *
 *   <span class="ds-avatar" role="img" aria-label="Ada Lovelace, online">AL<span class="ds-presence-dot ds-presence-dot--online"></span></span>
 *   <span class="ds-avatar ds-avatar--ring" role="img" aria-label="Ada Lovelace, new activity">AL</span>
 *   <span class="ds-avatar" role="img" aria-label="Ada Lovelace, 3 unread">AL<span class="ds-badge">3</span></span>
 *
 *   <div class="ds-avatar-group" role="group" aria-label="Assigned to" data-ds-avatar-group data-ds-avatar-group-max="3">
 *     <span class="ds-avatar" data-ds-avatar="Ada Lovelace"></span> ...
 *     <button class="ds-avatar ds-avatar-group__more" type="button" aria-haspopup="menu" aria-expanded="false" data-ds-open="#people-more" hidden></button>
 *     <div class="ds-menu" role="menu" id="people-more" hidden></div>
 *   </div>
 *
 * Variants:
 *   (none)                 a disc on the tint (--ds-avatar-bg / --ds-avatar-color:
 *                          --ds-accent / --ds-on-accent)
 *   .ds-avatar--hue-1 ... -6
 *                          a colour of its own, which avatar.js derives from
 *                          the name (DS.avatar.hue()): a chart role (1-4, the
 *                          neutral chart mark, and a mix of the second and
 *                          fourth) mixed into the surface (24%) behind the
 *                          same role mixed into the text (60%); every pair
 *                          holds 4.5:1 in every shipped theme and preset
 *   .ds-avatar--square     an entity: rounded corners (--ds-avatar-square-radius,
 *                          --ds-radius-sm, at most a quarter of the side)
 *   .ds-avatar--ring       an activity ring (new activity, speaking): a ring of
 *                          --ds-avatar-ring-color (--ds-primary, or the tone
 *                          of a .ds-tone-* class on the avatar itself) beyond
 *                          an edge of --ds-avatar-edge-color; the label says
 *                          what it means
 *   :is(a, button).ds-avatar
 *                          an avatar that opens something (a profile, the
 *                          rest of a group): a state layer over the picture,
 *                          the focus ring, a hit area of --ds-target-min
 *                          around the disc; no ripple and no morph (below)
 *
 * Parts inside an avatar (its overflow stays visible; a picture inside
 * clips itself to the radius):
 *   img                    covers the disc
 *   svg                    an icon, 60% of the side
 *   .ds-presence-dot       a status dot at the bottom end corner, on an edge
 *                          of --ds-avatar-edge-color; the avatar's label
 *                          carries its word (presence.css)
 *   .ds-badge              a count centred on the top end corner of the box,
 *                          a dot on the curve there, on the same edge
 *                          (badge.css)
 *
 * Group: .ds-avatar-group stacks its avatars, each overlapping the one
 * before by a quarter of the side, every one on its edge ring; a hidden
 * one takes no room. .ds-avatar-group--spread sets them side by side.
 * .ds-avatar-group__more is the neutral "+N" (--ds-surface-high /
 * --ds-text), usually a button that opens a menu of the rest (avatar.js
 * writes its text, its name and the menu). An avatar that takes keyboard
 * focus comes to the front while it has it, so its ring shows whole.
 *
 * Options (docs/options.md), computed here into --_size:
 *   size      .ds-xs ... .ds-xl on the avatar, the group or any ancestor:
 *             8px per step (16, 24, 32, 40, 48px around the 32px md,
 *             --ds-avatar-size); the type role of the size; a status dot
 *             and the edge ring follow
 *   shape     .ds-shape-*: multiplies the radius (a disc from the default
 *             up, square at 0); the corner parts follow the curve
 *   touch     .ds-touch: an interactive avatar keeps its disc and its hit
 *             area grows to --ds-target-min
 *   density   not read: an avatar is the size of a face, and a dense row
 *             takes a smaller size class
 *   tone      only the ring of .ds-avatar--ring, from the class on the
 *             avatar itself; the label carries what it means
 *
 * Interactive avatars and the ripple: a ripple host clips while a ripple
 * is inside (ripple.css), which would cut the status dot and the badge
 * on the corner. Until each ripple clips itself (plans/after-2.0.md), an
 * interactive avatar presses through its state layer alone (--ds-state-pressed
 * in --ds-dur-micro), the exception in meta.json. A disc never morphs: it
 * is a face, not a pill.
 *
 * Hooks: --ds-avatar-size (32px, the md base), --ds-avatar-bg,
 * --ds-avatar-color, --ds-avatar-font (the size's role),
 * --ds-avatar-square-radius (--ds-radius-sm), --ds-avatar-edge-color
 * (--ds-surface: the ground the avatar lies on), --ds-avatar-ring-color
 * (--ds-primary). Read: the badge's height hooks, to centre a badge on the
 * corner.
 *
 * Motion: none of its own. The state layer fades on --ds-dur-fast (the
 * press in --ds-dur-micro), the focus ring snaps (outline-offset,
 * --ds-dur-fast); a badge pops in and out through DS.badge.
 *
 * Blocked (:disabled, aria-disabled="true" on an interactive avatar): the
 * disabled model, --ds-disabled-fill and --ds-disabled-ink (a picture fades
 * to --ds-state-disabled), faded on --ds-dur-fast; no state layer.
 *
 * Forced colours: the disc keeps its edge (a transparent outline that
 * becomes visible), the state layer goes, the focus ring stays, a blocked
 * avatar turns GrayText; the ring
 * of --ring, a shadow elsewhere, becomes a Highlight outline beyond the
 * edge. A status dot and a badge keep their own forced looks.
 */

@layer ds.components.avatar {
  .ds-avatar {
    --_size: calc(var(--ds-avatar-size, 32px) + var(--ds-size-step, 0) * 8px);
    /* The edge ring between stacked avatars and around corner parts. */
    --_edge: max(1px, calc(var(--_size) / 16));
    --_edge-color: var(--ds-avatar-edge-color, var(--ds-surface));
    /* How far inside the box corner the curve passes (r - r / sqrt 2). */
    --_corner: calc(var(--_size) * 0.1464 * min(var(--ds-shape, 1), 1));
    position: relative;
    display: inline-grid;
    flex-shrink: 0;
    place-items: center;
    box-sizing: border-box;
    inline-size: var(--_size);
    block-size: var(--_size);
    padding: 0;
    border: 0;
    /* A disc at the default shape and above (past 50% it stays a disc). */
    border-radius: calc(50% * var(--ds-shape, 1));
    background: var(--ds-avatar-bg, var(--ds-accent));
    color: var(--ds-avatar-color, var(--ds-on-accent));
    font: var(--ds-avatar-font, var(--ds-size-font, var(--ds-font-label)));
    white-space: nowrap;
    text-decoration: none;
    vertical-align: middle;
    object-fit: cover;
    user-select: none;
  }

  .ds-avatar > img {
    grid-area: 1 / 1;
    inline-size: 100%;
    block-size: 100%;
    border-radius: inherit;
    object-fit: cover;
  }

  .ds-avatar > svg {
    grid-area: 1 / 1;
    inline-size: 60%;
    block-size: 60%;
  }

  /* Without .ds-base a hidden avatar would keep its grid. */
  .ds-avatar[hidden] {
    display: none;
  }

  /* An entity: rounded corners, at most a quarter of the side. */
  .ds-avatar--square {
    --_r: min(var(--ds-avatar-square-radius, var(--ds-radius-sm)), calc(var(--_size) / 4));
    --_corner: calc(var(--_r) * 0.2929 * var(--ds-shape, 1));
    border-radius: calc(var(--_r) * var(--ds-shape, 1));
  }

  /* A colour from the name: a chart role mixed into the surface, the same
     role mixed into the text (4.5:1 in every shipped theme; avatar.test.js). */
  .ds-avatar--hue-1 {
    --_hue: var(--ds-chart-1);
  }

  .ds-avatar--hue-2 {
    --_hue: var(--ds-chart-2);
  }

  .ds-avatar--hue-3 {
    --_hue: var(--ds-chart-3);
  }

  .ds-avatar--hue-4 {
    --_hue: var(--ds-chart-4);
  }

  .ds-avatar--hue-5 {
    --_hue: var(--ds-chart-neutral);
  }

  .ds-avatar--hue-6 {
    --_hue: color-mix(in srgb, var(--ds-chart-2), var(--ds-chart-4));
  }

  .ds-avatar:is(.ds-avatar--hue-1, .ds-avatar--hue-2, .ds-avatar--hue-3, .ds-avatar--hue-4, .ds-avatar--hue-5, .ds-avatar--hue-6) {
    background: color-mix(in srgb, var(--_hue) 24%, var(--ds-surface));
    color: color-mix(in srgb, var(--_hue) 60%, var(--ds-text));
  }

  /* The activity ring, beyond an edge of the ground. */
  .ds-avatar--ring {
    --_ring: var(--ds-avatar-ring-color, var(--ds-primary));
    box-shadow:
      0 0 0 var(--_edge) var(--_edge-color),
      0 0 0 calc(var(--_edge) * 2) var(--_ring);
  }

  .ds-avatar--ring:is(.ds-tone-neutral, .ds-tone-primary, .ds-tone-info, .ds-tone-success, .ds-tone-warning, .ds-tone-error) {
    --_ring: var(--ds-tone);
  }

  /* Corner parts: centred on the curve, each on the edge ring. */
  .ds-avatar > .ds-presence-dot {
    --_part: calc(var(--ds-presence-dot-size, 10px) + var(--ds-size-step, 0) * 2px);
    --ds-presence-ground: var(--_edge-color);
    position: absolute;
    inset-block-end: calc(var(--_corner) - var(--_part) / 2);
    inset-inline-end: calc(var(--_corner) - var(--_part) / 2);
    box-shadow: 0 0 0 var(--_edge) var(--_edge-color);
  }

  /* A count is centred on the box corner, so it covers less of the
     initials; a dot sits on the curve like the status dot. */
  .ds-avatar > .ds-badge {
    --_part: calc(var(--ds-badge-size, 20px) + var(--ds-size-step, 0) * 2px);
    position: absolute;
    inset-block-start: calc(var(--_part) / -2);
    inset-inline-end: calc(var(--_part) / -2);
    box-shadow: 0 0 0 var(--_edge) var(--_edge-color);
  }

  .ds-avatar > .ds-badge--dot {
    --_part: calc(var(--ds-badge-dot-size, 8px) + var(--ds-size-step, 0) * 2px);
    inset-block-start: calc(var(--_corner) - var(--_part) / 2);
    inset-inline-end: calc(var(--_corner) - var(--_part) / 2);
  }

  /*
   * An interactive avatar: the state layer lies over the picture (::after),
   * the hit area (::before) reaches the touch minimum around the disc.
   */
  :is(a, button).ds-avatar {
    cursor: pointer;
    -webkit-tap-highlight-color: transparent;
    /* The ring rests one width further out and snaps in. */
    outline-offset: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    transition:
      outline-offset var(--ds-dur-fast) var(--ds-ease-out),
      background-color var(--ds-dur-fast) var(--ds-ease-in-out),
      color var(--ds-dur-fast) var(--ds-ease-in-out),
      opacity var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  :is(a, button).ds-avatar > img {
    transition: opacity var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  :is(a, button).ds-avatar::before {
    content: '';
    position: absolute;
    inset: min(0px, calc((var(--_size) - var(--ds-target-min, 0px)) / 2));
  }

  :is(a, button).ds-avatar::after {
    content: '';
    position: absolute;
    inset: 0;
    border-radius: inherit;
    background: currentColor;
    opacity: 0;
    pointer-events: none;
    transition: opacity var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  @media (hover: hover) {
    :is(a, button).ds-avatar:hover::after {
      opacity: var(--ds-state-hover);
    }
  }

  :is(a, button).ds-avatar:focus-visible {
    z-index: var(--ds-z-raised);
    outline: var(--ds-focus-outline);
    outline-offset: var(--ds-focus-offset);
  }

  :is(a, button).ds-avatar:focus-visible::after {
    opacity: var(--ds-state-focus);
    transition-duration: 0s;
  }

  :is(a, button).ds-avatar:active::after {
    opacity: var(--ds-state-pressed);
    transition-duration: var(--ds-dur-micro);
  }

  /* Blocked: the disabled model (the neutral fill and ink, or the theme's
     dimming through --ds-disabled-opacity; a picture fades onto the fill),
     no layer, no press; aria-disabled keeps its focus layer. */
  :is(a, button).ds-avatar:is(:disabled, [aria-disabled="true"]) {
    cursor: not-allowed;
    opacity: var(--ds-disabled-opacity, var(--ds-state-disabled));
    background: var(--ds-disabled-fill, var(--ds-avatar-bg, var(--ds-accent)));
    color: var(--ds-disabled-ink, var(--ds-avatar-color, var(--ds-on-accent)));
  }

  /* A picture covers the fill: it fades to the disabled share, less what a
     theme's dimming of the whole avatar already takes. */
  :is(a, button).ds-avatar:is(:disabled, [aria-disabled="true"]) > img {
    opacity: calc(var(--ds-state-disabled) / var(--ds-disabled-opacity, 1));
  }

  @media (hover: hover) {
    :is(a, button).ds-avatar:is(:disabled, [aria-disabled="true"]):hover::after {
      opacity: 0;
    }
  }

  :is(a, button).ds-avatar:is(:disabled, [aria-disabled="true"]):active::after {
    opacity: 0;
  }

  /*
   * Group: a stack, each avatar a quarter over the one before, on its edge.
   */
  .ds-avatar-group {
    --_size: calc(var(--ds-avatar-size, 32px) + var(--ds-size-step, 0) * 8px);
    display: inline-flex;
    flex-wrap: nowrap;
    align-items: center;
    vertical-align: middle;
    /* No stacking context of its own: the menu of the rest, placed by the
       script where the top layer or anchor positioning is missing, must
       rise above what follows the group. */
  }

  .ds-avatar-group > .ds-avatar {
    box-shadow: 0 0 0 var(--_edge) var(--_edge-color);
  }

  .ds-avatar-group > .ds-avatar--ring {
    box-shadow:
      0 0 0 var(--_edge) var(--_edge-color),
      0 0 0 calc(var(--_edge) * 2) var(--_ring),
      0 0 0 calc(var(--_edge) * 3) var(--_edge-color);
  }

  .ds-avatar-group > .ds-avatar ~ .ds-avatar {
    margin-inline-start: calc(var(--_size) / -4);
  }

  .ds-avatar-group--spread {
    gap: var(--ds-space-1);
  }

  .ds-avatar-group--spread > .ds-avatar ~ .ds-avatar {
    margin-inline-start: 0;
  }

  .ds-avatar-group__more {
    --ds-avatar-bg: var(--ds-surface-high);
    --ds-avatar-color: var(--ds-text);
  }

  .ds-avatar-group__more:empty {
    display: none;
  }

  @media (forced-colors: active) {
    /* The disc keeps its edge where its fill is gone. */
    .ds-avatar {
      outline: 1px solid transparent;
    }

    :is(a, button).ds-avatar::after {
      display: none;
    }

    /* Blocked: GrayText, the one model for what cannot be used. */
    :is(a, button).ds-avatar:is(:disabled, [aria-disabled="true"]) {
      color: GrayText;
      outline-color: GrayText;
    }

    /* Shadows are gone here: the ring becomes an outline beyond the edge. */
    .ds-avatar--ring {
      outline: var(--_edge) solid Highlight;
      outline-offset: var(--_edge);
    }
  }
}

/* ── components/persona/persona.css ── */
/*
 * Persona: a person (or an entity) in one block: the avatar, the name, a
 * role and a status. In a list row, a table cell, a card head, a menu.
 *
 *   <div class="ds-persona">
 *     <span class="ds-avatar ds-avatar--hue-3" aria-hidden="true">AL<span class="ds-presence-dot ds-presence-dot--online"></span></span>
 *     <span class="ds-persona__text">
 *       <span class="ds-persona__name">Ada Lovelace</span>
 *       <span class="ds-persona__role">Field engineer</span>
 *       <span class="ds-persona__status"><span class="ds-presence-label"><span class="ds-presence-dot ds-presence-dot--online"></span>Online</span></span>
 *     </span>
 *   </div>
 *
 *   <a class="ds-persona ds-pressable" href="/people/ada"> ... </a>       (opens the profile)
 *
 * The avatar is aria-hidden: the name beside it names the person once. A
 * status shows as a word: in .ds-persona__status (a .ds-presence-label), or
 * as the avatar's dot plus that word; never the dot alone.
 *
 * Parts:
 *   .ds-persona__text    the column of lines, which may shrink (each line
 *                        ends in an ellipsis rather than wrap)
 *   .ds-persona__name    the name in the size's type role, --ds-text
 *   .ds-persona__role    a role, a team or an address in --ds-font-meta,
 *                        --ds-text-2
 *   .ds-persona__status  a status line in the role's type and ink, usually
 *                        a .ds-presence-label (presence.css)
 *
 * Variants:
 *   (none)               the avatar at the start, the lines beside it,
 *                        centred on it
 *   --stacked            the avatar above, the lines centred under it: the
 *                        head of a profile card or a people grid
 *   --inline             one line: the name and, after it, the role
 *   :is(a, button).ds-persona
 *                        a persona that opens something: add .ds-pressable
 *                        (the state layer, the focus ring and the ripple of
 *                        utilities.css); it takes a little room of its own
 *                        around its content (--ds-space-1 / --ds-space-2)
 *                        and reaches --ds-target-min
 *
 * Options (docs/options.md), computed here:
 *   size      .ds-xs ... .ds-xl on the persona or any ancestor: the avatar
 *             follows (16 to 48px), the name takes the size's type role
 *             (--ds-size-font), the gap 2px per step (8 to 16px)
 *   shape     the avatar's and the pressable's own radius (theirs)
 *   touch     an interactive persona is at least --ds-target-min high
 *   density, tone: not read; a persona sits in a row that has its own
 *             density, and a status says itself in words
 *
 * Hooks: --ds-persona-gap (--ds-space-3, the md base), --ds-persona-name-font
 * (the size's role, --ds-font-label), --ds-persona-role-font
 * (--ds-font-meta).
 *
 * Motion: none of its own; the pressable's state layer and focus snap.
 *
 * Forced colours: text in system colours by itself; the avatar and the
 * presence dot keep their own forced looks.
 */

@layer ds.components.persona {
  .ds-persona {
    --_gap: calc(var(--ds-persona-gap, var(--ds-space-3)) + var(--ds-size-step, 0) * 2px);
    display: inline-flex;
    align-items: center;
    gap: var(--_gap);
    min-inline-size: 0;
    max-inline-size: 100%;
    color: var(--ds-text);
    text-align: start;
    text-decoration: none;
    vertical-align: middle;
  }

  .ds-persona__text {
    display: flex;
    flex-direction: column;
    min-inline-size: 0;
  }

  .ds-persona__name,
  .ds-persona__role,
  .ds-persona__status {
    overflow: hidden;
    min-inline-size: 0;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .ds-persona__name {
    color: var(--ds-text);
    font: var(--ds-persona-name-font, var(--ds-size-font, var(--ds-font-label)));
  }

  .ds-persona__role,
  .ds-persona__status {
    color: var(--ds-text-2);
    font: var(--ds-persona-role-font, var(--ds-font-meta));
  }

  /* The status line holds the dot and its word on one line. */
  .ds-persona__status {
    display: flex;
    align-items: center;
  }

  .ds-persona--stacked {
    flex-direction: column;
    text-align: center;
  }

  .ds-persona--stacked > .ds-persona__text {
    align-items: center;
    max-inline-size: 100%;
  }

  .ds-persona--stacked .ds-persona__status {
    justify-content: center;
  }

  .ds-persona--inline > .ds-persona__text {
    flex-direction: row;
    align-items: baseline;
    gap: var(--ds-space-2);
  }

  .ds-persona--inline .ds-persona__name {
    flex-shrink: 0;
    max-inline-size: 100%;
  }

  /* An interactive persona: room around its content for the state layer. */
  :is(a, button).ds-persona {
    box-sizing: border-box;
    min-block-size: var(--ds-target-min, 0px);
    margin: 0;
    padding: var(--ds-space-1) var(--ds-space-2);
    border: 0;
    background: none;
    font: inherit;
  }

  :is(a, button).ds-persona:is(:disabled, [aria-disabled="true"]) {
    color: var(--ds-disabled-ink);
  }

  :is(a, button).ds-persona:is(:disabled, [aria-disabled="true"]) :is(.ds-persona__name, .ds-persona__role, .ds-persona__status) {
    color: inherit;
  }

  @media (forced-colors: active) {
    :is(a, button).ds-persona:is(:disabled, [aria-disabled="true"]) {
      color: GrayText;
    }
  }
}

/* ── components/media/media.css ── */
/*
 * Media card and gallery grid: thumbnails of files, photos, recordings or
 * devices that open, can be selected and carry their own actions.
 *
 *   <ul class="ds-media-grid" aria-label="Photos" data-ds-media>
 *     <li class="ds-media" data-ds-key="p1">
 *       <span class="ds-media__thumb"><img src="..." alt=""> [<span class="ds-media__tag">0:42</span>]</span>
 *       <a class="ds-media__open" href="..."><span class="ds-media__title">pump-room.jpg</span></a>
 *       <span class="ds-media__meta">2.4 MB · JPEG</span>
 *       <span class="ds-media__select"><input class="ds-checkbox ds-media__check" type="checkbox" aria-label="Select pump-room.jpg"></span>
 *       <span class="ds-media__actions"><button class="ds-btn ds-btn--quiet ds-btn--icon ds-sm" type="button"
 *             aria-label="More for pump-room.jpg" aria-haspopup="menu" ...>(moreVertical)</button></span>
 *     </li>
 *   </ul>
 *
 * The order of the parts is the tab order inside a card: open, checkbox,
 * actions.
 *
 * A thumbnail without a picture holds an icon (a file type, a device):
 *   <span class="ds-media__thumb">(fileText 32)</span>
 *
 * Parts:
 *   .ds-media__thumb     the picture at the card's ratio (--ds-media-ratio,
 *                        4 / 3), an <img> or <video> covering it, else an
 *                        icon centred on --ds-surface-high
 *   .ds-media__tag       a short fact over the picture's bottom end corner
 *                        (a duration, a page count, "RAW"): --ds-inverse
 *                        with --ds-on-inverse, the caption type
 *   .ds-media__select    the selection checkbox over the picture's top
 *                        start corner, on a disc of --ds-surface; it shows
 *                        with the card's hover or focus, and always once
 *                        anything in the grid is selected, under a coarse
 *                        pointer and under .ds-touch
 *   .ds-media__open      the main action (a link or a button) around the
 *                        title: its box stretches over the whole card
 *                        (::after), so the picture opens too, and carries
 *                        the state layer; the focus ring goes round the card
 *   .ds-media__title     the name, one line with an ellipsis
 *   .ds-media__meta      a second line in --ds-font-meta, --ds-text-2
 *   .ds-media__actions   buttons at the end of the text (a menu button),
 *                        above the stretched action
 *
 * Variants:
 *   (none)               a picture at 4 / 3 above the text
 *   --square             1 / 1
 *   --wide               16 / 9
 *   --bare               the picture alone: the title and meta stay in the
 *                        tree (read, not shown), the stretched action
 *                        still covers the card, the actions sit over the
 *                        picture
 *
 * Selected: the checkbox is the truth (:checked). The card takes
 * --ds-media-selected-bg (--ds-accent) with --ds-on-accent text and a static inset ring of
 * --ds-focus-width in --ds-selected-ring (--ds-primary), so the focus ring
 * stays free; the checked box is the mark that never relies on colour.
 * Colours on --ds-dur-fast, the ring at once.
 *
 * Grid: .ds-media-grid fills columns of at least --ds-media-min (128px at
 * md) and stretches them to the row; a list (<ul>) or any container of
 * cards. data-ds-media (media.js) makes it one tab stop with the arrow
 * keys, Space selection, Shift for a range, Ctrl+A and Escape.
 *
 * Options (docs/options.md), computed here:
 *   size      .ds-xs ... .ds-xl on the grid or any ancestor: the column
 *             minimum 32px per step (64 to 192px), the title in the
 *             size's type role
 *   density   .ds-density-*: the grid gap 4px per step, the text padding
 *             2px per step
 *   shape     the card's and the picture's radius times --ds-shape
 *   touch     .ds-touch: the selection checkboxes always show (their halo
 *             is the form's, at least --ds-target-min)
 *   tone      not read: a card shows no status of its own; a status chip
 *             or badge inside says its word
 *
 * Hooks: --ds-media-min (128px, the md column), --ds-media-gap
 * (--ds-space-4), --ds-media-ratio (4 / 3), --ds-media-radius
 * (--ds-radius-card), --ds-media-bg (--ds-surface), --ds-media-border
 * (--ds-line), --ds-media-selected-bg (--ds-accent), --ds-selected-ring
 * (read, --ds-primary).
 *
 * Motion: the state layer fades on --ds-dur-fast (the press in
 * --ds-dur-micro), the focus ring snaps (outline-offset), the selection
 * checkbox fades in on --ds-dur-fast and out on --ds-dur-instant, the
 * selected colours on --ds-dur-fast. Nothing moves or scales.
 *
 * Forced colours: every card keeps its border; a selected card is
 * Highlight with HighlightText; the tag keeps an edge.
 */

@layer ds.components.media {
  .ds-media-grid {
    --_min: calc(var(--ds-media-min, 128px) + var(--ds-size-step, 0) * 32px);
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(min(var(--_min), 100%), 1fr));
    gap: calc(var(--ds-media-gap, var(--ds-space-4)) + var(--ds-density, 0) * 4px);
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .ds-media {
    --_radius: calc(var(--ds-media-radius, var(--ds-radius-card)) * var(--ds-shape, 1));
    --_pad: calc(var(--ds-space-3) + var(--ds-density, 0) * 2px);
    position: relative;
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    grid-template-rows: auto auto 1fr;
    align-content: start;
    min-inline-size: 0;
    border: 1px solid var(--ds-media-border, var(--ds-line));
    border-radius: var(--_radius);
    background: var(--ds-media-bg, var(--ds-surface));
    color: var(--ds-text);
    /* The ring rests (invisible) one width further out and snaps in. */
    outline-offset: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    transition:
      background-color var(--ds-dur-fast) var(--ds-ease-in-out),
      outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-media__thumb {
    position: relative;
    display: grid;
    grid-column: 1 / -1;
    place-items: center;
    overflow: hidden;
    aspect-ratio: var(--ds-media-ratio, 4 / 3);
    border-radius: calc(var(--_radius) - 1px) calc(var(--_radius) - 1px) 0 0;
    background: var(--ds-surface-high);
    color: var(--ds-text-2);
  }

  .ds-media--square > .ds-media__thumb {
    aspect-ratio: 1 / 1;
  }

  .ds-media--wide > .ds-media__thumb {
    aspect-ratio: 16 / 9;
  }

  .ds-media__thumb > :is(img, video) {
    grid-area: 1 / 1;
    inline-size: 100%;
    block-size: 100%;
    object-fit: cover;
  }

  .ds-media__tag {
    position: absolute;
    inset-block-end: var(--ds-space-2);
    inset-inline-end: var(--ds-space-2);
    padding: 0 var(--ds-space-1);
    border-radius: calc(var(--ds-radius-xs) * var(--ds-shape, 1));
    background: var(--ds-inverse);
    color: var(--ds-on-inverse);
    font: var(--ds-font-caption);
  }

  .ds-media__open {
    grid-column: 1;
    min-inline-size: 0;
    padding: var(--_pad) var(--_pad) 0;
    color: inherit;
    text-decoration: none;
    cursor: pointer;
    -webkit-tap-highlight-color: transparent;
  }

  /* The card's own outline is the ring: the control draws none. */
  .ds-media__open:focus-visible {
    outline: none;
  }

  /* The whole card opens, and shows the state layer. */
  .ds-media__open::after {
    content: '';
    position: absolute;
    inset: 0;
    z-index: var(--ds-z-raised);
    border-radius: calc(var(--_radius) - 1px);
    background: currentColor;
    opacity: 0;
    transition: opacity var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  @media (hover: hover) {
    .ds-media__open:hover::after {
      opacity: var(--ds-state-hover);
    }
  }

  .ds-media__open:focus-visible::after {
    opacity: var(--ds-state-focus);
    transition-duration: 0s;
  }

  .ds-media__open:active::after {
    opacity: var(--ds-state-pressed);
    transition-duration: var(--ds-dur-micro);
  }

  .ds-media:has(.ds-media__open:focus-visible) {
    outline: var(--ds-focus-outline);
    outline-offset: var(--ds-focus-offset);
  }

  .ds-media__title,
  .ds-media__meta {
    display: block;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .ds-media__title {
    font: var(--ds-size-font, var(--ds-font-label));
  }

  .ds-media__meta {
    grid-column: 1;
    min-inline-size: 0;
    padding: 0 var(--_pad) var(--_pad);
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
  }

  /* Without meta the title keeps its bottom room. */
  .ds-media:not(:has(> .ds-media__meta)) > .ds-media__open {
    padding-block-end: var(--_pad);
  }

  .ds-media__actions {
    position: relative;
    z-index: var(--ds-z-pinned);
    display: flex;
    grid-row: 2 / 4;
    grid-column: 2;
    align-items: center;
    align-self: center;
    padding-inline-end: var(--ds-space-1);
  }

  /* Selection: the checkbox on a disc over the picture's corner. */
  .ds-media__select {
    position: absolute;
    inset-block-start: var(--ds-space-2);
    inset-inline-start: var(--ds-space-2);
    z-index: var(--ds-z-pinned);
    display: grid;
    place-items: center;
    inline-size: calc(var(--ds-space-8) + var(--ds-size-step, 0) * 4px);
    block-size: calc(var(--ds-space-8) + var(--ds-size-step, 0) * 4px);
    border-radius: calc(50% * var(--ds-shape, 1));
    background: var(--ds-surface);
    opacity: 0;
    transition: opacity var(--ds-dur-instant) var(--ds-ease-in-out);
  }

  @media (hover: hover) {
    .ds-media:hover > .ds-media__select {
      opacity: 1;
      transition-duration: var(--ds-dur-fast);
    }
  }

  .ds-media:focus-within > .ds-media__select,
  .ds-media-grid:has(.ds-media__check:checked) .ds-media__select,
  .ds-media__select:has(> .ds-media__check:checked) {
    opacity: 1;
    transition-duration: var(--ds-dur-fast);
  }

  @media (hover: none) {
    .ds-media__select {
      opacity: 1;
    }
  }

  .ds-touch .ds-media__select {
    opacity: 1;
  }

  /* Selected: the tint, and a ring inside the edge that leaves the focus
     ring free; the checked box says it without colour. */
  .ds-media:has(> .ds-media__select > .ds-media__check:checked) {
    background: var(--ds-media-selected-bg, var(--ds-accent));
    color: var(--ds-on-accent);
  }

  .ds-media:has(> .ds-media__select > .ds-media__check:checked) > .ds-media__meta {
    color: var(--ds-on-accent);
  }

  .ds-media:has(> .ds-media__select > .ds-media__check:checked)::before {
    content: '';
    position: absolute;
    inset: -1px;
    z-index: var(--ds-z-raised);
    border: var(--ds-focus-width) solid var(--ds-selected-ring, var(--ds-primary));
    border-radius: var(--_radius);
    pointer-events: none;
  }

  /* The picture alone: the text stays in the tree, unseen; the stretched
     action still covers the card. */
  .ds-media--bare > .ds-media__thumb {
    border-radius: calc(var(--_radius) - 1px);
  }

  .ds-media--bare > .ds-media__open {
    position: static;
    padding: 0;
  }

  .ds-media--bare > .ds-media__open > .ds-media__title,
  .ds-media--bare > .ds-media__meta {
    position: absolute;
    overflow: hidden;
    inline-size: 1px;
    block-size: 1px;
    clip-path: inset(50%);
    white-space: nowrap;
  }

  .ds-media--bare {
    align-self: start;
  }

  /* Placed in the card's box, not in a grid area. */
  .ds-media--bare > .ds-media__actions {
    position: absolute;
    grid-area: auto;
    inset-block-start: var(--ds-space-1);
    inset-inline-end: var(--ds-space-1);
    padding: 0;
    border-radius: calc(var(--ds-radius-action) * var(--ds-shape, 1));
    background: var(--ds-surface);
  }

  @media (forced-colors: active) {
    .ds-media__open::after {
      display: none;
    }

    /* Selected: the text part in Highlight, the ring around the card;
       the picture, the checkbox and the actions keep their forced looks
       (forced-color-adjust inherits, so they take it back). */
    .ds-media:has(> .ds-media__select > .ds-media__check:checked) {
      forced-color-adjust: none;
      background: Highlight;
      color: HighlightText;
    }

    .ds-media:has(> .ds-media__select > .ds-media__check:checked) > :is(.ds-media__thumb, .ds-media__select, .ds-media__actions) {
      forced-color-adjust: auto;
    }

    .ds-media:has(> .ds-media__select > .ds-media__check:checked) > .ds-media__meta {
      color: HighlightText;
    }

    .ds-media:has(> .ds-media__select > .ds-media__check:checked)::before {
      border-color: Highlight;
    }

    .ds-media:has(.ds-media__open:focus-visible) {
      outline-color: CanvasText;
    }

    .ds-media__tag {
      outline: 1px solid transparent;
    }
  }
}

/* ── components/levelmeter/levelmeter.css ── */
/*
 * Audio level meter: the live level of a microphone (or any signal) as a
 * bar, with a peak marker that holds and falls, and a word when it is too
 * loud. The page supplies the level: an AnalyserNode (levelmeter.js reads
 * it every frame) or a value from 0 to 1.
 *
 *   <div class="ds-levelmeter [ds-levelmeter--segmented | --vertical]" data-ds-levelmeter>
 *     <span class="ds-levelmeter__label" id="mic-label">Microphone</span>
 *     <div class="ds-levelmeter__track" role="meter" aria-labelledby="mic-label"
 *          aria-valuemin="0" aria-valuemax="100" aria-valuenow="0">
 *       <span class="ds-levelmeter__fill"></span>
 *       <span class="ds-levelmeter__peak"></span>
 *     </div>
 *     <span class="ds-levelmeter__note" aria-live="polite"></span>
 *   </div>
 *
 * Parts:
 *   .ds-levelmeter__label  the name, above the track (labels above), the
 *                          label type
 *   .ds-levelmeter__track  the meter (role="meter"): the track in
 *                          --ds-levelmeter-track (--ds-accent); the script
 *                          writes aria-valuenow (0 ... 100, a few times a
 *                          second) and aria-valuetext ("-18 dB")
 *   .ds-levelmeter__fill   the level, scaled from the start of the track by
 *                          --ds-levelmeter-level (0 ... 1, written by the
 *                          script every frame) in --ds-levelmeter-fill
 *                          (--ds-primary)
 *   .ds-levelmeter__peak   the highest recent level, a mark that holds for
 *                          --ds-hold-status and then falls (the script
 *                          writes --ds-levelmeter-peak, and hidden while
 *                          nothing was heard)
 *   .ds-levelmeter__note   a word for the state, written by the script:
 *                          "Too loud" while the signal clips (levelmeterLoud)
 *
 * Variants:
 *   (none)                 one bar
 *   --segmented            the track cut into segments (a mask of
 *                          --ds-levelmeter-segment and a 2px gap), so it
 *                          reads as a meter at a glance
 *   --vertical             upright: the level grows upwards over
 *                          --ds-levelmeter-length (96px)
 *
 * States: data-state="loud" (written by the script on .ds-levelmeter while
 * the signal clips, a sample peak at -1 dBFS): the fill and the peak in --ds-error and the note says
 * it in words, never the colour alone. aria-disabled="true" on the track
 * (the page's, a muted microphone): the disabled model, and the script
 * shows no level.
 *
 * Options (docs/options.md), computed here into --_t:
 *   size      .ds-xs ... .ds-xl on it or any ancestor: the thickness 2px per
 *             step (2 ... 10px around the 6px md, --ds-levelmeter-height)
 *   shape     the ends of the track times --ds-shape (round at the
 *             default, square at 0); segments keep the same radius
 *   density   the label's and note's distance from the track, 2px per step
 *   tone      on .ds-levelmeter itself: the fill in --ds-tone, the track in
 *             --ds-tone-container (the "loud" state still wins)
 *   touch     not read: a meter is no target
 *
 * Direction: a meter runs left to right whatever the writing direction,
 * like the scale it shows: the fill grows from the left, the peak mark is
 * placed from the left (left: 0) and the segments run that way (the
 * physical exceptions in meta.json).
 *
 * Hooks: --ds-levelmeter-height (6px, the md thickness),
 * --ds-levelmeter-length (96px, --vertical), --ds-levelmeter-fill
 * (--ds-primary), --ds-levelmeter-track (--ds-accent),
 * --ds-levelmeter-segment (6px, --segmented). Runtime properties (the
 * script's): --ds-levelmeter-level, --ds-levelmeter-peak.
 *
 * Motion: the level is live data and changes every frame without a
 * transition (the script's ballistics: it rises at once and falls over
 * --ds-dur-glide per full scale; the peak holds --ds-hold-status, then
 * falls the same way); the loud colour comes and goes on --ds-dur-fast.
 *
 * Forced colours: the track keeps a CanvasText outline, the fill is
 * Highlight, the peak CanvasText, loud stays a word.
 */

@layer ds.components.levelmeter {
  .ds-levelmeter {
    --_t: max(2px, calc(var(--ds-levelmeter-height, 6px) + var(--ds-size-step, 0) * 2px));
    --_end: min(calc(var(--ds-radius-action) * var(--ds-shape, 1)), calc(var(--_t) / 2));
    --_fill: var(--ds-levelmeter-fill, var(--ds-primary));
    --_track: var(--ds-levelmeter-track, var(--ds-accent));
    --_gap: calc(var(--ds-space-2) + var(--ds-density, 0) * 2px);
    display: grid;
    gap: var(--_gap);
    min-inline-size: 0;
    color: var(--ds-text);
  }

  .ds-levelmeter:is(.ds-tone-neutral, .ds-tone-primary, .ds-tone-info, .ds-tone-success, .ds-tone-warning, .ds-tone-error) {
    --_fill: var(--ds-levelmeter-fill, var(--ds-tone));
    --_track: var(--ds-levelmeter-track, var(--ds-tone-container));
  }

  .ds-levelmeter__label {
    font: var(--ds-font-label);
  }

  .ds-levelmeter__note {
    min-block-size: 1lh;
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
  }

  .ds-levelmeter__track {
    position: relative;
    overflow: hidden;
    block-size: var(--_t);
    border-radius: var(--_end);
    background: var(--_track);
    container-type: inline-size;
  }

  .ds-levelmeter__fill {
    position: absolute;
    inset: 0;
    background: var(--_fill);
    transform-origin: 0 50%;
    scale: var(--ds-levelmeter-level, 0) 1;
    transition: background-color var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  .ds-levelmeter__peak {
    position: absolute;
    inset-block: 0;
    left: 0;
    inline-size: max(2px, calc(var(--_t) / 2));
    background: var(--_fill);
    translate: calc(var(--ds-levelmeter-peak, 0) * (100cqi - 100%)) 0;
    transition: background-color var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  /* Without .ds-base a hidden peak (nothing heard yet) would show. */
  .ds-levelmeter__peak[hidden] {
    display: none;
  }

  .ds-levelmeter[data-state="loud"] {
    --_fill: var(--ds-error);
  }

  .ds-levelmeter[data-state="loud"] > .ds-levelmeter__note {
    color: var(--ds-error);
  }

  /* Segments: the track and what it holds cut by one mask. */
  .ds-levelmeter--segmented > .ds-levelmeter__track {
    --_seg: var(--ds-levelmeter-segment, 6px);
    border-radius: 0;
    background: none;
    mask: repeating-linear-gradient(to right, currentColor 0 var(--_seg), transparent var(--_seg) calc(var(--_seg) + 2px));
  }

  .ds-levelmeter--segmented > .ds-levelmeter__track::before {
    content: '';
    position: absolute;
    inset: 0;
    background: var(--_track);
  }

  /* Upright: the level grows from the bottom. */
  .ds-levelmeter--vertical {
    justify-items: center;
  }

  .ds-levelmeter--vertical > .ds-levelmeter__track {
    inline-size: var(--_t);
    block-size: var(--ds-levelmeter-length, 96px);
    container-type: size;
  }

  .ds-levelmeter--vertical .ds-levelmeter__fill {
    transform-origin: 50% 100%;
    scale: 1 var(--ds-levelmeter-level, 0);
  }

  .ds-levelmeter--vertical .ds-levelmeter__peak {
    inset-block: auto 0;
    inset-inline: 0;
    inline-size: auto;
    block-size: max(2px, calc(var(--_t) / 2));
    translate: 0 calc(var(--ds-levelmeter-peak, 0) * (100% - 100cqb));
  }

  .ds-levelmeter--vertical.ds-levelmeter--segmented > .ds-levelmeter__track {
    mask: repeating-linear-gradient(to top, currentColor 0 var(--_seg), transparent var(--_seg) calc(var(--_seg) + 2px));
  }

  /* Muted (the page's aria-disabled): the disabled model, no level. */
  .ds-levelmeter:has(> .ds-levelmeter__track[aria-disabled="true"]) {
    color: var(--ds-disabled-ink);
  }

  .ds-levelmeter__track[aria-disabled="true"] {
    background: var(--ds-disabled-fill);
  }

  .ds-levelmeter__track[aria-disabled="true"] > :is(.ds-levelmeter__fill, .ds-levelmeter__peak) {
    visibility: hidden;
  }

  @media (forced-colors: active) {
    .ds-levelmeter__track {
      forced-color-adjust: none;
      outline: 1px solid CanvasText;
      background: Canvas;
    }

    .ds-levelmeter__fill {
      background: Highlight;
    }

    .ds-levelmeter__peak {
      background: CanvasText;
    }

    .ds-levelmeter--segmented > .ds-levelmeter__track::before {
      background: Canvas;
    }

    .ds-levelmeter__track[aria-disabled="true"] {
      outline-color: GrayText;
    }
  }
}

/* ── components/command/command.css ── */
/*
 * Command palette: one search field over every command of an app, in a
 * modal dialog near the top of the window (the box stays where it is while
 * the results change). The WAI-ARIA combobox pattern: the field keeps
 * focus, the active option (data-active, aria-selected) gets the hover
 * layer, never colour alone; the matched letters are marked in the label's
 * weight and the primary ink.
 *
 *   <dialog class="ds-dialog ds-command" id="palette" data-ds-command aria-label="Command palette">
 *     <div class="ds-dialog__backdrop" data-ds-close></div>
 *     <div class="ds-dialog__box">
 *       <div class="ds-command__search">
 *         <svg ...>(search 20)</svg>
 *         [<button class="ds-command__back" type="button" tabindex="-1" aria-label="Back">(chevronLeft) <span>Devices</span></button>]  command.js
 *         <input class="ds-command__input" type="text" role="combobox" aria-label="Search commands" placeholder="Search or run a command">
 *         <kbd class="ds-kbd">Esc</kbd>
 *         <button class="ds-btn ds-btn--text ds-command__close" type="button" data-ds-close>Cancel</button>   phones only
 *       </div>
 *       <div class="ds-command__list" role="listbox" aria-label="Commands">
 *         <div class="ds-command__group" role="group" aria-labelledby="g1">
 *           <div class="ds-command__heading" id="g1" role="presentation">Devices</div>
 *           <div class="ds-command__item" role="option" id="o1" aria-selected="true" data-active aria-keyshortcuts="Control+Shift+A">
 *             <svg class="ds-command__icon" ...>(plus 20)</svg>
 *             <span class="ds-command__content">
 *               <span class="ds-command__label"><mark class="ds-command__match">Add</mark> a device</span>
 *               <span class="ds-command__description">Register a laptop, tablet or phone</span></span>
 *             <span class="ds-command__shortcut" aria-hidden="true"><kbd class="ds-kbd">Ctrl</kbd><kbd class="ds-kbd">Shift</kbd><kbd class="ds-kbd">A</kbd></span>
 *             [<svg class="ds-command__chevron" ...>(chevronRight)</svg>]   a command that opens a page
 *       <p class="ds-command__empty">No results for "x"</p>                      command.js, hidden while there are results
 *       <div class="ds-command__foot"><span>(hints)</span><p class="ds-command__status" role="status">12 results</p></div>
 *
 * command.js renders the groups and options from data (or from the
 * options of the markup), writes the status line (a .ds-spinner while
 * providers answer) and the empty message, and makes the back button of a
 * page. aria-disabled="true" on an option: the disabled ink, no layer.
 *
 * Options (docs/options.md), computed here:
 *   size      .ds-xs ... .ds-xl on the dialog or any ancestor: the search
 *             row and an option 8px per step, the option's type
 *             (--ds-size-font)
 *   density   any container: the search row and an option 4px per step, the
 *             list's padding 2px per step; type stays
 *   shape     the box's radius (the dialog's), an option's radius times
 *             --ds-shape
 *   touch     .ds-touch: an option at least --ds-target-min tall
 *   tone      none: a palette states no status
 *
 * Phones (600px and below): the box fills the window from the top, the
 * list takes the rest of the height.
 *
 * Hooks: --ds-command-width (640px), --ds-command-top (the room above the
 * box, min(12vh, 96px)), --ds-command-height (the box's most height,
 * 480px), --ds-command-search-height (56px) and --ds-command-item-height
 * (48px), the md comfortable bases, --ds-command-item-radius
 * (--ds-radius-sm).
 *
 * Forced colours: the active option takes a Highlight ring, a match its
 * underline (the colour is gone), blocked options GrayText.
 *
 * Motion: the dialog's (DS.overlay); the active layer fades in over
 * --ds-dur-micro and goes at once, so a held arrow key leaves no trail.
 *
 * Progressive:
 * - scrollbar-color and scrollbar-width (a thin, quiet scrollbar on the
 *   list): without them the platform scrollbar shows.
 */

@layer ds.components.command {
  /* Near the top, not centred: the box keeps its place while the list
     grows and shrinks under the field. */
  .ds-command {
    place-items: start center;
    padding-top: var(--ds-command-top, min(12vh, 96px));
  }

  .ds-command .ds-dialog__box {
    display: flex;
    flex-direction: column;
    gap: 0;
    width: min(var(--ds-command-width, 640px), 100%);
    max-height: min(var(--ds-command-height, 480px), 100%);
    padding: 0;
    overflow: hidden;
  }

  .ds-command__search {
    --_h: calc(var(--ds-command-search-height, 56px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px);
    display: flex;
    flex: none;
    align-items: center;
    gap: var(--ds-space-3);
    min-height: max(var(--ds-target-min, 0px), var(--_h));
    padding-inline: var(--ds-space-4);
    border-bottom: 1px solid var(--ds-line);
    color: var(--ds-text-2);
    transition: border-color var(--ds-dur-fast) var(--ds-ease-in-out);
  }

  .ds-command__search > svg {
    flex: none;
  }

  /* The field has no box of its own: the search row is its box. Its type
     is the input role (16px on phones, so they never zoom). */
  .ds-command__input {
    flex: 1;
    min-width: 0;
    height: 100%;
    margin: 0;
    padding: 0;
    border: 0;
    background: transparent;
    color: var(--ds-text);
    font: var(--ds-font-input);
    outline: none;
  }

  .ds-command__input::placeholder {
    color: var(--ds-text-2);
    opacity: 1;
  }

  /* The field has no ring of its own (it would draw inside the box's
     edge): while it has focus, the row's line under it turns primary, as
     a field's border does. */
  .ds-command__search:has(> .ds-command__input:focus) {
    border-bottom-color: var(--ds-primary);
  }

  /* A page: its label and the way back, before the field. */
  .ds-command__back {
    display: inline-flex;
    flex: none;
    align-items: center;
    gap: var(--ds-space-1);
    max-width: 40%;
    min-height: 28px;
    margin: 0;
    padding-block: 0;
    padding-inline: var(--ds-space-1) var(--ds-space-2);
    border: 0;
    border-radius: calc(var(--ds-radius-xs) * var(--ds-shape, 1));
    background: var(--ds-surface-low);
    color: var(--ds-text);
    font: var(--ds-font-label);
    cursor: pointer;
  }

  .ds-command__back[hidden] {
    display: none;
  }

  .ds-command__back > span {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .ds-command__search > .ds-kbd {
    flex: none;
  }

  /* The way out without an Escape key: on phones only. */
  .ds-command__close {
    display: none;
    flex: none;
    margin-inline-end: calc(-1 * var(--ds-space-2));
  }

  .ds-command__list {
    position: relative;
    flex: 1 1 auto;
    min-height: 0;
    margin: 0;
    padding: calc(var(--ds-space-2) + var(--ds-density, 0) * 2px);
    overflow-y: auto;
    overscroll-behavior: contain;
    scroll-padding-block: var(--ds-space-2);
    scrollbar-width: thin;
    scrollbar-color: var(--ds-line-2) transparent;
  }

  .ds-command__list[hidden] {
    display: none;
  }

  .ds-command__group + .ds-command__group,
  .ds-command__item + .ds-command__group {
    margin-top: var(--ds-space-2);
  }

  .ds-command__heading {
    padding: var(--ds-space-2) var(--ds-space-3) var(--ds-space-1);
    color: var(--ds-text-2);
    font: var(--ds-font-caption);
    cursor: default;
  }

  .ds-command__item {
    --_h: calc(var(--ds-command-item-height, 48px) + var(--ds-size-step, 0) * 8px + var(--ds-density, 0) * 4px);
    position: relative;
    display: flex;
    align-items: center;
    gap: var(--ds-space-3);
    min-height: max(var(--ds-target-min, 0px), var(--_h));
    padding: calc(var(--ds-space-2) + var(--ds-density, 0) * 2px) var(--ds-space-3);
    border-radius: calc(var(--ds-command-item-radius, var(--ds-radius-sm)) * var(--ds-shape, 1));
    color: var(--ds-text);
    cursor: pointer;
  }

  /* The state layer of the active option (keyboard and pointer share
     data-active, so there is no separate hover layer): in over
     --ds-dur-micro, gone at once. */
  .ds-command__item::before {
    content: '';
    position: absolute;
    inset: 0;
    border-radius: inherit;
    background: var(--ds-text);
    opacity: 0;
    pointer-events: none;
    transition: opacity var(--ds-dur-micro) var(--ds-ease-in-out);
  }

  .ds-command__item:not([data-active])::before {
    transition-duration: 0ms;
  }

  .ds-command__item[data-active]::before {
    opacity: var(--ds-state-hover);
  }

  .ds-command__item[aria-disabled="true"] {
    color: var(--ds-disabled-ink, var(--ds-text-2));
    cursor: default;
  }

  .ds-command__item[aria-disabled="true"]::before {
    opacity: 0;
  }

  .ds-command__icon,
  .ds-command__chevron {
    position: relative;
    flex: none;
    color: var(--ds-text-2);
  }

  .ds-command__content {
    position: relative;
    display: grid;
    flex: 1;
    gap: 2px;
    min-width: 0;
  }

  .ds-command__label {
    overflow: hidden;
    font: var(--ds-size-font, var(--ds-font-body));
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  /* The matched letters: the label's weight and the primary ink. */
  .ds-command__match {
    background: transparent;
    color: var(--ds-primary);
    font-weight: var(--ds-weight-label);
  }

  .ds-command__item[aria-disabled="true"] .ds-command__match {
    color: inherit;
  }

  .ds-command__description {
    overflow: hidden;
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .ds-command__shortcut {
    position: relative;
    display: inline-flex;
    flex: none;
    gap: var(--ds-space-1);
    color: var(--ds-text-2);
  }

  .ds-command__empty {
    margin: 0;
    padding: var(--ds-space-8) var(--ds-space-4);
    color: var(--ds-text-2);
    font: var(--ds-font-body);
    text-align: center;
  }

  .ds-command__empty[hidden] {
    display: none;
  }

  .ds-command__foot {
    display: flex;
    flex: none;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: var(--ds-space-2) var(--ds-space-4);
    padding: calc(var(--ds-space-2) + var(--ds-density, 0) * 2px) var(--ds-space-4);
    border-top: 1px solid var(--ds-line);
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
  }

  .ds-command__foot > span {
    display: inline-flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--ds-space-1) var(--ds-space-3);
  }

  .ds-command__status {
    display: inline-flex;
    align-items: center;
    gap: var(--ds-space-2);
    margin: 0;
    margin-inline-start: auto;
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
  }

  /* A status line of its own (no foot): only while it says something. */
  .ds-dialog__box > .ds-command__status:has(> span:empty):not(:has(.ds-spinner)) {
    display: none;
  }

  .ds-dialog__box > .ds-command__status {
    padding: var(--ds-space-2) var(--ds-space-4);
    border-top: 1px solid var(--ds-line);
  }

  /* Phones: the whole window from the top; the hints and the keys go (no keyboard to press them), the status stays. */
  @media (max-width: 600px) {
    .ds-command {
      padding: 0;
    }

    .ds-command .ds-dialog__box {
      width: 100%;
      height: 100%;
      max-height: none;
      border-radius: 0;
      padding-top: env(safe-area-inset-top);
      padding-bottom: env(safe-area-inset-bottom);
    }

    .ds-command__foot > span,
    .ds-command__search > .ds-kbd,
    .ds-command__shortcut {
      display: none;
    }

    .ds-command__close {
      display: inline-flex;
    }
  }

  @media (forced-colors: active) {
    .ds-command__item[data-active] {
      outline: 2px solid Highlight;
      outline-offset: -2px;
    }

    .ds-command__match {
      color: inherit;
      text-decoration: underline;
    }

    .ds-command__item[aria-disabled="true"] {
      color: GrayText;
    }

    .ds-command__search:has(> .ds-command__input:focus) {
      border-bottom-color: Highlight;
    }

    .ds-command__back {
      border: 1px solid ButtonText;
    }
  }
}

/* ── components/shortcuts/shortcuts.css ── */
/*
 * Shortcut sheet: every shortcut of the page in a dialog that "?" opens,
 * grouped by scope (when more than one has shortcuts) and by group, each
 * with its keys. The groups flow into columns as the box allows.
 *
 *   <dialog class="ds-dialog ds-dialog--lg ds-shortcuts" id="keys" data-ds-shortcuts aria-labelledby="keys-title">
 *     <div class="ds-dialog__backdrop" data-ds-close></div>
 *     <div class="ds-dialog__box">
 *       <div class="ds-dialog__head">
 *         <h2 class="ds-dialog__title" id="keys-title">Keyboard shortcuts</h2>
 *         <button class="ds-btn ds-btn--quiet ds-btn--icon" type="button" aria-label="Close" data-ds-close>(close)</button>
 *       </div>
 *       [<input class="ds-input ds-shortcuts__filter" type="search" aria-label="Find a shortcut" placeholder="Find a shortcut">]
 *       <div class="ds-dialog__body ds-shortcuts__list">  shortcuts.js renders:
 *         [<section class="ds-shortcuts__scope"><h3 class="ds-shortcuts__title">Board</h3>]   with several scopes
 *         <div class="ds-shortcuts__groups">
 *           <section class="ds-shortcuts__group"><h3 class="ds-shortcuts__heading">Editing</h3>
 *             <dl class="ds-shortcuts__items">
 *               <div class="ds-shortcuts__item [data-off]">
 *                 <dt class="ds-shortcuts__label">Save [<span class="ds-shortcuts__off">Not available here</span>]</dt>
 *                 <dd class="ds-shortcuts__keys"><span class="ds-shortcuts__combo" role="img" aria-label="Ctrl+S"><kbd class="ds-kbd">Ctrl</kbd><kbd class="ds-kbd">S</kbd></span>
 *                   [<span class="ds-shortcuts__or">or</span> ...]</dd>
 *         <p class="ds-shortcuts__empty">No keyboard shortcuts here.</p>   none, or none that match
 *
 * data-off: a shortcut that does nothing as the page stands (a disabled
 * control): the disabled ink and the words, never the colour alone.
 *
 * Options (docs/options.md), computed here:
 *   size      type only: the label takes --ds-size-font
 *   density   any container: a row's block padding 2px per step, the gap
 *             between groups 4px per step
 *   shape     the keys' radius (utilities.css)
 *   tone      none
 *
 * The groups are columns of at least --ds-shortcuts-column (240px), so a
 * phone shows one.
 *
 * Hooks: --ds-shortcuts-column (240px).
 *
 * Forced colours: the hairlines between rows are borders; a shortcut that
 * is off reads GrayText.
 *
 * Motion: the dialog's (DS.overlay).
 */

@layer ds.components.shortcuts {
  /* The title lines up with the list under it; the close button still
     reaches into the box's padding. */
  .ds-shortcuts .ds-dialog__head {
    margin-inline-start: 0;
  }

  .ds-shortcuts__filter {
    flex: none;
  }

  .ds-shortcuts__list {
    display: grid;
    align-content: start;
    gap: calc(var(--ds-space-6) + var(--ds-density, 0) * 4px);
  }

  .ds-shortcuts__scope {
    display: grid;
    gap: var(--ds-space-3);
  }

  .ds-shortcuts__scope + .ds-shortcuts__scope {
    padding-top: calc(var(--ds-space-6) + var(--ds-density, 0) * 4px);
    border-top: 1px solid var(--ds-line);
  }

  .ds-shortcuts__title {
    margin: 0;
    color: var(--ds-text);
    font: var(--ds-font-subtitle);
  }

  .ds-shortcuts__groups {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(min(var(--ds-shortcuts-column, 240px), 100%), 1fr));
    align-items: start;
    gap: calc(var(--ds-space-6) + var(--ds-density, 0) * 4px) var(--ds-space-6);
  }

  .ds-shortcuts__group {
    display: grid;
    gap: var(--ds-space-1);
    min-width: 0;
  }

  .ds-shortcuts__heading {
    margin: 0;
    color: var(--ds-text-2);
    font: var(--ds-font-caption);
  }

  .ds-shortcuts__items {
    display: grid;
    margin: 0;
  }

  /* The label takes what the keys leave and wraps, so the keys stay on its
     line, at the end, also with the note under a label that is off. */
  .ds-shortcuts__item {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: center;
    gap: var(--ds-space-1) var(--ds-space-3);
    padding-block: calc(var(--ds-space-2) + var(--ds-density, 0) * 2px);
    border-bottom: 1px solid var(--ds-line);
  }

  .ds-shortcuts__item:last-child {
    border-bottom: 0;
  }

  .ds-shortcuts__label {
    min-width: 0;
    margin: 0;
    color: var(--ds-text);
    font: var(--ds-size-font, var(--ds-font-body));
  }

  .ds-shortcuts__keys {
    display: inline-flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: flex-end;
    gap: var(--ds-space-1) var(--ds-space-2);
    margin: 0;
  }

  .ds-shortcuts__combo {
    display: inline-flex;
    gap: var(--ds-space-1);
  }

  .ds-shortcuts__or {
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
  }

  /* Off as the page stands: the disabled ink, and the words say it. */
  .ds-shortcuts__item[data-off] .ds-shortcuts__label,
  .ds-shortcuts__item[data-off] .ds-shortcuts__combo {
    color: var(--ds-disabled-ink, var(--ds-text-2));
  }

  /* Under the label: what the shortcut does, then that it does nothing now. */
  .ds-shortcuts__off {
    display: block;
    color: var(--ds-text-2);
    font: var(--ds-font-meta);
  }

  .ds-shortcuts__empty {
    margin: 0;
    padding: var(--ds-space-6) 0;
    color: var(--ds-text-2);
    font: var(--ds-font-body);
    text-align: center;
  }

  @media (forced-colors: active) {
    .ds-shortcuts__item[data-off] .ds-shortcuts__label,
    .ds-shortcuts__item[data-off] .ds-shortcuts__combo,
    .ds-shortcuts__item[data-off] .ds-kbd {
      color: GrayText;
    }
  }
}

/* ── components/banner/banner.css ── */
/*
 * Banner (3.0): the behaviour of the app's message strip, .ds-banner (the
 * App frame's, shell.css: the first child of .ds-panel, above the view):
 * several messages in priority order, each dismissible and remembered.
 *
 *   <div class="ds-banner" data-ds-banner [data-ds-banner-max="1"] [data-ds-banner-remember="local|session|off"]>
 *     <div class="ds-alert ds-tone-error" role="alert" data-ds-banner-id="outage-1104" [data-ds-banner-priority="90"]>
 *       (alertCircle 20)<span class="ds-alert__text">Sign-in is down. We are on it.</span>
 *       <button class="ds-btn ds-btn--quiet ds-btn--icon ds-sm ds-banner__dismiss" type="button" aria-label="Dismiss">(close 20)</button>   banner.js
 *     </div>
 *     <div class="ds-alert ds-tone-info" role="status" data-ds-banner-id="maintenance-1109" hidden> ... </div>   waiting
 *     <button class="ds-btn ds-btn--text ds-sm ds-banner__more" type="button" aria-expanded="false">Show 1 more</button>   banner.js
 *   </div>
 *
 * banner.js orders the alerts, hides the dismissed ones and those past the
 * maximum (hidden), adds the dismiss buttons and the more button.
 *
 * Messages under each other: only the first one shown keeps the panel's
 * top corners (shell.css); the next ones are square, a hairline apart. The
 * more button sits at the end of a row of its own under them, on the
 * panel's surface.
 *
 * Options (docs/options.md): those of the alert (size and density on its
 * padding, shape on the first message's corners, tone per message, the
 * icon and the word carry the status). The dismiss button is an icon button
 * at .ds-sm: it steps with size, never with density; .ds-touch makes it a
 * full target.
 *
 * Forced colours: the hairline between messages becomes CanvasText, as
 * every border.
 *
 * Motion: banner.js changes the messages inside DS.motion.flip() on the
 * panel, so the view glides; a message that appears fades in
 * (DS.motion.enter(alert, 'fade')). Nothing animates a height.
 */

@layer ds.components.banner {
  /* A waiting or dismissed message takes no room, also on a page without
     .ds-base (an alert is display: flex). */
  .ds-banner > [hidden] {
    display: none;
  }

  /* Under the first message shown: square corners, a hairline apart. */
  .ds-banner > .ds-alert:not(:nth-child(1 of .ds-alert:not([hidden]))) {
    border-top: 1px solid var(--ds-line);
    border-radius: 0;
  }

  /* The dismiss button closes the row, after any action. */
  .ds-banner__dismiss {
    order: 1;
  }

  .ds-banner > .ds-banner__more:not([hidden]) {
    display: flex;
    margin-block: var(--ds-space-1);
    margin-inline: auto var(--ds-space-2);
  }
}

/* ── components/notifications/notifications.css ── */
/*
 * Notification centre: a bell with the unread count that opens a side
 * sheet of notifications in groups, read and unread.
 *
 *   <span class="ds-notifications__bell">
 *     <button class="ds-btn ds-btn--quiet ds-btn--icon" type="button" data-ds-open="#inbox" aria-label="Notifications">(bell 20)</button>
 *     <span class="ds-badge ds-tone-error" aria-hidden="true">3</span>          notifications.js (DS.badge)
 *   </span>
 *   <dialog class="ds-sheet ds-notifications" id="inbox" data-ds-notifications aria-labelledby="inbox-title">
 *     ... .ds-sheet__head (title, subtitle "3 unread", settings link, close)
 *     <div class="ds-notifications__bar"> (unread-only switch) (Mark all as read) </div>
 *     <div class="ds-sheet__body ds-notifications__feed" tabindex="0">
 *       <section class="ds-notifications__group" aria-labelledby="h1">
 *         <h3 class="ds-notifications__heading" id="h1">Today</h3>
 *         <ul class="ds-notifications__list" role="list">
 *           <li class="ds-notifications__item" data-ds-key="n1" data-unread>
 *             <span class="ds-notifications__icon ds-tone-warning" aria-hidden="true">(wifiOff 20)</span>
 *             <div class="ds-notifications__content">
 *               <p class="ds-notifications__title" id="t1"><a class="ds-notifications__link" href="/devices/42">LAPTOP-0042 is offline</a></p>
 *               <p class="ds-notifications__text">Last seen in Building A.</p>
 *               <p class="ds-notifications__meta"><span class="ds-notifications__dot" aria-hidden="true"></span><span class="ds-sr">Unread, </span><time datetime="...">3 minutes ago</time></p>
 *               <div class="ds-notifications__actions"><button class="ds-btn ds-btn--text ds-sm" type="button">Open a ticket</button></div>
 *             </div>
 *             <button class="ds-btn ds-btn--quiet ds-btn--icon ds-sm ds-notifications__toggle" type="button" aria-label="Mark as read" aria-describedby="t1">(mailOpen 20)</button>
 *           </li>
 *       <div class="ds-empty ds-notifications__empty" hidden> ... </div>
 *
 * notifications.js renders the groups and rows from data (or reads the
 * rows of the markup), the badge, the subtitle and the empty state.
 *
 * Unread (data-unread on the row): a dot before the time, the title in the
 * label weight and the word "Unread" for screen readers: never colour
 * alone. The icon's tone is the class on the icon itself (an inherited
 * tone is ignored); its glyph carries the meaning.
 *
 * Options (docs/options.md), computed here:
 *   size      .ds-xs ... .ds-xl on the sheet or any ancestor: a row's
 *             padding 4px per step (8px of height), the icon disc 8px per
 *             step; type stays
 *   density   any container: a row's padding 2px per step, the bar's
 *             height 4px per step
 *   shape     the disc's radius (round at the default) times --ds-shape
 *   touch     reaches the buttons (the read button, the actions)
 *   tone      per notification, on its icon
 *
 * Hooks: --ds-notifications-icon-size (40px, the disc at md),
 * --ds-notifications-item-padding (12px, a row's block padding at md and
 * the comfortable density), --ds-notifications-dot-size (8px).
 *
 * Forced colours: the dot takes CanvasText (a background would vanish),
 * the disc keeps a CanvasText edge; links are LinkText by themselves.
 *
 * Motion: an arriving row fades in while the others glide
 * (DS.motion.flip()), only while the sheet is open; the dot comes in over
 * --ds-dur-fast and goes at once (--ds-dur-instant); the link's focus ring
 * snaps in on --ds-dur-fast. The sheet's own motion is DS.overlay's.
 */

@layer ds.components.notifications {
  /* The bell: the count on the icon button's corner, outside the button
     (a ripple host clips while a ripple is inside), so it never covers the
     glyph's centre and takes no press. */
  .ds-notifications__bell {
    position: relative;
    display: inline-flex;
    flex-shrink: 0;
  }

  .ds-notifications__bell > .ds-badge {
    position: absolute;
    inset-block-start: 0;
    inset-inline-end: 0;
    translate: 25% -25%;
    pointer-events: none;
  }

  /* The bar under the sheet's head: the unread-only switch and mark all
     read, at the sheet's side padding. */
  .ds-notifications__bar {
    display: flex;
    flex: none;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: var(--ds-space-2) var(--ds-space-4);
    min-height: calc(48px + var(--ds-density, 0) * 4px);
    padding: var(--ds-space-1) calc(var(--ds-sheet-padding, var(--ds-space-6)) + var(--ds-density, 0) * 2px);
    border-bottom: 1px solid var(--ds-line);
  }

  .ds-notifications__bar > .ds-btn:only-child {
    margin-inline-start: auto;
  }

  /* The feed starts a little under the bar: the first heading is no
     cramped line under the hairline. */
  .ds-notifications .ds-notifications__feed {
    padding-top: var(--ds-space-4);
  }

  .ds-notifications__group + .ds-notifications__group {
    margin-top: var(--ds-space-4);
  }

  .ds-notifications__heading {
    margin: 0 0 var(--ds-space-1);
    color: var(--ds-text-2);
    font: var(--ds-font-label);
  }

  .ds-notifications__list {
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .ds-notifications__item {
    --_pad: calc(var(--ds-notifications-item-padding, 12px) + var(--ds-size-step, 0) * 4px + var(--ds-density, 0) * 2px);
    --_disc: calc(var(--ds-notifications-icon-size, 40px) + var(--ds-size-step, 0) * 8px);
    display: grid;
    grid-template-columns: var(--_disc) minmax(0, 1fr) auto;
    align-items: start;
    gap: var(--ds-space-3);
    padding-block: var(--_pad);
  }

  .ds-notifications__item + .ds-notifications__item {
    border-top: 1px solid var(--ds-line);
  }

  .ds-notifications__icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: var(--_disc);
    height: var(--_disc);
    border-radius: min(calc(var(--_disc) / 2 * var(--ds-shape, 1)), calc(var(--_disc) / 2));
    background: var(--ds-surface-high);
    color: var(--ds-text-2);
  }

  /* A tone only from the class on the icon itself. */
  .ds-notifications__icon:is(.ds-tone-neutral, .ds-tone-primary, .ds-tone-info, .ds-tone-success, .ds-tone-warning, .ds-tone-error) {
    background: var(--ds-tone-container);
    color: var(--ds-on-tone-container);
  }

  .ds-notifications__content {
    display: grid;
    gap: var(--ds-space-1);
    min-width: 0;
  }

  .ds-notifications__content > * {
    margin: 0;
  }

  .ds-notifications__title {
    color: var(--ds-text);
    font: var(--ds-font-body);
    overflow-wrap: anywhere;
  }

  .ds-notifications__item[data-unread] .ds-notifications__title {
    font-weight: var(--ds-weight-label);
  }

  .ds-notifications__link {
    border-radius: calc(var(--ds-radius-xs) * var(--ds-shape, 1));
    color: inherit;
    text-decoration: none;
    outline-offset: calc(var(--ds-focus-offset) + var(--ds-focus-width));
    transition: outline-offset var(--ds-dur-fast) var(--ds-ease-out);
  }

  .ds-notifications__link:focus-visible {
    outline: var(--ds-focus-outline);
    outline-offset: var(--ds-focus-offset);
  }

  @media (hover: hover) {
    .ds-notifications__link:hover {
      text-decoration: underline;
      text-decoration-thickness: var(--ds-link-underline-thickness);
      text-underline-offset: var(--ds-link-underline-offset);
    }
  }

  .ds-notifications__text {
    color: var(--ds-text-2);
    font: var(--ds-font-body);
    overflow-wrap: anywhere;
  }

  .ds-notifications__meta {
    display: flex;
    align-items: center;
    gap: var(--ds-space-2);
    color: var(--ds-text-2);
    font: var(--ds-font-caption);
  }

  .ds-notifications__dot {
    flex: none;
    width: var(--ds-notifications-dot-size, 8px);
    height: var(--ds-notifications-dot-size, 8px);
    border-radius: 50%;
    background: var(--ds-primary);
    opacity: 0;
    transition: opacity var(--ds-dur-instant) var(--ds-ease-exit);
  }

  .ds-notifications__item[data-unread] .ds-notifications__dot {
    opacity: 1;
    transition-duration: var(--ds-dur-fast);
    transition-timing-function: var(--ds-ease-in-out);
  }

  /* Read: no dot and no room for one, so the time starts at the text. */
  .ds-notifications__item:not([data-unread]) .ds-notifications__dot {
    width: 0;
    margin-inline-end: calc(-1 * var(--ds-space-2));
  }

  /* The read button lines up with the title's first line. */
  .ds-notifications__toggle {
    align-self: start;
    margin-block-start: calc(var(--ds-space-1) * -1);
  }

  /* The text buttons' labels line up with the text above them. */
  .ds-notifications__actions {
    display: flex;
    flex-wrap: wrap;
    gap: var(--ds-space-1);
    margin-top: var(--ds-space-1);
    margin-inline-start: calc(-1 * var(--ds-space-3));
  }

  .ds-notifications__actions[hidden],
  .ds-notifications__content > [hidden] {
    display: none;
  }

  .ds-notifications__empty[hidden] {
    display: none;
  }

  @media (forced-colors: active) {
    .ds-notifications__dot {
      forced-color-adjust: none;
      background: CanvasText;
    }

    .ds-notifications__icon {
      border: 1px solid CanvasText;
    }
  }
}

/* ── components/ripple/ripple.css ── */
/*
 * Pointer ripple (js/ripple.js): a press grows a circle of the content
 * colour from the point that was pressed (Enter or Space: from the centre)
 * and fades it when the press ends. It is an effect, so it never
 * overshoots. Everything here applies only under .ds-ripples, which
 * DS.ripple.attach(root) or DS.init(root) puts on the root; pages that call
 * neither keep the flat state layer as their press feedback.
 *
 *   DS.ripple.attach(document);     <html class="... ds-ripples">
 *   <button class="ds-btn">         a host
 *     ... <span class="ds-press-ripple" aria-hidden="true" data-ds-keep
 *              style="--ds-ripple-x: 31px; --ds-ripple-y: 18px; --ds-ripple-r: 52px"></span>
 *   </button>
 *
 * Hosts: .ds-btn, .ds-chip (the ripple goes into .ds-chip__body),
 * .ds-segmented__option, .ds-drawer__item, .ds-drawer__toggle, .ds-tabs__tab,
 * :is(button, a).ds-tile, .ds-card--interactive, .ds-table__sort, the body rows of
 * .ds-table--interactive (a press on another link or control inside a
 * row or a <div> card is that control's own: no ripple, no .ds-pressed),
 * .ds-radio (radio cards), .ds-combo__toggle,
 * .ds-menu__item, .ds-errors summary, .ds-disclosure > summary,
 * .ds-list--interactive > .ds-list__item, :is(a, button).ds-kv-list__row,
 * .ds-dropzone, :is(button, a).ds-columns__col, .ds-pressable (a project element
 * with the system's state layer, utilities.css) and [data-ds-ripple] (any element,
 * made positioned here); inline links, the switch, checkbox and radio
 * inputs (their halo is the press), combobox options and native field
 * parts have none; data-ds-ripple="off" on a host or an ancestor opts out.
 * A host positions itself in its own stylesheet; while a ripple is inside
 * it also gets overflow: clip and isolation: isolate, with zero specificity:
 * a ripple never escapes its host, and a host at rest looks as without
 * .ds-ripples. A host that holds a corner badge (> .ds-badge--corner,
 * badge.css: an icon button with a count) is isolated but never clipped,
 * so the badge over its edge stays whole; its ripple clips itself, a box
 * over the host with the host's radius and the circle as its ::before.
 *
 * .ds-press-ripple--out   the release: the ripple fades, then the script removes it
 *
 * Runtime properties (set by the script on the ripple): --ds-ripple-x and
 * --ds-ripple-y (its centre, from the host's padding box), --ds-ripple-r
 * (the distance to the farthest corner).
 *
 * Hook: --ds-ripple-color (default currentColor, the content colour).
 *
 * Options (src/core/options.css): the ripple has none of its own and takes
 * every one from its host, which it fills and which clips it:
 *   size, density, touch  the script measures the host, so the circle reaches
 *                         the farthest corner of any box
 *   shape                 the clip is the host's radius: at shape 0 a square
 *                         host clips a square, and the press morph (each
 *                         host's own rule) never makes it rounder than at
 *                         rest. The tab's ripple box takes the inset and the
 *                         radius of the tab's layer (below)
 *   tone                  the default ink is the host's content colour, so a
 *                         filled error button ripples in its on-tone colour
 *
 * Cascade: this file's sublayer, ds.components.ripple, is the last one
 * (meta.json "order"; the build fails a host that comes later), so the
 * ripple's own box wins over any rule of a host that reaches its children,
 * and the press rules below over each host's own. They leave out what they
 * must not touch by selector instead of losing to the host by specificity,
 * so they hold in any later layer too (the spec plays the file once more in
 * ds.utilities). Hosts name .ds-pressed and .ds-ripples in their own rules
 * freely: they are this component's state classes (meta.json
 * "stateClasses"), written by js/ripple.js, and set no cascade order.
 *
 * The flat state layer and the ripple never stack: under .ds-ripples a
 * pressed host keeps its hover layer (devices that hover) or none (touch),
 * or its focus layer when a key pressed it, and the ripple adds the press
 * (--ds-state-pressed). A button's layer also keeps what its
 * --ds-btn-state-pressed-opacity hook asks for beyond the ripple (the
 * solid disc of .ds-btn--disc). Forced colours show no ripple.
 *
 * A table row cannot hold the ripple and does not clip: the ripple goes
 * into its first cell (a <td>, or a <th scope="row"> row header) as a box
 * over the whole row (against the positioned row; the script gives it the
 * row's height, which WebKit would take from the table) that clips the circle,
 * its ::before. The row is isolated while it ripples, so the ripple
 * paints over the row's colour and under the cells' content and layers.
 * A row of a pinned table (.ds-table--pin-first) ripples in two parts with
 * one centre: the box over the row goes into its second cell (the pinned
 * first cell paints over it), a second box into the pinned cell, which
 * places and clips it; the pinned cell lays the row's layer over its
 * opaque base, so it follows the same rule as the other cells.
 *
 * Progressive:
 * - overflow-clip-margin (a chip's ripple covers the chip's 1px border
 *   like its state layer does, and a selected interactive card keeps the
 *   outer pixel of its 2px ring while a ripple is inside): without it the
 *   ripple stops at the padding box and the card's ring thins to 1px for
 *   the press.
 */

@layer ds.components.ripple {
  /* An element of the page's that asks for a ripple. Every other host
     positions itself in its own stylesheet (the combobox toggle absolutely):
     this file must not decide that, whatever the cascade order. */
  :where(.ds-ripples [data-ds-ripple]:not([data-ds-ripple="off"])) {
    position: relative;
  }

  /* Clipped and isolated only while a ripple is inside: at rest nothing of
     the host changes (no clipped overflow, no other raster path). A table
     cell only holds its row's ripple box: the row isolates, the box clips,
     and the cell keeps its own overflow (a truncated first cell). */
  :where(.ds-ripples :not(tr > :is(td, th), :has(> .ds-badge--corner)):has(> .ds-press-ripple)) {
    overflow: clip;
    isolation: isolate;
  }

  /* A host with a badge on its corner (.ds-badge--corner, badge.css) must
     not clip: the badge hangs over its edge. Its ripple clips itself
     instead: a box over the host's padding box with the host's radius
     (inherited, so it follows the press morph), its ::before the circle,
     as a table row's or a tab's ripple. Isolated all the same, so the
     ripple paints over the host's fill and under its content. */
  :where(.ds-ripples :has(> .ds-badge--corner):has(> .ds-press-ripple)) {
    isolation: isolate;
  }

  .ds-ripples :has(> .ds-badge--corner) > .ds-press-ripple {
    inset: 0;
    width: auto;
    height: auto;
    overflow: clip;
    border-radius: inherit;
    background: none;
    animation: none;
  }

  .ds-ripples :has(> .ds-badge--corner) > .ds-press-ripple::before {
    content: '';
    position: absolute;
    top: calc(var(--ds-ripple-y) - var(--ds-ripple-r));
    left: calc(var(--ds-ripple-x) - var(--ds-ripple-r));
    width: calc(var(--ds-ripple-r) * 2);
    height: calc(var(--ds-ripple-r) * 2);
    border-radius: 50%;
    background: var(--ds-ripple-color, currentColor);
    animation: ds-press-ripple var(--ds-dur-medium) var(--ds-ease-out) backwards;
  }

  /* A selected interactive card draws its ring over its 1px border (its
     ::after at inset -1px): the clip keeps that pixel, so the ring does not
     thin while pressed (its border is transparent, so the ripple there is
     under the ring). */
  @supports (overflow-clip-margin: 1px) {
    :where(.ds-ripples .ds-chip__body:has(> .ds-press-ripple)),
    :where(.ds-ripples .ds-card--interactive:is([aria-pressed="true"], [aria-checked="true"], [aria-selected="true"], :has(.ds-card__action:is([aria-pressed="true"], [aria-checked="true"], [aria-selected="true"]))):has(> .ds-press-ripple)) {
      overflow-clip-margin: 1px;
    }
  }

  /* Above the host's fill, below its content (the host is isolated).
     Physical on purpose (D9): --ds-ripple-x and -y are pointer
     coordinates from the host's top left corner. */
  .ds-press-ripple {
    position: absolute;
    top: calc(var(--ds-ripple-y) - var(--ds-ripple-r));
    left: calc(var(--ds-ripple-x) - var(--ds-ripple-r));
    z-index: -1;
    width: calc(var(--ds-ripple-r) * 2);
    height: calc(var(--ds-ripple-r) * 2);
    border-radius: 50%;
    background: var(--ds-ripple-color, currentColor);
    opacity: var(--ds-state-pressed);
    pointer-events: none;
    animation: ds-press-ripple var(--ds-dur-medium) var(--ds-ease-out) backwards;
  }

  .ds-press-ripple--out {
    opacity: 0;
    transition: opacity var(--ds-dur-base) var(--ds-ease-in-out);
  }

  /* A row's ripple: a box over the row (its first cell, <td> or a <th>
     row header, is static, so the row places it: positioned, and in an
     interactive table transformed, which WebKit needs) that clips
     the circle. The row is isolated instead of the cell. */
  :where(.ds-ripples tr:has(> :is(td, th) > .ds-press-ripple)) {
    isolation: isolate;
  }

  .ds-ripples tr > :is(td, th) > .ds-press-ripple {
    inset: 0;
    width: auto;
    height: auto;
    overflow: clip;
    border-radius: 0;
    background: none;
    animation: none;
  }

  .ds-ripples tr > :is(td, th) > .ds-press-ripple::before {
    content: '';
    position: absolute;
    top: calc(var(--ds-ripple-y) - var(--ds-ripple-r));
    left: calc(var(--ds-ripple-x) - var(--ds-ripple-r));
    width: calc(var(--ds-ripple-r) * 2);
    height: calc(var(--ds-ripple-r) * 2);
    border-radius: 50%;
    background: var(--ds-ripple-color, currentColor);
    animation: ds-press-ripple var(--ds-dur-medium) var(--ds-ease-out) backwards;
  }

  /*
   * One press feedback, not two: the ripple brings --ds-state-pressed, so
   * the flat layer of a pressed host (:active, or .ds-pressed while
   * js/ripple.js holds the press) stays at its hover value (0 on touch,
   * which shows no hover). A button keeps its press hook: its layer shows
   * what --ds-btn-state-pressed-opacity asks for beyond the ripple's
   * --ds-state-pressed (so .ds-btn--disc keeps its disc on touch, too; a
   * negative difference computes to 0). A key press on a focused host keeps
   * its focus layer (--ds-state-focus) under the ripple.
   * :where() keeps the specificity of each component's own press rule. Each
   * rule also leaves out the host's blocked states by itself (the zero-weight
   * :not()), so the host's own rule for them applies in any cascade order,
   * with this file in its later sublayer. A host that adds a blocked
   * state adds it here too.
   */
  :where(.ds-ripples) .ds-btn:where(:not([data-ds-ripple="off"], [data-ds-ripple="off"] *, :disabled, [aria-disabled="true"], [aria-busy="true"], .ds-btn--done)):is(:active, .ds-pressed)::before {
    opacity: calc(var(--ds-btn-state-pressed-opacity, var(--ds-state-pressed)) - var(--ds-state-pressed));
  }

  :where(.ds-ripples) .ds-chip:where(:not([data-ds-ripple="off"], [data-ds-ripple="off"] *)):is(:active, .ds-pressed) .ds-chip__input:not(:disabled, [aria-disabled="true"]) + .ds-chip__body::before,
  :where(.ds-ripples) .ds-chip:where(:not([data-ds-ripple="off"], [data-ds-ripple="off"] *)):is(button, a):not(:disabled, [aria-disabled="true"]):is(:active, .ds-pressed) > .ds-chip__body::before,
  :where(.ds-ripples) .ds-segmented__option:where(:not([data-ds-ripple="off"], [data-ds-ripple="off"] *, :disabled, [aria-disabled="true"])):is(:active, .ds-pressed)::before,
  :where(.ds-ripples) .ds-drawer__item:where(:not([data-ds-ripple="off"], [data-ds-ripple="off"] *, [aria-disabled="true"])):is(:active, .ds-pressed)::before,
  :where(.ds-ripples) :is(button, a).ds-tile:where(:not([data-ds-ripple="off"], [data-ds-ripple="off"] *, :disabled, [aria-disabled="true"])):is(:active, .ds-pressed)::before,
  :where(.ds-ripples) .ds-card--interactive:where(:not([data-ds-ripple="off"], [data-ds-ripple="off"] *, :disabled, [aria-disabled="true"])):is(:active, .ds-pressed)::before,
  :where(.ds-ripples) .ds-table__sort:where(:not([data-ds-ripple="off"], [data-ds-ripple="off"] *)):is(:active, .ds-pressed)::before,
  :where(.ds-ripples) .ds-radio:where(:not([data-ds-ripple="off"], [data-ds-ripple="off"] *)):is(:active, .ds-pressed):not(.ds-radio--disabled, :has(input:is(:disabled, [aria-disabled="true"])))::before,
  :where(.ds-ripples) .ds-combo__toggle:where(:not([data-ds-ripple="off"], [data-ds-ripple="off"] *)):is(:active, .ds-pressed)::before,
  :where(.ds-ripples) .ds-menu__item:where(:not([data-ds-ripple="off"], [data-ds-ripple="off"] *, [aria-disabled="true"])):is(:active, .ds-pressed)::before,
  :where(.ds-ripples) .ds-errors summary:where(:not([data-ds-ripple="off"], [data-ds-ripple="off"] *)):is(:active, .ds-pressed)::before,
  :where(.ds-ripples) .ds-pressable:where(:not([data-ds-ripple="off"], [data-ds-ripple="off"] *, :disabled, [aria-disabled="true"], [aria-busy="true"])):is(:active, .ds-pressed)::before {
