    opacity: 0;
  }

  @media (hover: hover) {
    :where(.ds-ripples) .ds-disclosure > summary:where(:not([data-ds-ripple="off"], [data-ds-ripple="off"] *)):is(:active, .ds-pressed)::before,
    :where(.ds-ripples) :is(button, a).ds-columns__col:where(:not([data-ds-ripple="off"], [data-ds-ripple="off"] *)):is(:active, .ds-pressed)::before {
      opacity: var(--ds-state-hover);
    }

    :where(.ds-ripples) .ds-list--interactive > .ds-list__item:where(:not([data-ds-ripple="off"], [data-ds-ripple="off"] *, :has(.ds-list__action:is(:disabled, [aria-disabled="true"])))):is(:active, .ds-pressed)::before,
    :where(.ds-ripples) :is(a, button).ds-kv-list__row:where(:not([data-ds-ripple="off"], [data-ds-ripple="off"] *, :disabled, [aria-disabled="true"])):is(:active, .ds-pressed)::before,
    :where(.ds-ripples) .ds-disclosure--row > summary:where(:not([data-ds-ripple="off"], [data-ds-ripple="off"] *)):is(:active, .ds-pressed)::before {
      opacity: var(--ds-state-hover-lg);
    }
  }

  :where(.ds-ripples) .ds-list--interactive > .ds-list__item:where(:not([data-ds-ripple="off"], [data-ds-ripple="off"] *, :has(.ds-list__action:is(:disabled, [aria-disabled="true"])))):has(.ds-list__action:focus-visible):is(:active, .ds-pressed)::before,
  :where(.ds-ripples) :is(a, button).ds-kv-list__row:where(:not([data-ds-ripple="off"], [data-ds-ripple="off"] *, :disabled, [aria-disabled="true"])):focus-visible:is(:active, .ds-pressed)::before,
  :where(.ds-ripples) .ds-disclosure > summary:where(:not([data-ds-ripple="off"], [data-ds-ripple="off"] *)):focus-visible:is(:active, .ds-pressed)::before,
  :where(.ds-ripples) :is(button, a).ds-columns__col:where(:not([data-ds-ripple="off"], [data-ds-ripple="off"] *)):focus-visible:is(:active, .ds-pressed)::before {
    opacity: var(--ds-state-focus);
  }

  /*
   * The drawer's group toggles (a large row, like its items) and the tabs
   * (2.0): the same one-feedback rule. A tab's layer is a pill inside the
   * tab (tabs.css), so its ripple is a box over that pill that clips the
   * circle, its ::before (like a table row's). It reads the tab's private
   * --_inset and --_layer, inherited from the tab: a deliberate exception to
   * "private to its rule" (the box is the tab's own layer again, and a public
   * name would invite setting it), so size, density, shape and the contained
   * look reach the press as they reach the layer. tabs.css names this reader.
   * Here and not in tabs.css: a rule there would lose to .ds-press-ripple
   * above, in this later sublayer.
   */
  .ds-ripples .ds-tabs__tab > .ds-press-ripple {
    top: var(--_inset);
    inset-inline: 0;
    bottom: var(--_inset);
    width: auto;
    height: auto;
    overflow: clip;
    border-radius: var(--_layer);
    background: none;
    animation: none;
  }

  .ds-ripples .ds-tabs__tab > .ds-press-ripple::before {
    content: '';
    position: absolute;
    top: calc(var(--ds-ripple-y) - var(--ds-ripple-r) - var(--_inset));
    left: calc(var(--ds-ripple-x) - var(--ds-ripple-r));
    width: calc(var(--ds-ripple-r) * 2);
    height: calc(var(--ds-ripple-r) * 2);
    border-radius: 50%;
    background: var(--ds-ripple-color, currentColor);
    animation: ds-press-ripple var(--ds-dur-medium) var(--ds-ease-out) backwards;
  }

  :where(.ds-ripples) .ds-drawer__toggle:where(:not([data-ds-ripple="off"], [data-ds-ripple="off"] *)):is(:active, .ds-pressed)::before,
  :where(.ds-ripples) .ds-tabs__tab:where(:not([data-ds-ripple="off"], [data-ds-ripple="off"] *, :disabled, [aria-disabled="true"])):is(:active, .ds-pressed)::before {
    opacity: 0;
  }

  @media (hover: hover) {
    :where(.ds-ripples) .ds-drawer__toggle:where(:not([data-ds-ripple="off"], [data-ds-ripple="off"] *)):is(:active, .ds-pressed)::before {
      opacity: var(--ds-state-hover-lg);
    }

    :where(.ds-ripples) .ds-tabs__tab:where(:not([data-ds-ripple="off"], [data-ds-ripple="off"] *, :disabled, [aria-disabled="true"])):is(:active, .ds-pressed)::before {
      opacity: var(--ds-state-hover);
    }
  }

  :where(.ds-ripples) .ds-drawer__toggle:where(:not([data-ds-ripple="off"], [data-ds-ripple="off"] *)):focus-visible:is(:active, .ds-pressed)::before,
  :where(.ds-ripples) .ds-tabs__tab:where(:not([data-ds-ripple="off"], [data-ds-ripple="off"] *, :disabled, [aria-disabled="true"])):focus-visible:is(:active, .ds-pressed)::before {
    opacity: var(--ds-state-focus);
  }

  @media (forced-colors: active) {
    .ds-press-ripple {
      display: none;
    }
  }
}
